class ChaoxingAPIError(RuntimeError):
    pass


def aes_encrypt_base64(value: str, key: str = TRANSFER_KEY) -> str:
    """Match the AES-CBC transfer encoding used by Chaoxing's password login form."""
    key_bytes = key.encode("utf-8")
    if len(key_bytes) not in {16, 24, 32}:
        raise ChaoxingAPIError("Chaoxing login transfer key has an invalid AES length")
    padder = padding.PKCS7(algorithms.AES.block_size).padder()
    padded = padder.update(value.encode("utf-8")) + padder.finalize()
    encryptor = Cipher(algorithms.AES(key_bytes), modes.CBC(key_bytes[:16])).encryptor()
    encrypted = encryptor.update(padded) + encryptor.finalize()
    return base64.b64encode(encrypted).decode("ascii")


def html_attrs(tag: str) -> dict[str, str]:
    return {
        name.lower(): unescape(value)
        for name, _quote, value in re.findall(
            r"([a-zA-Z_:][\w:.-]*)\s*=\s*(['\"])(.*?)\2",
            tag,
            flags=re.DOTALL,
        )
    }


def parse_hidden_inputs(html: str) -> dict[str, str]:
    hidden: dict[str, str] = {}
    for match in re.finditer(r"<input\b[^>]*>", html, flags=re.IGNORECASE | re.DOTALL):
        attrs = html_attrs(match.group(0))
        if attrs.get("type", "").lower() != "hidden":
            continue
        key = attrs.get("name") or attrs.get("id")
        if key:
            hidden[key] = attrs.get("value", "")
    return hidden


def html_text(fragment: str, limit: int | None = None) -> str:
    without_blocks = re.sub(
        r"<(script|style)\b[^>]*>.*?</\1>",
        " ",
        fragment,
        flags=re.IGNORECASE | re.DOTALL,
    )
    text = re.sub(r"<[^>]+>", " ", without_blocks)
    text = re.sub(r"\s+", " ", unescape(text)).strip()
    return text[:limit] if limit is not None else text


def parse_knowledge_graph_relation_html(html: str) -> dict[str, list[dict[str, str]]]:
    """Parse the legacy outline editor's per-node relation picker.

    Chaoxing renders one ``ul`` for each relation definition.  The three
    built-ins use IDs 0 (association), 1 (predecessor), and 2 (successor);
    custom relation-definition IDs are emitted in the same attribute.  Some
    deployed pages leave the ``li[data]`` value unquoted, so the parser keeps a
    narrow fallback for that observed form.
    """

    groups: dict[str, list[dict[str, str]]] = {}
    for ul_match in re.finditer(
        r"<ul\b(?P<attrs>[^>]*)>(?P<body>.*?)</ul>",
        str(html or ""),
        flags=re.IGNORECASE | re.DOTALL,
    ):
        attrs_text = ul_match.group("attrs")
        attrs = html_attrs(attrs_text)
        relation_id = str(attrs.get("data-relationid") or "").strip()
        if not relation_id:
            class_match = re.search(
                r"(?:^|\s)relationType_(-?\d+)(?:\s|$)",
                attrs.get("class", ""),
                flags=re.IGNORECASE,
            )
            if class_match:
                relation_id = class_match.group(1)
        if not relation_id:
            continue

        items = groups.setdefault(relation_id, [])
        for li_match in re.finditer(
            r"<li\b(?P<attrs>[^>]*)>(?P<body>.*?)</li>",
            ul_match.group("body"),
            flags=re.IGNORECASE | re.DOTALL,
        ):
            li_attrs_text = li_match.group("attrs")
            li_attrs = html_attrs(li_attrs_text)
            topic_id = str(li_attrs.get("data") or "").strip()
            if not topic_id:
                unquoted = re.search(
                    r"(?:^|\s)data\s*=\s*([^\s>]+)",
                    li_attrs_text,
                    flags=re.IGNORECASE,
                )
                if unquoted:
                    topic_id = unescape(unquoted.group(1).strip().strip("'\""))
            if not topic_id:
                continue

            name_match = re.search(
                r"<span\b(?P<attrs>[^>]*)>(?P<body>.*?)</span>",
                li_match.group("body"),
                flags=re.IGNORECASE | re.DOTALL,
            )
            name = ""
            if name_match:
                span_attrs = html_attrs(name_match.group("attrs"))
                if "zpspan" in span_attrs.get("class", "").lower().split():
                    name = html_text(name_match.group("body"))
            if not name:
                for span_match in re.finditer(
                    r"<span\b(?P<attrs>[^>]*)>(?P<body>.*?)</span>",
                    li_match.group("body"),
                    flags=re.IGNORECASE | re.DOTALL,
                ):
                    span_attrs = html_attrs(span_match.group("attrs"))
                    if "zpspan" in span_attrs.get("class", "").lower().split():
                        name = html_text(span_match.group("body"))
                        break
            if not name:
                name = html_text(li_match.group("body"))
            description = str(li_attrs.get("relationdesc") or li_attrs.get("olddesc") or "").strip()
            items.append(
                {
                    "topic_id": topic_id,
                    "name": name,
                    "description": description,
                }
            )

    for relation_id in ("0", "1", "2"):
        groups.setdefault(relation_id, [])
    return groups


def append_query_params(url: str, params: dict[str, Any]) -> str:
    parsed = urlparse(url)
    encoded = urlencode(params)
    query = parsed.query + ("&" if parsed.query and encoded else "") + encoded
    return parsed._replace(query=query).geturl()


def append_missing_query_params(url: str, params: dict[str, Any]) -> str:
    """Append only absent query keys, matching the course-page JavaScript."""

    parsed = urlparse(url)
    existing = parse_qs(parsed.query, keep_blank_values=True)
    additions = {
        key: value
        for key, value in params.items()
        if key not in existing and value is not None and str(value) != ""
    }
    if not additions:
        return url
    encoded = urlencode(additions)
    query = parsed.query + ("&" if parsed.query else "") + encoded
    return parsed._replace(query=query).geturl()


def replace_query_params(url: str, params: dict[str, Any]) -> str:
    """Replace named query values while preserving every unrelated parameter."""

    parsed = urlparse(url)
    replacements = {str(key).casefold(): value for key, value in params.items()}
    pairs = [
        (key, value)
        for key, value in parse_qsl(parsed.query, keep_blank_values=True)
        if key.casefold() not in replacements
    ]
    pairs.extend(
        (str(key), str(value))
        for key, value in params.items()
        if value is not None and str(value) != ""
    )
    return parsed._replace(query=urlencode(pairs)).geturl()


def query_value(url: str, name: str) -> str:
    values = parse_qs(urlparse(url).query).get(name, [])
    return values[0] if values else ""


def redact_url_query_values(url: str, names: set[str]) -> str:
    parsed = urlparse(url)
    sensitive = {name.casefold() for name in names}
    pairs = [
        (key, "[redacted]" if key.casefold() in sensitive and value else value)
        for key, value in parse_qsl(parsed.query, keep_blank_values=True)
    ]
    return parsed._replace(query=urlencode(pairs)).geturl()


def parse_page_values(html: str, names: tuple[str, ...]) -> dict[str, str]:
    """Read selected bootstrap values from hidden inputs or simple JS assignments."""

    hidden = parse_hidden_inputs(html)
    hidden_casefolded = {key.casefold(): value for key, value in hidden.items()}
    values: dict[str, str] = {}
    for name in names:
        raw = hidden.get(name)
        if raw is None:
            raw = hidden_casefolded.get(name.casefold())
        if raw is None:
            match = re.search(
                rf"(?:\b(?:var|let|const)\s+|\bwindow\.){re.escape(name)}\s*=\s*"
                r"(?P<value>[^;\r\n]+)",
                html,
                flags=re.IGNORECASE,
            )
            raw = match.group("value").strip() if match else ""
        normalized = str(raw or "").strip()
        if len(normalized) >= 2 and normalized[0] in {"'", '"'}:
            if normalized[-1] == normalized[0]:
                normalized = normalized[1:-1]
        if normalized.lower() in {"null", "undefined"}:
            normalized = ""
        values[name] = unescape(normalized)
    return values


def parse_teacher_nav_items(html: str) -> list[dict[str, str]]:
    items: list[dict[str, str]] = []
    for match in re.finditer(r"<li\b([^>]*)>(.*?)</li>", html, flags=re.I | re.S):
        li_attrs = html_attrs(match.group(1))
        module = li_attrs.get("dataname", "")
        if not module:
            continue
        anchor = re.search(r"<a\b([^>]*)>(.*?)</a>", match.group(2), flags=re.I | re.S)
        if not anchor:
            continue
        anchor_attrs = html_attrs(anchor.group(1))
        data_url = anchor_attrs.get("data-url", "")
        if not data_url:
            continue
        visible_text = html_text(anchor.group(2))
        title = anchor_attrs.get("title", "")
        items.append(
            {
                "module": module,
                "label": visible_text or title or module,
                "title": title,
                "data_url": data_url,
                "page_header": li_attrs.get("pageheader", ""),
                "course_nav_id": li_attrs.get("data", ""),
                "open_type": li_attrs.get("opentype", ""),
            }
        )
    return items


def parse_learning_nav_items(html: str) -> list[dict[str, str]]:
    items = parse_teacher_nav_items(html)
    for item in items:
        item["label"] = re.sub(r"(?:\s|\u200b)*NEW\s*$", "", item["label"]).strip()
    return items


def parse_personal_space_modules(html: str) -> list[dict[str, Any]]:
    modules: list[dict[str, Any]] = []
    for match in re.finditer(r"<div\b([^>]*)>", html, flags=re.I | re.S):
        attrs = html_attrs(match.group(1))
        if attrs.get("role", "").lower() != "menuitem" or attrs.get("level") != "1":
            continue
        label = str(attrs.get("name") or "").strip()
        if not label:
            label = str(attrs.get("aria-label") or "").split("菜单", 1)[0].strip()
        if not label:
            continue
        element_id = str(attrs.get("id") or "").strip()
        app_id = element_id[5:] if element_id.lower().startswith("first") else element_id
        data_url = str(attrs.get("dataurl") or attrs.get("data-url") or "").strip()
        modules.append(
            {
                "index": len(modules) + 1,
                "app_id": app_id,
                "label": label,
                "data_url": data_url,
                "available": bool(data_url),
                "element_id": element_id,
            }
        )
    return modules


def resolve_personal_space_module(modules: list[dict[str, Any]], query: str) -> dict[str, Any]:
    normalized = str(query or "").replace("\u200b", "").strip().lower()
    if not normalized:
        raise ChaoxingAPIError("personal-space module name, ID, or index is required")
    exact = [
        item
        for item in modules
        if normalized
        in {
            str(item.get("app_id") or "").lower(),
            str(item.get("label") or "").replace("\u200b", "").strip().lower(),
            str(item.get("index") or ""),
        }
    ]
    if len(exact) == 1:
        return exact[0]
    partial = [
        item
        for item in modules
        if normalized in str(item.get("label") or "").replace("\u200b", "").strip().lower()
    ]
    if len(partial) == 1:
        return partial[0]
    if not partial:
        raise ChaoxingAPIError(f"personal-space module not found: {query}")
    options = ", ".join(
        f"{item['index']}. {item['label']} ({item['app_id']})" for item in partial[:20]
    )
    raise ChaoxingAPIError(f"multiple personal-space modules match: {options}")


def parse_note_detail_html(html: str) -> dict[str, Any]:
    decoder = json.JSONDecoder()
    for match in re.finditer(r"\bnote\s*:\s*", html):
        try:
            note, _end = decoder.raw_decode(html[match.end() :])
        except json.JSONDecodeError:
            continue
        if isinstance(note, dict) and str(note.get("cid") or "").strip():
            return note
    raise ChaoxingAPIError("note detail page exposed no note object")


def parse_note_detail_user(html: str) -> dict[str, Any]:
    decoder = json.JSONDecoder()
    for match in re.finditer(r"\buser\s*:\s*", html):
        try:
            user, _end = decoder.raw_decode(html[match.end() :])
        except json.JSONDecodeError:
            continue
        if isinstance(user, dict) and str(user.get("puid") or "").strip():
            return user
    return {}


def parse_personal_notice_compose_context(html: str) -> dict[str, Any]:
    """Parse the authenticated personal-notice editor bootstrap state."""

    decoder = json.JSONDecoder()

    def json_after(pattern: str, label: str) -> Any:
        marker = re.search(pattern, html, flags=re.I | re.S)
        if not marker:
            raise ChaoxingAPIError(f"personal notice editor exposed no {label}")
        try:
            value, _end = decoder.raw_decode(html[marker.end() :].lstrip())
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError(f"personal notice editor exposed invalid {label}") from exc
        return value

    user = json_after(r"window\.authUser\s*=\s*\{\s*info\s*:\s*", "account data")
    departments = json_after(r"window\.myFunDepts\s*=\s*", "sender identities")
    if not isinstance(user, dict):
        raise ChaoxingAPIError("personal notice editor exposed invalid account data")
    if not isinstance(departments, list):
        departments = []

    def assigned_string(name: str, default: str = "") -> str:
        marker = re.search(
            rf"window\.{re.escape(name)}\s*=\s*(['\"])(.*?)\1",
            html,
            flags=re.I | re.S,
        )
        if not marker:
            return default
        value = marker.group(2)
        return value.replace(r"\'", "'").replace(r"\"", '"').replace(r"\\", "\\")

    sender = next(
        (
            item
            for item in departments
            if isinstance(item, dict) and str(item.get("checked") or "0") == "1"
        ),
        {},
    )
    return {
        "user": user,
        "sender_identities": [item for item in departments if isinstance(item, dict)],
        "issuing_puid": str(sender.get("creatorId") or user.get("puid") or ""),
        "uuid": assigned_string("uuidTemp") or f"$CACG${uuid4()}",
        "uuid_enc": assigned_string("uuidEncTemp"),
        "source_type": assigned_string("sourceType", "0"),
        "is_rich_text": assigned_string("isRtf", "1") == "1",
        "operation": assigned_string("operationType", "add"),
        "original_type": assigned_string("oType"),
        "original_id": assigned_string("oId"),
        "original_encoding": assigned_string("oEnc"),
        "original_custom_parameters": assigned_string("oCustomParams"),
        "folder_id": assigned_string("foldCode"),
        "tag": assigned_string("tag"),
        "tag_encoding": assigned_string("tagEnc"),
        "fid_codes": assigned_string("fidsCode"),
    }


def parse_personal_group_manage_context(html: str) -> dict[str, Any]:
    """Parse account and group state embedded in the personal-group management page."""

    decoder = json.JSONDecoder()

    def first_object(pattern: str, required_key: str) -> dict[str, Any]:
        for marker in re.finditer(pattern, html, flags=re.I | re.S):
            try:
                value, _end = decoder.raw_decode(html[marker.end() :].lstrip())
            except json.JSONDecodeError:
                continue
            if isinstance(value, dict) and str(value.get(required_key) or "").strip():
                return value
        return {}

    account = first_object(r"\bauthUser\s*:\s*", "puid")
    circle = first_object(r"\bcircle\s*:\s*", "bbsid")
    if not circle:
        raise ChaoxingAPIError("personal group management page exposed no group state")
    return {"account": account, "group": circle}


def build_teacher_entry_url(
    course: dict[str, Any], clazz: dict[str, Any], page_header: int = -1
) -> str:
    required = {
        "courseId": str(course.get("course_id") or "").strip(),
        "clazzId": str(clazz.get("clazz_id") or "").strip(),
        "cpi": str(course.get("cpi") or "").strip(),
    }
    if not all(required.values()):
        raise ChaoxingAPIError("course_id, clazz_id, and cpi are required")
    return (
        COURSE_ENTRY_URL
        + "?"
        + urlencode(
            {
                **required,
                "edit": "true",
                "v": "2",
                "pageHeader": str(page_header),
                "single": "0",
            }
        )
    )


def resolve_module(items: list[dict[str, str]], query: str) -> dict[str, str]:
    normalized = query.replace("\u200b", "").strip().lower()
    exact = [
        item
        for item in items
        if normalized
        in {
            item.get("module", "").lower(),
            item.get("label", "").replace("\u200b", "").strip().lower(),
            item.get("title", "").replace("\u200b", "").strip().lower(),
        }
    ]
    if len(exact) == 1:
        return exact[0]
    partial = [
        item
        for item in items
        if normalized in item.get("label", "").replace("\u200b", "").strip().lower()
        or normalized in item.get("title", "").replace("\u200b", "").strip().lower()
    ]
    if len(partial) == 1:
        return partial[0]
    if not partial:
        labels = ", ".join(item.get("label") or item.get("module", "") for item in items)
        raise ChaoxingAPIError(f"course module not found: {query}; available: {labels}")
    labels = ", ".join(item.get("label") or item.get("module", "") for item in partial)
    raise ChaoxingAPIError(f"multiple module matches: {labels}")


def parse_homework_items(html: str, page_url: str, clazz: dict[str, Any]) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    class_name = str(clazz.get("clazz_name") or "")
    blocks = re.finditer(
        r"<li\b[^>]*id=['\"]work\d+['\"][\s\S]*?</li>",
        html,
        flags=re.IGNORECASE,
    )
    for match in blocks:
        block = match.group(0)
        open_tag = re.search(r"<li\b[^>]*>", block, flags=re.IGNORECASE)
        attrs = html_attrs(open_tag.group(0)) if open_tag else {}
        plain = html_text(block)

        mark_match = re.search(
            r"href=['\"]([^'\"]*?/mooc2-ans/work/mark\?[^'\"]+)['\"]",
            block,
            flags=re.IGNORECASE,
        )
        mark_url = urljoin(page_url, unescape(mark_match.group(1))) if mark_match else ""
        work_id = query_value(mark_url, "id") or str(attrs.get("id", "")).removeprefix("work")
        if not work_id:
            continue

        counts = re.search(r"(\d+)\s*待批\s*(\d+)\s*已交\s*(\d+)\s*未交", plain)
        pending = int(counts.group(1)) if counts else 0
        submitted = int(counts.group(2)) if counts else None
        unsubmitted = int(counts.group(3)) if counts else None

        if class_name and class_name in plain:
            title = plain.split(class_name, 1)[0].strip()
        elif "作答时间" in plain:
            title = plain.split("作答时间", 1)[0].strip()
        else:
            title = re.sub(r"\d+\s*待批.*$", "", plain).strip()
        title = re.sub(r"^(?:(?:批阅|修改设置|移动到|删除)\s+)+", "", title)
        time_match = re.search(
            r"作答时间[:：]\s*(.*?)(?=\s*(?:\d+\s*待批|修改设置|移动到|删除|批阅|$))",
            plain,
        )

        items.append(
            {
                "work_id": work_id,
                "title": title,
                "pending_count": pending,
                "submitted_count": submitted,
                "unsubmitted_count": unsubmitted,
                "answer_time": time_match.group(1).strip() if time_match else "",
                "mark_url": mark_url,
            }
        )
    return items


def _data_body_blocks(html: str) -> list[str]:
    starts = list(
        re.finditer(
            r"<ul\b[^>]*class=['\"][^'\"]*\bdataBody_td\b[^'\"]*['\"][^>]*>",
            html,
            flags=re.IGNORECASE,
        )
    )
    return [
        html[match.start() : starts[index + 1].start() if index + 1 < len(starts) else len(html)]
        for index, match in enumerate(starts)
    ]


def parse_homework_library_items(html: str) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    for block in _data_body_blocks(html):
        open_tag = re.search(r"<ul\b[^>]*>", block, flags=re.IGNORECASE)
        attrs = html_attrs(open_tag.group(0)) if open_tag else {}
        item_id = str(attrs.get("data") or "").strip()
        item_type = str(attrs.get("type") or "").strip()
        if not item_id or item_type not in {"0", "1"}:
            continue
        title_match = re.search(
            r"<a\b[^>]*\btitle=['\"]([^'\"]*)['\"][^>]*>",
            block,
            flags=re.IGNORECASE,
        )
        if not title_match:
            continue
        title = html_text(unescape(title_match.group(1)))
        creator_match = re.search(
            r"<li\b[^>]*class=['\"][^'\"]*\bdataBody_read\b[^'\"]*['\"][^>]*>"
            r"([\s\S]*?)</li>",
            block,
            flags=re.IGNORECASE,
        )
        question_match = re.search(
            r"<li\b[^>]*class=['\"][^'\"]*\bdataHead_questionNum\b[^'\"]*['\"][^>]*>"
            r"([\s\S]*?)</li>",
            block,
            flags=re.IGNORECASE,
        )
        score_match = re.search(
            r"<li\b[^>]*class=['\"][^'\"]*\bdataHead_score\b[^'\"]*['\"][^>]*>"
            r"([\s\S]*?)</li>",
            block,
            flags=re.IGNORECASE,
        )
        count_match = re.search(r"共\s*(\d+)\s*份", html_text(block))
        view_match = re.search(
            r"viewWork\(['\"]?([^,'\"]+)['\"]?\s*,\s*['\"]?(\d+)['\"]?\)",
            block,
            flags=re.IGNORECASE,
        )
        edit_match = re.search(
            r"href=['\"]([^'\"]*?/mooc2-ans/work/goToWorkEditor\?[^'\"]+)['\"]",
            block,
            flags=re.IGNORECASE,
        )

        question_text = html_text(question_match.group(1)) if question_match else ""
        score_text = html_text(score_match.group(1)) if score_match else ""
        try:
            question_count: int | None = int(question_text)
        except ValueError:
            question_count = None
        try:
            score: int | float | None = float(score_text)
            if score.is_integer():
                score = int(score)
        except ValueError:
            score = None

        items.append(
            {
                "item_id": item_id,
                "title": title,
                "is_folder": item_type == "0",
                "item_type": "folder" if item_type == "0" else "homework",
                "work_type": int(view_match.group(2)) if view_match else 0,
                "child_count": int(count_match.group(1)) if count_match else None,
                "question_count": question_count,
                "score": score,
                "creator": html_text(creator_match.group(1)) if creator_match else "",
                "edit_url": (
                    urljoin(MOOC2_BASE_URL, unescape(edit_match.group(1))) if edit_match else ""
                ),
            }
        )
    return items


def parse_homework_drafts(html: str) -> list[dict[str, Any]]:
    drafts: list[dict[str, Any]] = []
    for block in _data_body_blocks(html):
        title_match = re.search(
            r"<div\b[^>]*class=['\"][^'\"]*\bdraftsWork\b[^'\"]*['\"][^>]*"
            r"\btitle=['\"]([^'\"]*)['\"][^>]*>",
            block,
            flags=re.IGNORECASE,
        )
        edit_match = re.search(
            r"href=['\"]([^'\"]*?/mooc2-ans/work/goToWorkEditor\?[^'\"]+)['\"]",
            block,
            flags=re.IGNORECASE,
        )
        if not title_match or not edit_match:
            continue
        edit_url = urljoin(MOOC2_BASE_URL, unescape(edit_match.group(1)))
        work_id = query_value(edit_url, "workid")
        if not work_id:
            continue
        creator_match = re.search(
            r"<li\b[^>]*class=['\"][^'\"]*\bdataBody_read\b[^'\"]*['\"][^>]*>"
            r"([\s\S]*?)</li>",
            block,
            flags=re.IGNORECASE,
        )
        time_matches = re.findall(
            r"<li\b[^>]*class=['\"][^'\"]*\bdataBody_time\b[^'\"]*['\"][^>]*>"
            r"([\s\S]*?)</li>",
            block,
            flags=re.IGNORECASE,
        )
        drafts.append(
            {
                "work_id": work_id,
                "title": html_text(unescape(title_match.group(1))),
                "creator": html_text(creator_match.group(1)) if creator_match else "",
                "created_at": html_text(time_matches[0]) if time_matches else "",
                "edit_url": edit_url,
            }
        )
    return drafts


def _tag_has_boolean_attribute(tag: str, attribute: str) -> bool:
    return bool(
        re.search(
            rf"\b{re.escape(attribute)}(?:\s*=\s*(?:['\"][^'\"]*['\"]|[^\s>]+))?"
            r"(?=\s|/?>)",
            tag,
            flags=re.IGNORECASE,
        )
    )


def _html_form_controls(html: str) -> list[tuple[str, str]]:
    """Approximate jQuery ``serialize`` for server-rendered form fragments."""
    html = re.sub(
        r"<(script|style)\b[^>]*>[\s\S]*?</\1>",
        "",
        html,
        flags=re.IGNORECASE,
    )
    controls: list[tuple[str, str]] = []
    for match in re.finditer(r"<input\b[^>]*>", html, flags=re.IGNORECASE | re.DOTALL):
        tag = match.group(0)
        attrs = html_attrs(tag)
        name = attrs.get("name", "")
        input_type = attrs.get("type", "text").lower()
        if (
            not name
            or _tag_has_boolean_attribute(tag, "disabled")
            or input_type in {"button", "file", "image", "reset", "submit"}
            or (
                input_type in {"checkbox", "radio"}
                and not _tag_has_boolean_attribute(tag, "checked")
            )
        ):
            continue
        controls.append(
            (
                name,
                attrs.get("value", "on" if input_type in {"checkbox", "radio"} else ""),
            )
        )
    for match in re.finditer(
        r"<textarea\b([^>]*)>([\s\S]*?)</textarea>",
        html,
        flags=re.IGNORECASE,
    ):
        tag = "<textarea" + match.group(1) + ">"
        attrs = html_attrs(tag)
        name = attrs.get("name", "")
        if name and not _tag_has_boolean_attribute(tag, "disabled"):
            controls.append((name, unescape(match.group(2))))
    for match in re.finditer(
        r"<select\b([^>]*)>([\s\S]*?)</select>",
        html,
        flags=re.IGNORECASE,
    ):
        tag = "<select" + match.group(1) + ">"
        attrs = html_attrs(tag)
        name = attrs.get("name", "")
        if not name or _tag_has_boolean_attribute(tag, "disabled"):
            continue
        selected: list[str] = []
        fallback = ""
        for option in re.finditer(
            r"<option\b([^>]*)>([\s\S]*?)</option>",
            match.group(2),
            flags=re.IGNORECASE,
        ):
            option_tag = "<option" + option.group(1) + ">"
            option_attrs = html_attrs(option_tag)
            value = option_attrs.get("value", html_text(option.group(2)))
            if not fallback:
                fallback = value
            if _tag_has_boolean_attribute(option_tag, "selected"):
                selected.append(value)
        for value in selected or [fallback]:
            controls.append((name, value))
    return controls


def _control_values(controls: list[tuple[str, str]], name: str) -> list[str]:
    return [value for key, value in controls if key == name]


def _set_form_control(
    controls: list[tuple[str, str]],
    name: str,
    value: str | int | float | bool | list[str],
) -> None:
    controls[:] = [(key, item) for key, item in controls if key != name]
    values = value if isinstance(value, list) else [value]
    controls.extend((name, str(item)) for item in values)


def _html_element_fragment(html: str, opening: re.Match[str]) -> str:
    tag_match = re.match(r"<\s*([a-zA-Z0-9]+)\b", opening.group(0))
    if not tag_match:
        return opening.group(0)
    tag = tag_match.group(1)
    depth = 0
    for token in re.finditer(
        rf"</?{re.escape(tag)}\b[^>]*>",
        html[opening.start() :],
        flags=re.IGNORECASE | re.DOTALL,
    ):
        text = token.group(0)
        if text.startswith("</"):
            depth -= 1
            if depth == 0:
                return html[opening.start() : opening.start() + token.end()]
        elif not text.rstrip().endswith("/>"):
            depth += 1
    return html[opening.start() :]


def _numeric_or_text(value: str) -> int | float | str:
    value = value.strip()
    if not value:
        return ""
    try:
        number = float(value)
    except ValueError:
        return value
    return int(number) if number.is_integer() else number


def normalize_homework_question_type(question_type: str) -> str:
    normalized = str(question_type or "").strip().lower()
    try:
        return HOMEWORK_QUESTION_TYPE_ALIASES[normalized]
    except KeyError as exc:
        supported = ", ".join(item["key"] for item in HOMEWORK_QUESTION_TYPES.values())
        raise ChaoxingAPIError(
            f"unsupported homework question type: {question_type}; supported: {supported}"
        ) from exc


def parse_homework_editor_outline(html: str) -> dict[str, Any]:
    hidden = parse_hidden_inputs(html)
    controls = _html_form_controls(_form_fragment(html, "workForm"))
    title_values = _control_values(controls, "title")
    groups: list[dict[str, Any]] = []
    questions: list[dict[str, Any]] = []
    document = re.sub(
        r"<script\b[^>]*>[\s\S]*?</script>",
        "",
        html,
        flags=re.IGNORECASE,
    )
    for opening in re.finditer(
        r"<div\b[^>]*class=['\"][^'\"]*\bcatalogDiv\b[^'\"]*['\"][^>]*>",
        document,
        flags=re.IGNORECASE | re.DOTALL,
    ):
        fragment = _html_element_fragment(document, opening)
        group_attrs = html_attrs(opening.group(0))
        type_input = re.search(
            r"<input\b[^>]*\bname=['\"]qTypeValue['\"][^>]*>",
            fragment,
            flags=re.IGNORECASE | re.DOTALL,
        )
        if not type_input:
            continue
        type_attrs = html_attrs(type_input.group(0))
        type_code = type_attrs.get("value", "")
        type_info = HOMEWORK_QUESTION_TYPES.get(
            type_code,
            {"key": f"type_{type_code}", "label": f"题型 {type_code}"},
        )
        score_match = re.search(
            r"<input\b[^>]*class=['\"][^'\"]*\bquestionScore\b[^'\"]*['\"][^>]*>",
            fragment,
            flags=re.IGNORECASE | re.DOTALL,
        )
        group_questions: list[dict[str, Any]] = []
        for question_match in re.finditer(
            r"<li\b(?=[^>]*\bonclick=['\"]viewQuestion\()[^>]*>",
            fragment,
            flags=re.IGNORECASE | re.DOTALL,
        ):
            question_tag = question_match.group(0)
            question_attrs = html_attrs(question_tag)
            onclick = question_attrs.get("onclick", "")
            call = re.search(
                r"viewQuestion\(\s*['\"]?([^,'\")]+)['\"]?\s*,\s*"
                r"['\"]?([^,'\")]+)['\"]?\s*,\s*['\"]?([^,'\")]+)['\"]?\s*,\s*"
                r"['\"]?([^,'\")]+)['\"]?\s*\)",
                onclick,
                flags=re.IGNORECASE,
            )
            if not call:
                continue
            li_fragment = _html_element_fragment(fragment, question_match)
            preview_match = re.search(
                r"<span\b[^>]*class=['\"][^'\"]*\bqueliTitle\b[^'\"]*['\"][^>]*>"
                r"([\s\S]*?)</span>",
                li_fragment,
                flags=re.IGNORECASE,
            )
            question = {
                "index": int(question_attrs.get("qidx") or len(questions) + 1),
                "type_index": int(question_attrs.get("data") or len(group_questions) + 1),
                "question_id": call.group(1).strip(),
                "question_type_code": call.group(2).strip() or type_code,
                "question_type": type_info["key"],
                "question_type_label": type_info["label"],
                "course_question_type_id": call.group(3).strip()
                or type_attrs.get("coursequestiontypeid", ""),
                "relation_id": call.group(4).strip() or group_attrs.get("id", ""),
                "preview": html_text(preview_match.group(1)) if preview_match else "",
            }
            group_questions.append(question)
            questions.append(question)
        groups.append(
            {
                "relation_id": group_attrs.get("id", ""),
                "question_type_code": type_code,
                "question_type": type_info["key"],
                "question_type_label": type_info["label"],
                "course_question_type_id": type_attrs.get("coursequestiontypeid", ""),
                "question_count": len(group_questions),
                "total_score": (
                    _numeric_or_text(html_attrs(score_match.group(0)).get("value", ""))
                    if score_match
                    else ""
                ),
                "questions": group_questions,
            }
        )
    return {
        "work_id": hidden.get("workid", ""),
        "title": title_values[0] if title_values else "",
        "directory_id": hidden.get("directoryid", ""),
        "grading": hidden.get("grading", ""),
        "question_group": hidden.get("questionGroup", ""),
        "work_used": hidden.get("workUsed", "").lower() == "true",
        "question_count": len(questions),
        "groups": groups,
        "questions": questions,
    }


def parse_homework_question_detail(
    html: str,
    *,
    question_id: str = "",
    question_type_code: str = "",
    relation_id: str = "",
    index: int | None = None,
) -> dict[str, Any]:
    controls = _html_form_controls(html)

    def first(name: str, default: str = "") -> str:
        values = _control_values(controls, name)
        return values[0] if values else default

    type_info = HOMEWORK_QUESTION_TYPES.get(
        question_type_code,
        {"key": f"type_{question_type_code}", "label": f"题型 {question_type_code}"},
    )
    stem_html = first("content")
    analysis_html = first("answerAnalysis")
    options: list[dict[str, Any]] = []
    correct_answers = [value.upper() for value in _control_values(controls, "defAnswer")]
    for name, value in controls:
        if re.fullmatch(r"[A-Z]", name):
            options.append(
                {
                    "label": name,
                    "text": html_text(value),
                    "html": value,
                    "correct": name in correct_answers,
                }
            )

    fill_answers = [
        {
            "blank": int(name),
            "text": html_text(value),
            "html": value,
        }
        for name, value in controls
        if name.isdigit()
    ]
    fill_answers.sort(key=lambda item: item["blank"])

    true_false_answer: bool | None = None
    for tag in re.findall(r"<a\b[^>]*>", html, flags=re.IGNORECASE | re.DOTALL):
        attrs = html_attrs(tag)
        call = re.search(
            r"checkTrueFalse\(\s*(true|false)\s*\)",
            attrs.get("onclick", ""),
            flags=re.IGNORECASE,
        )
        if call and "check_answer" in attrs.get("class", "").split():
            true_false_answer = call.group(1).lower() == "true"
            break

    if question_type_code in {"0", "1"}:
        answer: Any = correct_answers
        if question_type_code == "0":
            answer = correct_answers[0] if correct_answers else ""
    elif question_type_code == "2":
        answer = fill_answers
    elif question_type_code == "3":
        answer = true_false_answer
    else:
        answer_html = first("answer")
        answer = html_text(answer_html)

    answer_html = first("answer") if question_type_code not in {"0", "1", "2", "3"} else ""
    return {
        "index": index,
        "question_id": question_id,
        "relation_id": relation_id,
        "question_type_code": question_type_code,
        "question_type": type_info["key"],
        "question_type_label": type_info["label"],
        "score": _numeric_or_text(first("score")),
        "stem": html_text(stem_html),
        "stem_html": stem_html,
        "stem_images": parse_content_images(stem_html),
        "stem_attachments": parse_attachment_iframes(stem_html),
        "options": options,
        "answer": answer,
        "answer_html": answer_html,
        "answer_analysis": html_text(analysis_html),
        "answer_analysis_html": analysis_html,
        "difficulty": _numeric_or_text(first("difficulty")),
        "topic_id": first("topicId"),
        "school_topic_ids": first("schoolTopicIds"),
        "label_ids": first("labelIdArr"),
        "word_min": _numeric_or_text(first("wordMinNum")),
        "word_max": _numeric_or_text(first("wordnum")),
    }


def _resolve_titled_item(
    items: list[dict[str, Any]],
    query: str,
    *,
    id_key: str,
    label: str,
) -> dict[str, Any]:
    normalized = query.strip().lower()
    if not normalized:
        raise ChaoxingAPIError(f"{label} index, title, or ID is required")
    for key in (id_key, "index"):
        exact = [item for item in items if str(item.get(key, "")).strip().lower() == normalized]
        if len(exact) == 1:
            return exact[0]
    exact_titles = [
        item for item in items if str(item.get("title", "")).strip().lower() == normalized
    ]
    if len(exact_titles) == 1:
        return exact_titles[0]
    partial = [item for item in items if normalized in str(item.get("title", "")).lower()]
    if len(partial) == 1:
        return partial[0]
    if not partial:
        raise ChaoxingAPIError(f"{label} not found: {query}")
    candidates = ", ".join(
        f"{item.get('index')}. {item.get('title')} ({item.get(id_key)})" for item in partial
    )
    raise ChaoxingAPIError(f"multiple {label} matches: {candidates}")


def resolve_homework_library_item(items: list[dict[str, Any]], query: str) -> dict[str, Any]:
    return _resolve_titled_item(items, query, id_key="item_id", label="homework-library item")


def resolve_homework_editor_target(
    library_items: list[dict[str, Any]],
    drafts: list[dict[str, Any]],
    query: str,
) -> dict[str, Any]:
    candidates: list[dict[str, Any]] = []
    for item in library_items:
        if item.get("is_folder"):
            continue
        candidates.append(
            {
                **item,
                "work_id": str(item.get("item_id") or ""),
                "source": "library",
            }
        )
    for item in drafts:
        candidates.append({**item, "source": "draft"})
    return _resolve_titled_item(
        candidates,
        query,
        id_key="work_id",
        label="editable homework",
    )


def resolve_homework_question(questions: list[dict[str, Any]], query: str) -> dict[str, Any]:
    normalized = str(query or "").strip().lower()
    if not normalized:
        raise ChaoxingAPIError("question index, ID, or stem is required")
    for key in ("question_id", "index"):
        exact = [
            question
            for question in questions
            if str(question.get(key, "")).strip().lower() == normalized
        ]
        if len(exact) == 1:
            return exact[0]
    exact_stems = [
        question
        for question in questions
        if str(question.get("stem", "")).strip().lower() == normalized
    ]
    if len(exact_stems) == 1:
        return exact_stems[0]
    partial = [
        question
        for question in questions
        if normalized in str(question.get("stem", "")).strip().lower()
        or normalized in str(question.get("preview", "")).strip().lower()
    ]
    if len(partial) == 1:
        return partial[0]
    if not partial:
        raise ChaoxingAPIError(f"homework question not found: {query}")
    candidates = ", ".join(
        f"{question.get('index')}. "
        f"{str(question.get('stem') or question.get('preview') or '')[:80]} "
        f"({question.get('question_id')})"
        for question in partial
    )
    raise ChaoxingAPIError(f"multiple homework questions match: {candidates}")


def resolve_homework_draft(items: list[dict[str, Any]], query: str) -> dict[str, Any]:
    return _resolve_titled_item(items, query, id_key="work_id", label="homework draft")


