def parse_submission_rows(html: str) -> tuple[list[dict[str, Any]], int]:
    hidden = parse_hidden_inputs(html)
    try:
        total_pages = max(1, int(hidden.get("totalPage") or "1"))
    except ValueError:
        total_pages = 1
    rows: list[dict[str, Any]] = []
    blocks = re.finditer(
        r"<ul\b[^>]*class=['\"][^'\"]*dataBody_td[^'\"]*['\"][\s\S]*?</ul>",
        html,
        flags=re.IGNORECASE,
    )
    for match in blocks:
        block = match.group(0)
        open_tag = re.search(r"<ul\b[^>]*>", block, flags=re.IGNORECASE)
        attrs = html_attrs(open_tag.group(0)) if open_tag else {}
        answer_id = str(attrs.get("id") or "").strip()
        if not answer_id:
            continue

        name_match = re.search(
            r"<div\b[^>]*class=['\"][^'\"]*py_name[^'\"]*['\"][^>]*>(.*?)</div>",
            block,
            flags=re.IGNORECASE | re.DOTALL,
        )
        name = html_text(name_match.group(1)) if name_match else ""
        li_texts = [
            html_text(item)
            for item in re.findall(r"<li\b[^>]*>(.*?)</li>", block, flags=re.IGNORECASE | re.DOTALL)
        ]
        details = [item for item in li_texts if item and item != "批阅 打回"]
        score_input = re.search(
            r"<input\b[^>]*class=['\"][^'\"]*scoreInput[^'\"]*['\"][^>]*>",
            block,
            flags=re.IGNORECASE | re.DOTALL,
        )
        score_attrs = html_attrs(score_input.group(0)) if score_input else {}
        review_match = re.search(
            r"data=['\"]([^'\"]*?/mooc2-ans/work/library/review-work\?[^'\"]+)['\"]",
            block,
            flags=re.IGNORECASE,
        )
        review_url = (
            urljoin(MOOC2_BASE_URL, unescape(review_match.group(1))) if review_match else ""
        )
        rows.append(
            {
                "answer_id": answer_id,
                "person_id": str(attrs.get("createid") or ""),
                "student_name": name,
                "student_no": details[1] if len(details) > 1 else "",
                "submitted_at": details[2] if len(details) > 2 else "",
                "submit_ip": details[3] if len(details) > 3 else "",
                "status": details[4] if len(details) > 4 else "",
                "reviewer": details[5] if len(details) > 5 else "",
                "score": score_attrs.get("value", ""),
                "score_data": score_attrs.get("data", ""),
                "review_url": review_url,
            }
        )
    return rows, total_pages


def resolve_submission(rows: list[dict[str, Any]], query: str) -> dict[str, Any]:
    normalized = query.strip().lower()
    if not normalized:
        raise ChaoxingAPIError("submission index, answer_id, student name, or number is required")
    for key in ("answer_id", "index", "student_no"):
        exact = [row for row in rows if str(row.get(key, "")).strip().lower() == normalized]
        if len(exact) == 1:
            return exact[0]
    exact_names = [
        row for row in rows if str(row.get("student_name", "")).strip().lower() == normalized
    ]
    if len(exact_names) == 1:
        return exact_names[0]
    partial = [
        row for row in rows if normalized in str(row.get("student_name", "")).strip().lower()
    ]
    if len(partial) == 1:
        return partial[0]
    if not partial:
        raise ChaoxingAPIError(f"submission not found: {query}")
    candidates = ", ".join(
        f"{row.get('index')}. {row.get('student_name')} ({row.get('student_no')})"
        for row in partial
    )
    raise ChaoxingAPIError(f"multiple submission matches: {candidates}")


def is_answer_image_url(url: str) -> bool:
    if not url:
        return False
    ignored = ("/mooc2-ans/module/work/images/", "/mooc2-ans/images/", "popClose")
    return not any(token in url for token in ignored)


def parse_attachment_iframes(fragment: str) -> list[dict[str, str]]:
    attachments: list[dict[str, str]] = []
    frames = re.findall(r"<iframe\b[^>]*>", fragment, flags=re.IGNORECASE | re.DOTALL)
    for frame in frames:
        attrs = html_attrs(frame)
        classes = set(attrs.get("class", "").split())
        if "attach-iframe" in classes:
            attachments.append(
                {
                    "filename": attrs.get("filename", ""),
                    "filetype": attrs.get("filetype", ""),
                    "objectid": attrs.get("objectid", ""),
                }
            )
            continue
        if attrs.get("module") != "insertdoc" and "ans-insertdoc-module" not in classes:
            continue
        raw_data = attrs.get("data", "")
        try:
            data = json.loads(unescape(raw_data)) if raw_data else {}
        except json.JSONDecodeError:
            data = {}
        if not isinstance(data, dict):
            data = {}
        attachments.append(
            {
                "filename": str(data.get("name") or data.get("title") or ""),
                "filetype": str(data.get("type") or ""),
                "objectid": str(data.get("objectid") or ""),
                "size": str(data.get("size") or data.get("hsize") or ""),
                "jobid": str(data.get("jobid") or data.get("_jobid") or ""),
            }
        )
    return attachments


def parse_review_summary(html: str, max_chars: int = 4000) -> dict[str, Any]:
    hidden = parse_hidden_inputs(html)
    fragments = re.findall(
        r"<dd\b[^>]*class=['\"][^'\"]*stuAnswerWords[^'\"]*['\"][^>]*>"
        r"([\s\S]*?)</dd>",
        html,
        flags=re.IGNORECASE,
    )
    student_answers: list[dict[str, Any]] = []
    answer_attachments: list[dict[str, str]] = []
    for fragment in fragments:
        images = [
            urljoin(MOOC2_BASE_URL, unescape(src))
            for src in re.findall(
                r"<img\b[^>]*src=['\"]([^'\"]+)['\"]",
                fragment,
                flags=re.IGNORECASE,
            )
            if is_answer_image_url(src)
        ]
        attachments = parse_attachment_iframes(fragment)
        answer_attachments.extend(attachments)
        student_answers.append(
            {
                "text": html_text(fragment),
                "images": images,
                "attachments": attachments,
            }
        )
    answer_images = [image for answer in student_answers for image in answer.get("images", [])]
    return {
        "work_answer_id": hidden.get("workAnswerId", ""),
        "work_id": hidden.get("workId", ""),
        "full_score": hidden.get("fullScore", ""),
        "student_answers": student_answers,
        "answer_images": answer_images,
        "student_answer_attachments": answer_attachments,
        "attachments": parse_attachment_iframes(html),
        "text_excerpt": html_text(html, limit=max_chars),
    }


def parse_notice_payload(payload: dict[str, Any]) -> tuple[list[dict[str, Any]], str]:
    notices_node = payload.get("notices")
    top_nodes = payload.get("topNotices")
    raw_items: list[Any] = []
    if isinstance(top_nodes, list):
        raw_items.extend(top_nodes)
    if isinstance(notices_node, dict) and isinstance(notices_node.get("list"), list):
        raw_items.extend(notices_node["list"])

    items: list[dict[str, Any]] = []
    seen: set[str] = set()
    for raw in raw_items:
        if not isinstance(raw, dict):
            continue
        notice_id = str(raw.get("idCode") or raw.get("uuid") or "").strip()
        if not notice_id or notice_id in seen:
            continue
        seen.add(notice_id)
        items.append(
            {
                "notice_id": notice_id,
                "uuid": str(raw.get("uuid") or ""),
                "title": str(raw.get("title") or "").strip(),
                "content": str(raw.get("content") or "").strip(),
                "rich_content": str(raw.get("rtf_content") or ""),
                "creator_name": str(raw.get("createrName") or ""),
                "send_time": str(raw.get("sendTime") or raw.get("completeTime") or ""),
                "insert_time": raw.get("insertTime"),
                "recipient_names": raw.get("toNames")
                if isinstance(raw.get("toNames"), list)
                else [],
                "recipient_count": raw.get("count_all"),
                "read_count": raw.get("count_read"),
                "is_top": bool(raw.get("top")),
                "send_tag": raw.get("sendTag"),
                "source_url": str(raw.get("sourceUrl") or ""),
                "attachments": raw.get("attachment")
                if isinstance(raw.get("attachment"), list)
                else [],
                "images": raw.get("img_data") if isinstance(raw.get("img_data"), list) else [],
                "allow_comments": raw.get("allow_comments"),
                "show_comments": raw.get("showComments"),
                "show_read": (
                    raw.get("extendParam", {}).get("showRead")
                    if isinstance(raw.get("extendParam"), dict)
                    else None
                ),
            }
        )
    next_value = str(notices_node.get("lastGetId") or "") if isinstance(notices_node, dict) else ""
    return items, next_value


def _json_list(value: Any) -> list[Any]:
    if isinstance(value, list):
        return value
    if not isinstance(value, str) or not value.strip():
        return []
    try:
        parsed = json.loads(value)
    except json.JSONDecodeError:
        return []
    return parsed if isinstance(parsed, list) else []


def _json_dict(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return value
    if not isinstance(value, str) or not value.strip():
        return {}
    try:
        parsed = json.loads(value)
    except json.JSONDecodeError:
        return {}
    return parsed if isinstance(parsed, dict) else {}


def parse_notice_draft_payload(
    payload: dict[str, Any],
) -> tuple[list[dict[str, Any]], str, bool]:
    raw_items = payload.get("draftList")
    pages = payload.get("pagesOffset")
    pages = pages if isinstance(pages, dict) else {}
    items: list[dict[str, Any]] = []
    if not isinstance(raw_items, list):
        raw_items = []
    for raw in raw_items:
        if not isinstance(raw, dict):
            continue
        draft_id = str(raw.get("id") or "").strip()
        draft_uuid = str(raw.get("uuid") or "").strip()
        if not draft_id and not draft_uuid:
            continue
        draft_params = _json_dict(raw.get("draftParamVo"))
        extension = _json_dict(draft_params.get("noticeSubmeterExtend"))
        send_time = raw.get("sendTime") or draft_params.get("sendTime")
        try:
            send_time = int(send_time) if send_time not in (None, "") else None
        except (TypeError, ValueError):
            send_time = None
        items.append(
            {
                "draft_id": draft_id,
                "draft_uuid": draft_uuid,
                "version": raw.get("version"),
                "title": str(raw.get("title") or "").strip(),
                "content": str(raw.get("content") or "").strip(),
                "rich_content": str(raw.get("rtf_content") or ""),
                "source_type": raw.get("sourceType"),
                "operation": str(raw.get("operTypeStr") or "add"),
                "status": raw.get("status"),
                "insert_time": raw.get("insertTime"),
                "update_time": raw.get("updateTime"),
                "send_time": send_time,
                "is_scheduled": send_time is not None,
                "recipients": _json_list(raw.get("toreceiver")),
                "notice_target": _json_list(draft_params.get("noticeTarget")),
                "notice_uuid": str(draft_params.get("uuid") or ""),
                "notice_id": str(
                    raw.get("noticeIdCode")
                    or raw.get("noticeId")
                    or draft_params.get("noticeId")
                    or ""
                ),
                "attachments": _json_list(raw.get("attachment")),
                "images": _json_list(raw.get("content_imgs")),
                "allow_comments": extension.get("allowComments"),
                "orderly_receive": _json_list(extension.get("orderlyReceive")),
            }
        )
    return items, str(pages.get("lastValue") or ""), bool(pages.get("lastPage"))


def resolve_notice_draft(drafts: list[dict[str, Any]], query: str) -> dict[str, Any]:
    normalized = query.strip().lower()
    if not normalized:
        raise ChaoxingAPIError("draft index, ID, UUID, or title is required")
    for key in ("draft_id", "draft_uuid", "index"):
        exact = [draft for draft in drafts if str(draft.get(key, "")).strip().lower() == normalized]
        if len(exact) == 1:
            return exact[0]
    exact_titles = [
        draft for draft in drafts if str(draft.get("title", "")).strip().lower() == normalized
    ]
    if len(exact_titles) == 1:
        return exact_titles[0]
    partial = [
        draft for draft in drafts if normalized in str(draft.get("title", "")).strip().lower()
    ]
    if len(partial) == 1:
        return partial[0]
    if not partial:
        raise ChaoxingAPIError(f"notice draft not found: {query}")
    candidates = ", ".join(
        f"{draft.get('index')}. {draft.get('title')} ({draft.get('draft_id')})" for draft in partial
    )
    raise ChaoxingAPIError(f"multiple notice draft matches: {candidates}")


def parse_notice_send_time(value: Any) -> int:
    if isinstance(value, bool) or value is None or str(value).strip() == "":
        raise ChaoxingAPIError("scheduled send time is required")
    timestamp: int
    if isinstance(value, (int, float)) or str(value).strip().isdigit():
        timestamp = int(float(value))
        if timestamp < 100_000_000_000:
            timestamp *= 1000
    else:
        normalized = str(value).strip().replace("/", "-")
        if normalized.endswith("Z"):
            normalized = normalized[:-1] + "+00:00"
        try:
            parsed = datetime.fromisoformat(normalized)
        except ValueError as exc:
            raise ChaoxingAPIError(
                "scheduled send time must be an epoch timestamp or ISO date-time"
            ) from exc
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone(timedelta(hours=8)))
        timestamp = int(parsed.timestamp() * 1000)
    if timestamp <= int(datetime.now(UTC).timestamp() * 1000) + 60_000:
        raise ChaoxingAPIError("scheduled send time must be at least one minute in the future")
    return timestamp


def _total_records(html: str) -> int | None:
    match = re.search(r"共\s*(\d+)\s*条", html_text(html), flags=re.IGNORECASE)
    return int(match.group(1)) if match else None


def parse_course_operation_log_rows(
    html: str,
) -> tuple[list[dict[str, Any]], int | None, list[dict[str, Any]]]:
    modules: list[dict[str, Any]] = []
    module_match = re.search(
        r"id=['\"]modules['\"][^>]*>(\s*\[[\s\S]*?\]\s*)<",
        html,
        flags=re.IGNORECASE,
    )
    if module_match:
        try:
            raw_modules = json.loads(unescape(module_match.group(1)).strip())
        except json.JSONDecodeError:
            raw_modules = []
        if isinstance(raw_modules, list):
            modules = [item for item in raw_modules if isinstance(item, dict)]

    rows: list[dict[str, Any]] = []
    for match in re.finditer(
        r"<ul\b[^>]*class=['\"][^'\"]*dataBody_td[^'\"]*['\"][^>]*>"
        r"([\s\S]*?)</ul>",
        html,
        flags=re.IGNORECASE,
    ):
        cells = [
            html_text(cell.group(1))
            for cell in re.finditer(r"<li\b[^>]*>([\s\S]*?)</li>", match.group(1), re.I)
        ]
        cells = [cell for cell in cells if cell]
        if len(cells) < 5:
            continue
        rows.append(
            {
                "operator_name": cells[0],
                "operator_no": cells[1],
                "operation": cells[2],
                "ip": cells[3],
                "operation_time": cells[4],
            }
        )
    return rows, _total_records(html), modules


def parse_student_join_log_rows(html: str) -> tuple[list[dict[str, Any]], int | None]:
    rows: list[dict[str, Any]] = []
    for match in re.finditer(r"<tr\b[^>]*>([\s\S]*?)</tr>", html, flags=re.IGNORECASE):
        cells = [
            html_text(cell.group(1))
            for cell in re.finditer(
                r"<t[dh]\b[^>]*>([\s\S]*?)</t[dh]>", match.group(1), flags=re.IGNORECASE
            )
        ]
        if len(cells) != 5 or cells[0] == "姓名":
            continue
        rows.append(
            {
                "student_name": cells[0],
                "student_no": cells[1],
                "clazz_name": cells[2],
                "join_method": cells[3],
                "join_time": cells[4],
            }
        )
    return rows, _total_records(html)


def parse_student_leave_log_rows(html: str) -> tuple[list[dict[str, Any]], int | None]:
    rows: list[dict[str, Any]] = []
    for match in re.finditer(
        r"<ul\b[^>]*class=['\"][^'\"]*dataBody_td[^'\"]*['\"][^>]*>"
        r"([\s\S]*?)</ul>",
        html,
        flags=re.IGNORECASE,
    ):
        fragment = match.group(1)
        drop_match = re.search(
            r"class=['\"][^'\"]*(?:dataBody_check|recoverystudy)[^'\"]*['\"][^>]*"
            r"\bdata=['\"]([^'\"]+)",
            fragment,
            flags=re.IGNORECASE,
        )
        if not drop_match:
            drop_match = re.search(
                r"\bdata=['\"]([^'\"]+)['\"][^>]*class=['\"][^'\"]*"
                r"(?:dataBody_check|recoverystudy)",
                fragment,
                flags=re.IGNORECASE,
            )
        cells = [
            html_text(cell.group(1))
            for cell in re.finditer(r"<li\b[^>]*>([\s\S]*?)</li>", fragment, re.I)
        ]
        cells = [cell for cell in cells if cell]
        if not drop_match or len(cells) < 6:
            continue
        rows.append(
            {
                "person_drop_id": drop_match.group(1),
                "student_name": cells[0],
                "clazz_name": cells[1],
                "operation": cells[2],
                "ip": cells[3],
                "operation_time": cells[4],
                "restorable": "恢复" in cells[-1],
            }
        )
    return rows, _total_records(html)


def parse_class_settings(html: str) -> dict[str, Any]:
    def checkbox(marker: str) -> bool:
        match = re.search(
            rf"<input\b(?=[^>]*\bonclick\s*=\s*['\"][^'\"]*{re.escape(marker)})[^>]*>",
            html,
            flags=re.IGNORECASE | re.DOTALL,
        )
        return bool(match and re.search(r"\bchecked\b", match.group(0), flags=re.I))

    def input_value(input_id: str) -> str:
        return input_attrs_by_id(html, input_id).get("value", "")

    public_enabled = checkbox("updateispublic")
    network_open = bool(
        re.search(
            r"<input\b(?=[^>]*\bid=['\"]networkopenId['\"])(?=[^>]*\bchecked\b)[^>]*>",
            html,
            flags=re.IGNORECASE | re.DOTALL,
        )
    )
    limit_match = re.search(
        r"<span\b(?=[^>]*\bid=['\"]classLimit['\"])[^>]*>",
        html,
        flags=re.IGNORECASE | re.DOTALL,
    )
    limit_attrs = html_attrs(limit_match.group(0)) if limit_match else {}
    limit_value = _number_value(limit_attrs.get("stunum"))
    semester_match = re.search(r"selectTerm\(\s*(\[.*?\])\s*\)", html, flags=re.S)
    semesters: list[dict[str, Any]] = []
    if semester_match:
        try:
            raw_semesters = json.loads(semester_match.group(1))
        except json.JSONDecodeError:
            raw_semesters = []
        if isinstance(raw_semesters, list):
            semesters = [
                {
                    "semester_id": str(item.get("id") or ""),
                    "name": str(item.get("texts") or ""),
                }
                for item in raw_semesters
                if isinstance(item, dict)
            ]
    return {
        "state": "ended" if input_value("clazzState") == "1" else "active",
        "allow_student_join": checkbox("updateEnableInvitecode"),
        "join_requires_approval": checkbox("updateIntoClazzValidation"),
        "unit_binding_requirement": (
            "course_unit"
            if checkbox("updateOnlyCourseUnitStudent")
            else "any_unit"
            if checkbox("updateOnlyBindUnitStudent")
            else "none"
        ),
        "allow_student_withdraw": checkbox("changeisretire"),
        "public_scope": (
            "network"
            if public_enabled and network_open
            else "school"
            if public_enabled
            else "closed"
        ),
        "application_start": input_value("applyStartTime"),
        "application_end": input_value("applyEndTime"),
        "semester_name": input_value("selectTerm"),
        "available_semesters": semesters,
        "student_limit": int(limit_value) if limit_value is not None else None,
        "open_start": input_value("registDate"),
        "open_end": input_value("endTime"),
        "ignore_video_restrictions": checkbox("ignoreVideoCtrl"),
        "hidden_from_students": checkbox("hideClazz"),
    }


def resolve_student_leave_log(records: list[dict[str, Any]], query: str) -> dict[str, Any]:
    normalized = query.strip().lower()
    if not normalized:
        raise ChaoxingAPIError("student name, leave-record ID, or index is required")
    exact = [
        item
        for item in records
        if normalized
        in {
            str(item.get("person_drop_id") or "").lower(),
            str(item.get("student_name") or "").strip().lower(),
            str(item.get("index") or ""),
        }
    ]
    if len(exact) == 1:
        return exact[0]
    partial = [
        item
        for item in records
        if normalized in str(item.get("student_name") or "").strip().lower()
    ]
    if len(partial) == 1:
        return partial[0]
    if not partial:
        raise ChaoxingAPIError(f"student leave record not found: {query}")
    candidates = ", ".join(
        f"{item.get('index')}. {item.get('student_name')} ({item.get('person_drop_id')})"
        for item in partial
    )
    raise ChaoxingAPIError(f"multiple student leave records match: {candidates}")


def resolve_notice(notices: list[dict[str, Any]], query: str) -> dict[str, Any]:
    normalized = query.strip().lower()
    if not normalized:
        raise ChaoxingAPIError("notice index, ID, UUID, or title is required")
    for key in ("notice_id", "uuid", "index"):
        exact = [
            notice for notice in notices if str(notice.get(key, "")).strip().lower() == normalized
        ]
        if len(exact) == 1:
            return exact[0]
    exact_titles = [
        notice for notice in notices if str(notice.get("title", "")).strip().lower() == normalized
    ]
    if len(exact_titles) == 1:
        return exact_titles[0]
    partial = [
        notice for notice in notices if normalized in str(notice.get("title", "")).strip().lower()
    ]
    if len(partial) == 1:
        return partial[0]
    if not partial:
        raise ChaoxingAPIError(f"notice not found: {query}")
    candidates = ", ".join(
        f"{notice.get('index')}. {notice.get('title')} ({notice.get('notice_id')})"
        for notice in partial
    )
    raise ChaoxingAPIError(f"multiple notice matches: {candidates}")


def parse_exam_items(html: str, page_url: str) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    blocks = re.finditer(
        r"<li\b[^>]*data=['\"](\d+)['\"][^>]*>[\s\S]*?</li>",
        html,
        flags=re.IGNORECASE,
    )
    for match in blocks:
        block = match.group(0)
        task_id = match.group(1)
        content_tag = re.search(
            r"<div\b[^>]*class=['\"][^'\"]*list_li_content[^'\"]*['\"][^>]*>",
            block,
            flags=re.IGNORECASE,
        )
        content_attrs = html_attrs(content_tag.group(0)) if content_tag else {}
        title_match = re.search(
            r"<h2\b[^>]*class=['\"][^'\"]*list_li_tit[^'\"]*['\"][^>]*>"
            r"(.*?)</h2>",
            block,
            flags=re.IGNORECASE | re.DOTALL,
        )
        if not title_match:
            continue
        class_match = re.search(
            r"<div\b[^>]*class=['\"][^'\"]*list_class[^'\"]*['\"][^>]*"
            r"title=['\"]([^'\"]*)['\"][^>]*>",
            block,
            flags=re.IGNORECASE | re.DOTALL,
        )
        time_match = re.search(
            r"<span>\s*考试时间[:：]\s*(.*?)\s*</span>",
            block,
            flags=re.IGNORECASE | re.DOTALL,
        )
        counts = re.search(r"(\d+)\s*待批\s*(\d+)\s*已交\s*(\d+)\s*未交", html_text(block))
        mark_match = re.search(
            r"href=['\"]([^'\"]*?/mooc2-ans/exam/test/marklist\?[^'\"]+)['\"]",
            block,
            flags=re.IGNORECASE,
        )
        settings_match = re.search(
            r"href=['\"]([^'\"]*?/mooc2-ans/exam/test/topublishsettings\?[^'\"]+)['\"]",
            block,
            flags=re.IGNORECASE,
        )
        items.append(
            {
                "exam_id": task_id,
                "paper_id": str(content_attrs.get("data") or ""),
                "title": html_text(title_match.group(1)),
                "clazz_name": unescape(class_match.group(1)).strip() if class_match else "",
                "exam_time": html_text(time_match.group(1)) if time_match else "",
                "pending_count": int(counts.group(1)) if counts else 0,
                "submitted_count": int(counts.group(2)) if counts else None,
                "unsubmitted_count": int(counts.group(3)) if counts else None,
                "paper_type": str(content_attrs.get("type") or ""),
                "parallel_paper": str(content_attrs.get("parallelpaper") or ""),
                "mark_url": (
                    urljoin(page_url, unescape(mark_match.group(1))) if mark_match else ""
                ),
                "settings_url": (
                    urljoin(page_url, unescape(settings_match.group(1))) if settings_match else ""
                ),
            }
        )
    return items


def resolve_exam(items: list[dict[str, Any]], query: str) -> dict[str, Any]:
    normalized = query.strip().lower()
    if not normalized:
        raise ChaoxingAPIError("exam index, title, exam_id, or paper_id is required")
    for key in ("exam_id", "paper_id", "index"):
        exact = [item for item in items if str(item.get(key, "")).strip().lower() == normalized]
        if len(exact) == 1:
            return exact[0]
    exact_titles = [
        item for item in items if str(item.get("title", "")).strip().lower() == normalized
    ]
    if len(exact_titles) == 1:
        return exact_titles[0]
    partial = [item for item in items if normalized in str(item.get("title", "")).strip().lower()]
    if len(partial) == 1:
        return partial[0]
    if not partial:
        raise ChaoxingAPIError(f"exam not found: {query}")
    candidates = ", ".join(
        f"{item.get('index')}. {item.get('title')} ({item.get('exam_id')})" for item in partial
    )
    raise ChaoxingAPIError(f"multiple exam matches: {candidates}")


def _class_cell_values(fragment: str, class_name: str) -> list[str]:
    return [
        html_text(match.group(1))
        for match in re.finditer(
            rf"<li\b[^>]*class=['\"][^'\"]*\b{re.escape(class_name)}\b[^'\"]*['\"][^>]*>"
            r"([\s\S]*?)</li>",
            fragment,
            flags=re.IGNORECASE,
        )
    ]


def parse_exam_paper_library_items(html: str) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    for block in _data_body_blocks(html):
        opening = re.search(r"<ul\b[^>]*>", block, flags=re.IGNORECASE | re.DOTALL)
        attrs = html_attrs(opening.group(0)) if opening else {}
        item_id = str(attrs.get("data") or "").strip()
        item_type = str(attrs.get("type") or "").strip()
        if not item_id.isdigit() or item_type not in {"0", "1"}:
            continue

        title_match = re.search(
            r"<a\b([^>]*\bclass=['\"][^'\"]*\brename_title\b[^'\"]*['\"][^>]*)>"
            r"([\s\S]*?)</a>",
            block,
            flags=re.IGNORECASE,
        )
        if not title_match:
            continue
        title_attrs = html_attrs("<a" + title_match.group(1) + ">")
        title = html_text(title_attrs.get("title") or title_match.group(2))
        if not title:
            continue

        reads = _class_cell_values(block, "dataBody_read")
        details = _class_cell_values(block, "dataBody_down")
        look_match = re.search(
            r"paperLibLookPaper\(\s*['\"]?([^,'\"\s]+)['\"]?\s*,\s*"
            r"['\"]?(\d+)['\"]?\s*,\s*['\"]?([^)'\"\s]+)",
            block,
            flags=re.IGNORECASE,
        )
        publish_match = re.search(
            r"['\"]([^'\"]*?/mooc2-ans/exam/test/topublish\?[^'\"]+)['\"]",
            block,
            flags=re.IGNORECASE,
        )

        if item_type == "0":
            items.append(
                {
                    "item_id": item_id,
                    "folder_id": item_id,
                    "title": title,
                    "item_type": "folder",
                    "is_folder": True,
                    "creator": details[-2] if len(details) >= 2 else "",
                }
            )
            continue

        question_count = _numeric_or_text(reads[0]) if reads else ""
        total_score = _numeric_or_text(reads[1]) if len(reads) > 1 else ""
        usage_count = _numeric_or_text(details[2]) if len(details) > 2 else ""
        items.append(
            {
                "item_id": item_id,
                "paper_id": item_id,
                "title": title,
                "item_type": "paper",
                "is_folder": False,
                "creator_id": str(attrs.get("createruid") or ""),
                "question_count": question_count if isinstance(question_count, int) else None,
                "total_score": (total_score if isinstance(total_score, (int, float)) else None),
                "difficulty": details[0] if details else "",
                "creator": details[1] if len(details) > 1 else "",
                "usage_count": usage_count if isinstance(usage_count, int) else None,
                "paper_type": look_match.group(1) if look_match else "0",
                "parallel_paper": look_match.group(3) if look_match else "0",
                "publish_url": (
                    urljoin(MOOC2_BASE_URL, unescape(publish_match.group(1)))
                    if publish_match
                    else ""
                ),
            }
        )
    return items


def resolve_exam_paper_library_item(
    items: list[dict[str, Any]], query: str, *, folders: bool | None = None
) -> dict[str, Any]:
    normalized = query.strip().lower()
    if not normalized:
        raise ChaoxingAPIError("paper-library index, ID, or title is required")
    candidates = [
        item for item in items if folders is None or bool(item.get("is_folder")) is folders
    ]
    for key in ("item_id", "paper_id", "folder_id", "index"):
        exact = [
            item for item in candidates if str(item.get(key) or "").strip().lower() == normalized
        ]
        if len(exact) == 1:
            return exact[0]
    exact_titles = [
        item for item in candidates if str(item.get("title") or "").strip().lower() == normalized
    ]
    if len(exact_titles) == 1:
        return exact_titles[0]
    partial = [
        item for item in candidates if normalized in str(item.get("title") or "").strip().lower()
    ]
    if len(partial) == 1:
        return partial[0]
    kind = "folder" if folders else "paper" if folders is False else "paper-library item"
    if not partial:
        raise ChaoxingAPIError(f"{kind} not found: {query}")
    labels = ", ".join(
        f"{item.get('index')}. {item.get('title')} ({item.get('item_id')})" for item in partial[:10]
    )
    raise ChaoxingAPIError(f"multiple {kind} matches: {labels}")


def normalize_exam_question_type(question_type: str) -> str:
    normalized = str(question_type or "").strip().lower()
    try:
        return EXAM_CORE_QUESTION_TYPE_ALIASES[normalized]
    except KeyError as exc:
        supported = ", ".join(item["key"] for item in EXAM_CORE_QUESTION_TYPES.values())
        raise ChaoxingAPIError(
            f"unsupported exam question type: {question_type}; supported: {supported}"
        ) from exc


def parse_exam_editor_outline(html: str) -> dict[str, Any]:
    hidden = parse_hidden_inputs(html)
    document = re.sub(
        r"<(script|style)\b[^>]*>[\s\S]*?</\1>",
        "",
        html,
        flags=re.IGNORECASE,
    )
    title_match = re.search(
        r"<input\b[^>]*\bname=['\"]examPaperTitle['\"][^>]*>",
        document,
        flags=re.IGNORECASE | re.DOTALL,
    )
    title = html_attrs(title_match.group(0)).get("value", "") if title_match else ""
    total_count_match = re.search(
        r"<i\b[^>]*\bid=['\"]totalQuestionNum['\"][^>]*>([\s\S]*?)</i>",
        document,
        flags=re.IGNORECASE,
    )
    total_score_match = re.search(
        r"<i\b[^>]*\bid=['\"]questionScoreSum['\"][^>]*>([\s\S]*?)</i>",
        document,
        flags=re.IGNORECASE,
    )

    groups: list[dict[str, Any]] = []
    questions: list[dict[str, Any]] = []
    for opening in re.finditer(
        r"<div\b[^>]*class=['\"][^'\"]*\bquesTypeBlock\b[^'\"]*['\"][^>]*>",
        document,
        flags=re.IGNORECASE | re.DOTALL,
    ):
        fragment = _html_element_fragment(document, opening)
        group_attrs = html_attrs(opening.group(0))
        relation_id = str(group_attrs.get("id") or "").strip()
        if not relation_id:
            continue
        type_input = re.search(
            r"<input\b[^>]*\bname=['\"]qTypeValue['\"][^>]*>",
            fragment,
            flags=re.IGNORECASE | re.DOTALL,
        )
        if not type_input:
            continue
        type_attrs = html_attrs(type_input.group(0))
        type_code = str(type_attrs.get("value") or group_attrs.get("type") or "").strip()
        type_info = EXAM_CORE_QUESTION_TYPES.get(
            type_code,
            {"key": f"type_{type_code}", "label": f"题型 {type_code}"},
        )
        name_match = re.search(
            r"<span\b[^>]*class=['\"][^'\"]*\bquestionTypeName\b[^'\"]*['\"][^>]*>"
            r"([\s\S]*?)</span>",
            fragment,
            flags=re.IGNORECASE,
        )
        question_type_label = html_text(name_match.group(1)) if name_match else type_info["label"]
        score_match = re.search(
            r"<input\b[^>]*class=['\"][^'\"]*\bquestionScore\b[^'\"]*['\"][^>]*>",
            fragment,
            flags=re.IGNORECASE | re.DOTALL,
        )
        description_match = re.search(
            r"<div\b[^>]*class=['\"][^'\"]*\btypeInfo_tit\b[^'\"]*['\"][^>]*>"
            r"[\s\S]*?<p\b([^>]*)>([\s\S]*?)</p>",
            fragment,
            flags=re.IGNORECASE,
        )
        description = ""
        if description_match:
            description_attrs = html_attrs("<p" + description_match.group(1) + ">")
            description = html_text(description_attrs.get("title") or description_match.group(2))
            description = re.sub(r"^题型说明\s*[:：]?\s*", "", description)

        group_questions: list[dict[str, Any]] = []
        for question_opening in re.finditer(
            r"<li\b(?=[^>]*\bonclick=['\"][^'\"]*doQuestionLiClick\()[^>]*>",
            fragment,
            flags=re.IGNORECASE | re.DOTALL,
        ):
            question_tag = question_opening.group(0)
            question_attrs = html_attrs(question_tag)
            call = re.search(
                r"doQuestionLiClick\(\s*['\"]?([^,'\")]+)['\"]?\s*,\s*"
                r"['\"]?([^,'\")]+)['\"]?\s*,\s*['\"]?([^,'\")]+)['\"]?",
                question_attrs.get("onclick", ""),
                flags=re.IGNORECASE,
            )
            if not call:
                continue
            question_id = str(call.group(1) or question_attrs.get("id") or "").strip()
            if not question_id:
                continue
            question_fragment = _html_element_fragment(fragment, question_opening)
            index_match = re.search(
                r"<span\b[^>]*class=['\"][^'\"]*\bquesIndex\b[^'\"]*['\"][^>]*>"
                r"([\s\S]*?)</span>",
                question_fragment,
                flags=re.IGNORECASE,
            )
            question_score_match = re.search(
                r"<span\b[^>]*class=['\"][^'\"]*\bquesScore\b[^'\"]*['\"][^>]*>"
                r"([\s\S]*?)</span>",
                question_fragment,
                flags=re.IGNORECASE,
            )
            preview_match = re.search(
                r"<span\b[^>]*class=['\"][^'\"]*\bcontentTitle\b[^'\"]*['\"][^>]*>"
                r"([\s\S]*?)</span>",
                question_fragment,
                flags=re.IGNORECASE,
            )
            parsed_index = _numeric_or_text(html_text(index_match.group(1)) if index_match else "")
            question_type_code = str(call.group(2) or type_code).strip()
            question_type_info = EXAM_CORE_QUESTION_TYPES.get(
                question_type_code,
                {
                    "key": f"type_{question_type_code}",
                    "label": question_type_label,
                },
            )
            question = {
                "index": parsed_index if isinstance(parsed_index, int) else len(questions) + 1,
                "type_index": len(group_questions) + 1,
                "question_id": question_id,
                "section_id": question_id,
                "relation_id": relation_id,
                "question_type_code": question_type_code,
                "question_type": question_type_info["key"],
                "question_type_label": question_type_label,
                "course_question_type_id": str(
                    call.group(3) or type_attrs.get("coursequestiontypeid") or "0"
                ).strip(),
                "score": _numeric_or_text(
                    html_text(question_score_match.group(1)) if question_score_match else ""
                ),
                "preview": html_text(preview_match.group(1)) if preview_match else "",
            }
            group_questions.append(question)
            questions.append(question)

        groups.append(
            {
                "index": len(groups) + 1,
                "relation_id": relation_id,
                "question_type_code": type_code,
                "question_type": type_info["key"],
                "question_type_label": question_type_label,
                "course_question_type_id": str(
                    type_attrs.get("coursequestiontypeid") or "0"
                ).strip(),
                "description": description,
                "question_count": len(group_questions),
                "total_score": (
                    _numeric_or_text(html_attrs(score_match.group(0)).get("value", ""))
                    if score_match
                    else ""
                ),
                "questions": group_questions,
            }
        )

    total_count = (
        _numeric_or_text(html_text(total_count_match.group(1))) if total_count_match else ""
    )
    total_score = (
        _numeric_or_text(html_text(total_score_match.group(1))) if total_score_match else ""
    )
    difficulty_match = re.search(
        r"<strong\b[^>]*\bid=['\"]selectBox['\"][^>]*>[\s\S]*?"
        r"<p\b[^>]*>\s*<span\b([^>]*)>([\s\S]*?)</span>",
        document,
        flags=re.IGNORECASE,
    )
    difficulty_code = ""
    difficulty_label = ""
    if difficulty_match:
        difficulty_code = html_attrs("<span" + difficulty_match.group(1) + ">").get("value", "")
        difficulty_label = html_text(difficulty_match.group(2))
    return {
        "paper_id": str(hidden.get("paperid") or ""),
        "title": title,
        "is_open": str(hidden.get("isOpen") or ""),
        "is_group_paper": str(hidden.get("isGroupPaper") or "").lower() == "true",
        "group_id": str(hidden.get("currPaperGroupId") or "0"),
        "question_group": str(hidden.get("questionGroup") or "0"),
        "serial_number_mode": str(hidden.get("serialNumberMode") or "0"),
        "item_serial_number_mode": str(hidden.get("itemSerialNumberMode") or "0"),
        "difficulty_code": difficulty_code,
        "difficulty_label": difficulty_label,
        "score_decimal_places": _numeric_or_text(hidden.get("scoreDecimalPlaces", "")),
        "max_title_length": _numeric_or_text(hidden.get("maxPaperTitleLength", "")),
        "question_count": total_count if isinstance(total_count, int) else len(questions),
        "total_score": total_score,
        "group_count": len(groups),
        "groups": groups,
        "questions": questions,
    }


def parse_exam_question_detail(
    html: str,
    *,
    question_id: str = "",
    question_type_code: str = "",
    relation_id: str = "",
    index: int | None = None,
) -> dict[str, Any]:
    controls = _html_form_controls(html)
    hidden = parse_hidden_inputs(html)

    def first(name: str, default: str = "") -> str:
        values = _control_values(controls, name)
        if values:
            return values[0]
        return str(hidden.get(name) or default)

    type_info = EXAM_CORE_QUESTION_TYPES.get(
        question_type_code,
        {"key": f"type_{question_type_code}", "label": f"题型 {question_type_code}"},
    )
    stem_html = first("content")
    analysis_html = first("answerAnalysis")
    correct_answers = [value.upper() for value in _control_values(controls, "defAnswer")]
    options = [
        {
            "label": name,
            "text": html_text(value),
            "html": value,
            "correct": name in correct_answers,
        }
        for name, value in controls
        if re.fullmatch(r"[A-Z]", name)
    ]
    fill_answers = [
        {"blank": int(name), "text": html_text(value), "html": value}
        for name, value in controls
        if name.isdigit()
    ]
    fill_answers.sort(key=lambda item: item["blank"])

    true_false_answer: bool | None = None
    for tag in re.findall(r"<a\b[^>]*>", html, flags=re.IGNORECASE | re.DOTALL):
        attrs = html_attrs(tag)
        call = re.search(
            r"checkTrueFalse\(\s*(true|false)\s*\)",
            attrs.get("onclick", ""),
            flags=re.IGNORECASE,
        )
        if call and "check_answer" in attrs.get("class", "").split():
            true_false_answer = call.group(1).lower() == "true"
            break

    if question_type_code in {"0", "1"}:
        answer: Any = correct_answers
        if question_type_code == "0":
            answer = correct_answers[0] if correct_answers else ""
        answer_html = ""
    elif question_type_code == "2":
        answer = fill_answers
        answer_html = ""
    elif question_type_code == "3":
        answer = true_false_answer
        answer_html = ""
    else:
        answer_html = first("answer")
        answer = html_text(answer_html)

    return {
        "index": index,
        "question_id": str(question_id),
        "section_id": str(question_id),
        "relation_id": str(relation_id),
        "question_type_code": str(question_type_code),
        "question_type": type_info["key"],
        "question_type_label": type_info["label"],
        "score": _numeric_or_text(first("score")),
        "stem": html_text(stem_html),
        "stem_html": stem_html,
        "stem_images": parse_content_images(stem_html),
        "stem_attachments": parse_attachment_iframes(stem_html),
        "options": options,
        "answer": answer,
        "answer_html": answer_html,
        "answer_analysis": html_text(analysis_html),
        "answer_analysis_html": analysis_html,
        "difficulty": _numeric_or_text(first("difficulty")),
        "easy": first("easy", "0"),
        "topic_id": first("topicId", "0"),
        "school_topic_ids": first("schoolTopicIds"),
        "label_ids": first("labelIdArr"),
        "target_data": first("targetData"),
        "is_mutex": first("isMutex"),
        "blank_subject": bool(
            re.search(
                r"class=['\"][^'\"]*\bblankSubjectCheck\b[^'\"]*\bchecked_dx\b",
                html,
                flags=re.IGNORECASE,
            )
        ),
        "standard_id": first("standardId", "0"),
        "word_min": _numeric_or_text(first("wordMinNum", "0")),
        "word_max": _numeric_or_text(first("wordnum", "0")),
        "score_points": first("scorePoints") or first("saveScorePoints"),
        "use_ai": first("useAi", "0"),
        "auto_score": first("autoScore", "0"),
        "prompt_id": first("promptId", "-1"),
    }


def resolve_exam_editor_question(questions: list[dict[str, Any]], query: str) -> dict[str, Any]:
    normalized = str(query or "").strip().lower()
    if not normalized:
        raise ChaoxingAPIError("exam question index, ID, or stem preview is required")
    for key in ("question_id", "section_id", "index"):
        exact = [
            question
            for question in questions
            if str(question.get(key) or "").strip().lower() == normalized
        ]
        if len(exact) == 1:
            return exact[0]
    partial = [
        question
        for question in questions
        if normalized in str(question.get("stem") or question.get("preview") or "").lower()
    ]
    if len(partial) == 1:
        return partial[0]
    if not partial:
        raise ChaoxingAPIError(f"exam question not found: {query}")
    labels = ", ".join(
        f"{question.get('index')}. {str(question.get('preview') or '')[:80]} "
        f"({question.get('question_id')})"
        for question in partial[:10]
    )
    raise ChaoxingAPIError(f"multiple exam question matches: {labels}")


def resolve_exam_question_type_group(groups: list[dict[str, Any]], query: str) -> dict[str, Any]:
    normalized = str(query or "").strip().lower()
    if not normalized:
        raise ChaoxingAPIError(
            "exam question-type index, relation ID, type code, or label is required"
        )

    for key in ("relation_id", "index"):
        exact = [
            group for group in groups if str(group.get(key) or "").strip().lower() == normalized
        ]
        if len(exact) == 1:
            return exact[0]

    exact = [
        group
        for group in groups
        if normalized
        in {
            str(group.get("question_type_code") or "").strip().lower(),
            str(group.get("question_type") or "").strip().lower(),
            str(group.get("question_type_label") or "").strip().lower(),
        }
    ]
    if len(exact) == 1:
        return exact[0]

    partial = [
        group
        for group in groups
        if normalized
        in str(group.get("question_type_label") or group.get("description") or "").lower()
    ]
    if len(partial) == 1:
        return partial[0]

    candidates = exact or partial
    if not candidates:
        raise ChaoxingAPIError(f"exam question type not found: {query}")
    labels = ", ".join(
        f"{group.get('index')}. {group.get('question_type_label')} ({group.get('relation_id')})"
        for group in candidates[:10]
    )
    raise ChaoxingAPIError(f"multiple exam question types match: {labels}")


def reposition_identifier(
    identifiers: list[str], identifier: str, target_position: Any
) -> list[str]:
    if isinstance(target_position, bool):
        raise ChaoxingAPIError("target position must be an integer")
    try:
        position = int(str(target_position).strip())
    except (TypeError, ValueError) as exc:
        raise ChaoxingAPIError("target position must be an integer") from exc
    if str(position) != str(target_position).strip() and not isinstance(target_position, int):
        raise ChaoxingAPIError("target position must be an integer")
    normalized_ids = [str(value) for value in identifiers]
    identifier = str(identifier)
    if identifier not in normalized_ids:
        raise ChaoxingAPIError(f"item is absent from the current order: {identifier}")
    if not 1 <= position <= len(normalized_ids):
        raise ChaoxingAPIError(f"target position must be between 1 and {len(normalized_ids)}")
    reordered = [value for value in normalized_ids if value != identifier]
    reordered.insert(position - 1, identifier)
    return reordered


def _element_inner_html(fragment: str) -> str:
    opening_end = fragment.find(">")
    closing_start = fragment.rfind("</")
    if opening_end < 0:
        return fragment
    if closing_start <= opening_end:
        return fragment[opening_end + 1 :]
    return fragment[opening_end + 1 : closing_start]


def _exam_question_type(label: str) -> str:
    normalized = re.sub(r"\s+", "", label)
    return EXAM_QUESTION_TYPE_KEYS.get(normalized, "other")


def _exam_detail_block(question_html: str, label: str) -> str:
    for opening in re.finditer(
        r"<div\b[^>]*class=['\"][^'\"]*\bcomplete_bom\b[^'\"]*['\"][^>]*>",
        question_html,
        flags=re.IGNORECASE | re.DOTALL,
    ):
        block = _html_element_fragment(question_html, opening)
        if label in html_text(block):
            return block
    return ""


def _exam_detail_value(block: str) -> tuple[str, str]:
    if not block:
        return "", ""
    opening = re.search(
        r"<(?:div|p)\b[^>]*class=['\"][^'\"]*\bp_764\b[^'\"]*['\"][^>]*>",
        block,
        flags=re.IGNORECASE | re.DOTALL,
    )
    if not opening:
        return "", ""
    element = _html_element_fragment(block, opening)
    value_html = _element_inner_html(element).strip()
    return value_html, html_text(value_html)


def _exam_matching_columns(question_html: str) -> list[list[dict[str, str]]]:
    columns: list[list[dict[str, str]]] = []
    for opening in re.finditer(
        r"<div\b[^>]*class=['\"][^'\"]*\bline_wid_550\b[^'\"]*['\"][^>]*>",
        question_html,
        flags=re.IGNORECASE | re.DOTALL,
    ):
        column_html = _html_element_fragment(question_html, opening)
        values: list[dict[str, str]] = []
        for item in re.finditer(
            r"<div\b[^>]*class=['\"][^'\"]*\blineCt\b[^'\"]*['\"][^>]*>"
            r"\s*<span\b[^>]*>([\s\S]*?)</span>\s*"
            r"<div\b[^>]*>([\s\S]*?)</div>",
            column_html,
            flags=re.IGNORECASE,
        ):
            values.append(
                {
                    "label": html_text(item.group(1)).rstrip(".、"),
                    "content_html": item.group(2).strip(),
                    "content": html_text(item.group(2)),
                }
            )
        if values:
            columns.append(values)
    return columns


def parse_exam_paper(html: str, paper_id: str = "") -> dict[str, Any]:
    title_match = re.search(
        r"<h2\b[^>]*class=['\"][^'\"]*\blookTit\b[^'\"]*['\"][^>]*>"
        r"([\s\S]*?)</h2>",
        html,
        flags=re.IGNORECASE,
    )
    title = html_text(title_match.group(1)) if title_match else ""

    declared_question_count: int | None = None
    declared_total_score: int | float | None = None
    volume_opening = re.search(
        r"<div\b[^>]*class=['\"][^'\"]*\bvolumeLookDetails\b[^'\"]*['\"][^>]*>",
        html,
        flags=re.IGNORECASE | re.DOTALL,
    )
    if volume_opening:
        volume = _html_element_fragment(html, volume_opening)
        values = [
            _numeric_or_text(html_text(value.group(1)))
            for value in re.finditer(
                r"<span\b[^>]*class=['\"][^'\"]*\bcolorBlue\b[^'\"]*['\"][^>]*>"
                r"([\s\S]*?)</span>",
                volume,
                flags=re.IGNORECASE,
            )
        ]
        if values and isinstance(values[0], int):
            declared_question_count = values[0]
        if len(values) > 1 and isinstance(values[1], (int, float)):
            declared_total_score = values[1]

    groups: list[dict[str, Any]] = []
    questions: list[dict[str, Any]] = []
    group_openings = list(
        re.finditer(
            r"<div\b[^>]*class=['\"][^'\"]*\btypeDiv\b[^'\"]*['\"][^>]*>",
            html,
            flags=re.IGNORECASE | re.DOTALL,
        )
    )
    for group_number, group_opening in enumerate(group_openings, 1):
        group_html = _html_element_fragment(html, group_opening)
        heading_match = re.search(
            r"<h2\b[^>]*class=['\"][^'\"]*\btitle\b[^'\"]*['\"][^>]*>"
            r"([\s\S]*?)</h2>",
            group_html,
            flags=re.IGNORECASE,
        )
        instruction_match = re.search(
            r"<(?:p|div)\b[^>]*class=['\"][^'\"]*\btypeinfo\b[^'\"]*['\"][^>]*>"
            r"([\s\S]*?)</(?:p|div)>",
            group_html,
            flags=re.IGNORECASE,
        )
        question_openings = list(
            re.finditer(
                r"<div\b[^>]*class=['\"][^'\"]*\bstem_con\b[^'\"]*['\"][^>]*>",
                group_html,
                flags=re.IGNORECASE | re.DOTALL,
            )
        )
        group_questions: list[dict[str, Any]] = []
        for local_index, question_opening in enumerate(question_openings):
            end = (
                question_openings[local_index + 1].start()
                if local_index + 1 < len(question_openings)
                else len(group_html)
            )
            question_html = group_html[question_opening.start() : end]
            stem_element = _html_element_fragment(group_html, question_opening)
            stem_attrs = html_attrs(question_opening.group(0))
            raw_stem_html = _element_inner_html(stem_element)
            score_label_match = re.search(
                r"<span\b[^>]*class=['\"][^'\"]*\bcolorShallow\b[^'\"]*['\"][^>]*>"
                r"([\s\S]*?)</span>",
                raw_stem_html,
                flags=re.IGNORECASE,
            )
            score_label = html_text(score_label_match.group(1)) if score_label_match else ""
            type_match = re.search(r"[（(]\s*([^，,）)]+)", score_label)
            type_label = type_match.group(1).strip() if type_match else ""
            score_match = re.search(r"[，,]\s*(-?\d+(?:\.\d+)?)\s*分", score_label)
            score = _numeric_or_text(score_match.group(1)) if score_match else None
            number_match = re.match(r"\s*(\d+)\s*[.、]", html_text(raw_stem_html))
            question_number = int(number_match.group(1)) if number_match else len(questions) + 1
            stem_html = re.sub(
                r"^\s*\d+\s*[.、]\s*",
                "",
                raw_stem_html,
                count=1,
            )
            stem_html = re.sub(
                r"<span\b[^>]*class=['\"][^'\"]*\bcolorShallow\b[^'\"]*['\"][^>]*>"
                r"[\s\S]*?</span>",
                "",
                stem_html,
                count=1,
                flags=re.IGNORECASE,
            ).strip()

            options: list[dict[str, str]] = []
            for option in re.finditer(
                r"<span\b[^>]*class=['\"][^'\"]*\bnum_option\b[^'\"]*['\"][^>]*>"
                r"([\s\S]*?)</span>\s*"
                r"<div\b[^>]*class=['\"][^'\"]*\banswer_p\b[^'\"]*['\"][^>]*>"
                r"([\s\S]*?)</div>",
                question_html,
                flags=re.IGNORECASE,
            ):
                options.append(
                    {
                        "label": html_text(option.group(1)).rstrip(".、"),
                        "content_html": option.group(2).strip(),
                        "content": html_text(option.group(2)),
                    }
                )

            fill_answers = [
                {
                    "index": index,
                    "answer_html": answer.group(1).strip(),
                    "answer": html_text(answer.group(1)),
                }
                for index, answer in enumerate(
                    re.finditer(
                        r"<div\b[^>]*class=['\"][^'\"]*\bans-wid-cRight\b[^'\"]*"
                        r"['\"][^>]*>([\s\S]*?)</div>",
                        question_html,
                        flags=re.IGNORECASE,
                    ),
                    1,
                )
            ]
            matching_pairs = [
                {
                    "left": html_text(pair.group(1)),
                    "right": html_text(pair.group(2)),
                }
                for pair in re.finditer(
                    r"<span\b[^>]*class=['\"][^'\"]*\bline_option\b[^'\"]*['\"][^>]*>"
                    r"([\s\S]*?)</span>[\s\S]*?"
                    r"<span\b[^>]*class=['\"][^'\"]*\bline_option_answer\b[^'\"]*"
                    r"['\"][^>]*>([\s\S]*?)</span>",
                    question_html,
                    flags=re.IGNORECASE,
                )
            ]

            answer_html = ""
            answer_match = re.search(
                r"<div\b[^>]*class=['\"][^'\"]*\banswer_tit\b[^'\"]*['\"][^>]*>"
                r"([\s\S]*?)</div>",
                question_html,
                flags=re.IGNORECASE,
            )
            if answer_match:
                answer_html = re.sub(
                    r"^\s*答案\s*[:：]\s*",
                    "",
                    answer_match.group(1),
                    count=1,
                ).strip()
            analysis_html, analysis = _exam_detail_value(
                _exam_detail_block(question_html, "答案解析")
            )
            difficulty_html, difficulty_text = _exam_detail_value(
                _exam_detail_block(question_html, "难度")
            )
            difficulty_match = re.search(r"-?\d+(?:\.\d+)?", difficulty_text)
            difficulty = _numeric_or_text(difficulty_match.group(0)) if difficulty_match else None
            topic_block = _exam_detail_block(question_html, "知识点")
            topics = [
                {
                    "topic_id": topic.group(1),
                    "title": html_text(topic.group(2)),
                }
                for topic in re.finditer(
                    r"<[^>]+\btopicid=['\"]([^'\"]+)['\"][^>]*>([\s\S]*?)</[^>]+>",
                    topic_block,
                    flags=re.IGNORECASE,
                )
            ]
            images = [
                urljoin(MOOC2_BASE_URL, unescape(src))
                for src in re.findall(
                    r"<img\b[^>]*src=['\"]([^'\"]+)['\"]",
                    stem_html,
                    flags=re.IGNORECASE,
                )
            ]
            question = {
                "index": len(questions) + 1,
                "number": question_number,
                "section_id": str(stem_attrs.get("id") or "").removeprefix("section"),
                "question_type": _exam_question_type(type_label),
                "question_type_label": type_label,
                "score": score,
                "stem_html": stem_html,
                "stem": html_text(stem_html),
                "images": images,
                "options": options,
                "answer_html": answer_html,
                "answer": html_text(answer_html),
                "fill_answers": fill_answers,
                "matching_columns": _exam_matching_columns(question_html),
                "matching_pairs": matching_pairs,
                "analysis_html": analysis_html,
                "analysis": analysis,
                "difficulty": difficulty,
                "difficulty_label": difficulty_text,
                "difficulty_html": difficulty_html,
                "topics": topics,
                "group_index": group_number,
            }
            questions.append(question)
            group_questions.append(question)

        groups.append(
            {
                "index": group_number,
                "title": html_text(heading_match.group(1)) if heading_match else "",
                "instructions": (
                    re.sub(r"^\s*题型说明\s*[:：]\s*", "", html_text(instruction_match.group(1)))
                    if instruction_match
                    else ""
                ),
                "question_count": len(group_questions),
                "question_indexes": [question["index"] for question in group_questions],
            }
        )

    computed_score = sum(
        float(question["score"])
        for question in questions
        if isinstance(question.get("score"), (int, float))
    )
    if isinstance(computed_score, float) and computed_score.is_integer():
        computed_score = int(computed_score)
    return {
        "paper_id": str(paper_id),
        "title": title,
        "declared_question_count": declared_question_count,
        "declared_total_score": declared_total_score,
        "question_count": len(questions),
        "computed_total_score": computed_score,
        "group_count": len(groups),
        "groups": groups,
        "questions": questions,
    }


def resolve_exam_paper_question(questions: list[dict[str, Any]], query: str) -> dict[str, Any]:
    normalized = query.strip().lower()
    if not normalized:
        raise ChaoxingAPIError("exam-paper question index, section ID, or stem is required")
    for key in ("index", "number", "section_id"):
        exact = [
            question
            for question in questions
            if str(question.get(key) or "").strip().lower() == normalized
        ]
        if len(exact) == 1:
            return exact[0]
    exact_stems = [
        question
        for question in questions
        if str(question.get("stem") or "").strip().lower() == normalized
    ]
    if len(exact_stems) == 1:
        return exact_stems[0]
    partial = [
        question
        for question in questions
        if normalized in str(question.get("stem") or "").strip().lower()
    ]
    if len(partial) == 1:
        return partial[0]
    if not partial:
        raise ChaoxingAPIError(f"exam-paper question not found: {query}")
    labels = ", ".join(
        f"{question.get('index')}. {str(question.get('stem') or '')[:80]}"
        f" ({question.get('section_id')})"
        for question in partial[:10]
    )
    raise ChaoxingAPIError(f"multiple exam-paper questions match: {labels}")


def parse_exam_submission_payload(payload: dict[str, Any]) -> list[dict[str, Any]]:
    raw_rows = payload.get("data")
    if not isinstance(raw_rows, list):
        return []
    rows: list[dict[str, Any]] = []
    for raw in raw_rows:
        if not isinstance(raw, dict):
            continue
        answer_id = str(raw.get("id") or "").strip()
        student_name = str(raw.get("createUserName") or "").strip()
        student_no = str(raw.get("loginName") or "").strip()
        if not answer_id and not student_name and not student_no:
            continue
        review_path = str(raw.get("markUrl") or "").strip()
        rows.append(
            {
                "answer_id": answer_id,
                "person_id": str(raw.get("createUserId") or ""),
                "student_name": student_name,
                "student_no": student_no,
                "score": raw.get("answerScore"),
                "right_rate": str(raw.get("rightRate") or ""),
                "received_at": str(raw.get("receiveTime") or ""),
                "submitted_at": str(raw.get("submitTime") or ""),
                "reviewed_at": str(raw.get("piyueTime") or ""),
                "reviewer_name": str(raw.get("piyueUserName") or ""),
                "duration": str(raw.get("examConsumeTime") or ""),
                "submit_location": str(raw.get("submitStyle") or ""),
                "status_code": raw.get("status"),
                "status_label": str(raw.get("mark") or ""),
                "evaluation_status": raw.get("evaluation"),
                "can_teacher_review": bool(raw.get("tchPiYueExam")),
                "review_url": urljoin(MOOC2_BASE_URL, review_path) if review_path else "",
            }
        )
    return rows


def resolve_exam_submission(rows: list[dict[str, Any]], query: str) -> dict[str, Any]:
    normalized = query.strip().lower()
    if not normalized:
        raise ChaoxingAPIError(
            "exam submission index, answer_id, student name, or number is required"
        )
    for key in ("answer_id", "index", "student_no", "person_id"):
        exact = [row for row in rows if str(row.get(key, "")).strip().lower() == normalized]
        if len(exact) == 1:
            return exact[0]
    exact_names = [
        row for row in rows if str(row.get("student_name", "")).strip().lower() == normalized
    ]
    if len(exact_names) == 1:
        return exact_names[0]
    partial = [
        row for row in rows if normalized in str(row.get("student_name", "")).strip().lower()
    ]
    if len(partial) == 1:
        return partial[0]
    if not partial:
        raise ChaoxingAPIError(f"exam submission not found: {query}")
    candidates = ", ".join(
        f"{row.get('index')}. {row.get('student_name')} ({row.get('student_no')})"
        for row in partial
    )
    raise ChaoxingAPIError(f"multiple exam submission matches: {candidates}")


def parse_content_images(fragment: str) -> list[str]:
    return [
        urljoin(MOOC2_BASE_URL, unescape(src))
        for src in re.findall(
            r"<img\b[^>]*src=['\"]([^'\"]+)['\"]",
            fragment,
            flags=re.IGNORECASE,
        )
        if is_answer_image_url(src)
    ]


def input_attrs_by_id(fragment: str, input_id: str) -> dict[str, str]:
    match = re.search(
        rf"<input\b[^>]*\bid=['\"]{re.escape(input_id)}['\"][^>]*>",
        fragment,
        flags=re.IGNORECASE | re.DOTALL,
    )
    return html_attrs(match.group(0)) if match else {}


def parse_exam_answer_sheet(html: str) -> dict[str, Any]:
    hidden = parse_hidden_inputs(html)
    wrappers = list(
        re.finditer(
            r"<div\b[^>]*class=['\"][^'\"]*\bquestionWrap\b[^'\"]*['\"][^>]*>",
            html,
            flags=re.IGNORECASE | re.DOTALL,
        )
    )
    questions: list[dict[str, Any]] = []
    for position, wrapper in enumerate(wrappers):
        end = wrappers[position + 1].start() if position + 1 < len(wrappers) else len(html)
        fragment = html[wrapper.start() : end]
        wrapper_attrs = html_attrs(wrapper.group(0))
        question_input = re.search(
            r"<input\b[^>]*\bid=['\"]input(\d+)['\"][^>]*>",
            fragment,
            flags=re.IGNORECASE | re.DOTALL,
        )
        if not question_input:
            continue
        question_id = question_input.group(1)
        question_input_attrs = html_attrs(question_input.group(0))

        score_match = re.search(
            rf"<input\b[^>]*\bname=['\"]score{re.escape(question_id)}['\"][^>]*>",
            fragment,
            flags=re.IGNORECASE | re.DOTALL,
        )
        score_attrs = html_attrs(score_match.group(0)) if score_match else {}
        full_score_attrs = input_attrs_by_id(fragment, "fullScore" + question_id)
        record_attrs = input_attrs_by_id(fragment, "recordid" + question_id)
        type_attrs = input_attrs_by_id(fragment, "type" + question_id)
        relation_attrs = input_attrs_by_id(fragment, "relationid" + question_id)

        bbs_match = re.search(
            rf"<div\b[^>]*\bid=['\"]bbsStem_{re.escape(question_id)}['\"][^>]*>",
            fragment,
            flags=re.IGNORECASE | re.DOTALL,
        )
        bbs_attrs = html_attrs(bbs_match.group(0)) if bbs_match else {}
        stem_html = bbs_attrs.get("content", "")
        student_answer_html = bbs_attrs.get("answer", "")
        correct_answer_html = bbs_attrs.get("rightanwer", "") or bbs_attrs.get("rightanswer", "")

        if not stem_html:
            stem_match = re.search(
                r"<h3\b[^>]*class=['\"][^'\"]*\bmark_name\b[^'\"]*['\"][^>]*>"
                r"([\s\S]*?)</h3>",
                fragment,
                flags=re.IGNORECASE,
            )
            stem_html = stem_match.group(1) if stem_match else ""
            stem_html = re.sub(r"^\s*\d+\s*[.、]\s*", "", stem_html, count=1)
            stem_html = re.sub(
                r"<span\b[^>]*class=['\"][^'\"]*\bcolorShallow\b[^'\"]*['\"][^>]*>"
                r"[\s\S]*?</span>",
                "",
                stem_html,
                count=1,
                flags=re.IGNORECASE,
            )

        if not student_answer_html:
            answer_match = re.search(
                r"学生答案\s*[:：]?\s*</i>([\s\S]*?)</span>",
                fragment,
                flags=re.IGNORECASE,
            )
            student_answer_html = answer_match.group(1) if answer_match else ""
        if not correct_answer_html:
            correct_match = re.search(
                r"正确答案\s*[:：]?\s*</i>([\s\S]*?)</span>",
                fragment,
                flags=re.IGNORECASE,
            )
            correct_answer_html = correct_match.group(1) if correct_match else ""

        options: list[dict[str, str]] = []
        options_match = re.search(
            r"<ul\b[^>]*class=['\"][^'\"]*\bmark_letter\b[^'\"]*['\"][^>]*>"
            r"([\s\S]*?)</ul>",
            fragment,
            flags=re.IGNORECASE,
        )
        if options_match:
            for option_fragment in re.findall(
                r"<li\b[^>]*>([\s\S]*?)</li>",
                options_match.group(1),
                flags=re.IGNORECASE,
            ):
                option_text = html_text(option_fragment)
                label_match = re.match(r"([A-Za-z])\s*[.、]\s*(.*)", option_text)
                options.append(
                    {
                        "label": label_match.group(1) if label_match else "",
                        "text": label_match.group(2) if label_match else option_text,
                    }
                )

        analysis_match = re.search(
            r"<div\b[^>]*class=['\"][^'\"]*\bAnalysisCon\b[^'\"]*['\"][^>]*>"
            r"([\s\S]*?)</div>",
            fragment,
            flags=re.IGNORECASE,
        )
        analysis_html = analysis_match.group(1) if analysis_match else ""
        questions.append(
            {
                "index": int(wrapper_attrs.get("index") or position + 1),
                "question_id": question_id,
                "record_id": record_attrs.get("value", ""),
                "relation_id": relation_attrs.get("value", ""),
                "question_type": wrapper_attrs.get("name", ""),
                "question_type_code": type_attrs.get("value", ""),
                "full_score": full_score_attrs.get("value")
                or question_input_attrs.get("value", ""),
                "score": score_attrs.get("value", ""),
                "grading_status": score_attrs.get("markstatus", ""),
                "score_readonly": bool(
                    score_match
                    and re.search(r"\breadonly(?:\s*=|\s|>)", score_match.group(0), re.I)
                ),
                "stem": html_text(stem_html),
                "stem_html": stem_html,
                "stem_images": parse_content_images(stem_html),
                "stem_attachments": parse_attachment_iframes(stem_html),
                "options": options,
                "student_answer": html_text(student_answer_html),
                "student_answer_html": student_answer_html,
                "student_answer_images": parse_content_images(student_answer_html),
                "student_answer_attachments": parse_attachment_iframes(student_answer_html),
                "correct_answer": html_text(correct_answer_html),
                "correct_answer_html": correct_answer_html,
                "answer_analysis": html_text(analysis_html),
            }
        )

    return {
        "answer_id": hidden.get("answerId") or hidden.get("testUserRelationId", ""),
        "student_name": hidden.get("stuRealName", ""),
        "exam_title": hidden.get("_title", ""),
        "status_code": hidden.get("status", ""),
        "exam_full_score": hidden.get("examFullScore", ""),
        "exam_id": hidden.get("testPaperId", ""),
        "paper_id": hidden.get("paperId", ""),
        "course_id": hidden.get("courseId", ""),
        "clazz_id": hidden.get("classId", ""),
        "question_count": len(questions),
        "questions": questions,
    }


def parse_question_bank_items(
    html: str,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    directories: list[dict[str, Any]] = []
    questions: list[dict[str, Any]] = []
    item_starts = list(
        re.finditer(
            r"<li\b[^>]*\bdata-type=['\"](?:folder|que)['\"][^>]*>",
            html,
            flags=re.IGNORECASE | re.DOTALL,
        )
    )
    for position, match in enumerate(item_starts):
        end = item_starts[position + 1].start() if position + 1 < len(item_starts) else len(html)
        attrs = html_attrs(match.group(0))
        item_type = attrs.get("data-type", "")
        body = html[match.end() : end]
        if item_type == "folder":
            name_match = re.search(
                r"<span\b[^>]*class=['\"][^'\"]*dirname[^'\"]*['\"][^>]*>"
                r"(.*?)</span>",
                body,
                flags=re.IGNORECASE | re.DOTALL,
            )
            count_match = re.search(r"共\s*(\d+)\s*题", html_text(body))
            creator_match = re.search(
                r"<span\b[^>]*class=['\"][^'\"]*auth-name[^'\"]*['\"][^>]*>"
                r"(.*?)</span>",
                body,
                flags=re.IGNORECASE | re.DOTALL,
            )
            scope_match = re.search(
                r"<span\b[^>]*class=['\"][^'\"]*tips[^'\"]*['\"][^>]*>"
                r"(.*?)</span>",
                body,
                flags=re.IGNORECASE | re.DOTALL,
            )
            if attrs.get("id") and name_match:
                directories.append(
                    {
                        "directory_id": attrs["id"],
                        "course_id": attrs.get("courseid", ""),
                        "name": html_text(name_match.group(1)),
                        "question_count": int(count_match.group(1)) if count_match else None,
                        "creator_name": (
                            html_text(creator_match.group(1)) if creator_match else ""
                        ),
                        "creator_id": attrs.get("createrid", ""),
                        "scope": html_text(scope_match.group(1)) if scope_match else "",
                        "share_state": attrs.get("isshare", ""),
                    }
                )
            continue
        if item_type != "que":
            continue

        stem_tag = re.search(
            r"<span\b[^>]*class=['\"][^'\"]*choose-name[^'\"]*['\"][^>]*>",
            body,
            flags=re.IGNORECASE | re.DOTALL,
        )
        stem_attrs = html_attrs(stem_tag.group(0)) if stem_tag else {}
        type_tag = re.search(
            r"<span\b[^>]*class=['\"][^'\"]*overHidden1[^'\"]*['\"][^>]*>",
            body,
            flags=re.IGNORECASE | re.DOTALL,
        )
        type_attrs = html_attrs(type_tag.group(0)) if type_tag else {}

        details_tag = re.search(
            r"<div\b[^>]*class=['\"][^'\"]*\bquestions-details\b[^'\"]*['\"][^>]*>",
            body,
            flags=re.IGNORECASE | re.DOTALL,
        )
        details_fragment = ""
        if details_tag:
            titles_start = re.search(
                r"<ul\b[^>]*class=['\"][^'\"]*\bquestion-titles\b",
                body[details_tag.end() :],
                flags=re.IGNORECASE,
            )
            details_end = details_tag.end() + titles_start.start() if titles_start else len(body)
            details_fragment = body[details_tag.end() : details_end]

        answer_marker = re.search(
            r"<div\b[^>]*class=['\"][^'\"]*\bquestion\b[^'\"]*\bclearfix\b"
            r"[^'\"]*['\"][^>]*>",
            details_fragment,
            flags=re.IGNORECASE | re.DOTALL,
        )
        pre_answer = (
            details_fragment[: answer_marker.start()] if answer_marker else details_fragment
        )
        option_match = re.search(
            r"<ul\b[^>]*class=['\"][^'\"]*\boption\b[^'\"]*['\"][^>]*>"
            r"([\s\S]*?)</ul>",
            pre_answer,
            flags=re.IGNORECASE,
        )
        options: list[dict[str, str]] = []
        if option_match:
            for option_html in re.findall(
                r"<li\b[^>]*>([\s\S]*?)</li>",
                option_match.group(1),
                flags=re.IGNORECASE,
            ):
                option_text = html_text(option_html)
                label_match = re.match(r"([A-Za-z])\s*[.、]\s*(.*)", option_text)
                options.append(
                    {
                        "label": label_match.group(1) if label_match else "",
                        "text": label_match.group(2) if label_match else option_text,
                        "html": option_html,
                    }
                )
        stem_html = (
            pre_answer[: option_match.start()] + pre_answer[option_match.end() :]
            if option_match
            else pre_answer
        )
        answer_html = ""
        if answer_marker:
            answer_tail = details_fragment[answer_marker.end() :]
            answer_box = re.search(
                r"<div\b[^>]*class=['\"][^'\"]*\bquestion-box\b[^'\"]*['\"][^>]*>",
                answer_tail,
                flags=re.IGNORECASE | re.DOTALL,
            )
            if answer_box:
                answer_html = answer_tail[answer_box.end() :]
                answer_html = re.sub(r"(?:\s*</div>){2,}\s*$", "", answer_html, flags=re.IGNORECASE)

        def span_text(class_name: str, fragment: str = body) -> str:
            found = re.search(
                rf"<span\b[^>]*class=['\"][^'\"]*{class_name}[^'\"]*['\"][^>]*>"
                r"(.*?)</span>",
                fragment,
                flags=re.IGNORECASE | re.DOTALL,
            )
            return html_text(found.group(1)) if found else ""

        stem = stem_attrs.get("title", "").strip() or html_text(stem_html)
        if not stem:
            stem = span_text("choose-name")
        questions.append(
            {
                "question_id": attrs.get("id", ""),
                "index": int(attrs["index"]) + 1 if attrs.get("index", "").isdigit() else None,
                "course_id": attrs.get("courseid", ""),
                "origin_type": attrs.get("origintype", ""),
                "course_question_type_id": attrs.get("coursequestionyypeid", ""),
                "is_map_course": attrs.get("ismapcourse", "").lower() == "true",
                "topic_id": attrs.get("topicid", ""),
                "question_type": type_attrs.get("title", "") or span_text("overHidden1"),
                "stem": stem,
                "stem_html": stem_html,
                "options": options,
                "answer": html_text(answer_html),
                "answer_html": answer_html,
                "difficulty": span_text("hard"),
                "usage_count": span_text("dose"),
                "accuracy": span_text("accuracy"),
                "creator_name": span_text("auth-name"),
                "images": [
                    urljoin(MOOC2_BASE_URL, unescape(src))
                    for src in re.findall(
                        r"<img\b[^>]*src=['\"]([^'\"]+)['\"]",
                        body,
                        flags=re.IGNORECASE,
                    )
                    if is_answer_image_url(src)
                ],
                "answer_images": parse_content_images(answer_html),
                "attachments": parse_attachment_iframes(body),
                "answer_attachments": parse_attachment_iframes(answer_html),
            }
        )
    return directories, questions


def parse_question_bank_directory_tree(payload: dict[str, Any]) -> list[dict[str, Any]]:
    directory_map = payload.get("directorysMap")
    if not isinstance(directory_map, dict):
        raise ChaoxingAPIError("question-bank directory response exposed no directory map")
    directories: list[dict[str, Any]] = []
    for raw_items in directory_map.values():
        if not isinstance(raw_items, list):
            continue
        for raw in raw_items:
            if not isinstance(raw, dict):
                continue
            directory_id = str(raw.get("id") or "").strip()
            if not directory_id:
                continue
            directories.append(
                {
                    "index": len(directories) + 1,
                    "directory_id": directory_id,
                    "parent_id": str(raw.get("pid") or "0"),
                    "course_id": str(raw.get("courseId") or ""),
                    "name": html_text(str(raw.get("dirName") or "")),
                    "question_count": _numeric_or_text(
                        str(raw.get("questionCount", raw.get("questionNum", "")))
                    ),
                    "exam_count": _numeric_or_text(str(raw.get("examNum", ""))),
                    "is_open": str(raw.get("isOpen") or "0"),
                    "share_state": str(raw.get("isShare") or "0"),
                    "is_top": str(raw.get("top") or "0") == "1",
                    "person_id": str(raw.get("personId") or ""),
                    "user_id": str(raw.get("userId") or ""),
                    "created_at": raw.get("createTime"),
                    "updated_at": raw.get("lastUpdateTime"),
                }
            )

    by_id = {item["directory_id"]: item for item in directories}
    for item in directories:
        names = [item["name"]]
        parent_id = item["parent_id"]
        visited = {item["directory_id"]}
        while parent_id != "0" and parent_id in by_id and parent_id not in visited:
            visited.add(parent_id)
            parent = by_id[parent_id]
            names.append(parent["name"])
            parent_id = parent["parent_id"]
        item["path"] = " / ".join(reversed([name for name in names if name]))
        item["child_count"] = sum(
            1 for candidate in directories if candidate["parent_id"] == item["directory_id"]
        )
    return directories


def parse_question_bank_permission_teachers(html: str) -> list[dict[str, str | int]]:
    teacher_list = re.search(
        r"<div\b[^>]*\bid=['\"]teacherList['\"][^>]*>(.*?)</div>",
        html,
        flags=re.IGNORECASE | re.DOTALL,
    )
    if not teacher_list:
        return []
    teachers: list[dict[str, str | int]] = []
    pattern = re.compile(
        r"<span\b(?=[^>]*\bclass=['\"][^'\"]*\bipt-checkbox\b[^'\"]*['\"]"
        r")(?=[^>]*\bdata=['\"]([^'\"]+)['\"])[^>]*>.*?</span>\s*"
        r"<span\b[^>]*\bclass=['\"][^'\"]*\bipt-txt\b[^'\"]*['\"][^>]*>"
        r"(.*?)</span>",
        flags=re.IGNORECASE | re.DOTALL,
    )
    for person_id, name_html in pattern.findall(teacher_list.group(1)):
        normalized_id = str(person_id).strip()
        if not normalized_id:
            continue
        teachers.append(
            {
                "index": len(teachers) + 1,
                "person_id": normalized_id,
                "teacher_name": html_text(name_html),
            }
        )
    return teachers


def parse_question_bank_question_types(html: str) -> list[dict[str, Any]]:
    question_types: list[dict[str, Any]] = []
    for match in re.finditer(r"<li\b[^>]*>.*?</li>", html, flags=re.IGNORECASE | re.DOTALL):
        block = match.group(0)
        opening = re.match(r"<li\b[^>]*>", block, flags=re.IGNORECASE | re.DOTALL)
        if not opening:
            continue
        attrs = html_attrs(opening.group(0))
        if "courseqtype" not in attrs.get("class", "").lower().split():
            continue
        type_id = str(attrs.get("typeid") or "").strip()
        if not type_id:
            continue
        name_match = re.search(
            r"<p\b[^>]*\bclass=['\"][^'\"]*\boverHidden1\b[^'\"]*['\"][^>]*>"
            r"(.*?)</p>",
            block,
            flags=re.IGNORECASE | re.DOTALL,
        )
        origin_type = str(attrs.get("origintype") or "").strip()
        base = QUESTION_BANK_CREATABLE_BASE_TYPES.get(origin_type, {})
        sort_raw = str(attrs.get("sort") or "").strip()
        question_types.append(
            {
                "index": len(question_types) + 1,
                "type_id": type_id,
                "name": html_text(name_match.group(1)) if name_match else "",
                "origin_type": origin_type,
                "base_type": base.get("key", f"origin_type_{origin_type}"),
                "base_type_label": base.get("label", ""),
                "system_type": str(attrs.get("systemtype") or ""),
                "sort": _numeric_or_text(sort_raw),
                "can_rename": "resetName" in block,
                "can_delete": "deleteType" in block,
            }
        )
    return question_types


def resolve_question_bank_question_type(
    question_types: list[dict[str, Any]], query: str
) -> dict[str, Any]:
    normalized = str(query or "").strip().lower()
    if not normalized:
        raise ChaoxingAPIError("question-bank question-type index, ID, or name is required")
    for key in ("type_id", "index"):
        matches = [
            item
            for item in question_types
            if str(item.get(key) or "").strip().lower() == normalized
        ]
        if len(matches) == 1:
            return matches[0]
    exact = [
        item for item in question_types if str(item.get("name") or "").strip().lower() == normalized
    ]
    if len(exact) == 1:
        return exact[0]
    partial = [
        item for item in question_types if normalized in str(item.get("name") or "").strip().lower()
    ]
    if len(partial) == 1:
        return partial[0]
    candidates = exact or partial
    if not candidates:
        raise ChaoxingAPIError(f"question-bank question type not found: {query}")
    labels = ", ".join(
        f"{item.get('index')}. {item.get('name')} ({item.get('type_id')})"
        for item in candidates[:10]
    )
    raise ChaoxingAPIError(f"multiple question-bank question types match: {labels}")


def parse_question_bank_label_tree(payload: dict[str, Any]) -> list[dict[str, Any]]:
    raw_roots = payload.get("data")
    if not isinstance(raw_roots, list):
        raise ChaoxingAPIError("question-bank label response exposed no label tree")
    labels: list[dict[str, Any]] = []

    def visit(raw: Any, parent_path: str, level: int) -> None:
        if not isinstance(raw, dict):
            return
        label_id = str(raw.get("id") or "").strip()
        if not label_id:
            return
        name = str(raw.get("name") or "").strip()
        path = f"{parent_path} / {name}" if parent_path and name else name or parent_path
        children = raw.get("children") if isinstance(raw.get("children"), list) else []
        labels.append(
            {
                "index": len(labels) + 1,
                "label_id": label_id,
                "parent_id": str(raw.get("parentId") or "0"),
                "name": name,
                "path": path,
                "level": level,
                "sort_index": _numeric_or_text(str(raw.get("index") or "")),
                "child_count": len(children),
            }
        )
        for child in children:
            visit(child, path, level + 1)

    for root in raw_roots:
        visit(root, "", 1)
    return labels


def resolve_question_bank_label(
    labels: list[dict[str, Any]], query: str, *, allow_root: bool = False
) -> dict[str, Any]:
    normalized = str(query or "").strip().lower()
    if allow_root and normalized in {"0", "root", "根", "根标签", "标签根目录"}:
        return {
            "index": 0,
            "label_id": "0",
            "parent_id": "",
            "name": "标签根目录",
            "path": "标签根目录",
            "level": 0,
        }
    if not normalized:
        raise ChaoxingAPIError("question-bank label index, ID, name, or path is required")
    for key in ("label_id", "index"):
        matches = [
            item for item in labels if str(item.get(key) or "").strip().lower() == normalized
        ]
        if len(matches) == 1:
            return matches[0]
    exact = [
        item
        for item in labels
        if normalized
        in {
            str(item.get("name") or "").strip().lower(),
            str(item.get("path") or "").strip().lower(),
        }
    ]
    if len(exact) == 1:
        return exact[0]
    partial = [item for item in labels if normalized in str(item.get("path") or "").strip().lower()]
    if len(partial) == 1:
        return partial[0]
    candidates = exact or partial
    if not candidates:
        raise ChaoxingAPIError(f"question-bank label not found: {query}")
    labels_text = ", ".join(
        f"{item.get('index')}. {item.get('path')} ({item.get('label_id')})"
        for item in candidates[:10]
    )
    raise ChaoxingAPIError(f"multiple question-bank labels match: {labels_text}")


def parse_question_bank_topic_tree(
    payload: dict[str, Any],
) -> tuple[list[dict[str, Any]], list[str]]:
    data = payload.get("data")
    if not isinstance(data, dict) or not isinstance(data.get("list"), list):
        raise ChaoxingAPIError("question-bank topic response exposed no topic tree")

    selected_ids: list[str] = []
    raw_selected = data.get("selects")
    if isinstance(raw_selected, list):
        for raw in raw_selected:
            value = raw.get("id") if isinstance(raw, dict) else raw
            topic_id = str(value if value is not None else "").strip()
            if topic_id and topic_id not in selected_ids:
                selected_ids.append(topic_id)

    topics: list[dict[str, Any]] = []

    def visit(raw: Any, parent_path: str, level: int) -> None:
        if not isinstance(raw, dict):
            return
        topic_id = str(raw.get("id") if raw.get("id") is not None else "").strip()
        if not topic_id:
            return
        name = str(raw.get("content") or "").strip()
        path = f"{parent_path} / {name}" if parent_path and name else name or parent_path
        raw_children = raw.get("subList")
        children = raw_children if isinstance(raw_children, list) else []
        node_type = str(raw.get("type") if raw.get("type") is not None else "").strip()
        kind = "category" if node_type == "1" else "knowledge_point" if node_type == "0" else ""
        selected = bool(raw.get("select")) or topic_id in selected_ids
        if selected and topic_id not in selected_ids:
            selected_ids.append(topic_id)
        topics.append(
            {
                "index": len(topics) + 1,
                "topic_id": topic_id,
                "parent_id": str(
                    raw.get("parent") if raw.get("parent") is not None else "0"
                ).strip(),
                "name": name,
                "path": path,
                "level": level,
                "server_level": _numeric_or_text(str(raw.get("level") or "")),
                "node_type": node_type,
                "kind": kind,
                "selected": selected,
                "has_children": bool(children) or bool(raw.get("hasSub")),
                "child_count": len(children),
                "enc": str(raw.get("enc") or ""),
                "education_topic_id": str(raw.get("eduTopicId") or ""),
            }
        )
        for child in children:
            visit(child, path, level + 1)

    for root in data["list"]:
        visit(root, "", 1)
    return topics, selected_ids


def resolve_question_bank_topic(
    topics: list[dict[str, Any]], query: str, *, allow_root: bool = False
) -> dict[str, Any]:
    normalized = str(query or "").strip().lower()
    if allow_root and normalized in {"0", "root", "根", "根节点", "知识点根目录"}:
        return {
            "index": 0,
            "topic_id": "0",
            "parent_id": "",
            "name": "知识点根目录",
            "path": "知识点根目录",
            "level": 0,
            "node_type": "1",
            "kind": "category",
        }
    if not normalized:
        raise ChaoxingAPIError("question-bank topic index, ID, name, or path is required")
    for key in ("topic_id", "index"):
        matches = [
            item for item in topics if str(item.get(key) or "").strip().lower() == normalized
        ]
        if len(matches) == 1:
            return matches[0]
    exact = [
        item
        for item in topics
        if normalized
        in {
            str(item.get("name") or "").strip().lower(),
            str(item.get("path") or "").strip().lower(),
        }
    ]
    if len(exact) == 1:
        return exact[0]
    partial = [item for item in topics if normalized in str(item.get("path") or "").strip().lower()]
    if len(partial) == 1:
        return partial[0]
    candidates = exact or partial
    if not candidates:
        raise ChaoxingAPIError(f"question-bank topic not found: {query}")
    topics_text = ", ".join(
        f"{item.get('index')}. {item.get('path')} ({item.get('topic_id')})"
        for item in candidates[:10]
    )
    raise ChaoxingAPIError(f"multiple question-bank topics match: {topics_text}")


def parse_question_bank_inactive_items(
    payload: dict[str, Any],
    *,
    state: str,
    index_offset: int = 0,
) -> dict[str, Any]:
    raw_items = payload.get("list")
    if not isinstance(raw_items, list):
        raise ChaoxingAPIError("question-bank inactive-item response exposed no item list")
    items: list[dict[str, Any]] = []
    difficulty_labels = {"0": "易", "1": "中", "2": "难"}
    for raw in raw_items:
        if not isinstance(raw, dict):
            continue
        raw_type = str(raw.get("type") if raw.get("type") is not None else "").strip()
        item_type = "directory" if raw_type == "0" else "question"
        nested_key = "questionBankRelation" if item_type == "directory" else "questionBank"
        nested = raw.get(nested_key)
        if not isinstance(nested, dict):
            continue
        item_id = str(nested.get("id") if nested.get("id") is not None else "").strip()
        if not item_id:
            continue
        if item_type == "directory":
            name = str(nested.get("dirName") or "").strip()
            content_html = ""
        else:
            content_html = str(nested.get("content") or "")
            name = html_text(content_html)
        easy_code = str(nested.get("easy") if nested.get("easy") is not None else "").strip()
        items.append(
            {
                "index": index_offset + len(items) + 1,
                "recycle_id": str(raw.get("id") or ""),
                "item_id": item_id,
                "item_type": item_type,
                "state": state,
                "name": name,
                "content_html": content_html,
                "parent_id": str(
                    nested.get("pid") or nested.get("parentId") or nested.get("dirId") or "0"
                ),
                "course_id": str(nested.get("courseId") or nested.get("courseid") or ""),
                "question_type": str(nested.get("courseQuestionTypeName") or ""),
                "origin_type": str(
                    nested.get("originType") if nested.get("originType") is not None else ""
                ),
                "difficulty_code": easy_code,
                "difficulty": difficulty_labels.get(easy_code, ""),
                "creator_name": str(raw.get("createrName") or ""),
                "created_at": raw.get("createTime"),
                "locked_at": raw.get("lockTime"),
            }
        )
    path_items: list[dict[str, str]] = []
    raw_path = payload.get("dirPathList")
    if isinstance(raw_path, list):
        for raw in raw_path:
            if isinstance(raw, dict):
                path_items.append(
                    {
                        "directory_id": str(raw.get("id") or ""),
                        "name": str(raw.get("dirName") or ""),
                    }
                )
    page_info = payload.get("pageInfo") if isinstance(payload.get("pageInfo"), dict) else {}
    return {
        "items": items,
        "path": path_items,
        "reported_total": _numeric_or_text(str(payload.get("total") or "0")),
        "page_info": page_info,
    }


QUESTION_BANK_SMART_IMPORT_TYPES: dict[str, tuple[int, str]] = {
    "QuestionChoice": (0, "单选题"),
    "MultiChoice": (1, "多选题"),
    "QuestionGapFilling": (2, "填空题"),
    "QuestionYesNo": (3, "判断题"),
    "QuestionCommon": (4, "简答题"),
    "QuestionClozeTest": (14, "完型填空"),
    "QuestionComposite": (15, "阅读理解"),
    "QuestionSameChoose": (20, "共用选项题"),
    "QuestionChooseWordGapFilling": (24, "选词填空"),
    "QuestionWriting": (26, "写作题"),
}


def parse_question_bank_smart_import_context(html: str) -> dict[str, Any]:
    hidden = parse_hidden_inputs(html)

    def hidden_int(name: str) -> int:
        try:
            return int(str(hidden.get(name) or "0"))
        except ValueError:
            return 0

    base_url = str(hidden.get("moocImportExportUrl") or "").strip().rstrip("/")
    parsed = urlparse(base_url)
    hostname = (parsed.hostname or "").lower()
    if parsed.scheme != "https" or not (
        hostname == "chaoxing.com" or hostname.endswith(".chaoxing.com")
    ):
        raise ChaoxingAPIError("question-bank smart-import page exposed no trusted import host")
    import_enc = str(hidden.get("importQuestionEnc") or "").strip()
    if not import_enc:
        raise ChaoxingAPIError("question-bank smart-import page exposed no import token")
    return {
        "import_base_url": base_url,
        "import_endpoint": base_url + "/import/import-question",
        "import_token": import_enc,
        "paper_library_id": str(hidden.get("paperLibraryId") or ""),
        "work_library_id": str(hidden.get("workLibraryId") or ""),
        "micro_topic_id": str(hidden.get("microTopicId") or ""),
        "group_id": str(hidden.get("groupId") or "0"),
        "initial_status": str(hidden.get("initStatus") or ""),
        "need_question_ids": str(hidden.get("pMessage") or "").lower() == "true",
        "course_question_count": hidden_int("courseQueNum"),
        "course_question_limit": hidden_int("queNumMaxSize"),
        "allow_import_topics": str(hidden.get("allowImportTopic") or "").lower() == "true",
    }


def _question_bank_writing_subject(question: dict[str, Any]) -> int | None:
    raw_subject = question.get("subject")
    if raw_subject is not None and str(raw_subject).strip() != "":
        try:
            subject = int(raw_subject)
        except (TypeError, ValueError):
            subject = -1
        if subject in {0, 1, 2, 3}:
            return subject
    text = str(question.get("content") or question.get("writingLanguage") or "")
    patterns = (
        (1, r"中文写作|汉语写作|chinese\s*writing"),
        (2, r"西班牙语写作|西语写作|spanish\s*writing"),
        (3, r"法语写作|法文写作|french\s*writing"),
        (0, r"英文写作|英语写作|english\s*writing"),
    )
    for subject, pattern in patterns:
        if re.search(pattern, text, re.IGNORECASE):
            return subject
    return None


def _question_bank_smart_import_question(question: dict[str, Any]) -> dict[str, Any] | None:
    source_type = str(question.get("type") or "").strip()
    if not source_type or source_type == "Paragraph":
        return None
    type_definition = QUESTION_BANK_SMART_IMPORT_TYPES.get(source_type)
    if type_definition is None:
        raise ChaoxingAPIError(f"unsupported smart-import question type: {source_type}")
    numeric_type, default_name = type_definition
    result: dict[str, Any] = {}
    for source_key, target_key in (
        ("content", "content"),
        ("answerKey", "analysis"),
        ("knowledge", "knowledge"),
        ("label", "label"),
        ("target", "target"),
        ("score", "score"),
    ):
        value = question.get(source_key)
        if value not in (None, "", [], {}):
            result[target_key] = value
    if question.get("difficulty") not in (None, ""):
        result["difficulty"] = question["difficulty"]
        if question.get("easy") not in (None, ""):
            result["easy"] = question["easy"]
    alias = str(question.get("typeAlias") or default_name).strip() or default_name
    result.update({"name": default_name, "typeAlias": alias})

    child_questions = question.get("questions")
    if isinstance(child_questions, list):
        children: list[dict[str, Any]] = []
        for child in child_questions:
            if not isinstance(child, dict):
                continue
            normalized_child = _question_bank_smart_import_question(child)
            if normalized_child is None:
                continue
            child_name = str(normalized_child.pop("name", ""))
            child_type = normalized_child.pop("type", None)
            children.append(
                {
                    "id": uuid4().hex,
                    "name": child_name,
                    "type": child_type,
                    "data": normalized_child,
                }
            )
        result["answer"] = children

    if source_type in {"QuestionChoice", "MultiChoice"}:
        correct = {str(item).strip().upper() for item in question.get("answer") or []}
        answers: list[dict[str, Any]] = []
        for index, option in enumerate(question.get("options") or []):
            if not isinstance(option, dict):
                continue
            name = str(option.get("name") or chr(ord("A") + index)).strip().upper()
            item: dict[str, Any] = {
                "content": str(option.get("value") or option.get("content") or ""),
                "name": name,
            }
            if name in correct or option.get("isRightAnswer") is True:
                item["isanswer"] = True
            answers.append(item)
        result.update(
            {
                "type": 1 if source_type == "MultiChoice" else 0,
                "name": "多选题" if source_type == "MultiChoice" else "单选题",
                "answer": answers,
            }
        )
        if not question.get("typeAlias"):
            result["typeAlias"] = result["name"]
        return result

    if source_type == "QuestionGapFilling":
        answers = [
            {"content": str(value), "name": str(index)}
            for index, value in enumerate(question.get("answer") or [], 1)
        ]
        if question.get("isMutex") in {0, 1, "0", "1"}:
            result["isMutex"] = int(question["isMutex"])
        result.update({"type": 9 if alias == "分录题" else 2, "answer": answers})
        return result

    if source_type == "QuestionYesNo":
        result.update({"type": 3, "answer": [{"answer": question.get("answerValue") is True}]})
        return result

    if source_type == "QuestionCommon":
        raw_answer = question.get("answer")
        if raw_answer is not None:
            answer_text = (
                ", ".join(str(value) for value in raw_answer)
                if isinstance(raw_answer, list)
                else str(raw_answer)
            )
            result["answer"] = [{"answer": answer_text}]
        result["type"] = {"名词解释": 5, "论述题": 6, "计算题": 7}.get(alias, 4)
        return result

    result["type"] = numeric_type
    if source_type == "QuestionSameChoose":
        result["answer"] = question.get("answerList") or []
    elif source_type == "QuestionChooseWordGapFilling":
        result["answer"] = question.get("answerList") or []
    elif source_type == "QuestionWriting":
        result["name"] = "写作题"
        if not question.get("typeAlias"):
            result["typeAlias"] = "写作题"
        raw_answer = question.get("answer")
        if isinstance(raw_answer, list):
            answer_text = "".join(str(value) for value in raw_answer)
        else:
            answer_text = str(raw_answer or "")
        writing_answer: dict[str, Any] = {"answer": answer_text}
        subject = _question_bank_writing_subject(question)
        defaults: dict[int, dict[str, str]] = {
            0: {"grade": "cet4"},
            1: {"grade": "十二", "literaryForm": "narrative", "wordnum": "15000"},
            2: {"grade": "delea1"},
            3: {"grade": "delfa1"},
        }
        if subject is not None:
            writing_answer["subject"] = str(subject)
        writing_defaults = defaults.get(subject, {})
        writing_answer["grade"] = str(question.get("grade") or writing_defaults.get("grade") or "")
        literary_form = question.get("literaryForm") or writing_defaults.get("literaryForm")
        word_count = question.get("wordnum") or writing_defaults.get("wordnum")
        if literary_form:
            writing_answer["literaryForm"] = str(literary_form)
        if word_count:
            writing_answer["wordnum"] = str(word_count)
        result["answer"] = [writing_answer]
    return result


def normalize_question_bank_smart_import_paper(paper: list[Any]) -> dict[str, Any]:
    if not isinstance(paper, list):
        raise ChaoxingAPIError("smart-import parser returned no paper list")
    questions: list[dict[str, Any]] = []
    warnings: list[dict[str, Any]] = []
    for source_index, raw in enumerate(paper, 1):
        if not isinstance(raw, dict) or raw.get("noSave"):
            continue
        normalized = _question_bank_smart_import_question(raw)
        if normalized is None:
            continue
        normalized["id"] = len(questions)
        question_warnings: list[str] = []
        if not html_text(str(normalized.get("content") or "")):
            question_warnings.append("题干为空")
        numeric_type = int(normalized["type"])
        answers = normalized.get("answer")
        if numeric_type in {0, 1} and not any(
            isinstance(item, dict) and item.get("isanswer") for item in answers or []
        ):
            question_warnings.append("客观题没有正确答案")
        elif numeric_type == 2 and not any(
            isinstance(item, dict) and str(item.get("content") or "").strip()
            for item in answers or []
        ):
            question_warnings.append("填空题没有答案")
        elif numeric_type == 3 and raw.get("answerValue") not in {True, False}:
            question_warnings.append("判断题没有答案")
        hint = str(raw.get("hintMsg") or "").strip()
        if hint:
            question_warnings.append(hint)
        if question_warnings:
            warnings.append(
                {
                    "source_index": source_index,
                    "question_index": len(questions) + 1,
                    "messages": question_warnings,
                }
            )
        questions.append(normalized)
    if len(questions) > 1000:
        raise ChaoxingAPIError("one smart import cannot contain more than 1000 questions")
    return {"question_count": len(questions), "questions": questions, "warnings": warnings}


def parse_question_bank_source_courses(html: str) -> list[dict[str, Any]]:
    match = re.search(
        r'<div\b[^>]*\bid=["\']course-select["\'][^>]*>(?P<body>.*?)</div>\s*</div>',
        html,
        re.IGNORECASE | re.DOTALL,
    )
    fragment = match.group("body") if match else html
    courses: list[dict[str, Any]] = []
    for tag_match in re.finditer(
        r"<li\b(?P<attrs>[^>]*)>(?P<body>.*?)</li>",
        fragment,
        re.IGNORECASE | re.DOTALL,
    ):
        attrs = html_attrs("<li " + tag_match.group("attrs") + ">")
        course_id = str(attrs.get("courseid") or "").strip()
        name = html_text(tag_match.group("body"))
        if not course_id or not name:
            continue
        courses.append(
            {
                "index": len(courses) + 1,
                "course_id": course_id,
                "course_name": name,
                "course_token": str(attrs.get("cenc") or ""),
                "selected_by_default": "active" in str(attrs.get("class") or "").split(),
            }
        )
    return courses


def resolve_question_bank_source_course(
    courses: list[dict[str, Any]], query: str
) -> dict[str, Any]:
    normalized = str(query or "").strip().lower()
    if not normalized:
        raise ChaoxingAPIError("source-course index, ID, or name is required")
    for key in ("course_id", "index"):
        matches = [
            item for item in courses if str(item.get(key) or "").strip().lower() == normalized
        ]
        if len(matches) == 1:
            return matches[0]
    exact = [
        item for item in courses if str(item.get("course_name") or "").strip().lower() == normalized
    ]
    if len(exact) == 1:
        return exact[0]
    partial = [
        item for item in courses if normalized in str(item.get("course_name") or "").strip().lower()
    ]
    if len(partial) == 1:
        return partial[0]
    candidates = exact or partial
    if not candidates:
        raise ChaoxingAPIError(f"question-bank source course not found: {query}")
    choices = ", ".join(
        f"{item['index']}. {item['course_name']} ({item['course_id']})" for item in candidates[:10]
    )
    raise ChaoxingAPIError(f"multiple question-bank source courses match: {choices}")


def parse_question_bank_source_questions(html: str, *, index_offset: int = 0) -> dict[str, Any]:
    hidden = parse_hidden_inputs(html)
    questions: list[dict[str, Any]] = []
    row_pattern = re.compile(
        r'<tr\b(?P<attrs>[^>]*\bclass=["\'][^"\']*\bquestion-item\b[^"\']*["\'][^>]*)>'
        r"(?P<body>.*?)</tr>",
        re.IGNORECASE | re.DOTALL,
    )
    for row in row_pattern.finditer(html):
        attrs = html_attrs("<tr " + row.group("attrs") + ">")
        question_id = str(attrs.get("data-id") or "").strip()
        if not question_id:
            continue
        body = row.group("body")
        cells = re.findall(r"<td\b[^>]*>(.*?)</td>", body, re.IGNORECASE | re.DOTALL)
        cell_values = [html_text(cell) for cell in cells]
        title_match = re.search(
            r'<p\b[^>]*\bclass=["\'][^"\']*\btable-question-title\b[^"\']*["\'][^>]*>'
            r"(?P<body>.*?)</p>",
            body,
            re.IGNORECASE | re.DOTALL,
        )
        stem = html_text(title_match.group("body")) if title_match else ""
        directory_id_match = re.search(r"qListDirSearch\(['\"]([^'\"]+)", body)
        directory_name_match = re.search(
            r'<div\b[^>]*\bclass=["\'][^"\']*\bshow-txt\b[^"\']*["\'][^>]*>'
            r"(?P<body>.*?)</div>",
            body,
            re.IGNORECASE | re.DOTALL,
        )

        def cell_text(index: int, values: list[str] = cell_values) -> str:
            return values[index] if len(values) > index else ""

        questions.append(
            {
                "index": index_offset + len(questions) + 1,
                "question_id": question_id,
                "source_course_id": str(attrs.get("courseid") or ""),
                "origin_type": str(attrs.get("qtype") or ""),
                "custom_type_id": str(attrs.get("coursequestiontypeid") or "0"),
                "stem": stem,
                "directory_id": directory_id_match.group(1) if directory_id_match else "",
                "directory_name": (
                    html_text(directory_name_match.group("body"))
                    if directory_name_match
                    else cell_text(2)
                ),
                "question_type": cell_text(3),
                "correct_rate": cell_text(4),
                "difficulty": cell_text(5),
                "use_count": _numeric_or_text(cell_text(6)),
                "creator_name": cell_text(7),
                "created_at": cell_text(8),
                "selectable": not bool(
                    re.search(r"<input\b[^>]*\bdisabled\b", body, re.IGNORECASE)
                ),
            }
        )
    try:
        page = int(hidden.get("currentPageNo") or "1")
        page_count = int(hidden.get("totalPage") or "1")
        total = int(hidden.get("totalResult") or str(len(questions)))
    except ValueError as exc:
        raise ChaoxingAPIError("question-bank source search exposed invalid pagination") from exc
    return {
        "page": page,
        "page_count": page_count,
        "total": total,
        "questions": questions,
    }


def resolve_question_bank_source_question(
    questions: list[dict[str, Any]], query: str
) -> dict[str, Any]:
    normalized = str(query or "").strip().lower()
    if not normalized:
        raise ChaoxingAPIError("source question index, ID, or stem is required")
    for key in ("question_id", "index"):
        matches = [
            item for item in questions if str(item.get(key) or "").strip().lower() == normalized
        ]
        if len(matches) == 1:
            return matches[0]
    exact = [
        item for item in questions if str(item.get("stem") or "").strip().lower() == normalized
    ]
    if len(exact) == 1:
        return exact[0]
    partial = [
        item for item in questions if normalized in str(item.get("stem") or "").strip().lower()
    ]
    if len(partial) == 1:
        return partial[0]
    candidates = exact or partial
    if not candidates:
        raise ChaoxingAPIError(f"source question not found: {query}")
    choices = ", ".join(
        f"{item['index']}. {item['stem']} ({item['question_id']})" for item in candidates[:10]
    )
    raise ChaoxingAPIError(f"multiple source questions match: {choices}")


def parse_question_bank_export_context(html: str) -> dict[str, Any]:
    hidden = parse_hidden_inputs(html)
    base_url = str(hidden.get("moocImportExportUrl") or "").strip().rstrip("/")
    parsed = urlparse(base_url)
    hostname = (parsed.hostname or "").lower()
    if parsed.scheme != "https" or not (
        hostname == "chaoxing.com" or hostname.endswith(".chaoxing.com")
    ):
        raise ChaoxingAPIError("question-bank page exposed no trusted export host")
    token = str(hidden.get("exportQuestionEnc") or "").strip()
    if not token:
        raise ChaoxingAPIError("question-bank page exposed no export token")
    download_match = re.search(
        r"downloadCenter['\"]?\)\.attr\(\s*['\"]src['\"]\s*,\s*"
        r"['\"]([^'\"]*?/mycourse/downloadcenter\?[^'\"]+)['\"]",
        html,
        flags=re.IGNORECASE,
    )
    return {
        "export_base_url": base_url,
        "export_endpoint": base_url + "/export-questions",
        "export_token": token,
        "version": str(hidden.get("qbankExcelExportVersion") or ""),
        "micro_topic_id": str(hidden.get("microTopicId") or "0"),
        "download_center_url": (
            urljoin(MOOC2_BASE_URL, unescape(download_match.group(1))) if download_match else ""
        ),
    }


def parse_question_bank_download_center(html: str, *, index_offset: int = 0) -> dict[str, Any]:
    hidden = parse_hidden_inputs(html)
    status_names = {
        "0": "processing",
        "1": "completed",
        "2": "failed",
        "3": "cancelled",
        "-1": "failed",
    }
    records: list[dict[str, Any]] = []
    row_pattern = re.compile(
        r"<ul\b(?P<attrs>[^>]*\bclass=['\"][^'\"]*\bdataBody_td\b[^'\"]*['\"]"
        r"[^>]*)>(?P<body>.*?)</ul>",
        flags=re.IGNORECASE | re.DOTALL,
    )
    for row in row_pattern.finditer(html):
        attrs = html_attrs("<ul " + row.group("attrs") + ">")
        record_id = str(attrs.get("data") or attrs.get("data-id") or attrs.get("id") or "")
        record_id = record_id.strip()
        if not record_id:
            continue
        body = row.group("body")
        cells: list[dict[str, str]] = []
        for cell in re.finditer(
            r"<li\b(?P<attrs>[^>]*)>(?P<body>.*?)</li>",
            body,
            flags=re.IGNORECASE | re.DOTALL,
        ):
            cell_attrs = html_attrs("<li " + cell.group("attrs") + ">")
            cells.append(
                {
                    "class": str(cell_attrs.get("class") or ""),
                    "text": html_text(cell.group("body")),
                }
            )
        name_match = re.search(
            r"<[^>]+\bclass=['\"][^'\"]*\bnameText\b[^'\"]*['\"][^>]*>"
            r"(?P<body>.*?)</[^>]+>",
            body,
            flags=re.IGNORECASE | re.DOTALL,
        )
        file_name = html_text(name_match.group("body")) if name_match else ""
        if not file_name:
            file_name = next(
                (
                    item["text"]
                    for item in cells
                    if item["text"] and not re.search(r"time|status|handle", item["class"], re.I)
                ),
                "",
            )
        metadata: dict[str, Any] = {}
        check_tag = re.search(
            r"<[^>]+\bclass=['\"][^'\"]*\bcheckSafe\b[^'\"]*['\"][^>]*>",
            body,
            flags=re.IGNORECASE | re.DOTALL,
        )
        if check_tag:
            check_attrs = html_attrs(check_tag.group(0))
            raw_metadata = str(check_attrs.get("data") or "").strip()
            if raw_metadata:
                try:
                    decoded = json.loads(raw_metadata)
                except json.JSONDecodeError:
                    decoded = {}
                if isinstance(decoded, dict):
                    metadata = decoded
            record_id = str(check_attrs.get("id") or record_id).strip()
        direct_url_match = re.search(
            r"<a\b[^>]*\b(?:href|data-url)=['\"]([^'\"]+)['\"][^>]*"
            r"\bclass=['\"][^'\"]*\b(?:download_ic|checkSafe)\b",
            body,
            flags=re.IGNORECASE | re.DOTALL,
        )
        created_at = next(
            (
                match.group(0)
                for item in cells
                if (
                    match := re.search(
                        r"20\d{2}[-/.]\d{1,2}[-/.]\d{1,2}(?:\s+\d{1,2}:\d{2}(?::\d{2})?)?",
                        item["text"],
                    )
                )
            ),
            "",
        )
        status_code = str(attrs.get("data-status") or attrs.get("status") or "").strip()
        status_text = next(
            (
                item["text"]
                for item in cells
                if re.search(r"status|state|progress", item["class"], re.IGNORECASE)
                and item["text"]
            ),
            "",
        )
        records.append(
            {
                "index": index_offset + len(records) + 1,
                "record_id": record_id,
                "file_name": file_name,
                "created_at": created_at,
                "status": status_names.get(status_code, "unknown"),
                "status_code": status_code,
                "status_text": status_text,
                "relation_id": str(metadata.get("relationId") or ""),
                "clazz_id": str(metadata.get("clazzId") or ""),
                "library_id": str(metadata.get("libraryId") or ""),
                "metadata": metadata,
                "direct_url": (
                    urljoin(MOOC2_BASE_URL, unescape(direct_url_match.group(1)))
                    if direct_url_match
                    else ""
                ),
                "can_download": bool(check_tag or direct_url_match),
                "can_rename": bool(re.search(r"\beditName\b", body, re.IGNORECASE)),
                "can_delete": bool(re.search(r"\bdeleteOrCancel\b", body, re.IGNORECASE)),
            }
        )

    def hidden_int(name: str, default: int) -> int:
        try:
            return int(str(hidden.get(name) or default))
        except (TypeError, ValueError):
            return default

    return {
        "page": hidden_int("downcenterpage", 1),
        "page_count": hidden_int("totalPage", 1),
        "order": str(hidden.get("downcenterorder") or "down"),
        "record_count": len(records),
        "records": records,
        "has_processing": any(item["status"] == "processing" for item in records),
    }


def resolve_question_bank_download_record(
    records: list[dict[str, Any]], query: str
) -> dict[str, Any]:
    normalized = str(query or "").strip().lower()
    if not normalized:
        raise ChaoxingAPIError("download record index, ID, or file name is required")
    for key in ("record_id", "index"):
        matches = [
            item for item in records if str(item.get(key) or "").strip().lower() == normalized
        ]
        if len(matches) == 1:
            return matches[0]
    exact = [
        item for item in records if str(item.get("file_name") or "").strip().lower() == normalized
    ]
    if len(exact) == 1:
        return exact[0]
    partial = [
        item for item in records if normalized in str(item.get("file_name") or "").strip().lower()
    ]
    if len(partial) == 1:
        return partial[0]
    candidates = exact or partial
    if not candidates:
        raise ChaoxingAPIError(f"question-bank download record not found: {query}")
    choices = ", ".join(
        f"{item['index']}. {item['file_name']} ({item['record_id']})" for item in candidates[:10]
    )
    raise ChaoxingAPIError(f"multiple question-bank download records match: {choices}")


def content_disposition_filename(value: str) -> str:
    encoded = re.search(r"filename\*\s*=\s*(?:UTF-8'')?([^;]+)", value or "", flags=re.IGNORECASE)
    if encoded:
        candidate = unquote(encoded.group(1).strip().strip("'\""))
    else:
        plain = re.search(r"filename\s*=\s*(?:\"([^\"]+)\"|([^;]+))", value or "", re.I)
        candidate = (plain.group(1) or plain.group(2)).strip() if plain else ""
    candidate = candidate.replace("\\", "/").split("/")[-1].replace("\x00", "").strip()
    try:
        repaired = candidate.encode("latin-1").decode("utf-8")
    except (UnicodeEncodeError, UnicodeDecodeError):
        repaired = candidate
    if repaired and repaired.isprintable():
        candidate = repaired
    return candidate


def resolve_question_bank_inactive_item(items: list[dict[str, Any]], query: str) -> dict[str, Any]:
    normalized = str(query or "").strip().lower()
    if not normalized:
        raise ChaoxingAPIError("inactive question-bank item index, ID, or name is required")
    for key in ("item_id", "recycle_id", "index"):
        matches = [item for item in items if str(item.get(key) or "").strip().lower() == normalized]
        if len(matches) == 1:
            return matches[0]
    exact = [item for item in items if str(item.get("name") or "").strip().lower() == normalized]
    if len(exact) == 1:
        return exact[0]
    partial = [item for item in items if normalized in str(item.get("name") or "").strip().lower()]
    if len(partial) == 1:
        return partial[0]
    candidates = exact or partial
    if not candidates:
        raise ChaoxingAPIError(f"inactive question-bank item not found: {query}")
    item_text = ", ".join(
        f"{item.get('index')}. {item.get('name')} ({item.get('item_id')})"
        for item in candidates[:10]
    )
    raise ChaoxingAPIError(f"multiple inactive question-bank items match: {item_text}")


def resolve_question_bank_directory(
    directories: list[dict[str, Any]], query: str, *, allow_root: bool = False
) -> dict[str, Any]:
    normalized = str(query or "").strip().lower()
    if allow_root and normalized in {"0", "root", "根目录", "全部题目", "题库根目录"}:
        return {
            "index": 0,
            "directory_id": "0",
            "parent_id": "",
            "course_id": "",
            "name": "根目录",
            "path": "根目录",
            "child_count": sum(1 for item in directories if item.get("parent_id") == "0"),
        }
    if not normalized:
        raise ChaoxingAPIError("question-bank directory index, ID, name, or path is required")
    for key in ("directory_id", "index"):
        exact = [
            item for item in directories if str(item.get(key) or "").strip().lower() == normalized
        ]
        if len(exact) == 1:
            return exact[0]
    exact = [
        item
        for item in directories
        if normalized
        in {
            str(item.get("name") or "").strip().lower(),
            str(item.get("path") or "").strip().lower(),
        }
    ]
    if len(exact) == 1:
        return exact[0]
    partial = [
        item
        for item in directories
        if normalized in str(item.get("path") or item.get("name") or "").lower()
    ]
    if len(partial) == 1:
        return partial[0]
    candidates = exact or partial
    if not candidates:
        raise ChaoxingAPIError(f"question-bank directory not found: {query}")
    labels = ", ".join(
        f"{item.get('index')}. {item.get('path')} ({item.get('directory_id')})"
        for item in candidates[:10]
    )
    raise ChaoxingAPIError(f"multiple question-bank directories match: {labels}")


def resolve_question_bank_question(questions: list[dict[str, Any]], query: str) -> dict[str, Any]:
    normalized = query.strip().lower()
    if not normalized:
        raise ChaoxingAPIError("question index, question_id, or stem is required")
    for key in ("question_id", "index"):
        exact = [item for item in questions if str(item.get(key, "")).strip().lower() == normalized]
        if len(exact) == 1:
            return exact[0]
    exact_stems = [
        item for item in questions if str(item.get("stem", "")).strip().lower() == normalized
    ]
    if len(exact_stems) == 1:
        return exact_stems[0]
    partial = [
        item for item in questions if normalized in str(item.get("stem", "")).strip().lower()
    ]
    if len(partial) == 1:
        return partial[0]
    if not partial:
        raise ChaoxingAPIError(f"question-bank question not found: {query}")
    candidates = ", ".join(
        f"{item.get('index')}. {str(item.get('stem') or '')[:80]} ({item.get('question_id')})"
        for item in partial[:10]
    )
    raise ChaoxingAPIError(f"multiple question-bank question matches: {candidates}")


def parse_class_student_table(
    html: str, page_url: str
) -> tuple[list[dict[str, Any]], int | None, int]:
    table_match = re.search(
        r"<table\b[^>]*\bid=['\"]studentTable['\"][^>]*>([\s\S]*?)</table>",
        html,
        flags=re.IGNORECASE,
    )
    if not table_match:
        return [], None, 1
    table_html = table_match.group(1)
    fields: list[str] = []
    for header in re.finditer(r"<th\b([^>]*)>[\s\S]*?</th>", table_html, flags=re.IGNORECASE):
        attrs = html_attrs(header.group(1))
        field_match = re.search(r"field\s*:\s*['\"]([^'\"]+)", attrs.get("lay-data", ""))
        fields.append(field_match.group(1) if field_match else "")

    tbody_match = re.search(r"<tbody\b[^>]*>([\s\S]*?)</tbody>", table_html, flags=re.I)
    tbody = tbody_match.group(1) if tbody_match else table_html
    students: list[dict[str, Any]] = []
    for row_match in re.finditer(r"<tr\b[^>]*>([\s\S]*?)</tr>", tbody, flags=re.I):
        row_html = row_match.group(1)
        cells = re.findall(r"<td\b[^>]*>([\s\S]*?)</td>", row_html, flags=re.I)
        if not cells:
            continue
        values = [html_text(cell) for cell in cells]
        row = {
            field: values[index]
            for index, field in enumerate(fields)
            if field and index < len(values)
        }
        person_id = str(row.get("personid") or "").strip()
        if not person_id:
            continue
        access_match = re.search(
            r"href=['\"]([^'\"]*?/mooc2-ans/moocanalysis/accesslog\?[^'\"]+)['\"]",
            row_html,
            flags=re.I,
        )
        students.append(
            {
                "person_id": person_id,
                "student_name": str(row.get("userName") or "").strip(),
                "student_no": str(row.get("studentNumber") or "").strip(),
                "school": str(row.get("schoolName") or "").strip(),
                "department": str(row.get("group1") or "").strip(),
                "major": str(row.get("group2") or "").strip(),
                "administrative_class": str(row.get("group3") or "").strip(),
                "joined_at": str(row.get("createTime") or "").strip(),
                "access_log_url": (
                    urljoin(page_url, unescape(access_match.group(1))) if access_match else ""
                ),
            }
        )

    total_match = re.search(r"共\s*(\d+)\s*人", html_text(html))
    total_count = int(total_match.group(1)) if total_match else None
    hidden = parse_hidden_inputs(html)
    try:
        current_page = max(1, int(hidden.get("pageNum") or "1"))
    except (TypeError, ValueError):
        current_page = 1
    return students, total_count, current_page


def resolve_class_student(students: list[dict[str, Any]], query: str) -> dict[str, Any]:
    normalized = query.strip().lower()
    if not normalized:
        raise ChaoxingAPIError("student index, person_id, name, or student number is required")
    for key in ("person_id", "index", "student_no"):
        exact = [
            student
            for student in students
            if str(student.get(key, "")).strip().lower() == normalized
        ]
        if len(exact) == 1:
            return exact[0]
    exact_names = [
        student
        for student in students
        if str(student.get("student_name", "")).strip().lower() == normalized
    ]
    if len(exact_names) == 1:
        return exact_names[0]
    partial = [
        student
        for student in students
        if normalized in str(student.get("student_name", "")).strip().lower()
    ]
    if len(partial) == 1:
        return partial[0]
    if not partial:
        raise ChaoxingAPIError(f"class student not found: {query}")
    candidates = ", ".join(
        f"{student.get('index')}. {student.get('student_name')} ({student.get('student_no')})"
        for student in partial
    )
    raise ChaoxingAPIError(f"multiple class student matches: {candidates}")


def parse_student_bank_candidates(html: str) -> tuple[list[dict[str, Any]], int | None]:
    candidates: list[dict[str, Any]] = []
    for row_match in re.finditer(
        r"<ul\b[^>]*class=['\"][^'\"]*\btabBody_td\b[^'\"]*['\"][^>]*>"
        r"([\s\S]*?)</ul>",
        html,
        flags=re.I,
    ):
        row_html = row_match.group(1)
        identity_match = re.search(
            r"<li\b(?=[^>]*\bdata-personid=['\"]([^'\"]+))"
            r"(?=[^>]*\bdata-enc=['\"]([^'\"]+))[^>]*>",
            row_html,
            flags=re.I | re.S,
        )
        if not identity_match:
            continue
        cells = [
            html_text(cell.group(1))
            for cell in re.finditer(r"<li\b[^>]*>([\s\S]*?)</li>", row_html, flags=re.I)
        ]
        if len(cells) < 5:
            continue
        candidates.append(
            {
                "person_id": identity_match.group(1),
                "selection_enc": identity_match.group(2),
                "student_name": cells[1] if len(cells) > 1 else "",
                "student_no": cells[2] if len(cells) > 2 else "",
                "at_school": cells[3] == "是" if len(cells) > 3 else None,
                "organization_values": cells[4:-1] if len(cells) > 5 else [],
                "school": cells[-1] if len(cells) > 4 else "",
            }
        )
    hidden = parse_hidden_inputs(html)
    try:
        total = int(hidden["searchStuCount"]) if hidden.get("searchStuCount") else None
    except (TypeError, ValueError):
        total = None
    return candidates, total


def resolve_student_bank_candidate(candidates: list[dict[str, Any]], query: str) -> dict[str, Any]:
    normalized = query.strip().lower()
    if not normalized:
        raise ChaoxingAPIError("candidate index, person_id, name, or student number is required")
    for key in ("person_id", "index", "student_no"):
        exact = [
            candidate
            for candidate in candidates
            if str(candidate.get(key, "")).strip().lower() == normalized
        ]
        if len(exact) == 1:
            return exact[0]
    exact_names = [
        candidate
        for candidate in candidates
        if str(candidate.get("student_name", "")).strip().lower() == normalized
    ]
    if len(exact_names) == 1:
        return exact_names[0]
    partial = [
        candidate
        for candidate in candidates
        if normalized in str(candidate.get("student_name", "")).strip().lower()
    ]
    if len(partial) == 1:
        return partial[0]
    if not partial:
        raise ChaoxingAPIError(f"student-bank candidate not found: {query}")
    matches = ", ".join(
        f"{item.get('index')}. {item.get('student_name')} ({item.get('student_no')})"
        for item in partial
    )
    raise ChaoxingAPIError(f"multiple student-bank candidates match: {matches}")


def parse_class_join_applications(html: str) -> tuple[list[dict[str, Any]], int]:
    applications: list[dict[str, Any]] = []
    for row_match in re.finditer(
        r"(<ul\b[^>]*class=['\"][^'\"]*\bdataBody_codeapply_td\b[^'\"]*['\"]"
        r"[^>]*>)([\s\S]*?)</ul>",
        html,
        flags=re.I,
    ):
        attrs = html_attrs(row_match.group(1))
        log_id = str(attrs.get("data") or attrs.get("data-id") or "").strip()
        if not log_id:
            continue
        cells = [
            html_text(cell.group(1))
            for cell in re.finditer(r"<li\b[^>]*>([\s\S]*?)</li>", row_match.group(2), re.I)
        ]
        details = [cell for cell in cells if cell and cell not in {"通过", "拒绝"}]
        applied_at = next(
            (value for value in details if re.search(r"\d{4}[-/.年]\d{1,2}[-/.月]\d{1,2}", value)),
            "",
        )
        student_no = next(
            (
                value
                for value in details[1:]
                if re.fullmatch(r"[A-Za-z0-9_-]{5,}", value) and value != log_id
            ),
            "",
        )
        applications.append(
            {
                "log_id": log_id,
                "student_name": details[0] if details else "",
                "student_no": student_no,
                "applied_at": applied_at,
                "details": details,
            }
        )
    hidden = parse_hidden_inputs(html)
    try:
        total = int(hidden.get("codeaddstuApplyCount") or len(applications))
    except (TypeError, ValueError):
        total = len(applications)
    return applications, total


def resolve_class_join_application(
    applications: list[dict[str, Any]], query: str
) -> dict[str, Any]:
    normalized = query.strip().lower()
    if not normalized:
        raise ChaoxingAPIError("application index, log ID, name, or student number is required")
    for key in ("log_id", "index", "student_no"):
        exact = [
            item for item in applications if str(item.get(key, "")).strip().lower() == normalized
        ]
        if len(exact) == 1:
            return exact[0]
    exact_names = [
        item
        for item in applications
        if str(item.get("student_name", "")).strip().lower() == normalized
    ]
    if len(exact_names) == 1:
        return exact_names[0]
    partial = [
        item
        for item in applications
        if any(normalized in str(value).lower() for value in item.get("details", []))
    ]
    if len(partial) == 1:
        return partial[0]
    if not partial:
        raise ChaoxingAPIError(f"class join application not found: {query}")
    matches = ", ".join(
        f"{item.get('index')}. {item.get('student_name')} ({item.get('log_id')})"
        for item in partial
    )
    raise ChaoxingAPIError(f"multiple class join applications match: {matches}")


def parse_student_access_summary(html: str) -> dict[str, Any]:
    plain = html_text(html)
    chapter_match = re.search(r"(\d+)\s*章节学习次数", plain)
    if not chapter_match:
        chapter_match = re.search(r"章节学习次数\s*(\d+)", plain)
    duration_match = re.search(r"(?:(\d+)\s*小时)?\s*(\d+)\s*分钟\s*课程访问时长", plain)
    export_match = re.search(
        r"stuExportUrl\s*=\s*['\"]([^'\"]*?/api/export-stu-visit-log\?[^'\"]+)",
        html,
        flags=re.I,
    )
    return {
        "chapter_study_count": int(chapter_match.group(1)) if chapter_match else None,
        "course_access_hours": (int(duration_match.group(1) or 0) if duration_match else None),
        "course_access_minutes": int(duration_match.group(2)) if duration_match else None,
        "export_url_template": unescape(export_match.group(1)) if export_match else "",
    }


def parse_student_access_log_payload(
    payload: dict[str, Any], year: int
) -> tuple[list[dict[str, Any]], dict[str, int]]:
    logs: list[dict[str, Any]] = []
    raw_logs = payload.get("array")
    if isinstance(raw_logs, list):
        for raw in raw_logs:
            if not isinstance(raw, dict):
                continue
            short_time = str(raw.get("time") or "").strip()
            timestamp = (
                f"{year}-{short_time}" if re.match(r"\d{2}-\d{2}\s", short_time) else short_time
            )
            logs.append(
                {
                    "timestamp": timestamp,
                    "time": short_time,
                    "event_type": str(raw.get("eventType") or ""),
                    "event_name": str(raw.get("eventName") or ""),
                    "message": str(raw.get("message") or ""),
                    "relation_name": str(raw.get("relationName") or ""),
                    "client_ip": str(raw.get("clientip") or ""),
                    "ip_city": str(raw.get("ipCity") or ""),
                }
            )
    page_info = payload.get("pageInfo")
    if not isinstance(page_info, dict):
        page_info = {}

    def page_int(name: str, default: int) -> int:
        try:
            return int(page_info.get(name) or default)
        except (TypeError, ValueError):
            return default

    return logs, {
        "current_page": page_int("currentPageNo", 1),
        "page_size": page_int("pagesize", len(logs) or 1),
        "page_count": page_int("totalPage", 1),
        "total_count": page_int("totalResult", len(logs)),
    }


def parse_teacher_team(html: str) -> tuple[list[dict[str, Any]], int | None]:
    starts = list(
        re.finditer(
            r"<ul\b[^>]*class=['\"][^'\"]*\bdataBody_td\b[^'\"]*['\"][^>]*>",
            html,
            flags=re.I | re.S,
        )
    )
    teachers: list[dict[str, Any]] = []
    for position, start in enumerate(starts):
        end = starts[position + 1].start() if position + 1 < len(starts) else len(html)
        block = html[start.start() : end]
        attrs = html_attrs(start.group(0))
        nested_identity = re.search(
            r"<[^>]+\bpersonid=['\"][^'\"]+['\"][^>]*>",
            block,
            flags=re.I,
        )
        nested_attrs = html_attrs(nested_identity.group(0)) if nested_identity else {}

        def field_text(class_name: str, fragment: str = block) -> str:
            match = re.search(
                rf"<li\b[^>]*class=['\"][^'\"]*\b{class_name}\b[^'\"]*['\"][^>]*>"
                r"([\s\S]*?)</li>",
                fragment,
                flags=re.I,
            )
            return html_text(match.group(1)) if match else ""

        name = field_text("dataBody_name")
        if not name:
            continue
        teachers.append(
            {
                "person_id": str(attrs.get("personid") or nested_attrs.get("personid") or ""),
                "uid": str(attrs.get("uid") or ""),
                "team_teacher_id": str(
                    attrs.get("teamteachid") or nested_attrs.get("teamteachid") or ""
                ),
                "role_code": str(attrs.get("role") or nested_attrs.get("role") or ""),
                "teacher_name": name,
                "role": field_text("dataBody_read"),
                "teacher_no": field_text("dataBody_down"),
                "school": field_text("dataBody_size"),
                "department": field_text("dataBody_depart"),
                "joined_at": field_text("dataBody_time"),
            }
        )
    total_match = re.search(r"id=['\"]allTeacherNum['\"][^>]*>\s*(\d+)", html, flags=re.I)
    total = int(total_match.group(1)) if total_match else None
    return teachers, total


def resolve_course_teacher(teachers: list[dict[str, Any]], query: str) -> dict[str, Any]:
    normalized = query.strip().lower()
    if not normalized:
        raise ChaoxingAPIError("teacher index, person ID, name, or teacher number is required")
    for key in ("person_id", "uid", "team_teacher_id", "index", "teacher_no"):
        exact = [
            teacher
            for teacher in teachers
            if str(teacher.get(key, "")).strip().lower() == normalized
        ]
        if len(exact) == 1:
            return exact[0]
    exact_names = [
        teacher
        for teacher in teachers
        if str(teacher.get("teacher_name", "")).strip().lower() == normalized
    ]
    if len(exact_names) == 1:
        return exact_names[0]
    partial = [
        teacher
        for teacher in teachers
        if normalized in str(teacher.get("teacher_name", "")).strip().lower()
    ]
    if len(partial) == 1:
        return partial[0]
    if not partial:
        raise ChaoxingAPIError(f"course teacher not found: {query}")
    matches = ", ".join(
        f"{item.get('index')}. {item.get('teacher_name')} ({item.get('teacher_no')})"
        for item in partial
    )
    raise ChaoxingAPIError(f"multiple course teachers match: {matches}")


def parse_teacher_bank_candidates(html: str) -> tuple[list[dict[str, Any]], int | None]:
    candidates: list[dict[str, Any]] = []
    for row_match in re.finditer(
        r"(<ul\b[^>]*class=['\"][^'\"]*\bdataBody_addtea\b[^'\"]*['\"][^>]*>)"
        r"([\s\S]*?)</ul>",
        html,
        flags=re.I,
    ):
        attrs = html_attrs(row_match.group(1))
        person_id = str(attrs.get("personid") or "").strip()
        selection_enc = str(attrs.get("enc") or "").strip()
        if not person_id or not selection_enc:
            continue
        cells = [
            html_text(cell.group(1))
            for cell in re.finditer(r"<li\b[^>]*>([\s\S]*?)</li>", row_match.group(2), re.I)
        ]
        candidates.append(
            {
                "person_id": person_id,
                "selection_enc": selection_enc,
                "teacher_name": cells[0] if cells else "",
                "teacher_no": cells[1] if len(cells) > 1 else "",
                "department": cells[2] if len(cells) > 2 else "",
            }
        )
    total_match = re.search(r"共\s*(\d+)\s*人", html_text(html))
    total = int(total_match.group(1)) if total_match else None
    return candidates, total


def resolve_teacher_bank_candidate(candidates: list[dict[str, Any]], query: str) -> dict[str, Any]:
    normalized = query.strip().lower()
    if not normalized:
        raise ChaoxingAPIError("candidate index, person ID, name, or teacher number is required")
    for key in ("person_id", "index", "teacher_no"):
        exact = [
            item for item in candidates if str(item.get(key, "")).strip().lower() == normalized
        ]
        if len(exact) == 1:
            return exact[0]
    exact_names = [
        item
        for item in candidates
        if str(item.get("teacher_name", "")).strip().lower() == normalized
    ]
    if len(exact_names) == 1:
        return exact_names[0]
    partial = [
        item
        for item in candidates
        if normalized in str(item.get("teacher_name", "")).strip().lower()
    ]
    if len(partial) == 1:
        return partial[0]
    if not partial:
        raise ChaoxingAPIError(f"teacher-bank candidate not found: {query}")
    matches = ", ".join(
        f"{item.get('index')}. {item.get('teacher_name')} ({item.get('teacher_no')})"
        for item in partial
    )
    raise ChaoxingAPIError(f"multiple teacher-bank candidates match: {matches}")


def _number_value(raw: Any) -> int | float | None:
    value = str(raw if raw is not None else "").strip()
    if not value:
        return None
    try:
        number = float(value)
    except ValueError:
        return None
    return int(number) if number.is_integer() else number


def _form_fragment(html: str, form_id: str) -> str:
    match = re.search(
        rf"<form\b(?=[^>]*\bid=['\"]{re.escape(form_id)}['\"])[^>]*>"
        r"([\s\S]*?)</form>",
        html,
        flags=re.IGNORECASE,
    )
    return match.group(1) if match else ""


def _weight_components(
    form: str,
    class_name: str,
    available_by_key: dict[str, bool] | None = None,
) -> list[dict[str, Any]]:
    components: list[dict[str, Any]] = []
    seen: set[str] = set()
    for match in re.finditer(r"<input\b[^>]*>", form, flags=re.IGNORECASE | re.DOTALL):
        attrs = html_attrs(match.group(0))
        classes = set(attrs.get("class", "").split())
        key = attrs.get("name", "")
        if class_name not in classes or key not in GRADE_WEIGHT_LABELS or key in seen:
            continue
        seen.add(key)
        weight = _number_value(attrs.get("value"))
        available = available_by_key.get(key, True) if available_by_key is not None else True
        components.append(
            {
                "key": key,
                "label": GRADE_WEIGHT_LABELS[key],
                "weight": weight if weight is not None else 0,
                "available": available,
                "enabled": available and bool(weight),
            }
        )
    return components


def _input_values_by_id(fragment: str, input_ids: tuple[str, ...]) -> dict[str, Any]:
    requested = set(input_ids)
    values: dict[str, Any] = {}
    for match in re.finditer(r"<input\b[^>]*>", fragment, flags=re.IGNORECASE | re.DOTALL):
        attrs = html_attrs(match.group(0))
        input_id = attrs.get("id", "")
        if input_id not in requested or input_id in values:
            continue
        raw_value = attrs.get("value", "")
        number = _number_value(raw_value)
        values[input_id] = number if number is not None else raw_value
    return values


def _input_has_attribute(fragment: str, input_id: str, attribute: str) -> bool:
    match = re.search(
        rf"<input\b(?=[^>]*\bid=['\"]{re.escape(input_id)}['\"])[^>]*>",
        fragment,
        flags=re.IGNORECASE | re.DOTALL,
    )
    return bool(
        match
        and re.search(
            rf"\s{re.escape(attribute)}(?:\s*=|\s|/?>)",
            match.group(0),
            flags=re.IGNORECASE,
        )
    )


def parse_custom_weight_payload(payload: dict[str, Any]) -> dict[str, Any]:
    data = payload.get("data")
    if not isinstance(data, dict):
        data = {}
    raw_groups = data.get("list")
    if not isinstance(raw_groups, list):
        raw_groups = []

    def normalize(raw: Any) -> dict[str, Any] | None:
        if not isinstance(raw, dict):
            return None
        raw_settings = raw.get("settings")
        settings: Any = raw_settings
        if isinstance(raw_settings, str):
            try:
                settings = json.loads(raw_settings) if raw_settings.strip() else {}
            except json.JSONDecodeError:
                settings = {"raw": raw_settings}
        elif not isinstance(raw_settings, (dict, list)):
            settings = {}
        children = [
            item for item in (normalize(child) for child in raw.get("children", [])) if item
        ]
        return {
            "weight_id": str(raw.get("weightId") or raw.get("id") or ""),
            "name": str(raw.get("name") or ""),
            "weight": _number_value(raw.get("weight")) or 0,
            "weight_type_index": raw.get("weightTypeIndex"),
            "part": raw.get("part"),
            "description": str(raw.get("desc") or ""),
            "settings": settings,
            "relations": raw.get("relations"),
            "children": children,
        }

    groups = [item for item in (normalize(raw) for raw in raw_groups) if item]
    child_weights = [
        child["weight"]
        for group in groups
        for child in group.get("children", [])
        if isinstance(child.get("weight"), (int, float))
    ]
    total = sum(child_weights)
    return {
        "available": bool(groups),
        "clean_direct_scores": data.get("cleanCustomScore") == 1,
        "total_weight": total,
        "valid_total": bool(groups) and total == 100,
        "groups": groups,
    }


def parse_grade_weight_configuration(
    html: str,
    custom_payload: dict[str, Any] | None = None,
) -> dict[str, Any]:
    mode_code = input_attrs_by_id(html, "weightType").get("value", "")
    active_mode = ""
    mode_classes = {
        "classicMode": "classic",
        "taskMode": "task",
        "customMode": "custom",
    }
    for match in re.finditer(r"<p\b[^>]*>", html, flags=re.IGNORECASE | re.DOTALL):
        classes = set(html_attrs(match.group(0)).get("class", "").split())
        if "tab-active" not in classes:
            continue
        for css_class, mode in mode_classes.items():
            if css_class in classes:
                active_mode = mode
                break
        if active_mode:
            break
    if not active_mode:
        active_mode = {"0": "classic", "1": "task", "2": "custom"}.get(mode_code, "unknown")

    classic_form = _form_fragment(html, "weightForm")
    task_form = _form_fragment(html, "taskWeightForm")
    classic_components = _weight_components(classic_form, "num")
    classic_total = sum(
        component["weight"]
        for component in classic_components
        if isinstance(component.get("weight"), (int, float))
    )

    task_available: dict[str, bool] = {}
    task_rows = list(
        re.finditer(
            r"<li\b[^>]*class=['\"][^'\"]*\bno-base\b[^'\"]*['\"][^>]*>",
            task_form,
            flags=re.IGNORECASE | re.DOTALL,
        )
    )
    for row in task_rows:
        attrs = html_attrs(row.group(0))
        key = attrs.get("data", "")
        if key in GRADE_WEIGHT_LABELS:
            style = re.sub(r"\s+", "", attrs.get("style", "").lower())
            task_available[key] = "display:none" not in style
    task_components = _weight_components(task_form, "weightInput", task_available)
    task_total = sum(
        component["weight"]
        for component in task_components
        if component["available"] and isinstance(component.get("weight"), (int, float))
    )
    custom = parse_custom_weight_payload(custom_payload or {})
    classic_clean = _input_has_attribute(classic_form, "cleanConfigButton", "checked")
    task_clean = _input_has_attribute(task_form, "cleanConfigButtonV2", "checked")
    classic_settings = _input_values_by_id(
        classic_form,
        (
            "completionRate",
            "masteryRate",
            "allTaskType",
            "passRateType",
            "attendStatisticType",
            "attendLimit",
            "attendMinLimit",
            "activeLimit",
            "bbsStatisticType",
            "visitTimeLimit",
            "readTimeLimit",
            "liveStatisticType",
            "liveViewingRate",
            "liveTimeLimit",
            "chaoxingClassType",
            "chaoxingClassLimit",
            "chaoxingClassRate",
        ),
    )
    task_settings = _input_values_by_id(
        task_form,
        (
            "attendLimitV1",
            "attendMinLimitV1",
            "visitTimeLimitV2",
            "readTimeLimitV2",
            "liveViewingRateV2",
            "liveTimeLimitV2",
            "chaoxingClassLimitV2",
            "chaoxingClassRateV2",
        ),
    )
    profiles: dict[str, dict[str, Any]] = {
        "classic": {
            "available": bool(classic_components),
            "total_weight": classic_total,
            "valid_total": bool(classic_components) and classic_total == 100,
            "clean_direct_scores": classic_clean,
            "components": classic_components,
            "settings": classic_settings,
        },
        "task": {
            "available": any(task_available.values()),
            "total_weight": task_total,
            "valid_total": any(task_available.values()) and task_total == 100,
            "clean_direct_scores": task_clean,
            "components": task_components,
            "settings": task_settings,
        },
        "custom": custom,
    }
    active_profile = profiles.get(active_mode, {})
    return {
        "active_mode": active_mode,
        "active_mode_code": mode_code,
        "weight_id": input_attrs_by_id(html, "weightId").get("value", ""),
        "scores_visible_to_students": (
            input_attrs_by_id(html, "visibleScore").get("value", "") == "1"
        ),
        "active_total_weight": active_profile.get("total_weight"),
        "active_total_valid": active_profile.get("valid_total", False),
        "profiles": profiles,
    }


def parse_statistics_navigation(payload: dict[str, Any]) -> list[dict[str, Any]]:
    raw_entries = payload.get("data")
    if payload.get("status") is not True or not isinstance(raw_entries, list):
        raise ChaoxingAPIError("statistics navigation response had an invalid shape")
    entries: list[dict[str, Any]] = []
    for raw in raw_entries:
        if not isinstance(raw, dict):
            continue
        url = str(raw.get("url") or "").strip()
        if not url:
            continue
        entries.append(
            {
                "name": str(raw.get("name") or "").strip(),
                "url": url,
                "visible": bool(raw.get("show")),
                "sort": raw.get("sort"),
            }
        )
    return entries


def grade_component_schema(initialization: dict[str, Any]) -> list[dict[str, Any]]:
    weight = initialization.get("weight")
    if not isinstance(weight, dict):
        weight = {}
    weight_type = _number_value(weight.get("weightType"))
    components: list[dict[str, Any]] = []

    if weight_type == 2:
        roots = initialization.get("thirdWeight")
        if not isinstance(roots, list):
            roots = []
        for root in roots:
            if not isinstance(root, dict) or (_number_value(root.get("weight")) or 0) <= 0:
                continue
            children = root.get("children")
            if not isinstance(children, list):
                continue
            for child in children:
                if not isinstance(child, dict):
                    continue
                child_weight = _number_value(child.get("weight")) or 0
                field = str(child.get("id") or "").strip()
                if not field or child_weight <= 0:
                    continue
                components.append(
                    {
                        "field": field,
                        "label": str(child.get("name") or field),
                        "weight": child_weight,
                        "parent": str(root.get("name") or ""),
                        "parent_weight": _number_value(root.get("weight")) or 0,
                    }
                )
        return components

    model_type = _number_value(weight.get("modelType"))
    if model_type == 1:
        relations = weight.get("clazzEngineRelations")
        if isinstance(relations, list):
            for relation in relations:
                if not isinstance(relation, dict):
                    continue
                relation_weight = _number_value(relation.get("weight")) or 0
                engine_id = str(relation.get("engineId") or "").strip()
                if engine_id and relation_weight > 0:
                    components.append(
                        {
                            "field": f"taskEngine{engine_id}",
                            "label": str(relation.get("name") or "学习任务"),
                            "weight": relation_weight,
                        }
                    )
    elif model_type == 2 and (_number_value(weight.get("taskEngine")) or 0) > 0:
        components.append(
            {
                "field": "taskEngineScore",
                "label": "学习任务",
                "weight": _number_value(weight.get("taskEngine")) or 0,
            }
        )

    for key, field in GRADE_SCORE_FIELDS.items():
        component_weight = _number_value(weight.get(key)) or 0
        if component_weight <= 0:
            continue
        label = GRADE_WEIGHT_LABELS[key]
        if key == "offline":
            label = str(weight.get("offlineName") or label)
        components.append(
            {
                "field": field,
                "label": label,
                "weight": component_weight,
            }
        )

    custom_weights = weight.get("customWeightList")
    if isinstance(custom_weights, list):
        for custom in custom_weights:
            if not isinstance(custom, dict):
                continue
            custom_weight = _number_value(custom.get("customWeight")) or 0
            custom_id = str(custom.get("id") or "").strip()
            if custom_id and custom_weight > 0:
                components.append(
                    {
                        "field": f"custom{custom_id}",
                        "label": str(custom.get("customWeightName") or f"自定义成绩 {custom_id}"),
                        "weight": custom_weight,
                    }
                )
    return components


def parse_grade_summary_payload(payload: dict[str, Any]) -> dict[str, Any]:
    distribution = payload.get("array")
    if not isinstance(distribution, list):
        distribution = []
    return {
        "student_count": int(_number_value(payload.get("studentNum")) or 0),
        "record_count": int(_number_value(payload.get("count")) or 0),
        "average": _number_value(payload.get("avg")),
        "minimum": _number_value(payload.get("min")),
        "maximum": _number_value(payload.get("max")),
        "distribution": [
            {
                "label": str(item.get("name") or ""),
                "count": int(_number_value(item.get("value")) or 0),
            }
            for item in distribution
            if isinstance(item, dict)
        ],
        "range_thresholds": {
            "upper": _number_value(payload.get("firstScoreUpper")),
            "middle_upper": _number_value(payload.get("secondScoreUpper")),
            "middle_lower": _number_value(payload.get("secondScoreLower")),
            "lower": _number_value(payload.get("thirdScoreUpper")),
        },
    }


def parse_grade_visibility_payload(payload: dict[str, Any]) -> dict[str, Any]:
    raw_settings = payload.get("openScore")
    raw_classes = payload.get("data")
    if not isinstance(raw_settings, dict) or not isinstance(raw_classes, list):
        raise ChaoxingAPIError("grade-visibility response had an invalid shape")
    classes: list[dict[str, Any]] = []
    for raw in raw_classes:
        if not isinstance(raw, dict):
            continue
        clazz_id = str(raw.get("id") or "").strip()
        if not clazz_id:
            continue
        classes.append(
            {
                "clazz_id": clazz_id,
                "clazz_name": str(raw.get("name") or ""),
                "student_count": int(_number_value(raw.get("studentCount")) or 0),
                "scores_visible": _number_value(raw.get("visibleScore")) == 1,
                "archived": _number_value(raw.get("isFiled")) == 1,
                "active": bool(raw.get("isStart")),
            }
        )
    return {
        "scheduled_open": bool(raw_settings.get("openCheck")),
        "open_at": str(raw_settings.get("openScoreTime") or ""),
        "students_can_view_rank": bool(raw_settings.get("viewRankCheck")),
        "students_can_view_class_average": bool(raw_settings.get("viewClazzAvgScoreCheck")),
        "class_count": len(classes),
        "visible_class_count": sum(item["scores_visible"] for item in classes),
        "classes": classes,
    }


def parse_grade_score_payload(
    payload: dict[str, Any],
    components: list[dict[str, Any]],
    *,
    raw_scores: bool,
) -> tuple[list[dict[str, Any]], dict[str, int]]:
    if payload.get("code") not in (None, 0):
        raise ChaoxingAPIError(str(payload.get("msg") or "grade-list request failed"))
    raw_rows = payload.get("data")
    page = payload.get("pageInfo")
    if not isinstance(raw_rows, list) or not isinstance(page, dict):
        raise ChaoxingAPIError("grade-list response had an invalid shape")

    students: list[dict[str, Any]] = []
    for raw in raw_rows:
        if not isinstance(raw, dict):
            continue
        custom_score = _number_value(raw.get("customScore"))
        if custom_score == -1:
            custom_score = None
        component_scores = [
            {
                **component,
                "value": _number_value(raw.get(str(component["field"]))),
                "value_kind": "raw_score" if raw_scores else "weighted_contribution",
            }
            for component in components
        ]
        students.append(
            {
                "index": int(_number_value(raw.get("dataNo")) or len(students) + 1),
                "person_id": str(raw.get("personId") or raw.get("personid") or ""),
                "user_id": str(raw.get("userid") or ""),
                "student_no": str(raw.get("loginName") or ""),
                "student_name": str(raw.get("userName") or ""),
                "photo_url": str(raw.get("img") or ""),
                "total_score": None if raw_scores else _number_value(raw.get("score")),
                "custom_score": custom_score,
                "component_scores": component_scores,
            }
        )

    page_info = {
        "page": int(_number_value(page.get("currentPageNo")) or 1),
        "page_size": int(_number_value(page.get("pagesize")) or len(students)),
        "total_pages": int(_number_value(page.get("totalPage")) or 1),
        "total_count": int(_number_value(page.get("totalResult")) or len(students)),
    }
    return students, page_info


def _progress_fraction(raw: Any) -> dict[str, Any]:
    display = str(raw if raw is not None else "").strip()
    match = re.fullmatch(r"\s*(\d+)\s*/\s*(\d+)\s*", display)
    return {
        "completed": int(match.group(1)) if match else None,
        "total": int(match.group(2)) if match else None,
        "display": display,
    }


def _duration_minutes(raw: Any) -> int | float | None:
    if isinstance(raw, (int, float)):
        return _number_value(raw)
    text = str(raw if raw is not None else "").strip()
    if not text:
        return None
    hours = re.search(r"(\d+(?:\.\d+)?)\s*小时", text)
    minutes = re.search(r"(\d+(?:\.\d+)?)\s*分钟", text)
    if not hours and not minutes:
        return _number_value(text)
    total = (float(hours.group(1)) * 60 if hours else 0) + (
        float(minutes.group(1)) if minutes else 0
    )
    return int(total) if total.is_integer() else total


def parse_learning_progress_payload(
    payload: dict[str, Any],
    custom_components: list[dict[str, Any]] | None = None,
) -> tuple[list[dict[str, Any]], dict[str, int]]:
    if payload.get("code") not in (None, 0):
        raise ChaoxingAPIError(str(payload.get("msg") or "learning-progress request failed"))
    raw_rows = payload.get("data")
    page = payload.get("pageInfo")
    if not isinstance(raw_rows, list) or not isinstance(page, dict):
        raise ChaoxingAPIError("learning-progress response had an invalid shape")
    components = custom_components or []

    students: list[dict[str, Any]] = []
    for raw in raw_rows:
        if not isinstance(raw, dict):
            continue
        students.append(
            {
                "index": int(_number_value(raw.get("dataNo")) or len(students) + 1),
                "person_id": str(raw.get("personId") or raw.get("personid") or ""),
                "user_id": str(raw.get("userid") or ""),
                "student_no": str(raw.get("loginName") or ""),
                "student_name": str(raw.get("userName") or ""),
                "photo_url": str(raw.get("img") or ""),
                "task_points": _progress_fraction(raw.get("job")),
                "video_view_minutes": _duration_minutes(raw.get("totalTime")),
                "chapter_quizzes": _progress_fraction(raw.get("ceyan")),
                "homeworks": _progress_fraction(raw.get("work")),
                "exams": _progress_fraction(raw.get("exam")),
                "attendance": _progress_fraction(raw.get("attend")),
                "group_task_value": _number_value(raw.get("pbl")),
                "course_activity_points": _number_value(raw.get("active")),
                "discussion_activity_value": _number_value(raw.get("bbs")),
                "chapter_learning_times": _number_value(raw.get("visitTime")),
                "reading_minutes": _duration_minutes(raw.get("readTime")),
                "live_minutes": _duration_minutes(raw.get("liveTime")),
                "classroom_minutes": _duration_minutes(raw.get("cxClass")),
                "custom_metrics": [
                    {
                        **component,
                        "value": raw.get(str(component["field"])),
                    }
                    for component in components
                    if str(component["field"]) in raw
                ],
            }
        )

    page_info = {
        "page": int(_number_value(page.get("currentPageNo")) or 1),
        "page_size": int(_number_value(page.get("pagesize")) or len(students)),
        "total_pages": int(_number_value(page.get("totalPage")) or 1),
        "total_count": int(_number_value(page.get("totalResult")) or len(students)),
    }
    return students, page_info


def parse_study_monitor_payload(
    payload: dict[str, Any],
) -> tuple[list[dict[str, Any]], dict[str, int], int]:
    if payload.get("code") not in (None, 0):
        raise ChaoxingAPIError(str(payload.get("msg") or "study-monitor request failed"))
    raw_rows = payload.get("data")
    page = payload.get("pageInfo")
    if not isinstance(raw_rows, list) or not isinstance(page, dict):
        raise ChaoxingAPIError("study-monitor response had an invalid shape")
    students: list[dict[str, Any]] = []
    for raw in raw_rows:
        if not isinstance(raw, dict):
            continue
        abnormal = _number_value(raw.get("studyStatus")) == 1
        deal_type = _number_value(raw.get("dealType"))
        deal_count = int(_number_value(raw.get("dealCount")) or 0)
        students.append(
            {
                "index": int(_number_value(raw.get("dataNo")) or len(students) + 1),
                "person_id": str(raw.get("personId") or raw.get("personid") or ""),
                "user_id": str(raw.get("userid") or ""),
                "student_no": str(raw.get("loginName") or ""),
                "student_name": str(raw.get("userName") or ""),
                "photo_url": str(raw.get("img") or ""),
                "study_status": "abnormal" if abnormal else "normal",
                "anomaly_type_code": int(_number_value(raw.get("unnormalType")) or 0),
                "anomaly_type": str(raw.get("unnormalTypeDescript") or ""),
                "anomaly_count": int(_number_value(raw.get("unnormalCount")) or 0),
                "processed_count": deal_count,
                "processing_status": "processed" if deal_type == 1 else "unprocessed",
                "can_clear_anomaly": abnormal and deal_count == 0,
            }
        )
    page_info = {
        "page": int(_number_value(page.get("currentPageNo")) or 1),
        "page_size": int(_number_value(page.get("pagesize")) or len(students)),
        "total_pages": int(_number_value(page.get("totalPage")) or 1),
        "total_count": int(_number_value(page.get("totalResult")) or len(students)),
    }
    appeal_count = int(_number_value(payload.get("appealCount")) or 0)
    return students, page_info, appeal_count


def resolve_study_monitor_student(students: list[dict[str, Any]], query: str) -> dict[str, Any]:
    return resolve_class_student(students, query)


def parse_discussion_topic(raw: dict[str, Any]) -> dict[str, Any]:
    images = raw.get("content_imgs", raw.get("img_data"))
    if not isinstance(images, list):
        images = []
    last_reply = raw.get("lastReply")
    if not isinstance(last_reply, dict):
        last_reply = {}
    quote_info = raw.get("quoteInfo")
    if not isinstance(quote_info, dict):
        quote_info = {}
    permissions = raw.get("userAuth")
    if not isinstance(permissions, dict):
        permissions = {}
    return {
        "topic_id": str(raw.get("id") or "").strip(),
        "uuid": str(raw.get("uuid") or "").strip(),
        "bbs_id": str(raw.get("bbsid") or ""),
        "title": str(raw.get("title") or "").strip(),
        "content": str(raw.get("text_content") or raw.get("content") or "").strip(),
        "creator_name": str(raw.get("createrName") or ""),
        "creator_id": str(raw.get("createrId") or ""),
        "creator_puid": str(raw.get("create_puid") or raw.get("puid") or ""),
        "created_at": raw.get("create_time"),
        "updated_at": raw.get("update_time"),
        "formatted_time": str(raw.get("ftime") or ""),
        "reply_count": raw.get("reply_count", raw.get("s_replycount")),
        "read_count": raw.get("readPersonCount", raw.get("s_readcount")),
        "praise_count": raw.get("praise_count"),
        "is_praised": str(raw.get("isPraise") or "0").lower() in {"1", "true"},
        "is_choice": str(raw.get("choice") or "0").lower() in {"1", "true"},
        "is_top": bool(raw.get("top")),
        "topic_type": raw.get("topicType"),
        "chapter_id": str(raw.get("chapterId") or ""),
        "folder_id": str(raw.get("folderId") or ""),
        "class_tags": str(raw.get("tags") or ""),
        "class_reply_counts": quote_info.get("classReplyCount")
        if isinstance(quote_info.get("classReplyCount"), dict)
        else {},
        "reply_setting": quote_info.get("replySetting")
        if isinstance(quote_info.get("replySetting"), dict)
        else {},
        "share_url": str(raw.get("shareUrl") or ""),
        "images": images,
        "score": raw.get("score") if isinstance(raw.get("score"), dict) else {},
        "permissions": permissions,
        "last_reply": {
            "reply_id": str(last_reply.get("replyId") or ""),
            "name": str(last_reply.get("name") or ""),
            "time": last_reply.get("time"),
            "formatted_time": str(last_reply.get("formattime") or ""),
            "content": str(last_reply.get("content") or ""),
        }
        if last_reply
        else None,
    }


def parse_discussion_payload(
    payload: dict[str, Any],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    topics: list[dict[str, Any]] = []
    for raw in payload.get("datas") or []:
        if not isinstance(raw, dict):
            continue
        topic = parse_discussion_topic(raw)
        if not topic["topic_id"] and not topic["uuid"]:
            continue
        topics.append(topic)

    folders: list[dict[str, Any]] = []
    for raw in payload.get("folder_list") or []:
        if not isinstance(raw, dict):
            continue
        folders.append(
            {
                "folder_id": str(raw.get("id") or ""),
                "folder_uuid": str(raw.get("folder_uuid") or ""),
                "parent_id": str(raw.get("pid") or ""),
                "name": str(raw.get("name") or ""),
                "class_tag": str(raw.get("ftag") or ""),
            }
        )
    return topics, folders


def resolve_discussion_topic(topics: list[dict[str, Any]], query: str) -> dict[str, Any]:
    normalized = query.strip().lower()
    if not normalized:
        raise ChaoxingAPIError("topic index, title, topic_id, or uuid is required")
    for key in ("topic_id", "uuid", "index"):
        exact = [topic for topic in topics if str(topic.get(key, "")).strip().lower() == normalized]
        if len(exact) == 1:
            return exact[0]
    exact_titles = [
        topic for topic in topics if str(topic.get("title", "")).strip().lower() == normalized
    ]
    if len(exact_titles) == 1:
        return exact_titles[0]
    partial = [
        topic for topic in topics if normalized in str(topic.get("title", "")).strip().lower()
    ]
    if len(partial) == 1:
        return partial[0]
    if not partial:
        raise ChaoxingAPIError(f"discussion topic not found: {query}")
    candidates = ", ".join(
        f"{topic.get('index')}. {topic.get('title')} ({topic.get('topic_id')})" for topic in partial
    )
    raise ChaoxingAPIError(f"multiple discussion topic matches: {candidates}")


def resolve_discussion_reply(replies: list[dict[str, Any]], query: str) -> dict[str, Any]:
    flattened: list[dict[str, Any]] = []

    def visit(items: list[dict[str, Any]]) -> None:
        for item in items:
            copy = dict(item)
            children = copy.pop("replies", [])
            copy["index"] = len(flattened) + 1
            flattened.append(copy)
            if isinstance(children, list):
                visit([child for child in children if isinstance(child, dict)])

    visit(replies)
    normalized = query.strip().lower()
    if not normalized:
        raise ChaoxingAPIError("reply index, reply_id, uuid, or content is required")
    for key in ("reply_id", "uuid", "index"):
        exact = [
            reply for reply in flattened if str(reply.get(key, "")).strip().lower() == normalized
        ]
        if len(exact) == 1:
            return exact[0]
    exact_content = [
        reply for reply in flattened if str(reply.get("content", "")).strip().lower() == normalized
    ]
    if len(exact_content) == 1:
        return exact_content[0]
    partial = [
        reply for reply in flattened if normalized in str(reply.get("content", "")).strip().lower()
    ]
    if len(partial) == 1:
        return partial[0]
    if not partial:
        raise ChaoxingAPIError(f"discussion reply not found: {query}")
    candidates = ", ".join(
        f"{reply.get('index')}. {reply.get('content', '')[:40]} ({reply.get('reply_id')})"
        for reply in partial
    )
    raise ChaoxingAPIError(f"multiple discussion reply matches: {candidates}")


def parse_discussion_replies(payload: dict[str, Any], *, is_top: bool) -> list[dict[str, Any]]:
    def normalize(raw: dict[str, Any], top: bool) -> dict[str, Any]:
        attachments = raw.get("attachment")
        if not isinstance(attachments, list):
            attachments = []
        images = raw.get("img_data")
        if not isinstance(images, list):
            images = []
        children = raw.get("second_data")
        if not isinstance(children, list):
            children = []
        return {
            "reply_id": str(raw.get("id") or ""),
            "uuid": str(raw.get("uuid") or ""),
            "topic_id": str(raw.get("topic_id") or ""),
            "parent_id": str(raw.get("parent_id") or ""),
            "content": str(raw.get("content") or "").strip(),
            "creator_name": str(raw.get("creater_name") or ""),
            "creator_id": str(raw.get("creater_id") or ""),
            "creator_puid": str(raw.get("create_puid") or raw.get("puid") or ""),
            "created_at": raw.get("create_time"),
            "formatted_time": str(raw.get("ftime") or ""),
            "floor": str(raw.get("floor") or ""),
            "class_tag": str(raw.get("tag") or ""),
            "is_top": top or bool(raw.get("top")),
            "is_anonymous": bool(raw.get("isAnonymous")),
            "praise_count": raw.get("praiseCount"),
            "score": raw.get("score") if isinstance(raw.get("score"), dict) else {},
            "images": images,
            "attachments": attachments,
            "replies": [normalize(child, False) for child in children if isinstance(child, dict)],
        }

    datas = payload.get("datas")
    if not isinstance(datas, list):
        return []
    return [normalize(raw, is_top) for raw in datas if isinstance(raw, dict)]


def parse_chapter_items(html: str) -> list[dict[str, Any]]:
    starts = [
        match.start()
        for match in re.finditer(
            r"<div\b[^>]*class=['\"][^'\"]*chapter_unit[^'\"]*['\"]",
            html,
            flags=re.IGNORECASE,
        )
    ]
    chapters: list[dict[str, Any]] = []
    for block_index, start in enumerate(starts):
        end = starts[block_index + 1] if block_index + 1 < len(starts) else len(html)
        block = html[start:end]
        parent_part = block.split("<!-- 第二级开始 -->", 1)[0]
        id_match = re.search(
            r"<input\b[^>]*class=['\"][^'\"]*firstNodeId[^'\"]*['\"][^>]*",
            parent_part,
            flags=re.IGNORECASE,
        )
        parent_id = html_attrs(id_match.group(0)).get("value", "") if id_match else ""
        title_match = re.search(
            r"<a\b[^>]*class=['\"][^'\"]*clicktitle[^'\"]*['\"][^>]*",
            parent_part,
            flags=re.IGNORECASE,
        )
        title_attrs = html_attrs(title_match.group(0)) if title_match else {}
        if not parent_id and not title_attrs.get("title"):
            continue
        number_match = re.search(
            r"catalog_num[\s\S]*?<em\b[^>]*>(.*?)</em>",
            parent_part,
            flags=re.IGNORECASE,
        )
        progress_match = re.search(
            r"catalog_ressbar_width[^>]*style=['\"][^'\"]*width\s*:\s*([\d.]+)%",
            parent_part,
            flags=re.IGNORECASE,
        )

        child_matches = list(
            re.finditer(
                r"onclick=['\"]toNew\(\s*['\"]([^'\"]+)['\"]\s*,\s*"
                r"['\"]([^'\"]+)['\"]\s*,\s*['\"]([^'\"]+)['\"]\s*\)",
                block,
                flags=re.IGNORECASE,
            )
        )
        children: list[dict[str, Any]] = []
        seen_children: set[str] = set()
        for child_index, match in enumerate(child_matches):
            knowledge_id = match.group(2)
            if knowledge_id in seen_children:
                continue
            seen_children.add(knowledge_id)
            next_start = (
                child_matches[child_index + 1].start()
                if child_index + 1 < len(child_matches)
                else len(block)
            )
            fragment = block[match.start() : next_start]
            child_title_match = re.search(
                r"<a\b[^>]*class=['\"][^'\"]*clicktitle[^'\"]*['\"][^>]*",
                fragment,
                flags=re.IGNORECASE,
            )
            child_title_attrs = html_attrs(child_title_match.group(0)) if child_title_match else {}
            child_number_match = re.search(
                r"<span\b[^>]*class=['\"][^'\"]*catalog_sbar[^'\"]*['\"][^>]*>"
                r"(.*?)</span>",
                fragment,
                flags=re.IGNORECASE | re.DOTALL,
            )
            task_match = re.search(
                r"<span\b[^>]*class=['\"][^'\"]*catalog_points_yi[^'\"]*['\"][^>]*>"
                r"(.*?)</span>",
                fragment,
                flags=re.IGNORECASE | re.DOTALL,
            )
            state_match = re.search(
                r"<span\b[^>]*class=['\"][^'\"]*state_text[^'\"]*['\"][^>]*>"
                r"(.*?)</span>",
                fragment,
                flags=re.IGNORECASE | re.DOTALL,
            )
            state_call = re.search(
                r"setOpenStatus\(\s*['\"]([^'\"]*)['\"]\s*,\s*"
                r"['\"]([^'\"]*)['\"]\s*,\s*['\"]([^'\"]*)['\"]\s*,\s*"
                r"['\"]([^'\"]*)['\"]\s*,\s*['\"]([^'\"]*)['\"]\s*,\s*"
                r"['\"]([^'\"]*)['\"]\s*\)",
                fragment,
                flags=re.IGNORECASE,
            )
            child_progress_match = re.search(
                r"catalog_ressbar_width[^>]*style=['\"][^'\"]*width\s*:\s*([\d.]+)%",
                fragment,
                flags=re.IGNORECASE,
            )
            task_text = html_text(task_match.group(1)) if task_match else ""
            raw_open_status = state_call.group(1).strip().lower() if state_call else ""
            open_timeout = state_call.group(5).strip() if state_call else ""
            configured_open_status = raw_open_status
            if (raw_open_status == "open" and open_timeout == "2") or (
                raw_open_status == "close" and open_timeout == "1"
            ):
                configured_open_status = "time"
            children.append(
                {
                    "chapter_id": knowledge_id,
                    "number": html_text(child_number_match.group(1)) if child_number_match else "",
                    "title": child_title_attrs.get("title", ""),
                    "task_point_count": int(task_text) if task_text.isdigit() else 0,
                    "open_status": html_text(state_match.group(1)) if state_match else "",
                    "open_status_code": raw_open_status,
                    "configured_open_status": configured_open_status,
                    "open_begin": state_call.group(3) if state_call else "",
                    "open_end": state_call.group(4) if state_call else "",
                    "open_timeout": open_timeout,
                    "time_end_review": state_call.group(6) == "1" if state_call else False,
                    "progress_percent": float(child_progress_match.group(1))
                    if child_progress_match
                    else 0.0,
                    "study_url": append_query_params(
                        f"{MOOC2_BASE_URL}/mooc2-ans/mycourse/teacherstudy",
                        {
                            "chapterId": knowledge_id,
                            "courseId": match.group(1),
                            "clazzid": match.group(3),
                        },
                    ),
                }
            )
        chapters.append(
            {
                "chapter_id": parent_id,
                "number": html_text(number_match.group(1)) if number_match else "",
                "title": title_attrs.get("title", ""),
                "progress_percent": float(progress_match.group(1)) if progress_match else 0.0,
                "task_point_count": sum(child["task_point_count"] for child in children),
                "children": children,
            }
        )
    return chapters


def parse_chapter_editor_tree(html: str) -> dict[str, Any]:
    marker = re.search(
        r"\bans_config\s*=\s*\{\s*courseid\s*:\s*([^,]+),\s*root\s*:\s*",
        html,
        flags=re.IGNORECASE,
    )
    if not marker:
        raise ChaoxingAPIError("chapter editor did not expose its chapter tree")
    try:
        root, _end = json.JSONDecoder().raw_decode(html[marker.end() :].lstrip())
    except json.JSONDecodeError as exc:
        raise ChaoxingAPIError("chapter editor exposed invalid chapter-tree data") from exc
    if not isinstance(root, dict):
        raise ChaoxingAPIError("chapter editor exposed invalid chapter-tree data")

    flat: list[dict[str, Any]] = []

    def normalize(
        raw: dict[str, Any],
        *,
        parent_id: str,
        depth: int,
        position: int,
        number_parts: tuple[int, ...],
    ) -> dict[str, Any]:
        chapter_id = str(raw.get("id") or "")
        children_raw = raw.get("children")
        if not isinstance(children_raw, list):
            children_raw = []
        item: dict[str, Any] = {
            "index": len(flat) + 1,
            "chapter_id": chapter_id,
            "title": unescape(str(raw.get("text") or "")).strip(),
            "parent_id": parent_id,
            "depth": depth,
            "position": position,
            "number": ".".join(str(part) for part in number_parts),
            "has_children": bool(children_raw),
            "children": [],
        }
        flat.append(item)
        item["children"] = [
            normalize(
                child,
                parent_id=chapter_id,
                depth=depth + 1,
                position=child_position,
                number_parts=(*number_parts, child_position),
            )
            for child_position, child in enumerate(children_raw, start=1)
            if isinstance(child, dict)
        ]
        return item

    children = root.get("children")
    if not isinstance(children, list):
        children = []
    tree = [
        normalize(
            child,
            parent_id="0",
            depth=1,
            position=position,
            number_parts=(position,),
        )
        for position, child in enumerate(children, start=1)
        if isinstance(child, dict)
    ]
    course_id = str(marker.group(1)).strip().strip("'\"")
    return {
        "course_id": course_id,
        "root_id": str(root.get("id") or "0"),
        "chapter_count": len(flat),
        "max_depth": max((int(item["depth"]) for item in flat), default=0),
        "chapters": tree,
        "flat_chapters": flat,
    }


def resolve_chapter_editor_item(items: list[dict[str, Any]], query: str) -> dict[str, Any]:
    return _resolve_titled_item(items, query, id_key="chapter_id", label="chapter")


def parse_chapter_cards(payload: dict[str, Any]) -> list[dict[str, Any]]:
    raw_items = payload.get("data")
    if not isinstance(raw_items, list):
        return []
    cards: list[dict[str, Any]] = []
    for raw in raw_items:
        if not isinstance(raw, dict):
            continue
        description_html = str(raw.get("description") or "")
        attachment_manifest = raw.get("attachments")
        if isinstance(attachment_manifest, str):
            try:
                attachment_manifest = json.loads(attachment_manifest)
            except json.JSONDecodeError:
                attachment_manifest = []
        if not isinstance(attachment_manifest, list):
            attachment_manifest = []
        cards.append(
            {
                "index": len(cards) + 1,
                "card_id": str(raw.get("id") or ""),
                "chapter_id": str(raw.get("nodeid") or ""),
                "title": str(raw.get("title") or "").strip(),
                "content_html": description_html,
                "content": html_text(description_html),
                "images": parse_content_images(description_html),
                "attachments": parse_attachment_iframes(description_html),
                "attachment_manifest": [
                    item for item in attachment_manifest if isinstance(item, dict)
                ],
            }
        )
    return cards


def resolve_chapter_card(items: list[dict[str, Any]], query: str) -> dict[str, Any]:
    return _resolve_titled_item(items, query, id_key="card_id", label="chapter card")


def resolve_resource_item(
    items: list[dict[str, Any]],
    query: str,
    *,
    require_folder: bool | None = None,
) -> dict[str, Any]:
    candidates = items
    if require_folder is not None:
        candidates = [item for item in items if bool(item.get("is_folder")) is require_folder]
    normalized = str(query or "").strip().lower()
    if not normalized:
        kind = "folder" if require_folder else "resource"
        raise ChaoxingAPIError(f"{kind} index, name, path, or ID is required")
    for key in ("data_id", "index"):
        exact = [
            item for item in candidates if str(item.get(key) or "").strip().lower() == normalized
        ]
        if len(exact) == 1:
            return exact[0]
    exact = [
        item
        for item in candidates
        if normalized
        in {
            str(item.get("name") or "").strip().lower(),
            str(item.get("path") or "").strip().lower(),
        }
    ]
    if len(exact) == 1:
        return exact[0]
    partial = [
        item
        for item in candidates
        if normalized in str(item.get("name") or "").strip().lower()
        or normalized in str(item.get("path") or "").strip().lower()
    ]
    if len(partial) == 1:
        return partial[0]
    kind = "resource folder" if require_folder else "resource"
    matches = exact or partial
    if not matches:
        raise ChaoxingAPIError(f"{kind} not found: {query}")
    choices = ", ".join(
        f"{item.get('index')}. {item.get('path') or item.get('name')} ({item.get('data_id')})"
        for item in matches[:20]
    )
    raise ChaoxingAPIError(f"multiple {kind} matches: {choices}")


def parse_course_data_items(html: str) -> list[dict[str, Any]]:
    starts = [
        match.start()
        for match in re.finditer(
            r"<ul\b[^>]*class=['\"][^'\"]*dataBody_td[^'\"]*['\"]",
            html,
            flags=re.IGNORECASE,
        )
    ]
    items: list[dict[str, Any]] = []
    for index, start in enumerate(starts):
        end = starts[index + 1] if index + 1 < len(starts) else len(html)
        block = html[start:end]
        opening = re.search(r"<ul\b[^>]*>", block, flags=re.IGNORECASE | re.DOTALL)
        attrs = html_attrs(opening.group(0)) if opening else {}
        data_id = str(attrs.get("id") or "")
        if not data_id:
            continue
        title_match = re.search(
            r"<a\b[^>]*class=['\"][^'\"]*rename_title[^'\"]*['\"][^>]*",
            block,
            flags=re.IGNORECASE | re.DOTALL,
        )
        title_attrs = html_attrs(title_match.group(0)) if title_match else {}
        visibility_match = re.search(
            r"<span\b[^>]*class=['\"][^'\"]*hideText[^'\"]*['\"][^>]*",
            block,
            flags=re.IGNORECASE | re.DOTALL,
        )
        visibility_attrs = html_attrs(visibility_match.group(0)) if visibility_match else {}
        reader_match = re.search(
            rf"<a\b[^>]*id=['\"]reader_{re.escape(data_id)}['\"][^>]*>(.*?)</a>",
            block,
            flags=re.IGNORECASE | re.DOTALL,
        )
        download_count_match = re.search(
            r"dataBody_down[^>]*>[\s\S]{0,800}?<div\b[^>]*class=['\"][^'\"]*"
            r"dataBody_read_select[^'\"]*['\"][^>]*>\s*([\d]+|-)",
            block,
            flags=re.IGNORECASE,
        )
        size_match = re.search(
            r"<li\b[^>]*class=['\"][^'\"]*dataBody_size[^'\"]*['\"][^>]*>"
            r"(.*?)</li>",
            block,
            flags=re.IGNORECASE | re.DOTALL,
        )
        creator_match = re.search(
            r"<li\b[^>]*class=['\"][^'\"]*dataBody_creater[^'\"]*['\"][^>]*>"
            r"(.*?)</li>",
            block,
            flags=re.IGNORECASE | re.DOTALL,
        )
        time_match = re.search(
            r"<li\b[^>]*class=['\"][^'\"]*dataBody_time[^'\"]*['\"][^>]*>"
            r"(.*?)</li>",
            block,
            flags=re.IGNORECASE | re.DOTALL,
        )
        download_match = re.search(
            r"href=['\"]([^'\"]*?/coursedata/downloadData\?[^'\"]+)['\"]",
            block,
            flags=re.IGNORECASE,
        )
        top_match = re.search(
            r"toppingButton\(\s*['\"]?([^,'\"\s)]+)['\"]?\s*,\s*"
            r"['\"]?([^,'\"\s)]+)['\"]?\s*,\s*"
            r"['\"]?([^,'\"\s)]+)['\"]?\s*,\s*"
            r"['\"]?([^,'\"\s)]+)['\"]?\s*\)",
            block,
            flags=re.IGNORECASE,
        )
        cancel_top_match = re.search(
            rf"cancelTopSetting\(\s*['\"]?{re.escape(data_id)}['\"]?\s*\)",
            block,
            flags=re.IGNORECASE,
        )
        data_type = str(attrs.get("type") or "")
        name = title_attrs.get("title") or attrs.get("dataname", "")
        items.append(
            {
                "data_id": data_id,
                "index": index + 1,
                "name": name,
                "title": name,
                "data_type": data_type,
                "is_folder": data_type.lower() == "afolder",
                "is_open": str(attrs.get("isopen") or ""),
                "source": str(attrs.get("source") or ""),
                "order_id": str(attrs.get("order") or ""),
                "root_id": top_match.group(4) if top_match else "",
                "is_top": bool(cancel_top_match),
                "visibility": visibility_attrs.get("title", ""),
                "object_id": str(attrs.get("objectid") or ""),
                "source_url": str(attrs.get("url") or ""),
                "load_url": str(attrs.get("loadurl") or ""),
                "can_download": str(attrs.get("isdown") or "") == "1",
                "download_url": urljoin(MOOC2_BASE_URL, unescape(download_match.group(1)))
                if download_match
                else "",
                "reader_count": int(html_text(reader_match.group(1)))
                if reader_match and html_text(reader_match.group(1)).isdigit()
                else 0,
                "download_count": int(download_count_match.group(1))
                if download_count_match and download_count_match.group(1).isdigit()
                else 0,
                "size": html_text(size_match.group(1)) if size_match else "",
                "creator_name": html_text(creator_match.group(1)) if creator_match else "",
                "created_at": html_text(time_match.group(1)) if time_match else "",
            }
        )
    return items


def parse_resource_labels(html: str) -> list[dict[str, Any]]:
    labels: list[dict[str, Any]] = []
    for match in re.finditer(
        r"(<li\b[^>]*class=['\"][^'\"]*\btopiclabelli\b[^'\"]*['\"][^>]*>)"
        r"([\s\S]*?)</li>",
        html,
        flags=re.IGNORECASE,
    ):
        attrs = html_attrs(match.group(1))
        label_id = str(attrs.get("data") or attrs.get("data-id") or "").strip()
        if not label_id:
            continue
        block = match.group(2)
        name_match = re.search(
            r"<div\b[^>]*class=['\"][^'\"]*\btopicname\b[^'\"]*['\"][^>]*>"
            r"([\s\S]*?)</div>",
            block,
            flags=re.IGNORECASE,
        )
        checkbox_match = re.search(
            r"<input\b[^>]*class=['\"][^'\"]*\btopicLabelCheckBox\b[^'\"]*['\"][^>]*>",
            block,
            flags=re.IGNORECASE,
        )
        checkbox = checkbox_match.group(0) if checkbox_match else ""
        name = html_text(name_match.group(1)) if name_match else ""
        labels.append(
            {
                "index": len(labels) + 1,
                "label_id": label_id,
                "name": name,
                "title": name,
                "assigned": bool(re.search(r"\bchecked\b", checkbox, flags=re.IGNORECASE)),
                "editable": bool(re.search(r"\bedittopiclabel\b", block, flags=re.IGNORECASE)),
                "deletable": bool(re.search(r"\bdeletetopiclabel\b", block, flags=re.IGNORECASE)),
            }
        )
    return labels


def parse_resource_import_courses(html: str) -> list[dict[str, Any]]:
    courses: list[dict[str, Any]] = []
    for match in re.finditer(r"<li\b[^>]*>.*?</li>", html, flags=re.IGNORECASE | re.DOTALL):
        opening = re.search(r"<li\b[^>]*>", match.group(0), flags=re.IGNORECASE)
        attrs = html_attrs(opening.group(0)) if opening else {}
        course_id = str(attrs.get("data") or attrs.get("data-id") or "").strip()
        cpi = str(attrs.get("data-cpi") or "").strip()
        if not course_id:
            onclick = str(attrs.get("onclick") or "")
            call = re.search(
                r"intoCourseDataPop\(\s*['\"]?([^,'\"\s)]+)['\"]?\s*,\s*"
                r"['\"]?([^,'\"\s)]+)['\"]?",
                onclick,
                flags=re.IGNORECASE,
            )
            if call:
                course_id = call.group(1)
                cpi = cpi or call.group(2)
        if not course_id:
            continue
        name = html_text(match.group(0))
        courses.append(
            {
                "index": len(courses) + 1,
                "course_id": course_id,
                "cpi": cpi,
                "course_name": name,
                "title": name,
            }
        )
    return courses


def parse_resource_import_items(payload: dict[str, Any]) -> dict[str, Any]:
    data = payload.get("data")
    if not isinstance(data, dict):
        data = {}
    raw_items = data.get("courseDatas")
    if not isinstance(raw_items, list):
        raw_items = []
    items: list[dict[str, Any]] = []
    for raw in raw_items:
        if not isinstance(raw, dict):
            continue
        data_type = str(raw.get("type") or "").lstrip(".")
        name = str(raw.get("name") or "").strip()
        item = {
            "index": len(items) + 1,
            "data_id": str(raw.get("id") or ""),
            "name": name,
            "title": name,
            "data_type": data_type,
            "is_folder": str(raw.get("xtype") or "").lower() == "dir"
            or data_type.lower() == "afolder",
            "object_id": str(raw.get("objectid") or ""),
            "size": str(raw.get("hsize") or raw.get("size") or ""),
            "insert_time": raw.get("insertTime"),
            "order_id": str(raw.get("orderId") or ""),
            "is_pinned": bool(raw.get("top")),
            "uploader": str(raw.get("uploader") or ""),
            "origin_uploader": str(raw.get("originUploader") or ""),
            "school": str(raw.get("school") or ""),
            "topic_names": str(raw.get("topicNames") or ""),
        }
        items.append(item)
    try:
        total_pages = int(data.get("total") or 1)
    except (TypeError, ValueError):
        total_pages = 1
    try:
        server_page_size = int(data.get("size") or len(items))
    except (TypeError, ValueError):
        server_page_size = len(items)
    return {
        "total_pages": max(1, total_pages),
        "server_page_size": server_page_size,
        "items": items,
    }


def load_cookie_records(path: Path) -> list[dict[str, Any]]:
    if not path.exists():
        raise ChaoxingAPIError(f"cookie file not found: {path}")
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise ChaoxingAPIError(f"invalid cookie file: {path}") from exc
    cookies = payload.get("cookies") if isinstance(payload, dict) else payload
    if not isinstance(cookies, list):
        raise ChaoxingAPIError("cookie file must contain a cookies array")
    return [item for item in cookies if isinstance(item, dict)]


def cookie_file_payload(session: requests.Session) -> dict[str, Any]:
    cookies: list[dict[str, Any]] = []
    for cookie in session.cookies:
        cookies.append(
            {
                "name": cookie.name,
                "value": cookie.value,
                "domain": cookie.domain,
                "path": cookie.path,
                "secure": bool(cookie.secure),
                "expires": cookie.expires,
                "httpOnly": cookie.has_nonstandard_attr("HttpOnly"),
            }
        )
    return {
        "created_at": datetime.now().astimezone().isoformat(timespec="seconds"),
        "cookies": cookies,
    }


def save_cookie_file_atomic(session: requests.Session, path: Path) -> int:
    """Persist a verified login without exposing values or clobbering on failed login."""
    temporary = path.with_name(f".{path.name}.{uuid4().hex}.tmp")
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        temporary.write_text(
            json.dumps(cookie_file_payload(session), ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )
        temporary.chmod(0o600)
        temporary.replace(path)
    except OSError as exc:
        raise ChaoxingAPIError(f"cannot save Chaoxing cookie file: {exc}") from exc
    finally:
        temporary.unlink(missing_ok=True)
    return len(session.cookies)


def validated_chaoxing_url(value: str, label: str) -> str:
    normalized = value.strip()
    parsed = urlparse(normalized)
    hostname = (parsed.hostname or "").lower()
    if parsed.scheme != "https" or not (
        hostname == "chaoxing.com" or hostname.endswith(".chaoxing.com")
    ):
        raise ChaoxingAPIError(f"{label} must be an HTTPS chaoxing.com URL")
    return normalized


def parse_teaching_courses(data: dict[str, Any]) -> list[dict[str, Any]]:
    courses: list[dict[str, Any]] = []
    seen: set[str] = set()
    for channel in data.get("channelList", []):
        if not isinstance(channel, dict):
            continue
        content = channel.get("content") or {}
        if not isinstance(content, dict):
            continue
        clazzes = content.get("clazz")
        if not isinstance(clazzes, list) or not clazzes:
            continue
        course_id = str(content.get("id") or "").strip()
        if not course_id or course_id in seen:
            continue
        seen.add(course_id)
        classes = [
            {
                "index": index,
                "clazz_id": str(clazz.get("clazzId") or "").strip(),
                "clazz_name": str(clazz.get("clazzName") or "").strip(),
                "student_count": clazz.get("clazzStudentCount"),
                "chat_id": str(clazz.get("chatid") or "").strip(),
                "state": clazz.get("state"),
            }
            for index, clazz in enumerate(clazzes, 1)
            if isinstance(clazz, dict)
        ]
        courses.append(
            {
                "index": len(courses) + 1,
                "course_id": course_id,
                "course_name": str(content.get("name") or "").strip(),
                "teacher": str(content.get("teacherfactor") or "").strip(),
                "term": str(content.get("schools") or "").strip(),
                "cpi": str(channel.get("cpi") or content.get("cpi") or "").strip(),
                "class_count": len(classes),
                "classes": classes,
            }
        )
    return courses


def parse_learning_courses(html: str) -> list[dict[str, Any]]:
    """Parse the current account's student-role course cards.

    The student course list is rendered as nested ``div`` cards rather than a
    JSON API.  We first identify top-level card starts by the stable
    ``learnCourse`` class and ``c_<course id>`` element ID, then parse each
    bounded slice.  This avoids depending on presentation-only whitespace or
    exact nested markup.
    """

    starts: list[tuple[int, dict[str, str]]] = []
    for match in re.finditer(r"<div\b[^>]*>", str(html or ""), flags=re.IGNORECASE | re.DOTALL):
        attrs = html_attrs(match.group(0))
        classes = {value.casefold() for value in attrs.get("class", "").split()}
        if "learncourse" not in classes or not attrs.get("id", "").startswith("c_"):
            continue
        starts.append((match.start(), attrs))

    courses: list[dict[str, Any]] = []
    for position, (start, card_attrs) in enumerate(starts):
        end = starts[position + 1][0] if position + 1 < len(starts) else len(html)
        block = html[start:end]
        inputs: list[dict[str, str]] = [
            html_attrs(match.group(0))
            for match in re.finditer(r"<input\b[^>]*>", block, flags=re.IGNORECASE | re.DOTALL)
        ]

        def input_value(
            *names: str,
            source_inputs: tuple[dict[str, str], ...] = tuple(inputs),
        ) -> str:
            expected = {name.casefold() for name in names}
            for attrs in source_inputs:
                identifiers = {
                    attrs.get("name", "").casefold(),
                    attrs.get("id", "").casefold(),
                    *{value.casefold() for value in attrs.get("class", "").split()},
                }
                if expected & identifiers:
                    return str(attrs.get("value") or "").strip()
            return ""

        anchor_match = re.search(
            r"<a\b(?P<attrs>[^>]*)>",
            block,
            flags=re.IGNORECASE | re.DOTALL,
        )
        entry_url = ""
        for candidate in re.finditer(
            r"<a\b(?P<attrs>[^>]*)>", block, flags=re.IGNORECASE | re.DOTALL
        ):
            href = html_attrs(candidate.group("attrs")).get("href", "")
            if "stucoursemiddle" in href:
                anchor_match = candidate
                entry_url = href.strip()
                break
        if not entry_url and anchor_match:
            entry_url = html_attrs(anchor_match.group("attrs")).get("href", "").strip()

        name = ""
        name_match = re.search(
            r"<span\b(?P<attrs>[^>]*)>(?P<body>.*?)</span>",
            block,
            flags=re.IGNORECASE | re.DOTALL,
        )
        for candidate in re.finditer(
            r"<span\b(?P<attrs>[^>]*)>(?P<body>.*?)</span>",
            block,
            flags=re.IGNORECASE | re.DOTALL,
        ):
            attrs = html_attrs(candidate.group("attrs"))
            if "course-name" in attrs.get("class", "").casefold().split():
                name_match = candidate
                name = str(attrs.get("title") or html_text(candidate.group("body"))).strip()
                break
        if not name and name_match:
            attrs = html_attrs(name_match.group("attrs"))
            name = str(attrs.get("title") or html_text(name_match.group("body"))).strip()

        teacher = ""
        term = ""
        for paragraph in re.finditer(
            r"<p\b(?P<attrs>[^>]*)>(?P<body>.*?)</p>",
            block,
            flags=re.IGNORECASE | re.DOTALL,
        ):
            attrs = html_attrs(paragraph.group("attrs"))
            text = html_text(paragraph.group("body"))
            title = str(attrs.get("title") or "").strip()
            if "开课时间" in text:
                term = re.sub(r"^\s*开课时间\s*[：:]?\s*", "", text).strip()
            elif not teacher and (title or "color3" in attrs.get("class", "").split()):
                teacher = title or text

        image_url = ""
        image_match = re.search(r"<img\b[^>]*>", block, flags=re.IGNORECASE | re.DOTALL)
        if image_match:
            image_attrs = html_attrs(image_match.group(0))
            image_url = str(
                image_attrs.get("data-original")
                or image_attrs.get("data-src")
                or image_attrs.get("src")
                or ""
            ).strip()

        course_id = input_value("courseId") or card_attrs.get("id", "")[2:]
        clazz_id = input_value("clazzId")
        cpi = input_value("curPersonId", "cpi")
        role = input_value("role")
        plain = html_text(block)
        course = {
            "index": len(courses) + 1,
            "course_id": str(course_id).strip(),
            "course_name": name,
            "clazz_id": clazz_id,
            "cpi": cpi,
            "role": role or "0",
            "teacher": teacher,
            "term": term,
            "entry_url": urljoin(MOOC2_BASE_URL, entry_url) if entry_url else "",
            "image_url": urljoin(MOOC2_BASE_URL, image_url) if image_url else "",
            "ended": bool(re.search(r"课程已结束|已结束课程", plain)),
            "can_quit": "quitTheCourse(" in block or "退课" in plain,
            "is_top": "取消置顶" in plain,
        }
        if course["course_id"] and course["clazz_id"] and course["entry_url"]:
            courses.append(course)
    return courses


def parse_learning_ai_tools(html: str) -> list[dict[str, Any]]:
    """Parse the tools offered by the learner AI-workbench page."""

    tools: list[dict[str, Any]] = []
    candidates: list[tuple[dict[str, str], str]] = []
    for match in re.finditer(
        r"<li\b(?P<attrs>[^>]*)>(?P<body>.*?)</li>",
        str(html or ""),
        flags=re.IGNORECASE | re.DOTALL,
    ):
        attrs = html_attrs(match.group("attrs"))
        candidates.append((attrs, match.group("body")))
    for match in re.finditer(r"<input\b[^>]*>", str(html or ""), flags=re.I | re.S):
        attrs = html_attrs(match.group(0))
        candidates.append((attrs, ""))

    seen: set[tuple[str, str]] = set()
    for attrs, body in candidates:
        raw_url = str(attrs.get("hrefstr") or "").strip()
        if not raw_url:
            continue
        name_match = re.search(
            r"<span\b[^>]*class=['\"][^'\"]*workName[^'\"]*['\"][^>]*>"
            r"(.*?)</span>",
            body,
            flags=re.IGNORECASE | re.DOTALL,
        )
        name = (
            html_text(name_match.group(1))
            if name_match
            else str(attrs.get("agentname") or attrs.get("title") or "").strip()
        )
        if not name:
            continue
        tool_id = str(attrs.get("iframeid") or "").strip()
        key = (tool_id, raw_url)
        if key in seen:
            continue
        seen.add(key)
        parsed = urlparse(raw_url)
        tools.append(
            {
                "index": len(tools) + 1,
                "tool_id": tool_id,
                "name": name,
                "host": parsed.netloc,
                "entry_url": redact_url_query_values(raw_url, LEARNING_SECRET_QUERY_NAMES),
            }
        )
    return tools


def parse_learning_chapters(html: str) -> dict[str, list[dict[str, Any]]]:
    """Parse learner-visible chapter units and their directly selectable chapters."""

    source = str(html or "")
    unit_starts: list[int] = []
    for match in re.finditer(r"<div\b[^>]*>", source, flags=re.I | re.S):
        attrs = html_attrs(match.group(0))
        if "chapter_unit" in attrs.get("class", "").split():
            unit_starts.append(match.start())

    units: list[dict[str, Any]] = []
    flat: list[dict[str, Any]] = []
    for unit_position, start in enumerate(unit_starts, 1):
        end = unit_starts[unit_position] if unit_position < len(unit_starts) else len(source)
        block = source[start:end]
        child_starts: list[tuple[int, dict[str, str]]] = []
        for match in re.finditer(r"<div\b[^>]*>", block, flags=re.I | re.S):
            attrs = html_attrs(match.group(0))
            if "chapter_item" in attrs.get("class", "").split() and attrs.get("id", "").startswith(
                "cur"
            ):
                child_starts.append((match.start(), attrs))

        parent = block[: child_starts[0][0]] if child_starts else block
        number_match = re.search(r"<em\b[^>]*>(.*?)</em>", parent, flags=re.I | re.S)
        unit_number = html_text(number_match.group(1)) if number_match else str(unit_position)
        unit_title = ""
        for span_match in re.finditer(r"<span\b[^>]*>.*?</span>", parent, flags=re.I | re.S):
            attrs = html_attrs(span_match.group(0))
            if attrs.get("title"):
                unit_title = str(attrs["title"]).strip()
                break
        if not unit_title:
            title_match = re.search(
                r"<a\b[^>]*class=['\"][^'\"]*clicktitle[^'\"]*['\"][^>]*>"
                r"(.*?)</a>",
                parent,
                flags=re.I | re.S,
            )
            unit_title = html_text(title_match.group(1)) if title_match else ""

        children: list[dict[str, Any]] = []
        for child_position, (child_start, attrs) in enumerate(child_starts, 1):
            child_end = (
                child_starts[child_position][0]
                if child_position < len(child_starts)
                else len(block)
            )
            fragment = block[child_start:child_end]
            sequence_match = re.search(
                r"<span\b[^>]*class=['\"][^'\"]*catalog_sbar[^'\"]*['\"][^>]*>"
                r"(.*?)</span>",
                fragment,
                flags=re.I | re.S,
            )
            pending_count = 0
            for input_match in re.finditer(r"<input\b[^>]*>", fragment, flags=re.I | re.S):
                input_attrs = html_attrs(input_match.group(0))
                if "knowledgeJobCount" not in input_attrs.get("class", "").split():
                    continue
                raw_count = str(input_attrs.get("value") or "").strip()
                pending_count = int(raw_count) if raw_count.isdigit() else 0
                break
            status_match = re.search(
                r"<span\b[^>]*class=['\"][^'\"]*bntHoverTips[^'\"]*['\"][^>]*>"
                r"(.*?)</span>",
                fragment,
                flags=re.I | re.S,
            )
            chapter = {
                "index": len(flat) + 1,
                "chapter_id": attrs.get("id", "")[3:],
                "number": html_text(sequence_match.group(1)) if sequence_match else "",
                "title": str(attrs.get("title") or "").strip(),
                "unit_number": unit_number,
                "unit_title": unit_title,
                "pending_task_count": pending_count,
                "task_status": html_text(status_match.group(1)) if status_match else "",
            }
            children.append(chapter)
            flat.append(chapter)
        units.append(
            {
                "index": unit_position,
                "number": unit_number,
                "title": unit_title,
                "chapter_count": len(children),
                "pending_task_count": sum(item["pending_task_count"] for item in children),
                "chapters": children,
            }
        )
    return {"units": units, "chapters": flat}


def _learning_entry_status_key(status: str) -> str:
    normalized = re.sub(r"\s+", "", str(status or ""))
    for marker, key in (
        ("未交", "unsubmitted"),
        ("待提交", "unsubmitted"),
        ("已交", "submitted"),
        ("待批阅", "submitted"),
        ("已完成", "completed"),
        ("未开始", "not_started"),
        ("进行中", "ongoing"),
        ("已结束", "ended"),
        ("已过期", "expired"),
    ):
        if marker in normalized:
            return key
    return "unknown"


def parse_learning_task_entries(html: str) -> list[dict[str, Any]]:
    """Parse student homework, exam, or self-test list entries without opening them."""

    entries: list[dict[str, Any]] = []
    for match in re.finditer(
        r"<li\b(?P<attrs>[^>]*)>(?P<body>.*?)</li>",
        str(html or ""),
        flags=re.I | re.S,
    ):
        attrs = html_attrs(match.group("attrs"))
        if "gotask" not in str(attrs.get("onclick") or "").casefold():
            continue
        raw_url = str(attrs.get("data") or attrs.get("href") or "").strip()
        if not raw_url:
            continue
        body = match.group("body")
        title_match = re.search(
            r"<p\b[^>]*class=['\"][^'\"]*overHidden2[^'\"]*['\"][^>]*>"
            r"(.*?)</p>",
            body,
            flags=re.I | re.S,
        )
        status_match = re.search(
            r"<p\b[^>]*class=['\"][^'\"]*status[^'\"]*['\"][^>]*>"
            r"(.*?)</p>",
            body,
            flags=re.I | re.S,
        )
        aria_parts = [part.strip() for part in str(attrs.get("aria-label") or "").split(";")]
        title = (
            html_text(title_match.group(1))
            if title_match
            else (aria_parts[0] if aria_parts else "")
        )
        status = (
            html_text(status_match.group(1))
            if status_match
            else (aria_parts[1] if len(aria_parts) > 1 else "")
        )
        query = {
            key.casefold(): values[0] for key, values in parse_qs(urlparse(raw_url).query).items()
        }
        entries.append(
            {
                "index": len(entries) + 1,
                "title": title,
                "status": status,
                "status_key": _learning_entry_status_key(status),
                "work_id": query.get("workid", ""),
                "answer_id": query.get("answerid", ""),
                "exam_id": query.get("examid", ""),
                "test_paper_id": query.get("testpaperid", ""),
                "test_user_relation_id": query.get("testuserrelationid", ""),
                "task_id": query.get("taskid", ""),
                "entry_url": redact_url_query_values(raw_url, LEARNING_SECRET_QUERY_NAMES),
            }
        )
    return entries


def parse_learning_materials(html: str) -> list[dict[str, Any]]:
    """Parse one learner course-material folder page."""

    source = str(html or "")
    starts: list[tuple[int, dict[str, str]]] = []
    for match in re.finditer(r"<ul\b[^>]*>", source, flags=re.I | re.S):
        attrs = html_attrs(match.group(0))
        if "dataBody_td" in attrs.get("class", "").split():
            starts.append((match.start(), attrs))
    items: list[dict[str, Any]] = []
    for position, (start, attrs) in enumerate(starts):
        end = starts[position + 1][0] if position + 1 < len(starts) else len(source)
        fragment = source[start:end]
        size_match = re.search(
            r"<li\b[^>]*class=['\"][^'\"]*dataBody_size_stu[^'\"]*['\"][^>]*>"
            r"(.*?)</li>",
            fragment,
            flags=re.I | re.S,
        )
        creator_match = re.search(
            r"<li\b[^>]*class=['\"][^'\"]*dataBody_creater_stu[^'\"]*['\"][^>]*>"
            r"(.*?)</li>",
            fragment,
            flags=re.I | re.S,
        )
        item_type = str(attrs.get("type") or "").strip().lower()
        raw_target_url = str(attrs.get("url") or attrs.get("loadurl") or "").strip()
        items.append(
            {
                "index": len(items) + 1,
                "data_id": str(attrs.get("id") or "").strip(),
                "name": str(attrs.get("dataname") or "").strip(),
                "item_type": item_type,
                "is_folder": item_type == "afolder",
                "downloadable": str(attrs.get("isdown") or "").strip() == "1",
                "open_state": str(attrs.get("isopen") or "").strip(),
                "object_id": str(attrs.get("objectid") or "").strip(),
                "source": str(attrs.get("source") or "").strip(),
                "order": str(attrs.get("order") or "").strip(),
                "size": html_text(size_match.group(1)) if size_match else "",
                "creator": html_text(creator_match.group(1)) if creator_match else "",
                "target_url": redact_url_query_values(raw_target_url, LEARNING_SECRET_QUERY_NAMES)
                if raw_target_url
                else "",
            }
        )
    return items


def resolve_learning_material(
    items: list[dict[str, Any]], query: str, *, folders_only: bool = False
) -> dict[str, Any]:
    normalized = str(query or "").strip().casefold()
    if not normalized:
        raise ChaoxingAPIError("learning material name, data_id, or index is required")
    candidates = [item for item in items if not folders_only or item.get("is_folder")]
    exact = [
        item
        for item in candidates
        if normalized
        in {
            str(item.get("index") or ""),
            str(item.get("data_id") or "").casefold(),
            str(item.get("name") or "").strip().casefold(),
        }
    ]
    if len(exact) == 1:
        return exact[0]
    partial = [item for item in candidates if normalized in str(item.get("name") or "").casefold()]
    if len(partial) == 1:
        return partial[0]
    if not partial:
        noun = "folder" if folders_only else "material"
        raise ChaoxingAPIError(f"learning {noun} not found: {query}")
    options = ", ".join(
        f"{item['index']}. {item['name']} ({item['data_id']})" for item in partial[:20]
    )
    raise ChaoxingAPIError(f"multiple learning materials match: {options}")


def parse_learning_wrong_question_summary(html: str) -> dict[str, Any]:
    hidden = parse_hidden_inputs(str(html or ""))

    def integer(name: str, default: int = 0) -> int:
        try:
            return int(str(hidden.get(name) or default))
        except ValueError:
            return default

    group_count = integer("groupCount")
    topic_ids = [value for value in str(hidden.get("topicArr") or "").split(",") if value]
    return {
        "group_count": group_count,
        "has_wrong_questions": group_count > 0,
        "last_exam_id": str(hidden.get("lastExamId") or ""),
        "self_test_available": str(hidden.get("showSelfTest") or "") == "1",
        "selected_question_type": str(hidden.get("queType") or ""),
        "selected_topic_ids": topic_ids,
    }


def normalize_learning_activity(raw: dict[str, Any], *, source: str) -> dict[str, Any]:
    status = ChaoxingAPI._ai_workbench_integer(raw.get("status"), -1)
    extra = raw.get("extraInfo") if isinstance(raw.get("extraInfo"), dict) else {}
    safe_extra = {
        key: extra[key]
        for key in ("topicId", "groupId", "workId", "chapterId", "taskId")
        if key in extra
    }
    return {
        "activity_id": str(raw.get("id") or raw.get("activeId") or raw.get("taskId") or ""),
        "name": str(
            raw.get("nameOne")
            or raw.get("typeTitle")
            or raw.get("title")
            or raw.get("taskName")
            or raw.get("name")
            or ""
        ).strip(),
        "subtitle": str(raw.get("nameTwo") or raw.get("description") or "").strip(),
        "display_time": str(raw.get("nameFour") or "").strip(),
        "activity_type": ChaoxingAPI._ai_workbench_integer(
            raw.get("activeType", raw.get("type")), -1
        ),
        "status": status,
        "status_label": ChaoxingAPI._class_activity_status_label(status),
        "user_status": ChaoxingAPI._ai_workbench_integer(raw.get("userStatus"), -1),
        "start_time": raw.get("startTime"),
        "end_time": raw.get("endTime"),
        "release_count": ChaoxingAPI._ai_workbench_integer(raw.get("releaseNum"), 0),
        "attendance_count": ChaoxingAPI._ai_workbench_integer(raw.get("attendNum"), 0),
        "viewed": str(raw.get("isLook") or "0").strip().lower() in {"1", "true"},
        "source": source,
        "metadata": safe_extra,
    }


def normalize_learning_record_sections(
    payloads: dict[str, dict[str, Any]],
    page_values: dict[str, str],
) -> dict[str, Any]:
    """Reduce learning-record APIs to study metrics and omit identity/bootstrap secrets."""

    def section(name: str) -> dict[str, Any]:
        payload = payloads.get(name)
        if not isinstance(payload, dict):
            return {}
        data = payload.get("data")
        return data if isinstance(data, dict) else payload

    def integer(value: Any) -> int:
        try:
            return int(str(value or "0"))
        except (TypeError, ValueError):
            return 0

    job = section("job")
    work = section("work")
    tests = section("test")
    group_task = section("group_task")
    video_test = section("video_test")
    score_data = section("score")
    score = score_data.get("score") if isinstance(score_data.get("score"), dict) else {}
    self_exam = section("self_exam")
    week = section("week")
    sign = section("attendance")
    points = section("points")
    live = section("live")
    cxclass = section("cxclass")
    component_scores = score_data.get("weightList")
    if not isinstance(component_scores, list):
        component_scores = []

    return {
        "chapter_tasks": {
            "completed": job.get("job"),
            "published": job.get("publishJobNum"),
            "completion_percent": job.get("jobPer"),
            "class_rank": job.get("jobRank"),
            "slow_progress": bool(job.get("isSlowJob")),
        },
        "homework": {
            "completed": work.get("finishCount"),
            "assigned": work.get("receivedNum"),
            "completion_percent": work.get("finishPer"),
            "score": work.get("workScore"),
        },
        "chapter_quizzes": {
            "completed": tests.get("testNum"),
            "assigned": tests.get("receivedNum"),
            "completion_percent": tests.get("finishPer"),
            "average_score": tests.get("testAvgScore"),
            "question_task_count": tests.get("jobCount"),
        },
        "course_exams": {
            "completed": integer(page_values.get("examFinishNum")),
            "assigned": integer(page_values.get("examPublishNum")),
        },
        "group_tasks": {
            "completed": group_task.get("taskNum"),
            "assigned": group_task.get("publishTaskNum"),
            "completion_percent": group_task.get("taskPer"),
            "score": group_task.get("taskScore"),
        },
        "video_quizzes": {
            "completed": video_test.get("finishCount"),
            "assigned": video_test.get("count"),
            "completion_percent": video_test.get("finishPer"),
            "questions_completed": video_test.get("finishQuestionCount"),
            "question_count": video_test.get("questionCount"),
        },
        "self_tests": {
            "attempt_count": self_exam.get("examCount"),
            "question_count": self_exam.get("quesCount"),
            "objective_question_count": self_exam.get("objQuesCount"),
            "objective_correct_count": self_exam.get("objRightCount"),
            "objective_correct_percent": self_exam.get("objRightPercent"),
        },
        "score": {
            "visible": bool(score_data.get("showScore")),
            "overall": score.get("score"),
            "component_scores": [
                {"name": str(item.get("name") or ""), "value": item.get("value")}
                for item in component_scores
                if isinstance(item, dict)
            ],
        },
        "weekly_activity": {
            "dates": week.get("dates") if isinstance(week.get("dates"), list) else [],
            "counts": week.get("counts") if isinstance(week.get("counts"), list) else [],
        },
        "attendance": {
            key: sign.get(key)
            for key in (
                "allCount",
                "attendanceCount",
                "realAbsenceCount",
                "absenceCount",
                "overdueCount",
                "earlyCount",
                "lateCount",
                "sickCount",
                "personnalCount",
                "publicCount",
                "signPer",
            )
        },
        "points": points.get("ponits"),
        "live": {
            "live_minutes": live.get("livingTime"),
            "replay_minutes": live.get("playbackTime"),
            "chaoxing_class_live_minutes": cxclass.get("liveTime"),
            "chaoxing_class_replay_minutes": cxclass.get("lookBackTime"),
        },
    }


def resolve_learning_course(courses: list[dict[str, Any]], query: str) -> dict[str, Any]:
    normalized = str(query or "").strip().casefold()
    if not normalized:
        raise ChaoxingAPIError("learning course name, course_id, clazz_id, or index is required")
    exact = [
        course
        for course in courses
        if normalized
        in {
            str(course.get("course_id") or "").casefold(),
            str(course.get("clazz_id") or "").casefold(),
            str(course.get("course_name") or "").strip().casefold(),
            str(course.get("index") or ""),
        }
    ]
    if len(exact) == 1:
        return exact[0]
    if len(exact) > 1:
        raise ChaoxingAPIError(f"multiple exact learning-course matches: {query}")
    partial = [
        course
        for course in courses
        if normalized in str(course.get("course_name") or "").strip().casefold()
        or normalized in str(course.get("teacher") or "").strip().casefold()
    ]
    if len(partial) == 1:
        return partial[0]
    if not partial:
        raise ChaoxingAPIError(f"learning course not found: {query}")
    candidates = ", ".join(
        f"{course['index']}. {course['course_name']} ({course['course_id']}/{course['clazz_id']})"
        for course in partial
    )
    raise ChaoxingAPIError(f"multiple learning-course matches: {candidates}")


def resolve_course(courses: list[dict[str, Any]], query: str) -> dict[str, Any]:
    normalized = query.strip().lower()
    if not normalized:
        raise ChaoxingAPIError("course name or course_id is required")
    exact = [
        course
        for course in courses
        if str(course.get("course_id", "")).lower() == normalized
        or str(course.get("course_name", "")).strip().lower() == normalized
        or str(course.get("index", "")) == normalized
    ]
    if len(exact) == 1:
        return exact[0]
    if len(exact) > 1:
        raise ChaoxingAPIError(f"multiple exact course matches: {query}")
    partial = [
        course
        for course in courses
        if normalized in str(course.get("course_name", "")).strip().lower()
    ]
    if len(partial) == 1:
        return partial[0]
    if not partial:
        raise ChaoxingAPIError(f"course not found: {query}")
    candidates = ", ".join(
        f"{course['index']}. {course['course_name']} ({course['course_id']})" for course in partial
    )
    raise ChaoxingAPIError(f"multiple course matches: {candidates}")


def resolve_class(course: dict[str, Any], query: str | None = None) -> dict[str, Any]:
    classes = course.get("classes")
    if not isinstance(classes, list) or not classes:
        raise ChaoxingAPIError(f"course has no classes: {course.get('course_name', '')}")
    if not query:
        return classes[0]
    normalized = query.strip().lower()
    exact = [
        item
        for item in classes
        if str(item.get("clazz_id", "")).lower() == normalized
        or str(item.get("clazz_name", "")).strip().lower() == normalized
        or str(item.get("index", "")) == normalized
    ]
    if len(exact) == 1:
        return exact[0]
    partial = [
        item for item in classes if normalized in str(item.get("clazz_name", "")).strip().lower()
    ]
    if len(partial) == 1:
        return partial[0]
    if not partial:
        raise ChaoxingAPIError(f"class not found: {query}")
    candidates = ", ".join(
        f"{item['index']}. {item['clazz_name']} ({item['clazz_id']})" for item in partial
    )
    raise ChaoxingAPIError(f"multiple class matches: {candidates}")


class ChaoxingAPI:
    def __init__(
        self,
        cookie_file: Path,
        timeout: float = 20.0,
        state_file: Path | None = None,
    ) -> None:
        self.cookie_file = cookie_file
        self.timeout = timeout
        self.state_file = state_file

    @staticmethod
    def _new_session() -> requests.Session:
        session = requests.Session()
        session.headers.update(
            {
                "User-Agent": (
                    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                    "AppleWebKit/537.36 (KHTML, like Gecko) "
                    "Chrome/136.0 Safari/537.36"
                ),
                "Accept-Language": "zh-CN,zh;q=0.9,en;q=0.8",
            }
        )
        return session

    def _session(self) -> requests.Session:
        session = self._new_session()
        for cookie in load_cookie_records(self.cookie_file):
            name = str(cookie.get("name") or "")
            value = str(cookie.get("value") or "")
            domain = str(cookie.get("domain") or "")
            path = str(cookie.get("path") or "/")
            if name and domain:
                session.cookies.set(name, value, domain=domain, path=path)
        return session

    @staticmethod
    def _decode(response: requests.Response) -> str:
        for encoding in ("utf-8-sig", response.encoding, response.apparent_encoding, "gb18030"):
            if not encoding:
                continue
            try:
                return response.content.decode(encoding)
            except (LookupError, UnicodeDecodeError):
                continue
        return response.content.decode("utf-8", errors="replace")

    def _read_local_state(self) -> dict[str, Any]:
        if self.state_file is None:
            return {"version": 1, "topic_drafts": []}
        try:
            text = self.state_file.read_text(encoding="utf-8")
        except FileNotFoundError:
            return {"version": 1, "topic_drafts": []}
        except OSError as exc:
            raise ChaoxingAPIError(f"cannot read local Chaoxing state: {exc}") from exc
        try:
            state = json.loads(text)
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("local Chaoxing state is invalid JSON") from exc
        if not isinstance(state, dict) or state.get("version") != 1:
            raise ChaoxingAPIError("local Chaoxing state has an unsupported format")
        if not isinstance(state.get("topic_drafts", []), list):
            raise ChaoxingAPIError("local Chaoxing topic-draft registry is invalid")
        return state

    def _write_local_state(self, state: dict[str, Any]) -> None:
        if self.state_file is None:
            return
        temporary = self.state_file.with_name(f".{self.state_file.name}.{uuid4().hex}.tmp")
        try:
            self.state_file.parent.mkdir(parents=True, exist_ok=True)
            temporary.write_text(
                json.dumps(state, ensure_ascii=False, indent=2, sort_keys=True),
                encoding="utf-8",
            )
            temporary.replace(self.state_file)
        except OSError as exc:
            raise ChaoxingAPIError(f"cannot write local Chaoxing state: {exc}") from exc
        finally:
            temporary.unlink(missing_ok=True)

    def _upsert_topic_draft_record(self, record: dict[str, Any]) -> None:
        if self.state_file is None:
            return
        state = self._read_local_state()
        records = [
            item
            for item in state.get("topic_drafts", [])
            if isinstance(item, dict)
            and not (
                str(item.get("bbs_id") or "") == str(record.get("bbs_id") or "")
                and str(item.get("draft_uuid") or "") == str(record.get("draft_uuid") or "")
            )
        ]
        records.append(record)
        state["topic_drafts"] = records
        self._write_local_state(state)

    def _remove_topic_draft_record(self, bbs_id: str, draft_uuid: str) -> None:
        if self.state_file is None:
            return
        state = self._read_local_state()
        state["topic_drafts"] = [
            item
            for item in state.get("topic_drafts", [])
            if not (
                isinstance(item, dict)
                and str(item.get("bbs_id") or "") == bbs_id
                and str(item.get("draft_uuid") or "") == draft_uuid
            )
        ]
        self._write_local_state(state)

    def _session_status(self, response: requests.Response) -> dict[str, Any]:
        html = self._decode(response)
        lowered_url = response.url.lower()
        logged_in = "passport2.chaoxing.com/login" not in lowered_url and any(
            marker in html for marker in ("账号：", "课程教学", "frame_content")
        )
        account_name = ""
        for pattern in (
            r'aria-label=["\']账号：([^"\']+)',
            r'<h3[^>]*class=["\'][^"\']*user[^"\']*["\'][^>]*>([^<]+)</h3>',
        ):
            match = re.search(pattern, html, flags=re.IGNORECASE | re.DOTALL)
            if match:
                account_name = unescape(match.group(1)).strip()
                break
        return {
            "logged_in": logged_in,
            "account_name": account_name,
            "final_url": response.url,
            "http_status": response.status_code,
            "verification": (
                "authenticated personal-space markers present"
                if logged_in
                else "login markers absent"
            ),
        }

    @staticmethod
    def _safe_request_failure(operation: str, exc: requests.RequestException) -> str:
        """Describe a failed authenticated request without reflecting signed URLs."""
        response = getattr(exc, "response", None)
        status_code = getattr(response, "status_code", None)
        if isinstance(status_code, int):
            return f"{operation} failed (HTTP {status_code})"
        return f"{operation} failed ({exc.__class__.__name__})"

    def _login_target_status(
        self,
        response: requests.Response,
        requested_url: str,
    ) -> dict[str, Any]:
        """Verify a cross-application login target without returning signed query values."""
        requested = urlparse(requested_url)
        final = urlparse(response.url)
        html = self._decode(response)
        title_match = re.search(r"<title[^>]*>(.*?)</title>", html, flags=re.I | re.S)
        requested_host = (requested.hostname or "").lower()
        final_host = (final.hostname or "").lower()
        final_path = final.path or "/"
        lowered_path = final_path.rstrip("/").casefold() or "/"
        lowered_html = html.casefold()
        login_page = (
            (
                final_host in {"passport.chaoxing.com", "passport2.chaoxing.com"}
                and (lowered_path == "/login" or lowered_path.startswith("/login/"))
            )
            or lowered_path == "/login"
            or lowered_path.startswith("/login/")
            or (
                "fanyalogin" in lowered_html
                and ('name="uname"' in lowered_html or "name='uname'" in lowered_html)
            )
        )
        target_reached = final_host == requested_host and not login_page
        return {
            "requested_host": requested_host,
            "requested_path": requested.path or "/",
            "final_host": final_host,
            "final_path": final_path,
            "http_status": response.status_code,
            "title": html_text(title_match.group(1)) if title_match else "",
            "login_redirected": login_page,
            "target_reached": target_reached,
            "verification": (
                "target host reached without a Chaoxing login page"
                if target_reached
                else "target host was not reached with the authenticated session"
            ),
        }

    def login(
        self,
        username: str,
        password: str,
        *,
        fid: str = "-1",
        target_url: str = AUTH_CHECK_URL,
    ) -> dict[str, Any]:
        """Log in through Chaoxing HTTP APIs and atomically persist verified cookies."""
        username = username.strip()
        if not username:
            raise ChaoxingAPIError("Chaoxing username cannot be empty")
        if not password:
            raise ChaoxingAPIError("Chaoxing password cannot be empty")
        fid = fid.strip() or "-1"
        target_url = validated_chaoxing_url(target_url, "login target URL")

        session = self._new_session()
        encoded_refer = quote(target_url, safe="")
        login_page_url = (
            f"{LOGIN_PAGE_URL}?newversion=true&fid={quote(fid, safe='')}&refer={encoded_refer}"
        )
        try:
            page_response = session.get(login_page_url, timeout=self.timeout)
            page_response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(self._safe_request_failure("login page request", exc)) from exc

        hidden = parse_hidden_inputs(self._decode(page_response))
        t_value = hidden.get("t", "true")
        post_username = aes_encrypt_base64(username) if t_value == "true" else username
        post_password = aes_encrypt_base64(password) if t_value == "true" else password
        payload = {
            "fid": hidden.get("fid", fid),
            "uname": post_username,
            "password": post_password,
            "refer": hidden.get("refer", encoded_refer),
            "t": t_value,
            "forbidotherlogin": hidden.get("forbidotherlogin", "0"),
            "validate": hidden.get("validate", ""),
            "doubleFactorLogin": hidden.get("doubleFactorLogin", "0"),
            "independentId": hidden.get("independentId", ""),
            "independentNameId": hidden.get("independentNameId", ""),
        }
        try:
            login_response = session.post(
                FANYA_LOGIN_URL,
                data=payload,
                timeout=self.timeout,
                headers={
                    "Origin": "https://passport2.chaoxing.com",
                    "Referer": login_page_url,
                    "X-Requested-With": "XMLHttpRequest",
                    "Accept": "application/json, text/javascript, */*; q=0.01",
                },
            )
            login_response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"login request failed: {exc}") from exc
        try:
            result = login_response.json()
        except ValueError as exc:
            raise ChaoxingAPIError("login response was not valid JSON") from exc
        if not isinstance(result, dict):
            raise ChaoxingAPIError("login response was not a JSON object")

        if result.get("containTwoFactorLogin"):
            two_factor_url = str(result.get("twoFactorLoginPCUrl") or "").strip()
            if two_factor_url:
                two_factor_url = validated_chaoxing_url(
                    unquote(two_factor_url), "two-factor verification URL"
                )
                raise ChaoxingAPIError(f"login requires two-factor verification: {two_factor_url}")
            raise ChaoxingAPIError("login requires two-factor verification")
        if not result.get("status"):
            message = (
                result.get("msg2") or result.get("mes") or result.get("errorMsg") or "login failed"
            )
            safe_message = str(message)
            for secret in (password, post_password):
                if secret:
                    safe_message = safe_message.replace(secret, "[redacted]")
            raise ChaoxingAPIError(safe_message)

        result_url = unquote(str(result.get("url") or "").strip())
        if result_url:
            result_url = validated_chaoxing_url(result_url, "post-login URL")
        try:
            if result_url and result_url != target_url:
                warmup = session.get(result_url, timeout=self.timeout, allow_redirects=True)
                warmup.raise_for_status()
            target_response = session.get(
                target_url,
                timeout=self.timeout,
                allow_redirects=True,
            )
            target_response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(
                self._safe_request_failure("post-login target verification", exc)
            ) from exc

        target_status = self._login_target_status(target_response, target_url)
        if target_url == AUTH_CHECK_URL:
            auth_response = target_response
        else:
            try:
                auth_response = session.get(
                    AUTH_CHECK_URL,
                    timeout=self.timeout,
                    allow_redirects=True,
                )
                auth_response.raise_for_status()
            except requests.RequestException as exc:
                raise ChaoxingAPIError(
                    self._safe_request_failure("personal-space verification", exc)
                ) from exc

        status = self._session_status(auth_response)
        if not status["logged_in"]:
            raise ChaoxingAPIError(
                "login response succeeded but authenticated personal-space verification failed"
            )
        if not target_status["target_reached"]:
            raise ChaoxingAPIError(
                "login response succeeded but the requested Chaoxing target returned to login "
                "or another host"
            )
        cookie_count = save_cookie_file_atomic(session, self.cookie_file)
        result = {
            **status,
            "cookies_saved": cookie_count,
            "cookie_file": str(self.cookie_file),
            "verification": (
                "authenticated personal-space markers present; verified cookies saved atomically"
            ),
        }
        if target_url != AUTH_CHECK_URL:
            result["target"] = target_status
            result["verification"] = (
                "authenticated personal-space markers present; requested Chaoxing target reached; "
                "verified cookies saved atomically"
            )
        return result

    def check_session(self) -> dict[str, Any]:
        try:
            response = self._session().get(
                AUTH_CHECK_URL, timeout=self.timeout, allow_redirects=True
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"session check failed: {exc}") from exc
        return self._session_status(response)

    def list_personal_space_modules(self) -> dict[str, Any]:
        session = self._session()
        try:
            response = session.get(AUTH_CHECK_URL, timeout=self.timeout, allow_redirects=True)
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"personal-space request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError("Chaoxing personal-space login has expired")
        modules = parse_personal_space_modules(self._decode(response))
        if not modules:
            raise ChaoxingAPIError("personal-space page exposed no module entries")
        return {
            "final_url": response.url,
            "count": len(modules),
            "modules": modules,
            "verification": f"parsed {len(modules)} personal-space modules through HTTP",
        }

    def inspect_personal_space_module(self, module_query: str) -> dict[str, Any]:
        session = self._session()
        try:
            root_response = session.get(
                AUTH_CHECK_URL,
                timeout=self.timeout,
                allow_redirects=True,
            )
            root_response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"personal-space request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in root_response.url.lower():
            raise ChaoxingAPIError("Chaoxing personal-space login has expired")
        modules = parse_personal_space_modules(self._decode(root_response))
        selected = resolve_personal_space_module(modules, module_query)
        module_url = str(selected.get("data_url") or "").strip()
        parsed = urlparse(module_url)
        if parsed.scheme not in {"http", "https"} or not parsed.hostname:
            raise ChaoxingAPIError(
                f"personal-space module exposes no HTTP entry URL: {selected['label']}"
            )
        try:
            response = session.get(
                module_url,
                timeout=max(self.timeout, 60),
                allow_redirects=True,
                headers={"Referer": root_response.url},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"personal-space module request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError(
                f"personal-space module was redirected to login: {selected['label']}"
            )
        html = self._decode(response)
        title_match = re.search(r"<title[^>]*>(.*?)</title>", html, flags=re.I | re.S)
        return {
            "module": selected,
            "final_url": response.url,
            "http_status": response.status_code,
            "content_type": str(response.headers.get("Content-Type") or ""),
            "title": html_text(title_match.group(1)) if title_match else "",
            "text_excerpt": html_text(html, limit=20_000),
            "verification": "authenticated personal-space module response retrieved through HTTP",
        }

    def _personal_space_module_context(
        self,
        module_query: str,
    ) -> tuple[requests.Session, requests.Response, dict[str, Any]]:
        session = self._session()
        try:
            root_response = session.get(
                AUTH_CHECK_URL,
                timeout=self.timeout,
                allow_redirects=True,
            )
            root_response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"personal-space request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in root_response.url.lower():
            raise ChaoxingAPIError("Chaoxing personal-space login has expired")
        selected = resolve_personal_space_module(
            parse_personal_space_modules(self._decode(root_response)),
            module_query,
        )
        module_url = str(selected.get("data_url") or "").strip()
        if urlparse(module_url).scheme not in {"http", "https"}:
            raise ChaoxingAPIError(
                f"personal-space module exposes no HTTP entry URL: {selected['label']}"
            )
        try:
            response = session.get(
                module_url,
                timeout=max(self.timeout, 60),
                allow_redirects=True,
                headers={"Referer": root_response.url},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"personal-space module request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError(
                f"personal-space module was redirected to login: {selected['label']}"
            )
        return session, response, selected

    def _job_ability_context(self) -> dict[str, Any]:
        session, landing, _module = self._personal_space_module_context("岗位能力")
        if (urlparse(landing.url).hostname or "").lower() != "gangwei.chaoxing.com":
            raise ChaoxingAPIError("job-ability module did not reach gangwei.chaoxing.com")
        return {
            "session": session,
            "landing_url": landing.url,
        }

    @staticmethod
    def _job_ability_signature(value: str, *, day: str | None = None) -> str:
        signing_day = day or datetime.now(timezone(timedelta(hours=8))).date().isoformat()
        material = f"{value}-{signing_day}-{JOB_ABILITY_SIGNATURE_SUFFIX}".encode()
        return hashlib.md5(material, usedforsecurity=False).hexdigest()

    def _job_ability_json_request(
        self,
        context: dict[str, Any],
        path: str,
        *,
        params: dict[str, Any] | None = None,
        operation: str,
    ) -> dict[str, Any]:
        if not path.startswith("/jobability/"):
            raise ChaoxingAPIError("job-ability request path is outside the fixed API root")
        session = context.get("session")
        if not isinstance(session, requests.Session):
            raise ChaoxingAPIError("job-ability session context is invalid")
        url = f"{JOB_ABILITY_BASE_URL}{path}"
        try:
            response = session.get(
                url,
                params=dict(params or {}),
                timeout=self.timeout,
                headers={
                    "Accept": "application/json, text/plain, */*",
                    "Referer": str(context.get("landing_url") or JOB_ABILITY_BASE_URL),
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"{operation} failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError("Chaoxing job-ability login has expired")
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError(f"{operation} returned invalid JSON") from exc
        if not isinstance(payload, dict):
            raise ChaoxingAPIError(f"{operation} returned a non-object JSON payload")
        status = payload.get("status")
        if status is False or str(status).strip().lower() in {"0", "false", "failed", "error"}:
            message = str(payload.get("msg") or payload.get("message") or operation).strip()
            raise ChaoxingAPIError(f"{operation} was rejected: {message}")
        return payload

    @staticmethod
    def _job_ability_page_values(page: int, page_size: int) -> tuple[int, int]:
        if page < 1:
            raise ChaoxingAPIError("job-ability page must be at least 1")
        if page_size < 1 or page_size > 100:
            raise ChaoxingAPIError("job-ability page_size must be between 1 and 100")
        return page, page_size

    @staticmethod
    def _job_ability_plain_text(value: Any) -> str:
        if value is None:
            return ""
        return re.sub(r"\s+", " ", unescape(str(value))).strip()

    @staticmethod
    def _job_ability_rich_text(value: Any) -> str:
        if value is None:
            return ""
        return html_text(str(value), limit=100_000)

    @staticmethod
    def _job_ability_count(value: Any) -> int | float | str | None:
        if value is None or value == "":
            return None
        if isinstance(value, bool):
            return int(value)
        if isinstance(value, (int, float)):
            return value
        text = str(value).strip()
        try:
            return int(text)
        except ValueError:
            try:
                return float(text)
            except ValueError:
                return text

    @staticmethod
    def _job_ability_bool(value: Any) -> bool:
        if isinstance(value, bool):
            return value
        if isinstance(value, (int, float)):
            return value != 0
        return str(value or "").strip().lower() in {"1", "true", "yes", "on"}

    @classmethod
    def _normalize_job_ability_ad(
        cls,
        raw: dict[str, Any],
        index: int,
    ) -> dict[str, Any]:
        return {
            "index": index,
            "job_ad_id": cls._job_ability_plain_text(raw.get("id")),
            "recruitment_title": cls._job_ability_plain_text(raw.get("zpgw")),
            "job_title": cls._job_ability_plain_text(raw.get("zwmc")),
            "company": cls._job_ability_plain_text(raw.get("zpqy")),
            "company_type": cls._job_ability_plain_text(raw.get("qylx")),
            "company_size": cls._job_ability_plain_text(raw.get("qygm")),
            "education_requirement": cls._job_ability_plain_text(raw.get("xlyq")),
            "experience_requirement": cls._job_ability_plain_text(raw.get("jyyq")),
            "demand_count": cls._job_ability_count(raw.get("xqrs")),
            "salary": cls._job_ability_plain_text(raw.get("xzdy")),
            "salary_range": cls._job_ability_plain_text(raw.get("xzqj")),
            "location": cls._job_ability_plain_text(raw.get("gzdd")),
            "province": cls._job_ability_plain_text(raw.get("sf")),
            "city": cls._job_ability_plain_text(raw.get("cs")),
            "district": cls._job_ability_plain_text(raw.get("qx")),
            "industry": cls._job_ability_plain_text(raw.get("sshy")),
            "company_industry": cls._job_ability_plain_text(raw.get("qyhy")),
            "abilities": cls._job_ability_plain_text(raw.get("gwnl")),
            "category": cls._job_ability_plain_text(raw.get("jycc")),
            "level": cls._job_ability_plain_text(raw.get("cc")),
            "year": cls._job_ability_plain_text(raw.get("nd")),
            "updated_at": cls._job_ability_plain_text(raw.get("gxrq")),
            "job_description": cls._job_ability_rich_text(raw.get("gwms")),
            "company_description": cls._job_ability_rich_text(raw.get("qyjs")),
            "external_detail_url": cls._job_ability_plain_text(raw.get("jlxqydz")),
        }

    @staticmethod
    def _job_ability_data_list(payload: dict[str, Any], operation: str) -> list[Any]:
        data = payload.get("data")
        if data is None:
            return []
        if not isinstance(data, list):
            raise ChaoxingAPIError(f"{operation} returned a non-list data field")
        return data

    def _job_ability_jobs_from_context(
        self,
        context: dict[str, Any],
        keyword: str,
        *,
        page: int,
        page_size: int,
        education_level: str,
    ) -> tuple[list[dict[str, Any]], int | float | str | None]:
        normalized_keyword = keyword.strip()
        if not normalized_keyword:
            raise ChaoxingAPIError("job search keyword cannot be empty")
        page, page_size = self._job_ability_page_values(page, page_size)
        params: dict[str, Any] = {
            "sw": normalized_keyword,
            "enc": self._job_ability_signature(normalized_keyword),
            "page": page,
            "size": page_size,
        }
        normalized_level = education_level.strip()
        if normalized_level:
            params["cc"] = normalized_level
        payload = self._job_ability_json_request(
            context,
            "/jobability/job/qwjs",
            params=params,
            operation="job search",
        )
        start = (page - 1) * page_size + 1
        records = [
            self._normalize_job_ability_ad(raw, start + offset)
            for offset, raw in enumerate(self._job_ability_data_list(payload, "job search"))
            if isinstance(raw, dict)
        ]
        return records, self._job_ability_count(payload.get("total"))

    def read_job_ability_status(self) -> dict[str, Any]:
        context = self._job_ability_context()
        payload = self._job_ability_json_request(
            context,
            "/jobability/job/checklogin",
            operation="job-ability status",
        )
        data = payload.get("data")
        if not isinstance(data, dict):
            raise ChaoxingAPIError("job-ability status returned no account feature object")
        school_library = self._job_ability_bool(data.get("schoolBaseLibrary"))
        major_trend = self._job_ability_bool(data.get("majortrend"))
        civil_postgraduate = self._job_ability_bool(data.get("civilPostgraduate"))
        return {
            "authenticated": True,
            "public_job_search_available": True,
            "public_occupation_library_available": True,
            "public_industry_library_available": True,
            "school_base_library_enabled": school_library,
            "major_trend_enabled": major_trend,
            "civil_postgraduate_enabled": civil_postgraduate,
            "private_routes_available": school_library,
            "verification": (
                "job-ability checklogin succeeded; account identifiers were intentionally omitted"
            ),
        }

    def search_job_ability_jobs(
        self,
        keyword: str,
        *,
        page: int = 1,
        page_size: int = 20,
        education_level: str = "",
    ) -> dict[str, Any]:
        context = self._job_ability_context()
        jobs, total = self._job_ability_jobs_from_context(
            context,
            keyword,
            page=page,
            page_size=page_size,
            education_level=education_level,
        )
        return {
            "keyword": keyword.strip(),
            "education_level": education_level.strip(),
            "page": page,
            "page_size": page_size,
            "count": len(jobs),
            "total": total,
            "jobs": jobs,
            "verification": f"read {len(jobs)} current recruitment records through HTTP",
        }

    @staticmethod
    def _resolve_job_ability_ad(
        jobs: list[dict[str, Any]],
        query: str,
    ) -> dict[str, Any]:
        normalized = query.strip().lower()
        if not normalized:
            raise ChaoxingAPIError("job ad query cannot be empty")
        exact = [
            item
            for item in jobs
            if normalized
            in {
                str(item.get("job_ad_id") or "").strip().lower(),
                str(item.get("recruitment_title") or "").strip().lower(),
                str(item.get("job_title") or "").strip().lower(),
                (f"{item.get('company') or ''} {item.get('job_title') or ''}".strip().lower()),
            }
        ]
        if len(exact) == 1:
            return exact[0]
        candidates = exact or [
            item
            for item in jobs
            if any(
                normalized in str(item.get(key) or "").strip().lower()
                for key in ("job_ad_id", "recruitment_title", "job_title", "company")
            )
        ]
        if len(candidates) == 1:
            return candidates[0]
        if not candidates:
            raise ChaoxingAPIError(f"job ad not found: {query}")
        labels = ", ".join(
            f"{item['index']}. {item['job_title'] or item['recruitment_title']} "
            f"- {item['company']} ({item['job_ad_id']})"
            for item in candidates[:20]
        )
        raise ChaoxingAPIError(f"multiple job ads match: {labels}")

    def read_job_ability_job_ad(
        self,
        job: str,
        *,
        search: str = "",
        education_level: str = "",
    ) -> dict[str, Any]:
        context = self._job_ability_context()
        keyword = search.strip() or job.strip()
        jobs, total = self._job_ability_jobs_from_context(
            context,
            keyword,
            page=1,
            page_size=100,
            education_level=education_level,
        )
        selected = self._resolve_job_ability_ad(jobs, job)
        return {
            "search": keyword,
            "search_total": total,
            "job": selected,
            "verification": f"resolved and normalized current job ad {selected['job_ad_id']}",
        }

    def list_popular_job_ability_jobs(
        self,
        *,
        education_level: str = "本科",
    ) -> dict[str, Any]:
        context = self._job_ability_context()
        normalized_level = education_level.strip()
        payload = self._job_ability_json_request(
            context,
            "/jobability/job/rmgw",
            params={
                "cc": normalized_level,
                "enc": self._job_ability_signature("rmgw"),
            },
            operation="popular job list",
        )
        data = payload.get("data")
        if not isinstance(data, dict):
            raise ChaoxingAPIError("popular job list returned no data object")
        popular_raw = data.get("rmgw") if isinstance(data.get("rmgw"), list) else []
        high_salary_raw = data.get("gxgw") if isinstance(data.get("gxgw"), list) else []
        popular = [
            self._normalize_job_ability_ad(raw, index)
            for index, raw in enumerate(popular_raw, start=1)
            if isinstance(raw, dict)
        ]
        high_salary = [
            self._normalize_job_ability_ad(raw, index)
            for index, raw in enumerate(high_salary_raw, start=1)
            if isinstance(raw, dict)
        ]
        return {
            "education_level": normalized_level,
            "popular_jobs": popular,
            "high_salary_jobs": high_salary,
            "verification": (
                f"read {len(popular)} popular and {len(high_salary)} high-salary jobs"
            ),
        }

    @classmethod
    def _normalize_job_ability_occupation(
        cls,
        raw: dict[str, Any],
        index: int,
    ) -> dict[str, Any]:
        return {
            "index": index,
            "name": cls._job_ability_plain_text(raw.get("zymc")),
            "demand_count": cls._job_ability_count(raw.get("xqrs")),
        }

    def read_job_ability_occupation_catalog(
        self,
        *,
        education_level: str = "本科",
    ) -> dict[str, Any]:
        context = self._job_ability_context()
        normalized_level = education_level.strip()
        payload = self._job_ability_json_request(
            context,
            "/jobability/joblibrary/index",
            params={
                "cc": normalized_level,
                "enc": self._job_ability_signature("index"),
            },
            operation="occupation catalog",
        )
        data = payload.get("data")
        if not isinstance(data, dict):
            raise ChaoxingAPIError("occupation catalog returned no data object")
        popular_raw = data.get("rmzylist") if isinstance(data.get("rmzylist"), list) else []
        emerging_raw = data.get("xxzylist") if isinstance(data.get("xxzylist"), list) else []
        counts = {
            "level_1": self._job_ability_count(data.get("yijcount")),
            "level_2": self._job_ability_count(data.get("erjcount")),
            "level_3": self._job_ability_count(data.get("sanjcount")),
            "level_4": self._job_ability_count(data.get("sijcount")),
        }
        return {
            "education_level": normalized_level,
            "counts": counts,
            "popular_occupations": [
                self._normalize_job_ability_occupation(raw, index)
                for index, raw in enumerate(popular_raw, start=1)
                if isinstance(raw, dict)
            ],
            "emerging_occupations": [
                self._normalize_job_ability_occupation(raw, index)
                for index, raw in enumerate(emerging_raw, start=1)
                if isinstance(raw, dict)
            ],
            "verification": "read the current four-level occupation catalog summary",
        }

    def search_job_ability_occupations(
        self,
        keyword: str,
        *,
        education_level: str = "本科",
    ) -> dict[str, Any]:
        normalized_keyword = keyword.strip()
        if not normalized_keyword:
            raise ChaoxingAPIError("occupation search keyword cannot be empty")
        context = self._job_ability_context()
        payload = self._job_ability_json_request(
            context,
            "/jobability/joblibrary/zyjs",
            params={
                "cc": education_level.strip(),
                "sw": normalized_keyword,
                "enc": self._job_ability_signature(normalized_keyword),
            },
            operation="occupation search",
        )
        records = [
            self._normalize_job_ability_occupation(raw, index)
            for index, raw in enumerate(
                self._job_ability_data_list(payload, "occupation search"), start=1
            )
            if isinstance(raw, dict)
        ]
        return {
            "keyword": normalized_keyword,
            "education_level": education_level.strip(),
            "count": len(records),
            "occupations": records,
            "verification": f"read {len(records)} matching occupations through HTTP",
        }

