    def _subject_creation_context(self) -> tuple[requests.Session, str]:
        session, response, _selected = self._personal_space_module_context("专题创作")
        if (urlparse(response.url).hostname or "").lower() != "yz4.chaoxing.com":
            raise ChaoxingAPIError("subject-creation module did not reach yz4.chaoxing.com")
        return session, response.url

    def _subject_creation_request(
        self,
        session: requests.Session,
        referer: str,
        path: str,
        operation: str,
        *,
        params: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        try:
            response = session.get(
                SUBJECT_CREATION_BASE_URL + path,
                params=params,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
                timeout=max(self.timeout, 60),
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"{operation} request failed: {exc}") from exc
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError(f"{operation} response was not JSON") from exc
        if not isinstance(payload, dict):
            raise ChaoxingAPIError(f"{operation} response was not a JSON object")
        return payload

    @staticmethod
    def _normalize_subject_creation_folder(
        raw: dict[str, Any], index: int, parent_folder_id: str
    ) -> dict[str, Any]:
        return {
            "index": index,
            "id": str(raw.get("id") or raw.get("folderId") or ""),
            "name": str(raw.get("folderName") or raw.get("name") or "").strip(),
            "parent_folder_id": str(raw.get("cfid") or parent_folder_id or "-1"),
            "has_children": bool(raw.get("hasChilds")),
            "creator_id": str(raw.get("creatorId") or ""),
            "author": str(raw.get("author") or "").strip(),
            "child_count": int(raw.get("subCount") or 0),
        }

    @staticmethod
    def _normalize_subject_creation_subject(
        raw: dict[str, Any], index: int, parent_folder_id: str
    ) -> dict[str, Any]:
        return {
            "index": index,
            "id": str(raw.get("id") or ""),
            "course_id": str(raw.get("course_Id") or raw.get("courseId") or ""),
            "encrypted_course_id": str(raw.get("encCourseId") or ""),
            "name": str(raw.get("name") or "").strip(),
            "description": str(raw.get("schools") or "").strip(),
            "cover_url": str(raw.get("coverUrl") or ""),
            "author": str(raw.get("author") or "").strip(),
            "parent_folder_id": str(raw.get("cfid") or parent_folder_id or "-1"),
            "published": str(raw.get("published") or "0") not in {"", "0", "false", "False"},
            "deleted_by_admin": "selfDeleted" in raw and str(raw.get("selfDeleted") or "0") != "1",
        }

    def _subject_creation_listing(
        self,
        session: requests.Session,
        referer: str,
        *,
        folder_id: str = "-1",
        search: str = "",
        max_items: int = 1000,
    ) -> dict[str, Any]:
        if max_items < 1:
            raise ChaoxingAPIError("max_items must be positive")
        folders: list[dict[str, Any]] = []
        subjects: list[dict[str, Any]] = []
        folder_ids: set[str] = set()
        subject_ids: set[str] = set()
        start = 0
        total = 0
        metadata: dict[str, Any] = {}
        while len(subjects) < max_items:
            payload = self._subject_creation_request(
                session,
                referer,
                "/subject_creation/SubjectCreationController/mySubjectsNew",
                "subject-creation listing",
                params={
                    "version": "3.0",
                    "folderId": folder_id,
                    "searchValue": search,
                    "start": start,
                    "size": min(100, max_items),
                },
            )
            metadata = payload
            raw_folders = payload.get("folders") if isinstance(payload.get("folders"), list) else []
            raw_subjects = (
                payload.get("specials") if isinstance(payload.get("specials"), list) else []
            )
            for raw in raw_folders:
                if not isinstance(raw, dict):
                    continue
                item = self._normalize_subject_creation_folder(raw, len(folders) + 1, folder_id)
                if item["id"] and item["id"] not in folder_ids:
                    folder_ids.add(item["id"])
                    folders.append(item)
            added = 0
            for raw in raw_subjects:
                if not isinstance(raw, dict):
                    continue
                item = self._normalize_subject_creation_subject(raw, len(subjects) + 1, folder_id)
                identity = item["course_id"] or item["id"]
                if identity and identity not in subject_ids:
                    subject_ids.add(identity)
                    subjects.append(item)
                    added += 1
                    if len(subjects) >= max_items:
                        break
            try:
                total = int(payload.get("totalNum") or len(subjects))
            except (TypeError, ValueError):
                total = len(subjects)
            if not raw_subjects or len(subjects) >= total or added == 0:
                break
            start += max(50, len(raw_subjects))
        return {
            "folder_id": folder_id,
            "search": search,
            "folder_count": len(folders),
            "subject_count": len(subjects),
            "total": total,
            "folders": folders,
            "subjects": subjects,
            "creation_available": bool(metadata.get("show", True)),
            "verification": "subject folders and subjects parsed from a fresh HTTP listing",
        }

    def list_subject_creation_items(
        self,
        *,
        folder: str = "-1",
        search: str = "",
        max_items: int = 1000,
    ) -> dict[str, Any]:
        session, referer = self._subject_creation_context()
        folder_id = "-1"
        if str(folder).strip() not in {"", "-1", "root", "根目录"}:
            folder_id = self._resolve_subject_creation_item(
                self._subject_creation_tree(session, referer)["folders"],
                str(folder),
                "subject folder",
            )["id"]
        return self._subject_creation_listing(
            session,
            referer,
            folder_id=folder_id,
            search=search.strip(),
            max_items=max_items,
        )

    def _subject_creation_tree(
        self, session: requests.Session, referer: str, *, max_folders: int = 1000
    ) -> dict[str, Any]:
        pending: list[tuple[str, str]] = [("-1", "")]
        visited: set[str] = set()
        folders: list[dict[str, Any]] = []
        subjects: list[dict[str, Any]] = []
        while pending:
            parent_id, parent_path = pending.pop(0)
            if parent_id in visited:
                continue
            visited.add(parent_id)
            listing = self._subject_creation_listing(
                session, referer, folder_id=parent_id, max_items=1000
            )
            for subject in listing["subjects"]:
                subjects.append({**subject, "folder_path": parent_path})
            for folder in listing["folders"]:
                path = "/".join(item for item in (parent_path, folder["name"]) if item)
                normalized = {**folder, "path": path}
                folders.append(normalized)
                if len(folders) > max_folders:
                    raise ChaoxingAPIError("subject folder tree exceeds max_folders")
                pending.append((folder["id"], path))
        for index, folder in enumerate(folders, 1):
            folder["index"] = index
        for index, subject in enumerate(subjects, 1):
            subject["index"] = index
        return {
            "folder_count": len(folders),
            "subject_count": len(subjects),
            "folders": folders,
            "subjects": subjects,
            "verification": "complete subject-creation folder tree read through HTTP",
        }

    def list_subject_creation_tree(self, *, max_folders: int = 1000) -> dict[str, Any]:
        session, referer = self._subject_creation_context()
        return self._subject_creation_tree(session, referer, max_folders=max_folders)

    @staticmethod
    def _resolve_subject_creation_item(
        items: list[dict[str, Any]], query: str, label: str
    ) -> dict[str, Any]:
        normalized = query.strip().lower()
        if not normalized:
            raise ChaoxingAPIError(f"{label} is required")
        exact = [
            item
            for item in items
            if normalized
            in {
                str(item.get("id") or "").lower(),
                str(item.get("course_id") or "").lower(),
                str(item.get("name") or "").strip().lower(),
                str(item.get("path") or "").strip().lower(),
                str(item.get("index") or ""),
            }
        ]
        if len(exact) == 1:
            return exact[0]
        partial = [
            item
            for item in items
            if normalized in str(item.get("name") or "").strip().lower()
            or normalized in str(item.get("path") or "").strip().lower()
        ]
        candidates = exact or partial
        if len(candidates) == 1:
            return candidates[0]
        if not candidates:
            raise ChaoxingAPIError(f"{label} not found: {query}")
        names = ", ".join(
            f"{item.get('name')} ({item.get('id') or item.get('course_id')})"
            for item in candidates[:10]
        )
        raise ChaoxingAPIError(f"multiple {label} matches: {names}")

    @staticmethod
    def _subject_creation_ack(payload: dict[str, Any], operation: str) -> None:
        if payload.get("flag") is True:
            return
        message = payload.get("error") or payload.get("msg") or f"{operation} was not acknowledged"
        raise ChaoxingAPIError(str(message))

    def subject_creation_status(self) -> dict[str, Any]:
        session, referer = self._subject_creation_context()
        listing = self._subject_creation_listing(session, referer, max_items=1)
        payload = self._subject_creation_request(
            session,
            referer,
            "/subject_creation/SubjectCreationController/checkUserCertifyAndUnit",
            "subject creation eligibility",
        )
        self._subject_creation_ack(payload, "subject creation eligibility")
        certified = not bool(payload.get("notCertify"))
        return {
            "creation_available": listing["creation_available"],
            "real_name_certified": certified,
            "can_create": listing["creation_available"] and certified,
            "verification": "subject creation availability and real-name status read through HTTP",
        }

    def create_subject_creation_folder(
        self, name: str, *, parent_folder: str = "-1"
    ) -> dict[str, Any]:
        name = name.strip()
        if not name:
            raise ChaoxingAPIError("subject folder name cannot be empty")
        session, referer = self._subject_creation_context()
        tree = self._subject_creation_tree(session, referer)
        parent_id = "-1"
        if str(parent_folder).strip() not in {"", "-1", "root", "根目录"}:
            parent_id = self._resolve_subject_creation_item(
                tree["folders"], str(parent_folder), "parent subject folder"
            )["id"]
        before = self._subject_creation_listing(session, referer, folder_id=parent_id)
        if any(item["name"] == name for item in before["folders"]):
            raise ChaoxingAPIError(f"subject folder already exists: {name}")
        payload = self._subject_creation_request(
            session,
            referer,
            "/subject_creation/SubjectCreationController/createFolder",
            "subject folder creation",
            params={"folderName": name, "folderId": parent_id},
        )
        self._subject_creation_ack(payload, "subject folder creation")
        created_id = str(payload.get("addFolderId") or "")
        after = self._subject_creation_listing(session, referer, folder_id=parent_id)
        matches = [
            item
            for item in after["folders"]
            if (created_id and item["id"] == created_id)
            or (not created_id and item["name"] == name)
        ]
        if len(matches) != 1:
            raise ChaoxingAPIError(
                "server acknowledged folder creation, but fresh read did not verify it"
            )
        return {
            "folder": matches[0],
            "verification": "created subject folder is present in its refreshed parent listing",
        }

    def rename_subject_creation_folder(self, folder: str, name: str) -> dict[str, Any]:
        name = name.strip()
        if not name:
            raise ChaoxingAPIError("subject folder name cannot be empty")
        session, referer = self._subject_creation_context()
        selected = self._resolve_subject_creation_item(
            self._subject_creation_tree(session, referer)["folders"], folder, "subject folder"
        )
        payload = self._subject_creation_request(
            session,
            referer,
            "/subject_creation/SubjectCreationController/changeFolderName",
            "subject folder rename",
            params={"folderName": name, "folderId": selected["id"]},
        )
        self._subject_creation_ack(payload, "subject folder rename")
        refreshed = self._resolve_subject_creation_item(
            self._subject_creation_tree(session, referer)["folders"],
            selected["id"],
            "subject folder",
        )
        if refreshed["name"] != name:
            raise ChaoxingAPIError(
                "server acknowledged folder rename, but fresh read did not verify it"
            )
        return {
            "folder": refreshed,
            "verification": "renamed subject folder matches a fresh tree read",
        }

    def move_subject_creation_folder(
        self, folder: str, *, target_folder: str = "-1"
    ) -> dict[str, Any]:
        session, referer = self._subject_creation_context()
        tree = self._subject_creation_tree(session, referer)
        selected = self._resolve_subject_creation_item(tree["folders"], folder, "subject folder")
        target_id = "-1"
        if str(target_folder).strip() not in {"", "-1", "root", "根目录"}:
            target_id = self._resolve_subject_creation_item(
                tree["folders"], target_folder, "target subject folder"
            )["id"]
        if selected["id"] == target_id:
            raise ChaoxingAPIError("a subject folder cannot be moved into itself")
        payload = self._subject_creation_request(
            session,
            referer,
            "/subject_creation/SubjectCreationController/mvSubject",
            "subject folder move",
            params={"resourceId": selected["id"], "folderId": target_id, "isFolder": "true"},
        )
        self._subject_creation_ack(payload, "subject folder move")
        refreshed = self._resolve_subject_creation_item(
            self._subject_creation_tree(session, referer)["folders"],
            selected["id"],
            "subject folder",
        )
        if refreshed["parent_folder_id"] != target_id:
            raise ChaoxingAPIError(
                "server acknowledged folder move, but fresh tree did not verify it"
            )
        return {
            "folder": refreshed,
            "verification": "moved subject folder has the requested parent in a fresh tree read",
        }

    def delete_subject_creation_folder(
        self, folder: str, *, allow_nonempty: bool = False
    ) -> dict[str, Any]:
        session, referer = self._subject_creation_context()
        tree = self._subject_creation_tree(session, referer)
        selected = self._resolve_subject_creation_item(tree["folders"], folder, "subject folder")
        contents = self._subject_creation_listing(session, referer, folder_id=selected["id"])
        if not allow_nonempty and (contents["folders"] or contents["subjects"]):
            raise ChaoxingAPIError(
                "subject folder is not empty; set allow_nonempty=true explicitly"
            )
        payload = self._subject_creation_request(
            session,
            referer,
            "/subject_creation/SubjectCreationController/delSubjectFolder",
            "subject folder deletion",
            params={"folderId": selected["id"]},
        )
        self._subject_creation_ack(payload, "subject folder deletion")
        remaining = self._subject_creation_tree(session, referer)["folders"]
        if any(item["id"] == selected["id"] for item in remaining):
            raise ChaoxingAPIError("server acknowledged folder deletion, but it remains visible")
        return {
            "deleted_folder": selected,
            "verification": "deleted subject folder is absent from a fresh tree read",
        }

    def set_subject_creation_publish_status(self, subject: str, published: bool) -> dict[str, Any]:
        session, referer = self._subject_creation_context()
        selected = self._resolve_subject_creation_item(
            self._subject_creation_tree(session, referer)["subjects"], subject, "subject"
        )
        payload = self._subject_creation_request(
            session,
            referer,
            "/subject_creation/SubjectCreationController/subjectHandle",
            "subject publish-status update",
            params={
                "course_Id": selected["course_id"],
                "type": "publishSubject" if published else "ubPublishSubject",
            },
        )
        self._subject_creation_ack(payload, "subject publish-status update")
        refreshed = self._resolve_subject_creation_item(
            self._subject_creation_tree(session, referer)["subjects"],
            selected["course_id"],
            "subject",
        )
        if refreshed["published"] is not published:
            raise ChaoxingAPIError(
                "server acknowledged publish-status update, but fresh read did not verify it"
            )
        return {
            "subject": refreshed,
            "verification": "subject publish status matches a fresh tree read",
        }

    def move_subject_creation_subject(
        self, subject: str, *, target_folder: str = "-1"
    ) -> dict[str, Any]:
        session, referer = self._subject_creation_context()
        tree = self._subject_creation_tree(session, referer)
        selected = self._resolve_subject_creation_item(tree["subjects"], subject, "subject")
        target_id = "-1"
        if str(target_folder).strip() not in {"", "-1", "root", "根目录"}:
            target_id = self._resolve_subject_creation_item(
                tree["folders"], target_folder, "target subject folder"
            )["id"]
        payload = self._subject_creation_request(
            session,
            referer,
            "/subject_creation/SubjectCreationController/mvSubject",
            "subject move",
            params={
                "resourceId": f"mooc_{selected['course_id']}",
                "folderId": target_id,
                "isFolder": "false",
            },
        )
        self._subject_creation_ack(payload, "subject move")
        refreshed = self._resolve_subject_creation_item(
            self._subject_creation_tree(session, referer)["subjects"],
            selected["course_id"],
            "subject",
        )
        if refreshed["parent_folder_id"] != target_id:
            raise ChaoxingAPIError(
                "server acknowledged subject move, but fresh tree did not verify it"
            )
        return {
            "subject": refreshed,
            "verification": "moved subject has the requested folder in a fresh tree read",
        }

    def delete_subject_creation_subject(self, subject: str) -> dict[str, Any]:
        session, referer = self._subject_creation_context()
        selected = self._resolve_subject_creation_item(
            self._subject_creation_tree(session, referer)["subjects"], subject, "subject"
        )
        payload = self._subject_creation_request(
            session,
            referer,
            "/subject_creation/SubjectCreationController/subjectHandle",
            "subject deletion",
            params={"course_Id": selected["course_id"], "type": "delSubject"},
        )
        self._subject_creation_ack(payload, "subject deletion")
        active = self._subject_creation_tree(session, referer)["subjects"]
        recycle = self._subject_creation_recycle_listing(session, referer)
        if any(item["course_id"] == selected["course_id"] for item in active) or not any(
            item["course_id"] == selected["course_id"] for item in recycle["subjects"]
        ):
            raise ChaoxingAPIError("server acknowledged subject deletion, but recycle read failed")
        return {
            "deleted_subject": selected,
            "verification": "subject is absent from active tree and present in recycle bin",
        }

    def _subject_creation_recycle_listing(
        self,
        session: requests.Session,
        referer: str,
        *,
        search: str = "",
        max_items: int = 1000,
    ) -> dict[str, Any]:
        if max_items < 1:
            raise ChaoxingAPIError("max_items must be positive")
        subjects: list[dict[str, Any]] = []
        seen: set[str] = set()
        start = 0
        total = 0
        while len(subjects) < max_items:
            payload = self._subject_creation_request(
                session,
                referer,
                "/subject_creation/SubjectCreationController/subjectRecycle",
                "subject recycle listing",
                params={"version": "3.0", "searchValue": search, "start": start},
            )
            raw_items = payload.get("subjects") if isinstance(payload.get("subjects"), list) else []
            added = 0
            for raw in raw_items:
                if not isinstance(raw, dict):
                    continue
                item = self._normalize_subject_creation_subject(raw, len(subjects) + 1, "")
                identity = item["course_id"] or item["id"]
                if identity and identity not in seen:
                    seen.add(identity)
                    subjects.append(item)
                    added += 1
                    if len(subjects) >= max_items:
                        break
            try:
                total = int(payload.get("totalNum") or len(subjects))
            except (TypeError, ValueError):
                total = len(subjects)
            if not raw_items or len(subjects) >= total or added == 0:
                break
            start += 50
        return {
            "search": search,
            "count": len(subjects),
            "total": total,
            "subjects": subjects,
            "verification": "subject recycle bin parsed from fresh HTTP responses",
        }

    def list_subject_creation_recycle(
        self, *, search: str = "", max_items: int = 1000
    ) -> dict[str, Any]:
        session, referer = self._subject_creation_context()
        return self._subject_creation_recycle_listing(
            session, referer, search=search.strip(), max_items=max_items
        )

    def restore_subject_creation_subject(self, subject: str) -> dict[str, Any]:
        session, referer = self._subject_creation_context()
        selected = self._resolve_subject_creation_item(
            self._subject_creation_recycle_listing(session, referer)["subjects"],
            subject,
            "recycled subject",
        )
        if selected["deleted_by_admin"]:
            raise ChaoxingAPIError("subject was deleted by an administrator and cannot be restored")
        payload = self._subject_creation_request(
            session,
            referer,
            "/subject_creation/SubjectCreationController/subjectHandle",
            "subject restore",
            params={"course_Id": selected["course_id"], "type": "recoverSubject"},
        )
        self._subject_creation_ack(payload, "subject restore")
        recycle = self._subject_creation_recycle_listing(session, referer)["subjects"]
        active = self._subject_creation_tree(session, referer)["subjects"]
        if any(item["course_id"] == selected["course_id"] for item in recycle) or not any(
            item["course_id"] == selected["course_id"] for item in active
        ):
            raise ChaoxingAPIError("server acknowledged subject restore, but fresh reads failed")
        return {
            "restored_subject": selected,
            "verification": "subject is absent from recycle bin and present in active tree",
        }

    def permanently_delete_subject_creation_subject(self, subject: str) -> dict[str, Any]:
        session, referer = self._subject_creation_context()
        selected = self._resolve_subject_creation_item(
            self._subject_creation_recycle_listing(session, referer)["subjects"],
            subject,
            "recycled subject",
        )
        payload = self._subject_creation_request(
            session,
            referer,
            "/subject_creation/SubjectCreationController/removeSubject",
            "permanent subject deletion",
            params={"courseId": selected["course_id"]},
        )
        self._subject_creation_ack(payload, "permanent subject deletion")
        remaining = self._subject_creation_recycle_listing(session, referer)["subjects"]
        if any(item["course_id"] == selected["course_id"] for item in remaining):
            raise ChaoxingAPIError(
                "server acknowledged permanent subject deletion, but it remains visible"
            )
        return {
            "deleted_subject": selected,
            "verification": "subject is absent from a fresh recycle-bin read",
        }

    @staticmethod
    def _detection_type(value: str) -> tuple[str, dict[str, str]]:
        normalized = value.strip().lower().replace("-", "_")
        aliases = {
            "similarity": "similarity",
            "similarity_check": "similarity",
            "查重": "similarity",
            "相似度": "similarity",
            "相似度检测": "similarity",
            "aigc": "aigc",
            "ai": "aigc",
            "aigc检测": "aigc",
            "comparison": "comparison",
            "compare": "comparison",
            "two": "comparison",
            "两两比对": "comparison",
            "两两对比": "comparison",
        }
        key = aliases.get(normalized)
        if key is None:
            raise ChaoxingAPIError("detection type must be similarity, aigc, or comparison")
        config = {
            "similarity": {
                "list_path": "/smas/article/search",
                "status_path": "/smas/article/getStatus",
                "delete_path": "/smas/article/cancelLookResult",
                "smas_type": "",
            },
            "aigc": {
                "list_path": "/smas/aigc/list",
                "status_path": "/smas/aigc/getStatus",
                "delete_path": "/smas/aigc/del",
                "smas_type": "2",
            },
            "comparison": {
                "list_path": "/smas/two/contrast/list",
                "status_path": "/smas/two/contrast/getStatus",
                "delete_path": "/smas/two/contrast/del",
                "smas_type": "3",
            },
        }
        return key, config[key]

    def _daya_context(self) -> tuple[requests.Session, str]:
        errors: list[str] = []
        for module in ("大雅AIGC检测", "大雅相似度检测"):
            try:
                session, response, _selected = self._personal_space_module_context(module)
            except ChaoxingAPIError as exc:
                errors.append(str(exc))
                continue
            hostname = (urlparse(response.url).hostname or "").lower()
            if hostname == "dsa.dayainfo.com":
                return session, response.url
            errors.append(f"{module} reached {hostname or 'an unknown host'}")
        raise ChaoxingAPIError("cannot establish Daya detection session: " + "; ".join(errors))

    def _daya_response(
        self,
        session: requests.Session,
        referer: str,
        path: str,
        operation: str,
        *,
        method: str = "GET",
        params: dict[str, Any] | None = None,
        data: dict[str, Any] | None = None,
        files: dict[str, Any] | None = None,
        timeout: float | None = None,
    ) -> requests.Response:
        try:
            response = session.request(
                method,
                DAYA_BASE_URL + path,
                params=params,
                data=data,
                files=files,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
                timeout=timeout or max(self.timeout, 60),
                allow_redirects=True,
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"{operation} request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError(f"{operation} was redirected to login")
        return response

    def _daya_json(
        self,
        session: requests.Session,
        referer: str,
        path: str,
        operation: str,
        **kwargs: Any,
    ) -> dict[str, Any]:
        response = self._daya_response(session, referer, path, operation, **kwargs)
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError(f"{operation} response was not JSON") from exc
        if not isinstance(payload, dict):
            raise ChaoxingAPIError(f"{operation} response was not a JSON object")
        return payload

    def list_detection_channels(self) -> dict[str, Any]:
        session, referer = self._daya_context()
        response = self._daya_response(
            session,
            referer,
            "/smas/show/upload",
            "detection channel listing",
        )
        html = self._decode(response)
        match = re.search(
            r'<ul\b[^>]*class=["\'][^"\']*test_range[^"\']*["\'][^>]*>(.*?)</ul>',
            html,
            flags=re.I | re.S,
        )
        channels: list[dict[str, Any]] = []
        if match:
            for item in re.finditer(r"<li\b([^>]*)>(.*?)</li>", match.group(1), flags=re.I | re.S):
                attrs = html_attrs(item.group(1))
                channel_match = re.search(r"chanId['\"]?\s*:\s*(\d+)", attrs.get("data", ""))
                if not channel_match:
                    continue
                channels.append(
                    {
                        "index": len(channels) + 1,
                        "channel_id": channel_match.group(1),
                        "name": html_text(item.group(2)),
                        "default": "checked" in attrs.get("class", "").split(),
                    }
                )
        if not channels:
            raise ChaoxingAPIError("similarity-check page exposed no detection channels")
        return {
            "count": len(channels),
            "channels": channels,
            "verification": "detection channels parsed from the authenticated upload page",
        }

    @staticmethod
    def _parse_detection_records(html: str, detection_type: str) -> dict[str, Any]:
        starts = list(
            re.finditer(
                r'<ul\b[^>]*\bid=["\']ul_([^"\']+)["\'][^>]*>',
                html,
                flags=re.I,
            )
        )
        records: list[dict[str, Any]] = []
        for index, start in enumerate(starts, 1):
            end = starts[index].start() if index < len(starts) else len(html)
            block = html[start.start() : end]

            def class_text(class_fragment: str, source: str = block) -> str:
                match = re.search(
                    r'<[^>]+class=["\'][^"\']*'
                    + re.escape(class_fragment)
                    + r'[^"\']*["\'][^>]*>(.*?)</[^>]+>',
                    source,
                    flags=re.I | re.S,
                )
                return html_text(match.group(1)) if match else ""

            links = []
            for anchor in re.finditer(r"<a\b([^>]*)>(.*?)</a>", block, flags=re.I | re.S):
                attrs = html_attrs(anchor.group(1))
                href = attrs.get("href", "")
                if href and href != "javascript:void(0);":
                    links.append({"label": html_text(anchor.group(2)), "href": href})
            records.append(
                {
                    "index": index,
                    "token": unescape(start.group(1)),
                    "type": detection_type,
                    "title": class_text("personal_testRecords_title_name"),
                    "status_text": class_text("personal_testRecords_title_status"),
                    "author": class_text("author"),
                    "text": html_text(block, limit=4000),
                    "links": links,
                }
            )
        page_match = re.search(
            r"setPage\(\s*['\"]?(\d+)['\"]?\s*,\s*['\"]?(\d+)['\"]?\s*,"
            r"\s*['\"]?(\d+)['\"]?",
            html,
            flags=re.I,
        )
        return {
            "page": int(page_match.group(1)) if page_match else 1,
            "page_size": int(page_match.group(2)) if page_match else len(records),
            "total": int(page_match.group(3)) if page_match else len(records),
            "free_entitlement_page": bool(
                re.search(r'id=["\']isFree["\'][^>]*value=["\']true["\']', html, flags=re.I)
            ),
            "records": records,
        }

    def _detection_records_page(
        self,
        session: requests.Session,
        referer: str,
        detection_type: str,
        config: dict[str, str],
        *,
        page: int,
        page_size: int,
        status: int,
        begin_date: str,
        end_date: str,
        search: str,
    ) -> dict[str, Any]:
        response = self._daya_response(
            session,
            referer,
            config["list_path"],
            "detection record listing",
            method="POST",
            data={
                "cpage": page,
                "pageSize": page_size,
                "status": status,
                "beginDate": begin_date,
                "endDate": end_date,
                "sw": search,
            },
        )
        parsed = self._parse_detection_records(self._decode(response), detection_type)
        parsed["final_url"] = response.url
        return parsed

    def list_detection_records(
        self,
        detection_type: str,
        *,
        page: int = 1,
        page_size: int = 100,
        status: int = -1,
        begin_date: str = "",
        end_date: str = "",
        search: str = "",
    ) -> dict[str, Any]:
        type_key, config = self._detection_type(detection_type)
        if page < 1 or page_size < 1 or page_size > 1000:
            raise ChaoxingAPIError("page must be positive and page_size must be 1..1000")
        if status not in {-1, 0, 4, 5, 6}:
            raise ChaoxingAPIError("detection status must be -1, 0, 4, 5, or 6")
        session, referer = self._daya_context()
        result = self._detection_records_page(
            session,
            referer,
            type_key,
            config,
            page=page,
            page_size=page_size,
            status=status,
            begin_date=begin_date.strip(),
            end_date=end_date.strip(),
            search=search.strip(),
        )
        return {
            "type": type_key,
            **result,
            "count": len(result["records"]),
            "verification": "authenticated Daya detection records parsed through HTTP",
        }

    @staticmethod
    def _resolve_detection_record(records: list[dict[str, Any]], query: str) -> dict[str, Any]:
        normalized = query.strip().lower()
        if not normalized:
            raise ChaoxingAPIError("detection record is required")
        exact = [
            record
            for record in records
            if normalized
            in {
                str(record.get("token") or "").lower(),
                str(record.get("title") or "").strip().lower(),
                str(record.get("index") or ""),
            }
        ]
        if len(exact) == 1:
            return exact[0]
        partial = [
            record
            for record in records
            if normalized in str(record.get("title") or "").strip().lower()
        ]
        candidates = exact or partial
        if len(candidates) == 1:
            return candidates[0]
        if not candidates and re.fullmatch(r"[A-Za-z0-9_=%+./:-]{6,}", query.strip()):
            return {"token": query.strip(), "title": "", "index": 0}
        if not candidates:
            raise ChaoxingAPIError(f"detection record not found: {query}")
        raise ChaoxingAPIError(
            "multiple detection record matches: "
            + ", ".join(
                f"{record.get('title')} ({record.get('token')})" for record in candidates[:10]
            )
        )

    def _find_detection_record(
        self,
        session: requests.Session,
        referer: str,
        type_key: str,
        config: dict[str, str],
        query: str,
    ) -> dict[str, Any]:
        listing = self._detection_records_page(
            session,
            referer,
            type_key,
            config,
            page=1,
            page_size=1000,
            status=-1,
            begin_date="",
            end_date="",
            search="",
        )
        return self._resolve_detection_record(listing["records"], query)

    def read_detection_record_status(self, detection_type: str, record: str) -> dict[str, Any]:
        type_key, config = self._detection_type(detection_type)
        session, referer = self._daya_context()
        selected = self._find_detection_record(session, referer, type_key, config, record)
        payload = self._daya_json(
            session,
            referer,
            config["status_path"],
            "detection status",
            params={"webArticleStr": selected["token"]},
        )
        return {
            "type": type_key,
            "record": selected,
            "status": payload,
            "verification": "detection status read from the live status endpoint",
        }

    @staticmethod
    def _validate_detection_file(path_value: str | Path) -> Path:
        path = Path(path_value).expanduser().resolve()
        if not path.is_file():
            raise ChaoxingAPIError(f"detection input file not found: {path}")
        allowed = {".doc", ".docx", ".pdf", ".txt", ".wps", ".rar", ".zip", ".ppt", ".pptx", ".rtf"}
        if path.suffix.lower() not in allowed:
            raise ChaoxingAPIError(
                "detection file must be DOC, DOCX, PDF, TXT, WPS, RAR, ZIP, PPT, PPTX, or RTF"
            )
        if path.stat().st_size > 100 * 1024 * 1024:
            raise ChaoxingAPIError("detection input file exceeds 100 MiB")
        return path

    @staticmethod
    def _detection_ack(payload: dict[str, Any], operation: str) -> None:
        value = payload.get("status")
        if value is True or value == 1 or str(value).strip().lower() in {"true", "1"}:
            return
        raise ChaoxingAPIError(str(payload.get("msg") or f"{operation} was not acknowledged"))

    def submit_detection(
        self,
        detection_type: str,
        title: str,
        *,
        author: str = "",
        content: str | None = None,
        file: str | Path | None = None,
        end_year: str = "",
        channel_ids: list[str] | None = None,
    ) -> dict[str, Any]:
        type_key, _config = self._detection_type(detection_type)
        if type_key == "comparison":
            raise ChaoxingAPIError("use comparison detection submission for two-file comparison")
        title = title.strip()
        author = author.strip()
        if not title or len(title) > 300:
            raise ChaoxingAPIError("detection title must contain 1..300 characters")
        if len(author) > 200:
            raise ChaoxingAPIError("detection author must contain at most 200 characters")
        if type_key == "similarity" and not author:
            raise ChaoxingAPIError("similarity detection author is required")
        content_value = (content or "").strip()
        if bool(content_value) == bool(file):
            raise ChaoxingAPIError("provide exactly one of content or file for detection")
        if content_value and not 50 <= len(content_value) <= 10_000:
            raise ChaoxingAPIError("detection pasted content must contain 50..10000 characters")
        path = self._validate_detection_file(file) if file else None
        session, referer = self._daya_context()
        endpoint = "/smas/aigc/upload" if type_key == "aigc" else "/dsa/article/upload"
        data = {"articletitle": title, "author": author, "content": content_value}
        if type_key == "similarity":
            data.update(
                {
                    "endYear": end_year.strip(),
                    "chanIds": ",".join(channel_ids or ["0"]),
                }
            )
        files = None
        with ExitStack() as stack:
            if path:
                stream = stack.enter_context(path.open("rb"))
                files = {
                    "file": (
                        path.name,
                        stream,
                        mimetypes.guess_type(path.name)[0] or "application/octet-stream",
                    )
                }
            payload = self._daya_json(
                session,
                referer,
                endpoint,
                "detection submission",
                method="POST",
                data=data,
                files=files,
                timeout=max(self.timeout, 300),
            )
        self._detection_ack(payload, "detection submission")
        listing = self._detection_records_page(
            session,
            referer,
            type_key,
            self._detection_type(type_key)[1],
            page=1,
            page_size=100,
            status=-1,
            begin_date="",
            end_date="",
            search=title,
        )
        matches = [record for record in listing["records"] if record["title"] == title]
        return {
            "type": type_key,
            "title": title,
            "message": str(payload.get("msg") or ""),
            "result_url": str(payload.get("url") or ""),
            "matching_records": matches,
            "verification": (
                "server acknowledged detection submission; matching fresh records returned"
                if matches
                else (
                    "server acknowledged detection submission; "
                    "no matching row was immediately visible"
                )
            ),
        }

    def submit_detection_comparison(
        self,
        title_1: str,
        file_1: str | Path,
        title_2: str,
        file_2: str | Path,
    ) -> dict[str, Any]:
        title_1 = title_1.strip()
        title_2 = title_2.strip()
        if not title_1 or not title_2 or len(title_1) > 300 or len(title_2) > 300:
            raise ChaoxingAPIError("comparison titles must each contain 1..300 characters")
        path_1 = self._validate_detection_file(file_1)
        path_2 = self._validate_detection_file(file_2)
        session, referer = self._daya_context()
        with ExitStack() as stack:
            stream_1 = stack.enter_context(path_1.open("rb"))
            stream_2 = stack.enter_context(path_2.open("rb"))
            payload = self._daya_json(
                session,
                referer,
                "/smas/two/contrast/upload",
                "comparison detection submission",
                method="POST",
                data={"title1": title_1, "title2": title_2},
                files={
                    "file1": (
                        path_1.name,
                        stream_1,
                        mimetypes.guess_type(path_1.name)[0] or "application/octet-stream",
                    ),
                    "file2": (
                        path_2.name,
                        stream_2,
                        mimetypes.guess_type(path_2.name)[0] or "application/octet-stream",
                    ),
                },
                timeout=max(self.timeout, 300),
            )
        self._detection_ack(payload, "comparison detection submission")
        return {
            "type": "comparison",
            "titles": [title_1, title_2],
            "message": str(payload.get("msg") or ""),
            "result_url": str(payload.get("url") or ""),
            "verification": "server acknowledged two-file comparison submission",
        }

    def read_detection_payment_status(self, detection_type: str, record: str) -> dict[str, Any]:
        type_key, config = self._detection_type(detection_type)
        session, referer = self._daya_context()
        selected = self._find_detection_record(session, referer, type_key, config, record)
        params: dict[str, Any] = {"webArticleStr": selected["token"]}
        if config["smas_type"]:
            params["smasType"] = config["smas_type"]
        payload = self._daya_json(
            session,
            referer,
            "/smas/article/payment/status",
            "detection payment status",
            params=params,
        )
        return {
            "type": type_key,
            "record": selected,
            "record_missing": bool(payload.get("noSlaid")),
            "authorization_error": bool(payload.get("noAuth")),
            "free_entitlement_available": bool(payload.get("enabledUseFree")),
            "free_entitlement_source": str(payload.get("typeStr") or ""),
            "payment_required": payload.get("isPayment") is True,
            "already_available": payload.get("isPayment") is False,
            "raw_status": payload,
            "verification": "payment and free-entitlement status read through HTTP",
        }

    def use_detection_free_entitlement(self, detection_type: str, record: str) -> dict[str, Any]:
        type_key, config = self._detection_type(detection_type)
        session, referer = self._daya_context()
        selected = self._find_detection_record(session, referer, type_key, config, record)
        params: dict[str, Any] = {"webArticleStr": selected["token"]}
        if config["smas_type"]:
            params["smasType"] = config["smas_type"]
        before = self._daya_json(
            session,
            referer,
            "/smas/article/payment/status",
            "detection payment status",
            params=params,
        )
        if not before.get("enabledUseFree"):
            raise ChaoxingAPIError("no free detection entitlement is currently available")
        response = self._daya_response(
            session,
            referer,
            "/smas/article/edit/status",
            "free detection entitlement use",
            params=params,
        )
        after = self._daya_json(
            session,
            response.url,
            "/smas/article/payment/status",
            "post-entitlement payment status",
            params=params,
        )
        if after.get("isPayment") is not False:
            raise ChaoxingAPIError(
                "free entitlement request completed, but report availability was not verified"
            )
        return {
            "type": type_key,
            "record": selected,
            "free_entitlement_used": True,
            "verification": "payment status now reports the detection result as available",
        }

    def download_detection_report(
        self,
        detection_type: str,
        record: str,
        output_path: str | Path,
        *,
        result_type: int = 1,
        overwrite: bool = False,
        timeout_seconds: float = 300,
    ) -> dict[str, Any]:
        type_key, config = self._detection_type(detection_type)
        session, referer = self._daya_context()
        selected = self._find_detection_record(session, referer, type_key, config, record)
        token = selected["token"]
        if type_key == "similarity":
            begin = self._daya_json(
                session,
                referer,
                "/smas/report/begin",
                "detection report generation",
                method="POST",
                data={"webArticleStr": token, "resultType": result_type, "reportType": 1},
            )
            if begin.get("status") is False:
                raise ChaoxingAPIError(str(begin.get("msg") or "report generation failed"))
            deadline = monotonic() + max(0, timeout_seconds)
            while not begin.get("hasReport"):
                if monotonic() >= deadline:
                    raise ChaoxingAPIError("timed out waiting for the detection report")
                sleep(min(3.0, max(0.1, deadline - monotonic())))
                begin = self._daya_json(
                    session,
                    referer,
                    "/smas/report/status",
                    "detection report status",
                    params={"webArticleStr": token, "resultType": result_type, "reportType": 1},
                )
                if begin.get("status") is False:
                    raise ChaoxingAPIError(str(begin.get("msg") or "report generation failed"))
            path = "/smas/report/download"
            params = {"webArticleStr": token, "resultType": result_type, "reportType": 1}
        elif type_key == "aigc":
            path = "/smas/aigc/report"
            params = {"webArticleStr": token}
        else:
            path = "/smas/two/contrast/report"
            params = {"webArticleStr": token}
        response = self._daya_response(
            session,
            referer,
            path,
            "detection report download",
            params=params,
            timeout=max(self.timeout, timeout_seconds),
        )
        suggested = (
            content_disposition_filename(str(response.headers.get("Content-Disposition") or ""))
            or f"{type_key}-report-{token[:16]}.pdf"
        )
        target = self._resource_download_target(
            output_path,
            suggested_name=suggested,
            overwrite=overwrite,
        )
        temporary = target.with_name(target.name + ".part")
        if temporary.exists():
            raise ChaoxingAPIError(f"temporary download target already exists: {temporary}")
        size = 0
        try:
            with temporary.open("wb") as stream:
                for chunk in response.iter_content(chunk_size=1024 * 256):
                    if chunk:
                        stream.write(chunk)
                        size += len(chunk)
            temporary.replace(target)
        except OSError as exc:
            temporary.unlink(missing_ok=True)
            raise ChaoxingAPIError(f"cannot save detection report: {exc}") from exc
        if size <= 0:
            target.unlink(missing_ok=True)
            raise ChaoxingAPIError("downloaded detection report was empty")
        return {
            "type": type_key,
            "record": selected,
            "output_path": str(target),
            "byte_count": size,
            "verification": "non-empty detection report saved through authenticated HTTP",
        }

    def delete_detection_record(self, detection_type: str, record: str) -> dict[str, Any]:
        type_key, config = self._detection_type(detection_type)
        session, referer = self._daya_context()
        selected = self._find_detection_record(session, referer, type_key, config, record)
        payload = self._daya_json(
            session,
            referer,
            config["delete_path"],
            "detection record deletion",
            params={"webArticleStr": selected["token"]},
        )
        self._detection_ack(payload, "detection record deletion")
        refreshed = self._detection_records_page(
            session,
            referer,
            type_key,
            config,
            page=1,
            page_size=1000,
            status=-1,
            begin_date="",
            end_date="",
            search="",
        )["records"]
        if any(item["token"] == selected["token"] for item in refreshed):
            raise ChaoxingAPIError("server acknowledged deletion, but the detection record remains")
        return {
            "type": type_key,
            "deleted_record": selected,
            "verification": "deleted detection record is absent from a fresh HTTP listing",
        }

    @staticmethod
    def _live_integer(value: Any, default: int = 0) -> int:
        try:
            return int(value)
        except (TypeError, ValueError):
            return default

    @staticmethod
    def _live_boolean(value: Any) -> bool:
        if isinstance(value, bool):
            return value
        if isinstance(value, (int, float)):
            return value != 0
        return str(value or "").strip().lower() in {"1", "true", "yes", "on"}

    @staticmethod
    def _live_rich_text(content: str, content_format: str) -> str:
        normalized = str(content_format or "plain").strip().lower()
        if normalized == "html":
            return content.strip()
        if normalized == "plain":
            return (
                "<p>" + escape(content.strip()).replace("\r\n", "\n").replace("\n", "<br>") + "</p>"
            )
        raise ChaoxingAPIError("live content_format must be plain or html")

    @staticmethod
    def _live_schedule(value: str) -> str:
        normalized = value.strip()
        if not normalized:
            return ""
        try:
            datetime.strptime(normalized, "%Y-%m-%d %H:%M")
        except ValueError as exc:
            raise ChaoxingAPIError("live scheduled_time must use YYYY-MM-DD HH:MM") from exc
        return normalized

    def _live_context(
        self,
    ) -> tuple[requests.Session, str, dict[str, str]]:
        session = self._session()
        try:
            response = session.get(
                LIVE_BASE_URL + "/courseLive/personLiveRoomManager",
                timeout=max(self.timeout, 60),
                allow_redirects=True,
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"personal live-room request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError("personal live-room session has expired")
        html = self._decode(response)
        fid_match = re.search(r"\bfid\s*:\s*['\"]?(\d+)", html)
        puid_match = re.search(
            r"(?:\bvar\s+puid|\buserId)\s*=\s*['\"]?(\d+)",
            html,
            flags=re.I,
        )
        if not fid_match or not puid_match:
            raise ChaoxingAPIError("personal live-room page exposed no account context")
        token_matches = re.findall(r"\bs\s*:\s*['\"]([^'\"]*)['\"]", html)
        token = next((item for item in token_matches if item), "")
        return (
            session,
            response.url,
            {
                "fid": fid_match.group(1),
                "puid": puid_match.group(1),
                "token": token,
            },
        )

    def _live_response(
        self,
        session: requests.Session,
        referer: str,
        path: str,
        operation: str,
        *,
        method: str = "GET",
        params: dict[str, Any] | None = None,
        data: dict[str, Any] | None = None,
        files: dict[str, Any] | None = None,
        timeout: float | None = None,
    ) -> requests.Response:
        try:
            response = session.request(
                method.upper(),
                LIVE_BASE_URL + path,
                params=params,
                data=data,
                files=files,
                timeout=timeout or max(self.timeout, 60),
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
                allow_redirects=True,
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"{operation} request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError(f"{operation} was redirected to login")
        return response

    def _live_json(
        self,
        session: requests.Session,
        referer: str,
        path: str,
        operation: str,
        **kwargs: Any,
    ) -> Any:
        response = self._live_response(session, referer, path, operation, **kwargs)
        try:
            payload: Any = json.loads(self._decode(response))
            if isinstance(payload, str):
                payload = json.loads(payload)
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError(f"{operation} response was not JSON") from exc
        return payload

    @staticmethod
    def _live_ack(payload: Any, operation: str) -> None:
        if isinstance(payload, dict):
            result = payload.get("result")
            status = payload.get("status")
            if payload.get("createResult") is True:
                return
            if (
                result is True
                or result == 1
                or str(result).strip().lower()
                in {
                    "true",
                    "1",
                    "success",
                }
            ):
                return
            if status is True or status == 1 or str(status).strip().lower() in {"true", "1"}:
                return
            message = payload.get("message") or payload.get("msg") or payload.get("error")
            raise ChaoxingAPIError(str(message or f"{operation} was not acknowledged"))
        raise ChaoxingAPIError(f"{operation} response was not a JSON object")

    @classmethod
    def _live_verified_mutation_ack(cls, payload: Any, operation: str) -> None:
        """Accept one legacy false response only when a fresh state check follows.

        The recycle restore endpoint returns ``{"result": false}`` after a
        successful restore. Callers using this helper must verify the resulting
        active/recycle state before reporting success.
        """
        if (
            isinstance(payload, dict)
            and payload.get("result") is False
            and not any(payload.get(key) for key in ("message", "msg", "error"))
        ):
            return
        cls._live_ack(payload, operation)

    def _normalize_live_room(self, raw: dict[str, Any], index: int) -> dict[str, Any]:
        live_status = self._live_integer(raw.get("liveStatus"), -1)
        live_type = self._live_integer(raw.get("liveType2"), 0)
        status_label = {
            0: "未开始",
            1: "直播中",
            2: "直播中",
            3: "直播中",
            4: "已结束",
        }.get(live_status, "未知")
        mode = {1: "chaoxing_pc_client", 2: "cloud_live"}.get(live_type, "multi_device")
        room_id = str(raw.get("liveId") or "").strip()
        stream_room_id = str(raw.get("realLiveId") or "").strip()
        if stream_room_id == "0":
            stream_room_id = ""
        return {
            "index": index,
            "room_id": room_id,
            "stream_room_id": stream_room_id,
            "active_id": str(raw.get("activeId") or "").strip(),
            "video_id": str(raw.get("videoId") or "").strip(),
            "title": str(raw.get("liveTitle") or "").strip(),
            "introduction": str(raw.get("introduce") or "").strip(),
            "status": live_status,
            "status_label": status_label,
            "mode": mode,
            "is_cloud": self._live_boolean(raw.get("isYunShi")),
            "scheduled_time": str(raw.get("ygdate") or "").strip(),
            "created_at": str(raw.get("createTime") or raw.get("viewCreateTime") or "").strip(),
            "started_at": str(raw.get("startDate") or raw.get("viewStartTime") or "").strip(),
            "ended_at": str(raw.get("endDate") or "").strip(),
            "deleted_at": str(raw.get("deletedTime") or raw.get("viewDeleteTime") or "").strip(),
            "duration_seconds": self._live_integer(raw.get("duration"), 0),
            "cover_object_id": str(raw.get("ygimg") or "").strip(),
            "can_start_with_chaoxing_client": (
                live_status == 0 and self._live_integer(raw.get("ysClientDataVersion"), 0) == 1
            ),
            "watch_url": f"https://zhibo.chaoxing.com/{room_id}" if room_id else "",
        }

    def _live_room_records(
        self,
        session: requests.Session,
        referer: str,
        context: dict[str, str],
        *,
        search: str = "",
        start_time: str = "",
        end_time: str = "",
        sort_key: int = 0,
        sort_type: int = 0,
        max_items: int = 1000,
    ) -> tuple[list[tuple[dict[str, Any], dict[str, Any]]], int]:
        if max_items < 1:
            raise ChaoxingAPIError("max_items must be positive")
        page = 1
        page_size = min(100, max_items)
        total = 0
        seen: set[str] = set()
        records: list[tuple[dict[str, Any], dict[str, Any]]] = []
        while len(records) < max_items:
            payload = self._live_json(
                session,
                referer,
                "/courseLive/personLiveRoomManager",
                "personal live-room listing",
                params={
                    "page": page,
                    "pageSize": page_size,
                    "title": search,
                    "startTime": start_time,
                    "endTime": end_time,
                    "type": 1,
                    "customizedValue": "chaoxing",
                    "s": context["token"],
                    "sortKey": sort_key,
                    "sortType": sort_type,
                },
            )
            if not isinstance(payload, dict):
                raise ChaoxingAPIError("personal live-room listing returned invalid JSON")
            raw_items = payload.get("list") if isinstance(payload.get("list"), list) else []
            total = self._live_integer(payload.get("count"), len(records) + len(raw_items))
            for raw in raw_items:
                if not isinstance(raw, dict):
                    continue
                normalized = self._normalize_live_room(raw, len(records) + 1)
                identity = normalized["room_id"] or normalized["active_id"]
                if not identity or identity in seen:
                    continue
                seen.add(identity)
                records.append((normalized, raw))
                if len(records) >= max_items:
                    break
            if not raw_items or len(records) >= total or len(raw_items) < page_size:
                break
            page += 1
        return records, total

    @staticmethod
    def _resolve_live_record(
        records: list[tuple[dict[str, Any], dict[str, Any]]], query: str, label: str
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        normalized = query.strip().lower()
        if not normalized:
            raise ChaoxingAPIError(f"{label} is required")
        exact = [
            record
            for record in records
            if normalized
            in {
                str(record[0].get("room_id") or "").lower(),
                str(record[0].get("stream_room_id") or "").lower(),
                str(record[0].get("active_id") or "").lower(),
                str(record[0].get("video_id") or "").lower(),
                str(record[0].get("title") or "").strip().lower(),
                str(record[0].get("index") or ""),
            }
        ]
        partial = [
            record
            for record in records
            if normalized in str(record[0].get("title") or "").strip().lower()
        ]
        candidates = exact or partial
        if len(candidates) == 1:
            return candidates[0]
        if not candidates:
            raise ChaoxingAPIError(f"{label} not found: {query}")
        raise ChaoxingAPIError(
            f"multiple {label} matches: "
            + ", ".join(
                f"{item[0].get('title')} ({item[0].get('room_id')})" for item in candidates[:10]
            )
        )

    def list_live_rooms(
        self,
        *,
        search: str = "",
        start_time: str = "",
        end_time: str = "",
        sort_key: int = 0,
        sort_type: int = 0,
        max_items: int = 1000,
    ) -> dict[str, Any]:
        session, referer, context = self._live_context()
        records, total = self._live_room_records(
            session,
            referer,
            context,
            search=search.strip(),
            start_time=start_time.strip(),
            end_time=end_time.strip(),
            sort_key=sort_key,
            sort_type=sort_type,
            max_items=max_items,
        )
        return {
            "search": search.strip(),
            "count": len(records),
            "total": total,
            "rooms": [item[0] for item in records],
            "verification": "personal live rooms parsed from fresh authenticated HTTP responses",
        }

    def _find_live_room(
        self,
        session: requests.Session,
        referer: str,
        context: dict[str, str],
        query: str,
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        records, _total = self._live_room_records(session, referer, context, max_items=5000)
        return self._resolve_live_record(records, query, "live room")

    def _live_room_detail(
        self,
        session: requests.Session,
        referer: str,
        room: dict[str, Any],
        raw: dict[str, Any],
    ) -> dict[str, Any]:
        payload = self._live_json(
            session,
            referer,
            "/courseLive/getLiveConfig",
            "live-room configuration",
            params={"LiveId": room["room_id"]},
        )
        if not isinstance(payload, dict) or not isinstance(payload.get("data"), dict):
            raise ChaoxingAPIError("live-room configuration returned invalid JSON")
        detail = payload["data"]
        config = detail.get("configObj")
        if not isinstance(config, dict):
            config = _json_dict(detail.get("config"))
        metadata = self._live_json(
            session,
            referer,
            "/courseLive/liveTitleAndIntroduce",
            "live-room metadata",
            params={"liveId": room["room_id"]},
        )
        if not isinstance(metadata, dict):
            metadata = {}
        stream_room_id = room["stream_room_id"] or str(detail.get("liveId") or "")
        preview_object_id = str(config.get("preVideo") or "").strip()
        normalized = {
            **room,
            "stream_room_id": stream_room_id,
            "title": str(metadata.get("title") or detail.get("liveTitle") or room["title"]),
            "introduction": str(
                metadata.get("introduce") or detail.get("introduce") or room["introduction"]
            ),
            "scheduled_time": str(
                metadata.get("ygdate") or detail.get("ygdate") or room["scheduled_time"]
            ),
            "preview_video_object_id": preview_object_id,
            "preview_video_url_available": bool(preview_object_id),
            "stream_credentials_available": bool(detail.get("pushUrl") or raw.get("pushUrl")),
        }
        settings = {
            "comments_enabled": self._live_boolean(detail.get("comment")),
            "forwarding_enabled": self._live_boolean(
                config.get("forward", detail.get("rewardValue"))
            ),
            # The page treats ifReview=1 as "replay disabled" and removes the
            # checked state from the "allow replay" switch.
            "replay_enabled": not self._live_boolean(detail.get("ifReview")),
            "learning_app_only": self._live_boolean(detail.get("onlyInXxt")),
            "chat_content_review": self._live_boolean(detail.get("contentReview")),
            "login_required": self._live_boolean(detail.get("loginWatchValue")),
            "picture_live": self._live_boolean(detail.get("pictureLive")),
            "access_password": str(config.get("pwd") or ""),
            "show_viewer_count": self._live_boolean(config.get("showUserCountInLivingRoom")),
            "reservations_enabled": self._live_boolean(config.get("ifSubscribe")),
            "preupload_enabled": self._live_boolean(config.get("preUpload")),
            "allowed_unit_ids": [
                value for value in str(config.get("allowAccessFids") or "").split(",") if value
            ],
            "replay_start_offset_seconds": self._live_integer(detail.get("videoPlayStartTime"), 0),
        }
        return {
            "room": normalized,
            "settings": settings,
            "_detail": detail,
            "verification": "live-room metadata and settings read from fresh HTTP responses",
        }

    def read_live_room(self, room: str) -> dict[str, Any]:
        session, referer, context = self._live_context()
        selected, raw = self._find_live_room(session, referer, context, room)
        result = self._live_room_detail(session, referer, selected, raw)
        result.pop("_detail", None)
        return result

    def create_live_room(
        self,
        title: str,
        *,
        scheduled_time: str = "",
        introduction: str = "",
        content_format: str = "plain",
        mode: str = "multi_device",
        chat_content_review: bool = True,
        cover_object_id: str = "",
        preview_video_object_id: str = "",
        extends_info: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        title = title.strip()
        if not title or len(title) > 200:
            raise ChaoxingAPIError("live title must contain 1..200 characters")
        mode_key = mode.strip().lower().replace("-", "_")
        mode_aliases = {
            "multi_device": "1",
            "regular": "1",
            "web": "1",
            "phone": "1",
            "chaoxing_pc_client": "2",
            "pc_client": "2",
            "client": "2",
        }
        if mode_key not in mode_aliases:
            raise ChaoxingAPIError("live mode must be multi_device or chaoxing_pc_client")
        schedule = self._live_schedule(scheduled_time)
        rich_introduction = self._live_rich_text(introduction, content_format)
        session, referer, context = self._live_context()
        before, _total = self._live_room_records(
            session, referer, context, search=title, max_items=5000
        )
        before_ids = {item[0]["room_id"] for item in before}
        payload = self._live_json(
            session,
            referer,
            "/courseLive/newCteateLive",
            "live-room creation",
            method="POST",
            data={
                "type": mode_aliases[mode_key],
                "title": title,
                "ygdate": schedule,
                "jieshao": rich_introduction,
                "chatContentReview": str(bool(chat_content_review)).lower(),
                "ygimg": cover_object_id.strip(),
                "s": context["token"],
                "objectId": preview_video_object_id.strip(),
                "customizedValue": "chaoxing",
                "extendsInfo": json.dumps(extends_info, ensure_ascii=False)
                if extends_info is not None
                else "null",
            },
        )
        self._live_ack(payload, "live-room creation")
        after, _total = self._live_room_records(
            session, referer, context, search=title, max_items=5000
        )
        active_id = str(payload.get("activeId") or "") if isinstance(payload, dict) else ""
        candidates = [
            item
            for item in after
            if item[0]["room_id"] not in before_ids
            and item[0]["title"] == title
            and (not active_id or item[0]["active_id"] == active_id)
        ]
        if len(candidates) != 1:
            raise ChaoxingAPIError(
                "server acknowledged live-room creation, but fresh listing did not verify it"
            )
        detail = self._live_room_detail(session, referer, *candidates[0])
        detail.pop("_detail", None)
        detail["verification"] = "created live room matches fresh metadata and list reads"
        return detail

    def update_live_room(
        self,
        room: str,
        *,
        title: str | None = None,
        scheduled_time: str | None = None,
        introduction: str | None = None,
        content_format: str = "plain",
        cover_object_id: str | None = None,
        preview_video_object_id: str | None = None,
    ) -> dict[str, Any]:
        session, referer, context = self._live_context()
        selected, raw = self._find_live_room(session, referer, context, room)
        current = self._live_room_detail(session, referer, selected, raw)
        next_title = current["room"]["title"] if title is None else title.strip()
        if not next_title or len(next_title) > 200:
            raise ChaoxingAPIError("live title must contain 1..200 characters")
        next_schedule = (
            current["room"]["scheduled_time"]
            if scheduled_time is None
            else self._live_schedule(scheduled_time)
        )
        next_introduction = (
            current["room"]["introduction"]
            if introduction is None
            else self._live_rich_text(introduction, content_format)
        )
        next_cover = (
            current["room"]["cover_object_id"]
            if cover_object_id is None
            else cover_object_id.strip()
        )
        next_preview = (
            current["room"]["preview_video_object_id"]
            if preview_video_object_id is None
            else preview_video_object_id.strip()
        )
        payload = self._live_json(
            session,
            referer,
            "/courseLive/newUpdateLive",
            "live-room update",
            method="POST",
            data={
                "isYunshi": int(current["room"]["is_cloud"]),
                "status": current["room"]["status"],
                "liveId": current["room"]["room_id"],
                "title": next_title,
                "ygdate": next_schedule,
                "jieshao": next_introduction,
                "ygimg": next_cover,
                "fid": context["fid"],
                "s": context["token"],
                "objectId": next_preview,
                "customizedValue": "chaoxing",
            },
        )
        self._live_ack(payload, "live-room update")
        refreshed_room, refreshed_raw = self._find_live_room(
            session, referer, context, current["room"]["room_id"]
        )
        refreshed = self._live_room_detail(session, referer, refreshed_room, refreshed_raw)
        refreshed.pop("_detail", None)
        expected = {
            "title": next_title,
            "scheduled_time": next_schedule,
            "introduction": next_introduction,
            "cover_object_id": next_cover,
            "preview_video_object_id": next_preview,
        }
        if any(refreshed["room"].get(key) != value for key, value in expected.items()):
            raise ChaoxingAPIError(
                "server acknowledged live-room update, but fresh metadata did not verify it"
            )
        refreshed["verification"] = "updated live-room metadata matches fresh HTTP reads"
        return refreshed

    def update_live_room_settings(
        self,
        room: str,
        *,
        comments_enabled: bool | None = None,
        forwarding_enabled: bool | None = None,
        replay_enabled: bool | None = None,
        learning_app_only: bool | None = None,
        chat_content_review: bool | None = None,
        login_required: bool | None = None,
        picture_live: bool | None = None,
        access_password: str | None = None,
        show_viewer_count: bool | None = None,
        reservations_enabled: bool | None = None,
        preupload_enabled: bool | None = None,
        allowed_unit_ids: list[str] | None = None,
        replay_start_offset_seconds: int | None = None,
    ) -> dict[str, Any]:
        session, referer, context = self._live_context()
        selected, raw = self._find_live_room(session, referer, context, room)
        current = self._live_room_detail(session, referer, selected, raw)
        settings = dict(current["settings"])
        updates = {
            "comments_enabled": comments_enabled,
            "forwarding_enabled": forwarding_enabled,
            "replay_enabled": replay_enabled,
            "learning_app_only": learning_app_only,
            "chat_content_review": chat_content_review,
            "login_required": login_required,
            "picture_live": picture_live,
            "access_password": access_password,
            "show_viewer_count": show_viewer_count,
            "reservations_enabled": reservations_enabled,
            "preupload_enabled": preupload_enabled,
            "allowed_unit_ids": allowed_unit_ids,
            "replay_start_offset_seconds": replay_start_offset_seconds,
        }
        for key, value in updates.items():
            if value is not None:
                settings[key] = value
        offset = self._live_integer(settings["replay_start_offset_seconds"], -1)
        if offset < 0 or offset > 86_399:
            raise ChaoxingAPIError("replay_start_offset_seconds must be 0..86399")
        allowed = [
            str(value).strip() for value in settings["allowed_unit_ids"] if str(value).strip()
        ]
        hours, remainder = divmod(offset, 3600)
        minutes, seconds = divmod(remainder, 60)
        payload = self._live_json(
            session,
            referer,
            "/courseLive/setLive",
            "live-room settings update",
            params={
                "liveId": current["room"]["room_id"],
                "rid": current["room"]["video_id"],
                "comment": str(bool(settings["comments_enabled"])).lower(),
                "forward": str(bool(settings["forwarding_enabled"])).lower(),
                "reminisce": str(bool(settings["replay_enabled"])).lower(),
                "xuexitong": str(bool(settings["learning_app_only"])).lower(),
                "isYunshi": int(current["room"]["is_cloud"]),
                "chatContentReview": str(bool(settings["chat_content_review"])).lower(),
                "loginWatch": str(bool(settings["login_required"])).lower(),
                "pictureLive": str(bool(settings["picture_live"])).lower(),
                "pwd": str(settings["access_password"] or ""),
                "h": hours,
                "m": minutes,
                "s": seconds,
                "showUserCountInLivingRoom": str(bool(settings["show_viewer_count"])).lower(),
                "ifSubscribe": str(bool(settings["reservations_enabled"])).lower(),
                "preUpload": str(bool(settings["preupload_enabled"])).lower(),
                "allowAccessFids": ",".join(allowed),
            },
        )
        self._live_ack(payload, "live-room settings update")
        refreshed_room, refreshed_raw = self._find_live_room(
            session, referer, context, current["room"]["room_id"]
        )
        refreshed = self._live_room_detail(session, referer, refreshed_room, refreshed_raw)
        refreshed.pop("_detail", None)
        expected = {**settings, "allowed_unit_ids": allowed, "replay_start_offset_seconds": offset}
        if any(refreshed["settings"].get(key) != value for key, value in expected.items()):
            raise ChaoxingAPIError(
                "server acknowledged live-room settings update, but fresh read did not verify it"
            )
        refreshed["verification"] = "live-room settings match a fresh configuration read"
        return refreshed

    def read_live_room_status(self, room: str) -> dict[str, Any]:
        session, referer, context = self._live_context()
        selected, raw = self._find_live_room(session, referer, context, room)
        stream_payload = self._live_json(
            session,
            referer,
            "/liveAPI/getlivestatus",
            "live stream status",
            params={"streamName": raw.get("streamName", ""), "vdoid": raw.get("vdoid", "")},
        )
        stream_room_id = selected["stream_room_id"]
        room_payload: Any = {}
        if stream_room_id:
            room_payload = self._live_json(
                session,
                referer,
                "/liveAPI/getLiveStatusByLiveId",
                "live room status",
                params={"liveId": stream_room_id},
            )
        return {
            "room": selected,
            "stream_status": stream_payload,
            "room_status": room_payload,
            "verification": "live status read from both available status endpoints",
        }

    def read_live_watch_address(self, room: str) -> dict[str, Any]:
        session, referer, context = self._live_context()
        selected, raw = self._find_live_room(session, referer, context, room)
        response = self._live_response(
            session,
            referer,
            "/courseLive/watchAddress",
            "live watch-address read",
            params={
                "liveId": selected["room_id"],
                "streamName": raw.get("streamName", ""),
                "vdoid": raw.get("vdoid", ""),
                "status": selected["status"],
                "isYunshi": int(selected["is_cloud"]),
                "videoId": selected["video_id"],
                "customizedValue": raw.get("customizedValue") or "",
            },
        )
        html = self._decode(response)
        address = re.search(
            r'<span\b[^>]*id=["\']watchUrl["\'][^>]*>(.*?)</span>',
            html,
            flags=re.I | re.S,
        )
        invitation = re.search(
            r'<p\b[^>]*class=["\'][^"\']*Invitation[^"\']*["\'][^>]*>.*?'
            r"<span[^>]*>(.*?)</span>",
            html,
            flags=re.I | re.S,
        )
        info_text = html_text(html, limit=3000)
        valid_until = ""
        date_match = re.search(r"\((\d{2}-\d{2})", info_text)
        if date_match:
            valid_until = date_match.group(1)
        return {
            "room": selected,
            "watch_url": html_text(address.group(1)) if address else selected["watch_url"],
            "invitation_code": html_text(invitation.group(1)) if invitation else "",
            "invitation_code_valid_until": valid_until,
            "verification": "watch URL and invitation code parsed from a fresh HTTP page",
        }

    def read_live_stream_credentials(self, room: str) -> dict[str, Any]:
        session, referer, context = self._live_context()
        selected, raw = self._find_live_room(session, referer, context, room)
        current = self._live_room_detail(session, referer, selected, raw)
        detail = current["_detail"]
        push_url = str(detail.get("pushUrl") or raw.get("pushUrl") or "").strip()
        if not push_url:
            raise ChaoxingAPIError("live room exposes no RTMP push credential")
        return {
            "room": current["room"],
            "push_url": push_url,
            "rtmp_pull_url": str(detail.get("rtmpPullUrl") or raw.get("rtmpPullUrl") or ""),
            "flv_pull_url": str(detail.get("flvPullUrl") or raw.get("flvPullUrl") or ""),
            "hls_pull_url": str(detail.get("m3u8PullUrl") or raw.get("m3u8PullUrl") or ""),
            "recording_hls_url": str(detail.get("m3u8DownUrl") or raw.get("m3u8DownUrl") or ""),
            "recording_mp4_url": str(detail.get("mp4DownUrl") or raw.get("mp4DownUrl") or ""),
            "usage": (
                "Publish an RTMP media stream to push_url with ffmpeg or another RTMP sender; "
                "stopping that sender ends the outgoing stream. No Chaoxing client is required."
            ),
            "verification": "stream endpoints read from the authenticated live configuration",
        }

    def list_live_units(self) -> dict[str, Any]:
        session, referer, _context = self._live_context()
        payload = self._live_json(
            session,
            referer,
            "/courseLive/getCurrentUnits",
            "live access-unit listing",
        )
        if not isinstance(payload, dict) or self._live_integer(payload.get("result"), 0) != 1:
            raise ChaoxingAPIError("live access-unit listing was not acknowledged")
        raw_items = payload.get("data") if isinstance(payload.get("data"), list) else []
        units: list[dict[str, Any]] = []
        seen: set[tuple[str, str]] = set()
        for raw in raw_items:
            if not isinstance(raw, dict):
                continue
            unit_id = str(raw.get("id") or "").strip()
            name = str(raw.get("name") or "").strip()
            identity = (unit_id, name)
            if not unit_id or identity in seen:
                continue
            seen.add(identity)
            units.append({"index": len(units) + 1, "unit_id": unit_id, "name": name})
        return {
            "count": len(units),
            "units": units,
            "verification": "available live access units read through HTTP",
        }

    def export_live_rooms(
        self,
        *,
        search: str = "",
        start_time: str = "",
        end_time: str = "",
        sort_key: int = 0,
        sort_type: int = 0,
    ) -> dict[str, Any]:
        session, referer, _context = self._live_context()
        payload = self._live_json(
            session,
            referer,
            "/courseLive/exportLiveBatch",
            "live-room export",
            method="POST",
            data={
                "selectAll": "true",
                "title": search.strip(),
                "startTime": start_time.strip(),
                "endTime": end_time.strip(),
                "sortKey": sort_key,
                "sortType": sort_type,
            },
        )
        self._live_ack(payload, "live-room export")
        return {
            "queued": True,
            "delivery": "Chaoxing inbox",
            "message": str(payload.get("msg") or "") if isinstance(payload, dict) else "",
            "verification": "Chaoxing acknowledged generation of the live-room export",
        }

    def upload_live_asset(
        self,
        file: str | Path,
        *,
        kind: str,
        room: str = "",
    ) -> dict[str, Any]:
        kind_key = kind.strip().lower().replace("-", "_")
        if kind_key not in {"cover", "preview_video"}:
            raise ChaoxingAPIError("live asset kind must be cover or preview_video")
        path = Path(file).expanduser().resolve()
        if not path.is_file():
            raise ChaoxingAPIError(f"live asset file not found: {path}")
        suffix = path.suffix.lower()
        if kind_key == "cover" and suffix not in {".jpg", ".jpeg", ".gif", ".png"}:
            raise ChaoxingAPIError("live cover must be JPG, JPEG, GIF, or PNG")
        if kind_key == "cover" and path.stat().st_size > 4 * 1024 * 1024:
            raise ChaoxingAPIError("live cover exceeds 4 MiB")
        if kind_key == "preview_video" and suffix != ".mp4":
            raise ChaoxingAPIError("live preview video must be MP4")
        session, referer, context = self._live_context()
        endpoint_payload = self._live_json(
            session,
            referer,
            "/liveAPI/getYunpanUploadUrl",
            "live asset upload endpoint",
            params={"userId": context["puid"], "prdid": 447},
        )
        if (
            not isinstance(endpoint_payload, dict)
            or self._live_integer(endpoint_payload.get("result"), 0) != 1
        ):
            raise ChaoxingAPIError("live asset upload endpoint was not available")
        upload_url = validated_chaoxing_url(
            str(endpoint_payload.get("uploadfileUrl") or ""), "live upload URL"
        )
        try:
            with path.open("rb") as stream:
                response = session.post(
                    upload_url,
                    files={
                        "file": (
                            path.name,
                            stream,
                            mimetypes.guess_type(path.name)[0] or "application/octet-stream",
                        )
                    },
                    timeout=max(self.timeout, 300),
                    headers={"Referer": referer},
                )
                response.raise_for_status()
        except (OSError, requests.RequestException) as exc:
            raise ChaoxingAPIError(f"live asset upload failed: {exc}") from exc
        try:
            result = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("live asset upload response was not JSON") from exc
        data = result.get("data") if isinstance(result, dict) else None
        object_id = str(data.get("objectId") or "").strip() if isinstance(data, dict) else ""
        if not object_id or not self._live_boolean(result.get("result")):
            raise ChaoxingAPIError("live asset upload was not acknowledged")
        attachment = None
        if room:
            attachment = self.update_live_room(
                room,
                **(
                    {"cover_object_id": object_id}
                    if kind_key == "cover"
                    else {"preview_video_object_id": object_id}
                ),
            )
        return {
            "kind": kind_key,
            "object_id": object_id,
            "file_name": path.name,
            "byte_count": path.stat().st_size,
            "attached_room": attachment["room"] if attachment else None,
            "verification": (
                "uploaded asset was attached and verified on the requested live room"
                if attachment
                else "Chaoxing cloud acknowledged the uploaded live asset"
            ),
        }

    def _live_recycle_records(
        self,
        session: requests.Session,
        referer: str,
        *,
        search: str = "",
        max_items: int = 1000,
    ) -> list[tuple[dict[str, Any], dict[str, Any]]]:
        if max_items < 1:
            raise ChaoxingAPIError("max_items must be positive")
        records: list[tuple[dict[str, Any], dict[str, Any]]] = []
        seen: set[str] = set()
        page = 1
        page_size = min(100, max_items)
        while len(records) < max_items:
            payload = self._live_json(
                session,
                referer,
                "/courseLive/deletedLiveRoomManager",
                "live recycle listing",
                params={
                    "page": page,
                    "pageSize": page_size,
                    "title": search.strip(),
                    "type": 0,
                },
            )
            if payload is None:
                raw_items: list[Any] = []
            elif isinstance(payload, list):
                raw_items = payload
            else:
                raise ChaoxingAPIError("live recycle listing returned invalid JSON")
            for raw in raw_items:
                if not isinstance(raw, dict):
                    continue
                normalized = self._normalize_live_room(raw, len(records) + 1)
                identity = normalized["room_id"] or normalized["active_id"]
                if not identity or identity in seen:
                    continue
                seen.add(identity)
                records.append((normalized, raw))
                if len(records) >= max_items:
                    break
            if not raw_items or len(raw_items) < page_size:
                break
            page += 1
        return records

    def list_live_recycle(self, *, search: str = "", max_items: int = 1000) -> dict[str, Any]:
        session, referer, _context = self._live_context()
        records = self._live_recycle_records(session, referer, search=search, max_items=max_items)
        return {
            "search": search.strip(),
            "count": len(records),
            "rooms": [item[0] for item in records],
            "verification": "live recycle bin parsed from fresh authenticated HTTP responses",
        }

    def delete_live_room(self, room: str) -> dict[str, Any]:
        session, referer, context = self._live_context()
        selected, _raw = self._find_live_room(session, referer, context, room)
        payload = self._live_json(
            session,
            referer,
            "/courseLive/newDeleteOneLive",
            "live-room deletion",
            params={
                "liveId": selected["room_id"],
                "isYunshi": int(selected["is_cloud"]),
                "fid": context["fid"],
                "s": context["token"],
            },
        )
        self._live_verified_mutation_ack(payload, "live-room deletion")
        active, _total = self._live_room_records(session, referer, context, max_items=5000)
        recycle = self._live_recycle_records(session, referer, max_items=5000)
        if any(item[0]["room_id"] == selected["room_id"] for item in active) or not any(
            item[0]["room_id"] == selected["room_id"] for item in recycle
        ):
            raise ChaoxingAPIError(
                "server acknowledged live-room deletion, but recycle reads did not verify it"
            )
        return {
            "deleted_room": selected,
            "verification": "live room is absent from active rooms and present in recycle bin",
        }

    def restore_live_room(self, room: str) -> dict[str, Any]:
        session, referer, context = self._live_context()
        records = self._live_recycle_records(session, referer, max_items=5000)
        selected, _raw = self._resolve_live_record(records, room, "recycled live room")
        payload = self._live_json(
            session,
            referer,
            "/courseLive/resumeLive",
            "live-room restore",
            params={"liveId": selected["room_id"], "isYunshi": int(selected["is_cloud"])},
        )
        self._live_verified_mutation_ack(payload, "live-room restore")
        active, _total = self._live_room_records(session, referer, context, max_items=5000)
        recycle = self._live_recycle_records(session, referer, max_items=5000)
        if not any(item[0]["room_id"] == selected["room_id"] for item in active) or any(
            item[0]["room_id"] == selected["room_id"] for item in recycle
        ):
            raise ChaoxingAPIError(
                "server acknowledged live-room restore, but fresh reads did not verify it"
            )
        restored = next(item[0] for item in active if item[0]["room_id"] == selected["room_id"])
        return {
            "restored_room": restored,
            "verification": "live room is present in active rooms and absent from recycle bin",
        }

    def permanently_delete_live_room(self, room: str) -> dict[str, Any]:
        session, referer, _context = self._live_context()
        records = self._live_recycle_records(session, referer, max_items=5000)
        selected, _raw = self._resolve_live_record(records, room, "recycled live room")
        payload = self._live_json(
            session,
            referer,
            "/courseLive/deleteLiveForever",
            "permanent live-room deletion",
            params={"liveId": selected["room_id"], "isYunshi": int(selected["is_cloud"])},
        )
        self._live_verified_mutation_ack(payload, "permanent live-room deletion")
        remaining = self._live_recycle_records(session, referer, max_items=5000)
        if any(item[0]["room_id"] == selected["room_id"] for item in remaining):
            raise ChaoxingAPIError(
                "server acknowledged permanent live-room deletion, but it remains visible"
            )
        return {
            "deleted_room": selected,
            "verification": "live room is absent from a fresh recycle-bin read",
        }

    def _normalize_live_theme(self, raw: dict[str, Any], index: int) -> dict[str, Any]:
        config = _json_dict(raw.get("configJson"))
        status = self._live_integer(raw.get("status"), -1)
        allowed_units = [
            value for value in str(config.get("limitViewingFid") or "").split(",") if value
        ]
        return {
            "index": index,
            "theme_id": str(raw.get("themedLiveId") or "").strip(),
            "name": str(raw.get("name") or "").strip(),
            "description": str(raw.get("description") or "").strip(),
            "status": status,
            "status_label": {0: "未开始", 1: "直播中", 2: "已结束"}.get(status, "未知"),
            "created_at": raw.get("createTime"),
            "updated_at": raw.get("updateTime"),
            "settings": {
                "forwarding_enabled": self._live_boolean(config.get("isForwardingIsAllowed")),
                "replay_enabled": self._live_boolean(config.get("isRetrospectivesAreAllowed")),
                "learning_app_only": self._live_boolean(config.get("isOnlyXxtAllowed")),
                "login_required": self._live_boolean(config.get("isOnlyLoginAllowed")),
                "allowed_unit_ids": allowed_units,
            },
            "invitation_code": str(config.get("invitationCode") or ""),
        }

    def _live_theme_records(
        self,
        session: requests.Session,
        referer: str,
        context: dict[str, str],
        *,
        search: str = "",
        max_items: int = 1000,
    ) -> tuple[list[tuple[dict[str, Any], dict[str, Any]]], int]:
        if max_items < 1:
            raise ChaoxingAPIError("max_items must be positive")
        page = 1
        page_size = min(100, max_items)
        records: list[tuple[dict[str, Any], dict[str, Any]]] = []
        total = 0
        while len(records) < max_items:
            payload = self._live_json(
                session,
                referer,
                "/themedLive/getThemedLiveList",
                "themed-live listing",
                method="POST",
                data={
                    "page": page,
                    "pageSize": page_size,
                    "fid": context["fid"],
                    "title": search.strip(),
                },
            )
            if not isinstance(payload, dict) or self._live_integer(payload.get("status"), 0) != 1:
                raise ChaoxingAPIError(
                    str(
                        payload.get("message")
                        if isinstance(payload, dict)
                        else "themed-live listing returned invalid JSON"
                    )
                )
            raw_items = payload.get("list") if isinstance(payload.get("list"), list) else []
            total = self._live_integer(payload.get("totalCount"), len(records) + len(raw_items))
            for raw in raw_items:
                if not isinstance(raw, dict):
                    continue
                records.append((self._normalize_live_theme(raw, len(records) + 1), raw))
                if len(records) >= max_items:
                    break
            if not raw_items or len(records) >= total or len(raw_items) < page_size:
                break
            page += 1
        return records, total

    @staticmethod
    def _resolve_live_theme_record(
        records: list[tuple[dict[str, Any], dict[str, Any]]], query: str
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        normalized = query.strip().lower()
        if not normalized:
            raise ChaoxingAPIError("live theme is required")
        exact = [
            record
            for record in records
            if normalized
            in {
                str(record[0].get("theme_id") or "").lower(),
                str(record[0].get("name") or "").strip().lower(),
                str(record[0].get("index") or ""),
            }
        ]
        partial = [
            record
            for record in records
            if normalized in str(record[0].get("name") or "").strip().lower()
        ]
        candidates = exact or partial
        if len(candidates) == 1:
            return candidates[0]
        if not candidates and re.fullmatch(r"[A-Za-z0-9_-]{20,}", query.strip()):
            return (
                {
                    "index": 0,
                    "theme_id": query.strip(),
                    "name": "",
                    "description": "",
                    "status": -1,
                    "status_label": "未知",
                    "created_at": None,
                    "updated_at": None,
                    "settings": {},
                    "invitation_code": "",
                },
                {"themedLiveId": query.strip()},
            )
        if not candidates:
            raise ChaoxingAPIError(f"live theme not found: {query}")
        raise ChaoxingAPIError(
            "multiple live theme matches: "
            + ", ".join(
                f"{item[0].get('name')} ({item[0].get('theme_id')})" for item in candidates[:10]
            )
        )

    def _find_live_theme(
        self,
        session: requests.Session,
        referer: str,
        context: dict[str, str],
        query: str,
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        records, _total = self._live_theme_records(session, referer, context, max_items=5000)
        return self._resolve_live_theme_record(records, query)

    def _live_theme_detail_context(
        self,
        session: requests.Session,
        referer: str,
        context: dict[str, str],
        theme: dict[str, Any],
    ) -> dict[str, Any]:
        response = self._live_response(
            session,
            referer,
            "/courseLive/openThemedLiveDetail",
            "themed-live detail",
            params={
                "themedLiveId": theme["theme_id"],
                "type": 0,
                "page": 1,
                "pageSize": 10,
                "customizedValue": "chaoxing",
                "liveStatus": "",
                "title": "",
                "startTime": "",
                "endTime": "",
                "fid": context["fid"],
                "s": context["token"],
                "r": "",
                "browserLocale": "",
                "sortKey": 0,
                "sortType": 0,
            },
        )
        html = self._decode(response)
        internal = re.search(r"themedLiveId\s*:\s*['\"]([^'\"]+)['\"]", html)
        if not internal:
            raise ChaoxingAPIError("themed-live detail exposed no internal identifier")
        invitation = re.search(r"invitationCode\s*:\s*['\"]([^'\"]*)['\"]", html)
        name = re.search(r"themedLiveName\s*:\s*['\"]([^'\"]*)['\"]", html)
        address = re.search(r"copyAddress\s*:\s*['\"]([^'\"]+)['\"]\s*\+\s*['\"]([^'\"]+)", html)
        watch_url = ""
        if address:
            watch_url = address.group(1) + address.group(2)
        if not watch_url:
            watch_url = f"https://zhibo.chaoxing.com/themedLive/{internal.group(1)}"
        return {
            "internal_theme_id": internal.group(1),
            "name": unescape(name.group(1)) if name else theme.get("name", ""),
            "invitation_code": invitation.group(1) if invitation else "",
            "watch_url": watch_url,
            "referer": response.url,
        }

    def _live_theme_room_records(
        self,
        session: requests.Session,
        detail: dict[str, Any],
        context: dict[str, str],
        *,
        search: str = "",
        max_items: int = 1000,
    ) -> tuple[list[tuple[dict[str, Any], dict[str, Any]]], int]:
        page = 1
        page_size = min(100, max_items)
        records: list[tuple[dict[str, Any], dict[str, Any]]] = []
        total = 0
        seen: set[str] = set()
        while len(records) < max_items:
            payload = self._live_json(
                session,
                detail["referer"],
                "/courseLive/getLiveListOfThemedLive",
                "themed-live room listing",
                params={
                    "page": page,
                    "pageSize": page_size,
                    "title": search.strip(),
                    "startTime": "",
                    "endTime": "",
                    "type": 1,
                    "customizedValue": "chaoxing",
                    "s": context["token"],
                    "sortKey": 0,
                    "sortType": 0,
                    "themedLiveId": detail["internal_theme_id"],
                },
            )
            if not isinstance(payload, dict):
                raise ChaoxingAPIError("themed-live room listing returned invalid JSON")
            raw_items = payload.get("list") if isinstance(payload.get("list"), list) else []
            total = self._live_integer(payload.get("count"), len(records) + len(raw_items))
            for raw in raw_items:
                if not isinstance(raw, dict):
                    continue
                normalized = self._normalize_live_room(raw, len(records) + 1)
                if not normalized["room_id"] or normalized["room_id"] in seen:
                    continue
                seen.add(normalized["room_id"])
                records.append((normalized, raw))
                if len(records) >= max_items:
                    break
            if not raw_items or len(records) >= total or len(raw_items) < page_size:
                break
            page += 1
        return records, total

    def list_live_themes(self, *, search: str = "", max_items: int = 1000) -> dict[str, Any]:
        session, referer, context = self._live_context()
        records, total = self._live_theme_records(
            session, referer, context, search=search, max_items=max_items
        )
        return {
            "search": search.strip(),
            "count": len(records),
            "total": total,
            "ui_entry_visible": context["fid"] in {"1385", "184815"},
            "themes": [item[0] for item in records],
            "verification": "themed-live records read through authenticated HTTP",
        }

    def read_live_theme(self, theme: str, *, max_rooms: int = 1000) -> dict[str, Any]:
        session, referer, context = self._live_context()
        selected, raw = self._find_live_theme(session, referer, context, theme)
        detail = self._live_theme_detail_context(session, referer, context, selected)
        rooms, total = self._live_theme_room_records(session, detail, context, max_items=max_rooms)
        current = selected
        if not current["name"]:
            current = {**selected, "name": detail["name"]}
        if not current["invitation_code"]:
            current = {**current, "invitation_code": detail["invitation_code"]}
        return {
            "theme": current,
            "watch_url": detail["watch_url"],
            "invitation_code": detail["invitation_code"] or current["invitation_code"],
            "room_count": len(rooms),
            "room_total": total,
            "rooms": [item[0] for item in rooms],
            "verification": "themed-live metadata and child rooms read through HTTP",
        }

    def create_live_theme(self, name: str, *, description: str = "") -> dict[str, Any]:
        name = name.strip()
        if not name or len(name) > 200:
            raise ChaoxingAPIError("live theme name must contain 1..200 characters")
        session, referer, context = self._live_context()
        before, _total = self._live_theme_records(
            session, referer, context, search=name, max_items=5000
        )
        if any(item[0]["name"] == name for item in before):
            raise ChaoxingAPIError(f"live theme already exists: {name}")
        payload = self._live_json(
            session,
            referer,
            "/themedLive/createThemedLive",
            "live theme creation",
            method="POST",
            data={"name": name, "description": description.strip(), "fid": context["fid"]},
        )
        self._live_ack(payload, "live theme creation")
        after, _total = self._live_theme_records(
            session, referer, context, search=name, max_items=5000
        )
        matches = [item for item in after if item[0]["name"] == name]
        if len(matches) != 1:
            raise ChaoxingAPIError(
                "server acknowledged live theme creation, but fresh listing did not verify it"
            )
        detail = self._live_theme_detail_context(session, referer, context, matches[0][0])
        return {
            "theme": matches[0][0],
            "watch_url": detail["watch_url"],
            "invitation_code": detail["invitation_code"] or matches[0][0]["invitation_code"],
            "verification": "created live theme is present in a fresh HTTP listing",
        }

    def update_live_theme(
        self,
        theme: str,
        *,
        name: str | None = None,
        description: str | None = None,
    ) -> dict[str, Any]:
        session, referer, context = self._live_context()
        selected, _raw = self._find_live_theme(session, referer, context, theme)
        next_name = selected["name"] if name is None else name.strip()
        next_description = selected["description"] if description is None else description.strip()
        if not next_name or len(next_name) > 200:
            raise ChaoxingAPIError("live theme name must contain 1..200 characters")
        payload = self._live_json(
            session,
            referer,
            "/themedLive/editThemedLive",
            "live theme update",
            method="POST",
            data={
                "id": selected["theme_id"],
                "name": next_name,
                "description": next_description,
                "fid": context["fid"],
            },
        )
        self._live_ack(payload, "live theme update")
        refreshed, _total = self._live_theme_records(
            session, referer, context, search=next_name, max_items=5000
        )
        matches = [item for item in refreshed if item[0]["name"] == next_name]
        if len(matches) != 1 or matches[0][0]["description"] != next_description:
            raise ChaoxingAPIError(
                "server acknowledged live theme update, but fresh listing did not verify it"
            )
        return {
            "theme": matches[0][0],
            "verification": "updated live theme matches a fresh HTTP listing",
        }

    def update_live_theme_settings(
        self,
        theme: str,
        *,
        forwarding_enabled: bool | None = None,
        replay_enabled: bool | None = None,
        learning_app_only: bool | None = None,
        login_required: bool | None = None,
        allowed_unit_ids: list[str] | None = None,
    ) -> dict[str, Any]:
        session, referer, context = self._live_context()
        selected, raw = self._find_live_theme(session, referer, context, theme)
        config = _json_dict(raw.get("configJson"))
        changes = {
            "isForwardingIsAllowed": forwarding_enabled,
            "isRetrospectivesAreAllowed": replay_enabled,
            "isOnlyXxtAllowed": learning_app_only,
            "isOnlyLoginAllowed": login_required,
        }
        for key, value in changes.items():
            if value is not None:
                config[key] = bool(value)
        if allowed_unit_ids is not None:
            config["limitViewingFid"] = ",".join(
                str(value).strip() for value in allowed_unit_ids if str(value).strip()
            )
        payload = self._live_json(
            session,
            referer,
            "/themedLive/setThemedLiveConfig",
            "live theme settings update",
            method="POST",
            data={
                "id": selected["theme_id"],
                "configJson": json.dumps(config, ensure_ascii=False, separators=(",", ":")),
            },
        )
        self._live_ack(payload, "live theme settings update")
        refreshed, _total = self._live_theme_records(
            session, referer, context, search=selected["name"], max_items=5000
        )
        matches = [item for item in refreshed if item[0]["name"] == selected["name"]]
        if len(matches) != 1:
            raise ChaoxingAPIError(
                "server acknowledged live theme settings update, but theme disappeared"
            )
        expected = {
            "forwarding_enabled": self._live_boolean(config.get("isForwardingIsAllowed")),
            "replay_enabled": self._live_boolean(config.get("isRetrospectivesAreAllowed")),
            "learning_app_only": self._live_boolean(config.get("isOnlyXxtAllowed")),
            "login_required": self._live_boolean(config.get("isOnlyLoginAllowed")),
            "allowed_unit_ids": [
                value for value in str(config.get("limitViewingFid") or "").split(",") if value
            ],
        }
        if matches[0][0]["settings"] != expected:
            raise ChaoxingAPIError(
                "server acknowledged live theme settings update, but fresh read did not verify it"
            )
        return {
            "theme": matches[0][0],
            "verification": "live theme settings match a fresh authenticated listing",
        }

    def add_live_room_to_theme(self, theme: str, room: str) -> dict[str, Any]:
        session, referer, context = self._live_context()
        selected_theme, _theme_raw = self._find_live_theme(session, referer, context, theme)
        selected_room, room_raw = self._find_live_room(session, referer, context, room)
        detail = self._live_theme_detail_context(session, referer, context, selected_theme)
        existing, _total = self._live_theme_room_records(session, detail, context, max_items=5000)
        if any(item[0]["room_id"] == selected_room["room_id"] for item in existing):
            return {
                "theme": selected_theme,
                "room": selected_room,
                "already_present": True,
                "verification": "live room was already present in a fresh themed-live listing",
            }
        stream_room_id = selected_room["stream_room_id"]
        if not stream_room_id:
            current = self._live_room_detail(session, referer, selected_room, room_raw)
            stream_room_id = current["room"]["stream_room_id"]
        if not stream_room_id:
            raise ChaoxingAPIError("live room exposes no stream-room identifier")
        payload = self._live_json(
            session,
            detail["referer"],
            "/themedLive/createLiveByPersonal",
            "add live room to theme",
            params={
                "liveIds": stream_room_id,
                "themedLiveId": detail["internal_theme_id"],
            },
        )
        self._live_ack(payload, "add live room to theme")
        refreshed_detail = self._live_theme_detail_context(
            session, referer, context, selected_theme
        )
        refreshed, _total = self._live_theme_room_records(
            session, refreshed_detail, context, max_items=5000
        )
        matches = [item[0] for item in refreshed if item[0]["room_id"] == selected_room["room_id"]]
        if len(matches) != 1:
            raise ChaoxingAPIError(
                "server acknowledged themed-live association, but fresh read did not verify it"
            )
        return {
            "theme": selected_theme,
            "room": matches[0],
            "already_present": False,
            "verification": "live room is present in a fresh themed-live child listing",
        }

    def create_live_room_in_theme(
        self,
        theme: str,
        title: str,
        *,
        scheduled_time: str = "",
        introduction: str = "",
        content_format: str = "plain",
        mode: str = "multi_device",
        chat_content_review: bool = True,
        cover_object_id: str = "",
        preview_video_object_id: str = "",
    ) -> dict[str, Any]:
        title = title.strip()
        if not title or len(title) > 200:
            raise ChaoxingAPIError("live title must contain 1..200 characters")
        mode_key = mode.strip().lower().replace("-", "_")
        mode_aliases = {
            "multi_device": "1",
            "regular": "1",
            "web": "1",
            "phone": "1",
            "chaoxing_pc_client": "2",
            "pc_client": "2",
            "client": "2",
        }
        if mode_key not in mode_aliases:
            raise ChaoxingAPIError("live mode must be multi_device or chaoxing_pc_client")
        session, referer, context = self._live_context()
        selected_theme, _raw = self._find_live_theme(session, referer, context, theme)
        detail = self._live_theme_detail_context(session, referer, context, selected_theme)
        before, _total = self._live_theme_room_records(
            session, detail, context, search=title, max_items=5000
        )
        before_ids = {item[0]["room_id"] for item in before}
        payload = self._live_json(
            session,
            detail["referer"],
            "/courseLive/newCteateLiveOfThemedLive",
            "themed live-room creation",
            method="POST",
            data={
                "type": mode_aliases[mode_key],
                "title": title,
                "ygdate": self._live_schedule(scheduled_time),
                "jieshao": self._live_rich_text(introduction, content_format),
                "chatContentReview": str(bool(chat_content_review)).lower(),
                "ygimg": cover_object_id.strip(),
                "s": context["token"],
                "objectId": preview_video_object_id.strip(),
                "customizedValue": "chaoxing",
                "extendsInfo": "null",
                "themedLiveId": detail["internal_theme_id"],
            },
        )
        self._live_ack(payload, "themed live-room creation")
        refreshed_detail = self._live_theme_detail_context(
            session, referer, context, selected_theme
        )
        after, _total = self._live_theme_room_records(
            session, refreshed_detail, context, search=title, max_items=5000
        )
        active_id = str(payload.get("activeId") or "") if isinstance(payload, dict) else ""
        matches = [
            item[0]
            for item in after
            if item[0]["room_id"] not in before_ids
            and item[0]["title"] == title
            and (not active_id or item[0]["active_id"] == active_id)
        ]
        if len(matches) != 1:
            raise ChaoxingAPIError(
                "server acknowledged themed live-room creation, but fresh read did not verify it"
            )
        return {
            "theme": selected_theme,
            "room": matches[0],
            "verification": "created room is present in the themed-live child listing",
        }

    def delete_live_theme(self, theme: str) -> dict[str, Any]:
        session, referer, context = self._live_context()
        selected, _raw = self._find_live_theme(session, referer, context, theme)
        detail = self._live_theme_detail_context(session, referer, context, selected)
        rooms, _total = self._live_theme_room_records(session, detail, context, max_items=5000)
        payload = self._live_json(
            session,
            referer,
            "/themedLive/deleteThemedLive",
            "live theme deletion",
            method="POST",
            data={"id": selected["theme_id"]},
        )
        self._live_verified_mutation_ack(payload, "live theme deletion")
        remaining, _total = self._live_theme_records(
            session, referer, context, search=selected["name"], max_items=5000
        )
        if any(item[0]["name"] == selected["name"] for item in remaining):
            raise ChaoxingAPIError(
                "server acknowledged live theme deletion, but it remains visible"
            )
        return {
            "deleted_theme": selected,
            "child_room_count": len(rooms),
            "child_rooms_deleted": False,
            "verification": "live theme is absent from a fresh listing; child rooms are retained",
        }

    def _contacts_json_request(
        self,
        session: requests.Session,
        path: str,
        operation: str,
        *,
        method: str = "GET",
        params: dict[str, Any] | None = None,
        data: dict[str, Any] | None = None,
        referer: str = "",
    ) -> dict[str, Any]:
        headers = {
            "Referer": referer,
            "X-Requested-With": "XMLHttpRequest",
        }
        try:
            response = session.request(
                method.upper(),
                CONTACTS_BASE_URL + path,
                params=params,
                data=data,
                headers=headers,
                timeout=max(self.timeout, 60),
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"{operation} failed: {exc}") from exc
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError(f"{operation} returned invalid JSON") from exc
        if not isinstance(payload, dict):
            raise ChaoxingAPIError(f"{operation} returned invalid JSON")
        if payload.get("result") not in {1, "1"}:
            raise ChaoxingAPIError(str(payload.get("msg") or f"{operation} was rejected"))
        return payload

    @staticmethod
    def _normalize_contact_user(raw: dict[str, Any], index: int) -> dict[str, Any]:
        return {
            "index": index,
            "puid": str(raw.get("puid") or ""),
            "user_id": str(raw.get("uid") or ""),
            "name": str(raw.get("name") or "").strip(),
            "picture_url": str(raw.get("pic") or ""),
            "encoded_puid": str(raw.get("puidEnc") or ""),
            "is_followed_by_me": bool(raw.get("isFollowedByMe")),
            "is_my_follower": bool(raw.get("isMyFollower")),
            "is_cared_by_me": bool(raw.get("isCaredByMe")),
        }

    @staticmethod
    def _resolve_contact_item(
        items: list[dict[str, Any]],
        query: str,
        *,
        label: str,
        id_keys: tuple[str, ...],
        name_key: str = "name",
    ) -> dict[str, Any]:
        normalized = query.strip().lower()
        if not normalized:
            raise ChaoxingAPIError(f"{label} name, ID, or index is required")
        exact: list[dict[str, Any]] = []
        for item in items:
            candidates = [str(item.get(key) or "").strip().lower() for key in id_keys]
            candidates.extend(
                (
                    str(item.get(name_key) or "").strip().lower(),
                    str(item.get("index") or "").strip().lower(),
                )
            )
            if normalized in candidates:
                exact.append(item)
        if len(exact) == 1:
            return exact[0]
        if len(exact) > 1:
            choices = ", ".join(
                f"{item.get(name_key) or '(unnamed)'} ({item.get(id_keys[0]) or '?'})"
                for item in exact[:8]
            )
            raise ChaoxingAPIError(f"multiple {label} records match: {choices}")
        partial = [
            item for item in items if normalized in str(item.get(name_key) or "").strip().lower()
        ]
        if len(partial) == 1:
            return partial[0]
        if not partial:
            raise ChaoxingAPIError(f"{label} not found: {query}")
        choices = ", ".join(
            f"{item.get(name_key) or '(unnamed)'} ({item.get(id_keys[0]) or '?'})"
            for item in partial[:8]
        )
        raise ChaoxingAPIError(f"multiple {label} records match: {choices}")

    def _contacts_context(self) -> tuple[requests.Session, requests.Response]:
        session, landing, _module = self._personal_space_module_context("通讯录")
        return session, landing

    def list_contact_units(self) -> dict[str, Any]:
        session, landing = self._contacts_context()
        payload = self._contacts_json_request(
            session,
            "/pc/contacts/getUnits",
            "contact unit list",
            params={"pageSize": 300},
            referer=landing.url,
        )
        raw_units = payload.get("msg") if isinstance(payload.get("msg"), list) else []
        units = [
            {
                "index": index,
                "fid": str(raw.get("fid") or ""),
                "name": str(raw.get("name") or "").strip(),
                "address_book_data_type": raw.get("addressbookDataType"),
            }
            for index, raw in enumerate(raw_units, 1)
            if isinstance(raw, dict)
        ]
        return {
            "count": len(units),
            "units": units,
            "verification": f"read {len(units)} visible contact units through HTTP",
        }

    def list_contact_departments(
        self,
        fid: str,
        *,
        parent_id: str = "2C89C38F937992D2",
        department_type: str = "unit",
    ) -> dict[str, Any]:
        fid = fid.strip()
        parent_id = parent_id.strip()
        if not fid or not parent_id:
            raise ChaoxingAPIError("contact unit fid and parent department ID are required")
        if department_type not in {"unit", "custom"}:
            raise ChaoxingAPIError("contact department type must be unit or custom")
        session, landing = self._contacts_context()
        payload = self._contacts_json_request(
            session,
            "/pc/contacts/getDepts",
            "contact department list",
            params={
                "pageSize": 300,
                "fid": fid,
                "pid": parent_id,
                "type": department_type,
            },
            referer=landing.url,
        )
        message = payload.get("msg") if isinstance(payload.get("msg"), dict) else {}
        raw_departments = message.get("list") if isinstance(message.get("list"), list) else []
        departments = [
            {
                "index": index,
                "department_id": str(raw.get("id") or ""),
                "parent_id": str(raw.get("pid") or ""),
                "fid": str(raw.get("fid") or fid),
                "name": str(raw.get("name") or "").strip(),
                "member_count": int(raw.get("usercount") or 0),
                "hide_members": bool(raw.get("hideUser")),
                "creator_uid": str(raw.get("creatorUid") or ""),
                "is_creator": bool(raw.get("isCreator")),
            }
            for index, raw in enumerate(raw_departments, 1)
            if isinstance(raw, dict)
        ]
        return {
            "fid": fid,
            "parent_id": parent_id,
            "department_type": department_type,
            "count": len(departments),
            "departments": departments,
            "verification": f"read {len(departments)} contact departments through HTTP",
        }

    def _list_contact_people_endpoint(
        self,
        session: requests.Session,
        landing: requests.Response,
        path: str,
        operation: str,
        base_params: dict[str, Any],
        *,
        max_items: int,
        page_size: int = 300,
    ) -> list[dict[str, Any]]:
        if max_items < 1:
            raise ChaoxingAPIError("max_items must be at least 1")
        people: list[dict[str, Any]] = []
        seen: set[str] = set()
        page = 1
        offset_value: Any = ""
        offset_aux_value: Any = ""
        while page <= 200 and len(people) < max_items:
            params = dict(base_params)
            params.update({"page": page, "pageSize": min(page_size, 300)})
            if page > 1:
                params["offsetValue"] = offset_value
                params["offsetAuxValue"] = offset_aux_value
            payload = self._contacts_json_request(
                session,
                path,
                operation,
                params=params,
                referer=landing.url,
            )
            message = payload.get("msg") if isinstance(payload.get("msg"), dict) else {}
            raw_people = message.get("list") if isinstance(message.get("list"), list) else []
            added = 0
            for raw in raw_people:
                if not isinstance(raw, dict):
                    continue
                person = self._normalize_contact_user(raw, len(people) + 1)
                identity = person["puid"] or person["user_id"]
                if not identity or identity in seen:
                    continue
                seen.add(identity)
                people.append(person)
                added += 1
                if len(people) >= max_items:
                    break
            if bool(message.get("lastPage")) or not raw_people or added == 0:
                break
            next_offset = message.get("lastValue", "")
            next_aux = message.get("lastAuxValue", "")
            if page > 1 and (next_offset, next_aux) == (offset_value, offset_aux_value):
                break
            offset_value, offset_aux_value = next_offset, next_aux
            page += 1
        return people

    def search_contact_people(
        self,
        search: str,
        *,
        fid: str = "",
        department_id: str = "",
        mode: int = -1,
        max_items: int = 300,
    ) -> dict[str, Any]:
        search = search.strip()
        if not search:
            raise ChaoxingAPIError("contact search text is required")
        session, landing = self._contacts_context()
        params: dict[str, Any] = {
            "fid": fid.strip(),
            "kw": search,
            "offsetValue": 1,
            "mode": "" if fid.strip() and mode > -1 else mode,
        }
        if department_id.strip():
            params["deptId"] = department_id.strip()
        people = self._list_contact_people_endpoint(
            session,
            landing,
            "/pc/contacts/getDeptUsers",
            "contact person search",
            params,
            max_items=max_items,
        )
        return {
            "search": search,
            "fid": fid.strip(),
            "department_id": department_id.strip(),
            "mode": mode,
            "count": len(people),
            "people": people,
            "verification": f"contact search returned {len(people)} visible people through HTTP",
        }

    def list_contact_department_members(
        self,
        fid: str,
        department_id: str,
        *,
        search: str = "",
        max_items: int = 1000,
    ) -> dict[str, Any]:
        fid = fid.strip()
        department_id = department_id.strip()
        if not fid or not department_id:
            raise ChaoxingAPIError("contact unit fid and department ID are required")
        session, landing = self._contacts_context()
        params: dict[str, Any] = {"fid": fid, "deptId": department_id}
        if search.strip():
            params.update({"kw": search.strip(), "offsetValue": 1})
        people = self._list_contact_people_endpoint(
            session,
            landing,
            "/pc/contacts/getDeptUsers",
            "contact department member list",
            params,
            max_items=max_items,
        )
        return {
            "fid": fid,
            "department_id": department_id,
            "search": search.strip(),
            "count": len(people),
            "people": people,
            "verification": f"read {len(people)} visible department members through HTTP",
        }

    def list_contact_relations(
        self,
        relation: str = "followers",
        *,
        max_items: int = 1000,
    ) -> dict[str, Any]:
        normalized = relation.strip().lower()
        relation_values = {
            "followers": 0,
            "follower": 0,
            "关注我的": 0,
            "following": 1,
            "followed": 1,
            "我关注的": 1,
        }
        if normalized not in relation_values:
            raise ChaoxingAPIError("contact relation must be followers or following")
        relation_name = "following" if relation_values[normalized] == 1 else "followers"
        session, landing = self._contacts_context()
        people = self._list_contact_people_endpoint(
            session,
            landing,
            "/pc/contacts/getFollowers",
            "contact relation list",
            {"isfollower": relation_values[normalized]},
            max_items=max_items,
            page_size=100,
        )
        return {
            "relation": relation_name,
            "count": len(people),
            "people": people,
            "verification": f"read {len(people)} {relation_name} contact records through HTTP",
        }

