    def list_contact_chatgroups(self, *, max_items: int = 1000) -> dict[str, Any]:
        session, landing = self._contacts_context()
        chatgroups: list[dict[str, Any]] = []
        seen: set[str] = set()
        page = 1
        offset_value: Any = ""
        offset_aux_value: Any = ""
        while page <= 200 and len(chatgroups) < max_items:
            params: dict[str, Any] = {"page": page, "pageSize": 20}
            if page > 1:
                params.update({"offsetValue": offset_value, "offsetAuxValue": offset_aux_value})
            payload = self._contacts_json_request(
                session,
                "/pc/contacts/getJoinedChatgroups",
                "contact chat-group list",
                params=params,
                referer=landing.url,
            )
            message = payload.get("msg") if isinstance(payload.get("msg"), dict) else {}
            raw_groups = message.get("list") if isinstance(message.get("list"), list) else []
            added = 0
            for raw in raw_groups:
                if not isinstance(raw, dict):
                    continue
                group_id = str(raw.get("groupid") or "")
                if not group_id or group_id in seen:
                    continue
                seen.add(group_id)
                chatgroups.append(
                    {
                        "index": len(chatgroups) + 1,
                        "chatgroup_id": group_id,
                        "name": str(raw.get("groupname") or "").strip(),
                        "picture_url": str(raw.get("pic") or ""),
                        "disabled": str(raw.get("disabled") or "").lower() == "true",
                    }
                )
                added += 1
                if len(chatgroups) >= max_items:
                    break
            if bool(message.get("lastPage")) or not raw_groups or added == 0:
                break
            next_offset = message.get("lastValue", "")
            next_aux = message.get("lastAuxValue", "")
            if page > 1 and (next_offset, next_aux) == (offset_value, offset_aux_value):
                break
            offset_value, offset_aux_value = next_offset, next_aux
            page += 1
        return {
            "count": len(chatgroups),
            "chatgroups": chatgroups,
            "verification": f"read {len(chatgroups)} joined chat groups through HTTP",
        }

