    def _resolve_known_contact_person(self, query: str) -> dict[str, Any]:
        normalized = query.strip()
        if normalized.isdigit():
            return {"puid": normalized, "name": "", "index": 0}
        people: list[dict[str, Any]] = []
        seen: set[str] = set()
        for relation in ("followers", "following"):
            for person in self.list_contact_relations(relation, max_items=10000)["people"]:
                if person["puid"] not in seen:
                    seen.add(person["puid"])
                    people.append(person)
        return self._resolve_contact_item(
            people,
            query,
            label="known contact person",
            id_keys=("puid", "user_id"),
        )

    def set_contact_follow_status(self, person: str, followed: bool) -> dict[str, Any]:
        selected = self._resolve_known_contact_person(person)
        session, landing = self._contacts_context()
        path = "/pc/user/addUserFollow" if followed else "/pc/user/delUserFollow"
        payload = self._contacts_json_request(
            session,
            path,
            "contact follow-status update",
            params={"followedPuid": selected["puid"]},
            referer=landing.url,
        )
        refreshed = self.list_contact_relations("following", max_items=10000)["people"]
        is_followed = any(item["puid"] == selected["puid"] for item in refreshed)
        if is_followed is not followed:
            raise ChaoxingAPIError("contact follow status did not match after refresh")
        return {
            "person": selected,
            "followed": followed,
            "server_message": payload.get("msg"),
            "verification": f"contact follow status is {followed} after refresh",
        }

    def _resolve_contact_people(self, queries: list[str]) -> list[dict[str, Any]]:
        if not queries:
            raise ChaoxingAPIError("at least one contact person is required")
        resolved: list[dict[str, Any]] = []
        seen: set[str] = set()
        for query in queries:
            person = self._resolve_known_contact_person(query)
            if person["puid"] not in seen:
                seen.add(person["puid"])
                resolved.append(person)
        return resolved

    def create_contact_team(self, name: str, members: list[str]) -> dict[str, Any]:
        name = name.strip()
        if not name:
            raise ChaoxingAPIError("contact team name cannot be empty")
        people = self._resolve_contact_people(members)
        session, landing = self._contacts_context()
        payload = self._contacts_json_request(
            session,
            "/pc/contacts/createCustomDept",
            "custom contact team creation",
            method="POST",
            data={"name": name, "puids": ",".join(p["puid"] for p in people) + ","},
            referer=landing.url,
        )
        message = payload.get("msg") if isinstance(payload.get("msg"), dict) else {}
        team_id = str(message.get("id") or "")
        created = self._find_contact_team(team_id or name)
        if created["name"] != name:
            raise ChaoxingAPIError("created contact team name differs after refresh")
        return {
            "team": created,
            "members": people,
            "verification": f"created contact team {created['team_id']} appears after refresh",
        }

    def rename_contact_team(self, team: str, name: str) -> dict[str, Any]:
        name = name.strip()
        if not name:
            raise ChaoxingAPIError("contact team name cannot be empty")
        selected = self._find_contact_team(team)
        if not selected["is_creator"]:
            raise ChaoxingAPIError("only a contact team creator can rename the team")
        session, landing = self._contacts_context()
        self._contacts_json_request(
            session,
            "/pc/contacts/updateDept",
            "custom contact team rename",
            method="POST",
            data={"name": name, "deptId": selected["team_id"]},
            referer=landing.url,
        )
        refreshed = self._find_contact_team(selected["team_id"])
        if refreshed["name"] != name:
            raise ChaoxingAPIError("contact team name did not match after refresh")
        return {
            "team": refreshed,
            "verification": f"contact team name is {name} after refresh",
        }

    def add_contact_team_members(self, team: str, members: list[str]) -> dict[str, Any]:
        selected = self._find_contact_team(team)
        if not selected["is_creator"]:
            raise ChaoxingAPIError("only a contact team creator can add members")
        people = self._resolve_contact_people(members)
        session, landing = self._contacts_context()
        self._contacts_json_request(
            session,
            "/pc/contacts/addOrDeleteUserDept",
            "custom contact team member addition",
            method="POST",
            data={
                "deptId": selected["team_id"],
                "addPuids": ",".join(person["puid"] for person in people) + ",",
                "deletePuid": "",
            },
            referer=landing.url,
        )
        refreshed = self.list_contact_team_members(selected["team_id"], max_items=10000)
        refreshed_ids = {person["puid"] for person in refreshed["people"]}
        missing = [person["puid"] for person in people if person["puid"] not in refreshed_ids]
        if missing:
            raise ChaoxingAPIError(f"added contact team members missing after refresh: {missing}")
        return {
            "team": refreshed["team"],
            "added": people,
            "verification": "all requested contact team members appear after refresh",
        }

    def remove_contact_team_member(self, team: str, member: str) -> dict[str, Any]:
        selected = self._find_contact_team(team)
        if not selected["is_creator"]:
            raise ChaoxingAPIError("only a contact team creator can remove members")
        current = self.list_contact_team_members(selected["team_id"], max_items=10000)
        person = self._resolve_contact_item(
            current["people"],
            member,
            label="contact team member",
            id_keys=("puid", "user_id"),
        )
        session, landing = self._contacts_context()
        self._contacts_json_request(
            session,
            "/pc/contacts/addOrDeleteUserDept",
            "custom contact team member removal",
            method="POST",
            data={
                "deptId": selected["team_id"],
                "addPuids": "",
                "deletePuid": person["puid"],
            },
            referer=landing.url,
        )
        refreshed = self.list_contact_team_members(selected["team_id"], max_items=10000)
        if any(item["puid"] == person["puid"] for item in refreshed["people"]):
            raise ChaoxingAPIError("removed contact team member still appears after refresh")
        return {
            "team": refreshed["team"],
            "removed": person,
            "verification": "removed contact team member is absent after refresh",
        }

    def delete_contact_team(self, team: str) -> dict[str, Any]:
        selected = self._find_contact_team(team)
        if not selected["is_creator"]:
            raise ChaoxingAPIError("only a contact team creator can delete the team")
        session, landing = self._contacts_context()
        self._contacts_json_request(
            session,
            "/pc/contacts/deleteDept",
            "custom contact team deletion",
            method="POST",
            data={"deptId": selected["team_id"]},
            referer=landing.url,
        )
        remaining = self.list_contact_teams()["teams"]
        if any(item["team_id"] == selected["team_id"] for item in remaining):
            raise ChaoxingAPIError("deleted contact team still appears after refresh")
        return {
            "deleted": selected,
            "verification": "deleted contact team is absent after refresh",
        }

    def exit_contact_team(self, team: str) -> dict[str, Any]:
        selected = self._find_contact_team(team)
        if selected["is_creator"]:
            raise ChaoxingAPIError("a contact team creator must delete rather than exit the team")
        session, landing = self._contacts_context()
        self._contacts_json_request(
            session,
            "/pc/contacts/exitDept",
            "custom contact team exit",
            method="POST",
            data={"deptId": selected["team_id"]},
            referer=landing.url,
        )
        remaining = self.list_contact_teams()["teams"]
        if any(item["team_id"] == selected["team_id"] for item in remaining):
            raise ChaoxingAPIError("exited contact team still appears after refresh")
        return {
            "exited": selected,
            "verification": "exited contact team is absent after refresh",
        }

    def _personal_groups_context(self) -> tuple[requests.Session, requests.Response]:
        session, landing, _module = self._personal_space_module_context("小组")
        return session, landing

    def _personal_group_json_request(
        self,
        session: requests.Session,
        path: str,
        operation: str,
        *,
        method: str = "GET",
        params: dict[str, Any] | None = None,
        data: dict[str, Any] | None = None,
        referer: str = "",
        allow_result: bool = False,
        allow_null: bool = False,
    ) -> dict[str, Any]:
        url = path if path.startswith("http") else GROUPWEB_BASE_URL + path
        headers = {"Referer": referer} if referer else {}
        try:
            if method.upper() == "POST":
                response = session.post(
                    url,
                    params=params,
                    data=data,
                    headers=headers,
                    timeout=max(self.timeout, 60),
                )
            else:
                response = session.get(
                    url,
                    params=params,
                    data=data,
                    headers=headers,
                    timeout=max(self.timeout, 60),
                )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"{operation} failed: {exc}") from exc
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError(f"{operation} returned invalid JSON") from exc
        if payload is None and allow_null:
            return {}
        if not isinstance(payload, dict):
            raise ChaoxingAPIError(f"{operation} returned invalid JSON")
        succeeded = payload.get("status") in {True, "1"}
        if allow_result:
            succeeded = succeeded or payload.get("result") in {True, "1"}
        if not succeeded:
            raise ChaoxingAPIError(
                str(payload.get("msg") or payload.get("errorMsg") or f"{operation} was rejected")
            )
        return payload

    @staticmethod
    def _normalize_personal_group(raw: dict[str, Any], index: int = 0) -> dict[str, Any]:
        def integer(value: Any) -> int:
            try:
                return int(value or 0)
            except (TypeError, ValueError):
                return 0

        permissions = raw.get("groupAuth") if isinstance(raw.get("groupAuth"), dict) else {}
        bbs_id = str(raw.get("bbsid") or "")
        return {
            "index": index,
            "group_id": str(raw.get("id") or ""),
            "bbs_id": bbs_id,
            "name": str(raw.get("name") or "").strip(),
            "description": str(raw.get("introduce") or raw.get("intro") or "").strip(),
            "folder_id": str(raw.get("folderId") or "0"),
            "logo_url": str(raw.get("logo") or ""),
            "member_count": integer(raw.get("mem_count") or raw.get("memCount")),
            "topic_count": integer(raw.get("topic_Count") or raw.get("topicCount")),
            "new_topic_count": integer(raw.get("newTopicCount")),
            "is_top": integer(raw.get("top")) == 1,
            "sort": integer(raw.get("sort")),
            "is_creator": integer(raw.get("isCreater")) == 1,
            "is_manager": integer(raw.get("isManager")) == 1,
            "creator_puid": str(raw.get("createrPuid") or ""),
            "creator_name": str(raw.get("createRealName") or ""),
            "created_at": raw.get("createTime"),
            "updated_at": raw.get("lastUpdateTime"),
            "join_status": integer(raw.get("status_join")),
            "invite_code": str(raw.get("inviteCode") or ""),
            "bulk_import_enabled": integer(raw.get("isBulkImport")) == 1,
            "bulk_import_used_today": integer(raw.get("bulkImportnumber")),
            "bulk_import_started_at": raw.get("bulkImportTime"),
            "bulk_import_effective_days": integer(raw.get("effective")),
            "permissions": permissions,
            "can_quit": str(permissions.get("quit") or "0") == "1",
            "can_update": str(permissions.get("modifyName") or "0") == "1",
            "can_add_members": str(permissions.get("addMem") or "0") == "1",
            "can_remove_members": str(permissions.get("delMem") or "0") == "1",
            "can_manage": integer(raw.get("isManager")) == 1 or integer(raw.get("isCreater")) == 1,
            "topics_url": GROUPWEB_BASE_URL
            + "/pc/topic/topiclist/index?"
            + urlencode({"bbsid": bbs_id}),
            "management_url": GROUPWEB_BASE_URL
            + "/pc/circle/manage/index?"
            + urlencode({"bbsid": bbs_id}),
        }

    @classmethod
    def _normalize_personal_group_folder(
        cls,
        raw: dict[str, Any],
        index: int = 0,
    ) -> dict[str, Any]:
        def integer(value: Any) -> int:
            try:
                return int(value or 0)
            except (TypeError, ValueError):
                return 0

        raw_children = raw.get("list")
        children = [
            cls._normalize_personal_group_folder(child, child_index)
            for child_index, child in enumerate(
                raw_children if isinstance(raw_children, list) else [], 1
            )
            if isinstance(child, dict)
        ]
        return {
            "index": index,
            "folder_id": str(raw.get("id") or ""),
            "parent_id": str(raw.get("pid") if raw.get("pid") is not None else "0"),
            "name": str(raw.get("name") or "").strip(),
            "is_top": integer(raw.get("top")) == 1,
            "sort": integer(raw.get("sort")),
            "children": children,
        }

    @classmethod
    def _flatten_personal_group_folders(
        cls,
        folders: list[dict[str, Any]],
    ) -> list[dict[str, Any]]:
        flattened: list[dict[str, Any]] = []
        for folder in folders:
            flattened.append(folder)
            children = folder.get("children")
            if isinstance(children, list):
                flattened.extend(cls._flatten_personal_group_folders(children))
        for index, folder in enumerate(flattened, 1):
            folder["flat_index"] = index
        return flattened

    @staticmethod
    def _resolve_personal_group_folder(
        folders: list[dict[str, Any]],
        query: str,
    ) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("personal group folder name, ID, or index is required")
        for key in ("folder_id", "flat_index", "name"):
            exact = [
                folder
                for folder in folders
                if str(folder.get(key) or "").strip().lower() == normalized
            ]
            if len(exact) == 1:
                return exact[0]
            if len(exact) > 1:
                raise ChaoxingAPIError(f"multiple personal group folders match: {query}")
        partial = [folder for folder in folders if normalized in folder["name"].lower()]
        if len(partial) == 1:
            return partial[0]
        if not partial:
            raise ChaoxingAPIError(f"personal group folder not found: {query}")
        raise ChaoxingAPIError(f"multiple personal group folders match: {query}")

    @staticmethod
    def _resolve_personal_group(
        groups: list[dict[str, Any]],
        query: str,
    ) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("personal group name, BBS ID, group ID, or index is required")
        for key in ("bbs_id", "group_id", "index", "name"):
            exact = [
                group for group in groups if str(group.get(key) or "").strip().lower() == normalized
            ]
            if len(exact) == 1:
                return exact[0]
            if len(exact) > 1:
                raise ChaoxingAPIError(f"multiple personal groups match: {query}")
        partial = [group for group in groups if normalized in group["name"].lower()]
        if len(partial) == 1:
            return partial[0]
        if not partial:
            raise ChaoxingAPIError(f"personal group not found: {query}")
        raise ChaoxingAPIError(f"multiple personal groups match: {query}")

    def list_personal_group_folder_tree(self) -> dict[str, Any]:
        session, landing = self._personal_groups_context()
        payload = self._personal_group_json_request(
            session,
            "/pc/circle_folder/getCircleFolderTree",
            "personal group folder tree",
            referer=landing.url,
        )
        raw_folders = payload.get("data")
        tree = [
            self._normalize_personal_group_folder(raw, index)
            for index, raw in enumerate(raw_folders if isinstance(raw_folders, list) else [], 1)
            if isinstance(raw, dict)
        ]
        flattened = self._flatten_personal_group_folders(tree)
        return {
            "count": len(flattened),
            "tree": tree,
            "folders": flattened,
            "verification": f"read {len(flattened)} personal group folders through HTTP",
        }

    def _personal_group_folder_id(self, folder: str) -> str:
        normalized = str(folder or "").strip()
        if normalized.lower() in {"", "0", "root"} or normalized in {"根目录", "我的小组"}:
            return "0"
        return self._resolve_personal_group_folder(
            self.list_personal_group_folder_tree()["folders"], normalized
        )["folder_id"]

    def list_personal_group_folders(
        self,
        *,
        parent_folder: str = "",
        search: str = "",
    ) -> dict[str, Any]:
        session, landing = self._personal_groups_context()
        if search.strip():
            path = "/pc/circle_folder/getCircleFolderSearchList"
            data = {"kw": quote(search.strip(), safe="")}
            parent_id = ""
        else:
            path = "/pc/circle_folder/getCircleFolderList"
            parent_id = self._personal_group_folder_id(parent_folder)
            data = {"folderId": parent_id}
        payload = self._personal_group_json_request(
            session,
            path,
            "personal group folder list",
            method="POST",
            data=data,
            referer=landing.url,
        )
        raw_folders = payload.get("data")
        folders = [
            self._normalize_personal_group_folder(raw, index)
            for index, raw in enumerate(raw_folders if isinstance(raw_folders, list) else [], 1)
            if isinstance(raw, dict)
        ]
        return {
            "parent_folder_id": parent_id,
            "search": search.strip(),
            "count": len(folders),
            "folders": folders,
            "verification": f"read {len(folders)} personal group folders through HTTP",
        }

    def list_personal_groups(
        self,
        *,
        folder: str = "",
        search: str = "",
    ) -> dict[str, Any]:
        session, landing = self._personal_groups_context()
        if search.strip():
            path = "/pc/circle/getCircleSearchList"
            data = {"kw": quote(search.strip(), safe="")}
            folder_id = ""
        else:
            path = "/pc/circle/getCircleList"
            folder_id = self._personal_group_folder_id(folder)
            data = {"folderId": folder_id}
        payload = self._personal_group_json_request(
            session,
            path,
            "personal group list",
            method="POST",
            data=data,
            referer=landing.url,
        )
        raw_groups = payload.get("data")
        groups = [
            self._normalize_personal_group(raw, index)
            for index, raw in enumerate(raw_groups if isinstance(raw_groups, list) else [], 1)
            if isinstance(raw, dict)
        ]
        return {
            "folder_id": folder_id,
            "search": search.strip(),
            "count": len(groups),
            "groups": groups,
            "verification": f"read {len(groups)} personal groups through HTTP",
        }

    def _all_personal_groups(self) -> list[dict[str, Any]]:
        folders = self.list_personal_group_folder_tree()["folders"]
        groups: list[dict[str, Any]] = []
        seen: set[str] = set()
        for folder_id in ["0"] + [folder["folder_id"] for folder in folders]:
            listing = self.list_personal_groups(folder=folder_id)["groups"]
            for group in listing:
                if group["bbs_id"] and group["bbs_id"] not in seen:
                    seen.add(group["bbs_id"])
                    group["index"] = len(groups) + 1
                    groups.append(group)
        return groups

    def _find_personal_group(self, group: str) -> dict[str, Any]:
        return self._resolve_personal_group(self._all_personal_groups(), group)

    def read_personal_group(self, group: str) -> dict[str, Any]:
        selected = self._find_personal_group(group)
        session, landing = self._personal_groups_context()
        try:
            response = session.get(
                selected["management_url"],
                headers={"Referer": landing.url},
                timeout=max(self.timeout, 60),
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"personal group detail failed: {exc}") from exc
        context = parse_personal_group_manage_context(self._decode(response))
        detailed = self._normalize_personal_group(context["group"], selected["index"])
        if detailed["bbs_id"] != selected["bbs_id"]:
            raise ChaoxingAPIError("personal group detail returned a different group")
        return {
            "group": detailed,
            "account": {
                "puid": str(context["account"].get("puid") or ""),
                "name": str(context["account"].get("name") or ""),
                "fid": str(context["account"].get("fid") or ""),
            },
            "settings": {
                key: value
                for key, value in context["group"].items()
                if key
                in set(PERSONAL_GROUP_BOOLEAN_SETTINGS)
                | set(PERSONAL_GROUP_SPEAKING_RULE_FIELDS)
                | {
                    "ispublic",
                    "showPic",
                    "memberVisible",
                    "anonymousAddTopic",
                    "anonymousAddReply",
                    "showGroupChat",
                    "showActivity",
                    "showCircleActivity",
                    "isShowCircleChat",
                    "autoClearStatus",
                    "sign_ban_startTime",
                    "topicNeedAttachment",
                    "levelTitleSeries",
                    "scoreRuleSeries",
                    "statisticByDate",
                    "replyListOrderType",
                }
            },
            "verification": f"read full personal group {selected['bbs_id']} through HTTP",
        }

    @staticmethod
    def _validate_personal_group_folder_name(name: str) -> str:
        normalized = name.strip()
        if not normalized:
            raise ChaoxingAPIError("personal group folder name is required")
        if len(normalized) > 16:
            raise ChaoxingAPIError("personal group folder name cannot exceed 16 characters")
        return normalized

    def create_personal_group_folder(self, name: str, *, parent_folder: str = "") -> dict[str, Any]:
        name = self._validate_personal_group_folder_name(name)
        parent_id = self._personal_group_folder_id(parent_folder)
        before_ids = {
            folder["folder_id"] for folder in self.list_personal_group_folder_tree()["folders"]
        }
        session, landing = self._personal_groups_context()
        self._personal_group_json_request(
            session,
            "/pc/circle_folder/addCircleFolder",
            "personal group folder creation",
            params={"pid": parent_id, "name": quote(name, safe="")},
            referer=landing.url,
        )
        after = self.list_personal_group_folder_tree()["folders"]
        created = [
            folder
            for folder in after
            if folder["folder_id"] not in before_ids
            and folder["parent_id"] == parent_id
            and folder["name"] == name
        ]
        if len(created) != 1:
            raise ChaoxingAPIError("could not identify exactly one created personal group folder")
        return {
            "folder": created[0],
            "verification": "identified one new personal group folder in a fresh tree read",
        }

    def rename_personal_group_folder(self, folder: str, name: str) -> dict[str, Any]:
        name = self._validate_personal_group_folder_name(name)
        before = self._resolve_personal_group_folder(
            self.list_personal_group_folder_tree()["folders"], folder
        )
        session, landing = self._personal_groups_context()
        self._personal_group_json_request(
            session,
            "/pc/circle_folder/updateCircleFolderName",
            "personal group folder rename",
            params={"folderId": before["folder_id"], "name": quote(name, safe="")},
            referer=landing.url,
        )
        after = self._resolve_personal_group_folder(
            self.list_personal_group_folder_tree()["folders"], before["folder_id"]
        )
        if after["name"] != name:
            raise ChaoxingAPIError("personal group folder name differs after refresh")
        return {
            "before": before,
            "folder": after,
            "verification": "personal group folder name matched a fresh tree read",
        }

    def move_personal_group_folder(self, folder: str, destination: str) -> dict[str, Any]:
        folders = self.list_personal_group_folder_tree()["folders"]
        selected = self._resolve_personal_group_folder(folders, folder)
        destination_id = self._personal_group_folder_id(destination)
        if selected["folder_id"] == destination_id:
            raise ChaoxingAPIError("a personal group folder cannot be moved into itself")
        session, landing = self._personal_groups_context()
        self._personal_group_json_request(
            session,
            "/pc/circle_folder/moveToFolder",
            "personal group folder move",
            params={"folderId": selected["folder_id"], "toFolderId": destination_id},
            referer=landing.url,
        )
        after = self._resolve_personal_group_folder(
            self.list_personal_group_folder_tree()["folders"], selected["folder_id"]
        )
        if after["parent_id"] != destination_id:
            raise ChaoxingAPIError("personal group folder parent differs after refresh")
        return {
            "before": selected,
            "folder": after,
            "verification": "personal group folder parent matched a fresh tree read",
        }

    def set_personal_group_folder_top_status(
        self,
        folder: str,
        top: bool,
    ) -> dict[str, Any]:
        selected = self._resolve_personal_group_folder(
            self.list_personal_group_folder_tree()["folders"], folder
        )
        session, landing = self._personal_groups_context()
        self._personal_group_json_request(
            session,
            "/pc/circle_folder/setOrCancelTop",
            "personal group folder top status",
            params={"operate": "setTop" if top else "cancelTop", "folderId": selected["folder_id"]},
            referer=landing.url,
        )
        after = self._resolve_personal_group_folder(
            self.list_personal_group_folder_tree()["folders"], selected["folder_id"]
        )
        if after["is_top"] is not bool(top):
            raise ChaoxingAPIError("personal group folder top status differs after refresh")
        return {
            "before": selected,
            "folder": after,
            "verification": f"personal group folder top status is {bool(top)} after refresh",
        }

    def delete_personal_group_folder(self, folder: str) -> dict[str, Any]:
        selected = self._resolve_personal_group_folder(
            self.list_personal_group_folder_tree()["folders"], folder
        )
        session, landing = self._personal_groups_context()
        self._personal_group_json_request(
            session,
            "/pc/circle_folder/deleteCircleFolder",
            "personal group folder deletion",
            params={"folderId": selected["folder_id"]},
            referer=landing.url,
        )
        remaining = self.list_personal_group_folder_tree()["folders"]
        if any(item["folder_id"] == selected["folder_id"] for item in remaining):
            raise ChaoxingAPIError("deleted personal group folder still appears after refresh")
        return {
            "deleted": selected,
            "verification": "deleted personal group folder is absent from a fresh tree read",
        }

    def create_personal_group(
        self,
        name: str,
        *,
        description: str = "",
        folder: str = "",
        logo_url: str = "",
    ) -> dict[str, Any]:
        name = name.strip()
        description = description.strip()
        if not name:
            raise ChaoxingAPIError("personal group name is required")
        if len(name) > 25:
            raise ChaoxingAPIError("personal group name cannot exceed 25 characters")
        if len(description) > 200:
            raise ChaoxingAPIError("personal group description cannot exceed 200 characters")
        folder_id = self._personal_group_folder_id(folder)
        bbs_id = str(uuid4())
        logo = logo_url.strip() or GROUPWEB_BASE_URL + "/res/pc/images/moren.jpg"
        session, landing = self._personal_groups_context()
        self._personal_group_json_request(
            session,
            "/pc/circle/createCircle",
            "personal group creation",
            params={
                "folderId": folder_id,
                "bbsid": bbs_id,
                "name": quote(name, safe=""),
                "introduce": description,
                "logo": logo,
            },
            referer=landing.url,
        )
        created = self._resolve_personal_group(self._all_personal_groups(), bbs_id)
        if created["name"] != name:
            raise ChaoxingAPIError("created personal group name differs after refresh")
        return {
            "group": created,
            "verification": "created personal group matched a fresh all-folder read",
        }

    def update_personal_group(
        self,
        group: str,
        *,
        name: str | None = None,
        description: str | None = None,
    ) -> dict[str, Any]:
        before = self.read_personal_group(group)["group"]
        if not before["can_update"] and not before["is_creator"]:
            raise ChaoxingAPIError("current account cannot update this personal group")
        desired_name = str(name if name is not None else before["name"]).strip()
        desired_description = str(
            description if description is not None else before["description"]
        ).strip()
        if name is None and description is None:
            raise ChaoxingAPIError("at least one personal group change is required")
        if not desired_name or len(desired_name) > 25:
            raise ChaoxingAPIError("personal group name must contain 1 to 25 characters")
        if len(desired_description) > 200:
            raise ChaoxingAPIError("personal group description cannot exceed 200 characters")
        session, landing = self._personal_groups_context()
        self._personal_group_json_request(
            session,
            f"/pc/circle/manage/{quote(before['bbs_id'], safe='')}/updateCircle",
            "personal group update",
            params={
                "name": quote(desired_name, safe=""),
                "introduce": quote(desired_description, safe=""),
            },
            referer=landing.url,
        )
        after = self.read_personal_group(before["bbs_id"])["group"]
        if after["name"] != desired_name or after["description"] != desired_description:
            raise ChaoxingAPIError("personal group name or description differs after refresh")
        return {
            "before": before,
            "group": after,
            "verification": "personal group name and description matched a fresh detail read",
        }

    @staticmethod
    def _personal_group_boolean(value: Any) -> bool:
        if isinstance(value, bool):
            return value
        if isinstance(value, int) and value in {0, 1}:
            return bool(value)
        normalized = str(value or "").strip().lower()
        if normalized in {"1", "true", "yes", "on"}:
            return True
        if normalized in {"", "0", "false", "no", "off"}:
            return False
        raise ChaoxingAPIError(f"personal group setting value is not boolean: {value}")

    def update_personal_group_settings(
        self,
        group: str,
        changes: dict[str, Any],
        *,
        sign_ban_start_time: int | None = None,
    ) -> dict[str, Any]:
        if not isinstance(changes, dict) or not changes:
            raise ChaoxingAPIError("at least one personal group setting change is required")
        unknown = sorted(set(changes) - set(PERSONAL_GROUP_BOOLEAN_SETTINGS))
        if unknown:
            raise ChaoxingAPIError(f"unsupported personal group settings: {', '.join(unknown)}")
        before_detail = self.read_personal_group(group)
        selected = before_detail["group"]
        permissions = selected.get("permissions")
        if not isinstance(permissions, dict):
            permissions = {}
        for field in changes:
            permission = PERSONAL_GROUP_SETTING_PERMISSIONS[field]
            if not selected["is_creator"] and str(permissions.get(permission) or "0") != "1":
                raise ChaoxingAPIError(
                    f"current account cannot change personal group setting: {field}"
                )
        normalized_changes = {
            field: self._personal_group_boolean(value) for field, value in changes.items()
        }
        session, landing = self._personal_groups_context()
        for field, enabled in normalized_changes.items():
            if self._personal_group_boolean(before_detail["settings"].get(field)) is enabled:
                continue
            action = PERSONAL_GROUP_BOOLEAN_SETTINGS[field]
            params: dict[str, Any] = {field: "1" if enabled else "0"}
            if action == "updateCircle":
                params.update(
                    {
                        "name": quote(selected["name"], safe=""),
                        "introduce": quote(selected["description"], safe=""),
                    }
                )
            if field == "sign_ban" and enabled:
                start_time = sign_ban_start_time
                if start_time is None:
                    start_time = int(datetime.now(tz=UTC).timestamp() * 1000)
                if start_time <= 0:
                    raise ChaoxingAPIError(
                        "sign ban start time must be a positive epoch millisecond"
                    )
                params["sign_ban_startTime"] = start_time
            self._personal_group_json_request(
                session,
                f"/pc/circle/manage/{quote(selected['bbs_id'], safe='')}/{action}",
                f"personal group setting {field}",
                params=params,
                referer=selected["management_url"] or landing.url,
            )
        after_detail = self.read_personal_group(selected["bbs_id"])
        for field, expected in normalized_changes.items():
            if self._personal_group_boolean(after_detail["settings"].get(field)) is not expected:
                raise ChaoxingAPIError(f"personal group setting {field} differs after refresh")
        return {
            "before": before_detail,
            "group": after_detail["group"],
            "settings": after_detail["settings"],
            "changes": normalized_changes,
            "verification": "all requested personal group settings matched a fresh detail read",
        }

    @staticmethod
    def _normalize_personal_group_level(
        raw: dict[str, Any],
        fallback_level: int,
    ) -> dict[str, Any]:
        try:
            level = int(raw.get("priority") or raw.get("level") or fallback_level)
        except (TypeError, ValueError):
            level = fallback_level
        setting = raw.get("setting")
        if isinstance(setting, str):
            try:
                setting = json.loads(setting)
            except json.JSONDecodeError:
                setting = {}
        if not isinstance(setting, dict):
            setting = {}
        try:
            growth_value = int(
                raw.get("growthValue")
                if raw.get("growthValue") is not None
                else setting.get("scoreThreshold") or 0
            )
        except (TypeError, ValueError):
            growth_value = 0
        return {
            "level": level,
            "title": str(raw.get("title") or raw.get("titleName") or f"Lv.{level}").strip(),
            "growth_value": growth_value,
            "title_image": str(raw.get("imageUrl") or raw.get("titleImage") or "").strip(),
        }

    @staticmethod
    def _default_personal_group_levels() -> list[dict[str, Any]]:
        return [
            {
                "level": level,
                "title": f"Lv.{level}",
                "growth_value": growth_value,
                "title_image": "",
            }
            for level, growth_value in enumerate(PERSONAL_GROUP_DEFAULT_LEVEL_THRESHOLDS, 1)
        ]

    @staticmethod
    def _personal_group_badge_referer(bbs_id: str, page: str) -> str:
        return GROUPWEB_BASE_URL + f"/group-pc/badge/{page}?" + urlencode({"bbsid": bbs_id})

    def list_personal_group_levels(self, group: str) -> dict[str, Any]:
        detail = self.read_personal_group(group)
        selected = detail["group"]
        payload = self._personal_group_json_request(
            self._session(),
            "/pc/circle/getCircleTitleList",
            "personal group level title list",
            params={"bbsid": selected["bbs_id"]},
            referer=self._personal_group_badge_referer(selected["bbs_id"], "defaultSeries"),
            allow_result=True,
        )
        raw_levels = payload.get("data")
        if not isinstance(raw_levels, list):
            raw_levels = []
        levels = [
            self._normalize_personal_group_level(raw, index)
            for index, raw in enumerate(raw_levels, 1)
            if isinstance(raw, dict)
        ]
        series = str(detail["settings"].get("levelTitleSeries") or "default").lower()
        if not levels and series == "default":
            levels = self._default_personal_group_levels()
        levels.sort(key=lambda item: item["level"])
        return {
            "group": selected,
            "enabled": self._personal_group_boolean(detail["settings"].get("growthEnable")),
            "series": series,
            "count": len(levels),
            "levels": levels,
            "verification": f"read {len(levels)} personal group levels through HTTP",
        }

    @classmethod
    def _validate_personal_group_custom_levels(
        cls,
        levels: list[dict[str, Any]],
    ) -> list[dict[str, Any]]:
        if not isinstance(levels, list) or len(levels) != 15:
            raise ChaoxingAPIError("personal group custom levels must contain exactly 15 items")
        normalized: list[dict[str, Any]] = []
        for index, raw in enumerate(levels, 1):
            if not isinstance(raw, dict):
                raise ChaoxingAPIError("each personal group custom level must be an object")
            try:
                level = int(raw.get("level") or index)
            except (TypeError, ValueError) as exc:
                raise ChaoxingAPIError("personal group level must be an integer") from exc
            title = str(
                raw.get("title") or raw.get("title_name") or raw.get("titleName") or ""
            ).strip()
            if not title:
                raise ChaoxingAPIError(f"personal group level {level} title is required")
            if len(title) > 5:
                raise ChaoxingAPIError(
                    f"personal group level {level} title cannot exceed 5 characters"
                )
            growth_value = cls._personal_group_nonnegative_integer(
                raw.get("growth_value")
                if raw.get("growth_value") is not None
                else raw.get("growthValue"),
                f"level {level} growth value",
            )
            title_image = str(
                raw.get("title_image") or raw.get("titleImage") or raw.get("image_url") or ""
            ).strip()
            if title_image:
                parsed = urlparse(title_image)
                if parsed.scheme != "https" or not parsed.hostname:
                    raise ChaoxingAPIError(
                        f"personal group level {level} title image must use HTTPS"
                    )
            normalized.append(
                {
                    "level": level,
                    "title": title,
                    "growth_value": growth_value,
                    "title_image": title_image,
                }
            )
        if sorted(item["level"] for item in normalized) != list(range(1, 16)):
            raise ChaoxingAPIError("personal group custom level numbers must be 1 through 15")
        normalized.sort(key=lambda item: item["level"])
        return normalized

    def update_personal_group_custom_levels(
        self,
        group: str,
        levels: list[dict[str, Any]],
    ) -> dict[str, Any]:
        normalized = self._validate_personal_group_custom_levels(levels)
        before = self.list_personal_group_levels(group)
        selected = before["group"]
        if not self._personal_group_can(selected, "growthEnableButton"):
            raise ChaoxingAPIError("current account cannot modify personal group levels")
        server_levels = [
            {
                "level": item["level"],
                "titleName": item["title"],
                "growthValue": item["growth_value"],
                "titleImage": item["title_image"],
            }
            for item in normalized
        ]
        self._personal_group_json_request(
            self._session(),
            "/pc/circle/switchLevelTitle",
            "personal group custom level update",
            method="POST",
            data={
                "bbsid": selected["bbs_id"],
                "mode": "custom",
                "levels": json.dumps(server_levels, ensure_ascii=False, separators=(",", ":")),
            },
            referer=self._personal_group_badge_referer(selected["bbs_id"], "setLevelTitle"),
            allow_result=True,
        )
        after = self.list_personal_group_levels(selected["bbs_id"])
        expected = {item["level"]: (item["title"], item["growth_value"]) for item in normalized}
        actual = {item["level"]: (item["title"], item["growth_value"]) for item in after["levels"]}
        if after["series"] != "custom" or actual != expected:
            raise ChaoxingAPIError("personal group custom levels differ after refresh")
        return {
            "before": before,
            **after,
            "verification": "all 15 custom personal group levels matched a fresh read",
        }

    def set_personal_group_level_series(self, group: str, series: str) -> dict[str, Any]:
        normalized_series = str(series or "").strip().lower()
        if normalized_series not in {"default", "custom"}:
            raise ChaoxingAPIError("personal group level series must be default or custom")
        before = self.list_personal_group_levels(group)
        selected = before["group"]
        if not self._personal_group_can(selected, "growthEnableButton"):
            raise ChaoxingAPIError("current account cannot switch personal group level series")
        if before["series"] != normalized_series:
            self._personal_group_json_request(
                self._session(),
                "/pc/circle/switchLevelTitle",
                "personal group level series update",
                params={"bbsid": selected["bbs_id"], "mode": normalized_series},
                referer=selected["management_url"],
                allow_result=True,
            )
        after = self.list_personal_group_levels(selected["bbs_id"])
        if after["series"] != normalized_series:
            raise ChaoxingAPIError("personal group level series differs after refresh")
        return {
            "before": before,
            **after,
            "verification": "personal group level series matched a fresh detail read",
        }

    @staticmethod
    def _normalize_personal_group_growth_rule(
        raw: dict[str, Any],
    ) -> dict[str, Any]:
        def integer(value: Any) -> int:
            try:
                return int(value or 0)
            except (TypeError, ValueError):
                return 0

        return {
            "growth_type": integer(raw.get("growthType")),
            "type_name": str(raw.get("typeName") or "").strip(),
            "trigger_condition": str(raw.get("triggerCondition") or "").strip(),
            "description": str(raw.get("description") or "").strip(),
            "growth_value": integer(raw.get("growthValue")),
            "daily_limit": integer(raw.get("dailyLimit")),
            "topic_min_length": integer(raw.get("topicMinLength")),
            "reply_min_length": integer(raw.get("replyMinLength")),
        }

    def list_personal_group_growth_rules(self, group: str) -> dict[str, Any]:
        detail = self.read_personal_group(group)
        selected = detail["group"]
        payload = self._personal_group_json_request(
            self._session(),
            "/pc/circle/rules",
            "personal group growth rule list",
            params={"bbsid": selected["bbs_id"]},
            referer=self._personal_group_badge_referer(selected["bbs_id"], "growthValueRule"),
            allow_result=True,
        )
        data = payload.get("data")
        if not isinstance(data, dict):
            data = {}
        raw_rules = data.get("rules")
        rules = (
            [
                self._normalize_personal_group_growth_rule(raw)
                for raw in raw_rules
                if isinstance(raw, dict)
            ]
            if isinstance(raw_rules, list)
            else []
        )
        rules.sort(key=lambda item: item["growth_type"])
        return {
            "group": selected,
            "series": str(
                data.get("seriesType") or detail["settings"].get("scoreRuleSeries") or "default"
            ),
            "count": len(rules),
            "rules": rules,
            "verification": f"read {len(rules)} personal group growth rules through HTTP",
        }

    def set_personal_group_growth_rule_series(
        self,
        group: str,
        series: str,
    ) -> dict[str, Any]:
        normalized_series = str(series or "").strip().lower()
        if normalized_series not in {"default", "custom"}:
            raise ChaoxingAPIError("personal group growth rule series must be default or custom")
        before = self.list_personal_group_growth_rules(group)
        selected = before["group"]
        if not self._personal_group_can(selected, "growthEnableButton"):
            raise ChaoxingAPIError("current account cannot switch personal group growth rules")
        if before["series"] != normalized_series:
            server_rules = [
                {
                    "growthType": rule["growth_type"],
                    "growthValue": rule["growth_value"],
                }
                for rule in before["rules"]
            ]
            self._personal_group_json_request(
                self._session(),
                "/pc/circle/switchGrowthRule",
                "personal group growth rule series update",
                method="POST",
                data={
                    "bbsid": selected["bbs_id"],
                    "mode": normalized_series,
                    "rules": json.dumps(
                        server_rules if normalized_series == "custom" else [],
                        ensure_ascii=False,
                        separators=(",", ":"),
                    ),
                },
                referer=self._personal_group_badge_referer(selected["bbs_id"], "growthValueRule"),
                allow_result=True,
            )
        after = self.list_personal_group_growth_rules(selected["bbs_id"])
        if after["series"] != normalized_series:
            raise ChaoxingAPIError("personal group growth rule series differs after refresh")
        return {
            "before": before,
            **after,
            "verification": "personal group growth rule series matched a fresh read",
        }

    def update_personal_group_growth_rules(
        self,
        group: str,
        changes: dict[str | int, Any],
    ) -> dict[str, Any]:
        if not isinstance(changes, dict) or not changes:
            raise ChaoxingAPIError("at least one personal group growth rule change is required")
        before = self.list_personal_group_growth_rules(group)
        selected = before["group"]
        if not self._personal_group_can(selected, "growthEnableButton"):
            raise ChaoxingAPIError("current account cannot modify personal group growth rules")
        by_type = {rule["growth_type"]: rule for rule in before["rules"]}
        if sorted(by_type) != list(PERSONAL_GROUP_GROWTH_TYPES):
            raise ChaoxingAPIError("personal group growth rule list is incomplete")
        normalized_changes: dict[int, int] = {}
        for raw_type, raw_value in changes.items():
            try:
                growth_type = int(raw_type)
            except (TypeError, ValueError) as exc:
                raise ChaoxingAPIError("personal group growth type must be an integer") from exc
            if growth_type not in PERSONAL_GROUP_GROWTH_TYPES:
                raise ChaoxingAPIError(f"unsupported personal group growth type: {growth_type}")
            growth_value = self._personal_group_nonnegative_integer(
                raw_value, f"growth type {growth_type} value"
            )
            daily_limit = by_type[growth_type]["daily_limit"]
            if growth_type != 1 and daily_limit > 0 and growth_value > daily_limit:
                raise ChaoxingAPIError(
                    "personal group growth type "
                    f"{growth_type} cannot exceed daily limit {daily_limit}"
                )
            normalized_changes[growth_type] = growth_value
        server_rules = [
            {
                "growthType": growth_type,
                "growthValue": normalized_changes.get(
                    growth_type, by_type[growth_type]["growth_value"]
                ),
            }
            for growth_type in PERSONAL_GROUP_GROWTH_TYPES
        ]
        self._personal_group_json_request(
            self._session(),
            "/pc/circle/switchGrowthRule",
            "personal group growth rule update",
            method="POST",
            data={
                "bbsid": selected["bbs_id"],
                "mode": "custom",
                "rules": json.dumps(server_rules, ensure_ascii=False, separators=(",", ":")),
            },
            referer=self._personal_group_badge_referer(selected["bbs_id"], "growthValueRule"),
            allow_result=True,
        )
        after = self.list_personal_group_growth_rules(selected["bbs_id"])
        actual = {rule["growth_type"]: rule["growth_value"] for rule in after["rules"]}
        if after["series"] != "custom" or any(
            actual.get(growth_type) != growth_value
            for growth_type, growth_value in normalized_changes.items()
        ):
            raise ChaoxingAPIError("personal group growth rules differ after refresh")
        return {
            "before": before,
            **after,
            "changes": normalized_changes,
            "verification": "all requested personal group growth rules matched a fresh read",
        }

    @staticmethod
    def _personal_group_nonnegative_integer(value: Any, field: str) -> int:
        try:
            normalized = int(value or 0)
        except (TypeError, ValueError) as exc:
            raise ChaoxingAPIError(f"personal group rule {field} must be an integer") from exc
        if normalized < 0:
            raise ChaoxingAPIError(f"personal group rule {field} cannot be negative")
        return normalized

    @staticmethod
    def _personal_group_attachment_rules(value: Any) -> dict[str, int]:
        if value is None or value == "":
            return {}
        if isinstance(value, str):
            try:
                value = json.loads(value)
            except json.JSONDecodeError as exc:
                raise ChaoxingAPIError(
                    "personal group attachment rules contain invalid JSON"
                ) from exc
        if not isinstance(value, dict):
            raise ChaoxingAPIError("personal group attachment rules must be an object")
        return {
            str(key): 1 if ChaoxingAPI._personal_group_boolean(item) else 0
            for key, item in value.items()
            if str(key).strip()
        }

    def update_personal_group_speaking_rules(
        self,
        group: str,
        changes: dict[str, Any],
        *,
        attachment_rules: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        if not isinstance(changes, dict):
            raise ChaoxingAPIError("personal group speaking-rule changes must be an object")
        unknown = sorted(set(changes) - set(PERSONAL_GROUP_SPEAKING_RULE_FIELDS))
        if unknown:
            raise ChaoxingAPIError(
                f"unsupported personal group speaking rules: {', '.join(unknown)}"
            )
        if not changes and attachment_rules is None:
            raise ChaoxingAPIError("at least one personal group speaking-rule change is required")
        before_detail = self.read_personal_group(group)
        selected = before_detail["group"]
        if not self._personal_group_can(selected, "showSpeechSet"):
            raise ChaoxingAPIError("current account cannot change speaking rules in this group")
        params = {
            field: self._personal_group_nonnegative_integer(
                changes.get(field, before_detail["settings"].get(field, 0)), field
            )
            for field in PERSONAL_GROUP_SPEAKING_RULE_FIELDS
        }
        current_attachment_rules = self._personal_group_attachment_rules(
            before_detail["settings"].get("topicNeedAttachment")
        )
        desired_attachment_rules = (
            self._personal_group_attachment_rules(attachment_rules)
            if attachment_rules is not None
            else current_attachment_rules
        )
        params["topicNeedAttachment"] = json.dumps(
            desired_attachment_rules, ensure_ascii=False, separators=(",", ":")
        )
        session, landing = self._personal_groups_context()
        self._personal_group_json_request(
            session,
            f"/pc/circle/manage/{quote(selected['bbs_id'], safe='')}/updateCircleExtend",
            "personal group speaking-rule update",
            params=params,
            referer=selected["management_url"] or landing.url,
        )
        after_detail = self.read_personal_group(selected["bbs_id"])
        for field in PERSONAL_GROUP_SPEAKING_RULE_FIELDS:
            actual = self._personal_group_nonnegative_integer(
                after_detail["settings"].get(field, 0), field
            )
            if actual != params[field]:
                raise ChaoxingAPIError(
                    f"personal group speaking rule {field} differs after refresh"
                )
        after_attachments = self._personal_group_attachment_rules(
            after_detail["settings"].get("topicNeedAttachment")
        )
        if after_attachments != desired_attachment_rules:
            raise ChaoxingAPIError("personal group attachment rules differ after refresh")
        return {
            "before": before_detail,
            "group": after_detail["group"],
            "speaking_rules": {
                **{field: params[field] for field in PERSONAL_GROUP_SPEAKING_RULE_FIELDS},
                "topicNeedAttachment": desired_attachment_rules,
            },
            "verification": "personal group speaking rules matched a fresh detail read",
        }

    def send_personal_group_notice(
        self,
        group: str,
        title: str,
        content: str,
        *,
        pcode: str = "",
    ) -> dict[str, Any]:
        title = title.strip()
        content = content.strip()
        if not title or not content:
            raise ChaoxingAPIError("personal group notice title and content are required")
        selected = self._find_personal_group(group)
        if not self._personal_group_can(selected, "sendNotice"):
            raise ChaoxingAPIError("current account cannot send notices to this personal group")
        session, landing = self._personal_groups_context()
        editor_url = (
            GROUPWEB_BASE_URL
            + "/pc/circle/manage/circleNoticePage?"
            + urlencode({"bbsid": selected["bbs_id"]})
        )
        try:
            response = session.post(
                GROUPWEB_BASE_URL + "/pc/circle/manage/addCircleNotice",
                data={
                    "bbsid": selected["bbs_id"],
                    "title": title,
                    "content": content,
                    "pcode": pcode.strip(),
                    "attr_file": "",
                    "imgs": "",
                    "isRtf": 1,
                    "rtf_content": self._notice_rtf(content),
                },
                headers={"Referer": editor_url or landing.url},
                timeout=max(self.timeout, 60),
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"personal group notice send failed: {exc}") from exc
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("personal group notice send returned invalid JSON") from exc
        if not isinstance(payload, dict) or payload.get("status") is not True:
            if isinstance(payload, dict) and payload.get("objs"):
                raise ChaoxingAPIError(
                    f"personal group notice requires the displayed pcode: {payload['objs']}"
                )
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "personal group notice send was rejected"))
        data = payload.get("data")
        notice_id = str(data.get("idCode") or "") if isinstance(data, dict) else ""
        if not notice_id:
            raise ChaoxingAPIError("personal group notice send returned no notice ID")
        sent = self.list_inbox_notices(scope="sent", search=title, max_items=1000)
        published = self._resolve_inbox_notice(sent["notices"], notice_id or title)
        if published["title"] != title:
            raise ChaoxingAPIError("personal group notice title differs in the sent inbox")
        return {
            "group": selected,
            "notice": published,
            "verification": "notice ID and title matched a fresh sent-inbox read",
        }

    @staticmethod
    def _personal_group_review_reminder_referer(bbs_id: str) -> str:
        return (
            GROUPWEB_BASE_URL + "/pc/checkRemind/jumpToRemindPage?" + urlencode({"bbsid": bbs_id})
        )

    @staticmethod
    def _normalize_personal_group_review_reminder_weeks(weeks: Any) -> list[str]:
        if isinstance(weeks, str):
            decoded = weeks.strip()
            for _ in range(2):
                unquoted = unquote(decoded)
                if unquoted == decoded:
                    break
                decoded = unquoted
            values = re.split(r"[、,，;；\s]+", decoded)
        elif isinstance(weeks, (list, tuple, set)):
            values = [str(item or "").strip() for item in weeks]
        else:
            values = []
        aliases = {
            **{
                str(index): name
                for index, name in enumerate(PERSONAL_GROUP_REVIEW_REMINDER_WEEKS, 1)
            },
            **{f"周{name[-1]}": name for name in PERSONAL_GROUP_REVIEW_REMINDER_WEEKS},
            **{name: name for name in PERSONAL_GROUP_REVIEW_REMINDER_WEEKS},
            "星期天": "星期日",
            "周天": "星期日",
        }
        normalized: list[str] = []
        for value in values:
            item = aliases.get(value.strip())
            if item and item not in normalized:
                normalized.append(item)
        if not normalized:
            raise ChaoxingAPIError("at least one valid review-reminder weekday is required")
        return [item for item in PERSONAL_GROUP_REVIEW_REMINDER_WEEKS if item in normalized]

    @staticmethod
    def _normalize_personal_group_review_reminder_time(value: Any, field: str) -> str:
        normalized = str(value or "").strip()
        try:
            parsed = datetime.strptime(normalized, "%H:%M")
        except ValueError as exc:
            raise ChaoxingAPIError(f"review-reminder {field} must use HH:MM") from exc
        return parsed.strftime("%H:%M")

    @staticmethod
    def _normalize_personal_group_review_reminder_puids(puids: Any) -> list[str]:
        if isinstance(puids, str):
            values = re.split(r"[,，;；\s]+", puids)
        elif isinstance(puids, (list, tuple, set)):
            values = [str(item or "").strip() for item in puids]
        else:
            values = []
        normalized = list(dict.fromkeys(item.strip() for item in values if item.strip()))
        if not normalized or any(not item.isdigit() for item in normalized):
            raise ChaoxingAPIError("review-reminder reviewer PUIDs must be non-empty digits")
        return normalized

    @staticmethod
    def _personal_group_review_reminder_names(raw: dict[str, Any]) -> list[str]:
        value = raw.get("namesList") or raw.get("nameList") or raw.get("names") or []
        if isinstance(value, str):
            values: list[Any] = re.split(r"[,，、;；]+", value)
        elif isinstance(value, list):
            values = value
        else:
            values = []
        names: list[str] = []
        for item in values:
            name = (
                str(item.get("name") or item.get("personName") or "").strip()
                if isinstance(item, dict)
                else str(item or "").strip()
            )
            if name and name not in names:
                names.append(name)
        return names

    @classmethod
    def _normalize_personal_group_review_reminder(
        cls,
        raw: dict[str, Any],
        index: int = 0,
    ) -> dict[str, Any]:
        raw_puids = (
            raw.get("puids") or raw.get("puidList") or raw.get("puid") or raw.get("userIds") or []
        )
        if isinstance(raw_puids, list):
            puid_values = [
                str(item.get("puid") or item.get("id") or "").strip()
                if isinstance(item, dict)
                else str(item or "").strip()
                for item in raw_puids
            ]
        else:
            puid_values = re.split(r"[,，;；\s]+", str(raw_puids or ""))
        puids = list(dict.fromkeys(item for item in puid_values if item.isdigit()))
        raw_weeks = raw.get("weeks") or raw.get("week") or []
        try:
            weeks = cls._normalize_personal_group_review_reminder_weeks(raw_weeks)
        except ChaoxingAPIError:
            weeks = []
        return {
            "index": index,
            "uuid": str(raw.get("uuid") or raw.get("id") or "").strip(),
            "start_time": str(raw.get("startTime") or "").strip(),
            "end_time": str(raw.get("endTime") or "").strip(),
            "weeks": weeks,
            "week_text": "、".join(weeks),
            "puids": puids,
            "names": cls._personal_group_review_reminder_names(raw),
        }

    @staticmethod
    def _resolve_personal_group_review_reminder(
        reminders: list[dict[str, Any]], query: str
    ) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("review-reminder UUID or index is required")
        for key in ("uuid", "index"):
            matches = [
                reminder
                for reminder in reminders
                if str(reminder.get(key) or "").strip().lower() == normalized
            ]
            if len(matches) == 1:
                return matches[0]
            if len(matches) > 1:
                raise ChaoxingAPIError(f"multiple review reminders match: {query}")
        raise ChaoxingAPIError(f"review reminder not found: {query}")

    @staticmethod
    def _parse_personal_group_reviewers(html: str) -> list[dict[str, str]]:
        reviewers: list[dict[str, str]] = []
        seen: set[str] = set()
        pattern = re.compile(
            r"<div\b(?=[^>]*\bclass=['\"][^'\"]*\badminItem\b[^'\"]*['\"])(?=[^>]*"
            r"\bpuid=['\"]([^'\"]+)['\"])[^>]*>([\s\S]*?)</div>",
            flags=re.IGNORECASE,
        )
        for match in pattern.finditer(html):
            puid = match.group(1).strip()
            if not puid or puid in seen:
                continue
            block = match.group(2)
            name_match = re.search(
                r"<span\b[^>]*class=['\"][^'\"]*\bmanagerName\b[^'\"]*['\"][^>]*>"
                r"([\s\S]*?)</span>",
                block,
                flags=re.IGNORECASE,
            )
            seen.add(puid)
            reviewers.append(
                {
                    "puid": puid,
                    "name": html_text(name_match.group(1)) if name_match else "",
                }
            )
        return reviewers

    def list_personal_group_review_reminders(self, group: str) -> dict[str, Any]:
        detail = self.read_personal_group(group)
        selected = detail["group"]
        session, landing = self._personal_groups_context()
        referer = self._personal_group_review_reminder_referer(selected["bbs_id"])
        try:
            page = session.get(
                referer,
                headers={"Referer": selected["management_url"] or landing.url},
                timeout=max(self.timeout, 60),
            )
            page.raise_for_status()
            response = session.get(
                GROUPWEB_BASE_URL + "/pc/checkRemind/getRemindList",
                params={"bbsid": selected["bbs_id"]},
                headers={"Referer": referer},
                timeout=max(self.timeout, 60),
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"personal group review-reminder list failed: {exc}") from exc
        reviewers = self._parse_personal_group_reviewers(self._decode(page))
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError(
                "personal group review-reminder list returned invalid JSON"
            ) from exc
        if not isinstance(payload, dict):
            raise ChaoxingAPIError("personal group review-reminder list returned invalid JSON")
        data = payload.get("data")
        raw_records = payload.get("records")
        if raw_records is None and isinstance(data, dict):
            raw_records = data.get("records")
        if raw_records is None:
            raw_records = []
        if not isinstance(raw_records, list):
            raise ChaoxingAPIError("personal group review-reminder list returned invalid records")
        reminders = [
            self._normalize_personal_group_review_reminder(raw, index)
            for index, raw in enumerate(raw_records, 1)
            if isinstance(raw, dict)
        ]
        reviewer_by_name: dict[str, list[str]] = {}
        for reviewer in reviewers:
            reviewer_by_name.setdefault(reviewer["name"], []).append(reviewer["puid"])
        for reminder in reminders:
            if reminder["puids"]:
                reminder["puids_source"] = "server"
                continue
            inferred = [
                reviewer_by_name[name][0]
                for name in reminder["names"]
                if len(reviewer_by_name.get(name, [])) == 1
            ]
            reminder["puids"] = list(dict.fromkeys(inferred))
            reminder["puids_source"] = "matched_reviewers" if inferred else "unavailable"
        return {
            "group": selected,
            "account": detail["account"],
            "reviewer_count": len(reviewers),
            "reviewers": reviewers,
            "count": len(reminders),
            "reminders": reminders,
            "verification": (
                f"read {len(reminders)} review reminders and {len(reviewers)} eligible reviewers "
                "through HTTP"
            ),
        }

    @staticmethod
    def _personal_group_review_reminder_payload(
        bbs_id: str,
        start_time: Any,
        end_time: Any,
        weeks: Any,
        puids: Any,
        *,
        uuid: str = "",
    ) -> dict[str, str]:
        normalized_start = ChaoxingAPI._normalize_personal_group_review_reminder_time(
            start_time, "start time"
        )
        normalized_end = ChaoxingAPI._normalize_personal_group_review_reminder_time(
            end_time, "end time"
        )
        if normalized_start >= normalized_end:
            raise ChaoxingAPIError("review-reminder end time must be later than start time")
        normalized_weeks = ChaoxingAPI._normalize_personal_group_review_reminder_weeks(weeks)
        normalized_puids = ChaoxingAPI._normalize_personal_group_review_reminder_puids(puids)
        payload = {
            "bbsid": bbs_id,
            "startTime": normalized_start,
            "endTime": normalized_end,
            "weeks": quote("、".join(normalized_weeks), safe=""),
            "puids": ",".join(normalized_puids),
        }
        if uuid:
            payload["uuid"] = uuid
        return payload

    def create_personal_group_review_reminder(
        self,
        group: str,
        start_time: str,
        end_time: str,
        weeks: list[str],
        puids: list[str],
    ) -> dict[str, Any]:
        before = self.list_personal_group_review_reminders(group)
        selected = before["group"]
        if not self._personal_group_can(selected, "showTopicNeedCheck"):
            raise ChaoxingAPIError("current account cannot create review reminders in this group")
        request_data = self._personal_group_review_reminder_payload(
            selected["bbs_id"], start_time, end_time, weeks, puids
        )
        self._personal_group_json_request(
            self._session(),
            "/pc/checkRemind/addRemind",
            "personal group review-reminder creation",
            method="POST",
            data=request_data,
            referer=self._personal_group_review_reminder_referer(selected["bbs_id"]),
            allow_result=True,
        )
        refreshed = self.list_personal_group_review_reminders(selected["bbs_id"])
        before_ids = {item["uuid"] for item in before["reminders"]}
        candidates = [
            item
            for item in refreshed["reminders"]
            if item["uuid"] not in before_ids
            and item["start_time"] == request_data["startTime"]
            and item["end_time"] == request_data["endTime"]
            and item["weeks"] == self._normalize_personal_group_review_reminder_weeks(weeks)
        ]
        if len(candidates) != 1:
            raise ChaoxingAPIError("created review reminder was not unique after refresh")
        return {
            "group": selected,
            "reminder": candidates[0],
            "verification": "created review reminder matched a fresh list read",
        }

    def update_personal_group_review_reminder(
        self,
        group: str,
        reminder: str,
        *,
        start_time: str | None = None,
        end_time: str | None = None,
        weeks: list[str] | None = None,
        puids: list[str] | None = None,
    ) -> dict[str, Any]:
        if all(value is None for value in (start_time, end_time, weeks, puids)):
            raise ChaoxingAPIError("at least one review-reminder change is required")
        listing = self.list_personal_group_review_reminders(group)
        selected = listing["group"]
        if not self._personal_group_can(selected, "showTopicNeedCheck"):
            raise ChaoxingAPIError("current account cannot update review reminders in this group")
        before = self._resolve_personal_group_review_reminder(listing["reminders"], reminder)
        desired_puids = puids if puids is not None else before["puids"]
        if not desired_puids:
            raise ChaoxingAPIError(
                "reviewer PUIDs must be supplied because the existing reminder did not expose them"
            )
        request_data = self._personal_group_review_reminder_payload(
            selected["bbs_id"],
            start_time if start_time is not None else before["start_time"],
            end_time if end_time is not None else before["end_time"],
            weeks if weeks is not None else before["weeks"],
            desired_puids,
            uuid=before["uuid"],
        )
        self._personal_group_json_request(
            self._session(),
            "/pc/checkRemind/updateRemind",
            "personal group review-reminder update",
            method="POST",
            data=request_data,
            referer=self._personal_group_review_reminder_referer(selected["bbs_id"]),
            allow_result=True,
        )
        refreshed = self.list_personal_group_review_reminders(selected["bbs_id"])
        after = self._resolve_personal_group_review_reminder(refreshed["reminders"], before["uuid"])
        expected_weeks = self._normalize_personal_group_review_reminder_weeks(
            weeks if weeks is not None else before["weeks"]
        )
        if (
            after["start_time"] != request_data["startTime"]
            or after["end_time"] != request_data["endTime"]
            or after["weeks"] != expected_weeks
        ):
            raise ChaoxingAPIError("updated review reminder differs after refresh")
        return {
            "group": selected,
            "before": before,
            "reminder": after,
            "verification": "updated review reminder matched a fresh list read",
        }

    def delete_personal_group_review_reminders(
        self, group: str, reminders: list[str]
    ) -> dict[str, Any]:
        if not reminders:
            raise ChaoxingAPIError("at least one review reminder is required")
        listing = self.list_personal_group_review_reminders(group)
        selected_group = listing["group"]
        if not self._personal_group_can(selected_group, "showTopicNeedCheck"):
            raise ChaoxingAPIError("current account cannot delete review reminders in this group")
        selected = [
            self._resolve_personal_group_review_reminder(listing["reminders"], query)
            for query in reminders
        ]
        uuids = list(dict.fromkeys(item["uuid"] for item in selected))
        self._personal_group_json_request(
            self._session(),
            "/pc/checkRemind/delRemind",
            "personal group review-reminder deletion",
            method="POST",
            data={"bbsid": selected_group["bbs_id"], "uuids": ",".join(uuids)},
            referer=self._personal_group_review_reminder_referer(selected_group["bbs_id"]),
            allow_result=True,
        )
        refreshed = self.list_personal_group_review_reminders(selected_group["bbs_id"])
        remaining = {item["uuid"] for item in refreshed["reminders"]}
        if any(uuid in remaining for uuid in uuids):
            raise ChaoxingAPIError("deleted review reminder still appears after refresh")
        return {
            "group": selected_group,
            "deleted": selected,
            "verification": "all deleted review reminders were absent after refresh",
        }

    @staticmethod
    def _personal_group_nested_data(payload: dict[str, Any], operation: str) -> Any:
        nested: Any = payload.get("msg")
        if isinstance(nested, str):
            try:
                nested = json.loads(nested)
            except json.JSONDecodeError as exc:
                raise ChaoxingAPIError(f"{operation} returned invalid nested JSON") from exc
        if not isinstance(nested, dict):
            raise ChaoxingAPIError(f"{operation} returned no data object")
        if nested.get("result") not in {None, True, "1"}:
            raise ChaoxingAPIError(str(nested.get("msg") or f"{operation} was rejected"))
        return nested.get("data")

    @staticmethod
    def _normalize_personal_group_label(raw: dict[str, Any], index: int = 0) -> dict[str, Any]:
        return {
            "index": index,
            "label_id": str(raw.get("id") or ""),
            "label_uuid": str(raw.get("uuid") or ""),
            "bbs_id": str(raw.get("bbsid") or ""),
            "name": str(raw.get("name") or "").strip(),
            "label_type": int(raw.get("labelType") or 0),
            "sort": int(raw.get("sort") or 0),
            "created_at": raw.get("insertTime"),
            "updated_at": raw.get("updateTime"),
        }

    @staticmethod
    def _resolve_personal_group_label(labels: list[dict[str, Any]], query: str) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("personal group label name, UUID, ID, or index is required")
        for key in ("label_uuid", "label_id", "index", "name"):
            exact = [
                item for item in labels if str(item.get(key) or "").strip().lower() == normalized
            ]
            if len(exact) == 1:
                return exact[0]
            if len(exact) > 1:
                raise ChaoxingAPIError(f"multiple personal group labels match: {query}")
        partial = [item for item in labels if normalized in item["name"].lower()]
        if len(partial) == 1:
            return partial[0]
        if not partial:
            raise ChaoxingAPIError(f"personal group label not found: {query}")
        raise ChaoxingAPIError(f"multiple personal group labels match: {query}")

    def list_personal_group_labels(self, group: str) -> dict[str, Any]:
        context = self._personal_group_topic_context(group)
        selected = context["group"]
        payload = self._personal_group_json_request(
            context["session"],
            "/pc/topic/topiclist/getLabelList",
            "personal group label list",
            method="POST",
            data={"bbsid": selected["bbs_id"]},
            referer=context["landing_url"],
        )
        raw_labels = self._personal_group_nested_data(payload, "personal group label list")
        labels = [
            self._normalize_personal_group_label(raw, index)
            for index, raw in enumerate(raw_labels if isinstance(raw_labels, list) else [], 1)
            if isinstance(raw, dict)
        ]
        return {
            "group": selected,
            "count": len(labels),
            "labels": labels,
            "verification": f"read {len(labels)} personal group labels through HTTP",
        }

    def create_personal_group_label(self, group: str, name: str) -> dict[str, Any]:
        name = name.strip()
        if not name:
            raise ChaoxingAPIError("personal group label name is required")
        if len(name) > 50:
            raise ChaoxingAPIError("personal group label name cannot exceed 50 characters")
        selected = self._find_personal_group(group)
        if not self._personal_group_can(selected, "addLebel"):
            raise ChaoxingAPIError("current account cannot create labels in this group")
        before = self.list_personal_group_labels(selected["bbs_id"])
        if any(item["name"] == name for item in before["labels"]):
            raise ChaoxingAPIError(f"personal group label already exists: {name}")
        session, landing = self._personal_groups_context()
        payload = self._personal_group_json_request(
            session,
            "/pc/topic/topiclist/addLabel",
            "personal group label creation",
            method="POST",
            data={
                "puid": self._personal_group_account_puid(selected["bbs_id"]),
                "bbsid": selected["bbs_id"],
                "label": quote(name, safe=""),
            },
            referer=selected["management_url"] or landing.url,
        )
        refreshed = self.list_personal_group_labels(selected["bbs_id"])
        before_ids = {item["label_uuid"] for item in before["labels"]}
        created = [
            item
            for item in refreshed["labels"]
            if item["label_uuid"] not in before_ids and item["name"] == name
        ]
        if len(created) != 1:
            raise ChaoxingAPIError("created personal group label was not unique after refresh")
        return {
            "group": selected,
            "label": created[0],
            "server_message": str(payload.get("msg") or ""),
            "verification": "created personal group label matched a fresh label-list read",
        }

    def rename_personal_group_label(self, group: str, label: str, name: str) -> dict[str, Any]:
        name = name.strip()
        if not name:
            raise ChaoxingAPIError("personal group label name is required")
        if len(name) > 50:
            raise ChaoxingAPIError("personal group label name cannot exceed 50 characters")
        selected = self._find_personal_group(group)
        if not self._personal_group_can(selected, "addLebel"):
            raise ChaoxingAPIError("current account cannot rename labels in this group")
        listing = self.list_personal_group_labels(selected["bbs_id"])
        before = self._resolve_personal_group_label(listing["labels"], label)
        if any(
            item["name"] == name and item["label_uuid"] != before["label_uuid"]
            for item in listing["labels"]
        ):
            raise ChaoxingAPIError(f"personal group label already exists: {name}")
        session, landing = self._personal_groups_context()
        payload = self._personal_group_json_request(
            session,
            "/pc/topic/topiclist/updateLabel",
            "personal group label rename",
            method="POST",
            data={
                "puid": self._personal_group_account_puid(selected["bbs_id"]),
                "bbsid": selected["bbs_id"],
                "labelUuids": before["label_uuid"],
                "label": quote(name, safe=""),
            },
            referer=selected["management_url"] or landing.url,
        )
        after = self._resolve_personal_group_label(
            self.list_personal_group_labels(selected["bbs_id"])["labels"],
            before["label_uuid"],
        )
        if after["name"] != name:
            raise ChaoxingAPIError("personal group label name differs after refresh")
        return {
            "group": selected,
            "before": before,
            "label": after,
            "server_message": str(payload.get("msg") or ""),
            "verification": "personal group label name matched a fresh label-list read",
        }

    def reorder_personal_group_labels(self, group: str, labels: list[str]) -> dict[str, Any]:
        selected = self._find_personal_group(group)
        if not self._personal_group_can(selected, "addLebel"):
            raise ChaoxingAPIError("current account cannot reorder labels in this group")
        listing = self.list_personal_group_labels(selected["bbs_id"])
        resolved = [
            self._resolve_personal_group_label(listing["labels"], query) for query in labels
        ]
        requested_ids = [item["label_uuid"] for item in resolved]
        existing_ids = [item["label_uuid"] for item in listing["labels"]]
        if len(set(requested_ids)) != len(requested_ids):
            raise ChaoxingAPIError("personal group label order contains duplicates")
        if set(requested_ids) != set(existing_ids):
            raise ChaoxingAPIError(
                "personal group label order must contain every label exactly once"
            )
        session, landing = self._personal_groups_context()
        self._personal_group_json_request(
            session,
            "/pc/topic/topiclist/updateLabelSort",
            "personal group label reorder",
            method="POST",
            data={
                "bbsid": selected["bbs_id"],
                "labelUuids": "," + ",".join(requested_ids),
            },
            referer=selected["management_url"] or landing.url,
        )
        refreshed = self.list_personal_group_labels(selected["bbs_id"])["labels"]
        refreshed_ids = [item["label_uuid"] for item in refreshed]
        if refreshed_ids != requested_ids:
            raise ChaoxingAPIError("personal group label order differs after refresh")
        return {
            "group": selected,
            "labels": refreshed,
            "verification": "personal group label order matched a fresh label-list read",
        }

    def delete_personal_group_labels(self, group: str, labels: list[str]) -> dict[str, Any]:
        if not labels:
            raise ChaoxingAPIError("at least one personal group label is required")
        selected = self._find_personal_group(group)
        if not self._personal_group_can(selected, "addLebel"):
            raise ChaoxingAPIError("current account cannot delete labels in this group")
        listing = self.list_personal_group_labels(selected["bbs_id"])
        resolved = [
            self._resolve_personal_group_label(listing["labels"], query) for query in labels
        ]
        uuids = [item["label_uuid"] for item in resolved]
        if len(set(uuids)) != len(uuids):
            raise ChaoxingAPIError("personal group label deletion contains duplicates")
        session, landing = self._personal_groups_context()
        payload = self._personal_group_json_request(
            session,
            "/pc/topic/topiclist/delLabel",
            "personal group label deletion",
            method="POST",
            data={
                "puid": self._personal_group_account_puid(selected["bbs_id"]),
                "bbsid": selected["bbs_id"],
                "labelUuids": ",".join(uuids),
            },
            referer=selected["management_url"] or landing.url,
        )
        remaining = self.list_personal_group_labels(selected["bbs_id"])["labels"]
        remaining_ids = {item["label_uuid"] for item in remaining}
        if set(uuids) & remaining_ids:
            raise ChaoxingAPIError("deleted personal group labels still appear after refresh")
        return {
            "group": selected,
            "deleted_labels": resolved,
            "server_message": str(payload.get("msg") or ""),
            "verification": "deleted personal group labels are absent from a fresh list read",
        }

