    @staticmethod
    def _normalize_personal_group_recycle_item(
        raw: dict[str, Any], index: int = 0
    ) -> dict[str, Any]:
        content = raw.get("content") if isinstance(raw.get("content"), dict) else {}
        raw_type = str(raw.get("dataType") or "").lower()
        if raw_type == "invitation":
            invitation = (
                content.get("invitation") if isinstance(content.get("invitation"), dict) else {}
            )
            topic = content.get("topic") if isinstance(content.get("topic"), dict) else {}
            title = str(topic.get("title") or topic.get("content") or "").strip()
            body = str(invitation.get("content") or "").strip()
            original_uuid = str(invitation.get("uuid") or "")
            item_type = "reply"
        elif raw_type == "folder":
            title = str(content.get("name") or "").strip()
            body = ""
            original_uuid = str(content.get("folder_uuid") or "")
            item_type = "folder"
        else:
            title = str(content.get("title") or "").strip()
            body = str(content.get("content") or "").strip()
            original_uuid = str(content.get("uuid") or "")
            item_type = "topic"
        return {
            "index": index,
            "recycle_id": str(raw.get("id") or ""),
            "item_type": item_type,
            "original_uuid": original_uuid,
            "title": title,
            "content": body,
            "reason": str(raw.get("reason") or ""),
            "operator_name": str(raw.get("operatorName") or ""),
            "deleted_at": raw.get("insert_time") or raw.get("insertTime"),
            "raw_data_type": raw_type,
        }

    @staticmethod
    def _resolve_personal_group_recycle_item(
        items: list[dict[str, Any]], query: str
    ) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("recycle item ID, UUID, title, content, or index is required")
        for key in ("recycle_id", "original_uuid", "index", "title", "content"):
            exact = [
                item for item in items if str(item.get(key) or "").strip().lower() == normalized
            ]
            if len(exact) == 1:
                return exact[0]
            if len(exact) > 1:
                raise ChaoxingAPIError(f"multiple personal group recycle items match: {query}")
        partial = [
            item for item in items if normalized in (item["title"] + "\n" + item["content"]).lower()
        ]
        if len(partial) == 1:
            return partial[0]
        if not partial:
            raise ChaoxingAPIError(f"personal group recycle item not found: {query}")
        raise ChaoxingAPIError(f"multiple personal group recycle items match: {query}")

    def list_personal_group_recycle_items(self, group: str) -> dict[str, Any]:
        selected = self._find_personal_group(group)
        if not self._personal_group_can(selected, "showRecycleBin"):
            raise ChaoxingAPIError("current account cannot read this personal group recycle bin")
        session, landing = self._personal_groups_context()
        items: list[dict[str, Any]] = []
        last_value = ""
        for _page in range(1, 501):
            payload = self._personal_group_json_request(
                session,
                f"/pc/recycle/{quote(selected['bbs_id'], safe='')}/getRecycleDataList",
                "personal group recycle list",
                params={"pageSize": 100, "lastValue": last_value},
                referer=selected["management_url"] or landing.url,
            )
            raw_items = payload.get("datas")
            for raw in raw_items if isinstance(raw_items, list) else []:
                if isinstance(raw, dict):
                    items.append(self._normalize_personal_group_recycle_item(raw, len(items) + 1))
            poff = payload.get("poff") if isinstance(payload.get("poff"), dict) else {}
            if str(poff.get("lastPage") or "0") in {"1", "true", "True"}:
                break
            next_value = str(poff.get("lastValue") or "")
            if not next_value or next_value == last_value:
                break
            last_value = next_value
        else:
            raise ChaoxingAPIError("personal group recycle pagination exceeded 500 pages")
        return {
            "group": selected,
            "count": len(items),
            "items": items,
            "verification": f"read {len(items)} personal group recycle items through HTTP",
        }

    def restore_personal_group_recycle_items(self, group: str, items: list[str]) -> dict[str, Any]:
        if not items:
            raise ChaoxingAPIError("at least one personal group recycle item is required")
        selected = self._find_personal_group(group)
        if not self._personal_group_can(selected, "showRecycleBin"):
            raise ChaoxingAPIError("current account cannot restore this group recycle bin")
        listing = self.list_personal_group_recycle_items(selected["bbs_id"])
        resolved = [
            self._resolve_personal_group_recycle_item(listing["items"], query) for query in items
        ]
        ids = [item["recycle_id"] for item in resolved]
        if len(set(ids)) != len(ids):
            raise ChaoxingAPIError("personal group recycle restoration contains duplicates")
        if len(ids) > 100:
            raise ChaoxingAPIError("Chaoxing restores at most 100 group recycle items at once")
        endpoint_by_type = {
            "folder": "/pc/recycle/recoveryTopicFolder",
            "topic": "/pc/recycle/recoveryTopic",
            "reply": "/pc/recycle/recoveryInvitation",
        }
        session, landing = self._personal_groups_context()
        messages: list[str] = []
        for item_type, endpoint in endpoint_by_type.items():
            selected_ids = [
                item["recycle_id"] for item in resolved if item["item_type"] == item_type
            ]
            if not selected_ids:
                continue
            payload = self._personal_group_json_request(
                session,
                endpoint,
                f"personal group {item_type} recycle restoration",
                params={"recycleId": ",".join(selected_ids), "bbsid": selected["bbs_id"]},
                referer=selected["management_url"] or landing.url,
            )
            messages.append(str(payload.get("msg") or ""))
        remaining = self.list_personal_group_recycle_items(selected["bbs_id"])["items"]
        if set(ids) & {item["recycle_id"] for item in remaining}:
            raise ChaoxingAPIError("restored personal group items remain in recycle after refresh")
        return {
            "group": selected,
            "restored_items": resolved,
            "server_messages": messages,
            "verification": "restored items are absent from a fresh recycle-list read",
        }

    def permanently_delete_personal_group_recycle_items(
        self, group: str, items: list[str]
    ) -> dict[str, Any]:
        if not items:
            raise ChaoxingAPIError("at least one personal group recycle item is required")
        selected = self._find_personal_group(group)
        if not self._personal_group_can(selected, "showRecycleBin"):
            raise ChaoxingAPIError("current account cannot delete this group recycle bin")
        listing = self.list_personal_group_recycle_items(selected["bbs_id"])
        resolved = [
            self._resolve_personal_group_recycle_item(listing["items"], query) for query in items
        ]
        ids = [item["recycle_id"] for item in resolved]
        if len(set(ids)) != len(ids):
            raise ChaoxingAPIError("personal group recycle deletion contains duplicates")
        if len(ids) > 100:
            raise ChaoxingAPIError("Chaoxing deletes at most 100 group recycle items at once")
        session, landing = self._personal_groups_context()
        payload = self._personal_group_json_request(
            session,
            "/pc/recycle/deleteResource",
            "personal group recycle permanent deletion",
            params={"resourceIds": ",".join(ids), "bbsid": selected["bbs_id"]},
            referer=selected["management_url"] or landing.url,
        )
        remaining = self.list_personal_group_recycle_items(selected["bbs_id"])["items"]
        if set(ids) & {item["recycle_id"] for item in remaining}:
            raise ChaoxingAPIError("deleted personal group recycle items remain after refresh")
        return {
            "group": selected,
            "deleted_items": resolved,
            "server_message": str(payload.get("msg") or ""),
            "verification": "permanently deleted items are absent from a fresh recycle read",
        }

    def empty_personal_group_recycle(self, group: str) -> dict[str, Any]:
        selected = self._find_personal_group(group)
        if not self._personal_group_can(selected, "showRecycleBin"):
            raise ChaoxingAPIError("current account cannot empty this group recycle bin")
        before = self.list_personal_group_recycle_items(selected["bbs_id"])
        if not before["items"]:
            return {
                "group": selected,
                "previous_count": 0,
                "verification": "personal group recycle bin was already empty",
            }
        session, landing = self._personal_groups_context()
        payload = self._personal_group_json_request(
            session,
            "/pc/recycle/clearRecycleBin",
            "personal group recycle empty",
            params={"bbsid": selected["bbs_id"]},
            referer=selected["management_url"] or landing.url,
        )
        for _attempt in range(12):
            sleep(5)
            refreshed = self.list_personal_group_recycle_items(selected["bbs_id"])
            if not refreshed["items"]:
                return {
                    "group": selected,
                    "previous_count": before["count"],
                    "server_message": str(payload.get("msg") or ""),
                    "verification": "personal group recycle bin is empty after refresh",
                }
        raise ChaoxingAPIError("personal group recycle bin did not become empty within 60 seconds")

    @staticmethod
    def _normalize_personal_group_export_job(raw: dict[str, Any], index: int = 0) -> dict[str, Any]:
        status_code = int(raw.get("status") or 0)
        status = {0: "exporting", 1: "ready", 2: "failed"}.get(status_code, "unknown")
        return {
            "index": index,
            "export_id": str(raw.get("id") or ""),
            "file_name": str(raw.get("fileName") or "").strip(),
            "file_size": int(raw.get("fileSize") or 0),
            "formatted_time": str(raw.get("ftime") or "").strip(),
            "status": status,
            "status_code": status_code,
            "download_url": str(raw.get("downloadURL") or "").strip(),
        }

    @staticmethod
    def _resolve_personal_group_export_job(
        jobs: list[dict[str, Any]], query: str
    ) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("personal group export ID, file name, or index is required")
        for key in ("export_id", "index", "file_name"):
            exact = [job for job in jobs if str(job.get(key) or "").strip().lower() == normalized]
            if len(exact) == 1:
                return exact[0]
            if len(exact) > 1:
                raise ChaoxingAPIError(f"multiple personal group exports match: {query}")
        partial = [job for job in jobs if normalized in job["file_name"].lower()]
        if len(partial) == 1:
            return partial[0]
        if not partial:
            raise ChaoxingAPIError(f"personal group export not found: {query}")
        raise ChaoxingAPIError(f"multiple personal group exports match: {query}")

    def list_personal_group_exports(self, group: str) -> dict[str, Any]:
        selected = self._find_personal_group(group)
        session = self._session()
        jobs: list[dict[str, Any]] = []
        seen: set[str] = set()
        last_value = ""
        for _page in range(1, 501):
            payload = self._personal_group_json_request(
                session,
                "/pc/statistics/getDownloadCenterList",
                "personal group export list",
                params={
                    "bbsid": selected["bbs_id"],
                    "lastValue": last_value,
                    "sortType": "",
                },
                referer=selected["management_url"],
            )
            raw_jobs = payload.get("list")
            for raw in raw_jobs if isinstance(raw_jobs, list) else []:
                if not isinstance(raw, dict):
                    continue
                job = self._normalize_personal_group_export_job(raw, len(jobs) + 1)
                if not job["export_id"] or job["export_id"] in seen:
                    continue
                seen.add(job["export_id"])
                jobs.append(job)
            poff = payload.get("poff") if isinstance(payload.get("poff"), dict) else {}
            if str(poff.get("lastPage") or "0").lower() in {"1", "true"}:
                break
            next_value = str(poff.get("lastValue") or "")
            if not next_value or next_value == last_value:
                break
            last_value = next_value
        else:
            raise ChaoxingAPIError("personal group export pagination exceeded 500 pages")
        return {
            "group": selected,
            "count": len(jobs),
            "exports": jobs,
            "verification": f"read {len(jobs)} personal group export jobs through HTTP",
        }

    def create_personal_group_member_export(self, group: str) -> dict[str, Any]:
        selected = self._find_personal_group(group)
        before = self.list_personal_group_exports(selected["bbs_id"])
        before_ids = {job["export_id"] for job in before["exports"]}
        payload = self._personal_group_json_request(
            self._session(),
            "/pc/export/cmem/exportMembers",
            "personal group member export",
            params={"bbsid": selected["bbs_id"]},
            referer=selected["management_url"],
        )
        for attempt in range(10):
            refreshed = self.list_personal_group_exports(selected["bbs_id"])
            created = [job for job in refreshed["exports"] if job["export_id"] not in before_ids]
            if created:
                return {
                    "group": selected,
                    "export": created[0],
                    "server_message": str(payload.get("msg") or ""),
                    "verification": "new member export job appeared in the download center",
                }
            if attempt < 9:
                sleep(1)
        raise ChaoxingAPIError("personal group member export job did not appear after refresh")

    def retry_personal_group_export(self, group: str, export_query: str) -> dict[str, Any]:
        selected = self._find_personal_group(group)
        before = self.list_personal_group_exports(selected["bbs_id"])
        job = self._resolve_personal_group_export_job(before["exports"], export_query)
        if job["status"] != "failed":
            raise ChaoxingAPIError("only failed personal group exports can be retried")
        payload = self._personal_group_json_request(
            self._session(),
            "/pc/statistics/reExport",
            "personal group export retry",
            params={"dataId": job["export_id"]},
            referer=selected["management_url"],
        )
        refreshed = self.list_personal_group_exports(selected["bbs_id"])
        after = self._resolve_personal_group_export_job(refreshed["exports"], job["export_id"])
        if after["status"] == "failed":
            raise ChaoxingAPIError("personal group export remained failed after retry")
        return {
            "group": selected,
            "before": job,
            "export": after,
            "server_message": str(payload.get("msg") or ""),
            "verification": "retried export is no longer failed after refresh",
        }

    def wait_personal_group_export(
        self,
        group: str,
        export_query: str,
        *,
        timeout_seconds: int = 120,
        poll_seconds: int = 2,
    ) -> dict[str, Any]:
        if timeout_seconds < 0 or timeout_seconds > 3600:
            raise ChaoxingAPIError("export wait timeout must be between 0 and 3600 seconds")
        if poll_seconds < 1 or poll_seconds > 60:
            raise ChaoxingAPIError("export poll interval must be between 1 and 60 seconds")
        selected = self._find_personal_group(group)
        started = monotonic()
        while True:
            listing = self.list_personal_group_exports(selected["bbs_id"])
            job = self._resolve_personal_group_export_job(listing["exports"], export_query)
            if job["status"] in {"ready", "failed"}:
                return {
                    "group": selected,
                    "export": job,
                    "elapsed_seconds": round(monotonic() - started, 3),
                    "verification": f"personal group export reached {job['status']} status",
                }
            elapsed = monotonic() - started
            if elapsed >= timeout_seconds:
                raise ChaoxingAPIError(
                    f"personal group export did not finish within {timeout_seconds} seconds"
                )
            sleep(min(poll_seconds, max(0.0, timeout_seconds - elapsed)))

    def cancel_personal_group_export(self, group: str, export_query: str) -> dict[str, Any]:
        selected = self._find_personal_group(group)
        before = self.list_personal_group_exports(selected["bbs_id"])
        job = self._resolve_personal_group_export_job(before["exports"], export_query)
        payload = self._personal_group_json_request(
            self._session(),
            "/pc/statistics/cancelExport",
            "personal group export cancellation",
            params={"dataId": job["export_id"]},
            referer=selected["management_url"],
        )
        remaining = self.list_personal_group_exports(selected["bbs_id"])["exports"]
        if any(item["export_id"] == job["export_id"] for item in remaining):
            raise ChaoxingAPIError("cancelled personal group export remains after refresh")
        return {
            "group": selected,
            "cancelled_export": job,
            "server_message": str(payload.get("msg") or ""),
            "verification": "cancelled export is absent from a fresh download-center read",
        }

    def download_personal_group_export(
        self,
        group: str,
        export_query: str,
        output_path: str | Path,
        *,
        overwrite: bool = False,
        wait_seconds: int = 120,
    ) -> dict[str, Any]:
        selected = self._find_personal_group(group)
        waited = self.wait_personal_group_export(
            selected["bbs_id"], export_query, timeout_seconds=wait_seconds
        )
        job = waited["export"]
        if job["status"] != "ready" or not job["download_url"]:
            raise ChaoxingAPIError("personal group export is not ready for download")
        wrapper_url = job["download_url"]
        wrapper_host = (urlparse(wrapper_url).hostname or "").lower()
        if wrapper_host not in {"sharewh.chaoxing.com", "sharewh1.chaoxing.com"}:
            raise ChaoxingAPIError("personal group export returned an unsafe download host")
        session = self._session()
        try:
            wrapper = session.get(
                wrapper_url,
                headers={"Referer": selected["management_url"]},
                timeout=max(self.timeout, 60),
            )
            wrapper.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"personal group export download failed: {exc}") from exc
        response = wrapper
        wrapper_type = str(wrapper.headers.get("Content-Type") or "").lower()
        if "text/html" in wrapper_type:
            match = re.search(
                r"var\s+downloadUrl\s*=\s*['\"]([^'\"]+)['\"]",
                self._decode(wrapper),
            )
            if not match:
                raise ChaoxingAPIError("personal group export wrapper returned no file URL")
            direct_url = unescape(match.group(1))
            direct_host = (urlparse(direct_url).hostname or "").lower()
            if not direct_host.endswith(".cldisk.com"):
                raise ChaoxingAPIError("personal group export returned an unsafe file host")
            try:
                response = session.get(
                    direct_url,
                    headers={"Referer": wrapper_url},
                    timeout=max(self.timeout, 300),
                    stream=True,
                )
                response.raise_for_status()
            except requests.RequestException as exc:
                raise ChaoxingAPIError(f"personal group export file failed: {exc}") from exc
        content_type = str(response.headers.get("Content-Type") or "").lower()
        if "text/html" in content_type:
            raise ChaoxingAPIError("personal group export returned HTML instead of a file")
        server_name = content_disposition_filename(
            str(response.headers.get("Content-Disposition") or "")
        )
        target = self._resource_download_target(
            output_path,
            suggested_name=server_name or job["file_name"] or f"group-export-{job['export_id']}",
            overwrite=overwrite,
        )
        temporary = target.with_name(target.name + ".part")
        if temporary.exists():
            raise ChaoxingAPIError(f"temporary download target already exists: {temporary}")
        byte_count = 0
        try:
            with temporary.open("wb") as stream:
                for chunk in response.iter_content(chunk_size=1024 * 256):
                    if chunk:
                        stream.write(chunk)
                        byte_count += len(chunk)
            if job["file_size"] and byte_count != job["file_size"]:
                temporary.unlink(missing_ok=True)
                raise ChaoxingAPIError(
                    "personal group export byte count differs from download-center metadata"
                )
            temporary.replace(target)
        except OSError as exc:
            temporary.unlink(missing_ok=True)
            raise ChaoxingAPIError(f"could not save personal group export: {exc}") from exc
        return {
            "group": selected,
            "export": job,
            "output_path": str(target),
            "file_name": target.name,
            "byte_count": byte_count,
            "content_type": content_type,
            "verification": "saved the ready personal group export as a local file",
        }

    @staticmethod
    def _normalize_personal_group_activity(raw: dict[str, Any], index: int = 0) -> dict[str, Any]:
        def integer(value: Any) -> int:
            try:
                return int(value or 0)
            except (TypeError, ValueError):
                return 0

        online_code = integer(raw.get("onlineOrNot"))
        return {
            "index": index,
            "activity_id": str(raw.get("id") or ""),
            "activity_uuid": str(raw.get("uuid") or ""),
            "bbs_id": str(raw.get("bbsid") or ""),
            "title": str(raw.get("title") or "").strip(),
            "status": "online" if online_code == 1 else "offline",
            "online": online_code == 1,
            "online_code": online_code or 2,
            "sort": integer(raw.get("sortValue")),
            "app_link": str(raw.get("activeLinkAPP") or "").strip(),
            "pc_link": str(raw.get("activeLink") or raw.get("activeLinkPC") or "").strip(),
            "app_image_url": str(raw.get("appImgUrl") or raw.get("appBannerUrl") or "").strip(),
            "app_image_width": integer(raw.get("appImgWidth") or raw.get("appBannerWidth")),
            "app_image_height": integer(raw.get("appImgHeight") or raw.get("appBannerHeight")),
            "pc_image_url": str(raw.get("pcImgUrl") or raw.get("pcBannerUrl") or "").strip(),
            "pc_image_width": integer(raw.get("pcImgWidth") or raw.get("pcBannerWidth")),
            "pc_image_height": integer(raw.get("pcImgHeight") or raw.get("pcBannerHeight")),
            "creator_puid": str(raw.get("createrPuid") or ""),
            "module_type": integer(raw.get("moduleType")) or 1,
            "created_at": raw.get("createTime"),
            "updated_at": raw.get("updateTime"),
        }

    @staticmethod
    def _resolve_personal_group_activity(
        activities: list[dict[str, Any]], query: str
    ) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("personal group activity title, UUID, ID, or index is required")
        for key in ("activity_uuid", "activity_id", "index", "title"):
            exact = [
                item
                for item in activities
                if str(item.get(key) or "").strip().lower() == normalized
            ]
            if len(exact) == 1:
                return exact[0]
            if len(exact) > 1:
                raise ChaoxingAPIError(f"multiple personal group activities match: {query}")
        partial = [item for item in activities if normalized in item["title"].lower()]
        if len(partial) == 1:
            return partial[0]
        if not partial:
            raise ChaoxingAPIError(f"personal group activity not found: {query}")
        raise ChaoxingAPIError(f"multiple personal group activities match: {query}")

    def _personal_group_activity_list_for_status(
        self,
        session: requests.Session,
        selected: dict[str, Any],
        online_code: int,
        *,
        max_items: int,
        referer: str,
    ) -> list[dict[str, Any]]:
        activities: list[dict[str, Any]] = []
        last_value = ""
        page_size = min(max(max_items, 1), 1000)
        for _page in range(1, 501):
            params: dict[str, Any] = {
                "bbsid": selected["bbs_id"],
                "onlineOrNot": online_code,
                "moduleType": 1,
                "pageSize": page_size,
                "crossOrigin": "true",
            }
            if last_value:
                params["lastValue"] = last_value
            payload = self._personal_group_json_request(
                session,
                GROUPYD_BASE_URL + "/apis/circle/getCircleActivityList",
                "personal group activity list",
                params=params,
                referer=referer,
                allow_result=True,
            )
            nested = self._personal_group_nested_data(payload, "personal group activity list")
            data = nested if isinstance(nested, dict) else {}
            raw_items = data.get("list") if isinstance(data.get("list"), list) else []
            for raw in raw_items:
                if isinstance(raw, dict):
                    activities.append(
                        self._normalize_personal_group_activity(raw, len(activities) + 1)
                    )
                    if len(activities) >= max_items:
                        return activities
            poff = data.get("poff") if isinstance(data.get("poff"), dict) else {}
            if online_code == 1 or str(poff.get("lastPage") or "0") in {
                "1",
                "true",
                "True",
            }:
                break
            next_value = str(poff.get("lastAuxValue") or poff.get("lastValue") or "")
            if not next_value or next_value == last_value:
                break
            last_value = next_value
        else:
            raise ChaoxingAPIError("personal group activity pagination exceeded 500 pages")
        return activities

    def list_personal_group_activities(
        self,
        group: str,
        *,
        status: str = "all",
        max_items: int = 1000,
    ) -> dict[str, Any]:
        if max_items < 1:
            raise ChaoxingAPIError("max_items must be at least 1")
        normalized_status = status.strip().lower().replace("-", "_")
        status_aliases = {
            "all": "all",
            "全部": "all",
            "online": "online",
            "published": "online",
            "上线": "online",
            "已上线": "online",
            "offline": "offline",
            "draft": "offline",
            "未上线": "offline",
            "下线": "offline",
        }
        normalized_status = status_aliases.get(normalized_status, normalized_status)
        if normalized_status not in {"all", "online", "offline"}:
            raise ChaoxingAPIError("personal group activity status must be all, online, or offline")
        selected = self._find_personal_group(group)
        session, landing = self._personal_groups_context()
        referer = (
            GROUPWEB_BASE_URL
            + "/res/vue/activity/activityManager.html?"
            + urlencode({"bbsid": selected["bbs_id"]})
        )
        online: list[dict[str, Any]] = []
        offline: list[dict[str, Any]] = []
        if normalized_status in {"all", "online"}:
            online = self._personal_group_activity_list_for_status(
                session,
                selected,
                1,
                max_items=max_items,
                referer=referer or landing.url,
            )
        if normalized_status in {"all", "offline"}:
            remaining = (
                max_items if normalized_status == "offline" else max(max_items - len(online), 1)
            )
            offline = self._personal_group_activity_list_for_status(
                session,
                selected,
                2,
                max_items=remaining,
                referer=referer or landing.url,
            )
        activities = [*online, *offline][:max_items]
        for index, item in enumerate(activities, 1):
            item["index"] = index
        return {
            "group": selected,
            "status": normalized_status,
            "count": len(activities),
            "online_count": len(online),
            "offline_count": len(offline),
            "activities": activities,
            "verification": f"read {len(activities)} personal group activities through HTTP",
        }

    @staticmethod
    def _personal_group_activity_form(
        *,
        selected: dict[str, Any],
        title: str,
        online: bool,
        sort_value: int,
        app_link: str,
        pc_link: str,
        app_image_url: str,
        pc_image_url: str,
        app_image_width: int = 0,
        app_image_height: int = 0,
        pc_image_width: int = 0,
        pc_image_height: int = 0,
        activity_id: str = "",
        activity_uuid: str = "",
    ) -> dict[str, Any]:
        form: dict[str, Any] = {
            "title": title,
            "activeLinkAPP": app_link,
            "activeLinkPC": pc_link,
            "appBannerUrl": app_image_url,
            "appBannerHeight": app_image_height or "",
            "appBannerWidth": app_image_width or "",
            "pcBannerUrl": pc_image_url,
            "pcBannerHeight": pc_image_height or "",
            "pcBannerWidth": pc_image_width or "",
            "sortValue": sort_value,
            "onlineOrNot": 1 if online else 2,
            "bbsid": selected["bbs_id"],
            "moduleType": 1,
        }
        if activity_id:
            form["id"] = activity_id
        if activity_uuid:
            form["uuid"] = activity_uuid
        return form

    def _save_personal_group_activity(
        self,
        session: requests.Session,
        form: dict[str, Any],
        *,
        referer: str,
    ) -> dict[str, Any]:
        payload = self._personal_group_json_request(
            session,
            GROUPYD_BASE_URL + "/apis/circle/addOrUpdateCircleActivity",
            "personal group activity save",
            method="POST",
            params={"crossOrigin": "true"},
            data=form,
            referer=referer,
            allow_result=True,
        )
        data = self._personal_group_nested_data(payload, "personal group activity save")
        if not isinstance(data, dict) or not str(data.get("uuid") or ""):
            raise ChaoxingAPIError("personal group activity save returned no activity UUID")
        return data

    def create_personal_group_activity(
        self,
        group: str,
        title: str,
        *,
        online: bool = False,
        app_link: str = "",
        pc_link: str = "",
        app_image_url: str = "",
        pc_image_url: str = "",
        app_image_width: int = 0,
        app_image_height: int = 0,
        pc_image_width: int = 0,
        pc_image_height: int = 0,
    ) -> dict[str, Any]:
        title = title.strip()
        if not title:
            raise ChaoxingAPIError("personal group activity title is required")
        if len(title) > 30:
            raise ChaoxingAPIError("personal group activity title cannot exceed 30 characters")
        if online and (not app_image_url.strip() or not pc_image_url.strip()):
            raise ChaoxingAPIError("online personal group activities require app and PC images")
        dimensions = (
            app_image_width,
            app_image_height,
            pc_image_width,
            pc_image_height,
        )
        if any(value < 0 for value in dimensions):
            raise ChaoxingAPIError("personal group activity image dimensions cannot be negative")
        if online and any(value < 1 for value in dimensions):
            raise ChaoxingAPIError(
                "online personal group activities require app and PC image dimensions"
            )
        selected = self._find_personal_group(group)
        if not selected.get("can_manage"):
            raise ChaoxingAPIError("current account cannot manage activities in this group")
        before = self.list_personal_group_activities(selected["bbs_id"], max_items=10000)
        session, _landing = self._personal_groups_context()
        referer = (
            GROUPWEB_BASE_URL
            + "/res/vue/activity/addActivity.html?"
            + urlencode({"bbsid": selected["bbs_id"]})
        )
        raw = self._save_personal_group_activity(
            session,
            self._personal_group_activity_form(
                selected=selected,
                title=title,
                online=online,
                sort_value=before["online_count"] + 1 if online else 1,
                app_link=app_link.strip(),
                pc_link=pc_link.strip(),
                app_image_url=app_image_url.strip(),
                pc_image_url=pc_image_url.strip(),
                app_image_width=app_image_width,
                app_image_height=app_image_height,
                pc_image_width=pc_image_width,
                pc_image_height=pc_image_height,
            ),
            referer=referer,
        )
        activity_uuid = str(raw.get("uuid") or "")
        refreshed = self.list_personal_group_activities(selected["bbs_id"], max_items=10000)
        created = self._resolve_personal_group_activity(refreshed["activities"], activity_uuid)
        if created["title"] != title or created["online"] is not bool(online):
            raise ChaoxingAPIError("created personal group activity differs after refresh")
        return {
            "group": selected,
            "activity": created,
            "verification": "created personal group activity matched a fresh activity-list read",
        }

    def update_personal_group_activity(
        self,
        group: str,
        activity: str,
        *,
        title: str | None = None,
        app_link: str | None = None,
        pc_link: str | None = None,
        app_image_url: str | None = None,
        pc_image_url: str | None = None,
        app_image_width: int | None = None,
        app_image_height: int | None = None,
        pc_image_width: int | None = None,
        pc_image_height: int | None = None,
    ) -> dict[str, Any]:
        changes = {
            "title": title,
            "app_link": app_link,
            "pc_link": pc_link,
            "app_image_url": app_image_url,
            "pc_image_url": pc_image_url,
            "app_image_width": app_image_width,
            "app_image_height": app_image_height,
            "pc_image_width": pc_image_width,
            "pc_image_height": pc_image_height,
        }
        if all(value is None for value in changes.values()):
            raise ChaoxingAPIError("at least one personal group activity field is required")
        selected = self._find_personal_group(group)
        if not selected.get("can_manage"):
            raise ChaoxingAPIError("current account cannot manage activities in this group")
        listing = self.list_personal_group_activities(selected["bbs_id"], max_items=10000)
        before = self._resolve_personal_group_activity(listing["activities"], activity)
        desired = {**before}
        for key, value in changes.items():
            if value is not None:
                desired[key] = value.strip() if isinstance(value, str) else value
        if not str(desired["title"]).strip():
            raise ChaoxingAPIError("personal group activity title is required")
        if len(str(desired["title"])) > 30:
            raise ChaoxingAPIError("personal group activity title cannot exceed 30 characters")
        if before["online"] and (
            not str(desired["app_image_url"]).strip() or not str(desired["pc_image_url"]).strip()
        ):
            raise ChaoxingAPIError("online personal group activities require app and PC images")
        desired_dimensions = (
            int(desired["app_image_width"] or 0),
            int(desired["app_image_height"] or 0),
            int(desired["pc_image_width"] or 0),
            int(desired["pc_image_height"] or 0),
        )
        if any(value < 0 for value in desired_dimensions):
            raise ChaoxingAPIError("personal group activity image dimensions cannot be negative")
        if before["online"] and any(value < 1 for value in desired_dimensions):
            raise ChaoxingAPIError(
                "online personal group activities require app and PC image dimensions"
            )
        session, _landing = self._personal_groups_context()
        referer = (
            GROUPWEB_BASE_URL
            + "/res/vue/activity/addActivity.html?"
            + urlencode(
                {"bbsid": selected["bbs_id"], "editType": 1, "actType": before["online_code"]}
            )
        )
        self._save_personal_group_activity(
            session,
            self._personal_group_activity_form(
                selected=selected,
                title=str(desired["title"]),
                online=bool(before["online"]),
                sort_value=int(before["sort"]),
                app_link=str(desired["app_link"]),
                pc_link=str(desired["pc_link"]),
                app_image_url=str(desired["app_image_url"]),
                pc_image_url=str(desired["pc_image_url"]),
                app_image_width=int(desired["app_image_width"] or 0),
                app_image_height=int(desired["app_image_height"] or 0),
                pc_image_width=int(desired["pc_image_width"] or 0),
                pc_image_height=int(desired["pc_image_height"] or 0),
                activity_id=before["activity_id"],
                activity_uuid=before["activity_uuid"],
            ),
            referer=referer,
        )
        refreshed = self.list_personal_group_activities(selected["bbs_id"], max_items=10000)
        after = self._resolve_personal_group_activity(
            refreshed["activities"], before["activity_uuid"]
        )
        for key, value in changes.items():
            if value is not None and after[key] != desired[key]:
                raise ChaoxingAPIError(f"personal group activity field {key} differs after refresh")
        return {
            "group": selected,
            "before": before,
            "activity": after,
            "verification": "personal group activity fields matched a fresh list read",
        }

    def set_personal_group_activity_online_status(
        self, group: str, activity: str, online: bool
    ) -> dict[str, Any]:
        selected = self._find_personal_group(group)
        if not selected.get("can_manage"):
            raise ChaoxingAPIError("current account cannot manage activities in this group")
        listing = self.list_personal_group_activities(selected["bbs_id"], max_items=10000)
        before = self._resolve_personal_group_activity(listing["activities"], activity)
        if before["online"] is bool(online):
            return {
                "group": selected,
                "before": before,
                "activity": before,
                "verification": "personal group activity already had the requested status",
            }
        if online and (not before["app_image_url"] or not before["pc_image_url"]):
            raise ChaoxingAPIError("online personal group activities require app and PC images")
        if online and any(
            int(before[field] or 0) < 1
            for field in (
                "app_image_width",
                "app_image_height",
                "pc_image_width",
                "pc_image_height",
            )
        ):
            raise ChaoxingAPIError(
                "online personal group activities require app and PC image dimensions"
            )
        session, _landing = self._personal_groups_context()
        referer = (
            GROUPWEB_BASE_URL
            + "/res/vue/activity/activityManager.html?"
            + urlencode({"bbsid": selected["bbs_id"]})
        )
        self._personal_group_json_request(
            session,
            GROUPYD_BASE_URL + "/apis/circle/checkCircleActivity",
            "personal group activity online-status update",
            params={
                "uuid": before["activity_uuid"],
                "bbsid": selected["bbs_id"],
                "onlineOrNot": before["online_code"],
                "moduleType": 1,
                "crossOrigin": "true",
            },
            referer=referer,
            allow_result=True,
        )
        if online:
            self._personal_group_json_request(
                session,
                GROUPYD_BASE_URL + "/apis/circle/sortCircleActivity",
                "personal group activity append sort",
                params={
                    "bbsid": selected["bbs_id"],
                    "uuids": before["activity_uuid"],
                    "sortValues": listing["online_count"] + 1,
                    "crossOrigin": "true",
                },
                referer=referer,
                allow_result=True,
            )
        refreshed = self.list_personal_group_activities(selected["bbs_id"], max_items=10000)
        after = self._resolve_personal_group_activity(
            refreshed["activities"], before["activity_uuid"]
        )
        if after["online"] is not bool(online):
            raise ChaoxingAPIError("personal group activity status differs after refresh")
        return {
            "group": selected,
            "before": before,
            "activity": after,
            "verification": "personal group activity status matched a fresh list read",
        }

    def reorder_personal_group_activities(
        self, group: str, activities: list[str]
    ) -> dict[str, Any]:
        selected = self._find_personal_group(group)
        if not selected.get("can_manage"):
            raise ChaoxingAPIError("current account cannot reorder activities in this group")
        listing = self.list_personal_group_activities(
            selected["bbs_id"], status="online", max_items=10000
        )
        resolved = [
            self._resolve_personal_group_activity(listing["activities"], query)
            for query in activities
        ]
        requested_ids = [item["activity_uuid"] for item in resolved]
        existing_ids = [item["activity_uuid"] for item in listing["activities"]]
        if len(set(requested_ids)) != len(requested_ids):
            raise ChaoxingAPIError("personal group activity order contains duplicates")
        if set(requested_ids) != set(existing_ids):
            raise ChaoxingAPIError(
                "personal group activity order must contain every online activity exactly once"
            )
        if not requested_ids:
            return {
                "group": selected,
                "activities": [],
                "verification": "personal group had no online activities to reorder",
            }
        session, _landing = self._personal_groups_context()
        referer = (
            GROUPWEB_BASE_URL
            + "/res/vue/activity/activityManager.html?"
            + urlencode({"bbsid": selected["bbs_id"]})
        )
        self._personal_group_json_request(
            session,
            GROUPYD_BASE_URL + "/apis/circle/sortCircleActivity",
            "personal group activity reorder",
            params={
                "bbsid": selected["bbs_id"],
                "uuids": ",".join(requested_ids),
                "sortValues": ",".join(str(index) for index in range(1, len(requested_ids) + 1)),
                "crossOrigin": "true",
            },
            referer=referer,
            allow_result=True,
        )
        refreshed = self.list_personal_group_activities(
            selected["bbs_id"], status="online", max_items=10000
        )["activities"]
        if [item["activity_uuid"] for item in refreshed] != requested_ids:
            raise ChaoxingAPIError("personal group activity order differs after refresh")
        return {
            "group": selected,
            "activities": refreshed,
            "verification": "personal group activity order matched a fresh online-list read",
        }

    def delete_personal_group_activity(self, group: str, activity: str) -> dict[str, Any]:
        selected = self._find_personal_group(group)
        if not selected.get("can_manage"):
            raise ChaoxingAPIError("current account cannot delete activities in this group")
        listing = self.list_personal_group_activities(selected["bbs_id"], max_items=10000)
        before = self._resolve_personal_group_activity(listing["activities"], activity)
        session, _landing = self._personal_groups_context()
        referer = (
            GROUPWEB_BASE_URL
            + "/res/vue/activity/activityManager.html?"
            + urlencode({"bbsid": selected["bbs_id"]})
        )
        self._personal_group_json_request(
            session,
            GROUPYD_BASE_URL + "/apis/circle/deleteActivity",
            "personal group activity deletion",
            params={
                "bbsid": selected["bbs_id"],
                "uuid": before["activity_uuid"],
                "crossOrigin": "true",
            },
            referer=referer,
            allow_result=True,
        )
        remaining = self.list_personal_group_activities(selected["bbs_id"], max_items=10000)[
            "activities"
        ]
        if any(item["activity_uuid"] == before["activity_uuid"] for item in remaining):
            raise ChaoxingAPIError("deleted personal group activity remains after refresh")
        return {
            "group": selected,
            "deleted": before,
            "verification": "deleted personal group activity is absent from a fresh list read",
        }

    @staticmethod
    def _local_image_dimensions(path: Path) -> tuple[int, int]:
        with path.open("rb") as stream:
            header = stream.read(32)
            if header.startswith(b"\x89PNG\r\n\x1a\n") and len(header) >= 24:
                return (
                    int.from_bytes(header[16:20], "big"),
                    int.from_bytes(header[20:24], "big"),
                )
            if header[:6] in {b"GIF87a", b"GIF89a"} and len(header) >= 10:
                return (
                    int.from_bytes(header[6:8], "little"),
                    int.from_bytes(header[8:10], "little"),
                )
            if header.startswith(b"BM") and len(header) >= 26:
                return (
                    abs(int.from_bytes(header[18:22], "little", signed=True)),
                    abs(int.from_bytes(header[22:26], "little", signed=True)),
                )
            if header.startswith(b"RIFF") and header[8:12] == b"WEBP":
                if header[12:16] == b"VP8X" and len(header) >= 30:
                    return (
                        int.from_bytes(header[24:27], "little") + 1,
                        int.from_bytes(header[27:30], "little") + 1,
                    )
                if header[12:16] == b"VP8L" and len(header) >= 25:
                    bits = int.from_bytes(header[21:25], "little")
                    return (bits & 0x3FFF) + 1, ((bits >> 14) & 0x3FFF) + 1
                if header[12:16] == b"VP8 " and header[23:26] == b"\x9d\x01\x2a":
                    return (
                        int.from_bytes(header[26:28], "little") & 0x3FFF,
                        int.from_bytes(header[28:30], "little") & 0x3FFF,
                    )
            if not header.startswith(b"\xff\xd8"):
                return 0, 0
            stream.seek(2)
            start_of_frame = {
                0xC0,
                0xC1,
                0xC2,
                0xC3,
                0xC5,
                0xC6,
                0xC7,
                0xC9,
                0xCA,
                0xCB,
                0xCD,
                0xCE,
                0xCF,
            }
            while True:
                byte = stream.read(1)
                if not byte:
                    return 0, 0
                if byte != b"\xff":
                    continue
                while byte == b"\xff":
                    byte = stream.read(1)
                if not byte:
                    return 0, 0
                marker = byte[0]
                if marker in {0xD8, 0xD9}:
                    continue
                length_bytes = stream.read(2)
                if len(length_bytes) != 2:
                    return 0, 0
                segment_length = int.from_bytes(length_bytes, "big")
                if segment_length < 2:
                    return 0, 0
                if marker in start_of_frame:
                    frame = stream.read(5)
                    if len(frame) != 5:
                        return 0, 0
                    return (
                        int.from_bytes(frame[3:5], "big"),
                        int.from_bytes(frame[1:3], "big"),
                    )
                stream.seek(segment_length - 2, 1)

    def upload_personal_group_activity_image(self, file: str | Path) -> dict[str, Any]:
        path = Path(file).expanduser().resolve()
        if not path.is_file():
            raise ChaoxingAPIError(f"activity image does not exist: {path}")
        content_type = mimetypes.guess_type(path.name)[0] or ""
        if not content_type.startswith("image/"):
            raise ChaoxingAPIError("personal group activity banners must be image files")
        try:
            width, height = self._local_image_dimensions(path)
        except OSError as exc:
            raise ChaoxingAPIError(f"cannot read activity image: {exc}") from exc
        session, landing = self._personal_groups_context()
        authorization = self._personal_group_json_request(
            session,
            NOTE_BASE_URL + "/pc/files/getYunPanUploadUrl",
            "personal group activity image upload authorization",
            params={"from": "group", "CrossOrigin": "true"},
            referer=landing.url,
            allow_result=True,
        )
        upload_url = str(authorization.get("data") or "")
        parsed = urlparse(upload_url)
        if (
            parsed.scheme != "https"
            or not parsed.hostname
            or not parsed.hostname.lower().endswith(".chaoxing.com")
        ):
            raise ChaoxingAPIError("Chaoxing returned an unexpected activity image upload URL")
        try:
            with path.open("rb") as stream:
                response = session.post(
                    upload_url,
                    data={
                        "name": path.name,
                        "lastModified": int(path.stat().st_mtime * 1000),
                        "size": path.stat().st_size,
                        "type": content_type,
                        "uploadtype": "normal",
                    },
                    files={"file": (path.name, stream, content_type)},
                    headers={"Referer": landing.url},
                    timeout=max(self.timeout, 120),
                )
            response.raise_for_status()
        except OSError as exc:
            raise ChaoxingAPIError(f"cannot read activity image: {exc}") from exc
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"personal group activity image upload failed: {exc}") from exc
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError(
                "personal group activity image upload returned invalid JSON"
            ) from exc
        if not isinstance(payload, dict) or payload.get("result") not in {True, "1"}:
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(
                str(message or "personal group activity image upload was rejected")
            )
        data = payload.get("data") if isinstance(payload.get("data"), dict) else {}
        preview_url = str(data.get("previewUrl") or "")
        if not preview_url:
            raise ChaoxingAPIError("personal group activity image upload returned no preview URL")
        return {
            "file": str(path),
            "file_name": path.name,
            "file_size": path.stat().st_size,
            "content_type": content_type,
            "width": width,
            "height": height,
            "preview_url": preview_url,
            "verification": "Chaoxing returned a preview URL for the uploaded activity image",
        }

    def _set_personal_group_logo_url(
        self,
        group: str,
        logo_url: str,
    ) -> dict[str, Any]:
        logo_url = str(logo_url or "").strip()
        parsed = urlparse(logo_url)
        if parsed.scheme != "https" or not parsed.hostname:
            raise ChaoxingAPIError("personal group logo must use a valid HTTPS URL")
        before = self._find_personal_group(group)
        if not self._personal_group_can(before, "modifyShowPic"):
            raise ChaoxingAPIError("current account cannot modify this personal group logo")
        payload = self._personal_group_json_request(
            self._session(),
            f"/pc/circle/manage/{quote(before['bbs_id'], safe='')}/logoUpload",
            "personal group logo update",
            params={"newLogo": logo_url, "type": "logo"},
            referer=before["management_url"],
        )
        after = self._find_personal_group(before["bbs_id"])
        if not after["logo_url"]:
            raise ChaoxingAPIError("personal group logo was empty after refresh")
        if before["logo_url"] != logo_url and after["logo_url"] == before["logo_url"]:
            raise ChaoxingAPIError("personal group logo did not change after refresh")
        return {
            "before": before,
            "group": after,
            "requested_logo_url": logo_url,
            "server_message": str(payload.get("msg") or ""),
            "verification": "personal group logo changed in a fresh all-group read",
        }

    def update_personal_group_logo(
        self,
        group: str,
        file: str | Path,
    ) -> dict[str, Any]:
        uploaded = self.upload_personal_group_activity_image(file)
        updated = self._set_personal_group_logo_url(group, uploaded["preview_url"])
        return {
            **updated,
            "upload": uploaded,
            "verification": (
                "Chaoxing accepted the image upload and the refreshed personal group logo changed"
            ),
        }

    def set_personal_group_top_status(self, group: str, top: bool) -> dict[str, Any]:
        before = self._find_personal_group(group)
        session, landing = self._personal_groups_context()
        self._personal_group_json_request(
            session,
            "/pc/circle/setOrCancelTop",
            "personal group top status",
            params={"operate": "setTop" if top else "cancelTop", "bbsid": before["bbs_id"]},
            referer=landing.url,
        )
        after = self._find_personal_group(before["bbs_id"])
        if after["is_top"] is not bool(top):
            raise ChaoxingAPIError("personal group top status differs after refresh")
        return {
            "before": before,
            "group": after,
            "verification": f"personal group top status is {bool(top)} after refresh",
        }

    def move_personal_group(self, group: str, destination_folder: str) -> dict[str, Any]:
        before = self._find_personal_group(group)
        destination_id = self._personal_group_folder_id(destination_folder)
        session, landing = self._personal_groups_context()
        self._personal_group_json_request(
            session,
            "/pc/circle/moveCircleToFolder",
            "personal group move",
            params={"bbsid": before["bbs_id"], "toFolderId": destination_id},
            referer=landing.url,
        )
        after = self._find_personal_group(before["bbs_id"])
        if after["folder_id"] != destination_id:
            raise ChaoxingAPIError("personal group folder differs after refresh")
        return {
            "before": before,
            "group": after,
            "verification": "personal group destination folder matched a fresh all-folder read",
        }

    def quit_personal_group(self, group: str) -> dict[str, Any]:
        selected = self._find_personal_group(group)
        if selected["is_creator"]:
            raise ChaoxingAPIError("a personal group creator must transfer or dismiss the group")
        if not selected["can_quit"]:
            raise ChaoxingAPIError("current account cannot quit this personal group")
        session, landing = self._personal_groups_context()
        self._personal_group_json_request(
            session,
            "/pc/cmem/quitCircle",
            "personal group quit",
            params={"bbsid": selected["bbs_id"]},
            referer=landing.url,
        )
        remaining = self._all_personal_groups()
        if any(item["bbs_id"] == selected["bbs_id"] for item in remaining):
            raise ChaoxingAPIError("quit personal group still appears after refresh")
        return {
            "quit": selected,
            "verification": "quit personal group is absent from a fresh all-folder read",
        }

    def dismiss_personal_group(self, group: str) -> dict[str, Any]:
        selected = self._find_personal_group(group)
        permissions = selected.get("permissions")
        if not isinstance(permissions, dict):
            permissions = {}
        if not selected["is_creator"] and str(permissions.get("dismiss") or "0") != "1":
            raise ChaoxingAPIError("current account cannot dismiss this personal group")
        session, landing = self._personal_groups_context()
        self._personal_group_json_request(
            session,
            "/pc/cmem/quitCircle",
            "personal group dismissal",
            params={"bbsid": selected["bbs_id"]},
            referer=landing.url,
        )
        remaining = self._all_personal_groups()
        if any(item["bbs_id"] == selected["bbs_id"] for item in remaining):
            raise ChaoxingAPIError("dismissed personal group still appears after refresh")
        return {
            "dismissed": selected,
            "verification": "dismissed personal group is absent from a fresh all-folder read",
        }

    @staticmethod
    def _normalize_personal_group_member(raw: dict[str, Any], index: int = 0) -> dict[str, Any]:
        try:
            manager_level = int(raw.get("manager") or 0)
        except (TypeError, ValueError):
            manager_level = 0
        role = "creator" if manager_level == 5 else "manager" if manager_level == 1 else "member"
        return {
            "index": index,
            "member_id": str(raw.get("id") or ""),
            "circle_id": str(raw.get("circleId") or ""),
            "department_id": str(raw.get("deptId") or ""),
            "folder_id": str(raw.get("folderId") or ""),
            "puid": str(raw.get("puid") or ""),
            "puid_encoded": str(raw.get("puidEnc") or ""),
            "name": str(raw.get("name") or raw.get("personName") or "").strip(),
            "person_name": str(raw.get("personName") or raw.get("name") or "").strip(),
            "picture_url": str(raw.get("pic") or ""),
            "joined_at": raw.get("joinTime"),
            "manager_level": manager_level,
            "role": role,
            "is_creator": manager_level == 5,
            "is_manager": manager_level == 1,
            "is_banned": str(raw.get("isBanned") or "0") == "1",
        }

    @staticmethod
    def _resolve_personal_group_member(members: list[dict[str, Any]], query: str) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("personal group member name, PUID, ID, or index is required")
        for key in ("member_id", "puid", "puid_encoded", "index", "name", "person_name"):
            exact = [
                member
                for member in members
                if str(member.get(key) or "").strip().lower() == normalized
            ]
            if len(exact) == 1:
                return exact[0]
            if len(exact) > 1:
                raise ChaoxingAPIError(f"multiple personal group members match: {query}")
        partial = [
            member
            for member in members
            if normalized in str(member.get("name") or member.get("person_name") or "").lower()
        ]
        if len(partial) == 1:
            return partial[0]
        if not partial:
            raise ChaoxingAPIError(f"personal group member not found: {query}")
        candidates = ", ".join(
            f"{member['index']}. {member['name']} ({member['puid'] or member['member_id']})"
            for member in partial
        )
        raise ChaoxingAPIError(f"multiple personal group members match: {candidates}")

    def list_personal_group_members(
        self,
        group: str,
        *,
        search: str = "",
    ) -> dict[str, Any]:
        selected = self._find_personal_group(group)
        session, landing = self._personal_groups_context()
        members: list[dict[str, Any]] = []
        last_id = ""
        last_join_time = ""
        seen_markers: set[tuple[str, str]] = set()
        page = 1
        while page <= 500:
            payload = self._personal_group_json_request(
                session,
                f"/pc/cmem/{quote(selected['bbs_id'], safe='')}/getCircleMember",
                "personal group member list",
                params={
                    "kw": search.strip(),
                    "page": page,
                    "pageSize": 20,
                    "lastId": last_id,
                    "lastJoinTime": last_join_time,
                },
                referer=selected["management_url"] or landing.url,
            )
            datas = payload.get("datas")
            if not isinstance(datas, dict):
                break
            raw_members = datas.get("list")
            batch = raw_members if isinstance(raw_members, list) else []
            members.extend(
                self._normalize_personal_group_member(raw, len(members) + 1)
                for raw in batch
                if isinstance(raw, dict)
            )
            if datas.get("lastPage") in {True, "1"} or not batch:
                break
            marker = (
                str(datas.get("lastId") or ""),
                str(datas.get("lastJoinTime") or ""),
            )
            if marker in seen_markers or marker == (last_id, last_join_time):
                raise ChaoxingAPIError("personal group member pagination did not advance")
            seen_markers.add(marker)
            last_id, last_join_time = marker
            page += 1
        else:
            raise ChaoxingAPIError("personal group member pagination exceeded 500 pages")
        return {
            "group": selected,
            "search": search.strip(),
            "count": len(members),
            "members": members,
            "verification": f"read {len(members)} personal group members through HTTP",
        }

    def read_personal_group_bulk_import_status(self, group: str) -> dict[str, Any]:
        selected = self._find_personal_group(group)
        session, landing = self._personal_groups_context()
        try:
            response = session.get(
                selected["management_url"],
                headers={"Referer": landing.url},
                timeout=max(self.timeout, 60),
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"personal group bulk-import status failed: {exc}") from exc
        html = self._decode(response)
        context = parse_personal_group_manage_context(html)
        detailed = self._normalize_personal_group(context["group"], selected["index"])
        if detailed["bbs_id"] != selected["bbs_id"]:
            raise ChaoxingAPIError("personal group bulk-import page returned a different group")
        template_match = re.search(
            r"<a\b[^>]*href=['\"]([^'\"]+)['\"][^>]*>\s*下载模板\s*</a>",
            html,
            flags=re.IGNORECASE,
        )
        template_url = (
            unescape(urljoin(response.url, template_match.group(1))) if template_match else ""
        )
        if template_url:
            parsed = urlparse(template_url)
            hostname = (parsed.hostname or "").lower()
            if parsed.scheme != "https" or not (
                hostname == "xuexi365.com"
                or hostname.endswith(".xuexi365.com")
                or hostname == "chaoxing.com"
                or hostname.endswith(".chaoxing.com")
            ):
                raise ChaoxingAPIError("personal group bulk-import template URL is unsafe")
        used = int(detailed["bulk_import_used_today"])
        started_at = detailed["bulk_import_started_at"]
        expires_at = ""
        try:
            started_milliseconds = int(started_at or 0)
        except (TypeError, ValueError):
            started_milliseconds = 0
        if started_milliseconds > 0:
            expires_at = (
                datetime.fromtimestamp(started_milliseconds / 1000, tz=UTC) + timedelta(days=30)
            ).isoformat()
        return {
            "group": detailed,
            "enabled": bool(detailed["bulk_import_enabled"]),
            "is_creator": bool(detailed["is_creator"]),
            "used_today": used,
            "daily_limit": 3,
            "remaining_today": max(0, 3 - used),
            "effective_days": int(detailed["bulk_import_effective_days"]),
            "started_at": started_at,
            "expires_at": expires_at,
            "template_url": template_url,
            "verification": "read bulk-import flags, quota, and template URL from management HTML",
        }

    @staticmethod
    def _parse_personal_group_modules(html: str) -> list[dict[str, Any]]:
        container_match = re.search(
            r"<div\b[^>]*class=['\"][^'\"]*\bcenterConfiguration\b[^'\"]*['\"][^>]*>"
            r"([\s\S]*?)(?=<div\b[^>]*class=['\"][^'\"]*\bpopBottom\b)",
            html,
            flags=re.IGNORECASE,
        )
        configuration_html = container_match.group(1) if container_match else ""
        modules: list[dict[str, Any]] = [
            {
                "type_id": 1,
                "name": "视频",
                "enabled": True,
                "configurable": False,
            }
        ]
        seen = {1}
        for match in re.finditer(
            r"<input\b[^>]*\bdata-type=['\"]?(\d+)['\"]?[^>]*>",
            configuration_html,
            flags=re.IGNORECASE,
        ):
            type_id = int(match.group(1))
            if type_id in seen:
                continue
            seen.add(type_id)
            block_start = configuration_html.rfind("<div", 0, match.start())
            block_end = configuration_html.find("</div>", match.end())
            block = (
                configuration_html[block_start : block_end + 6]
                if block_start >= 0 and block_end >= 0
                else ""
            )
            name = html_text(block)
            modules.append(
                {
                    "type_id": type_id,
                    "name": name,
                    "enabled": bool(re.search(r"\bchecked\b", match.group(0), re.IGNORECASE)),
                    "configurable": True,
                }
            )
        modules.sort(key=lambda item: item["type_id"])
        return modules

    def list_personal_group_modules(self, group: str) -> dict[str, Any]:
        selected = self._find_personal_group(group)
        session, landing = self._personal_groups_context()
        try:
            response = session.get(
                selected["management_url"],
                headers={"Referer": landing.url},
                timeout=max(self.timeout, 60),
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"personal group module configuration failed: {exc}") from exc
        context = parse_personal_group_manage_context(self._decode(response))
        detailed = self._normalize_personal_group(context["group"], selected["index"])
        if detailed["bbs_id"] != selected["bbs_id"]:
            raise ChaoxingAPIError("personal group module page returned a different group")
        modules = self._parse_personal_group_modules(self._decode(response))
        configurable = [item for item in modules if item["configurable"]]
        return {
            "group": detailed,
            "count": len(modules),
            "configurable_count": len(configurable),
            "configuration_available": bool(configurable),
            "modules": modules,
            "enabled_type_ids": [item["type_id"] for item in modules if item["enabled"]],
            "verification": (
                f"read the mandatory video module and {len(configurable)} configurable modules "
                "from management HTML"
            ),
        }

    def update_personal_group_modules(
        self, group: str, enabled_type_ids: list[int | str]
    ) -> dict[str, Any]:
        before = self.list_personal_group_modules(group)
        selected = before["group"]
        if not self._personal_group_can(selected, "showCircleSet"):
            raise ChaoxingAPIError("current account cannot configure modules in this group")
        if not before["configuration_available"]:
            raise ChaoxingAPIError(
                "personal group page exposes no configurable modules for this group type"
            )
        normalized: set[int] = {1}
        for value in enabled_type_ids:
            try:
                normalized.add(int(value))
            except (TypeError, ValueError) as exc:
                raise ChaoxingAPIError("personal group module type IDs must be integers") from exc
        available = {item["type_id"] for item in before["modules"]}
        unknown = sorted(normalized - available)
        if unknown:
            raise ChaoxingAPIError(
                "personal group page does not expose module types: "
                + ", ".join(str(item) for item in unknown)
            )
        desired = sorted(normalized)
        self._personal_group_json_request(
            self._session(),
            "/pc/circle/manage/setExtendItem",
            "personal group module configuration update",
            params={"bbsid": selected["bbs_id"], "types": ",".join(map(str, desired))},
            referer=selected["management_url"],
            allow_result=True,
        )
        after = self.list_personal_group_modules(selected["bbs_id"])
        if sorted(after["enabled_type_ids"]) != desired:
            raise ChaoxingAPIError("personal group module configuration differs after refresh")
        return {
            "before": before,
            **after,
            "verification": "enabled module type IDs matched a fresh management-page read",
        }

    def download_personal_group_bulk_import_template(
        self,
        group: str,
        output_path: str | Path,
        *,
        overwrite: bool = False,
    ) -> dict[str, Any]:
        status = self.read_personal_group_bulk_import_status(group)
        template_url = status["template_url"]
        if not template_url:
            raise ChaoxingAPIError("personal group page returned no bulk-import template URL")
        session = self._session()
        try:
            response = session.get(
                template_url,
                headers={"Referer": status["group"]["management_url"]},
                timeout=max(self.timeout, 300),
                stream=True,
                allow_redirects=True,
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(
                f"personal group bulk-import template download failed: {exc}"
            ) from exc
        content_type = str(response.headers.get("Content-Type") or "").lower()
        if "text/html" in content_type:
            raise ChaoxingAPIError("personal group bulk-import template returned HTML")
        target = self._resource_download_target(
            output_path,
            suggested_name=(
                content_disposition_filename(str(response.headers.get("Content-Disposition") or ""))
                or "学习通小组成员批量导入模板.xlsx"
            ),
            overwrite=overwrite,
        )
        temporary = target.with_name(target.name + ".part")
        if temporary.exists():
            raise ChaoxingAPIError(f"temporary download target already exists: {temporary}")
        byte_count = 0
        try:
            with temporary.open("wb") as stream:
                for chunk in response.iter_content(chunk_size=1024 * 256):
                    if chunk:
                        stream.write(chunk)
                        byte_count += len(chunk)
            if not zipfile.is_zipfile(temporary):
                raise ChaoxingAPIError("downloaded bulk-import template is not a valid XLSX file")
            with zipfile.ZipFile(temporary) as workbook:
                if "xl/workbook.xml" not in workbook.namelist():
                    raise ChaoxingAPIError(
                        "downloaded bulk-import template has no XLSX workbook structure"
                    )
            temporary.replace(target)
        except (OSError, zipfile.BadZipFile) as exc:
            raise ChaoxingAPIError(
                f"could not save personal group bulk-import template: {exc}"
            ) from exc
        finally:
            temporary.unlink(missing_ok=True)
        return {
            "group": status["group"],
            "output_path": str(target),
            "file_name": target.name,
            "byte_count": byte_count,
            "content_type": content_type,
            "verification": "saved and opened the downloaded XLSX template structure",
        }

    def bulk_import_personal_group_members(
        self,
        group: str,
        file: str | Path,
    ) -> dict[str, Any]:
        path = Path(file).expanduser().resolve()
        if not path.is_file():
            raise ChaoxingAPIError(f"personal group bulk-import file not found: {path}")
        if path.suffix.lower() != ".xlsx" or not zipfile.is_zipfile(path):
            raise ChaoxingAPIError("personal group bulk import requires a valid .xlsx file")
        with zipfile.ZipFile(path) as workbook:
            if "xl/workbook.xml" not in workbook.namelist():
                raise ChaoxingAPIError("personal group bulk-import file has no XLSX workbook")
        status = self.read_personal_group_bulk_import_status(group)
        selected = status["group"]
        if not status["enabled"]:
            raise ChaoxingAPIError("personal group bulk member import is not enabled")
        if not status["is_creator"]:
            raise ChaoxingAPIError("only the personal group creator can bulk import members")
        if status["remaining_today"] <= 0:
            raise ChaoxingAPIError("personal group bulk-import daily quota is exhausted")
        before = self.list_personal_group_members(selected["bbs_id"])
        session, landing = self._personal_groups_context()
        self._personal_group_json_request(
            session,
            "/pc/circle/manage/bulkImportnumber",
            "personal group bulk-import quota consumption",
            method="POST",
            params={"bbsid": selected["bbs_id"]},
            referer=selected["management_url"] or landing.url,
            allow_result=True,
        )
        try:
            with path.open("rb") as stream:
                response = session.post(
                    GROUPWEB_BASE_URL + "/pc/circle/manage/importCircleMember",
                    data={"bbsid": selected["bbs_id"]},
                    files={
                        "file": (
                            path.name,
                            stream,
                            "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                        )
                    },
                    headers={"Referer": selected["management_url"] or landing.url},
                    timeout=max(self.timeout, 300),
                )
                response.raise_for_status()
        except (OSError, requests.RequestException) as exc:
            raise ChaoxingAPIError(f"personal group bulk member import failed: {exc}") from exc
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError(
                "personal group bulk member import returned invalid JSON"
            ) from exc
        if not isinstance(payload, dict) or payload.get("result") not in {True, "1"}:
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "personal group bulk member import was rejected"))
        after = self.list_personal_group_members(selected["bbs_id"])
        before_ids = {item["member_id"] or item["puid"] for item in before["members"]}
        added = [
            item
            for item in after["members"]
            if (item["member_id"] or item["puid"]) not in before_ids
        ]
        refreshed_status = self.read_personal_group_bulk_import_status(selected["bbs_id"])
        return {
            "group": selected,
            "file": str(path),
            "server_message": str(payload.get("msg") or ""),
            "member_count_before": before["count"],
            "member_count_after": after["count"],
            "added_count": len(added),
            "added_members": added,
            "quota": {
                "used_today": refreshed_status["used_today"],
                "remaining_today": refreshed_status["remaining_today"],
                "daily_limit": refreshed_status["daily_limit"],
            },
            "verification": "server accepted the XLSX and the member list and quota were refreshed",
        }

    def read_personal_group_member(self, group: str, member: str) -> dict[str, Any]:
        listing = self.list_personal_group_members(group)
        selected = self._resolve_personal_group_member(listing["members"], member)
        return {
            "group": listing["group"],
            "member": selected,
            "verification": (
                "read personal group member "
                f"{selected['puid'] or selected['member_id']} through HTTP"
            ),
        }

    @staticmethod
    def _normalize_personal_group_member_source(
        raw: dict[str, Any], source_type: str, index: int
    ) -> dict[str, Any]:
        return {
            "index": index,
            "source_type": source_type,
            "source_id": str(raw.get("id") or ""),
            "bbs_id": str(raw.get("bbsid") or ""),
            "parent_id": str(raw.get("pid") if raw.get("pid") is not None else ""),
            "fid": str(raw.get("fid") or ""),
            "name": str(raw.get("name") or "").strip(),
            "member_count": int(raw.get("mem_count") or raw.get("memCount") or 0),
        }

    def list_personal_group_member_sources(self, group: str) -> dict[str, Any]:
        selected = self._find_personal_group(group)
        if not self._personal_group_can(selected, "addMem"):
            raise ChaoxingAPIError("current account cannot add members to this personal group")
        session, landing = self._personal_groups_context()
        circle_payload = self._personal_group_json_request(
            session,
            "/pc/cmem/getCamType",
            "personal group member source list",
            params={"camType": "circle", "camTid": "0", "fid": ""},
            referer=selected["management_url"] or landing.url,
        )
        unit_payload = self._personal_group_json_request(
            session,
            "/pc/cmem/getCamType",
            "personal group unit source list",
            params={"camType": "unit_list"},
            referer=selected["management_url"] or landing.url,
            allow_result=True,
        )
        raw_circles = circle_payload.get("datas")
        raw_units = unit_payload.get("msg")
        if not isinstance(raw_units, list):
            raw_units = unit_payload.get("data")
        circle_sources = [
            self._normalize_personal_group_member_source(raw, "circle", index)
            for index, raw in enumerate(raw_circles if isinstance(raw_circles, list) else [], 1)
            if isinstance(raw, dict)
        ]
        unit_sources = [
            self._normalize_personal_group_member_source(raw, "unit", index)
            for index, raw in enumerate(raw_units if isinstance(raw_units, list) else [], 1)
            if isinstance(raw, dict)
        ]
        return {
            "group": selected,
            "circle_sources": circle_sources,
            "unit_sources": unit_sources,
            "count": len(circle_sources) + len(unit_sources),
            "verification": "read available group-member sources through HTTP",
        }

    @staticmethod
    def _normalize_personal_group_member_candidate(
        raw: dict[str, Any], index: int
    ) -> dict[str, Any]:
        return {
            "index": index,
            "candidate_id": str(raw.get("id") or ""),
            "puid": str(raw.get("puid") or ""),
            "name": str(raw.get("name") or raw.get("personName") or "").strip(),
            "picture_url": str(raw.get("pic") or ""),
            "already_member": bool(raw.get("hasJoinCircle")),
        }

    def list_personal_group_member_candidates(
        self,
        group: str,
        *,
        source_type: str,
        source: str,
        fid: str = "",
        search: str = "",
        account_type: int = 0,
    ) -> dict[str, Any]:
        selected = self._find_personal_group(group)
        if not self._personal_group_can(selected, "addMem"):
            raise ChaoxingAPIError("current account cannot add members to this personal group")
        normalized_type = source_type.strip().lower()
        if normalized_type not in {"circle", "unit", "ibuild"}:
            raise ChaoxingAPIError("member source type must be circle, unit, or ibuild")
        source_id = str(source or "").strip()
        if not source_id:
            raise ChaoxingAPIError("personal group member source ID is required")
        if account_type not in {0, 1}:
            raise ChaoxingAPIError("member account type must be 0 or 1")
        session, landing = self._personal_groups_context()
        candidates: list[dict[str, Any]] = []
        page: int | str = "" if normalized_type == "circle" else 1
        seen_offsets: set[str] = set()
        while len(seen_offsets) <= 500:
            payload = self._personal_group_json_request(
                session,
                f"/pc/cmem/{normalized_type}/{quote(source_id, safe='')}/getCamTypeMember",
                "personal group member candidate list",
                params={
                    "fid": fid.strip(),
                    "kw": search.strip(),
                    "page": page,
                    "pageSize": 60,
                    "circleId": selected["group_id"],
                    "type": account_type,
                },
                referer=selected["management_url"] or landing.url,
                allow_result=True,
                allow_null=True,
            )
            raw_candidates = (
                payload.get("data") if normalized_type == "circle" else payload.get("msg")
            )
            batch = raw_candidates if isinstance(raw_candidates, list) else []
            candidates.extend(
                self._normalize_personal_group_member_candidate(raw, len(candidates) + 1)
                for raw in batch
                if isinstance(raw, dict)
            )
            if len(batch) < 60:
                break
            if normalized_type == "circle":
                next_page = str(batch[-1].get("id") or "") if isinstance(batch[-1], dict) else ""
            else:
                next_page = int(page) + 1
            marker = str(next_page)
            if not marker or marker in seen_offsets or marker == str(page):
                raise ChaoxingAPIError("personal group candidate pagination did not advance")
            seen_offsets.add(marker)
            page = next_page
        else:
            raise ChaoxingAPIError("personal group candidate pagination exceeded 500 pages")
        return {
            "group": selected,
            "source_type": normalized_type,
            "source_id": source_id,
            "fid": fid.strip(),
            "search": search.strip(),
            "account_type": account_type,
            "count": len(candidates),
            "candidates": candidates,
            "verification": f"read {len(candidates)} addable member candidates through HTTP",
        }

    def _personal_group_account_puid(self, group: str) -> str:
        return str(self.read_personal_group(group)["account"].get("puid") or "")

    def read_personal_group_member_permissions(
        self,
        group: str,
        member: str,
    ) -> dict[str, Any]:
        selected_group = self._find_personal_group(group)
        if not self._personal_group_can(selected_group, "addManager"):
            raise ChaoxingAPIError("current account cannot read manager permissions in this group")
        selected_member = self.read_personal_group_member(selected_group["bbs_id"], member)[
            "member"
        ]
        if not selected_member["is_manager"]:
            raise ChaoxingAPIError("personal group member is not a manager")
        current_puid = self._personal_group_account_puid(selected_group["bbs_id"])
        session, landing = self._personal_groups_context()
        payload = self._personal_group_json_request(
            session,
            f"/pc/circle/manage/{quote(selected_group['bbs_id'], safe='')}/getGroupAuthority",
            "personal group manager permission read",
            params={
                "bbsid": selected_group["bbs_id"],
                "mypuid": current_puid,
                "puid": selected_member["puid"],
            },
            referer=selected_group["management_url"] or landing.url,
        )
        datas = payload.get("datas")
        raw_authority: Any = datas.get("authority") if isinstance(datas, dict) else {}
        if isinstance(raw_authority, str):
            try:
                raw_authority = json.loads(raw_authority or "{}")
            except json.JSONDecodeError as exc:
                raise ChaoxingAPIError(
                    "personal group manager permissions contain invalid JSON"
                ) from exc
        if not isinstance(raw_authority, dict):
            raw_authority = {}
        permissions = {
            field: self._personal_group_boolean(raw_authority.get(field))
            for field in PERSONAL_GROUP_MANAGER_AUTHORITY_FIELDS
        }
        return {
            "group": selected_group,
            "member": selected_member,
            "permissions": permissions,
            "verification": "read personal group manager permissions through HTTP",
        }

    def update_personal_group_member_permissions(
        self,
        group: str,
        member: str,
        changes: dict[str, Any],
    ) -> dict[str, Any]:
        if not isinstance(changes, dict) or not changes:
            raise ChaoxingAPIError("at least one manager permission change is required")
        unknown = sorted(set(changes) - set(PERSONAL_GROUP_MANAGER_AUTHORITY_FIELDS))
        if unknown:
            raise ChaoxingAPIError(
                f"unsupported personal group manager permissions: {', '.join(unknown)}"
            )
        before = self.read_personal_group_member_permissions(group, member)
        selected_group = before["group"]
        selected_member = before["member"]
        enabled = {
            field
            for field, value in before["permissions"].items()
            if self._personal_group_boolean(value)
        }
        normalized_changes = {
            field: self._personal_group_boolean(value) for field, value in changes.items()
        }
        for field, value in normalized_changes.items():
            if value:
                enabled.add(field)
            else:
                enabled.discard(field)
        authority = {
            field: 1 for field in PERSONAL_GROUP_MANAGER_AUTHORITY_FIELDS if field in enabled
        }
        current_puid = self._personal_group_account_puid(selected_group["bbs_id"])
        session, landing = self._personal_groups_context()
        self._personal_group_json_request(
            session,
            (
                f"/pc/circle/manage/{quote(selected_group['bbs_id'], safe='')}"
                "/insertOrUpdateGroupAuthority"
            ),
            "personal group manager permission update",
            method="POST",
            data={
                "mypuid": current_puid,
                "puid": selected_member["puid"],
                "authority": quote(
                    json.dumps(authority, ensure_ascii=False, separators=(",", ":")), safe=""
                ),
                "bbsid": selected_group["bbs_id"],
            },
            referer=selected_group["management_url"] or landing.url,
        )
        after = self.read_personal_group_member_permissions(
            selected_group["bbs_id"], selected_member["puid"]
        )
        for field, expected in normalized_changes.items():
            if after["permissions"][field] is not expected:
                raise ChaoxingAPIError(
                    f"personal group manager permission {field} differs after refresh"
                )
        return {
            "before": before,
            "group": selected_group,
            "member": selected_member,
            "permissions": after["permissions"],
            "changes": normalized_changes,
            "verification": "all manager permission changes matched a fresh permission read",
        }

    def set_personal_group_member_manager_status(
        self,
        group: str,
        member: str,
        manager: bool,
    ) -> dict[str, Any]:
        selected_group = self._find_personal_group(group)
        if not self._personal_group_can(selected_group, "addManager"):
            raise ChaoxingAPIError("current account cannot change managers in this personal group")
        listing = self.list_personal_group_members(selected_group["bbs_id"])
        before = self._resolve_personal_group_member(listing["members"], member)
        if before["is_creator"]:
            raise ChaoxingAPIError("the personal group creator's manager status cannot be changed")
        if before["puid"] == self._personal_group_account_puid(selected_group["bbs_id"]):
            raise ChaoxingAPIError("current account cannot change its own manager status")
        if before["is_manager"] is bool(manager):
            raise ChaoxingAPIError("personal group member already has the requested manager status")
        session, landing = self._personal_groups_context()
        self._personal_group_json_request(
            session,
            "/pc/cmem/setManager",
            "personal group manager status update",
            params={
                "operate": "1" if manager else "0",
                "bbsid": selected_group["bbs_id"],
                "puids": before["puid"],
            },
            referer=selected_group["management_url"] or landing.url,
        )
        after = self.read_personal_group_member(selected_group["bbs_id"], before["puid"])["member"]
        if after["is_manager"] is not bool(manager):
            raise ChaoxingAPIError("personal group member manager status differs after refresh")
        return {
            "group": selected_group,
            "before": before,
            "member": after,
            "verification": f"member manager status is {bool(manager)} after refresh",
        }

    def remove_personal_group_member(self, group: str, member: str) -> dict[str, Any]:
        selected_group = self._find_personal_group(group)
        if not self._personal_group_can(selected_group, "delMem"):
            raise ChaoxingAPIError("current account cannot remove members from this personal group")
        listing = self.list_personal_group_members(selected_group["bbs_id"])
        selected_member = self._resolve_personal_group_member(listing["members"], member)
        if selected_member["is_creator"]:
            raise ChaoxingAPIError("the personal group creator cannot be removed")
        if selected_member["puid"] == self._personal_group_account_puid(selected_group["bbs_id"]):
            raise ChaoxingAPIError(
                "use the group quit action instead of removing the current account"
            )
        if selected_member["is_manager"] and not selected_group["is_creator"]:
            raise ChaoxingAPIError("only the personal group creator can remove a manager")
        session, landing = self._personal_groups_context()
        self._personal_group_json_request(
            session,
            "/pc/cmem/delMember",
            "personal group member removal",
            params={"bbsid": selected_group["bbs_id"], "puids": selected_member["puid"]},
            referer=selected_group["management_url"] or landing.url,
        )
        remaining = self.list_personal_group_members(selected_group["bbs_id"])["members"]
        if any(item["puid"] == selected_member["puid"] for item in remaining):
            raise ChaoxingAPIError("removed personal group member still appears after refresh")
        return {
            "group": selected_group,
            "removed": selected_member,
            "verification": "removed member is absent from a fresh member list",
        }

    def add_personal_group_members(self, group: str, puids: list[str]) -> dict[str, Any]:
        selected_group = self._find_personal_group(group)
        if not self._personal_group_can(selected_group, "addMem"):
            raise ChaoxingAPIError("current account cannot add members to this personal group")
        normalized_puids = list(dict.fromkeys(str(puid or "").strip() for puid in puids))
        if not normalized_puids or any(not puid.isdigit() for puid in normalized_puids):
            raise ChaoxingAPIError("one or more numeric PUIDs are required")
        before = self.list_personal_group_members(selected_group["bbs_id"])["members"]
        existing = {member["puid"] for member in before}
        duplicates = [puid for puid in normalized_puids if puid in existing]
        if duplicates:
            raise ChaoxingAPIError(
                f"personal group already contains PUIDs: {', '.join(duplicates)}"
            )
        session, landing = self._personal_groups_context()
        self._personal_group_json_request(
            session,
            "/pc/cmem/addMembers",
            "personal group member addition",
            params={"bbsid": selected_group["bbs_id"], "puids": ",".join(normalized_puids)},
            referer=selected_group["management_url"] or landing.url,
        )
        after = self.list_personal_group_members(selected_group["bbs_id"])["members"]
        added = [member for member in after if member["puid"] in normalized_puids]
        missing = sorted(set(normalized_puids) - {member["puid"] for member in added})
        if missing:
            raise ChaoxingAPIError(
                f"added personal group members are missing after refresh: {', '.join(missing)}"
            )
        return {
            "group": selected_group,
            "count": len(added),
            "added": added,
            "verification": "all requested PUIDs appear in a fresh member list",
        }

    def transfer_personal_group_creator(self, group: str, member: str) -> dict[str, Any]:
        before_group = self._find_personal_group(group)
        if not before_group["is_creator"]:
            raise ChaoxingAPIError("only the current personal group creator can transfer ownership")
        listing = self.list_personal_group_members(before_group["bbs_id"])
        new_creator = self._resolve_personal_group_member(listing["members"], member)
        if new_creator["is_creator"]:
            raise ChaoxingAPIError("selected member is already the personal group creator")
        session, landing = self._personal_groups_context()
        self._personal_group_json_request(
            session,
            "/pc/cmem/setCreater",
            "personal group creator transfer",
            params={"newCreaterPuid": new_creator["puid"], "bbsid": before_group["bbs_id"]},
            referer=before_group["management_url"] or landing.url,
        )
        after_group = self._find_personal_group(before_group["bbs_id"])
        if after_group["creator_puid"] != new_creator["puid"]:
            raise ChaoxingAPIError("personal group creator differs after refresh")
        return {
            "before": before_group,
            "group": after_group,
            "creator": new_creator,
            "verification": "new creator PUID matched a fresh personal group read",
        }

    def clear_personal_group_external_members(self, group: str) -> dict[str, Any]:
        selected_group = self._find_personal_group(group)
        if not self._personal_group_can(selected_group, "delMem"):
            raise ChaoxingAPIError("current account cannot clear members from this personal group")
        before = self.list_personal_group_members(selected_group["bbs_id"])["members"]
        external_members = [member for member in before if not member["puid"]]
        if not external_members:
            return {
                "group": selected_group,
                "removed_count": 0,
                "removed": [],
                "verification": "fresh member list contained no non-Chaoxing members",
            }
        session, landing = self._personal_groups_context()
        self._personal_group_json_request(
            session,
            "/pc/cmem/clearNonCXCmems",
            "non-Chaoxing personal group member clearing",
            params={"bbsid": selected_group["bbs_id"]},
            referer=selected_group["management_url"] or landing.url,
        )
        after = self.list_personal_group_members(selected_group["bbs_id"])["members"]
        if any(not member["puid"] for member in after):
            raise ChaoxingAPIError("non-Chaoxing personal group members remain after refresh")
        return {
            "group": selected_group,
            "removed_count": len(external_members),
            "removed": external_members,
            "verification": "fresh member list contains no non-Chaoxing members",
        }

    def _personal_group_topic_context(self, group: str) -> dict[str, Any]:
        selected = self._find_personal_group(group)
        session, landing = self._personal_groups_context()
        try:
            response = session.get(
                selected["topics_url"],
                headers={"Referer": landing.url},
                timeout=max(self.timeout, 60),
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"personal group topics page failed: {exc}") from exc
        html = self._decode(response)
        token_match = re.search(r"\burlToken\s*:\s*(['\"])(.*?)\1", html, flags=re.S)
        return {
            "group": selected,
            "session": session,
            "landing_url": response.url,
            "landing_html": html,
            "url_token": token_match.group(2) if token_match else "",
        }

    @staticmethod
    def _normalize_personal_group_topic_folder(
        raw: dict[str, Any], index: int = 0
    ) -> dict[str, Any]:
        return {
            "index": index,
            "folder_id": str(raw.get("id") or ""),
            "folder_uuid": str(raw.get("folder_uuid") or ""),
            "parent_id": str(raw.get("pid") or "0"),
            "name": str(raw.get("name") or "").strip(),
            "path_ids": str(raw.get("xpath") or ""),
            "topic_count": int(raw.get("count") or 0),
        }

    @staticmethod
    def _resolve_personal_group_topic_folder(
        folders: list[dict[str, Any]], query: str
    ) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if normalized in {"", "0", "root", "根目录", "话题根目录"}:
            return {
                "index": 0,
                "folder_id": "0",
                "folder_uuid": "",
                "parent_id": "",
                "name": "根目录",
                "path_ids": "",
                "topic_count": 0,
            }
        for key in ("folder_uuid", "folder_id", "index", "name"):
            exact = [
                folder
                for folder in folders
                if str(folder.get(key) or "").strip().lower() == normalized
            ]
            if len(exact) == 1:
                return exact[0]
            if len(exact) > 1:
                raise ChaoxingAPIError(f"multiple personal group topic folders match: {query}")
        partial = [folder for folder in folders if normalized in folder["name"].lower()]
        if len(partial) == 1:
            return partial[0]
        if not partial:
            raise ChaoxingAPIError(f"personal group topic folder not found: {query}")
        raise ChaoxingAPIError(f"multiple personal group topic folders match: {query}")

    @staticmethod
    def _resolve_personal_group_topic_draft(
        drafts: list[dict[str, Any]], query: str
    ) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("personal group topic draft UUID, title, or index is required")
        for key in ("draft_uuid", "index", "title"):
            exact = [
                draft for draft in drafts if str(draft.get(key) or "").strip().lower() == normalized
            ]
            if len(exact) == 1:
                return exact[0]
            if len(exact) > 1:
                raise ChaoxingAPIError(f"multiple personal group topic drafts match: {query}")
        partial = [
            draft for draft in drafts if normalized in str(draft.get("title") or "").strip().lower()
        ]
        if len(partial) == 1:
            return partial[0]
        if not partial:
            raise ChaoxingAPIError(f"personal group topic draft not found: {query}")
        raise ChaoxingAPIError(f"multiple personal group topic drafts match: {query}")

    def list_personal_group_topic_folder_tree(self, group: str) -> dict[str, Any]:
        context = self._personal_group_topic_context(group)
        selected = context["group"]
        payload = self._personal_group_json_request(
            context["session"],
            f"/pc/topicFolder/{quote(selected['bbs_id'], safe='')}/getFolderTree",
            "personal group topic folder tree",
            referer=context["landing_url"],
        )
        raw_folders = payload.get("datas")
        folders = [
            self._normalize_personal_group_topic_folder(raw, index)
            for index, raw in enumerate(raw_folders if isinstance(raw_folders, list) else [], 1)
            if isinstance(raw, dict)
        ]
        return {
            "group": selected,
            "count": len(folders),
            "folders": folders,
            "verification": f"read {len(folders)} personal group topic folders through HTTP",
        }

    @staticmethod
    def _personal_group_can(group: dict[str, Any], permission: str) -> bool:
        permissions = group.get("permissions")
        if not isinstance(permissions, dict):
            permissions = {}
        return bool(group.get("is_creator")) or str(permissions.get(permission) or "0") == "1"

    def create_personal_group_topic_folder(
        self,
        group: str,
        name: str,
        *,
        parent_folder: str = "",
    ) -> dict[str, Any]:
        name = name.strip()
        if not name:
            raise ChaoxingAPIError("personal group topic folder name is required")
        context = self._personal_group_topic_context(group)
        selected_group = context["group"]
        if not self._personal_group_can(selected_group, "addTopicFolder"):
            raise ChaoxingAPIError("current account cannot create topic folders in this group")
        before_tree = self.list_personal_group_topic_folder_tree(selected_group["bbs_id"])
        parent = self._resolve_personal_group_topic_folder(before_tree["folders"], parent_folder)
        before_ids = {item["folder_id"] for item in before_tree["folders"]}
        payload = self._personal_group_json_request(
            context["session"],
            "/pc/topicFolder/addFolder",
            "personal group topic folder creation",
            params={
                "bbsid": selected_group["bbs_id"],
                "name": quote(name, safe=""),
                "folderId": parent["folder_id"],
            },
            referer=context["landing_url"],
        )
        refreshed = self.list_personal_group_topic_folder_tree(selected_group["bbs_id"])
        candidates = [
            item
            for item in refreshed["folders"]
            if item["folder_id"] not in before_ids
            and item["name"] == name
            and item["parent_id"] == parent["folder_id"]
        ]
        if len(candidates) != 1:
            raise ChaoxingAPIError(
                "created personal group topic folder was not unique after refresh"
            )
        return {
            "group": selected_group,
            "parent_folder": parent,
            "folder": candidates[0],
            "server_message": str(payload.get("msg") or ""),
            "verification": "created personal group topic folder matched a fresh tree read",
        }

    def rename_personal_group_topic_folder(
        self,
        group: str,
        folder: str,
        name: str,
    ) -> dict[str, Any]:
        name = name.strip()
        if not name:
            raise ChaoxingAPIError("personal group topic folder name is required")
        context = self._personal_group_topic_context(group)
        selected_group = context["group"]
        if not self._personal_group_can(selected_group, "modifyTopicFolder"):
            raise ChaoxingAPIError("current account cannot rename topic folders in this group")
        before = self._resolve_personal_group_topic_folder(
            self.list_personal_group_topic_folder_tree(selected_group["bbs_id"])["folders"],
            folder,
        )
        payload = self._personal_group_json_request(
            context["session"],
            "/pc/topicFolder/updateFolder",
            "personal group topic folder rename",
            params={
                "bbsid": selected_group["bbs_id"],
                "folder_uuid": before["folder_uuid"],
                "name": name,
            },
            referer=context["landing_url"],
        )
        after = self._resolve_personal_group_topic_folder(
            self.list_personal_group_topic_folder_tree(selected_group["bbs_id"])["folders"],
            before["folder_id"],
        )
        if after["name"] != name:
            raise ChaoxingAPIError("personal group topic folder name differs after refresh")
        return {
            "group": selected_group,
            "before": before,
            "folder": after,
            "server_message": str(payload.get("msg") or ""),
            "verification": "personal group topic folder name matched a fresh tree read",
        }

    def move_personal_group_topic_folder(
        self,
        group: str,
        folder: str,
        destination_folder: str,
    ) -> dict[str, Any]:
        context = self._personal_group_topic_context(group)
        selected_group = context["group"]
        if not self._personal_group_can(selected_group, "modifyTopicFolder"):
            raise ChaoxingAPIError("current account cannot move topic folders in this group")
        tree = self.list_personal_group_topic_folder_tree(selected_group["bbs_id"])
        before = self._resolve_personal_group_topic_folder(tree["folders"], folder)
        destination = self._resolve_personal_group_topic_folder(tree["folders"], destination_folder)
        destination_path = {part for part in destination["path_ids"].strip("/").split("/") if part}
        if (
            destination["folder_id"] == before["folder_id"]
            or before["folder_id"] in destination_path
        ):
            raise ChaoxingAPIError("a personal group topic folder cannot move into itself")
        payload = self._personal_group_json_request(
            context["session"],
            f"/pc/topicFolder/{quote(selected_group['bbs_id'], safe='')}/batchMoveFolders",
            "personal group topic folder move",
            method="POST",
            data={
                "targetFolder_uuid": destination["folder_uuid"],
                "folderIds": before["folder_id"],
            },
            referer=context["landing_url"],
        )
        after = self._resolve_personal_group_topic_folder(
            self.list_personal_group_topic_folder_tree(selected_group["bbs_id"])["folders"],
            before["folder_id"],
        )
        if after["parent_id"] != destination["folder_id"]:
            raise ChaoxingAPIError("personal group topic folder destination differs after refresh")
        return {
            "group": selected_group,
            "before": before,
            "destination_folder": destination,
            "folder": after,
            "server_message": str(payload.get("msg") or ""),
            "verification": "personal group topic folder destination matched a fresh tree read",
        }

    def delete_personal_group_topic_folder(self, group: str, folder: str) -> dict[str, Any]:
        context = self._personal_group_topic_context(group)
        selected_group = context["group"]
        if not self._personal_group_can(selected_group, "delTopicFolder"):
            raise ChaoxingAPIError("current account cannot delete topic folders in this group")
        before = self._resolve_personal_group_topic_folder(
            self.list_personal_group_topic_folder_tree(selected_group["bbs_id"])["folders"],
            folder,
        )
        payload = self._personal_group_json_request(
            context["session"],
            "/pc/topicFolder/delFolder",
            "personal group topic folder deletion",
            params={
                "bbsid": selected_group["bbs_id"],
                "folder_uuid": before["folder_uuid"],
            },
            referer=context["landing_url"],
        )
        remaining = self.list_personal_group_topic_folder_tree(selected_group["bbs_id"])["folders"]
        if any(item["folder_id"] == before["folder_id"] for item in remaining):
            raise ChaoxingAPIError(
                "deleted personal group topic folder still appears after refresh"
            )
        return {
            "group": selected_group,
            "deleted_folder": before,
            "server_message": str(payload.get("msg") or ""),
            "verification": "deleted personal group topic folder is absent from a fresh tree read",
        }

    def read_personal_group_topic_draft(
        self,
        group: str,
        draft_uuid: str,
    ) -> dict[str, Any]:
        draft_uuid = draft_uuid.strip()
        if not draft_uuid:
            raise ChaoxingAPIError("personal group topic draft UUID is required")
        context = self._personal_group_topic_context(group)
        selected_group = context["group"]
        endpoint = GROUPWEB_BASE_URL + "/pc/topic/jumpToUpdateTopicDraft"
        try:
            response = context["session"].get(
                endpoint,
                params={"bbsid": selected_group["bbs_id"], "uuid": draft_uuid},
                headers={"Referer": context["landing_url"]},
                timeout=max(self.timeout, 60),
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"personal group topic draft read failed: {exc}") from exc
        html = self._decode(response)
        marker = re.search(r"\btopic\s*:\s*", html)
        if not marker:
            raise ChaoxingAPIError("personal group topic draft was not found or is not editable")
        try:
            raw, _end = json.JSONDecoder().raw_decode(html[marker.end() :].lstrip())
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("personal group topic draft page exposed invalid data") from exc
        if not isinstance(raw, dict):
            raise ChaoxingAPIError("personal group topic draft page exposed invalid data")
        if str(raw.get("bbsid") or "") != selected_group["bbs_id"]:
            raise ChaoxingAPIError("personal group topic draft belongs to a different group")
        is_edit = False
        for match in re.finditer(r"<input\b[^>]*>", html, flags=re.I):
            attrs = html_attrs(match.group(0))
            if attrs.get("name") == "isEdit":
                is_edit = attrs.get("value") == "1"
                break
        images = raw.get("img_data") if isinstance(raw.get("img_data"), list) else []
        attachments = raw.get("attachment")
        if not isinstance(attachments, list):
            attachments = []
        labels = raw.get("labelList")
        if not isinstance(labels, list):
            labels = []
        draft = {
            "draft_uuid": str(raw.get("uuid") or draft_uuid),
            "bbs_id": selected_group["bbs_id"],
            "title": str(raw.get("title") or "").strip(),
            "content": str(raw.get("content") or "").strip(),
            "rtf_content": str(raw.get("rtf_content") or ""),
            "folder_id": str(raw.get("folderId") or "0"),
            "is_edit": is_edit,
            "images": images,
            "attachments": attachments,
            "labels": labels,
        }
        return {
            "group": selected_group,
            "draft": draft,
            "verification": f"read personal group topic draft {draft['draft_uuid']} through HTTP",
        }

    def list_personal_group_topic_drafts(
        self,
        group: str,
        *,
        search: str = "",
    ) -> dict[str, Any]:
        selected_group = self._find_personal_group(group)
        state = self._read_local_state()
        records = [
            item
            for item in state.get("topic_drafts", [])
            if isinstance(item, dict) and str(item.get("bbs_id") or "") == selected_group["bbs_id"]
        ]
        drafts: list[dict[str, Any]] = []
        unavailable: list[dict[str, Any]] = []
        normalized_search = search.strip().lower()
        for record in records:
            draft_uuid = str(record.get("draft_uuid") or "")
            if not draft_uuid:
                continue
            try:
                draft = self.read_personal_group_topic_draft(selected_group["bbs_id"], draft_uuid)[
                    "draft"
                ]
            except ChaoxingAPIError as exc:
                unavailable.append({**record, "error": str(exc)})
                continue
            if (
                normalized_search
                and normalized_search not in (draft["title"] + "\n" + draft["content"]).lower()
            ):
                continue
            draft["updated_at"] = str(record.get("updated_at") or "")
            draft["index"] = len(drafts) + 1
            drafts.append(draft)
        return {
            "group": selected_group,
            "search": search.strip(),
            "count": len(drafts),
            "drafts": drafts,
            "unavailable": unavailable,
            "registry_enabled": self.state_file is not None,
            "verification": (
                f"re-read {len(drafts)} managed personal group topic drafts through HTTP"
            ),
        }

    def save_personal_group_topic_draft(
        self,
        group: str,
        title: str,
        content: str,
        *,
        draft_query: str = "",
        folder: str = "",
    ) -> dict[str, Any]:
        title = title.strip()
        content = content.strip()
        if not title and not content:
            raise ChaoxingAPIError(
                "personal group topic draft title and content cannot both be empty"
            )
        if len(title) > 200:
            raise ChaoxingAPIError("personal group topic draft title cannot exceed 200 characters")
        context = self._personal_group_topic_context(group)
        selected_group = context["group"]
        folder_id = "0"
        if folder.strip():
            tree = self.list_personal_group_topic_folder_tree(selected_group["bbs_id"])
            folder_id = self._resolve_personal_group_topic_folder(tree["folders"], folder)[
                "folder_id"
            ]
        draft_uuid = uuid4().hex
        if draft_query.strip():
            records = [
                item
                for item in self._read_local_state().get("topic_drafts", [])
                if isinstance(item, dict)
                and str(item.get("bbs_id") or "") == selected_group["bbs_id"]
            ]
            try:
                draft_uuid = self._resolve_personal_group_topic_draft(records, draft_query)[
                    "draft_uuid"
                ]
            except ChaoxingAPIError:
                if not re.fullmatch(r"[0-9a-fA-F-]{24,64}", draft_query.strip()):
                    raise
                draft_uuid = draft_query.strip()
            self.read_personal_group_topic_draft(selected_group["bbs_id"], draft_uuid)
        rtf_content = f"<p>{escape(content)}</p>" if content else ""
        payload = self._personal_group_json_request(
            context["session"],
            "/pc/topic/addTopicDraft",
            "personal group topic draft save",
            method="POST",
            params={"uuid": draft_uuid},
            data={
                "topicTitle": quote(title, safe=""),
                "topicContent": quote(content, safe=""),
                "files_url": "",
                "files_attr": "",
                "rtf_content": quote(rtf_content, safe=""),
                "bbsid": selected_group["bbs_id"],
                "folderId": folder_id,
                "label": "",
                "isEdit": "0",
                "isRichText": "1",
            },
            referer=context["landing_url"],
        )
        saved = self.read_personal_group_topic_draft(selected_group["bbs_id"], draft_uuid)["draft"]
        if saved["title"] != title or saved["content"] != content:
            raise ChaoxingAPIError("personal group topic draft differs after refresh")
        self._upsert_topic_draft_record(
            {
                "bbs_id": selected_group["bbs_id"],
                "group_name": selected_group["name"],
                "draft_uuid": draft_uuid,
                "title": title,
                "updated_at": datetime.now(UTC).isoformat(),
            }
        )
        return {
            "group": selected_group,
            "draft": saved,
            "server_message": str(payload.get("msg") or ""),
            "registry_enabled": self.state_file is not None,
            "verification": f"saved and re-read personal group topic draft {draft_uuid}",
        }

    def publish_personal_group_topic_draft(
        self,
        group: str,
        draft_query: str,
    ) -> dict[str, Any]:
        selected_group = self._find_personal_group(group)
        records = [
            item
            for item in self._read_local_state().get("topic_drafts", [])
            if isinstance(item, dict) and str(item.get("bbs_id") or "") == selected_group["bbs_id"]
        ]
        try:
            draft_uuid = self._resolve_personal_group_topic_draft(records, draft_query)[
                "draft_uuid"
            ]
        except ChaoxingAPIError:
            if not re.fullmatch(r"[0-9a-fA-F-]{24,64}", draft_query.strip()):
                raise
            draft_uuid = draft_query.strip()
        before = self.read_personal_group_topic_draft(selected_group["bbs_id"], draft_uuid)["draft"]
        context = self._personal_group_topic_context(selected_group["bbs_id"])
        if not context["url_token"]:
            raise ChaoxingAPIError("personal group topics page did not expose urlToken")
        if before["is_edit"]:
            path = (
                f"/pc/topic/{quote(selected_group['bbs_id'], safe='')}/"
                f"{quote(draft_uuid, safe='')}/updateTopic"
            )
            data = {
                "edit_topicTitle": quote(before["title"], safe=""),
                "edit_topicContent": quote(before["content"], safe=""),
                "edit_files_url": "",
                "edit_files_attr": "",
                "rtf_content": quote(before["rtf_content"], safe=""),
                "isRichText": "1",
                "label": "",
                "urlToken": context["url_token"],
            }
        else:
            path = f"/pc/topic/{quote(selected_group['bbs_id'], safe='')}/addTopic"
            data = {
                "topicTitle": quote(before["title"], safe=""),
                "topicContent": quote(before["content"], safe=""),
                "files_url": "",
                "files_attr": "",
                "rtf_content": quote(before["rtf_content"], safe=""),
                "bbsid": selected_group["bbs_id"],
                "folderId": before["folder_id"],
                "isRichText": "1",
                "label": "",
                "urlToken": context["url_token"],
            }
        payload = self._personal_group_json_request(
            context["session"],
            path,
            "personal group topic draft publication",
            method="POST",
            params={"uuid": draft_uuid} if not before["is_edit"] else None,
            data=data,
            referer=context["landing_url"],
        )
        _raw, topic = self._discussion_topic_payload(
            context["session"], draft_uuid, referer=context["landing_url"]
        )
        if topic["title"] != before["title"] or topic["content"] != before["content"]:
            raise ChaoxingAPIError("published personal group topic differs from its draft")
        self._remove_topic_draft_record(selected_group["bbs_id"], draft_uuid)
        return {
            "group": selected_group,
            "draft": before,
            "topic": topic,
            "server_message": str(payload.get("msg") or ""),
            "verification": f"published and re-read personal group topic {draft_uuid}",
        }

    def list_personal_group_topics(
        self,
        group: str,
        *,
        folder: str = "",
        search: str = "",
    ) -> dict[str, Any]:
        context = self._personal_group_topic_context(group)
        selected = context["group"]
        folder_tree = self.list_personal_group_topic_folder_tree(selected["bbs_id"])
        selected_folder = self._resolve_personal_group_topic_folder(folder_tree["folders"], folder)
        session = context["session"]
        bbs_id = selected["bbs_id"]
        folder_uuid = selected_folder["folder_uuid"]
        topics: list[dict[str, Any]] = []
        seen: set[str] = set()
        permissions: dict[str, Any] = {}
        displayed_folders: list[dict[str, Any]] = []

        top_payload = self._personal_group_json_request(
            session,
            f"/pc/topic/topiclist/{quote(bbs_id, safe='')}/getTopTopicList",
            "personal group top topic list",
            params={"folder_uuid": folder_uuid, "isSetTop": ""},
            referer=context["landing_url"],
        )
        top_topics, _unused = parse_discussion_payload(top_payload)
        for topic in top_topics:
            topic["is_top"] = True
            identity = topic["uuid"] or topic["topic_id"]
            if identity and identity not in seen:
                seen.add(identity)
                topics.append(topic)

        last_reply_time = ""
        last_aux_value = ""
        page = 1
        while page <= 100:
            params: dict[str, Any] = {
                "folder_uuid": folder_uuid,
                "page": str(page),
                "pageSize": "20",
                "kw": search.strip(),
                "isSetTop": "",
                "selectedStartTime": "",
                "selectedEndTime": "",
                "selectedType": "",
                "learnSilverStartTime": "",
                "learnSilverEndTime": "",
                "lastAuxValue": last_aux_value,
            }
            if last_reply_time:
                params["last_reply_time"] = last_reply_time
            payload = self._personal_group_json_request(
                session,
                f"/pc/topic/topiclist/{quote(bbs_id, safe='')}/getTopicList",
                "personal group topic list",
                method="POST",
                params=params,
                referer=context["landing_url"],
            )
            page_topics, page_folders = parse_discussion_payload(payload)
            for topic in page_topics:
                identity = topic["uuid"] or topic["topic_id"]
                if identity and identity not in seen:
                    seen.add(identity)
                    topics.append(topic)
            if page == 1:
                displayed_folders = page_folders
                raw_permissions = payload.get("userAuth")
                permissions = raw_permissions if isinstance(raw_permissions, dict) else {}
            poff = payload.get("poff") if isinstance(payload.get("poff"), dict) else {}
            if bool(poff.get("lastPage")) or not page_topics:
                break
            next_value = str(poff.get("lastValue") or "")
            next_aux = str(poff.get("lastAuxValue") or "")
            if not next_value or next_value == last_reply_time:
                break
            last_reply_time = next_value
            last_aux_value = next_aux
            page += 1

        for index, topic in enumerate(topics, 1):
            topic["index"] = index
        return {
            "group": selected,
            "folder": selected_folder,
            "search": search.strip(),
            "count": len(topics),
            "topics": topics,
            "child_folders": displayed_folders,
            "permissions": permissions,
            "verification": f"read {len(topics)} personal group topics through HTTP",
        }

    def read_personal_group_topic(
        self,
        group: str,
        topic_query: str,
        *,
        order: int = 2,
        reply_search: str = "",
    ) -> dict[str, Any]:
        if order not in {1, 2}:
            raise ChaoxingAPIError("personal group topic reply order must be 1 or 2")
        session = self._session()
        direct_uuid = bool(re.fullmatch(r"[0-9a-fA-F-]{24,64}", topic_query.strip()))
        if direct_uuid:
            selected_group = self._find_personal_group(group)
            _raw_topic, topic = self._discussion_topic_payload(
                session,
                topic_query.strip(),
                referer=selected_group["topics_url"],
            )
        else:
            listing = self._list_all_personal_group_topics(group)
            selected_group = listing["group"]
            selected = resolve_discussion_topic(listing["topics"], topic_query)
            _raw_topic, topic = self._discussion_topic_payload(
                session,
                selected["uuid"],
                referer=selected_group["topics_url"],
            )
        if topic["bbs_id"] != selected_group["bbs_id"]:
            raise ChaoxingAPIError("personal group topic detail returned a different group")
        common_params = {
            "bbsid": selected_group["bbs_id"],
            "uuid": topic["uuid"],
            "tag": "",
            "order": str(order),
        }
        top_payload = self._personal_group_json_request(
            session,
            "/pc/invitation/getTopReplyList",
            "personal group top replies",
            params={**common_params, "kw": reply_search.strip()},
            referer=selected_group["topics_url"],
        )
        replies = parse_discussion_replies(top_payload, is_top=True)
        last_value = ""
        last_aux_value = ""
        while True:
            payload = self._personal_group_json_request(
                session,
                "/pc/invitation/getReplyList",
                "personal group topic replies",
                params={
                    **common_params,
                    "kw": reply_search.strip(),
                    "lastValue": last_value,
                    "lastAuxValue": last_aux_value,
                },
                referer=selected_group["topics_url"],
            )
            page_replies = parse_discussion_replies(payload, is_top=False)
            replies.extend(page_replies)
            poff = payload.get("poff") if isinstance(payload.get("poff"), dict) else {}
            if bool(poff.get("lastPage")) or not page_replies:
                break
            next_value = str(poff.get("lastValue") or "")
            next_aux = str(poff.get("lastAuxValue") or "")
            if not next_value or (next_value, next_aux) == (last_value, last_aux_value):
                break
            last_value = next_value
            last_aux_value = next_aux

        unique: list[dict[str, Any]] = []
        seen: set[str] = set()
        for reply in replies:
            identity = str(reply.get("uuid") or reply.get("reply_id") or "")
            if identity and identity in seen:
                continue
            if identity:
                seen.add(identity)
            reply["index"] = len(unique) + 1
            unique.append(reply)
        return {
            "group": selected_group,
            "topic": topic,
            "reply_order": "oldest_first" if order == 1 else "newest_first",
            "reply_search": reply_search.strip(),
            "reply_count": len(unique),
            "replies": unique,
            "verification": f"read personal group topic {topic['uuid']} and {len(unique)} replies",
        }

    def _list_all_personal_group_topics(self, group: str) -> dict[str, Any]:
        root_listing = self.list_personal_group_topics(group)
        selected_group = root_listing["group"]
        tree = self.list_personal_group_topic_folder_tree(selected_group["bbs_id"])
        topics = list(root_listing["topics"])
        seen = {topic["uuid"] for topic in topics}
        for folder in tree["folders"]:
            listing = self.list_personal_group_topics(
                selected_group["bbs_id"], folder=folder["folder_uuid"]
            )
            for topic in listing["topics"]:
                if topic["uuid"] in seen:
                    continue
                seen.add(topic["uuid"])
                topics.append(topic)
        for index, topic in enumerate(topics, start=1):
            topic["index"] = index
        return {
            "group": selected_group,
            "topics": topics,
            "count": len(topics),
            "verification": (
                f"read {len(topics)} personal group topics across the root and "
                f"{len(tree['folders'])} folders"
            ),
        }

    def create_personal_group_topic(
        self,
        group: str,
        title: str,
        content: str,
        *,
        folder: str = "",
        anonymous: bool = False,
    ) -> dict[str, Any]:
        title = title.strip()
        content = content.strip()
        if not title and not content:
            raise ChaoxingAPIError("personal group topic title and content cannot both be empty")
        if len(title) > 200:
            raise ChaoxingAPIError("personal group topic title cannot exceed 200 characters")
        context = self._personal_group_topic_context(group)
        selected = context["group"]
        if not context["url_token"]:
            raise ChaoxingAPIError("personal group topics page did not expose urlToken")
        folder_uuid = ""
        selected_folder = self._resolve_personal_group_topic_folder([], "")
        if folder.strip():
            tree = self.list_personal_group_topic_folder_tree(selected["bbs_id"])
            selected_folder = self._resolve_personal_group_topic_folder(tree["folders"], folder)
            folder_uuid = selected_folder["folder_uuid"]
        topic_uuid = uuid4().hex
        payload = self._personal_group_json_request(
            context["session"],
            f"/pc/topic/{quote(selected['bbs_id'], safe='')}/addTopic",
            "personal group topic creation",
            method="POST",
            params={"uuid": topic_uuid},
            data={
                "topicTitle": quote(title, safe=""),
                "topicContent": quote(content, safe=""),
                "files_url": "",
                "files_attr": "",
                "bbsid": selected["bbs_id"],
                "folder_uuid": folder_uuid,
                "label": "",
                "urlToken": context["url_token"],
                "anonymous": "1" if anonymous else "0",
            },
            referer=context["landing_url"],
        )
        try:
            _raw, created = self._discussion_topic_payload(
                context["session"], topic_uuid, referer=context["landing_url"]
            )
        except ChaoxingAPIError:
            if payload.get("msg") and not payload.get("objs"):
                return {
                    "group": selected,
                    "topic_uuid": topic_uuid,
                    "folder": selected_folder,
                    "anonymous": anonymous,
                    "pending_review": True,
                    "server_message": str(payload.get("msg") or ""),
                    "verification": "server accepted the personal group topic for review",
                }
            raise
        if created["bbs_id"] != selected["bbs_id"]:
            raise ChaoxingAPIError("created personal group topic belongs to a different group")
        return {
            "group": selected,
            "topic": created,
            "folder": selected_folder,
            "anonymous": anonymous,
            "pending_review": False,
            "server_message": str(payload.get("msg") or ""),
            "verification": f"created and re-read personal group topic {topic_uuid}",
        }

    def update_personal_group_topic(
        self,
        group: str,
        topic_query: str,
        *,
        title: str | None = None,
        content: str | None = None,
    ) -> dict[str, Any]:
        if title is None and content is None:
            raise ChaoxingAPIError("personal group topic title or content change is required")
        listing = self.list_personal_group_topics(group)
        selected = resolve_discussion_topic(listing["topics"], topic_query)
        session = self._session()
        raw, before = self._discussion_topic_payload(
            session, selected["uuid"], referer=listing["group"]["topics_url"]
        )
        operation_auth = before.get("permissions", {}).get("operationAuth", {})
        if str(operation_auth.get("update") or "0") != "1":
            raise ChaoxingAPIError("current account cannot update this personal group topic")
        next_title = before["title"] if title is None else title.strip()
        next_content = before["content"] if content is None else content.strip()
        if not next_title and not next_content:
            raise ChaoxingAPIError("personal group topic title and content cannot both be empty")
        if len(next_title) > 200:
            raise ChaoxingAPIError("personal group topic title cannot exceed 200 characters")
        files_url, files_attr = self._discussion_asset_fields(raw)
        is_rich = bool(raw.get("rtf_content")) or bool(raw.get("isRtf"))
        data: dict[str, Any] = {
            "edit_topicTitle": quote(next_title, safe=""),
            "edit_topicContent": quote(next_content, safe=""),
            "edit_files_url": files_url,
            "edit_files_attr": quote(files_attr, safe=""),
            "isRichText": "1" if is_rich else "0",
        }
        if is_rich:
            rich_content = (
                str(raw.get("rtf_content") or "")
                if content is None
                else f"<p>{escape(next_content)}</p>"
            )
            data["rtf_content"] = quote(rich_content, safe="")
        payload = self._personal_group_json_request(
            session,
            f"/pc/topic/{quote(listing['group']['bbs_id'], safe='')}/"
            f"{quote(before['uuid'], safe='')}/updateTopic",
            "personal group topic update",
            method="POST",
            data=data,
            referer=listing["group"]["topics_url"],
        )
        _raw, updated = self._discussion_topic_payload(
            session, before["uuid"], referer=listing["group"]["topics_url"]
        )
        if updated["title"] != next_title or updated["content"] != next_content:
            raise ChaoxingAPIError("updated personal group topic differs after refresh")
        return {
            "group": listing["group"],
            "before": before,
            "topic": updated,
            "server_message": str(payload.get("msg") or ""),
            "verification": f"updated and re-read personal group topic {before['uuid']}",
        }

    def delete_personal_group_topic(self, group: str, topic_query: str) -> dict[str, Any]:
        before = self.read_personal_group_topic(group, topic_query)
        topic = before["topic"]
        operation_auth = topic.get("permissions", {}).get("operationAuth", {})
        if str(operation_auth.get("delete") or "0") != "1":
            raise ChaoxingAPIError("current account cannot delete this personal group topic")
        session = self._session()
        payload = self._personal_group_json_request(
            session,
            f"/pc/topic/{quote(before['group']['bbs_id'], safe='')}/"
            f"{quote(topic['uuid'], safe='')}/deleteTopic",
            "personal group topic deletion",
            method="POST",
            referer=before["group"]["topics_url"],
        )
        refreshed = self.list_personal_group_topics(group, search=topic["title"])
        if any(item["uuid"] == topic["uuid"] for item in refreshed["topics"]):
            raise ChaoxingAPIError("deleted personal group topic still appears after refresh")
        return {
            "group": before["group"],
            "deleted_topic": topic,
            "server_message": str(payload.get("msg") or ""),
            "verification": f"personal group topic {topic['uuid']} is absent after refresh",
        }

    def set_personal_group_topic_top_status(
        self,
        group: str,
        topic_query: str,
        top: bool,
    ) -> dict[str, Any]:
        before = self.read_personal_group_topic(group, topic_query)
        topic = before["topic"]
        operation_auth = topic.get("permissions", {}).get("operationAuth", {})
        if str(operation_auth.get("topSet") or "0") != "1":
            raise ChaoxingAPIError("current account cannot change this topic's top status")
        payload = self._personal_group_json_request(
            self._session(),
            f"/pc/topic/{quote(topic['uuid'], safe='')}/{'set' if top else 'cancel'}/top",
            "personal group topic top status",
            referer=before["group"]["topics_url"],
        )
        folder = topic["folder_id"] or ""
        refreshed = self.list_personal_group_topics(group, folder=folder)
        after = resolve_discussion_topic(refreshed["topics"], topic["uuid"])
        if after["is_top"] is not bool(top):
            raise ChaoxingAPIError("personal group topic top status differs after refresh")
        return {
            "group": before["group"],
            "before": topic,
            "topic": after,
            "server_message": str(payload.get("msg") or ""),
            "verification": f"personal group topic top status is {bool(top)} after refresh",
        }

    def _personal_group_topics_for_queries(
        self, group: str, queries: list[str]
    ) -> tuple[dict[str, Any], list[dict[str, Any]]]:
        if not queries:
            raise ChaoxingAPIError("at least one personal group topic is required")
        selected_group: dict[str, Any] | None = None
        listing: dict[str, Any] | None = None
        topic_uuids: list[str] = []
        for query in queries:
            normalized = str(query or "").strip()
            if re.fullmatch(r"[0-9a-fA-F-]{24,64}", normalized):
                topic_uuids.append(normalized)
                continue
            if listing is None:
                listing = self._list_all_personal_group_topics(group)
                selected_group = listing["group"]
            topic_uuids.append(resolve_discussion_topic(listing["topics"], normalized)["uuid"])
        if selected_group is None:
            selected_group = self._find_personal_group(group)
        session = self._session()
        topics = [
            self._discussion_topic_payload(
                session,
                topic_uuid,
                referer=selected_group["topics_url"],
            )[1]
            for topic_uuid in topic_uuids
        ]
        if any(topic["bbs_id"] != selected_group["bbs_id"] for topic in topics):
            raise ChaoxingAPIError("personal group topic selection contains another group")
        uuids = [topic["uuid"] for topic in topics]
        if len(set(uuids)) != len(uuids):
            raise ChaoxingAPIError("personal group topic selection contains duplicates")
        return selected_group, topics

    def set_personal_group_topic_choice_status(
        self,
        group: str,
        topic_query: str,
        choice: bool,
    ) -> dict[str, Any]:
        before = self.read_personal_group_topic(group, topic_query)
        topic = before["topic"]
        operation_auth = topic.get("permissions", {}).get("operationAuth", {})
        if str(operation_auth.get("choiceSet") or "0") != "1":
            raise ChaoxingAPIError("current account cannot change this topic's choice status")
        if topic["is_choice"] is bool(choice):
            return {
                "group": before["group"],
                "before": topic,
                "topic": topic,
                "verification": "personal group topic already had the requested choice status",
            }
        payload = self._personal_group_json_request(
            self._session(),
            f"/pc/topic/{quote(topic['uuid'], safe='')}/{'set' if choice else 'cancel'}/choice",
            "personal group topic choice status",
            referer=before["group"]["topics_url"],
        )
        after = self.read_personal_group_topic(before["group"]["bbs_id"], topic["uuid"])["topic"]
        if after["is_choice"] is not bool(choice):
            raise ChaoxingAPIError("personal group topic choice status differs after refresh")
        return {
            "group": before["group"],
            "before": topic,
            "topic": after,
            "server_message": str(payload.get("msg") or ""),
            "verification": f"personal group topic choice status is {bool(choice)} after refresh",
        }

    def set_personal_group_topic_praise_status(
        self,
        group: str,
        topic_query: str,
        praised: bool,
    ) -> dict[str, Any]:
        before = self.read_personal_group_topic(group, topic_query)
        topic = before["topic"]
        if topic["is_praised"] is bool(praised):
            return {
                "group": before["group"],
                "before": topic,
                "topic": topic,
                "verification": "personal group topic already had the requested praise status",
            }
        endpoint = "addTopicPraise" if praised else "cancelTopicPraise"
        payload = self._personal_group_json_request(
            self._session(),
            f"/pc/praise/{quote(topic['uuid'], safe='')}/{endpoint}",
            "personal group topic praise status",
            referer=before["group"]["topics_url"],
        )
        after = self.read_personal_group_topic(before["group"]["bbs_id"], topic["uuid"])["topic"]
        if after["is_praised"] is not bool(praised):
            raise ChaoxingAPIError("personal group topic praise status differs after refresh")
        return {
            "group": before["group"],
            "before": topic,
            "topic": after,
            "server_message": str(payload.get("msg") or ""),
            "verification": f"personal group topic praise status is {bool(praised)} after refresh",
        }

    def set_personal_group_topics_score(
        self,
        group: str,
        topic_queries: list[str],
        score: int,
    ) -> dict[str, Any]:
        selected_group, topics = self._personal_group_topics_for_queries(group, topic_queries)
        for topic in topics:
            operation_auth = topic.get("permissions", {}).get("operationAuth", {})
            if str(operation_auth.get("scoreSet") or "0") != "1":
                raise ChaoxingAPIError(
                    f"current account cannot score personal group topic {topic['uuid']}"
                )
            score_info = topic.get("score") if isinstance(topic.get("score"), dict) else {}
            score_range = (
                score_info.get("scoreRange")
                if isinstance(score_info.get("scoreRange"), dict)
                else {}
            )
            minimum = int(score_range.get("minscore") or 0)
            maximum = int(score_range.get("maxscore") or 100)
            if score < minimum or score > maximum:
                raise ChaoxingAPIError(
                    f"personal group topic score must be between {minimum} and {maximum}"
                )
        payload = self._personal_group_json_request(
            self._session(),
            "/pc/score/addTopicScoreByBatch",
            "personal group topic batch score",
            method="POST",
            data={
                "bbsid": selected_group["bbs_id"],
                "score": score,
                "uuids": ",".join(topic["uuid"] for topic in topics),
            },
            referer=selected_group["topics_url"],
            allow_result=True,
        )
        refreshed = [
            self.read_personal_group_topic(selected_group["bbs_id"], topic["uuid"])["topic"]
            for topic in topics
        ]
        for topic in refreshed:
            score_info = topic.get("score") if isinstance(topic.get("score"), dict) else {}
            if float(score_info.get("my_score") or 0) != float(score):
                raise ChaoxingAPIError(
                    f"personal group topic {topic['uuid']} score differs after refresh"
                )
        return {
            "group": selected_group,
            "score": score,
            "topics": refreshed,
            "server_message": str(payload.get("msg") or ""),
            "verification": "personal group topic scores matched fresh detail reads",
        }

    def move_personal_group_topics(
        self,
        group: str,
        topic_queries: list[str],
        destination_folder: str,
    ) -> dict[str, Any]:
        selected_group, topics = self._personal_group_topics_for_queries(group, topic_queries)
        for topic in topics:
            operation_auth = topic.get("permissions", {}).get("operationAuth", {})
            if str(operation_auth.get("addTopicToFolder") or "0") != "1":
                raise ChaoxingAPIError(
                    f"current account cannot move personal group topic {topic['uuid']}"
                )
        tree = self.list_personal_group_topic_folder_tree(selected_group["bbs_id"])
        destination = self._resolve_personal_group_topic_folder(tree["folders"], destination_folder)
        payload = self._personal_group_json_request(
            self._session(),
            f"/pc/topic/{quote(selected_group['bbs_id'], safe='')}/addTopicsToFolder",
            "personal group topic batch move",
            method="POST",
            data={
                "targetFolder_uuid": destination["folder_uuid"],
                "uuids": ",".join(topic["uuid"] for topic in topics),
            },
            referer=selected_group["topics_url"],
        )
        refreshed = self.list_personal_group_topics(
            selected_group["bbs_id"], folder=destination["folder_uuid"]
        )["topics"]
        refreshed_ids = {topic["uuid"] for topic in refreshed}
        missing = [topic["uuid"] for topic in topics if topic["uuid"] not in refreshed_ids]
        if missing:
            raise ChaoxingAPIError(
                f"moved personal group topics are absent from destination: {missing}"
            )
        return {
            "group": selected_group,
            "destination_folder": destination,
            "topics": [resolve_discussion_topic(refreshed, topic["uuid"]) for topic in topics],
            "server_message": str(payload.get("msg") or ""),
            "verification": "all personal group topics appeared in the destination after refresh",
        }

    def delete_personal_group_topics(
        self,
        group: str,
        topic_queries: list[str],
    ) -> dict[str, Any]:
        selected_group, topics = self._personal_group_topics_for_queries(group, topic_queries)
        for topic in topics:
            operation_auth = topic.get("permissions", {}).get("operationAuth", {})
            if str(operation_auth.get("delete") or "0") != "1":
                raise ChaoxingAPIError(
                    f"current account cannot delete personal group topic {topic['uuid']}"
                )
        payload = self._personal_group_json_request(
            self._session(),
            f"/course/topic/{quote(selected_group['bbs_id'], safe='')}/batchDeleteTopics",
            "personal group topic batch deletion",
            method="POST",
            data={"uuids": ",".join(topic["uuid"] for topic in topics)},
            referer=selected_group["topics_url"],
        )
        for topic in topics:
            folder = topic["folder_id"] or ""
            remaining = self.list_personal_group_topics(selected_group["bbs_id"], folder=folder)[
                "topics"
            ]
            if any(item["uuid"] == topic["uuid"] for item in remaining):
                raise ChaoxingAPIError(
                    f"deleted personal group topic remains after refresh: {topic['uuid']}"
                )
        return {
            "group": selected_group,
            "deleted_topics": topics,
            "server_message": str(payload.get("msg") or ""),
            "verification": "all deleted personal group topics are absent after refresh",
        }

    def move_personal_group_topic_folders(
        self,
        group: str,
        folders: list[str],
        destination_folder: str,
    ) -> dict[str, Any]:
        if not folders:
            raise ChaoxingAPIError("at least one personal group topic folder is required")
        context = self._personal_group_topic_context(group)
        selected_group = context["group"]
        if not self._personal_group_can(selected_group, "modifyTopicFolder"):
            raise ChaoxingAPIError("current account cannot move topic folders in this group")
        tree = self.list_personal_group_topic_folder_tree(selected_group["bbs_id"])
        resolved = [
            self._resolve_personal_group_topic_folder(tree["folders"], query) for query in folders
        ]
        ids = [folder["folder_id"] for folder in resolved]
        if "0" in ids or len(set(ids)) != len(ids):
            raise ChaoxingAPIError("topic-folder move cannot include root or duplicates")
        destination = self._resolve_personal_group_topic_folder(tree["folders"], destination_folder)
        for folder in resolved:
            destination_path = {
                part for part in destination["path_ids"].strip("/").split("/") if part
            }
            if (
                destination["folder_id"] == folder["folder_id"]
                or folder["folder_id"] in destination_path
            ):
                raise ChaoxingAPIError("a personal group topic folder cannot move into itself")
        payload = self._personal_group_json_request(
            context["session"],
            f"/pc/topicFolder/{quote(selected_group['bbs_id'], safe='')}/batchMoveFolders",
            "personal group topic-folder batch move",
            method="POST",
            data={
                "targetFolder_uuid": destination["folder_uuid"],
                "folderIds": ",".join(ids),
            },
            referer=context["landing_url"],
        )
        refreshed = self.list_personal_group_topic_folder_tree(selected_group["bbs_id"])["folders"]
        moved = [
            self._resolve_personal_group_topic_folder(refreshed, folder_id) for folder_id in ids
        ]
        if any(folder["parent_id"] != destination["folder_id"] for folder in moved):
            raise ChaoxingAPIError("personal group topic-folder destinations differ after refresh")
        return {
            "group": selected_group,
            "destination_folder": destination,
            "folders": moved,
            "server_message": str(payload.get("msg") or ""),
            "verification": "all topic-folder destinations matched a fresh tree read",
        }

    def delete_personal_group_topic_folders(
        self,
        group: str,
        folders: list[str],
    ) -> dict[str, Any]:
        if not folders:
            raise ChaoxingAPIError("at least one personal group topic folder is required")
        context = self._personal_group_topic_context(group)
        selected_group = context["group"]
        if not self._personal_group_can(selected_group, "delTopicFolder"):
            raise ChaoxingAPIError("current account cannot delete topic folders in this group")
        tree = self.list_personal_group_topic_folder_tree(selected_group["bbs_id"])
        resolved = [
            self._resolve_personal_group_topic_folder(tree["folders"], query) for query in folders
        ]
        ids = [folder["folder_id"] for folder in resolved]
        if "0" in ids or len(set(ids)) != len(ids):
            raise ChaoxingAPIError("topic-folder deletion cannot include root or duplicates")
        payload = self._personal_group_json_request(
            context["session"],
            f"/course/topic/{quote(selected_group['bbs_id'], safe='')}/batchDeleteFolders",
            "personal group topic-folder batch deletion",
            method="POST",
            data={"folderIds": ",".join(ids)},
            referer=context["landing_url"],
        )
        remaining = self.list_personal_group_topic_folder_tree(selected_group["bbs_id"])["folders"]
        remaining_ids = {folder["folder_id"] for folder in remaining}
        if set(ids) & remaining_ids:
            raise ChaoxingAPIError("deleted personal group topic folders remain after refresh")
        return {
            "group": selected_group,
            "deleted_folders": resolved,
            "server_message": str(payload.get("msg") or ""),
            "verification": "all deleted topic folders are absent from a fresh tree read",
        }

    def move_personal_group_topic(
        self,
        group: str,
        topic_query: str,
        destination_folder: str,
    ) -> dict[str, Any]:
        before = self.read_personal_group_topic(group, topic_query)
        topic = before["topic"]
        operation_auth = topic.get("permissions", {}).get("operationAuth", {})
        if str(operation_auth.get("addTopicToFolder") or "0") != "1":
            raise ChaoxingAPIError("current account cannot move this personal group topic")
        tree = self.list_personal_group_topic_folder_tree(before["group"]["bbs_id"])
        destination = self._resolve_personal_group_topic_folder(tree["folders"], destination_folder)
        payload = self._personal_group_json_request(
            self._session(),
            f"/pc/topic/{quote(before['group']['bbs_id'], safe='')}/addTopicsToFolder",
            "personal group topic move",
            method="POST",
            data={
                "targetFolder_uuid": destination["folder_uuid"],
                "uuids": topic["uuid"],
            },
            referer=before["group"]["topics_url"],
        )
        refreshed = self.list_personal_group_topics(
            before["group"]["bbs_id"], folder=destination["folder_uuid"]
        )
        after = resolve_discussion_topic(refreshed["topics"], topic["uuid"])
        return {
            "group": before["group"],
            "before": topic,
            "destination_folder": destination,
            "topic": after,
            "server_message": str(payload.get("msg") or ""),
            "verification": "personal group topic appeared in the destination after refresh",
        }

    def _personal_group_topic_detail_context(
        self, group: dict[str, Any], topic_uuid: str
    ) -> dict[str, Any]:
        session = self._session()
        endpoint = GROUPWEB_BASE_URL + "/pc/topic/jumpToTopicDetail"
        try:
            response = session.get(
                endpoint,
                params={"bbsid": group["bbs_id"], "uuid": topic_uuid},
                headers={"Referer": group["topics_url"]},
                timeout=max(self.timeout, 60),
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"personal group topic detail page failed: {exc}") from exc
        html = self._decode(response)
        token_match = re.search(r"\burlToken\s*:\s*(['\"])(.*?)\1", html, flags=re.S)
        if not token_match:
            raise ChaoxingAPIError("personal group topic detail page did not expose urlToken")
        return {
            "session": session,
            "detail_url": response.url,
            "url_token": token_match.group(2),
        }

    def create_personal_group_topic_reply(
        self,
        group: str,
        topic_query: str,
        content: str,
        *,
        reply_to: str = "",
        anonymous: bool = False,
    ) -> dict[str, Any]:
        content = content.strip()
        if not content:
            raise ChaoxingAPIError("personal group topic reply content cannot be empty")
        before = self.read_personal_group_topic(group, topic_query)
        topic = before["topic"]
        operation_auth = topic.get("permissions", {}).get("operationAuth", {})
        if str(operation_auth.get("reply") or "0") != "1":
            raise ChaoxingAPIError("current account cannot reply to this personal group topic")
        parent = resolve_discussion_reply(before["replies"], reply_to) if reply_to else None
        context = self._personal_group_topic_detail_context(before["group"], topic["uuid"])
        reply_uuid = uuid4().hex
        payload = self._personal_group_json_request(
            context["session"],
            f"/pc/invitation/{quote(topic['uuid'], safe='')}/addReplys",
            "personal group topic reply creation",
            method="POST",
            data={
                "replyId": parent["reply_id"] if parent else "-1",
                "uuid": reply_uuid,
                "topic_content": quote(content, safe=""),
                "files_url": "",
                "files_attr": "",
                "urlToken": context["url_token"],
                "bbsid": before["group"]["bbs_id"],
                "anonymous": "1" if anonymous else "0",
            },
            referer=context["detail_url"],
        )
        if not isinstance(payload.get("datas"), dict):
            return {
                "group": before["group"],
                "topic": topic,
                "reply_uuid": reply_uuid,
                "reply_to": parent,
                "anonymous": anonymous,
                "pending_review": True,
                "server_message": str(payload.get("msg") or ""),
                "verification": "server accepted the personal group topic reply for review",
            }
        refreshed = self.read_personal_group_topic(group, topic["uuid"])
        created = resolve_discussion_reply(refreshed["replies"], reply_uuid)
        if created["content"] != content:
            raise ChaoxingAPIError("created personal group topic reply differs after refresh")
        return {
            "group": before["group"],
            "topic": topic,
            "reply": created,
            "reply_to": parent,
            "anonymous": anonymous,
            "pending_review": False,
            "server_message": str(payload.get("msg") or ""),
            "verification": f"created and re-read personal group topic reply {reply_uuid}",
        }

    def update_personal_group_topic_reply(
        self,
        group: str,
        topic_query: str,
        reply_query: str,
        content: str,
    ) -> dict[str, Any]:
        content = content.strip()
        if not content:
            raise ChaoxingAPIError("personal group topic reply content cannot be empty")
        before = self.read_personal_group_topic(group, topic_query)
        topic = before["topic"]
        reply = resolve_discussion_reply(before["replies"], reply_query)
        image_urls = [
            str(item.get("imgUrl") or item.get("url") or "")
            for item in reply.get("images", [])
            if isinstance(item, dict)
        ]
        files_url = ";".join(url for url in image_urls if url)
        files_attr = ",".join(
            json.dumps(item, ensure_ascii=False, separators=(",", ":"))
            for item in reply.get("attachments", [])
            if isinstance(item, dict)
        )
        context = self._personal_group_topic_detail_context(before["group"], topic["uuid"])
        payload = self._personal_group_json_request(
            context["session"],
            f"/pc/invitation/{quote(topic['uuid'], safe='')}/updateReply",
            "personal group topic reply update",
            method="POST",
            data={
                "uuid": reply["uuid"],
                "reply_content": quote(content, safe=""),
                "reply_files_url": quote(files_url, safe=""),
                "reply_files_attr": quote(files_attr, safe=""),
            },
            referer=context["detail_url"],
        )
        refreshed = self.read_personal_group_topic(group, topic["uuid"])
        updated = resolve_discussion_reply(refreshed["replies"], reply["uuid"])
        if updated["content"] != content:
            raise ChaoxingAPIError("updated personal group topic reply differs after refresh")
        return {
            "group": before["group"],
            "topic": topic,
            "before": reply,
            "reply": updated,
            "server_message": str(payload.get("msg") or ""),
            "verification": f"updated and re-read personal group topic reply {reply['uuid']}",
        }

    def delete_personal_group_topic_reply(
        self, group: str, topic_query: str, reply_query: str
    ) -> dict[str, Any]:
        before = self.read_personal_group_topic(group, topic_query)
        topic = before["topic"]
        reply = resolve_discussion_reply(before["replies"], reply_query)
        context = self._personal_group_topic_detail_context(before["group"], topic["uuid"])
        payload = self._personal_group_json_request(
            context["session"],
            f"/pc/invitation/{quote(topic['uuid'], safe='')}/deleteReply",
            "personal group topic reply deletion",
            method="POST",
            params={"uuid": reply["uuid"]},
            referer=context["detail_url"],
        )
        refreshed = self.read_personal_group_topic(group, topic["uuid"])
        try:
            resolve_discussion_reply(refreshed["replies"], reply["uuid"])
        except ChaoxingAPIError as exc:
            if "not found" not in str(exc):
                raise
        else:
            raise ChaoxingAPIError("deleted personal group topic reply still appears after refresh")
        return {
            "group": before["group"],
            "topic": topic,
            "deleted_reply": reply,
            "server_message": str(payload.get("msg") or ""),
            "verification": f"personal group topic reply {reply['uuid']} is absent after refresh",
        }

    def _inbox_json_request(
        self,
        session: requests.Session,
        url: str,
        operation: str,
        *,
        method: str = "GET",
        params: dict[str, Any] | None = None,
        data: dict[str, Any] | None = None,
        referer: str = "",
    ) -> dict[str, Any]:
        headers = {"Referer": referer} if referer else {}
        try:
            if method.upper() == "POST":
                response = session.post(
                    url,
                    params=params,
                    data=data,
                    headers=headers,
                    timeout=max(self.timeout, 60),
                )
            else:
                response = session.get(
                    url,
                    params=params,
                    headers=headers,
                    timeout=max(self.timeout, 60),
                )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"{operation} failed: {exc}") from exc
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError(f"{operation} returned invalid JSON") from exc
        if not isinstance(payload, dict):
            raise ChaoxingAPIError(f"{operation} returned invalid JSON")
        if payload.get("status") not in {True, "1"}:
            raise ChaoxingAPIError(str(payload.get("msg") or f"{operation} was rejected"))
        return payload

    def _personal_notice_editor_context(
        self,
        *,
        draft_uuid: str = "",
        notice_id: str = "",
        operation: str = "add",
    ) -> dict[str, Any]:
        session, landing, _module = self._personal_space_module_context("收件箱")
        params = {"sourceType": "0"}
        if draft_uuid:
            params["draft_uuid"] = draft_uuid
        if notice_id:
            params["noticeId"] = notice_id
        if operation != "add":
            params["type"] = operation
        try:
            response = session.get(
                NOTICE_BASE_URL + "/pc/notice/richtextNotice",
                params=params,
                headers={"Referer": landing.url},
                timeout=max(self.timeout, 60),
                allow_redirects=True,
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"personal notice editor request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError("personal notice editor was redirected to login")
        context = parse_personal_notice_compose_context(self._decode(response))
        user = context["user"]
        account_name = str(user.get("name") or "").strip()
        if not account_name or "\ufffd" in account_name:
            account_name = str(self.check_session().get("account_name") or "").strip()
        context["user"] = {
            "puid": str(user.get("puid") or ""),
            "user_id": str(user.get("uid") or ""),
            "fid": str(user.get("fid") or ""),
            "name": account_name,
            "picture_url": str(user.get("pic") or ""),
        }
        context.update(
            {
                "session": session,
                "landing_url": landing.url,
                "editor_url": response.url,
            }
        )
        return context

    def _resolve_personal_notice_people(
        self,
        selectors: list[str],
        editor: dict[str, Any],
    ) -> list[dict[str, Any]]:
        if not selectors:
            raise ChaoxingAPIError("at least one personal notice recipient is required")
        current = editor["user"]
        current_puid = str(current.get("puid") or "")
        current_name = str(current.get("name") or "").strip()
        people: list[dict[str, Any]] = []
        seen: set[str] = set()
        for selector in selectors:
            query = str(selector or "").strip()
            if not query:
                continue
            if query.lower() in {"me", "myself", "self"} or query in {"我", "本人", "自己"}:
                person = dict(current)
            elif current_puid and query == current_puid:
                person = dict(current)
            elif current_name and query == current_name:
                person = dict(current)
            else:
                person = dict(self._resolve_known_contact_person(query))
            puid = str(person.get("puid") or "").strip()
            if not puid:
                raise ChaoxingAPIError(f"personal notice recipient has no PUID: {query}")
            if puid in seen:
                continue
            seen.add(puid)
            person["puid"] = puid
            person["name"] = str(person.get("name") or puid).strip()
            people.append(person)
        if not people:
            raise ChaoxingAPIError("at least one personal notice recipient is required")
        return people

    @staticmethod
    def _personal_notice_receiver_objects(
        people: list[dict[str, Any]],
    ) -> tuple[list[dict[str, Any]], list[dict[str, Any]], list[dict[str, Any]]]:
        receivers = [
            {"type": 1, "puid": person["puid"], "name": person["name"]} for person in people
        ]
        recent = [
            {
                "id": person["puid"],
                "type": 1,
                "ext": "",
                "name": person["name"],
                "pic": (
                    [person["picture_url"]] if str(person.get("picture_url") or "").strip() else []
                ),
            }
            for person in people
        ]
        orderly = [
            {
                "name": person["name"],
                "opt": 0,
                "puid": person["puid"],
                "type": 1,
            }
            for person in people[:20]
        ]
        return receivers, recent, orderly

    @staticmethod
    def _personal_notice_content(content: str, content_format: str) -> tuple[str, str]:
        normalized_format = str(content_format or "plain").strip().lower()
        if normalized_format not in {"plain", "html"}:
            raise ChaoxingAPIError("personal notice content_format must be plain or html")
        if normalized_format == "html":
            rich_content = content.strip()
            plain_content = html_text(rich_content, limit=1_000_000)
        else:
            plain_content = content.strip()
            rich_content = ChaoxingAPI._notice_rtf(plain_content)
        if not plain_content and not rich_content:
            raise ChaoxingAPIError("personal notice content cannot be empty")
        return plain_content, rich_content

    def send_personal_notice(
        self,
        recipients: list[str],
        title: str,
        content: str,
        *,
        content_format: str = "plain",
        allow_comments: bool = True,
        show_comments: bool = True,
        hide_read_status: bool = False,
        forbid_forwarding: bool = False,
        permission_password: str = "",
    ) -> dict[str, Any]:
        title = title.strip()
        if not title:
            raise ChaoxingAPIError("personal notice title is required")
        plain_content, rich_content = self._personal_notice_content(content, content_format)
        editor = self._personal_notice_editor_context()
        people = self._resolve_personal_notice_people(recipients, editor)
        _receiver_objects, recent, orderly = self._personal_notice_receiver_objects(people)
        result = self._inbox_json_request(
            editor["session"],
            NOTICE_BASE_URL + "/pc/notice/addNotice",
            "personal notice send",
            method="POST",
            data={
                "recentReceiver": json.dumps(recent, ensure_ascii=False, separators=(",", ":")),
                "toccRecentReceiver": "[]",
                "uuid": editor["uuid"],
                "uuidEnc": editor["uuid_enc"],
                "signId": "",
                "passportId": editor["user"]["puid"],
                "passportName": editor["user"]["name"],
                "source_type": "0",
                "noticeIdCode": "",
                "title": title,
                "content": plain_content,
                "puids": ",".join(person["puid"] for person in people),
                "deptids": "",
                "chatids": "",
                "circles": "",
                "clazzs": "",
                "togen": "",
                "tocc": "",
                "pcode": str(permission_password or ""),
                "issuingPuid": editor["issuing_puid"],
                "sendType": "0",
                "sendSetting": "",
                "sendSettingSign": "",
                "allow_comments": "0" if allow_comments else "1",
                "attr_file": "",
                "imgs": "",
                "isRtf": "1",
                "rtf_content": rich_content,
                "oType": editor["original_type"],
                "oId": editor["original_id"],
                "oCustomParams": editor["original_custom_parameters"],
                "oEnc": editor["original_encoding"],
                "foldId": editor["folder_id"],
                "orderlyReceive": json.dumps(orderly, ensure_ascii=False, separators=(",", ":")),
                "receiveUnreadReminds": "{}",
                "sendUnreadReminds": "{}",
                "letter_mode": "",
                "visible": "1" if forbid_forwarding else "0",
                "showRead": "2" if hide_read_status else "0",
                "showComments": "0" if show_comments else "1",
                "showReceiver": "",
                "nonRecCanReadAttachment": "0",
                "tag": editor["tag"],
                "tagEnc": editor["tag_encoding"],
                "fidsCode": editor["fid_codes"],
                "useTestQueue": "0",
                "urgentUuid": "",
                "categoryUuid": "",
            },
            referer=editor["editor_url"],
        )
        message = result.get("msg") if isinstance(result.get("msg"), dict) else {}
        returned_id = str(
            message.get("idCode") or message.get("noticeIdCode") or result.get("idCode") or ""
        )
        returned_uuid = str(message.get("uuid") or result.get("uuid") or "")
        sent_items = self.list_inbox_notices(scope="sent", search=title, max_items=1000)["notices"]
        sent = self._resolve_inbox_notice(sent_items, returned_id or returned_uuid or title)
        if sent["title"] != title:
            raise ChaoxingAPIError("sent personal notice title differs after refresh")
        self_received: dict[str, Any] | None = None
        if editor["user"]["puid"] in {person["puid"] for person in people}:
            received_items = self.list_inbox_notices(
                scope="received", search=title, max_items=1000
            )["notices"]
            self_received = self._resolve_inbox_notice(received_items, title)
        return {
            "recipients": people,
            "notice": sent,
            "self_received_notice": self_received,
            "server_message": result.get("msg"),
            "verification": (
                "sent notice matched a fresh sent-list read"
                + (
                    " and its self-recipient copy matched a fresh received-list read"
                    if self_received
                    else ""
                )
            ),
        }

    def list_personal_notice_drafts(
        self,
        *,
        search: str = "",
        max_items: int = 1000,
    ) -> dict[str, Any]:
        if not 1 <= max_items <= 10000:
            raise ChaoxingAPIError("max_items must be between 1 and 10000")
        session, landing, _module = self._personal_space_module_context("收件箱")
        referer = NOTICE_BASE_URL + "/pc/draft/notice/noticeDraftBox"
        drafts: list[dict[str, Any]] = []
        seen: set[str] = set()
        offset = ""
        pages = 0
        truncated = False
        while pages < 100:
            payload = self._inbox_json_request(
                session,
                NOTICE_DRAFT_LIST_URL,
                "personal notice draft list",
                method="POST",
                data={
                    "offsetValue": offset,
                    "pageSize": 1000,
                    "kw": str(search or "").strip(),
                    "courseId": "",
                },
                referer=referer or landing.url,
            )
            page_items, next_offset, last_page = parse_notice_draft_payload(payload)
            pages += 1
            for item in page_items:
                source_type = item.get("source_type")
                if str(source_type if source_type is not None else "") != "0":
                    continue
                identity = item["draft_id"] or item["draft_uuid"]
                if identity in seen:
                    continue
                seen.add(identity)
                drafts.append(item)
                if len(drafts) >= max_items:
                    truncated = not last_page or len(page_items) > len(drafts)
                    break
            if len(drafts) >= max_items or last_page or not next_offset:
                break
            if next_offset == offset:
                raise ChaoxingAPIError("personal notice draft cursor did not advance")
            offset = next_offset
        for index, draft in enumerate(drafts, 1):
            draft["index"] = index
        return {
            "search": str(search or "").strip(),
            "count": len(drafts),
            "max_items": max_items,
            "truncated": truncated,
            "drafts": drafts,
            "verification": f"read {len(drafts)} personal notice drafts through HTTP",
        }

    def save_personal_notice_draft(
        self,
        title: str,
        content: str,
        *,
        recipients: list[str] | None = None,
        draft_query: str = "",
        content_format: str = "plain",
        allow_comments: bool = True,
        show_comments: bool = True,
        hide_read_status: bool = False,
        forbid_forwarding: bool = False,
    ) -> dict[str, Any]:
        title = title.strip()
        if not title:
            raise ChaoxingAPIError("personal notice draft title is required")
        plain_content, rich_content = self._personal_notice_content(content, content_format)
        before: dict[str, Any] | None = None
        if draft_query:
            before = resolve_notice_draft(
                self.list_personal_notice_drafts(max_items=10000)["drafts"],
                draft_query,
            )
        editor = self._personal_notice_editor_context(
            draft_uuid=str(before.get("draft_uuid") or "") if before else "",
            notice_id=str(before.get("notice_id") or "") if before else "",
            operation=str(before.get("operation") or "add") if before else "add",
        )
        selectors = recipients
        if selectors is None and before:
            selectors = [
                str(item.get("puid") or "")
                for item in before.get("recipients", [])
                if isinstance(item, dict) and str(item.get("type") or "") == "1"
            ]
        people = self._resolve_personal_notice_people(selectors, editor) if selectors else []
        receiver_objects, _recent, orderly = self._personal_notice_receiver_objects(people)
        payload = self._inbox_json_request(
            editor["session"],
            PERSONAL_NOTICE_DRAFT_SAVE_URL,
            "personal notice draft save",
            method="POST",
            data={
                "draft_uuid": str(before.get("draft_uuid") or "") if before else "",
                "noticeId": str(before.get("notice_id") or "") if before else "",
                "draft_version": str(before.get("version") or "0") if before else "0",
                "source_type": "0",
                "title": title,
                "content": plain_content,
                "puids": (
                    json.dumps(receiver_objects, ensure_ascii=False, separators=(",", ":"))
                    if receiver_objects
                    else ""
                ),
                "tocc": "",
                "issuingPuid": editor["issuing_puid"],
                "attr_file": "",
                "imgs": "",
                "isRtf": "1",
                "rtf_content": rich_content,
                "operType": str(before.get("operation") or "add") if before else "add",
                "oType": editor["original_type"],
                "oId": editor["original_id"],
                "oCustomParams": editor["original_custom_parameters"],
                "foldId": editor["folder_id"],
                "uuid": (str(before.get("notice_uuid") or "") if before else editor["uuid"]),
                "uuidEnc": editor["uuid_enc"],
                "oEnc": editor["original_encoding"],
                "pcode": "",
                "signId": "",
                "sendSetting": "",
                "sendSettingSign": "",
                "orderlyReceive": json.dumps(orderly, ensure_ascii=False, separators=(",", ":")),
                "receiveUnreadReminds": "{}",
                "sendUnreadReminds": "{}",
                "letter_mode": "",
                "visible": "1" if forbid_forwarding else "0",
                "allow_comments": "0" if allow_comments else "1",
                "showRead": "2" if hide_read_status else "0",
                "showComments": "0" if show_comments else "1",
                "nonRecCanReadAttachment": "0",
                "draftType": "0",
                "sendTime": "",
                "sendType": "0",
                "tagEnc": editor["tag_encoding"],
            },
            referer=editor["editor_url"],
        )
        message = payload.get("msg") if isinstance(payload.get("msg"), dict) else {}
        returned_id = str(message.get("id") or payload.get("id") or "")
        after = resolve_notice_draft(
            self.list_personal_notice_drafts(search=title, max_items=1000)["drafts"],
            returned_id or title,
        )
        if after["title"] != title or after["content"] != plain_content:
            raise ChaoxingAPIError("personal notice draft title or content differs after refresh")
        return {
            "before": before,
            "draft": after,
            "recipients": people,
            "verification": (
                "personal notice draft title and content matched a fresh HTTP draft-list read"
            ),
        }

    def delete_personal_notice_draft(self, draft: str) -> dict[str, Any]:
        before = resolve_notice_draft(
            self.list_personal_notice_drafts(max_items=10000)["drafts"],
            draft,
        )
        session, landing, _module = self._personal_space_module_context("收件箱")
        self._inbox_json_request(
            session,
            NOTICE_DRAFT_DELETE_URL,
            "personal notice draft deletion",
            method="POST",
            data={"ids": before["draft_id"]},
            referer=NOTICE_BASE_URL + "/pc/draft/notice/noticeDraftBox" or landing.url,
        )
        remaining = self.list_personal_notice_drafts(search=before["title"], max_items=10000)[
            "drafts"
        ]
        if any(item["draft_id"] == before["draft_id"] for item in remaining):
            raise ChaoxingAPIError("deleted personal notice draft still appears after refresh")
        return {
            "deleted": before,
            "verification": "deleted personal notice draft is absent after refresh",
        }

    @staticmethod
    def _normalize_inbox_notice(
        notice: dict[str, Any],
        index: int = 0,
        *,
        placement: str = "normal",
    ) -> dict[str, Any]:
        def integer(value: Any) -> int:
            try:
                return int(value or 0)
            except (TypeError, ValueError):
                return 0

        notice_id = str(notice.get("idCode") or notice.get("noticeId") or "")
        notice_uuid = str(notice.get("uuid") or "")
        send_tag = integer(notice.get("sendTag"))
        unread = integer(notice.get("isread")) == 0 and integer(notice.get("redDot")) == 0
        attachments = notice.get("attachment") if isinstance(notice.get("attachment"), list) else []
        images = notice.get("imgs") if isinstance(notice.get("imgs"), list) else []
        source_url = str(notice.get("sourceUrl") or "").strip()
        detail_key = notice_uuid or notice_id
        detail_url = source_url or NOTICE_BASE_URL + "/pc/notice/" + quote(
            detail_key, safe="$-"
        ) + "/detail?" + urlencode({"sendTag": send_tag})
        return {
            "index": index,
            "notice_id": notice_id,
            "uuid": notice_uuid,
            "title": str(notice.get("title") or ""),
            "content": str(notice.get("content") or ""),
            "content_html": str(notice.get("rtf_content") or ""),
            "is_rich_text": str(notice.get("isRtf") or "0") == "1",
            "creator_id": str(notice.get("createrId") or ""),
            "creator_puid": str(notice.get("createrPuid") or ""),
            "creator_name": str(notice.get("createrName") or ""),
            "recipient_names": notice.get("toNames") or [],
            "cc_names": notice.get("toCcNames") or [],
            "inserted_at": notice.get("insertTime"),
            "sent_at": notice.get("sendTime"),
            "completed_at": notice.get("completeTime"),
            "scope": "sent" if send_tag == 1 else "received",
            "send_tag": send_tag,
            "is_read": not unread,
            "is_collected": integer(notice.get("collect")) == 1,
            "is_top": integer(notice.get("top")) == 1 or placement == "top",
            "placement": placement,
            "status": integer(notice.get("status")),
            "source_type": integer(notice.get("sourceType")),
            "read_count": integer(notice.get("count_read")),
            "recipient_count": integer(notice.get("count_all")),
            "other_read_count": integer(notice.get("otherReadCount")),
            "allow_comments": integer(notice.get("allowComments")) == 1,
            "attachments": attachments,
            "images": images,
            "detail_url": detail_url,
            "source_url": source_url,
            "folder_uuid": str(notice.get("folderUUID") or ""),
            "folder_name": str(notice.get("folderName") or ""),
            "can_mark_unread": send_tag == 0 and not unread,
            "can_delete": True,
        }

    @staticmethod
    def _normalize_inbox_folder(folder: dict[str, Any], index: int = 0) -> dict[str, Any]:
        def integer(value: Any) -> int:
            try:
                return int(value or 0)
            except (TypeError, ValueError):
                return 0

        return {
            "index": index,
            "folder_uuid": str(folder.get("uuid") or folder.get("folderUUID") or ""),
            "name": str(folder.get("folderName") or folder.get("name") or ""),
            "is_top": integer(folder.get("top")) == 1,
            "order": integer(folder.get("order") or folder.get("folderOrder")),
            "notice_count": integer(folder.get("noticeCount") or folder.get("count")),
            "unread_count": integer(folder.get("noReadCount") or folder.get("unreadCount")),
            "sender_filter": str(folder.get("senderName") or ""),
            "keyword_filter": str(folder.get("keywordName") or ""),
        }

    @staticmethod
    def _resolve_inbox_folder(
        folders: list[dict[str, Any]],
        query: str,
    ) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("inbox folder name, UUID, or index is required")
        for key in ("folder_uuid", "index", "name"):
            exact = [
                folder
                for folder in folders
                if str(folder.get(key) or "").strip().lower() == normalized
            ]
            if len(exact) == 1:
                return exact[0]
            if len(exact) > 1:
                choices = ", ".join(
                    f"{folder['name']} ({folder['folder_uuid']})" for folder in exact[:20]
                )
                raise ChaoxingAPIError(f"multiple inbox folders match: {choices}")
        partial = [folder for folder in folders if normalized in folder["name"].lower()]
        if len(partial) == 1:
            return partial[0]
        if not partial:
            raise ChaoxingAPIError(f"inbox folder not found: {query}")
        choices = ", ".join(
            f"{folder['name']} ({folder['folder_uuid']})" for folder in partial[:20]
        )
        raise ChaoxingAPIError(f"multiple inbox folders match: {choices}")

    def list_inbox_folders(self) -> dict[str, Any]:
        session, landing, _module = self._personal_space_module_context("收件箱")
        payload = self._inbox_json_request(
            session,
            NOTICE_BASE_URL + "/pc/notice/getNoticeFolders",
            "inbox folder list",
            method="POST",
            data={},
            referer=landing.url,
        )
        raw_folders = payload.get("msg")
        folders = [
            self._normalize_inbox_folder(raw, index)
            for index, raw in enumerate(raw_folders if isinstance(raw_folders, list) else [], 1)
            if isinstance(raw, dict)
        ]
        return {
            "count": len(folders),
            "folders": folders,
            "verification": f"read {len(folders)} personal inbox folders through HTTP",
        }

    def _find_inbox_folder(self, folder: str) -> dict[str, Any]:
        return self._resolve_inbox_folder(self.list_inbox_folders()["folders"], folder)

    @staticmethod
    def _normalize_inbox_sender_rules(rules: Any) -> list[dict[str, Any]]:
        if rules is None:
            return []
        if not isinstance(rules, list):
            raise ChaoxingAPIError("inbox folder sender_rules must be a list")
        if len(rules) > 10:
            raise ChaoxingAPIError("an inbox folder supports at most 10 sender rules")
        normalized: list[dict[str, Any]] = []
        seen: set[tuple[int, str]] = set()
        for raw in rules:
            if not isinstance(raw, dict):
                raise ChaoxingAPIError("each inbox folder sender rule must be an object")
            raw_type = raw.get("type", 1)
            if str(raw_type).strip().lower() in {"1", "person", "user"}:
                rule_type = 1
            elif str(raw_type).strip().lower() in {"3", "department", "dept"}:
                rule_type = 3
            else:
                raise ChaoxingAPIError("sender rule type must be person/user/1 or dept/3")
            data_id = str(
                raw.get("dataId")
                or raw.get("data_id")
                or raw.get("puid")
                or raw.get("department_id")
                or ""
            ).strip()
            if not data_id:
                raise ChaoxingAPIError("each inbox folder sender rule requires data_id")
            identity = (rule_type, data_id)
            if identity in seen:
                continue
            seen.add(identity)
            rule: dict[str, Any] = {
                "dataId": data_id,
                "type": rule_type,
                "name": str(raw.get("name") or data_id).strip(),
            }
            if rule_type == 3:
                rule["funDept"] = 1
            normalized.append(rule)
        return normalized

    @staticmethod
    def _normalize_inbox_keyword_rules(rules: Any) -> list[dict[str, int | str]]:
        if rules is None:
            return []
        if not isinstance(rules, list):
            raise ChaoxingAPIError("inbox folder keywords must be a list")
        if len(rules) > 10:
            raise ChaoxingAPIError("an inbox folder supports at most 10 keyword rules")
        normalized: list[dict[str, int | str]] = []
        for index, raw in enumerate(rules):
            if isinstance(raw, str):
                keyword = raw.strip()
                logic = 0
                match_type = 0
            elif isinstance(raw, dict):
                keyword = str(raw.get("keyword") or "").strip()
                raw_logic = str(raw.get("logic", 0)).strip().lower()
                logic = 1 if raw_logic in {"1", "or", "any", "或"} else 0
                raw_match = str(raw.get("type", 0)).strip().lower()
                match_type = 1 if raw_match in {"1", "not_contains", "exclude", "不包含"} else 0
            else:
                raise ChaoxingAPIError("each inbox folder keyword rule must be text or an object")
            if not keyword:
                raise ChaoxingAPIError("inbox folder keyword text cannot be empty")
            if len(keyword) > 10:
                raise ChaoxingAPIError("inbox folder keyword text cannot exceed 10 characters")
            normalized.append(
                {
                    "keyword": keyword,
                    "logic": 0 if index == 0 else logic,
                    "type": match_type,
                }
            )
        return normalized

    def read_inbox_folder_filters(self, folder: str) -> dict[str, Any]:
        selected = self._find_inbox_folder(folder)
        session, landing, _module = self._personal_space_module_context("收件箱")
        payload = self._inbox_json_request(
            session,
            NOTICE_BASE_URL + "/pc/notice/getFolderFilters",
            "inbox folder filter read",
            method="POST",
            data={"folderId": selected["folder_uuid"], "lastId": ""},
            referer=landing.url,
        )
        raw_filters = payload.get("filters")
        sender_rules: list[dict[str, Any]] = []
        for raw in raw_filters if isinstance(raw_filters, list) else []:
            if not isinstance(raw, dict):
                continue
            sender_rules.append(
                {
                    "filter_id": str(raw.get("id") or raw.get("filterId") or ""),
                    "data_id": str(raw.get("dataId") or ""),
                    "type": int(raw.get("type") or 0),
                    "name": str(raw.get("name") or raw.get("dataName") or ""),
                    "is_functional_department": str(raw.get("funDept") or "0") == "1",
                }
            )
        keyword_rules: list[dict[str, int | str]] = []
        raw_keywords = payload.get("keywordRules")
        if isinstance(raw_keywords, str) and raw_keywords.strip():
            try:
                decoded_keywords = json.loads(raw_keywords)
            except json.JSONDecodeError as exc:
                raise ChaoxingAPIError("inbox folder keyword rules returned invalid JSON") from exc
            keyword_rules = self._normalize_inbox_keyword_rules(
                decoded_keywords.get("keyword", []) if isinstance(decoded_keywords, dict) else []
            )
        elif isinstance(raw_keywords, dict):
            keyword_rules = self._normalize_inbox_keyword_rules(raw_keywords.get("keyword", []))
        refreshed = dict(selected)
        if payload.get("folderName") is not None:
            refreshed["name"] = str(payload.get("folderName") or "")
        return {
            "folder": refreshed,
            "sender_rules": sender_rules,
            "keyword_rules": keyword_rules,
            "keyword_filter_id": str(payload.get("keywordId") or ""),
            "verification": f"read filters for inbox folder {selected['folder_uuid']} through HTTP",
        }

    def create_inbox_folder(
        self,
        name: str,
        *,
        sender_rules: list[dict[str, Any]] | None = None,
        keywords: list[dict[str, Any] | str] | None = None,
    ) -> dict[str, Any]:
        name = name.strip()
        if not name:
            raise ChaoxingAPIError("inbox folder name is required")
        if len(name) > 16:
            raise ChaoxingAPIError("inbox folder name cannot exceed 16 characters")
        before = self.list_inbox_folders()["folders"]
        if any(folder["name"] == name for folder in before):
            raise ChaoxingAPIError(f"an inbox folder already has the name: {name}")
        normalized_senders = self._normalize_inbox_sender_rules(sender_rules)
        normalized_keywords = self._normalize_inbox_keyword_rules(keywords)
        session, landing, _module = self._personal_space_module_context("收件箱")
        payload = self._inbox_json_request(
            session,
            NOTICE_BASE_URL + "/pc/notice/addFolder",
            "inbox folder creation",
            method="POST",
            data={
                "folderName": name,
                "rules": json.dumps(normalized_senders, ensure_ascii=False, separators=(",", ":")),
                "keywordRule": (
                    json.dumps(
                        {"keyword": normalized_keywords},
                        ensure_ascii=False,
                        separators=(",", ":"),
                    )
                    if normalized_keywords
                    else ""
                ),
            },
            referer=landing.url,
        )
        returned = payload.get("msg") if isinstance(payload.get("msg"), dict) else {}
        returned_uuid = str(returned.get("uuid") or returned.get("folderUUID") or "")
        created = self._resolve_inbox_folder(
            self.list_inbox_folders()["folders"], returned_uuid or name
        )
        filters = self.read_inbox_folder_filters(created["folder_uuid"])
        return {
            "folder": created,
            "filters": filters,
            "verification": "created inbox folder and matched it in fresh folder/filter reads",
        }

    @staticmethod
    def _inbox_sender_rule_signature(rules: list[dict[str, Any]]) -> list[tuple[int, str, str]]:
        return sorted(
            (
                int(rule.get("type") or 0),
                str(rule.get("data_id") or rule.get("dataId") or ""),
                str(rule.get("name") or ""),
            )
            for rule in rules
        )

    @staticmethod
    def _inbox_keyword_rule_signature(
        rules: list[dict[str, Any]],
    ) -> list[tuple[str, int, int]]:
        return [
            (
                str(rule.get("keyword") or ""),
                int(rule.get("logic") or 0),
                int(rule.get("type") or 0),
            )
            for rule in rules
        ]

    def update_inbox_folder(
        self,
        folder: str,
        *,
        name: str | None = None,
        sender_rules: list[dict[str, Any]] | None = None,
        keywords: list[dict[str, Any] | str] | None = None,
    ) -> dict[str, Any]:
        before = self.read_inbox_folder_filters(folder)
        selected = before["folder"]
        desired_name = str(name if name is not None else selected["name"]).strip()
        if not desired_name:
            raise ChaoxingAPIError("inbox folder name is required")
        if len(desired_name) > 16:
            raise ChaoxingAPIError("inbox folder name cannot exceed 16 characters")
        if name is None and sender_rules is None and keywords is None:
            raise ChaoxingAPIError("at least one inbox folder change is required")

        if sender_rules is None:
            desired_senders = before["sender_rules"]
            new_sender_rules: list[dict[str, Any]] = []
            deleted_sender_ids: list[str] = []
        else:
            desired_senders = self._normalize_inbox_sender_rules(sender_rules)
            new_sender_rules = desired_senders
            deleted_sender_ids = [
                str(rule.get("filter_id") or "")
                for rule in before["sender_rules"]
                if str(rule.get("filter_id") or "")
            ]

        if keywords is None:
            desired_keywords = before["keyword_rules"]
            deleted_keyword_ids: list[str] = []
        else:
            desired_keywords = self._normalize_inbox_keyword_rules(keywords)
            deleted_keyword_ids = (
                [before["keyword_filter_id"]]
                if not desired_keywords and before["keyword_filter_id"]
                else []
            )

        session, landing, _module = self._personal_space_module_context("收件箱")
        self._inbox_json_request(
            session,
            NOTICE_BASE_URL + "/pc/notice/updateFolder",
            "inbox folder update",
            params={
                "folderId": selected["folder_uuid"],
                "folderName": desired_name,
                "rules": json.dumps(
                    new_sender_rules,
                    ensure_ascii=False,
                    separators=(",", ":"),
                ),
                "keywordRule": (
                    json.dumps(
                        {"keyword": desired_keywords},
                        ensure_ascii=False,
                        separators=(",", ":"),
                    )
                    if desired_keywords
                    else ""
                ),
                "delFilterIds": json.dumps(deleted_sender_ids, separators=(",", ":")),
                "delKeywordFilterIds": json.dumps(
                    deleted_keyword_ids,
                    separators=(",", ":"),
                ),
            },
            referer=landing.url,
        )
        after = self.read_inbox_folder_filters(selected["folder_uuid"])
        if after["folder"]["name"] != desired_name:
            raise ChaoxingAPIError("inbox folder name differs after refresh")
        if self._inbox_sender_rule_signature(after["sender_rules"]) != (
            self._inbox_sender_rule_signature(desired_senders)
        ):
            raise ChaoxingAPIError("inbox folder sender rules differ after refresh")
        if self._inbox_keyword_rule_signature(after["keyword_rules"]) != (
            self._inbox_keyword_rule_signature(desired_keywords)
        ):
            raise ChaoxingAPIError("inbox folder keyword rules differ after refresh")
        return {
            "before": before,
            "after": after,
            "verification": "inbox folder name and filters matched a fresh HTTP read",
        }

    def delete_inbox_folder(self, folder: str) -> dict[str, Any]:
        selected = self._find_inbox_folder(folder)
        session, landing, _module = self._personal_space_module_context("收件箱")
        self._inbox_json_request(
            session,
            NOTICE_BASE_URL + "/pc/notice/delFolderOrNotice",
            "inbox folder deletion",
            method="POST",
            data={
                "folder_uuids": selected["folder_uuid"],
                "noticeIds": "",
                "sendTag": 0,
            },
            referer=landing.url,
        )
        remaining = self.list_inbox_folders()["folders"]
        if any(item["folder_uuid"] == selected["folder_uuid"] for item in remaining):
            raise ChaoxingAPIError("deleted inbox folder still appears after refresh")
        return {
            "deleted": selected,
            "verification": "deleted inbox folder is absent after a fresh folder-list read",
        }

    def reorder_inbox_folders(
        self,
        folders: list[str],
        *,
        top: bool = False,
    ) -> dict[str, Any]:
        current = self.list_inbox_folders()["folders"]
        group = [folder for folder in current if folder["is_top"] is bool(top)]
        if not group:
            raise ChaoxingAPIError("the selected inbox folder group is empty")
        selected = [self._resolve_inbox_folder(group, query) for query in folders]
        selected_ids = [folder["folder_uuid"] for folder in selected]
        expected_ids = [folder["folder_uuid"] for folder in group]
        if len(selected_ids) != len(set(selected_ids)) or set(selected_ids) != set(expected_ids):
            raise ChaoxingAPIError(
                "folder order must include every folder in the selected group exactly once"
            )
        group_key = "top" if top else "default"
        folder_orders = {
            group_key: [
                {"uuid": folder_uuid, "order": len(selected_ids) - index}
                for index, folder_uuid in enumerate(selected_ids)
            ]
        }
        session, landing, _module = self._personal_space_module_context("收件箱")
        self._inbox_json_request(
            session,
            NOTICE_BASE_URL + "/pc/notice/folderOrder",
            "inbox folder reorder",
            method="POST",
            data={
                "folderOrders": json.dumps(
                    folder_orders,
                    ensure_ascii=False,
                    separators=(",", ":"),
                )
            },
            referer=landing.url,
        )
        refreshed = [
            folder
            for folder in self.list_inbox_folders()["folders"]
            if folder["is_top"] is bool(top)
        ]
        refreshed_ids = [folder["folder_uuid"] for folder in refreshed]
        if refreshed_ids != selected_ids:
            raise ChaoxingAPIError("inbox folder order differs after refresh")
        return {
            "top": bool(top),
            "folders": refreshed,
            "verification": "inbox folder order matched a fresh folder-list read",
        }

    @staticmethod
    def _resolve_inbox_notice(
        notices: list[dict[str, Any]],
        query: str,
    ) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("inbox notice title, ID, UUID, or index is required")
        for key in ("notice_id", "uuid", "index", "title"):
            exact = [
                notice
                for notice in notices
                if str(notice.get(key) or "").strip().lower() == normalized
            ]
            if len(exact) == 1:
                return exact[0]
            if len(exact) > 1:
                choices = ", ".join(
                    f"{notice['title']} ({notice['notice_id']})" for notice in exact[:20]
                )
                raise ChaoxingAPIError(f"multiple inbox notices match: {choices}")
        partial = [notice for notice in notices if normalized in notice["title"].lower()]
        if len(partial) == 1:
            return partial[0]
        if not partial:
            raise ChaoxingAPIError(f"inbox notice not found: {query}")
        choices = ", ".join(f"{notice['title']} ({notice['notice_id']})" for notice in partial[:20])
        raise ChaoxingAPIError(f"multiple inbox notices match: {choices}")

    def list_inbox_notices(
        self,
        *,
        scope: str = "received",
        folder_uuid: str = "",
        search: str = "",
        sender: str = "",
        start_time: str = "",
        end_time: str = "",
        max_items: int = 1000,
    ) -> dict[str, Any]:
        normalized_scope = str(scope or "received").strip().lower()
        if normalized_scope not in {"received", "sent"}:
            raise ChaoxingAPIError("scope must be received or sent")
        if not 1 <= max_items <= 10000:
            raise ChaoxingAPIError("max_items must be between 1 and 10000")
        session, landing, _module = self._personal_space_module_context("收件箱")
        notices: list[dict[str, Any]] = []
        seen: set[str] = set()
        folders: list[dict[str, Any]] = []
        last_value = ""
        truncated = False
        last_page = False
        for page in range(1, 501):
            payload = self._inbox_json_request(
                session,
                NOTICE_BASE_URL + "/pc/notice/getNoticeList",
                "inbox notice list",
                method="POST",
                data={
                    "type": "1" if normalized_scope == "sent" else "2",
                    "notice_type": "",
                    "lastValue": last_value,
                    "sort": "",
                    "folderUUID": str(folder_uuid or "").strip(),
                    "kw": str(search or "").strip(),
                    "startTime": str(start_time or "").strip(),
                    "endTime": str(end_time or "").strip(),
                    "gKw": "",
                    "gName": str(sender or "").strip(),
                    "year": "",
                    "tag": "",
                    "fidsCode": "",
                    "queryFolderNoticePrevYear": 0,
                    "filterSenderPuids": "",
                    "filterTags": "",
                },
                referer=landing.url,
            )
            if page == 1:
                raw_folders = payload.get("folders")
                if isinstance(raw_folders, list):
                    for raw in raw_folders:
                        if not isinstance(raw, dict):
                            continue
                        folders.append(
                            {
                                "index": len(folders) + 1,
                                "folder_uuid": str(raw.get("uuid") or ""),
                                "name": str(raw.get("folderName") or ""),
                                "is_top": str(raw.get("top") or "0") == "1",
                                "unread_count": int(raw.get("noReadCount") or 0),
                                "sender_filter": str(raw.get("senderName") or ""),
                                "keyword_filter": str(raw.get("keywordName") or ""),
                            }
                        )
            batches = (
                ("top", payload.get("topNotices")),
                ("urgent", payload.get("urgentNotices")),
                (
                    "normal",
                    (
                        payload.get("notices", {}).get("list")
                        if isinstance(payload.get("notices"), dict)
                        else []
                    ),
                ),
            )
            page_count = 0
            for placement, raw_items in batches:
                if not isinstance(raw_items, list):
                    continue
                for raw in raw_items:
                    if not isinstance(raw, dict):
                        continue
                    identity = str(raw.get("idCode") or raw.get("uuid") or "")
                    if not identity or identity in seen:
                        continue
                    seen.add(identity)
                    normalized_notice = self._normalize_inbox_notice(
                        raw,
                        len(notices) + 1,
                        placement=placement,
                    )
                    if folder_uuid and not normalized_notice["folder_uuid"]:
                        normalized_notice["folder_uuid"] = str(folder_uuid)
                    notices.append(normalized_notice)
                    page_count += 1
                    if len(notices) >= max_items:
                        truncated = True
                        break
                if truncated:
                    break
            if truncated:
                break
            notice_page = payload.get("notices")
            if not isinstance(notice_page, dict):
                last_page = True
                break
            last_page = str(notice_page.get("lastPage") or "0") in {"1", "true", "True"}
            next_value = str(notice_page.get("lastGetId") or "")
            if last_page or not next_value or page_count == 0:
                break
            if next_value == last_value:
                raise ChaoxingAPIError("inbox notice cursor did not advance")
            last_value = next_value
        return {
            "scope": normalized_scope,
            "folder_uuid": str(folder_uuid or "").strip(),
            "search": str(search or "").strip(),
            "sender": str(sender or "").strip(),
            "start_time": str(start_time or "").strip(),
            "end_time": str(end_time or "").strip(),
            "count": len(notices),
            "max_items": max_items,
            "truncated": truncated,
            "last_page": last_page,
            "folder_count": len(folders),
            "folders": folders,
            "notices": notices,
            "verification": f"read {len(notices)} {normalized_scope} inbox notices through HTTP",
        }

    def _find_inbox_notice(
        self,
        notice: str,
        scope: str,
        *,
        folder_uuid: str = "",
    ) -> dict[str, Any]:
        return self._resolve_inbox_notice(
            self.list_inbox_notices(
                scope=scope,
                folder_uuid=folder_uuid,
                max_items=10000,
            )["notices"],
            notice,
        )

    def list_inbox_folder_notices(
        self,
        folder: str,
        *,
        scope: str = "received",
        search: str = "",
        sender: str = "",
        start_time: str = "",
        end_time: str = "",
        max_items: int = 1000,
    ) -> dict[str, Any]:
        selected = self._find_inbox_folder(folder)
        result = self.list_inbox_notices(
            scope=scope,
            folder_uuid=selected["folder_uuid"],
            search=search,
            sender=sender,
            start_time=start_time,
            end_time=end_time,
            max_items=max_items,
        )
        result["folder"] = selected
        result["verification"] = (
            f"read {result['count']} notices from inbox folder "
            f"{selected['folder_uuid']} through HTTP"
        )
        return result

    def move_inbox_notices(
        self,
        notices: list[str],
        destination_folder: str,
        *,
        scope: str = "received",
        source_folder: str = "",
    ) -> dict[str, Any]:
        if not notices:
            raise ChaoxingAPIError("at least one inbox notice is required")
        folders = self.list_inbox_folders()["folders"]
        root_aliases = {"", "root", "inbox", "根目录", "收件箱"}
        normalized_destination = str(destination_folder or "").strip()
        if normalized_destination.lower() in root_aliases or normalized_destination in root_aliases:
            destination_uuid = ""
            destination = {"folder_uuid": "", "name": "收件箱"}
        else:
            destination = self._resolve_inbox_folder(folders, normalized_destination)
            destination_uuid = destination["folder_uuid"]

        if source_folder:
            source = self._resolve_inbox_folder(folders, source_folder)
            source_uuids = [source["folder_uuid"]]
        else:
            source_uuids = [""] + [folder["folder_uuid"] for folder in folders]
        available: list[dict[str, Any]] = []
        for source_uuid in source_uuids:
            available.extend(
                self.list_inbox_notices(
                    scope=scope,
                    folder_uuid=source_uuid,
                    max_items=10000,
                )["notices"]
            )
        selected = [self._resolve_inbox_notice(available, query) for query in notices]
        selected_ids = list(dict.fromkeys(item["notice_id"] for item in selected))
        if len(selected_ids) != len(selected):
            selected = [
                next(item for item in selected if item["notice_id"] == notice_id)
                for notice_id in selected_ids
            ]
        if all(item.get("folder_uuid", "") == destination_uuid for item in selected):
            raise ChaoxingAPIError("all selected notices are already in the destination folder")
        session, landing, _module = self._personal_space_module_context("收件箱")
        self._inbox_json_request(
            session,
            NOTICE_BASE_URL + "/pc/notice/moveNoticeToFolder",
            "inbox notice move",
            method="POST",
            data={"noticeIds": ",".join(selected_ids), "folder_uuid": destination_uuid},
            referer=landing.url,
        )
        destination_notices = self.list_inbox_notices(
            scope=scope,
            folder_uuid=destination_uuid,
            max_items=10000,
        )["notices"]
        destination_ids = {item["notice_id"] for item in destination_notices}
        missing_ids = [notice_id for notice_id in selected_ids if notice_id not in destination_ids]
        if missing_ids:
            raise ChaoxingAPIError(
                "moved inbox notices are absent from the destination after refresh: "
                + ", ".join(missing_ids)
            )
        return {
            "moved": selected,
            "destination": destination,
            "verification": "every moved notice appears in the destination after refresh",
        }

    def read_inbox_notice(self, notice: str, *, scope: str = "received") -> dict[str, Any]:
        selected = self._find_inbox_notice(notice, scope)
        session, landing, _module = self._personal_space_module_context("收件箱")
        key = selected["uuid"] or selected["notice_id"]
        payload = self._inbox_json_request(
            session,
            NOTICE_BASE_URL + "/pc/notice/" + quote(key, safe="$-") + "/getNoticeDetail",
            "inbox notice detail",
            params={"sendTag": selected["send_tag"]},
            referer=landing.url,
        )
        raw = payload.get("msg")
        if not isinstance(raw, dict):
            raise ChaoxingAPIError("inbox notice detail exposed no notice object")
        detailed = self._normalize_inbox_notice(raw, selected["index"])
        if detailed["notice_id"] != selected["notice_id"]:
            raise ChaoxingAPIError("inbox notice detail returned a different notice")
        if detailed["scope"] == "received":
            detailed["is_read"] = True
            detailed["can_mark_unread"] = True
        return {
            "before": selected,
            "notice": detailed,
            "verification": f"read full inbox notice {detailed['notice_id']} through HTTP",
        }

    def mark_inbox_notice_unread(
        self,
        notice: str,
        *,
        scope: str = "received",
    ) -> dict[str, Any]:
        selected = self._find_inbox_notice(notice, scope)
        if selected["send_tag"] != 0:
            raise ChaoxingAPIError("only received inbox notices can be marked unread")
        session, landing, _module = self._personal_space_module_context("收件箱")
        payload = self._inbox_json_request(
            session,
            NOTICE_BASE_URL + "/pc/notice/setNoticeUnread",
            "mark inbox notice unread",
            method="POST",
            data={"noticeId": selected["notice_id"]},
            referer=landing.url,
        )
        refreshed = self._find_inbox_notice(selected["notice_id"], "received")
        if refreshed["is_read"]:
            raise ChaoxingAPIError("inbox notice still appears read after refresh")
        return {
            "before": selected,
            "notice": refreshed,
            "read_count": payload.get("count_read"),
            "verification": f"inbox notice {selected['notice_id']} is unread after refresh",
        }

    def set_inbox_notice_top_status(
        self,
        notice: str,
        top: bool,
        *,
        scope: str = "received",
    ) -> dict[str, Any]:
        selected = self._find_inbox_notice(notice, scope)
        session, landing, _module = self._personal_space_module_context("收件箱")
        self._inbox_json_request(
            session,
            NOTICE_BASE_URL + f"/pc/notice/{quote(selected['notice_id'], safe='')}/topNotice",
            "set inbox notice top status",
            method="POST",
            data={"top": 1 if top else 0},
            referer=landing.url,
        )
        refreshed = self._find_inbox_notice(selected["notice_id"], scope)
        if refreshed["is_top"] is not bool(top):
            raise ChaoxingAPIError("inbox notice top status did not match after refresh")
        return {
            "before": selected,
            "notice": refreshed,
            "verification": f"inbox notice top status is {bool(top)} after refresh",
        }

    def set_inbox_notice_collect_status(
        self,
        notice: str,
        collect: bool,
        *,
        scope: str = "received",
    ) -> dict[str, Any]:
        selected = self._find_inbox_notice(notice, scope)
        session, landing, _module = self._personal_space_module_context("收件箱")
        self._inbox_json_request(
            session,
            NOTICE_BASE_URL
            + f"/pc/collect/notice/{quote(selected['notice_id'], safe='')}/collectNotice",
            "set inbox notice collection status",
            params={"collect": 1 if collect else 0},
            referer=landing.url,
        )
        refreshed = self._find_inbox_notice(selected["notice_id"], scope)
        if refreshed["is_collected"] is not bool(collect):
            raise ChaoxingAPIError("inbox notice collection status did not match after refresh")
        return {
            "before": selected,
            "notice": refreshed,
            "verification": f"inbox notice collection status is {bool(collect)} after refresh",
        }

    def delete_inbox_notice(
        self,
        notice: str,
        *,
        scope: str = "received",
    ) -> dict[str, Any]:
        selected = self._find_inbox_notice(notice, scope)
        session, landing, _module = self._personal_space_module_context("收件箱")
        self._inbox_json_request(
            session,
            NOTICE_BASE_URL + "/pc/notice/delNoitce",
            "inbox notice deletion",
            method="POST",
            data={"noticeIds": selected["notice_id"], "sendTag": selected["send_tag"]},
            referer=landing.url,
        )
        remaining = self.list_inbox_notices(scope=scope, max_items=10000)["notices"]
        if any(item["notice_id"] == selected["notice_id"] for item in remaining):
            raise ChaoxingAPIError("deleted inbox notice still appears in the active list")
        recycled = self.list_inbox_recycle(search=selected["title"], max_items=10000)["notices"]
        recycled_notice = next(
            (
                item
                for item in recycled
                if item["notice_id"] == selected["notice_id"]
                and item["send_tag"] == selected["send_tag"]
            ),
            None,
        )
        if recycled_notice is None:
            raise ChaoxingAPIError("deleted inbox notice is absent from the recycle bin")
        return {
            "deleted": selected,
            "recycled_notice": recycled_notice,
            "verification": (
                f"inbox notice {selected['notice_id']} is absent from the active list "
                "and present in recycle"
            ),
        }

    def list_inbox_recycle(
        self,
        *,
        search: str = "",
        max_items: int = 1000,
    ) -> dict[str, Any]:
        if not 1 <= max_items <= 10000:
            raise ChaoxingAPIError("max_items must be between 1 and 10000")
        session, _landing, _module = self._personal_space_module_context("收件箱")
        referer = NOTICE_BASE_URL + "/pc/recycle/notice/noticeRecycleBox"
        recycled: list[dict[str, Any]] = []
        seen: set[tuple[str, int]] = set()
        last_value = ""
        truncated = False
        last_page = False
        for _page in range(1, 501):
            payload = self._inbox_json_request(
                session,
                NOTICE_BASE_URL + "/pc/recycle/notice/getNoticeRecycles",
                "inbox recycle list",
                method="POST",
                data={
                    "lastValue": last_value,
                    "pageSize": 1000,
                    "kw": quote(str(search or "").strip(), safe=""),
                },
                referer=referer,
            )
            raw_items = payload.get("list")
            page_items = raw_items if isinstance(raw_items, list) else []
            for raw in page_items:
                if not isinstance(raw, dict):
                    continue
                normalized = self._normalize_inbox_notice(raw, len(recycled) + 1)
                identity = (normalized["notice_id"], normalized["send_tag"])
                if not identity[0] or identity in seen:
                    continue
                seen.add(identity)
                normalized.update(
                    {
                        "deleted_at": raw.get("deleteTime") or raw.get("recycleTime"),
                        "recycle_state": "recycled",
                    }
                )
                recycled.append(normalized)
                if len(recycled) >= max_items:
                    truncated = True
                    break
            if truncated:
                break
            last_page = str(payload.get("lastPage") or "0") in {"1", "true", "True"}
            next_value = str(payload.get("lastValue") or "")
            if last_page or not next_value or not page_items:
                break
            if next_value == last_value:
                raise ChaoxingAPIError("inbox recycle cursor did not advance")
            last_value = next_value
        return {
            "search": str(search or "").strip(),
            "count": len(recycled),
            "max_items": max_items,
            "truncated": truncated,
            "last_page": last_page,
            "notices": recycled,
            "verification": f"read {len(recycled)} recycled inbox notices through HTTP",
        }

    def _resolve_inbox_recycle_notice(self, query: str) -> dict[str, Any]:
        return self._resolve_inbox_notice(
            self.list_inbox_recycle(max_items=10000)["notices"],
            query,
        )

    def restore_inbox_recycle_notices(self, notices: list[str]) -> dict[str, Any]:
        if not notices:
            raise ChaoxingAPIError("at least one recycled inbox notice is required")
        before = self.list_inbox_recycle(max_items=10000)["notices"]
        selected = [self._resolve_inbox_notice(before, query) for query in notices]
        unique: dict[tuple[str, int], dict[str, Any]] = {
            (item["notice_id"], item["send_tag"]): item for item in selected
        }
        selected = list(unique.values())
        if len(selected) > 60:
            raise ChaoxingAPIError("at most 60 inbox notices can be restored at once")
        session, _landing, _module = self._personal_space_module_context("收件箱")
        referer = NOTICE_BASE_URL + "/pc/recycle/notice/noticeRecycleBox"
        self._inbox_json_request(
            session,
            NOTICE_BASE_URL + "/pc/recycle/notice/resNoticeRecycle",
            "inbox recycle restore",
            method="POST",
            data={
                "ids": ",".join(item["notice_id"] for item in selected),
                "sendTag": ",".join(str(item["send_tag"]) for item in selected),
            },
            referer=referer,
        )
        remaining = {
            (item["notice_id"], item["send_tag"])
            for item in self.list_inbox_recycle(max_items=10000)["notices"]
        }
        not_removed = [
            item["notice_id"]
            for item in selected
            if (item["notice_id"], item["send_tag"]) in remaining
        ]
        if not_removed:
            raise ChaoxingAPIError(
                "restored notices remain in the inbox recycle bin: " + ", ".join(not_removed)
            )
        active_by_scope: dict[str, set[str]] = {}
        for scope in {item["scope"] for item in selected}:
            active_by_scope[scope] = {
                item["notice_id"]
                for item in self.list_inbox_notices(scope=scope, max_items=10000)["notices"]
            }
        absent = [
            item["notice_id"]
            for item in selected
            if item["notice_id"] not in active_by_scope[item["scope"]]
        ]
        if absent:
            raise ChaoxingAPIError(
                "restored notices are absent from their active lists: " + ", ".join(absent)
            )
        return {
            "restored": selected,
            "verification": (
                "every restored notice is absent from recycle and present in its active list"
            ),
        }

    def permanently_delete_inbox_recycle_notices(
        self,
        notices: list[str],
    ) -> dict[str, Any]:
        if not notices:
            raise ChaoxingAPIError("at least one recycled inbox notice is required")
        before = self.list_inbox_recycle(max_items=10000)["notices"]
        selected = [self._resolve_inbox_notice(before, query) for query in notices]
        unique: dict[tuple[str, int], dict[str, Any]] = {
            (item["notice_id"], item["send_tag"]): item for item in selected
        }
        selected = list(unique.values())
        if len(selected) > 60:
            raise ChaoxingAPIError("at most 60 inbox notices can be permanently deleted at once")
        session, _landing, _module = self._personal_space_module_context("收件箱")
        referer = NOTICE_BASE_URL + "/pc/recycle/notice/noticeRecycleBox"
        self._inbox_json_request(
            session,
            NOTICE_BASE_URL + "/pc/recycle/notice/delNoticeRecycle",
            "inbox recycle permanent deletion",
            method="POST",
            data={
                "ids": ",".join(item["notice_id"] for item in selected),
                "sendTag": ",".join(str(item["send_tag"]) for item in selected),
            },
            referer=referer,
        )
        remaining = {
            (item["notice_id"], item["send_tag"])
            for item in self.list_inbox_recycle(max_items=10000)["notices"]
        }
        not_removed = [
            item["notice_id"]
            for item in selected
            if (item["notice_id"], item["send_tag"]) in remaining
        ]
        if not_removed:
            raise ChaoxingAPIError(
                "permanently deleted notices remain in recycle: " + ", ".join(not_removed)
            )
        return {
            "deleted": selected,
            "verification": "every selected notice is absent from recycle after permanent deletion",
        }

    def empty_inbox_recycle(self) -> dict[str, Any]:
        selected = self.list_inbox_recycle(max_items=10000)["notices"]
        session, _landing, _module = self._personal_space_module_context("收件箱")
        referer = NOTICE_BASE_URL + "/pc/recycle/notice/noticeRecycleBox"
        for offset in range(0, len(selected), 60):
            batch = selected[offset : offset + 60]
            self._inbox_json_request(
                session,
                NOTICE_BASE_URL + "/pc/recycle/notice/delNoticeRecycle",
                "inbox recycle empty",
                method="POST",
                data={
                    "ids": ",".join(item["notice_id"] for item in batch),
                    "sendTag": ",".join(str(item["send_tag"]) for item in batch),
                },
                referer=referer,
            )
        after = self.list_inbox_recycle(max_items=1)
        if after["count"]:
            raise ChaoxingAPIError("inbox recycle still contains notices after emptying")
        return {
            "deleted_count": len(selected),
            "verification": "a fresh inbox recycle read returned no notices",
        }

    @staticmethod
    def _normalize_note(note: dict[str, Any], index: int = 0) -> dict[str, Any]:
        def integer(value: Any) -> int:
            try:
                return int(value or 0)
            except (TypeError, ValueError):
                return 0

        user_auth = note.get("userAuth") if isinstance(note.get("userAuth"), dict) else {}
        operation_auth = (
            user_auth.get("operationAuth")
            if isinstance(user_auth.get("operationAuth"), dict)
            else {}
        )
        opened_state = integer(note.get("openedState"))
        creator_puid = str(note.get("createrPuid") or "")
        current_user_puid = str(note.get("_current_user_puid") or "")
        is_owner = bool(creator_puid and creator_puid == current_user_puid)
        return {
            "index": index,
            "note_cid": str(note.get("cid") or ""),
            "note_id": str(note.get("id") or ""),
            "title": str(note.get("title") or note.get("title1") or ""),
            "content": str(note.get("content") or note.get("content1") or ""),
            "content_html": str(note.get("rtf_content") or ""),
            "is_rich_text": str(note.get("isRtf") or "0") == "1",
            "notebook_cid": str(note.get("notebookCid") or ""),
            "notebook_id": str(note.get("notebookId") or ""),
            "notebook_name": str(note.get("notebookName") or ""),
            "opened_state": opened_state,
            "visibility": {
                0: "private",
                1: "friends",
                2: "selected_people",
                3: "public",
            }.get(opened_state, "unknown"),
            "creator_puid": creator_puid,
            "creator_name": str(note.get("createrName") or ""),
            "is_owner": is_owner,
            "created_at": note.get("createTime"),
            "updated_at": note.get("updateTime") or note.get("lastUpdateTime"),
            "read_count": integer(note.get("readCount") or note.get("s_readcount")),
            "reply_count": integer(note.get("replyCount") or note.get("reply_count")),
            "praise_count": integer(note.get("praiseCount") or note.get("praise_count")),
            "share_url": str(note.get("shareUrl") or ""),
            "category": integer(note.get("category")),
            "attachments": (
                note.get("attachment") if isinstance(note.get("attachment"), list) else []
            ),
            "images": note.get("imgs") if isinstance(note.get("imgs"), list) else [],
            "can_update": (
                str(operation_auth.get("update") or "0") == "1" if operation_auth else None
            ),
            "can_delete": (
                str(operation_auth.get("delete") or "0") == "1" or is_owner
                if operation_auth or is_owner
                else None
            ),
        }

    @staticmethod
    def _resolve_note(notes: list[dict[str, Any]], query: str) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("note title, CID, or index is required")
        for key in ("note_cid", "note_id", "title", "index"):
            exact = [
                note for note in notes if str(note.get(key) or "").strip().lower() == normalized
            ]
            if len(exact) == 1:
                return exact[0]
            if len(exact) > 1:
                choices = ", ".join(f"{note['title']} ({note['note_cid']})" for note in exact[:20])
                raise ChaoxingAPIError(f"multiple notes match: {choices}")
        partial = [note for note in notes if normalized in str(note["title"]).lower()]
        if len(partial) == 1:
            return partial[0]
        if not partial:
            raise ChaoxingAPIError(f"note not found: {query}")
        choices = ", ".join(f"{note['title']} ({note['note_cid']})" for note in partial[:20])
        raise ChaoxingAPIError(f"multiple notes match: {choices}")

    def _note_json_request(
        self,
        session: requests.Session,
        url: str,
        operation: str,
        *,
        method: str = "GET",
        params: dict[str, Any] | None = None,
        data: dict[str, Any] | None = None,
        referer: str = "",
    ) -> dict[str, Any]:
        headers = {"Referer": referer} if referer else {}
        try:
            if method.upper() == "POST":
                response = session.post(
                    url,
                    params=params,
                    data=data,
                    timeout=max(self.timeout, 60),
                    headers=headers,
                )
            else:
                response = session.get(
                    url,
                    params=params,
                    timeout=max(self.timeout, 60),
                    headers=headers,
                )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"{operation} failed: {exc}") from exc
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError(f"{operation} returned invalid JSON") from exc
        if not isinstance(payload, dict):
            raise ChaoxingAPIError(f"{operation} returned invalid JSON")
        if str(payload.get("result") or "0") != "1":
            raise ChaoxingAPIError(str(payload.get("msg") or f"{operation} was rejected"))
        return payload

    def _read_note_by_cid(
        self,
        session: requests.Session,
        note_cid: str,
    ) -> dict[str, Any]:
        try:
            response = session.get(
                NOTE_BASE_URL + "/pc/" + quote(note_cid, safe=""),
                timeout=max(self.timeout, 60),
                allow_redirects=True,
                headers={"Referer": NOTE_FEED_BASE_URL + "/pc/activity/activityList"},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"note detail request failed: {exc}") from exc
        html = self._decode(response)
        raw = parse_note_detail_html(html)
        user = parse_note_detail_user(html)
        raw["_current_user_puid"] = str(user.get("puid") or "")
        if str(raw.get("cid") or "") != note_cid:
            raise ChaoxingAPIError("note detail returned a different CID")
        return raw

    def list_notes(
        self,
        *,
        search: str = "",
        max_items: int = 1000,
    ) -> dict[str, Any]:
        if not 1 <= max_items <= 10000:
            raise ChaoxingAPIError("max_items must be between 1 and 10000")
        session = self._session()
        notes: list[dict[str, Any]] = []
        seen: set[str] = set()
        cursor_id = ""
        cursor_time: Any = ""
        truncated = False
        for _page in range(200):
            payload = self._note_json_request(
                session,
                NOTE_FEED_BASE_URL + "/pc/activity/getActivitysMe",
                "note list",
                params={
                    "index_Id": cursor_id,
                    "index_updateTime": cursor_time,
                    "searchType": 0,
                    "kw": str(search or "").strip(),
                },
                referer=NOTE_FEED_BASE_URL + "/pc/activity/activityList",
            )
            data = payload.get("data") if isinstance(payload.get("data"), dict) else {}
            entries = data.get("list") if isinstance(data.get("list"), list) else []
            for entry in entries:
                if not isinstance(entry, dict) or str(entry.get("type") or "") != "2":
                    continue
                raw = entry.get("note") if isinstance(entry.get("note"), dict) else {}
                note_cid = str(raw.get("cid") or "")
                if not note_cid or note_cid in seen:
                    continue
                seen.add(note_cid)
                notes.append(self._normalize_note(raw, len(notes) + 1))
                if len(notes) >= max_items:
                    truncated = True
                    break
            if truncated:
                break
            next_id = str(data.get("index_Id") or "")
            next_time = data.get("index_updateTime")
            if next_time in {-1, "-1", None} or not entries:
                break
            if next_id == cursor_id and str(next_time) == str(cursor_time):
                raise ChaoxingAPIError("note list cursor did not advance")
            cursor_id, cursor_time = next_id, next_time
        return {
            "search": str(search or "").strip(),
            "count": len(notes),
            "max_items": max_items,
            "truncated": truncated,
            "notes": notes,
            "verification": f"read {len(notes)} personal notes through HTTP",
        }

    def read_note(self, note: str) -> dict[str, Any]:
        session = self._session()
        selected = self._resolve_note(self.list_notes(max_items=10000)["notes"], note)
        raw = self._read_note_by_cid(session, selected["note_cid"])
        normalized = self._normalize_note(raw, selected["index"])
        return {
            "note": normalized,
            "verification": f"read full note {normalized['note_cid']} through HTTP",
        }

    @staticmethod
    def _note_content(content: str, content_format: str) -> tuple[str, str]:
        normalized_format = str(content_format or "plain").strip().lower()
        if normalized_format == "plain":
            plain = str(content or "")
            rich = "<p>" + escape(plain).replace("\r\n", "\n").replace("\n", "<br>") + "</p>"
            return plain, rich
        if normalized_format == "html":
            rich = str(content or "")
            return html_text(rich), rich
        raise ChaoxingAPIError("content_format must be plain or html")

    @staticmethod
    def _note_image_map(images: list[dict[str, Any]]) -> str:
        mapped: dict[str, str] = {}
        for image in images:
            if not isinstance(image, dict):
                continue
            object_id = str(image.get("objectId") or image.get("objectid") or "").strip()
            image_url = str(image.get("imgUrl") or image.get("url") or "").strip()
            if object_id and image_url:
                mapped[object_id] = image_url
        return json.dumps(mapped, ensure_ascii=False, separators=(",", ":")) if mapped else ""

    def _write_note(
        self,
        session: requests.Session,
        note_cid: str,
        *,
        title: str,
        content: str,
        content_html: str,
        notebook_cid: str,
        attachments: list[dict[str, Any]] | None = None,
        images: list[dict[str, Any]] | None = None,
        editing: bool = False,
    ) -> dict[str, Any]:
        url = (
            NOTE_BASE_URL + f"/pc/note_note/{quote(note_cid, safe='')}/noteEditLatest"
            if editing
            else NOTE_BASE_URL + "/pc/note_note/createNote"
        )
        params = None if editing else {"cid": note_cid}
        return self._note_json_request(
            session,
            url,
            "note update" if editing else "note creation",
            method="POST",
            params=params,
            data={
                "title": title,
                "content": content,
                "files_url": self._note_image_map(images or []),
                "attachment": (
                    json.dumps(attachments, ensure_ascii=False, separators=(",", ":"))
                    if attachments
                    else ""
                ),
                "rtf_content": content_html,
                "_t": int(datetime.now(tz=UTC).timestamp() * 1000),
                "isRichText": 1,
                "isCooperate": "",
                "notebookCid": notebook_cid or "root",
                "sort": "",
                "encode": 0,
            },
            referer=(
                NOTE_BASE_URL + f"/pc/note_note/noteRichtextEdit/{quote(note_cid, safe='')}"
                if editing
                else NOTE_BASE_URL + "/pc/note_note/noteRichtextCreate?from=activity"
            ),
        )

    def create_note(
        self,
        title: str,
        content: str,
        *,
        content_format: str = "plain",
        notebook_cid: str = "root",
    ) -> dict[str, Any]:
        note_title = str(title or "").strip()
        if len(note_title) > 200:
            raise ChaoxingAPIError("note title cannot exceed 200 characters")
        plain, rich = self._note_content(content, content_format)
        if not note_title and not plain and not rich:
            raise ChaoxingAPIError("note title and content cannot both be empty")
        note_cid = str(uuid4())
        session = self._session()
        payload = self._write_note(
            session,
            note_cid,
            title=note_title,
            content=plain,
            content_html=rich,
            notebook_cid=str(notebook_cid or "root").strip() or "root",
        )
        raw: dict[str, Any] | None = None
        for attempt in range(7):
            try:
                raw = self._read_note_by_cid(session, note_cid)
            except ChaoxingAPIError:
                if attempt == 6:
                    raise
                sleep(0.5)
                continue
            if str(raw.get("title") or "") == note_title:
                break
            if attempt < 6:
                sleep(0.5)
        if raw is None or str(raw.get("title") or "") != note_title:
            raise ChaoxingAPIError("created note title did not match after refresh")
        normalized = self._normalize_note(raw, 1)
        return {
            "note": normalized,
            "server_message": str(payload.get("msg") or ""),
            "verification": f"created and re-read private note {note_cid}",
        }

    def update_note(
        self,
        note: str,
        *,
        title: str | None = None,
        content: str | None = None,
        content_format: str = "plain",
    ) -> dict[str, Any]:
        if title is None and content is None:
            raise ChaoxingAPIError("title or content is required for a note update")
        session = self._session()
        selected = self._resolve_note(self.list_notes(max_items=10000)["notes"], note)
        raw = self._read_note_by_cid(session, selected["note_cid"])
        current = self._normalize_note(raw, selected["index"])
        if current["can_update"] is not True:
            raise ChaoxingAPIError("the current account cannot update this note")
        if current["category"] == 1:
            raise ChaoxingAPIError("collaborative note updates are not yet supported safely")
        next_title = current["title"] if title is None else str(title).strip()
        if len(next_title) > 200:
            raise ChaoxingAPIError("note title cannot exceed 200 characters")
        if content is None:
            next_content = current["content"]
            next_html = current["content_html"]
        else:
            next_content, next_html = self._note_content(content, content_format)
        if not next_title and not next_content and not next_html:
            raise ChaoxingAPIError("note title and content cannot both be empty")
        self._write_note(
            session,
            current["note_cid"],
            title=next_title,
            content=next_content,
            content_html=next_html,
            notebook_cid=current["notebook_cid"] or "root",
            attachments=current["attachments"],
            images=current["images"],
            editing=True,
        )
        updated_raw = self._read_note_by_cid(session, current["note_cid"])
        updated = self._normalize_note(updated_raw, current["index"])
        if updated["title"] != next_title or updated["content"] != next_content:
            raise ChaoxingAPIError("note title or content did not match after refresh")
        return {
            "before": current,
            "note": updated,
            "verification": f"updated and re-read note {updated['note_cid']}",
        }

    def delete_note(self, note: str) -> dict[str, Any]:
        session = self._session()
        selected = self._resolve_note(self.list_notes(max_items=10000)["notes"], note)
        raw = self._read_note_by_cid(session, selected["note_cid"])
        current = self._normalize_note(raw, selected["index"])
        if current["can_delete"] is not True:
            raise ChaoxingAPIError("the current account cannot delete this note")
        payload = self._note_json_request(
            session,
            NOTE_BASE_URL + f"/pc/note_note/{quote(current['note_cid'], safe='')}/deleteNoteLatest",
            "note deletion",
            referer=NOTE_BASE_URL + "/pc/" + quote(current["note_cid"], safe=""),
        )
        for attempt in range(7):
            remaining = self.list_notes(max_items=10000)["notes"]
            if all(item["note_cid"] != current["note_cid"] for item in remaining):
                return {
                    "deleted": current,
                    "server_message": str(payload.get("msg") or ""),
                    "verification": f"deleted note {current['note_cid']} is absent from the feed",
                }
            if attempt < 6:
                sleep(0.5)
        raise ChaoxingAPIError("deleted note still appears in the personal note feed")

    def list_teaching_courses(self) -> list[dict[str, Any]]:
        try:
            response = self._session().get(BACKCLAZZ_URL, timeout=self.timeout)
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"course list request failed: {exc}") from exc
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("course list response was not JSON") from exc
        if not isinstance(payload, dict) or payload.get("result") != 1:
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "failed to fetch teaching courses"))
        return parse_teaching_courses(payload)

    def get_course(self, query: str) -> dict[str, Any]:
        return resolve_course(self.list_teaching_courses(), query)

    def list_learning_courses(
        self,
        *,
        search: str = "",
        folder: str = "0",
    ) -> list[dict[str, Any]]:
        session, landing, _module = self._personal_space_module_context("课程教学")
        landing_html = self._decode(landing)
        hidden = parse_hidden_inputs(landing_html)
        try:
            response = session.post(
                LEARNING_COURSE_LIST_URL,
                data={
                    "courseType": "1",
                    "courseFolderId": str(folder or "0"),
                    "query": str(search or "").strip(),
                    "pageHeader": "-1",
                    "single": "0",
                    "superstarClass": "0",
                    "isFirefly": "0",
                    "fid": str(hidden.get("fid") or ""),
                },
                timeout=self.timeout,
                headers={
                    "Referer": landing.url,
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"learning-course list request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError("Chaoxing learning-course login has expired")
        html = self._decode(response)
        if "passport2.chaoxing.com/login" in html.lower():
            raise ChaoxingAPIError("Chaoxing learning-course response was a login page")
        courses = parse_learning_courses(html)
        normalized_search = str(search or "").strip().casefold()
        if normalized_search:
            courses = [
                course
                for course in courses
                if normalized_search in str(course.get("course_name") or "").casefold()
                or normalized_search in str(course.get("teacher") or "").casefold()
            ]
            for index, course in enumerate(courses, 1):
                course["index"] = index
        return courses

    def get_learning_course(self, query: str) -> dict[str, Any]:
        return resolve_learning_course(self.list_learning_courses(), query)

    def _learning_course_context(
        self,
        session: requests.Session,
        course: dict[str, Any],
    ) -> dict[str, Any]:
        entry_url = validated_chaoxing_url(
            str(course.get("entry_url") or ""), "learning-course entry URL"
        )
        try:
            response = session.get(
                entry_url,
                timeout=self.timeout,
                allow_redirects=True,
                headers={"Referer": MOOC2_BASE_URL + "/mooc2-ans/visit/interaction"},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"learning-course request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError("Chaoxing learning-course login has expired")
        html = self._decode(response)
        value_names = (
            "courseid",
            "clazzid",
            "cpi",
            "personid",
            "bbsid",
            "oldenc",
            "enc",
            "cfid",
            "t",
            "workEnc",
            "examEnc",
            "openc",
            "courseApp",
            "bbsUrlSwitch",
            "hideHead",
            "notAgreeCommitment",
            "notAgreeCourseCommitment",
        )
        values = parse_page_values(html, value_names)
        for key, query_name in (
            ("courseid", "courseid"),
            ("clazzid", "clazzid"),
            ("cpi", "cpi"),
            ("enc", "enc"),
            ("openc", "openc"),
        ):
            if not values[key]:
                values[key] = query_value(response.url, query_name)
        values["courseid"] = values["courseid"] or str(course.get("course_id") or "")
        values["clazzid"] = values["clazzid"] or str(course.get("clazz_id") or "")
        values["cpi"] = values["cpi"] or str(course.get("cpi") or "")
        values["personid"] = values["personid"] or values["cpi"]
        return {
            "entry_url": entry_url,
            "final_url": response.url,
            "http_status": response.status_code,
            "html": html,
            "values": values,
            "modules": parse_learning_nav_items(html),
        }

    @staticmethod
    def _learning_module_url(context: dict[str, Any], item: dict[str, str]) -> str:
        values = context.get("values") if isinstance(context.get("values"), dict) else {}
        module = str(item.get("module") or "")
        base_url = urljoin(str(context.get("final_url") or ""), str(item.get("data_url") or ""))
        course_id = str(values.get("courseid") or "")
        clazz_id = str(values.get("clazzid") or "")
        cpi = str(values.get("cpi") or "")
        t = str(values.get("t") or "")

        if module == "ai_workbench":
            url = base_url
        elif module in {"zy", "zb_jm", "bjexpand"}:
            url = append_missing_query_params(
                base_url,
                {
                    "courseId": course_id,
                    "classId": clazz_id,
                    "cpi": cpi,
                    "ut": "s",
                },
            )
        else:
            url = append_missing_query_params(
                base_url,
                {
                    "courseid": course_id,
                    "clazzid": clazz_id,
                    "cpi": cpi,
                    "ut": "s",
                    "t": t,
                },
            )

        url = append_missing_query_params(
            url,
            {
                "cpi": cpi,
                "t": t,
                "stuenc": str(values.get("enc") or ""),
            },
        )
        if module == "hd":
            url = append_missing_query_params(url, {"fid": str(values.get("cfid") or "")})
        elif module == "tl":
            url = append_missing_query_params(
                url,
                {
                    "bbsid": str(values.get("bbsid") or ""),
                    "enc": str(values.get("enc") or ""),
                    "openc": str(values.get("openc") or ""),
                    "hideHead": str(values.get("hideHead") or ""),
                },
            )
        elif module == "zj":
            url = append_missing_query_params(url, {"pageHeader": "1"})
        elif module == "zl":
            url = append_missing_query_params(url, {"pageHeader": "3"})
        elif module == "ctj":
            url = append_missing_query_params(url, {"pageHeader": "4"})
        elif module == "zc":
            url = append_missing_query_params(
                url,
                {
                    "enc": str(values.get("examEnc") or ""),
                    "openc": str(values.get("openc") or ""),
                    "type": "1",
                },
            )
        elif module == "cj":
            url = append_missing_query_params(url, {"pageHeader": "6"})
        elif module == "zy":
            url = append_missing_query_params(url, {"enc": str(values.get("workEnc") or "")})
        elif module == "ks":
            url = append_missing_query_params(
                url,
                {
                    "enc": str(values.get("examEnc") or ""),
                    "openc": str(values.get("openc") or ""),
                },
            )
        elif module == "zsd":
            url = append_missing_query_params(
                url,
                {"openType": "1", "enc": str(values.get("oldenc") or "")},
            )
        elif module == "ai_workbench":
            url = append_missing_query_params(url, {"pageHeader": "21"})
        return url

    def discover_learning_course_modules(self, course: dict[str, Any]) -> dict[str, Any]:
        context = self._learning_course_context(self._session(), course)
        public_modules = [
            {
                **item,
                "data_url": redact_url_query_values(
                    str(item.get("data_url") or ""),
                    {"enc", "stuenc", "openc", "workEnc", "examEnc", "token"},
                ),
            }
            for item in context["modules"]
        ]
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": course["clazz_id"],
            "entry_url": context["entry_url"],
            "final_url": redact_url_query_values(
                str(context["final_url"]), {"enc", "stuenc", "openc"}
            ),
            "module_count": len(public_modules),
            "modules": public_modules,
            "verification": "authenticated student-role course HTML parsed through HTTP",
        }

    def resolve_learning_course_module_login_target(
        self,
        course_query: str,
        module_query: str,
    ) -> tuple[dict[str, Any], dict[str, str], str]:
        """Resolve a signed learner-module URL for immediate in-memory login use."""
        course = self.get_learning_course(course_query)
        context = self._learning_course_context(self._session(), course)
        module = resolve_module(context["modules"], module_query)
        target_url = self._learning_module_url(context, module)
        validated_chaoxing_url(target_url, "learning-course login target URL")
        return course, module, target_url

    def _learning_module_response(
        self,
        course: dict[str, Any],
        module_query: str,
    ) -> dict[str, Any]:
        session = self._session()
        context = self._learning_course_context(session, course)
        item = resolve_module(context["modules"], module_query)
        module_url = self._learning_module_url(context, item)
        try:
            response = session.get(
                module_url,
                timeout=max(self.timeout, 60),
                allow_redirects=True,
                headers={"Referer": str(context["final_url"])},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"learning-course module request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError("learning-course module was redirected to login")
        html = self._decode(response)
        if "passport2.chaoxing.com/login" in html.lower():
            raise ChaoxingAPIError("learning-course module response was a login page")
        return {
            "session": session,
            "course_context": context,
            "module": item,
            "request_url": module_url,
            "response": response,
            "html": html,
        }

    def inspect_learning_course_module(
        self,
        course: dict[str, Any],
        module_query: str,
    ) -> dict[str, Any]:
        module = self._learning_module_response(course, module_query)
        item = module["module"]
        module_url = str(module["request_url"])
        response = module["response"]
        html = str(module["html"])
        title_match = re.search(r"<title[^>]*>(.*?)</title>", html, flags=re.I | re.S)
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": course["clazz_id"],
            "module": item,
            "request_url": redact_url_query_values(
                module_url, {"enc", "stuenc", "openc", "workEnc", "examEnc"}
            ),
            "final_url": redact_url_query_values(
                response.url, {"enc", "stuenc", "openc", "workEnc", "examEnc"}
            ),
            "http_status": response.status_code,
            "content_type": str(response.headers.get("Content-Type") or ""),
            "title": html_text(title_match.group(1)) if title_match else "",
            "text_excerpt": html_text(html, limit=20_000),
            "verification": "authenticated student-role module response retrieved through HTTP",
        }

    @staticmethod
    def _learning_course_result(course: dict[str, Any]) -> dict[str, Any]:
        return {
            "course_id": str(course.get("course_id") or ""),
            "course_name": str(course.get("course_name") or ""),
            "clazz_id": str(course.get("clazz_id") or ""),
        }

    @staticmethod
    def _learning_json_response(
        response: requests.Response,
        operation: str,
    ) -> dict[str, Any]:
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError(f"{operation} was redirected to login")
        try:
            payload = json.loads(ChaoxingAPI._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError(f"{operation} returned invalid JSON") from exc
        if not isinstance(payload, dict):
            raise ChaoxingAPIError(f"{operation} returned invalid JSON")
        return payload

    def _learning_knowledge_graph_context(self, course: dict[str, Any]) -> dict[str, Any]:
        module = self._learning_module_response(course, "课程图谱")
        query = {
            key.casefold(): values[0]
            for key, values in parse_qs(urlparse(str(module["request_url"])).query).items()
            if values
        }

        def value(name: str, fallback: Any = "") -> str:
            return str(query.get(name.casefold()) or fallback or "").strip()

        common = {
            "courseid": value("courseid", course.get("course_id")),
            "clazzid": value("clazzid", course.get("clazz_id")),
            "cpi": value("cpi", course.get("cpi")),
            "ut": value("ut", "s"),
            "enc": value("enc"),
            "stuenc": value("stuenc"),
            "openType": value("opentype", "1"),
        }
        if not all(common[key] for key in ("courseid", "clazzid", "cpi")):
            raise ChaoxingAPIError("learner course graph did not expose courseid, clazzid, and cpi")
        return {
            "session": module["session"],
            "common": common,
            "referer": str(module["response"].url),
        }

    @staticmethod
    def _learning_graph_public_items(items: list[dict[str, Any]]) -> list[dict[str, Any]]:
        return [
            {key: value for key, value in item.items() if key != "raw"}
            for item in items
            if isinstance(item, dict)
        ]

    def list_learning_activities(
        self,
        course: dict[str, Any],
        *,
        search: str = "",
        status: str = "all",
    ) -> dict[str, Any]:
        module = self._learning_module_response(course, "任务")
        session = module["session"]
        page_values = parse_page_values(
            str(module["html"]),
            ("fid", "courseId", "classId", "showNotStartedActive"),
        )
        course_id = page_values["courseId"] or str(course["course_id"])
        clazz_id = page_values["classId"] or str(course["clazz_id"])
        common = {
            "fid": page_values["fid"],
            "courseId": course_id,
            "classId": clazz_id,
            "showNotStartedActive": page_values["showNotStartedActive"],
        }

        def get_json(url: str, operation: str, params: dict[str, Any]) -> dict[str, Any]:
            try:
                response = session.get(
                    url,
                    params=params,
                    timeout=max(self.timeout, 60),
                    allow_redirects=True,
                    headers={
                        "Referer": str(module["response"].url),
                        "X-Requested-With": "XMLHttpRequest",
                    },
                )
                response.raise_for_status()
            except requests.RequestException as exc:
                raise ChaoxingAPIError(f"{operation} request failed") from exc
            return self._learning_json_response(response, operation)

        payload = get_json(
            MOBILELEARN_BASE_URL + "/v2/apis/active/student/activelist",
            "learner activity list",
            common,
        )
        if str(payload.get("result") or "") not in {"1", "true", "True"}:
            raise ChaoxingAPIError(
                str(payload.get("errorMsg") or "failed to list learner activities")
            )
        data = payload.get("data") if isinstance(payload.get("data"), dict) else {}
        activities = [
            normalize_learning_activity(raw, source="class_activity")
            for raw in data.get("activeList") or []
            if isinstance(raw, dict)
        ]
        unavailable_sources: list[str] = []

        try:
            task_payload = get_json(
                MOBILELEARN_BASE_URL + "/v2/apis/active/getData",
                "learner study-plan task list",
                {"DB_STRATEGY": "DEFAULT", "courseId": course_id, "classId": clazz_id},
            )
            task_data = task_payload.get("data")
            if str(task_payload.get("result") or "") in {"1", "true", "True"} and isinstance(
                task_data, list
            ):
                activities.extend(
                    normalize_learning_activity(raw, source="study_plan")
                    for raw in task_data
                    if isinstance(raw, dict)
                )
            elif task_payload.get("result") not in (None, 1, True, "1", "true"):
                unavailable_sources.append("study_plan")
        except ChaoxingAPIError:
            unavailable_sources.append("study_plan")

        try:
            ai_payload = get_json(
                MOOC2_BASE_URL + "/mooc2-ans/ai-evaluate/v2/answer/activities",
                "learner AI-practice list",
                {"courseid": course_id, "clazzid": clazz_id},
            )
            ai_data = ai_payload.get("data")
            if ai_payload.get("status") is True and isinstance(ai_data, list):
                activities.extend(
                    normalize_learning_activity(raw, source="ai_practice")
                    for raw in ai_data
                    if isinstance(raw, dict)
                )
            elif ai_payload.get("status") is not True:
                unavailable_sources.append("ai_practice")
        except ChaoxingAPIError:
            unavailable_sources.append("ai_practice")

        normalized_status = str(status or "all").strip().casefold().replace("-", "_")
        allowed_statuses = {"all", "not_started", "ongoing", "ended"}
        if normalized_status not in allowed_statuses:
            raise ChaoxingAPIError(
                "learner activity status must be all, not_started, ongoing, or ended"
            )
        normalized_search = str(search or "").strip().casefold()
        if normalized_search:
            activities = [
                item
                for item in activities
                if normalized_search in str(item.get("name") or "").casefold()
                or normalized_search in str(item.get("subtitle") or "").casefold()
            ]
        if normalized_status != "all":
            activities = [
                item for item in activities if item.get("status_label") == normalized_status
            ]
        for index, item in enumerate(activities, 1):
            item["index"] = index
        source_counts = Counter(str(item.get("source") or "") for item in activities)
        return {
            **self._learning_course_result(course),
            "search": search,
            "status": normalized_status,
            "count": len(activities),
            "source_counts": dict(source_counts),
            "unavailable_sources": sorted(set(unavailable_sources)),
            "activities": activities,
            "verification": "learner activity APIs read without entering or starting an activity",
        }

    def list_learning_chapters(
        self,
        course: dict[str, Any],
        *,
        search: str = "",
    ) -> dict[str, Any]:
        module = self._learning_module_response(course, "章节")
        parsed = parse_learning_chapters(str(module["html"]))
        chapters = parsed["chapters"]
        units = parsed["units"]
        normalized_search = str(search or "").strip().casefold()
        if normalized_search:
            chapters = [
                item
                for item in chapters
                if normalized_search in str(item.get("title") or "").casefold()
                or normalized_search in str(item.get("number") or "").casefold()
                or normalized_search in str(item.get("unit_title") or "").casefold()
            ]
            matched_ids = {item["chapter_id"] for item in chapters}
            units = [
                {
                    **unit,
                    "chapters": [
                        item for item in unit["chapters"] if item["chapter_id"] in matched_ids
                    ],
                }
                for unit in units
                if any(item["chapter_id"] in matched_ids for item in unit["chapters"])
            ]
        return {
            **self._learning_course_result(course),
            "search": search,
            "unit_count": len(units),
            "chapter_count": len(chapters),
            "pending_task_count": sum(item["pending_task_count"] for item in chapters),
            "units": units,
            "chapters": chapters,
            "verification": "learner chapter hierarchy parsed without opening a chapter",
        }

    def _list_learning_task_entries(
        self,
        course: dict[str, Any],
        module_name: str,
        result_key: str,
        *,
        search: str = "",
        status: str = "",
    ) -> dict[str, Any]:
        module = self._learning_module_response(course, module_name)
        html = str(module["html"])
        entries = parse_learning_task_entries(html)
        normalized_search = str(search or "").strip().casefold()
        normalized_status = str(status or "").strip().casefold().replace("-", "_")
        if normalized_search:
            entries = [item for item in entries if normalized_search in item["title"].casefold()]
        if normalized_status and normalized_status != "all":
            entries = [
                item
                for item in entries
                if normalized_status in {item["status_key"], item["status"].casefold()}
            ]
        for index, item in enumerate(entries, 1):
            item["index"] = index
        empty_match = re.search(
            r"<div\b[^>]*class=['\"][^'\"]*null-data[^'\"]*['\"][^>]*>"
            r"(.*?)</div>",
            html,
            flags=re.I | re.S,
        )
        return {
            **self._learning_course_result(course),
            "search": search,
            "status": normalized_status or "all",
            "count": len(entries),
            "empty_message": html_text(empty_match.group(1)) if empty_match else "",
            result_key: entries,
            "verification": f"learner {result_key} list parsed without opening an item",
        }

