    def read_learning_knowledge_graph_model(
        self,
        course: dict[str, Any],
        model: str,
    ) -> dict[str, Any]:
        context = self._learning_knowledge_graph_context(course)
        selected = self._resolve_knowledge_graph_model(
            self._normalize_knowledge_graph_models(
                self._knowledge_graph_topic_setting_data(context)
            ),
            model,
        )
        config = self._knowledge_graph_config_data(context)
        data_json = config.get("dataJson") if isinstance(config.get("dataJson"), dict) else {}
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/coursetopic/mapmodeldata",
            "learner knowledge-graph model read",
            params={
                "courseid": context["common"]["courseid"],
                "cpi": context["common"]["cpi"],
                "clazzid": context["common"]["clazzid"],
                "topicModelId": selected["model_id"],
                "view": "json",
                "enc": str(data_json.get("exportCourseTopicEnc") or ""),
            },
        )
        self._knowledge_graph_ack(payload, "learner knowledge-graph model read")
        raw = payload.get("data") if isinstance(payload.get("data"), dict) else {}
        normalized = self._normalize_knowledge_graph_model_data(raw)
        return {
            **self._learning_course_result(course),
            "model": self._learning_graph_public_items([selected])[0],
            "count": normalized["count"],
            "nodes": self._learning_graph_public_items(normalized["nodes"]),
            "verification": "learner model-specific graph data refreshed through HTTP",
        }

    def list_learning_discussions(
        self,
        course: dict[str, Any],
        *,
        search: str = "",
        class_only: bool = False,
    ) -> dict[str, Any]:
        module = self._learning_module_response(course, "讨论")
        session = module["session"]
        context = module["course_context"]
        values = context.get("values") if isinstance(context.get("values"), dict) else {}
        bbs_id = str(values.get("bbsid") or "")
        if not bbs_id:
            raise ChaoxingAPIError("learner course response did not expose bbsid")
        endpoint = f"{GROUPWEB_BASE_URL}/course/topic/{bbs_id}/getTopicList"
        topics: list[dict[str, Any]] = []
        folders: list[dict[str, Any]] = []
        permissions: dict[str, Any] = {}
        last_reply_time = ""
        last_aux_value = ""
        page = 1
        server_search = "" if class_only and search else search
        while page <= 100:
            params: dict[str, Any] = {
                "folder_uuid": "",
                "page": str(page),
                "pageSize": "20",
                "kw": server_search,
                "courseId": course["course_id"],
                "isSetTop": "",
                "selectedStartTime": "",
                "selectedEndTime": "",
                "selectedType": "",
                "learnSilverStartTime": "",
                "learnSilverEndTime": "",
                "lastAuxValue": last_aux_value,
            }
            if last_reply_time:
                params["last_reply_time"] = last_reply_time
            if class_only:
                params["searchType"] = "4"
                params["classid"] = course["clazz_id"]
            try:
                response = session.post(
                    endpoint,
                    params=params,
                    timeout=max(self.timeout, 60),
                    allow_redirects=True,
                    headers={"Referer": str(module["response"].url)},
                )
                response.raise_for_status()
            except requests.RequestException as exc:
                raise ChaoxingAPIError("learner discussion list request failed") from exc
            payload = self._learning_json_response(response, "learner discussion list")
            if not payload.get("status"):
                raise ChaoxingAPIError(
                    str(payload.get("msg") or "failed to fetch learner discussions")
                )
            page_topics, page_folders = parse_discussion_payload(payload)
            topics.extend(page_topics)
            if page == 1:
                folders = page_folders
                user_auth = payload.get("userAuth")
                permissions = user_auth if isinstance(user_auth, dict) else {}
            poff = payload.get("poff") if isinstance(payload.get("poff"), dict) else {}
            if bool(poff.get("lastPage")) or not page_topics:
                break
            next_reply_time = str(poff.get("lastValue") or "")
            next_aux = str(poff.get("lastAuxValue") or "")
            if not next_reply_time or next_reply_time == last_reply_time:
                break
            last_reply_time = next_reply_time
            last_aux_value = next_aux
            page += 1
        if class_only and search:
            normalized_search = str(search).casefold()
            topics = [
                topic
                for topic in topics
                if normalized_search in str(topic.get("title") or "").casefold()
                or normalized_search in str(topic.get("content") or "").casefold()
                or normalized_search in str(topic.get("creator_name") or "").casefold()
            ]
        for index, topic in enumerate(topics, 1):
            topic["index"] = index
        return {
            **self._learning_course_result(course),
            "scope": "selected_class" if class_only else "course_all_classes",
            "search": search,
            "bbs_id": bbs_id,
            "count": len(topics),
            "folder_count": len(folders),
            "topics": topics,
            "folders": folders,
            "permissions": permissions,
            "verification": f"parsed {len(topics)} learner discussion topics through HTTP",
        }

    @staticmethod
    def _learning_integrity_state(context: dict[str, Any]) -> dict[str, Any]:
        values = context.get("values") if isinstance(context.get("values"), dict) else {}
        account_pending = str(values.get("notAgreeCommitment") or "").strip().lower()
        course_status = str(values.get("notAgreeCourseCommitment") or "").strip()
        state_known = account_pending in {"true", "false"} and course_status in {"-1", "0", "1"}
        required = (account_pending == "true" and course_status == "-1") or course_status == "0"
        accepted: bool | None
        if required:
            accepted = False
        elif course_status == "1" or (account_pending == "false" and course_status == "-1"):
            accepted = True
        else:
            accepted = None
        status = {
            "required": required,
            "accepted": accepted,
            "state_known": state_known,
            "account_commitment_pending": account_pending == "true",
            "course_commitment_status": course_status,
        }
        if course_status == "0":
            status["basis"] = "course-specific commitment is pending"
        elif account_pending == "true" and course_status == "-1":
            status["basis"] = "account commitment is pending and the course inherits it"
        elif course_status == "1":
            status["basis"] = "course-specific commitment is accepted"
        elif account_pending == "false" and course_status == "-1":
            status["basis"] = "account commitment is accepted and the course inherits it"
        else:
            status["basis"] = "page flags do not currently require acceptance"
        return status

    def read_learning_integrity(self, course: dict[str, Any]) -> dict[str, Any]:
        context = self._learning_course_context(self._session(), course)
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": course["clazz_id"],
            "commitment": self._learning_integrity_state(context),
            "verification": "integrity requirement derived from current course-page flags",
        }

    def accept_learning_integrity(self, course: dict[str, Any]) -> dict[str, Any]:
        session = self._session()
        context = self._learning_course_context(session, course)
        before = self._learning_integrity_state(context)
        if before["accepted"] is True:
            return {
                "course_id": course["course_id"],
                "course_name": course["course_name"],
                "clazz_id": course["clazz_id"],
                "before": before,
                "after": before,
                "changed": False,
                "verification": "course page already showed no pending integrity acceptance",
            }
        if before["required"] is not True:
            raise ChaoxingAPIError(
                "the current course page exposes no pending integrity acceptance to submit"
            )
        values = context["values"]
        try:
            response = session.get(
                LEARNING_INTEGRITY_UPDATE_URL,
                params={
                    "courseid": str(values.get("courseid") or course["course_id"]),
                    "clazzid": str(values.get("clazzid") or course["clazz_id"]),
                    "personid": str(values.get("personid") or course.get("cpi") or ""),
                    "type": "1",
                },
                timeout=self.timeout,
                headers={
                    "Referer": str(context["final_url"]),
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"learning-integrity acceptance failed: {exc}") from exc
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("learning-integrity response was not JSON") from exc
        if not isinstance(payload, dict) or payload.get("status") is not True:
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(
                str(message or "learning-integrity acceptance was not acknowledged")
            )
        after_context = self._learning_course_context(session, course)
        after = self._learning_integrity_state(after_context)
        if not after["accepted"]:
            raise ChaoxingAPIError(
                "server acknowledged integrity acceptance, but the refreshed course "
                "still requires it"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": course["clazz_id"],
            "before": before,
            "after": after,
            "changed": True,
            "server_message": str(payload.get("msg") or ""),
            "verification": (
                "server acknowledged acceptance and refreshed course flags no longer require it"
            ),
        }

    def list_classes(self, course_query: str) -> dict[str, Any]:
        course = self.get_course(course_query)
        return {
            "course": {key: value for key, value in course.items() if key != "classes"},
            "classes": course["classes"],
        }

    def create_class(self, course: dict[str, Any], name: str) -> dict[str, Any]:
        name = name.strip()
        if not name:
            raise ChaoxingAPIError("class name cannot be empty")
        if len(name) > 100:
            raise ChaoxingAPIError("class name cannot exceed 100 characters")
        classes = course.get("classes") if isinstance(course.get("classes"), list) else []
        if not classes:
            raise ChaoxingAPIError("course does not expose a class for management context")
        session = self._session()
        referer = self._management_referer(session, course, classes[0])
        endpoint = f"{MOOC2_BASE_URL}/mooc2-ans/tcm/create-clazz"
        try:
            response = session.get(
                endpoint,
                params={
                    "courseid": course["course_id"],
                    "newClazzName": name,
                    "cpi": course["cpi"],
                },
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"class creation failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "class creation was not acknowledged"))
        clazz_id = str(payload.get("clazzId") or "")
        if not clazz_id:
            raise ChaoxingAPIError("class creation response did not expose clazzId")
        refreshed_course = self.get_course(course["course_id"])
        created = resolve_class(refreshed_course, clazz_id)
        if created["clazz_name"] != name:
            raise ChaoxingAPIError(
                "server acknowledged class creation, but the refreshed name differs"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "class": created,
            "server_message": str(payload.get("msg") or ""),
            "verification": f"created class {clazz_id} appears in the refreshed course list",
        }

    def rename_class(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        name: str,
    ) -> dict[str, Any]:
        name = name.strip()
        if not name:
            raise ChaoxingAPIError("class name cannot be empty")
        if len(name) > 100:
            raise ChaoxingAPIError("class name cannot exceed 100 characters")
        session = self._session()
        referer = self._management_referer(session, course, clazz)
        endpoint = f"{MOOC2_BASE_URL}/mooc2-ans/tcm/update-clazzname"
        try:
            response = session.get(
                endpoint,
                params={
                    "courseid": course["course_id"],
                    "clazzName": name,
                    "cpi": course["cpi"],
                    "clazzid": clazz["clazz_id"],
                },
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"class rename failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "class rename was not acknowledged"))
        refreshed_course = self.get_course(course["course_id"])
        renamed = resolve_class(refreshed_course, clazz["clazz_id"])
        if renamed["clazz_name"] != name:
            raise ChaoxingAPIError(
                "server acknowledged the class rename, but the refreshed name differs"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "class": renamed,
            "server_message": str(payload.get("msg") or ""),
            "verification": f"refreshed class {clazz['clazz_id']} has name {name}",
        }

    def read_class_settings(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> dict[str, Any]:
        session = self._session()
        referer = self._management_referer(session, course, clazz)
        endpoint = f"{MOOC2_BASE_URL}/mooc2-ans/tcm/getclazzsetting"
        try:
            response = session.get(
                endpoint,
                params={
                    "courseid": course["course_id"],
                    "clazzid": clazz["clazz_id"],
                    "cpi": course["cpi"],
                },
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"class settings request failed: {exc}") from exc
        settings = parse_class_settings(self._decode(response))
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "settings": settings,
            "verification": "parsed current class settings from authenticated HTTP HTML",
        }

    def read_class_invitation(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> dict[str, Any]:
        session = self._session()
        referer = self._management_referer(session, course, clazz)
        endpoint = f"{MOOC2_BASE_URL}/mooc2-ans/tcm/show-clsinvitecode"
        try:
            response = session.get(
                endpoint,
                params={
                    "courseid": course["course_id"],
                    "clazzid": clazz["clazz_id"],
                    "cpi": course["cpi"],
                },
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"class invitation request failed: {exc}") from exc
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("class invitation response was not JSON") from exc
        if not isinstance(payload, dict) or payload.get("status") is not True:
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "class invitation request was not acknowledged"))
        invite_code = str(payload.get("inviteCode") or "").strip()
        if not invite_code:
            raise ChaoxingAPIError("class invitation response did not expose an invite code")

        def absolute_url(value: Any) -> str:
            raw = str(value or "").strip()
            return urljoin(MOOC2_BASE_URL, raw) if raw else ""

        return {
            "course_id": course["course_id"],
            "course_name": str(payload.get("courseName") or course["course_name"]),
            "clazz_id": clazz["clazz_id"],
            "clazz_name": str(payload.get("clazzName") or clazz["clazz_name"]),
            "invite_code": invite_code,
            "valid_until": str(payload.get("validTimeStr") or ""),
            "valid_until_epoch_ms": payload.get("qrCodeValidTime"),
            "qr_code_url": absolute_url(payload.get("qrCodeUrl")),
            "alternate_qr_code_url": absolute_url(payload.get("qrCodeUrl2")),
            "cover_image_url": absolute_url(payload.get("coverImg")),
            "invitation_code_hidden_in_vm": bool(payload.get("hideVmInvitationCode")),
            "verification": "read the current class invitation from authenticated HTTP JSON",
        }

    def update_class_settings(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        allow_student_join: bool | None = None,
        join_requires_approval: bool | None = None,
        unit_binding_requirement: str | None = None,
        allow_student_withdraw: bool | None = None,
        public_scope: str | None = None,
        student_limit: int | None = None,
        ended: bool | None = None,
        ignore_video_restrictions: bool | None = None,
        hidden_from_students: bool | None = None,
        semester_id: str | None = None,
        open_start: str | None = None,
        open_end: str | None = None,
        application_start: str | None = None,
        application_end: str | None = None,
    ) -> dict[str, Any]:
        requested = {
            "allow_student_join": allow_student_join,
            "join_requires_approval": join_requires_approval,
            "unit_binding_requirement": unit_binding_requirement,
            "allow_student_withdraw": allow_student_withdraw,
            "public_scope": public_scope,
            "student_limit": student_limit,
            "ended": ended,
            "ignore_video_restrictions": ignore_video_restrictions,
            "hidden_from_students": hidden_from_students,
            "semester_id": semester_id,
            "open_start": open_start,
            "open_end": open_end,
            "application_start": application_start,
            "application_end": application_end,
        }
        changes = {key: value for key, value in requested.items() if value is not None}
        if not changes:
            raise ChaoxingAPIError("at least one class setting must be supplied")
        if unit_binding_requirement not in {None, "none", "any_unit", "course_unit"}:
            raise ChaoxingAPIError(
                "unit_binding_requirement must be none, any_unit, or course_unit"
            )
        if public_scope not in {None, "closed", "school", "network"}:
            raise ChaoxingAPIError("public_scope must be closed, school, or network")
        if student_limit is not None and not 0 <= student_limit <= 20000:
            raise ChaoxingAPIError("student_limit must be between 0 and 20000")
        if (open_start is None) != (open_end is None):
            raise ChaoxingAPIError("open_start and open_end must be supplied together")
        if (application_start is None) != (application_end is None):
            raise ChaoxingAPIError(
                "application_start and application_end must be supplied together"
            )

        session = self._session()
        referer = self._management_referer(session, course, clazz)
        common = {
            "courseid": course["course_id"],
            "clazzid": clazz["clazz_id"],
            "cpi": course["cpi"],
        }
        requests_to_make: list[tuple[str, dict[str, Any]]] = []
        if allow_student_join is not None:
            requests_to_make.append(
                (
                    "/mooc2-ans/tcm/update-enableinvitecode",
                    {**common, "enableinvitecode": int(allow_student_join)},
                )
            )
        if join_requires_approval is not None:
            requests_to_make.append(
                (
                    "/mooc2-ans/coursemanage/intoclazzvalidation",
                    {
                        "courseId": course["course_id"],
                        "clazzId": clazz["clazz_id"],
                        "cpi": course["cpi"],
                        "intoclazzvalidation": int(join_requires_approval),
                    },
                )
            )
        if unit_binding_requirement is not None:
            requests_to_make.append(
                (
                    "/mooc2-ans/tcm/updateStuApplyFidRequired",
                    {
                        "courseId": course["course_id"],
                        "clazzId": clazz["clazz_id"],
                        "cpi": course["cpi"],
                        "stuApplyFidRequired": {
                            "none": 0,
                            "any_unit": 1,
                            "course_unit": 2,
                        }[unit_binding_requirement],
                    },
                )
            )
        if allow_student_withdraw is not None:
            requests_to_make.append(
                (
                    "/mooc2-ans/tcm/update-clazzretire",
                    {**common, "isRetire": int(allow_student_withdraw)},
                )
            )
        if public_scope is not None:
            requests_to_make.append(
                (
                    "/mooc2-ans/tcm/update-clazzispublic",
                    {**common, "isPublic": {"closed": 0, "school": 1, "network": 2}[public_scope]},
                )
            )
        if student_limit is not None:
            requests_to_make.append(
                ("/mooc2-ans/tcm/update-stunumlimit", {**common, "limitCount": student_limit})
            )
        if ended is not None:
            requests_to_make.append(
                ("/mooc2-ans/tcm/update-clazzstate", {**common, "clazzState": int(ended)})
            )
        if ignore_video_restrictions is not None:
            requests_to_make.append(
                (
                    "/mooc2-ans/tcm/update-videoctrl",
                    {**common, "ignoreVideoCtrl": int(ignore_video_restrictions)},
                )
            )
        if hidden_from_students is not None:
            requests_to_make.append(
                (
                    "/mooc2-ans/tcm/updatehideclazz",
                    {
                        "courseId": course["course_id"],
                        "clazzId": clazz["clazz_id"],
                        "cpi": course["cpi"],
                        "hideClazz": int(hidden_from_students),
                    },
                )
            )
        if semester_id is not None:
            requests_to_make.append(
                ("/mooc2-ans/tcm/update-semester", {**common, "semesterId": semester_id})
            )
        if open_start is not None and open_end is not None:
            requests_to_make.append(
                (
                    "/mooc2-ans/tcm/update-opentime",
                    {**common, "startTime": open_start, "endTime": open_end},
                )
            )
        if application_start is not None and application_end is not None:
            requests_to_make.append(
                (
                    "/mooc2-ans/tcm/update-applytime",
                    {
                        **common,
                        "applyBeginDate": application_start,
                        "applyEndDate": application_end,
                    },
                )
            )

        acknowledgements: list[str] = []
        for path, params in requests_to_make:
            try:
                response = session.get(
                    f"{MOOC2_BASE_URL}{path}",
                    params=params,
                    timeout=self.timeout,
                    headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
                )
                response.raise_for_status()
                payload = json.loads(self._decode(response))
            except (requests.RequestException, json.JSONDecodeError) as exc:
                raise ChaoxingAPIError(f"class setting update failed for {path}: {exc}") from exc
            if not isinstance(payload, dict) or not payload.get("status"):
                message = payload.get("msg") if isinstance(payload, dict) else ""
                raise ChaoxingAPIError(str(message or f"class setting update failed for {path}"))
            acknowledgements.append(str(payload.get("msg") or path))

        after = self.read_class_settings(course, clazz)
        actual = after["settings"]
        expected: dict[str, Any] = {}
        for key in (
            "allow_student_join",
            "join_requires_approval",
            "unit_binding_requirement",
            "allow_student_withdraw",
            "public_scope",
            "student_limit",
            "ignore_video_restrictions",
            "hidden_from_students",
        ):
            if requested[key] is not None:
                expected[key] = requested[key]
        if ended is not None:
            expected["state"] = "ended" if ended else "active"
        if open_start is not None:
            expected["open_start"] = open_start
            expected["open_end"] = open_end
        if application_start is not None:
            expected["application_start"] = application_start
            expected["application_end"] = application_end
        if semester_id is not None:
            semester = next(
                (
                    item
                    for item in actual["available_semesters"]
                    if item["semester_id"] == str(semester_id)
                ),
                None,
            )
            if semester is None:
                raise ChaoxingAPIError("selected semester is absent from refreshed settings")
            expected["semester_name"] = semester["name"]
        mismatches = {
            key: {"expected": value, "actual": actual.get(key)}
            for key, value in expected.items()
            if actual.get(key) != value
        }
        if mismatches:
            raise ChaoxingAPIError(
                "server acknowledged class settings, but refreshed values differ: "
                + json.dumps(mismatches, ensure_ascii=False)
            )
        return {
            **after,
            "changes": changes,
            "server_messages": acknowledgements,
            "verification": f"re-read {len(expected)} changed class setting value(s)",
        }

    def delete_class(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> dict[str, Any]:
        session = self._session()
        referer = self._management_referer(session, course, clazz)
        endpoint = f"{MOOC2_BASE_URL}/mooc2-ans/tcm/delete-clazz"
        try:
            response = session.get(
                endpoint,
                params={
                    "courseid": course["course_id"],
                    "clazzid": clazz["clazz_id"],
                    "cpi": course["cpi"],
                },
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"class deletion failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "class deletion was not acknowledged"))
        refreshed = self.get_course(course["course_id"])
        if any(item["clazz_id"] == clazz["clazz_id"] for item in refreshed["classes"]):
            raise ChaoxingAPIError(
                "server acknowledged class deletion, but the class is still listed"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "deleted_class": clazz,
            "deleted": True,
            "server_message": str(payload.get("msg") or ""),
            "verification": f"class {clazz['clazz_id']} is absent from the refreshed course list",
        }

    def _student_management_fields(
        self,
        session: requests.Session,
        course: dict[str, Any],
        clazz: dict[str, Any],
        referer: str,
    ) -> tuple[str, dict[str, str]]:
        endpoint = f"{MOOC2_BASE_URL}/mooc2-ans/tcm/clazz-manage"
        try:
            response = session.get(
                endpoint,
                params={
                    "courseid": course["course_id"],
                    "clazzid": clazz["clazz_id"],
                    "v": "0",
                    "cpi": course["cpi"],
                },
                timeout=self.timeout,
                headers={"Referer": referer},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"student management context request failed: {exc}") from exc
        fields = parse_hidden_inputs(self._decode(response))
        return response.url, fields

    def search_student_bank_candidates(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        query: str,
        *,
        page: int = 1,
        page_size: int = 30,
    ) -> dict[str, Any]:
        query = query.strip()
        if not query:
            raise ChaoxingAPIError("student-bank search query cannot be empty")
        if page < 1:
            raise ChaoxingAPIError("page must be at least 1")
        if page_size not in {30, 50, 100}:
            raise ChaoxingAPIError("page_size must be 30, 50, or 100")
        session = self._session()
        referer = self._management_referer(session, course, clazz)
        management_url, fields = self._student_management_fields(session, course, clazz, referer)
        school_id = str(fields.get("stuBankAddStuFid") or "")
        enc = str(fields.get("stuBankAddStuEnc") or "")
        if not school_id or not enc:
            raise ChaoxingAPIError(
                "class management page did not expose student-bank authorization fields"
            )
        try:
            response = session.post(
                f"{MOOC2_BASE_URL}/mooc2-ans/tcm/searchStudent",
                data={
                    "cpi": course["cpi"],
                    "schoolId": school_id,
                    "searchAddStu": query,
                    "departmentId": "",
                    "majorId": "",
                    "classId": "",
                    "ranksId": "",
                    "directionId": "",
                    "pageNum": page,
                    "courseId": course["course_id"],
                    "clazzId": clazz["clazz_id"],
                    "pageSize": page_size,
                    "enc": enc,
                },
                timeout=self.timeout,
                headers={"Referer": management_url, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"student-bank search request failed: {exc}") from exc
        candidates, total = parse_student_bank_candidates(self._decode(response))
        public_candidates = []
        for index, candidate in enumerate(candidates, (page - 1) * page_size + 1):
            public_candidate = {
                key: value for key, value in candidate.items() if key != "selection_enc"
            }
            public_candidate["index"] = index
            public_candidates.append(public_candidate)
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "query": query,
            "page": page,
            "page_size": page_size,
            "server_total": total,
            "count": len(public_candidates),
            "candidates": public_candidates,
            "verification": (
                f"parsed {len(public_candidates)} matching student-bank records from HTTP HTML"
            ),
        }

    def add_student_from_bank(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        student_query: str,
    ) -> dict[str, Any]:
        listing = self.search_student_bank_candidates(
            course,
            clazz,
            student_query,
            page_size=100,
        )
        candidate = resolve_student_bank_candidate(listing["candidates"], student_query)
        session = self._session()
        referer = self._management_referer(session, course, clazz)
        try:
            response = session.post(
                f"{MOOC2_BASE_URL}/mooc2-ans/tcm/addstubylibrary",
                data={
                    "personIdStr": candidate["person_id"],
                    "courseId": course["course_id"],
                    "clazzId": clazz["clazz_id"],
                    "addType": 1,
                    "cpi": course["cpi"],
                },
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"student-bank add request failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "student-bank add was not acknowledged"))
        refreshed = self.list_class_students(course, clazz)
        added = resolve_class_student(refreshed["students"], candidate["person_id"])
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "student": added,
            "server_message": str(payload.get("msg") or ""),
            "verification": "added person ID appears in a fresh HTTP class-student listing",
        }

    def add_student_by_identity(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        name: str,
        identity: str,
        identity_type: str = "student_no",
        school_id: str = "",
    ) -> dict[str, Any]:
        name = name.strip()
        identity = identity.strip()
        if not name or not identity:
            raise ChaoxingAPIError("student name and identity cannot be empty")
        identity_codes = {
            "student_no": 0,
            "employee_no": 0,
            "mobile": 1,
            "email": 3,
        }
        if identity_type not in identity_codes:
            raise ChaoxingAPIError(
                "identity_type must be student_no, employee_no, mobile, or email"
            )
        session = self._session()
        referer = self._management_referer(session, course, clazz)
        management_url, fields = self._student_management_fields(session, course, clazz, referer)
        selected_school_id = school_id.strip() or str(fields.get("handAddStuFid") or "")
        if not selected_school_id:
            raise ChaoxingAPIError("class management page did not expose a school ID")
        try:
            response = session.get(
                f"{MOOC2_BASE_URL}/mooc2-ans/tcm/addstubyhand",
                params={
                    "loginName": identity,
                    "cpi": course["cpi"],
                    "realName": name,
                    "fid": selected_school_id,
                    "courseId": course["course_id"],
                    "handAddStudentType": identity_codes[identity_type],
                    "clazzId": clazz["clazz_id"],
                },
                timeout=self.timeout,
                headers={"Referer": management_url, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"manual student add request failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "manual student add was not acknowledged"))
        refreshed = self.list_class_students(course, clazz, search=identity)
        added = resolve_class_student(refreshed["students"], identity)
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "student": added,
            "identity_type": identity_type,
            "server_message": str(payload.get("msg") or ""),
            "verification": "new identity appears in a fresh HTTP class-student listing",
        }

    def remove_student(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        student_query: str,
    ) -> dict[str, Any]:
        before_listing = self.list_class_students(course, clazz, search=student_query)
        student = resolve_class_student(before_listing["students"], student_query)
        session = self._session()
        referer = self._management_referer(session, course, clazz)
        try:
            response = session.get(
                f"{MOOC2_BASE_URL}/mooc2-ans/tcm/delete-clazzstu",
                params={
                    "courseid": course["course_id"],
                    "clazzid": clazz["clazz_id"],
                    "cpi": course["cpi"],
                    "personIds": student["person_id"],
                },
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"student removal request failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "student removal was not acknowledged"))
        refreshed = self.list_class_students(course, clazz)
        if any(item["person_id"] == student["person_id"] for item in refreshed["students"]):
            raise ChaoxingAPIError(
                "server acknowledged student removal, but the student is still listed"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "removed_student": student,
            "server_message": str(payload.get("msg") or ""),
            "verification": "removed person ID is absent from a fresh HTTP class-student listing",
        }

    def list_class_join_applications(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> dict[str, Any]:
        session = self._session()
        referer = self._management_referer(session, course, clazz)
        try:
            response = session.get(
                f"{MOOC2_BASE_URL}/mooc2-ans/coursemanage/codeaddclazzapplydata",
                params={
                    "courseId": course["course_id"],
                    "clazzId": clazz["clazz_id"],
                    "cpi": course["cpi"],
                },
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"class join-application request failed: {exc}") from exc
        applications, total = parse_class_join_applications(self._decode(response))
        if total and not applications:
            raise ChaoxingAPIError(
                "join-application page reports pending records, but no rows could be parsed"
            )
        for index, application in enumerate(applications, 1):
            application["index"] = index
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "server_total": total,
            "count": len(applications),
            "applications": applications,
            "verification": f"parsed {len(applications)} pending join applications from HTTP HTML",
        }

    def decide_class_join_application(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        application_query: str,
        decision: str,
    ) -> dict[str, Any]:
        if decision not in {"approve", "reject"}:
            raise ChaoxingAPIError("decision must be approve or reject")
        before = self.list_class_join_applications(course, clazz)
        application = resolve_class_join_application(before["applications"], application_query)
        session = self._session()
        referer = self._management_referer(session, course, clazz)
        try:
            response = session.get(
                f"{MOOC2_BASE_URL}/mooc2-ans/coursemanage/updatecodeaddclzstatus",
                params={
                    "courseId": course["course_id"],
                    "clazzId": clazz["clazz_id"],
                    "cpi": course["cpi"],
                    "status": 1 if decision == "approve" else 2,
                    "logIds": application["log_id"],
                },
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"class join-application decision failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "join-application decision was not acknowledged"))
        refreshed = self.list_class_join_applications(course, clazz)
        if any(item["log_id"] == application["log_id"] for item in refreshed["applications"]):
            raise ChaoxingAPIError(
                "server acknowledged the decision, but the application is still pending"
            )
        verification = "decided log ID is absent from a fresh pending-application read"
        student: dict[str, Any] | None = None
        if decision == "approve":
            identity = str(application.get("student_no") or application.get("student_name") or "")
            if identity:
                students = self.list_class_students(course, clazz, search=identity)
                student = resolve_class_student(students["students"], identity)
                verification += "; approved student appears in the class listing"
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "decision": decision,
            "application": application,
            "student": student,
            "server_message": str(payload.get("msg") or ""),
            "verification": verification,
        }

    def move_student(
        self,
        course: dict[str, Any],
        source_clazz: dict[str, Any],
        target_clazz_query: str,
        student_query: str,
    ) -> dict[str, Any]:
        target_clazz = resolve_class(course, target_clazz_query)
        if target_clazz["clazz_id"] == source_clazz["clazz_id"]:
            raise ChaoxingAPIError("source and target class must differ")
        source_listing = self.list_class_students(
            course,
            source_clazz,
            search=student_query,
        )
        student = resolve_class_student(source_listing["students"], student_query)
        session = self._session()
        referer = self._management_referer(session, course, source_clazz)
        try:
            response = session.get(
                f"{MOOC2_BASE_URL}/mooc2-ans/tcm/change-clazz",
                params={
                    "courseId": course["course_id"],
                    "oldClazzId": source_clazz["clazz_id"],
                    "newClazzId": target_clazz["clazz_id"],
                    "personIds": f"{student['person_id']},",
                    "cpi": course["cpi"],
                },
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"student class-move request failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "student class move was not acknowledged"))
        refreshed_source = self.list_class_students(course, source_clazz)
        refreshed_target = self.list_class_students(course, target_clazz)
        if any(item["person_id"] == student["person_id"] for item in refreshed_source["students"]):
            raise ChaoxingAPIError(
                "server acknowledged the class move, but the student remains in the source class"
            )
        moved = resolve_class_student(refreshed_target["students"], student["person_id"])
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "source_class": source_clazz,
            "target_class": target_clazz,
            "student": moved,
            "server_message": str(payload.get("msg") or ""),
            "verification": (
                "person ID is absent from the source class and present in the target class"
            ),
        }

    def list_class_students(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        search: str = "",
        school_status: int = 0,
    ) -> dict[str, Any]:
        session = self._session()
        context = self._course_context(session, course, clazz)
        module = resolve_module(context["modules"], "管理")
        manage_url = self._module_url(context, module, course, clazz)
        try:
            landing = session.get(
                manage_url,
                timeout=self.timeout,
                allow_redirects=True,
                headers={"Referer": str(context["final_url"])},
            )
            landing.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"class management request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in landing.url.lower():
            raise ChaoxingAPIError(
                f"class management request was redirected to login: {landing.url}"
            )
        landing_hidden = parse_hidden_inputs(self._decode(landing))
        endpoint = f"{MOOC2_BASE_URL}/mooc2-ans/tcm/clazz-student"
        page_size = 100
        page = 1
        server_total: int | None = None
        students: list[dict[str, Any]] = []
        seen: set[str] = set()
        while page <= 200:
            try:
                response = session.get(
                    endpoint,
                    params={
                        "courseid": course["course_id"],
                        "clazzid": clazz["clazz_id"],
                        "requireStu": search,
                        "cpi": course["cpi"],
                        "pageNum": str(page),
                        "pageShowNum": str(page_size),
                        "orderContent": "",
                        "schoolStatus": str(school_status),
                        "v": landing_hidden.get("coruseManageV") or "0",
                        "order": "",
                    },
                    timeout=self.timeout,
                    allow_redirects=True,
                    headers={"Referer": landing.url},
                )
                response.raise_for_status()
            except requests.RequestException as exc:
                raise ChaoxingAPIError(f"class student list request failed: {exc}") from exc
            if "passport2.chaoxing.com/login" in response.url.lower():
                raise ChaoxingAPIError(
                    f"class student request was redirected to login: {response.url}"
                )
            page_students, page_total, _current_page = parse_class_student_table(
                self._decode(response), response.url
            )
            if server_total is None and page_total is not None:
                server_total = page_total
            for student in page_students:
                identity = student["person_id"]
                if identity in seen:
                    continue
                seen.add(identity)
                students.append(student)
            if not page_students or len(page_students) < page_size:
                break
            if server_total is not None and len(students) >= server_total:
                break
            page += 1

        for index, student in enumerate(students, 1):
            student["index"] = index
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "search": search,
            "school_status": school_status,
            "server_total": server_total,
            "count": len(students),
            "students": students,
            "verification": (
                f"parsed {len(students)} class student records across {page} HTTP page(s)"
            ),
        }

    def list_student_access_logs(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        student_query: str,
        *,
        year: int | None = None,
        month: int | None = None,
        day: int = 0,
    ) -> dict[str, Any]:
        today = date.today()
        selected_year = year or today.year
        selected_month = month or today.month
        if not 1 <= selected_month <= 12:
            raise ChaoxingAPIError("month must be between 1 and 12")
        if day:
            try:
                date(selected_year, selected_month, day)
            except ValueError as exc:
                raise ChaoxingAPIError(f"invalid access-log date: {exc}") from exc

        student_listing = self.list_class_students(
            course,
            clazz,
            search=student_query,
        )
        student = resolve_class_student(student_listing["students"], student_query)
        access_url = str(student.get("access_log_url") or "")
        if not access_url:
            access_url = append_query_params(
                f"{MOOC2_BASE_URL}/mooc2-ans/moocanalysis/accesslog",
                {
                    "courseid": course["course_id"],
                    "clazzid": clazz["clazz_id"],
                    "cpi": course["cpi"],
                    "ut": "t",
                    "stucpi": student["person_id"],
                    "from": "1",
                },
            )
        session = self._session()
        try:
            landing = session.get(access_url, timeout=self.timeout, allow_redirects=True)
            landing.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"student access-log page request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in landing.url.lower():
            raise ChaoxingAPIError(
                f"student access-log request was redirected to login: {landing.url}"
            )
        summary = parse_student_access_summary(self._decode(landing))
        common_params = {
            "clazzid": clazz["clazz_id"],
            "courseid": course["course_id"],
            "cpi": course["cpi"],
            "stucpi": student["person_id"],
        }
        month_endpoint = f"{MOOC2_BASE_URL}/mooc2-ans/moocanalysis/getmonthpv"
        try:
            month_response = session.get(
                month_endpoint,
                params={
                    **common_params,
                    "year": str(selected_year),
                    "month": str(selected_month),
                },
                timeout=self.timeout,
                headers={"Referer": landing.url},
            )
            month_response.raise_for_status()
            month_payload = json.loads(self._decode(month_response))
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"student monthly access request failed: {exc}") from exc
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("student monthly access response was not JSON") from exc
        if not isinstance(month_payload, dict):
            raise ChaoxingAPIError("student monthly access response had an invalid shape")

        logs: list[dict[str, Any]] = []
        page_size = 100
        page = 1
        page_count = 1
        total_count = 0
        log_endpoint = f"{MOOC2_BASE_URL}/mooc2-ans/moocanalysis/log"
        while page <= page_count and page <= 200:
            try:
                response = session.get(
                    log_endpoint,
                    params={
                        **common_params,
                        "year": str(selected_year),
                        "month": str(selected_month),
                        "day": str(day),
                        "pageNum": str(page),
                        "pageSize": str(page_size),
                    },
                    timeout=self.timeout,
                    headers={"Referer": landing.url},
                )
                response.raise_for_status()
            except requests.RequestException as exc:
                raise ChaoxingAPIError(f"student access-log request failed: {exc}") from exc
            try:
                payload = json.loads(self._decode(response))
            except json.JSONDecodeError as exc:
                raise ChaoxingAPIError("student access-log response was not JSON") from exc
            if not isinstance(payload, dict):
                raise ChaoxingAPIError("student access-log response had an invalid shape")
            page_logs, page_info = parse_student_access_log_payload(payload, selected_year)
            logs.extend(page_logs)
            page_count = max(1, page_info["page_count"])
            total_count = page_info["total_count"]
            page += 1

        raw_dates = month_payload.get("date")
        raw_counts = month_payload.get("count")
        dates = raw_dates if isinstance(raw_dates, list) else []
        counts = raw_counts if isinstance(raw_counts, list) else []
        daily_counts = [
            {"date": str(day_label), "count": count}
            for day_label, count in zip(dates, counts, strict=False)
        ]
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "student": student,
            "year": selected_year,
            "month": selected_month,
            "day": day,
            "summary": summary,
            "monthly_visit_count": month_payload.get("total"),
            "daily_visit_counts": daily_counts,
            "server_total": total_count,
            "count": len(logs),
            "logs": logs,
            "verification": (
                f"parsed {len(logs)} student access events across {max(1, page - 1)} "
                "authenticated HTTP page(s)"
            ),
        }

    def _management_referer(
        self,
        session: requests.Session,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> str:
        context = self._course_context(session, course, clazz)
        module = resolve_module(context["modules"], "管理")
        return self._module_url(context, module, course, clazz)

    def list_course_operation_logs(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        module: str = "",
        search: str = "",
        start_date: str = "",
        end_date: str = "",
    ) -> dict[str, Any]:
        session = self._session()
        referer = self._management_referer(session, course, clazz)
        endpoint = f"{MOOC2_BASE_URL}/mooc2-ans/tcm/operational-log"

        def fetch(page: int, module_code: str, module_name: str) -> str:
            try:
                response = session.get(
                    endpoint,
                    params={
                        "courseId": course["course_id"],
                        "cpi": course["cpi"],
                        "pageNum": page,
                        "moduleCode": module_code,
                        "moduleName": module_name,
                        "startDate": start_date,
                        "endDate": end_date,
                        "kw": search,
                        "showStartDateTime": start_date,
                        "showEndDateTime": end_date,
                    },
                    timeout=self.timeout,
                    headers={"Referer": referer},
                )
                response.raise_for_status()
            except requests.RequestException as exc:
                raise ChaoxingAPIError(f"course operation-log request failed: {exc}") from exc
            return self._decode(response)

        initial_html = fetch(1, "0", "")
        _, _, modules = parse_course_operation_log_rows(initial_html)
        module_code = "0"
        module_name = ""
        if module.strip():
            normalized = module.strip().lower()
            exact = [
                item
                for item in modules
                if normalized
                in {
                    str(item.get("id") or "").lower(),
                    str(item.get("name") or "").strip().lower(),
                }
            ]
            if len(exact) != 1:
                partial = [
                    item
                    for item in modules
                    if normalized in str(item.get("name") or "").strip().lower()
                ]
                exact = partial
            if len(exact) != 1:
                available = ", ".join(str(item.get("name") or "") for item in modules)
                raise ChaoxingAPIError(
                    f"operation-log module must match exactly one module; available: {available}"
                )
            module_code = str(exact[0].get("id") or "0")
            module_name = str(exact[0].get("name") or "")

        records: list[dict[str, Any]] = []
        seen: set[tuple[str, ...]] = set()
        total: int | None = None
        page = 1
        while page <= 200:
            html = (
                initial_html
                if page == 1 and module_code == "0" and not start_date and not end_date
                else fetch(page, module_code, module_name)
            )
            page_records, page_total, page_modules = parse_course_operation_log_rows(html)
            if page == 1:
                total = page_total
                if page_modules:
                    modules = page_modules
            new_records = []
            for record in page_records:
                key = (
                    record["operator_name"],
                    record["operator_no"],
                    record["operation"],
                    record["ip"],
                    record["operation_time"],
                )
                if key in seen:
                    continue
                seen.add(key)
                new_records.append(record)
            records.extend(new_records)
            if not page_records or (total is not None and len(records) >= total):
                break
            page += 1
        for index, item in enumerate(records, 1):
            item["index"] = index
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "module": {"id": module_code, "name": module_name or "全部"},
            "available_modules": modules,
            "search": search,
            "start_date": start_date,
            "end_date": end_date,
            "server_total": total,
            "count": len(records),
            "records": records,
            "verification": f"parsed {len(records)} teacher operation logs through HTTP",
        }

