    def restore_student_from_leave_log(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        student_query: str,
    ) -> dict[str, Any]:
        before_listing = self.list_student_leave_logs(course, clazz, search=student_query)
        before = resolve_student_leave_log(before_listing["records"], student_query)
        if not before["restorable"]:
            raise ChaoxingAPIError("selected student leave record is not restorable")
        session = self._session()
        referer = self._management_referer(session, course, clazz)
        try:
            response = session.get(
                f"{MOOC2_BASE_URL}/mooc2-ans/tcm/recoverystudy",
                params={
                    "courseid": course["course_id"],
                    "personDropIds": before["person_drop_id"],
                    "cpi": course["cpi"],
                },
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"student restore request failed: {exc}") from exc
        try:
            result = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("student restore response was not JSON") from exc
        if not isinstance(result, dict) or result.get("status") is not True:
            message = result.get("msg") if isinstance(result, dict) else ""
            raise ChaoxingAPIError(str(message or "student restore was not acknowledged"))
        after = self.list_student_leave_logs(course, clazz, search=student_query)
        if any(item["person_drop_id"] == before["person_drop_id"] for item in after["records"]):
            raise ChaoxingAPIError(
                "student restore was acknowledged, but the leave record is still restorable"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "restored_record": before,
            "server_message": str(result.get("msg") or ""),
            "verification": "restored leave-record ID is absent from a fresh HTTP read",
        }

    def list_course_teachers(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        search: str = "",
        role: int = 0,
    ) -> dict[str, Any]:
        session = self._session()
        context = self._course_context(session, course, clazz)
        module = resolve_module(context["modules"], "管理")
        manage_url = self._module_url(context, module, course, clazz)
        try:
            landing = session.get(
                manage_url,
                timeout=self.timeout,
                allow_redirects=True,
                headers={"Referer": str(context["final_url"])},
            )
            landing.raise_for_status()
            response = session.get(
                f"{MOOC2_BASE_URL}/mooc2-ans/tcm/teacher-team-manage",
                params={
                    "courseid": course["course_id"],
                    "requireTea": "",
                    "cpi": course["cpi"],
                    "orderContentTeam": "ID",
                    "orderTeam": "up",
                    "role": str(role),
                },
                timeout=self.timeout,
                allow_redirects=True,
                headers={"Referer": landing.url},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"teacher team request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError(f"teacher team request was redirected to login: {response.url}")
        teachers, server_total = parse_teacher_team(self._decode(response))
        if search.strip():
            normalized = search.strip().lower()
            teachers = [
                teacher
                for teacher in teachers
                if any(
                    normalized in str(teacher.get(key) or "").strip().lower()
                    for key in ("person_id", "uid", "teacher_name", "teacher_no", "role")
                )
            ]
        for index, teacher in enumerate(teachers, 1):
            teacher["index"] = index
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "search": search,
            "role_filter": role,
            "server_total": server_total,
            "count": len(teachers),
            "teachers": teachers,
            "verification": (
                f"parsed {len(teachers)} teacher-team records from authenticated HTTP"
            ),
        }

    def _teacher_management_context(
        self,
        session: requests.Session,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> tuple[str, dict[str, str]]:
        referer = self._management_referer(session, course, clazz)
        try:
            response = session.get(
                f"{MOOC2_BASE_URL}/mooc2-ans/tcm/teacher-team-manage",
                params={
                    "courseid": course["course_id"],
                    "cpi": course["cpi"],
                    "role": 0,
                    "requireTea": "",
                },
                timeout=self.timeout,
                headers={"Referer": referer},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"teacher management context request failed: {exc}") from exc
        html = self._decode(response)
        fields = parse_hidden_inputs(html)
        for input_id in ("queryFid", "query2Fid", "stuBankGetStuEnc"):
            attrs = input_attrs_by_id(html, input_id)
            if attrs.get("value"):
                fields[input_id] = attrs["value"]
        return response.url, fields

    def search_teacher_bank_candidates(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        query: str,
        *,
        role: str = "teacher",
        page: int = 1,
        include_internal: bool = False,
    ) -> dict[str, Any]:
        query = query.strip()
        if not query:
            raise ChaoxingAPIError("teacher-bank search query cannot be empty")
        if role not in {"teacher", "assistant"}:
            raise ChaoxingAPIError("role must be teacher or assistant")
        if page < 1:
            raise ChaoxingAPIError("page must be at least 1")
        session = self._session()
        management_url, fields = self._teacher_management_context(session, course, clazz)
        school_id = str(fields.get("queryFid") or "")
        enc = str(fields.get("stuBankGetStuEnc") or "")
        if not school_id or not enc:
            raise ChaoxingAPIError(
                "teacher management page did not expose teacher-bank authorization fields"
            )
        try:
            response = session.get(
                f"{MOOC2_BASE_URL}/mooc2-ans/tcm/searchteacher",
                params={
                    "courseId": course["course_id"],
                    "queryName": query,
                    "groupid": "",
                    "pageNum": page,
                    "enc": enc,
                    "isAssistant": "true" if role == "assistant" else "false",
                    "fid": school_id,
                },
                timeout=self.timeout,
                headers={"Referer": management_url, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"teacher-bank search request failed: {exc}") from exc
        candidates, total = parse_teacher_bank_candidates(self._decode(response))
        output_candidates = []
        for index, candidate in enumerate(candidates, 1):
            output = dict(candidate)
            output["index"] = index
            if not include_internal:
                output.pop("selection_enc", None)
            output_candidates.append(output)
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "query": query,
            "role": role,
            "page": page,
            "server_total": total,
            "count": len(output_candidates),
            "candidates": output_candidates,
            "verification": (
                f"parsed {len(output_candidates)} matching teacher-bank records from HTTP HTML"
            ),
        }

    def add_course_teacher_from_bank(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        teacher_query: str,
        *,
        role: str = "teacher",
    ) -> dict[str, Any]:
        listing = self.search_teacher_bank_candidates(
            course,
            clazz,
            teacher_query,
            role=role,
            include_internal=True,
        )
        candidate = resolve_teacher_bank_candidate(listing["candidates"], teacher_query)
        session = self._session()
        referer = self._management_referer(session, course, clazz)
        try:
            response = session.post(
                f"{MOOC2_BASE_URL}/mooc2-ans/tcm/addteamteacher",
                data={
                    "courseId": course["course_id"],
                    "cpi": course["cpi"],
                    "isAssistant": "true" if role == "assistant" else "false",
                    "userDataStr": json.dumps(
                        [
                            {
                                "personId": candidate["person_id"],
                                "enc": candidate["selection_enc"],
                            }
                        ],
                        ensure_ascii=False,
                        separators=(",", ":"),
                    ),
                },
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"teacher-bank add request failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "teacher-bank add was not acknowledged"))
        refreshed = self.list_course_teachers(course, clazz, search=candidate["teacher_no"])
        added = resolve_course_teacher(refreshed["teachers"], candidate["person_id"])
        if role == "assistant" and added["role"] != "助教":
            raise ChaoxingAPIError("added team member did not acquire the requested assistant role")
        if role == "teacher" and added["role"] != "教师":
            raise ChaoxingAPIError("added team member did not acquire the requested teacher role")
        added_candidate = {key: value for key, value in candidate.items() if key != "selection_enc"}
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "role": role,
            "candidate": added_candidate,
            "teacher": added,
            "server_message": str(payload.get("msg") or ""),
            "verification": "new person ID and requested role appear in a fresh team listing",
        }

    def add_course_teacher_by_identity(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        name: str,
        identity: str,
        identity_type: str = "employee_no",
        role: str = "teacher",
        school_id: str = "",
    ) -> dict[str, Any]:
        name = name.strip()
        identity = identity.strip()
        if not name or not identity:
            raise ChaoxingAPIError("teacher name and identity cannot be empty")
        if role not in {"teacher", "assistant"}:
            raise ChaoxingAPIError("role must be teacher or assistant")
        identity_codes = {"employee_no": 0, "student_no": 0, "mobile": 1, "chaoxing_no": 2}
        if identity_type not in identity_codes:
            raise ChaoxingAPIError(
                "identity_type must be employee_no, student_no, mobile, or chaoxing_no"
            )
        session = self._session()
        management_url, fields = self._teacher_management_context(session, course, clazz)
        selected_school_id = school_id.strip() or str(fields.get("query2Fid") or "")
        if not selected_school_id:
            raise ChaoxingAPIError("teacher management page did not expose a school ID")
        try:
            response = session.get(
                f"{MOOC2_BASE_URL}/mooc2-ans/tcm/addteacherbyhand",
                params={
                    "courseId": course["course_id"],
                    "cpi": course["cpi"],
                    "realName": name,
                    "fid": selected_school_id,
                    "isAssistant": "true" if role == "assistant" else "false",
                    "handAddTchType": identity_codes[identity_type],
                    "userName": identity,
                },
                timeout=self.timeout,
                headers={"Referer": management_url, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"manual teacher add request failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "manual teacher add was not acknowledged"))
        refreshed = self.list_course_teachers(course, clazz, search=identity)
        added = resolve_course_teacher(refreshed["teachers"], identity)
        expected_label = "助教" if role == "assistant" else "教师"
        if added["role"] != expected_label:
            raise ChaoxingAPIError("added team member did not acquire the requested role")
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "role": role,
            "identity_type": identity_type,
            "teacher": added,
            "server_message": str(payload.get("msg") or ""),
            "verification": "new identity and requested role appear in a fresh team listing",
        }

    def remove_course_teacher(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        teacher_query: str,
    ) -> dict[str, Any]:
        listing = self.list_course_teachers(course, clazz, search=teacher_query)
        teacher = resolve_course_teacher(listing["teachers"], teacher_query)
        if teacher["role"] == "创建者":
            raise ChaoxingAPIError("the course creator cannot be removed from the teaching team")
        if not teacher["person_id"]:
            raise ChaoxingAPIError("selected teaching-team record has no removable person ID")
        session = self._session()
        referer = self._management_referer(session, course, clazz)
        try:
            response = session.get(
                f"{MOOC2_BASE_URL}/mooc2-ans/tcm/removeteamteaher",
                params={
                    "courseId": course["course_id"],
                    "cpi": course["cpi"],
                    "personIds": teacher["person_id"],
                },
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"teaching-team removal request failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "teaching-team removal was not acknowledged"))
        refreshed = self.list_course_teachers(course, clazz)
        if any(item["person_id"] == teacher["person_id"] for item in refreshed["teachers"]):
            raise ChaoxingAPIError(
                "server acknowledged teaching-team removal, but the member is still listed"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "removed_teacher": teacher,
            "server_message": str(payload.get("msg") or ""),
            "verification": "removed person ID is absent from a fresh teaching-team listing",
        }

    def read_course_teacher_permissions(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        teacher_query: str,
    ) -> dict[str, Any]:
        listing = self.list_course_teachers(course, clazz, search=teacher_query)
        teacher = resolve_course_teacher(listing["teachers"], teacher_query)
        if teacher["role"] == "创建者" or not teacher["person_id"]:
            return {
                "course_id": course["course_id"],
                "course_name": course["course_name"],
                "teacher": teacher,
                "editable": False,
                "role_code": teacher.get("role_code") or "creator",
                "permissions": {},
                "message": "course creator permissions are not exposed by this endpoint",
                "verification": "creator record was resolved from the current team listing",
            }
        session = self._session()
        referer = self._management_referer(session, course, clazz)
        try:
            response = session.get(
                f"{MOOC2_BASE_URL}/mooc2-ans/tcm/getteamteacherpower",
                params={
                    "courseid": course["course_id"],
                    "personid": teacher["person_id"],
                },
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"teacher permission request failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(
                str(message or "teacher permission request was not acknowledged")
            )
        teacher_power = payload.get("teacherPower")
        permissions: dict[str, Any] = {}
        normalized_keys: set[str] = set()
        if isinstance(teacher_power, dict):
            for key, value in teacher_power.items():
                if key in {"id", "courseId", "personId"}:
                    continue
                normalized = key.lower()
                if normalized in normalized_keys:
                    continue
                permissions[key] = value
                normalized_keys.add(normalized)
        for key, value in payload.items():
            if (
                key not in {"status", "msg", "role", "teacherPower"}
                and key.lower() not in normalized_keys
            ):
                permissions[key] = value
                normalized_keys.add(key.lower())
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "teacher": teacher,
            "editable": True,
            "role_code": payload.get("role"),
            "permissions": permissions,
            "verification": "read the selected team member's current permission payload via HTTP",
        }

    def update_course_teacher_permissions(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        teacher_query: str,
        changes: dict[str, Any],
    ) -> dict[str, Any]:
        if not changes:
            raise ChaoxingAPIError("at least one teacher permission change is required")
        canonical_by_lower = {name.lower(): name for name in TEACHER_PERMISSION_FIELDS}
        normalized_changes: dict[str, Any] = {}
        for requested_key, requested_value in changes.items():
            canonical = canonical_by_lower.get(str(requested_key).strip().lower())
            if not canonical:
                available = ", ".join(TEACHER_PERMISSION_FIELDS)
                raise ChaoxingAPIError(
                    f"unknown teacher permission: {requested_key}; available: {available}"
                )
            normalized_changes[canonical] = requested_value

        before = self.read_course_teacher_permissions(course, clazz, teacher_query)
        if not before["editable"]:
            raise ChaoxingAPIError("selected teaching-team member permissions are not editable")
        teacher = before["teacher"]
        current = before["permissions"]

        def integer(value: Any, default: int = 0) -> int:
            try:
                return int(value)
            except (TypeError, ValueError):
                return default

        def current_form_value(field: str, permissions: dict[str, Any]) -> int:
            lookup = {str(key).lower(): value for key, value in permissions.items()}
            if field == "clonecourse":
                return 0 if integer(lookup.get("coursereuse"), 1) in {0, 2} else 1
            if field == "mapcourse":
                return 0 if integer(lookup.get("coursereuse"), 1) in {0, 3} else 1
            if field == "editCourseInfoData":
                return integer(lookup.get("editcoursedata"))
            if field == "allowedChapterOpenStatus":
                chapter_status = integer(lookup.get("editchapterstatus"))
                courseset = integer(lookup.get("courseset"))
                return 2 if chapter_status == 2 or (chapter_status == 1 and courseset == 1) else 0
            if field == "importCourseStatus":
                return int(integer(lookup.get("importcourseoption")) != 0)
            return integer(lookup.get(field.lower()))

        form = {field: current_form_value(field, current) for field in TEACHER_PERMISSION_FIELDS}

        def requested_form_value(field: str, value: Any) -> int:
            if isinstance(value, bool):
                if field in {"clonecourse", "mapcourse"}:
                    return 0 if value else 1
                if field == "allowedChapterOpenStatus":
                    return 2 if value else 0
                return int(value)
            try:
                raw = int(value)
            except (TypeError, ValueError) as exc:
                raise ChaoxingAPIError(
                    f"teacher permission {field} must be a boolean or integer"
                ) from exc
            if raw < -1 or raw > 3:
                raise ChaoxingAPIError(
                    f"teacher permission {field} raw value must be between -1 and 3"
                )
            return raw

        expected: dict[str, int] = {}
        for field, value in normalized_changes.items():
            expected[field] = requested_form_value(field, value)
            form[field] = expected[field]
        session = self._session()
        referer = self._management_referer(session, course, clazz)
        try:
            response = session.post(
                f"{MOOC2_BASE_URL}/mooc2-ans/tcm/setteacherpower",
                data={
                    "courseId": course["course_id"],
                    "cpi": course["cpi"],
                    "assistantIds": teacher["person_id"],
                    **form,
                },
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"teacher permission update failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "teacher permission update was not acknowledged"))
        after = self.read_course_teacher_permissions(course, clazz, teacher["person_id"])
        mismatches = {
            field: {
                "expected": value,
                "actual": current_form_value(field, after["permissions"]),
            }
            for field, value in expected.items()
            if current_form_value(field, after["permissions"]) != value
        }
        if mismatches:
            raise ChaoxingAPIError(
                f"teacher permission update was acknowledged but did not persist: {mismatches}"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "teacher": teacher,
            "changes": expected,
            "permissions": after["permissions"],
            "server_message": str(payload.get("msg") or ""),
            "verification": "every requested permission matches a fresh HTTP permission read",
        }

    def read_grade_weights(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> dict[str, Any]:
        session = self._session()
        context = self._course_context(session, course, clazz)
        endpoint = f"{MOOC2_BASE_URL}/mooc2-ans/tcm/scoreweightdata"
        custom_endpoint = f"{MOOC2_BASE_URL}/mooc2-ans/tcm/custom-weight/list"
        common_params = {
            "courseId": course["course_id"],
            "clazzId": clazz["clazz_id"],
        }
        try:
            response = session.get(
                endpoint,
                params={**common_params, "cpi": course["cpi"]},
                timeout=self.timeout,
                allow_redirects=True,
                headers={"Referer": str(context["final_url"])},
            )
            response.raise_for_status()
            custom_response = session.get(
                custom_endpoint,
                params=common_params,
                timeout=self.timeout,
                allow_redirects=True,
                headers={"Referer": response.url},
            )
            custom_response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"grade-weight request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError(f"grade-weight request was redirected to login: {response.url}")
        html = self._decode(response)
        if not _form_fragment(html, "weightForm"):
            raise ChaoxingAPIError("grade-weight response exposed no classic weight form")
        try:
            custom_payload = json.loads(self._decode(custom_response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("custom grade-weight response was not JSON") from exc
        if not isinstance(custom_payload, dict):
            raise ChaoxingAPIError("custom grade-weight response had an invalid shape")
        if custom_payload.get("status") is False:
            raise ChaoxingAPIError(
                str(custom_payload.get("msg") or "custom grade-weight request failed")
            )
        configuration = parse_grade_weight_configuration(html, custom_payload)
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            **configuration,
            "verification": (
                "parsed active grade-weight mode, component weights, settings, and custom "
                "hierarchy from authenticated HTTP responses"
            ),
        }

    def _open_statistics_entry(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        entry_path: str,
    ) -> dict[str, Any]:
        session = self._session()
        context = self._course_context(session, course, clazz)
        statistics_module = resolve_module(context["modules"], "tj")
        statistics_url = self._module_url(context, statistics_module, course, clazz)
        try:
            statistics_response = session.get(
                statistics_url,
                timeout=self.timeout,
                allow_redirects=True,
                headers={"Referer": str(context["final_url"])},
            )
            statistics_response.raise_for_status()
            navigation_response = session.get(
                f"{STAT2_BASE_URL}/stat2/stat-nav/teach",
                params={
                    "courseid": course["course_id"],
                    "clazzid": clazz["clazz_id"],
                    "cpi": course["cpi"],
                    "enc": "",
                    "ut": "t",
                    "sv": "3",
                    "perspectiveType": "0",
                },
                timeout=self.timeout,
                allow_redirects=True,
                headers={
                    "Referer": statistics_response.url,
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            navigation_response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"statistics navigation request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in statistics_response.url.lower():
            raise ChaoxingAPIError(
                f"statistics request was redirected to login: {statistics_response.url}"
            )
        try:
            navigation_payload = json.loads(self._decode(navigation_response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("statistics navigation response was not JSON") from exc
        if not isinstance(navigation_payload, dict):
            raise ChaoxingAPIError("statistics navigation response had an invalid shape")
        navigation = parse_statistics_navigation(navigation_payload)
        entry = next(
            (
                entry
                for entry in navigation
                if urlparse(str(entry["url"])).path.rstrip("/") == entry_path.rstrip("/")
            ),
            None,
        )
        if entry is None:
            raise ChaoxingAPIError(f"statistics navigation exposed no {entry_path} entry")

        entry_url = str(entry["url"])
        parsed_entry_url = urlparse(entry_url)
        if (
            parsed_entry_url.scheme != "https"
            or parsed_entry_url.netloc != urlparse(STAT2_BASE_URL).netloc
        ):
            raise ChaoxingAPIError("statistics navigation returned an unexpected entry origin")
        entry_origin = f"{parsed_entry_url.scheme}://{parsed_entry_url.netloc}"
        common_params = {
            "courseid": course["course_id"],
            "clazzid": clazz["clazz_id"],
            "cpi": course["cpi"],
            "ut": "t",
        }
        try:
            entry_response = session.get(
                entry_url,
                timeout=self.timeout,
                allow_redirects=True,
                headers={"Referer": statistics_response.url},
            )
            entry_response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"statistics entry request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in entry_response.url.lower():
            raise ChaoxingAPIError(
                f"statistics entry was redirected to login: {entry_response.url}"
            )
        return {
            "session": session,
            "entry_origin": entry_origin,
            "entry_url": entry_response.url,
            "common_params": common_params,
            "ajax_headers": {
                "Referer": entry_response.url,
                "X-Requested-With": "XMLHttpRequest",
            },
        }

    def _open_score_statistics(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> dict[str, Any]:
        statistics = self._open_statistics_entry(course, clazz, "/score-data/index")
        session = statistics["session"]
        score_origin = statistics["entry_origin"]
        common_params = statistics["common_params"]
        ajax_headers = statistics["ajax_headers"]
        try:
            initialization_response = session.get(
                f"{score_origin}/score-data/initTable",
                params=common_params,
                timeout=self.timeout,
                headers=ajax_headers,
            )
            initialization_response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"grade overview request failed: {exc}") from exc
        try:
            initialization = json.loads(self._decode(initialization_response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("grade initialization response was not JSON") from exc
        if not isinstance(initialization, dict) or initialization.get("status") is not True:
            raise ChaoxingAPIError("grade initialization response had an invalid shape")
        return {
            **statistics,
            "score_origin": score_origin,
            "initialization": initialization,
        }

    def read_grade_visibility(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> dict[str, Any]:
        statistics = self._open_statistics_entry(course, clazz, "/score-data/index")
        try:
            response = statistics["session"].post(
                f"{statistics['entry_origin']}/overall-score/getClazz",
                data={
                    "classId": clazz["clazz_id"],
                    "courseId": course["course_id"],
                    "cpi": course["cpi"],
                    "ut": "t",
                },
                timeout=self.timeout,
                headers=statistics["ajax_headers"],
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"grade-visibility request failed: {exc}") from exc
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("grade-visibility response was not JSON") from exc
        if not isinstance(payload, dict):
            raise ChaoxingAPIError("grade-visibility response had an invalid shape")
        settings = parse_grade_visibility_payload(payload)
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "context_clazz_id": clazz["clazz_id"],
            "context_clazz_name": clazz["clazz_name"],
            **settings,
            "verification": (
                f"parsed grade visibility for {settings['class_count']} classes from "
                "authenticated HTTP"
            ),
        }

    def list_course_grades(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        search: str = "",
        raw_scores: bool = False,
        sort: str = "loginName",
        descending: bool = False,
    ) -> dict[str, Any]:
        score_context = self._open_score_statistics(course, clazz)
        session = score_context["session"]
        score_origin = score_context["score_origin"]
        common_params = score_context["common_params"]
        ajax_headers = score_context["ajax_headers"]
        initialization = score_context["initialization"]
        try:
            summary_response = session.post(
                f"{score_origin}/teach-data/score",
                data=common_params,
                timeout=self.timeout,
                headers=ajax_headers,
            )
            summary_response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"grade summary request failed: {exc}") from exc
        try:
            summary_payload = json.loads(self._decode(summary_response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("grade summary response was not JSON") from exc
        if not isinstance(summary_payload, dict):
            raise ChaoxingAPIError("grade summary response had an invalid shape")

        components = grade_component_schema(initialization)
        students: list[dict[str, Any]] = []
        pages_fetched = 0
        page_no = 1
        server_total = 0
        while True:
            try:
                response = session.get(
                    f"{score_origin}/score-data/scoreList",
                    params={
                        **common_params,
                        "pageNo": page_no,
                        "pageSize": 100,
                        "sw": search,
                        "order": sort,
                        "sortType": 1 if descending else 0,
                        "groupId": -1,
                        "planId": -1,
                        "withoutWeight": 1 if raw_scores else 0,
                    },
                    timeout=self.timeout,
                    headers=ajax_headers,
                )
                response.raise_for_status()
            except requests.RequestException as exc:
                raise ChaoxingAPIError(f"grade-list request failed: {exc}") from exc
            try:
                payload = json.loads(self._decode(response))
            except json.JSONDecodeError as exc:
                raise ChaoxingAPIError("grade-list response was not JSON") from exc
            if not isinstance(payload, dict):
                raise ChaoxingAPIError("grade-list response had an invalid shape")
            page_students, page_info = parse_grade_score_payload(
                payload,
                components,
                raw_scores=raw_scores,
            )
            students.extend(page_students)
            pages_fetched += 1
            server_total = page_info["total_count"]
            if page_info["page"] >= page_info["total_pages"]:
                break
            page_no = page_info["page"] + 1
            if pages_fetched >= 1000:
                raise ChaoxingAPIError("grade-list pagination exceeded the safety limit")

        weight = initialization.get("weight")
        if not isinstance(weight, dict):
            weight = {}
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "search": search,
            "score_view": "raw" if raw_scores else "weighted",
            "score_value_meaning": (
                "Each component is the server-reported raw score; total_score is omitted."
                if raw_scores
                else "Each component is its weighted contribution; total_score is the final grade."
            ),
            "scores_visible_to_students": bool(initialization.get("visibleScore")),
            "grade_record_archived": initialization.get("isFiled") == 1,
            "weight_type": _number_value(weight.get("weightType")),
            "components": components,
            "weighted_summary": parse_grade_summary_payload(summary_payload),
            "server_total": server_total,
            "count": len(students),
            "pages_fetched": pages_fetched,
            "students": students,
            "verification": (
                f"parsed {len(students)} student grade records across {pages_fetched} "
                "authenticated HTTP page(s)"
            ),
        }

    def set_grade_visibility(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        visible_classes: list[str],
        *,
        scheduled_open: bool = False,
        open_at: str = "",
        students_can_view_rank: bool = False,
        students_can_view_class_average: bool = False,
    ) -> dict[str, Any]:
        open_at = open_at.strip()
        if scheduled_open and not open_at:
            raise ChaoxingAPIError("open_at is required when scheduled_open is true")
        before = self.read_grade_visibility(course, clazz)
        selected: list[dict[str, Any]] = []
        for selector in visible_classes:
            normalized = str(selector).strip().lower()
            exact = [
                item
                for item in before["classes"]
                if normalized
                in {
                    str(item["clazz_id"]).lower(),
                    str(item["clazz_name"]).strip().lower(),
                }
            ]
            if len(exact) == 1:
                item = exact[0]
            else:
                partial = [
                    item
                    for item in before["classes"]
                    if normalized in str(item["clazz_name"]).strip().lower()
                ]
                if len(partial) != 1:
                    raise ChaoxingAPIError(f"grade-visibility class is ambiguous: {selector}")
                item = partial[0]
            if item["clazz_id"] not in {entry["clazz_id"] for entry in selected}:
                selected.append(item)
        selected_ids = [item["clazz_id"] for item in selected]
        statistics = self._open_statistics_entry(course, clazz, "/score-data/index")
        try:
            response = statistics["session"].post(
                f"{statistics['entry_origin']}/overall-score/updateViewScore",
                data={
                    "clazzIds": ",".join(selected_ids) + ("," if selected_ids else ""),
                    "classId": clazz["clazz_id"],
                    "courseId": course["course_id"],
                    "cpi": course["cpi"],
                    "ut": "t",
                    "setType": 1,
                    "openCheck": str(scheduled_open).lower(),
                    "openScoreTime": open_at if scheduled_open else "",
                    "viewRankCheck": str(students_can_view_rank).lower(),
                    "viewClazzAvgScoreCheck": str(students_can_view_class_average).lower(),
                },
                timeout=self.timeout,
                headers=statistics["ajax_headers"],
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"grade-visibility update failed: {exc}") from exc
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("grade-visibility update response was not JSON") from exc
        if not isinstance(payload, dict) or payload.get("status") is not True:
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "grade-visibility update was not acknowledged"))
        after = self.read_grade_visibility(course, clazz)
        after_visible_ids = {
            item["clazz_id"] for item in after["classes"] if item["scores_visible"]
        }
        expected_visible_ids = set(selected_ids)
        settings_match = (
            after_visible_ids == expected_visible_ids
            and after["scheduled_open"] is scheduled_open
            and after["students_can_view_rank"] is students_can_view_rank
            and after["students_can_view_class_average"] is students_can_view_class_average
            and (not scheduled_open or after["open_at"] == open_at)
        )
        if not settings_match:
            raise ChaoxingAPIError(
                "server acknowledged grade visibility, but refreshed settings do not match"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "context_clazz_id": clazz["clazz_id"],
            "context_clazz_name": clazz["clazz_name"],
            "before": {
                "visible_class_ids": [
                    item["clazz_id"] for item in before["classes"] if item["scores_visible"]
                ],
                "scheduled_open": before["scheduled_open"],
                "open_at": before["open_at"],
                "students_can_view_rank": before["students_can_view_rank"],
                "students_can_view_class_average": before["students_can_view_class_average"],
            },
            "after": {
                "visible_class_ids": selected_ids,
                "visible_class_names": [item["clazz_name"] for item in selected],
                "scheduled_open": scheduled_open,
                "open_at": open_at if scheduled_open else "",
                "students_can_view_rank": students_can_view_rank,
                "students_can_view_class_average": students_can_view_class_average,
            },
            "verification": "refreshed grade-visibility settings exactly match the request",
        }

    def set_course_grade_override(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        student: str,
        score: int | float | None,
    ) -> dict[str, Any]:
        if score is not None and not 0 <= score <= 100:
            raise ChaoxingAPIError("grade override must be between 0 and 100, or null to clear")
        before_result = self.list_course_grades(course, clazz, search=student)
        selected_before = resolve_class_student(before_result["students"], student)
        request_score: int | float = -1 if score is None else score
        statistics = self._open_statistics_entry(course, clazz, "/score-data/index")
        try:
            response = statistics["session"].get(
                f"{statistics['entry_origin']}/score-data/fixScore",
                params={
                    "personId": selected_before["person_id"],
                    "score": request_score,
                    "clazzid": clazz["clazz_id"],
                },
                timeout=self.timeout,
                headers=statistics["ajax_headers"],
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"grade override request failed: {exc}") from exc
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("grade override response was not JSON") from exc
        if not isinstance(payload, dict) or payload.get("status") is not True:
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "grade override was not acknowledged"))
        after_result = self.list_course_grades(
            course,
            clazz,
            search=selected_before["student_no"],
        )
        selected_after = resolve_class_student(
            after_result["students"], selected_before["student_no"]
        )
        if selected_after["custom_score"] != score:
            raise ChaoxingAPIError(
                "server acknowledged grade override, but refreshed custom score does not match"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "student": {
                "person_id": selected_after["person_id"],
                "student_no": selected_after["student_no"],
                "student_name": selected_after["student_name"],
            },
            "before": {
                "total_score": selected_before["total_score"],
                "custom_score": selected_before["custom_score"],
            },
            "after": {
                "total_score": selected_after["total_score"],
                "custom_score": selected_after["custom_score"],
            },
            "verification": "refreshed custom score exactly matches the requested override",
        }

    def list_course_learning_progress(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        search: str = "",
        sort: str = "loginName",
        descending: bool = False,
    ) -> dict[str, Any]:
        score_context = self._open_score_statistics(course, clazz)
        session = score_context["session"]
        score_origin = score_context["score_origin"]
        common_params = score_context["common_params"]
        ajax_headers = score_context["ajax_headers"]
        initialization = score_context["initialization"]
        weight = initialization.get("weight")
        if not isinstance(weight, dict):
            weight = {}
        weight_type = _number_value(weight.get("weightType"))
        endpoint = (
            "/score-data/thirdStudySchedule" if weight_type == 2 else "/score-data/studySchedule"
        )
        custom_components = grade_component_schema(initialization) if weight_type == 2 else []

        students: list[dict[str, Any]] = []
        pages_fetched = 0
        page_no = 1
        server_total = 0
        while True:
            try:
                response = session.get(
                    score_origin + endpoint,
                    params={
                        **common_params,
                        "pageNo": page_no,
                        "pageSize": 100,
                        "sw": search,
                        "order": sort,
                        "sortType": 1 if descending else 0,
                        "groupId": -1,
                        "planId": -1,
                    },
                    timeout=self.timeout,
                    headers=ajax_headers,
                )
                response.raise_for_status()
            except requests.RequestException as exc:
                raise ChaoxingAPIError(f"learning-progress request failed: {exc}") from exc
            try:
                payload = json.loads(self._decode(response))
            except json.JSONDecodeError as exc:
                raise ChaoxingAPIError("learning-progress response was not JSON") from exc
            if not isinstance(payload, dict):
                raise ChaoxingAPIError("learning-progress response had an invalid shape")
            page_students, page_info = parse_learning_progress_payload(
                payload,
                custom_components,
            )
            students.extend(page_students)
            pages_fetched += 1
            server_total = page_info["total_count"]
            if page_info["page"] >= page_info["total_pages"]:
                break
            page_no = page_info["page"] + 1
            if pages_fetched >= 1000:
                raise ChaoxingAPIError("learning-progress pagination exceeded the safety limit")

        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "search": search,
            "weight_type": weight_type,
            "server_total": server_total,
            "count": len(students),
            "pages_fetched": pages_fetched,
            "students": students,
            "verification": (
                f"parsed {len(students)} student learning-progress records across "
                f"{pages_fetched} authenticated HTTP page(s)"
            ),
        }

    def list_study_monitor(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        search: str = "",
        only_abnormal: bool = False,
        anomaly_type: int = 0,
    ) -> dict[str, Any]:
        if anomaly_type not in {0, 1, 2, 4}:
            raise ChaoxingAPIError("anomaly_type must be 0 all, 1 video, 2 homework, or 4 exam")
        statistics = self._open_statistics_entry(course, clazz, "/study-monitor/v2/index")
        session = statistics["session"]
        origin = statistics["entry_origin"]
        common_params = statistics["common_params"]
        ajax_headers = statistics["ajax_headers"]
        students: list[dict[str, Any]] = []
        pages_fetched = 0
        page_no = 1
        server_total = 0
        appeal_count = 0
        while True:
            try:
                response = session.get(
                    f"{origin}/study-monitor/v2/studyList",
                    params={
                        **common_params,
                        "pageNo": page_no,
                        "pageSize": 100,
                        "q": search,
                        "studyStatus": 1 if only_abnormal else 0,
                        "type": anomaly_type,
                    },
                    timeout=self.timeout,
                    headers=ajax_headers,
                )
                response.raise_for_status()
            except requests.RequestException as exc:
                raise ChaoxingAPIError(f"study-monitor request failed: {exc}") from exc
            try:
                payload = json.loads(self._decode(response))
            except json.JSONDecodeError as exc:
                raise ChaoxingAPIError("study-monitor response was not JSON") from exc
            if not isinstance(payload, dict):
                raise ChaoxingAPIError("study-monitor response had an invalid shape")
            page_students, page_info, page_appeal_count = parse_study_monitor_payload(payload)
            students.extend(page_students)
            pages_fetched += 1
            server_total = page_info["total_count"]
            appeal_count = page_appeal_count
            if page_info["page"] >= page_info["total_pages"]:
                break
            page_no = page_info["page"] + 1
            if pages_fetched >= 1000:
                raise ChaoxingAPIError("study-monitor pagination exceeded the safety limit")
        anomaly_labels = {0: "all", 1: "video", 2: "homework", 4: "exam"}
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "search": search,
            "only_abnormal": only_abnormal,
            "anomaly_type": anomaly_labels[anomaly_type],
            "appeal_count": appeal_count,
            "server_total": server_total,
            "count": len(students),
            "pages_fetched": pages_fetched,
            "students": students,
            "verification": (
                f"parsed {len(students)} study-monitor records across {pages_fetched} "
                "authenticated HTTP page(s)"
            ),
        }

    def send_study_monitor_reminder(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        student: str,
        title: str,
        content: str,
    ) -> dict[str, Any]:
        title = title.strip()
        content = content.strip()
        if not title or not content:
            raise ChaoxingAPIError("reminder title and content are required")
        monitor = self.list_study_monitor(
            course,
            clazz,
            search=student,
            only_abnormal=True,
        )
        selected = resolve_study_monitor_student(monitor["students"], student)
        statistics = self._open_statistics_entry(course, clazz, "/study-monitor/v2/index")
        try:
            response = statistics["session"].get(
                f"{statistics['entry_origin']}/study-monitor/v2/remind",
                params={
                    **statistics["common_params"],
                    "personId": selected["person_id"],
                    "title": title,
                    "content": content,
                },
                timeout=self.timeout,
                headers=statistics["ajax_headers"],
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"study-monitor reminder request failed: {exc}") from exc
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("study-monitor reminder response was not JSON") from exc
        if not isinstance(payload, dict):
            raise ChaoxingAPIError("study-monitor reminder response had an invalid shape")
        acknowledged = (
            payload.get("status") is True or payload.get("result") == 1 or payload.get("code") == 0
        )
        if not acknowledged:
            raise ChaoxingAPIError(str(payload.get("msg") or "reminder was not acknowledged"))
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "student": selected,
            "title": title,
            "content": content,
            "server_acknowledged": True,
            "server_message": str(payload.get("msg") or ""),
            "verification": "Chaoxing explicitly acknowledged the abnormal-study reminder",
        }

    def clear_study_monitor_anomaly(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        student: str,
    ) -> dict[str, Any]:
        monitor = self.list_study_monitor(
            course,
            clazz,
            search=student,
            only_abnormal=True,
        )
        selected = resolve_study_monitor_student(monitor["students"], student)
        if not selected["can_clear_anomaly"]:
            raise ChaoxingAPIError("the selected anomaly cannot currently be cleared")
        statistics = self._open_statistics_entry(course, clazz, "/study-monitor/v2/index")
        try:
            response = statistics["session"].get(
                f"{statistics['entry_origin']}/study-monitor/v2/del",
                params={
                    **statistics["common_params"],
                    "personId": selected["person_id"],
                },
                timeout=self.timeout,
                headers=statistics["ajax_headers"],
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"clear study-monitor anomaly request failed: {exc}") from exc
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("clear study-monitor anomaly response was not JSON") from exc
        if not isinstance(payload, dict) or payload.get("status") is not True:
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "anomaly clear was not acknowledged"))
        after = self.list_study_monitor(
            course,
            clazz,
            search=selected["student_no"],
            only_abnormal=True,
        )
        still_abnormal = any(
            record["person_id"] == selected["person_id"] for record in after["students"]
        )
        if still_abnormal:
            raise ChaoxingAPIError(
                "server acknowledged the clear, but the anomaly is still visible"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "student": selected,
            "cleared": True,
            "verification": "student is absent from the refreshed abnormal-study monitor",
        }

    def _course_context(
        self,
        session: requests.Session,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> dict[str, Any]:
        entry_url = build_teacher_entry_url(course, clazz)
        try:
            response = session.get(entry_url, timeout=self.timeout, allow_redirects=True)
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"teacher course request failed: {exc}") from exc
        html = self._decode(response)
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError(f"course request was redirected to login: {response.url}")
        modules = parse_teacher_nav_items(html)
        if not modules:
            raise ChaoxingAPIError("teacher course response exposed no module entries")
        return {
            "entry_url": entry_url,
            "final_url": response.url,
            "hidden": parse_hidden_inputs(html),
            "modules": modules,
            "http_status": response.status_code,
        }

    @staticmethod
    def _module_url(
        context: dict[str, Any],
        item: dict[str, str],
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> str:
        hidden = context.get("hidden") if isinstance(context.get("hidden"), dict) else {}
        course_id = str(hidden.get("courseid") or course.get("course_id") or "")
        clazz_id = str(hidden.get("clazzid") or clazz.get("clazz_id") or "")
        params = {
            "courseid": course_id,
            "clazzid": clazz_id,
            "courseId": course_id,
            "classId": clazz_id,
            "clazzId": clazz_id,
            "cpi": str(hidden.get("cpi") or course.get("cpi") or ""),
            "enc": str(hidden.get("enc") or ""),
            "openc": str(hidden.get("openc") or ""),
            "t": str(hidden.get("t") or ""),
            "bbsid": str(hidden.get("bbsid") or ""),
            "ut": "t",
        }
        if item.get("module") == "zy":
            params["selectClassid"] = clazz_id
        base_url = urljoin(str(context["final_url"]), item["data_url"])
        if item.get("module") == "knowledge_hub":
            # This module URL is already signed. Re-appending the generic
            # course parameters changes the signed request and makes it fail.
            return base_url
        if item.get("module") == "tj":
            return append_query_params(
                base_url,
                {
                    "courseid": course_id,
                    "clazzid": clazz_id,
                    "cpi": str(hidden.get("cpi") or course.get("cpi") or ""),
                    "ut": "t",
                },
            )
        return append_query_params(base_url, params)

    def discover_course_modules(
        self, course: dict[str, Any], clazz: dict[str, Any]
    ) -> dict[str, Any]:
        context = self._course_context(self._session(), course, clazz)
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "entry_url": context["entry_url"],
            "final_url": context["final_url"],
            "module_count": len(context["modules"]),
            "modules": context["modules"],
            "verification": "authenticated course HTML parsed through HTTP",
        }

    def inspect_course_module(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        module_query: str,
    ) -> dict[str, Any]:
        session = self._session()
        context = self._course_context(session, course, clazz)
        item = resolve_module(context["modules"], module_query)
        module_url = self._module_url(context, item, course, clazz)
        try:
            response = session.get(
                module_url,
                timeout=self.timeout,
                allow_redirects=True,
                headers={"Referer": str(context["final_url"])},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"course module request failed: {exc}") from exc
        html = self._decode(response)
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError(f"module request was redirected to login: {response.url}")
        title_match = re.search(r"<title[^>]*>(.*?)</title>", html, flags=re.I | re.S)
        title = html_text(title_match.group(1)) if title_match else ""
        text_excerpt = html_text(html, limit=20_000)
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "module": item,
            "request_url": module_url,
            "final_url": response.url,
            "http_status": response.status_code,
            "content_type": response.headers.get("Content-Type", ""),
            "title": title,
            "text_excerpt": text_excerpt,
            "verification": "authenticated non-login module response retrieved through HTTP",
        }

    @staticmethod
    def _knowledge_hub_js_values(html: str) -> dict[str, str]:
        """Read the narrow set of bootstrap variables used by the knowledge-hub SPA."""

        names = (
            "unitId",
            "courseRobotId",
            "robotId",
            "rbtoken",
            "courseId",
            "clazzId",
            "cpi",
            "courseName",
            "type",
            "isLcSimulateLogin",
        )
        values: dict[str, str] = {}
        hidden = parse_hidden_inputs(html)
        for name in names:
            match = re.search(
                rf"(?:\b(?:var|let|const)\s+|\bwindow\.){re.escape(name)}\s*=\s*"
                r"(?P<value>[^;\r\n]+)",
                html,
                flags=re.IGNORECASE,
            )
            raw = match.group("value").strip() if match else str(hidden.get(name) or "").strip()
            if len(raw) >= 2 and raw[0] in {"'", '"'} and raw[-1] == raw[0]:
                quote_char = raw[0]
                raw = raw[1:-1]
                if quote_char == '"':
                    try:
                        raw = str(json.loads(f'"{raw}"'))
                    except json.JSONDecodeError:
                        raw = raw.replace(r"\"", '"').replace(r"\\", "\\")
                else:
                    raw = raw.replace(r"\'", "'").replace(r"\\", "\\")
            if raw:
                values[name] = raw
        return values

    @staticmethod
    def _knowledge_hub_bool(value: Any) -> bool:
        if isinstance(value, bool):
            return value
        if isinstance(value, (int, float)):
            return value != 0
        return str(value or "").strip().lower() in {"1", "true", "yes", "on", "enabled"}

    @staticmethod
    def _knowledge_hub_module(module: str) -> str:
        normalized = str(module or "NORMAL_BASE").strip().upper()
        if normalized not in KNOWLEDGE_HUB_MODULES:
            choices = ", ".join(sorted(KNOWLEDGE_HUB_MODULES))
            raise ChaoxingAPIError(f"knowledge-hub module must be one of: {choices}")
        return normalized

    @staticmethod
    def _knowledge_hub_public_value(value: Any) -> Any:
        secret_keys = {
            "rbtoken",
            "token",
            "_token",
            "uploadurl",
            "clientip",
        }
        if isinstance(value, dict):
            return {
                str(key): ChaoxingAPI._knowledge_hub_public_value(item)
                for key, item in value.items()
                if str(key).replace("_", "").lower() not in secret_keys
            }
        if isinstance(value, list):
            return [ChaoxingAPI._knowledge_hub_public_value(item) for item in value]
        return value

    def _knowledge_hub_context(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> dict[str, Any]:
        session = self._session()
        course_context = self._course_context(session, course, clazz)
        module = resolve_module(course_context["modules"], "knowledge_hub")
        request_url = self._module_url(course_context, module, course, clazz)
        try:
            response = session.get(
                request_url,
                timeout=self.timeout,
                allow_redirects=True,
                headers={"Referer": str(course_context["final_url"])},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(
                f"knowledge-hub bootstrap failed ({type(exc).__name__})"
            ) from exc
        if "passport2.chaoxing.com/login" in str(response.url).lower():
            raise ChaoxingAPIError("knowledge-hub bootstrap was redirected to login")
        parsed_url = urlparse(str(response.url))
        hostname = str(parsed_url.hostname or "").lower()
        if parsed_url.scheme not in {"http", "https"} or not (
            hostname == "chaoxing.com" or hostname.endswith(".chaoxing.com")
        ):
            raise ChaoxingAPIError("knowledge-hub bootstrap returned an unexpected host")
        values = self._knowledge_hub_js_values(self._decode(response))
        robot_id = str(values.get("courseRobotId") or values.get("robotId") or "").strip()
        unit_id = str(values.get("unitId") or "").strip()
        rbtoken = str(values.get("rbtoken") or "").strip()
        if not robot_id or not unit_id or not rbtoken:
            raise ChaoxingAPIError("knowledge-hub bootstrap omitted required request context")
        simulate_login = str(values.get("isLcSimulateLogin") or values.get("type") or "0").strip()
        return {
            "session": session,
            "origin": f"{parsed_url.scheme}://{parsed_url.netloc}",
            "root_url": str(response.url),
            "headers": {
                "rbtoken": rbtoken,
                "robotId": robot_id,
                "unitId": unit_id,
                "isLcSimulateLogin": simulate_login,
            },
            "course": course,
            "clazz": clazz,
        }

    def _knowledge_hub_response(
        self,
        context: dict[str, Any],
        path: str,
        operation: str,
        *,
        method: str = "GET",
        params: dict[str, Any] | None = None,
        json_body: Any = None,
        data: dict[str, Any] | None = None,
        stream: bool = False,
    ) -> requests.Response:
        url = urljoin(str(context["origin"]) + "/", path.lstrip("/"))
        headers = {
            **dict(context["headers"]),
            "Referer": str(context["root_url"]),
            "X-Requested-With": "XMLHttpRequest",
        }
        try:
            response = context["session"].request(
                method.upper(),
                url,
                params=params,
                json=json_body,
                data=data,
                timeout=self.timeout,
                headers=headers,
                allow_redirects=True,
                stream=stream,
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"{operation} failed ({type(exc).__name__})") from exc
        if "passport2.chaoxing.com/login" in str(response.url).lower():
            raise ChaoxingAPIError(f"{operation} was redirected to login")
        return response

    def _knowledge_hub_json_request(
        self,
        context: dict[str, Any],
        path: str,
        operation: str,
        *,
        method: str = "GET",
        params: dict[str, Any] | None = None,
        json_body: Any = None,
        data: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        response = self._knowledge_hub_response(
            context,
            path,
            operation,
            method=method,
            params=params,
            json_body=json_body,
            data=data,
        )
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError(f"{operation} returned invalid JSON") from exc
        if not isinstance(payload, dict):
            raise ChaoxingAPIError(f"{operation} returned an invalid payload")
        if payload.get("success") is False or payload.get("status") is False:
            message = payload.get("msg") or payload.get("message") or f"{operation} was rejected"
            safe_message = str(message)
            for secret in dict(context.get("headers") or {}).values():
                if secret:
                    safe_message = safe_message.replace(str(secret), "[redacted]")
            raise ChaoxingAPIError(safe_message)
        if payload.get("code") is not None:
            try:
                code = int(str(payload["code"]).strip())
            except (TypeError, ValueError):
                code = -1
            if code not in {0, 1} and not 200 <= code < 300:
                message = (
                    payload.get("msg") or payload.get("message") or f"{operation} was rejected"
                )
                safe_message = str(message)
                for secret in dict(context.get("headers") or {}).values():
                    if secret:
                        safe_message = safe_message.replace(str(secret), "[redacted]")
                raise ChaoxingAPIError(safe_message)
        return payload

    @staticmethod
    def _knowledge_hub_payload_data(payload: dict[str, Any]) -> Any:
        return payload.get("data") if "data" in payload else payload

    @classmethod
    def _normalize_knowledge_hub_base(
        cls,
        raw: dict[str, Any],
        index: int,
    ) -> dict[str, Any]:
        category = cls._ai_workbench_integer(raw.get("category"), 0)
        state = cls._ai_workbench_integer(raw.get("state"), -1)
        permission_data = raw.get("permissions")
        if permission_data is None:
            permission_data = raw.get("permission")
        if permission_data is None:
            permission_data = raw.get("_permissionList")
        enabled_value = raw.get("enable")
        if enabled_value is None:
            enabled_value = raw.get("enableStatus")
        rule = raw.get("rule")
        if isinstance(rule, str):
            try:
                parsed_rule = json.loads(rule)
                rule = parsed_rule if isinstance(parsed_rule, dict) else {}
            except json.JSONDecodeError:
                rule = {}
        if not isinstance(rule, dict):
            rule = {}
        state_names = {0: "completed", 1: "deleting", 3: "processing"}
        category_names = {
            0: "文档库",
            4: "表格库",
            9: "图谱库",
            10: "图片库",
        }
        return {
            "index": index,
            "base_id": str(raw.get("baseId") or raw.get("id") or ""),
            "name": str(raw.get("baseName") or raw.get("name") or ""),
            "description": str(raw.get("desc") or raw.get("description") or ""),
            "category": category,
            "category_name": category_names.get(category, "unknown"),
            "state": state,
            "state_name": state_names.get(state, "unknown"),
            "enabled": cls._knowledge_hub_bool(enabled_value),
            "default_base": cls._knowledge_hub_bool(raw.get("defaultBase") or raw.get("isDefault")),
            "shared": cls._knowledge_hub_bool(raw.get("shared")),
            "priority": cls._ai_workbench_integer(raw.get("priority"), 0),
            "cover": str(raw.get("cover") or ""),
            "resource_size": cls._ai_workbench_integer(
                raw.get("resourceSize") or raw.get("fileNum"), 0
            ),
            "segment_count": cls._ai_workbench_integer(raw.get("segmentNum"), 0),
            "segment_character_count": str(raw.get("segmentCharNum") or "0"),
            "creator_name": str(raw.get("creatorName") or raw.get("userName") or ""),
            "created_at": str(raw.get("createTime") or raw.get("createdAt") or ""),
            "updated_at": str(
                raw.get("updateTime") or raw.get("updatedAt") or raw.get("lastUploadTime") or ""
            ),
            "split_rule": cls._knowledge_hub_public_value(rule),
            "permissions": cls._knowledge_hub_public_value(permission_data or {}),
        }

    @staticmethod
    def _knowledge_hub_page(payload: dict[str, Any]) -> tuple[list[dict[str, Any]], dict[str, Any]]:
        data = ChaoxingAPI._knowledge_hub_payload_data(payload)
        if isinstance(data, list):
            records = [item for item in data if isinstance(item, dict)]
            return records, {"total": len(records), "page": 1, "page_size": len(records)}
        if not isinstance(data, dict):
            return [], {"total": 0, "page": 1, "page_size": 0}
        raw_records = data.get("records")
        if not isinstance(raw_records, list):
            raw_records = data.get("list")
        if not isinstance(raw_records, list):
            raw_records = data.get("items")
        records = [item for item in (raw_records or []) if isinstance(item, dict)]
        page_info = {
            "total": ChaoxingAPI._ai_workbench_integer(
                data.get("total") or data.get("totalCount"), len(records)
            ),
            "page": ChaoxingAPI._ai_workbench_integer(
                data.get("current") or data.get("page") or data.get("pageNum"), 1
            ),
            "page_size": ChaoxingAPI._ai_workbench_integer(
                data.get("size") or data.get("pageSize"), len(records)
            ),
            "total_pages": ChaoxingAPI._ai_workbench_integer(
                data.get("pages") or data.get("totalPages"), 1
            ),
        }
        for key in ("overLimit", "fileLimit"):
            if key in data:
                page_info[key] = data[key]
        return records, page_info

    def _knowledge_hub_bases_from_context(
        self,
        context: dict[str, Any],
        *,
        module: str = "NORMAL_BASE",
        page: int = 1,
        page_size: int = 100,
        category: int = -1,
        state: int = -1,
        creator: str = "",
        search: str = "",
        begin_time: str = "",
        end_time: str = "",
    ) -> tuple[list[dict[str, Any]], dict[str, Any]]:
        if page < 1:
            raise ChaoxingAPIError("knowledge-hub page must be positive")
        if not 1 <= page_size <= 1000:
            raise ChaoxingAPIError("knowledge-hub page_size must be between 1 and 1000")
        normalized_module = self._knowledge_hub_module(module)
        payload = self._knowledge_hub_json_request(
            context,
            f"/v1/manage/multi/knowledge/robot-base/condition/page/query/{page}/{page_size}",
            "knowledge-hub base list",
            params={
                "module": normalized_module,
                "category": category,
                "state": state,
                "userId": creator,
                "baseName": search,
                "beginTime": begin_time,
                "endTime": end_time,
                "courseId": str(context["course"]["course_id"]),
            },
        )
        records, page_info = self._knowledge_hub_page(payload)
        start = (page - 1) * page_size
        bases = [
            self._normalize_knowledge_hub_base(raw, start + index)
            for index, raw in enumerate(records, 1)
        ]
        return bases, page_info

    @staticmethod
    def _resolve_knowledge_hub_base(bases: list[dict[str, Any]], query: str) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("knowledge-hub base name or ID is required")
        exact = [
            item
            for item in bases
            if str(item.get("base_id") or "").lower() == normalized
            or str(item.get("name") or "").strip().lower() == normalized
        ]
        if len(exact) == 1:
            return exact[0]
        if len(exact) > 1:
            options = ", ".join(f"{item['name']} ({item['base_id']})" for item in exact[:10])
            raise ChaoxingAPIError(f"multiple knowledge-hub bases match: {options}")
        partial = [item for item in bases if normalized in str(item.get("name") or "").lower()]
        if len(partial) == 1:
            return partial[0]
        if not partial:
            raise ChaoxingAPIError(f"knowledge-hub base not found: {query}")
        options = ", ".join(f"{item['name']} ({item['base_id']})" for item in partial[:10])
        raise ChaoxingAPIError(f"multiple knowledge-hub bases match: {options}")

    def _knowledge_hub_base_detail_raw(
        self,
        context: dict[str, Any],
        base_id: str,
        *,
        module: str = "NORMAL_BASE",
    ) -> dict[str, Any]:
        payload = self._knowledge_hub_json_request(
            context,
            "/v1/manage/multi/knowledge/robot-base",
            "knowledge-hub base read",
            params={
                "module": self._knowledge_hub_module(module),
                "baseId": base_id,
                "courseId": str(context["course"]["course_id"]),
            },
        )
        data = self._knowledge_hub_payload_data(payload)
        if isinstance(data, dict) and isinstance(data.get("baseInfo"), dict):
            data = data["baseInfo"]
        if not isinstance(data, dict) or not str(data.get("baseId") or data.get("id") or ""):
            raise ChaoxingAPIError("knowledge-hub base read returned no base record")
        return data

    def _knowledge_hub_resolve_from_context(
        self,
        context: dict[str, Any],
        query: str,
        *,
        module: str = "NORMAL_BASE",
    ) -> dict[str, Any]:
        bases, _ = self._knowledge_hub_bases_from_context(context, module=module, page_size=1000)
        return self._resolve_knowledge_hub_base(bases, query)

    def read_knowledge_hub_status(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> dict[str, Any]:
        context = self._knowledge_hub_context(course, clazz)
        status_payload = self._knowledge_hub_json_request(
            context,
            "/v1/manage/multi/knowledge/open/status",
            "knowledge-hub status read",
        )
        dictionary_payload = self._knowledge_hub_json_request(
            context,
            "/v1/manage/multi/knowledge/base/dictionaries",
            "knowledge-hub dictionaries read",
        )
        status_data = self._knowledge_hub_payload_data(status_payload)
        if isinstance(status_data, dict):
            raw_modules = status_data.get("modules") or status_data.get("list") or []
        else:
            raw_modules = status_data if isinstance(status_data, list) else []
        modules = []
        for raw in raw_modules:
            if not isinstance(raw, dict):
                continue
            module_name = str(raw.get("module") or raw.get("moduleName") or raw.get("name") or "")
            modules.append(
                {
                    "module": module_name,
                    "enabled": self._knowledge_hub_bool(raw.get("enable")),
                    "model_segmentation_enabled": self._knowledge_hub_bool(
                        raw.get("enableModelSegment")
                    ),
                }
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "modules": modules,
            "dictionaries": self._knowledge_hub_public_value(
                self._knowledge_hub_payload_data(dictionary_payload)
            ),
            "verification": "knowledge-hub status and dictionaries read through authenticated HTTP",
        }

    def list_knowledge_hub_bases(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        module: str = "NORMAL_BASE",
        page: int = 1,
        page_size: int = 100,
        category: int = -1,
        state: int = -1,
        creator: str = "",
        search: str = "",
        begin_time: str = "",
        end_time: str = "",
    ) -> dict[str, Any]:
        context = self._knowledge_hub_context(course, clazz)
        bases, page_info = self._knowledge_hub_bases_from_context(
            context,
            module=module,
            page=page,
            page_size=page_size,
            category=category,
            state=state,
            creator=creator,
            search=search,
            begin_time=begin_time,
            end_time=end_time,
        )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "module": self._knowledge_hub_module(module),
            "count": len(bases),
            "page": page_info,
            "bases": bases,
            "verification": "knowledge-hub base page read through authenticated HTTP",
        }

    def read_knowledge_hub_base(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        base: str,
        *,
        module: str = "NORMAL_BASE",
    ) -> dict[str, Any]:
        context = self._knowledge_hub_context(course, clazz)
        selected = self._knowledge_hub_resolve_from_context(context, base, module=module)
        raw = self._knowledge_hub_base_detail_raw(context, selected["base_id"], module=module)
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "module": self._knowledge_hub_module(module),
            "base": self._normalize_knowledge_hub_base(raw, selected["index"]),
            "verification": "knowledge-hub base resolved and re-read by stable ID",
        }

    def read_knowledge_hub_statistics(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        module: str = "NORMAL_BASE",
    ) -> dict[str, Any]:
        context = self._knowledge_hub_context(course, clazz)
        normalized_module = self._knowledge_hub_module(module)
        payload = self._knowledge_hub_json_request(
            context,
            "/v1/manage/multi/knowledge/statistic/info",
            "knowledge-hub statistics read",
            params={"module": normalized_module},
        )
        data = self._knowledge_hub_payload_data(payload)
        if not isinstance(data, dict):
            data = {}
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "module": normalized_module,
            "file_count": self._ai_workbench_integer(data.get("fileNum"), 0),
            "segment_character_count": str(data.get("segmentCharNum") or "0"),
            "statistics": self._knowledge_hub_public_value(data),
            "verification": "knowledge-hub statistics read through authenticated HTTP",
        }

    @staticmethod
    def _knowledge_hub_validate_base_fields(name: str, description: str) -> tuple[str, str]:
        normalized_name = str(name or "").strip()
        normalized_description = str(description or "").strip()
        if not normalized_name:
            raise ChaoxingAPIError("knowledge-hub base name is required")
        if len(normalized_name) > 100:
            raise ChaoxingAPIError("knowledge-hub base name must not exceed 100 characters")
        if not normalized_description:
            raise ChaoxingAPIError("knowledge-hub base description is required")
        if len(normalized_description) > 350:
            raise ChaoxingAPIError("knowledge-hub base description must not exceed 350 characters")
        return normalized_name, normalized_description

    @staticmethod
    def _knowledge_hub_rule(raw: Any) -> dict[str, Any]:
        if isinstance(raw, str):
            try:
                raw = json.loads(raw)
            except json.JSONDecodeError:
                raw = None
        if isinstance(raw, dict):
            return dict(raw)
        return {"splitStrategy": 0, "enableOcr": True}

    def create_knowledge_hub_base(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        name: str,
        description: str,
        *,
        category: int = 0,
        cover: str = "",
        split_rule: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        normalized_name, normalized_description = self._knowledge_hub_validate_base_fields(
            name, description
        )
        if category not in KNOWLEDGE_HUB_BASE_CATEGORIES:
            raise ChaoxingAPIError("knowledge-hub category must be 0, 4, 9, or 10")
        context = self._knowledge_hub_context(course, clazz)
        before, _ = self._knowledge_hub_bases_from_context(context, page_size=1000)
        before_ids = {item["base_id"] for item in before}
        selected_cover = str(cover or "").strip()
        if not selected_cover:
            same_category = [
                item["cover"] for item in before if item["category"] == category and item["cover"]
            ]
            any_cover = [item["cover"] for item in before if item["cover"]]
            selected_cover = next(iter(same_category or any_cover), "")
        if not selected_cover:
            raise ChaoxingAPIError(
                "knowledge-hub cover is required because no existing base exposed a reusable cover"
            )
        request_body = {
            "baseName": normalized_name,
            "desc": normalized_description,
            "category": category,
            "cover": selected_cover,
            "rule": self._knowledge_hub_rule(split_rule),
        }
        payload = self._knowledge_hub_json_request(
            context,
            "/v1/manage/multi/knowledge/base/addOrUpdate",
            "knowledge-hub base creation",
            method="POST",
            params={"mode": "ADD"},
            json_body=request_body,
        )
        data = self._knowledge_hub_payload_data(payload)
        created_id = ""
        if isinstance(data, dict):
            created_id = str(data.get("baseId") or data.get("id") or "")
        elif data is not None:
            created_id = str(data)
        after, _ = self._knowledge_hub_bases_from_context(context, page_size=1000)
        candidates = [
            item
            for item in after
            if item["base_id"] not in before_ids
            and item["name"] == normalized_name
            and (not created_id or item["base_id"] == created_id)
        ]
        if len(candidates) != 1:
            raise ChaoxingAPIError(
                "knowledge-hub base creation was acknowledged but one new base "
                "could not be verified"
            )
        raw = self._knowledge_hub_base_detail_raw(context, candidates[0]["base_id"])
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "base": self._normalize_knowledge_hub_base(raw, candidates[0]["index"]),
            "verification": "new knowledge-hub base ID appeared and its detail was re-read",
        }

    def update_knowledge_hub_base(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        base: str,
        *,
        name: str | None = None,
        description: str | None = None,
        cover: str | None = None,
        split_rule: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        if all(value is None for value in (name, description, cover, split_rule)):
            raise ChaoxingAPIError("knowledge-hub base update requires at least one changed field")
        context = self._knowledge_hub_context(course, clazz)
        selected = self._knowledge_hub_resolve_from_context(context, base)
        old_raw = self._knowledge_hub_base_detail_raw(context, selected["base_id"])
        new_name = str(
            name if name is not None else old_raw.get("baseName") or old_raw.get("name") or ""
        )
        new_description = str(
            description
            if description is not None
            else old_raw.get("desc") or old_raw.get("description") or ""
        )
        new_name, new_description = self._knowledge_hub_validate_base_fields(
            new_name, new_description
        )
        old_body = {
            "baseId": selected["base_id"],
            "baseName": str(old_raw.get("baseName") or old_raw.get("name") or ""),
            "desc": str(old_raw.get("desc") or old_raw.get("description") or ""),
            "category": self._ai_workbench_integer(old_raw.get("category"), 0),
            "cover": str(old_raw.get("cover") or ""),
            "rule": self._knowledge_hub_rule(old_raw.get("rule")),
        }
        request_body = {
            **old_body,
            "baseName": new_name,
            "desc": new_description,
            "cover": str(cover).strip() if cover is not None else old_body["cover"],
            "rule": (
                self._knowledge_hub_rule(split_rule) if split_rule is not None else old_body["rule"]
            ),
        }
        self._knowledge_hub_json_request(
            context,
            "/v1/manage/multi/knowledge/base/addOrUpdate",
            "knowledge-hub base update",
            method="POST",
            params={"mode": "UPDATE"},
            json_body=request_body,
        )
        refreshed_raw = self._knowledge_hub_base_detail_raw(context, selected["base_id"])
        refreshed = self._normalize_knowledge_hub_base(refreshed_raw, selected["index"])
        expected = {
            "name": new_name,
            "description": new_description,
            "cover": request_body["cover"],
        }
        if any(refreshed[key] != value for key, value in expected.items()):
            try:
                self._knowledge_hub_json_request(
                    context,
                    "/v1/manage/multi/knowledge/base/addOrUpdate",
                    "knowledge-hub base rollback",
                    method="POST",
                    params={"mode": "UPDATE"},
                    json_body=old_body,
                )
            except ChaoxingAPIError:
                pass
            raise ChaoxingAPIError(
                "knowledge-hub base update was acknowledged but the requested "
                "fields did not persist"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "base": refreshed,
            "verification": "updated knowledge-hub base detail re-read by stable ID",
        }

    def _set_knowledge_hub_boolean_state(
        self,
        context: dict[str, Any],
        base: str,
        *,
        field: str,
        value: bool,
        path: str,
        params: dict[str, Any] | None,
        body_factory: Any,
        operation: str,
    ) -> dict[str, Any]:
        selected = self._knowledge_hub_resolve_from_context(context, base)
        if selected[field] == value:
            return selected
        old_value = bool(selected[field])
        self._knowledge_hub_json_request(
            context,
            path,
            operation,
            method="POST",
            params=params,
            json_body=body_factory(selected["base_id"], value),
        )
        refreshed_raw = self._knowledge_hub_base_detail_raw(context, selected["base_id"])
        refreshed = self._normalize_knowledge_hub_base(refreshed_raw, selected["index"])
        if refreshed[field] != value:
            try:
                rollback_params = params
                if params and "enable" in params:
                    rollback_params = {**params, "enable": str(old_value).lower()}
                self._knowledge_hub_json_request(
                    context,
                    path,
                    f"{operation} rollback",
                    method="POST",
                    params=rollback_params,
                    json_body=body_factory(selected["base_id"], old_value),
                )
            except ChaoxingAPIError:
                pass
            raise ChaoxingAPIError(
                f"{operation} was acknowledged but the requested state did not persist"
            )
        return refreshed

    def set_knowledge_hub_base_availability(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        base: str,
        enabled: bool,
    ) -> dict[str, Any]:
        context = self._knowledge_hub_context(course, clazz)
        refreshed = self._set_knowledge_hub_boolean_state(
            context,
            base,
            field="enabled",
            value=bool(enabled),
            path="/v1/manage/multi/knowledge/switch/availability",
            params={"enable": str(bool(enabled)).lower()},
            body_factory=lambda base_id, _value: [base_id],
            operation="knowledge-hub base availability update",
        )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "base": refreshed,
            "verification": "knowledge-hub base availability re-read by stable ID",
        }

    def set_knowledge_hub_base_priority(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        base: str,
        priority: bool,
    ) -> dict[str, Any]:
        context = self._knowledge_hub_context(course, clazz)
        selected = self._knowledge_hub_resolve_from_context(context, base)
        target = 1 if priority else 0
        if selected["priority"] != target:
            old_target = selected["priority"]
            self._knowledge_hub_json_request(
                context,
                "/v1/manage/multi/knowledge/setKnowledgePriority",
                "knowledge-hub base priority update",
                method="POST",
                json_body={"baseIds": [selected["base_id"]], "priority": target},
            )
            raw = self._knowledge_hub_base_detail_raw(context, selected["base_id"])
            selected = self._normalize_knowledge_hub_base(raw, selected["index"])
            if selected["priority"] != target:
                try:
                    self._knowledge_hub_json_request(
                        context,
                        "/v1/manage/multi/knowledge/setKnowledgePriority",
                        "knowledge-hub base priority rollback",
                        method="POST",
                        json_body={
                            "baseIds": [selected["base_id"]],
                            "priority": old_target,
                        },
                    )
                except ChaoxingAPIError:
                    pass
                raise ChaoxingAPIError("knowledge-hub base priority update did not persist")
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "base": selected,
            "verification": "knowledge-hub base priority re-read by stable ID",
        }

    def set_knowledge_hub_base_share(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        base: str,
        shared: bool,
    ) -> dict[str, Any]:
        context = self._knowledge_hub_context(course, clazz)
        refreshed = self._set_knowledge_hub_boolean_state(
            context,
            base,
            field="shared",
            value=bool(shared),
            path="/v1/manage/multi/knowledge/switch/share",
            params=None,
            body_factory=lambda base_id, value: {"baseId": base_id, "shared": value},
            operation="knowledge-hub base share update",
        )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "base": refreshed,
            "verification": "knowledge-hub base share state re-read by stable ID",
        }

    def delete_knowledge_hub_base(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        base: str,
    ) -> dict[str, Any]:
        context = self._knowledge_hub_context(course, clazz)
        selected = self._knowledge_hub_resolve_from_context(context, base)
        if selected["default_base"]:
            raise ChaoxingAPIError("the default knowledge-hub base cannot be deleted")
        self._knowledge_hub_json_request(
            context,
            "/v1/manage/multi/knowledge/delete",
            "knowledge-hub base deletion",
            method="POST",
            json_body=[selected["base_id"]],
        )
        remaining: list[dict[str, Any]] = []
        for attempt in range(10):
            remaining, _ = self._knowledge_hub_bases_from_context(context, page_size=1000)
            if not any(item["base_id"] == selected["base_id"] for item in remaining):
                break
            if attempt < 9:
                sleep(0.25)
        else:
            raise ChaoxingAPIError(
                "knowledge-hub base deletion was acknowledged but the base is still visible"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "deleted_base": selected,
            "remaining_count": len(remaining),
            "verification": "deleted knowledge-hub base is absent from the refreshed base list",
        }

    @classmethod
    def _normalize_knowledge_hub_document(
        cls,
        raw: dict[str, Any],
        index: int,
    ) -> dict[str, Any]:
        enabled_value = raw.get("fileEnable")
        if enabled_value is None and "disabled" in raw:
            enabled_value = not cls._knowledge_hub_bool(raw.get("disabled"))
        return {
            "index": index,
            "document_id": str(raw.get("id") or raw.get("documentId") or ""),
            "file_key": str(raw.get("fileKey") or raw.get("key") or ""),
            "object_id": str(raw.get("objectId") or raw.get("objectid") or ""),
            "name": str(raw.get("docName") or raw.get("fileName") or raw.get("name") or ""),
            "file_type": str(raw.get("fileType") or raw.get("suffix") or ""),
            "file_size": cls._ai_workbench_integer(raw.get("fileSize") or raw.get("size"), 0),
            "state": cls._ai_workbench_integer(raw.get("state"), -1),
            "source": str(raw.get("from") or raw.get("source") or ""),
            "classify_id": str(raw.get("classifyId") or ""),
            "classify_name": str(raw.get("classifyName") or ""),
            "enabled": cls._knowledge_hub_bool(enabled_value),
            "download_allowed": cls._knowledge_hub_bool(
                raw.get("allowDownload") or raw.get("downloadAllowed")
            ),
            "hidden_part": cls._knowledge_hub_bool(raw.get("hiddenPart")),
            "publish_date": str(raw.get("publishDate") or ""),
            "created_at": str(raw.get("createTime") or raw.get("createdAt") or ""),
            "updated_at": str(raw.get("updateTime") or raw.get("updatedAt") or ""),
        }

    def _knowledge_hub_documents_from_context(
        self,
        context: dict[str, Any],
        base_id: str,
        *,
        page: int = 1,
        page_size: int = 100,
        state: str = "",
        source: str = "",
        search: str = "",
        classify_id: str = "",
        file_type: str = "",
        begin_time: str = "",
        end_time: str = "",
        order: str = "",
    ) -> tuple[list[dict[str, Any]], dict[str, Any]]:
        if page < 1 or not 1 <= page_size <= 1000:
            raise ChaoxingAPIError("knowledge-hub document page or page_size is invalid")
        payload = self._knowledge_hub_json_request(
            context,
            f"/v1/manage/document/list/{page}/{page_size}",
            "knowledge-hub document list",
            params={
                "state": state,
                "from": source,
                "crawlTaskId": "",
                "uids": "",
                "indexSearch": 0,
                "classifyId": classify_id,
                "docName": search,
                "beginTime": begin_time,
                "endTime": end_time,
                "baseId": base_id,
                "fileType": file_type,
                "courseId": str(context["course"]["course_id"]),
                "order": order,
            },
        )
        records, page_info = self._knowledge_hub_page(payload)
        start = (page - 1) * page_size
        documents = [
            self._normalize_knowledge_hub_document(raw, start + index)
            for index, raw in enumerate(records, 1)
        ]
        return documents, page_info

    def _knowledge_hub_all_documents(
        self,
        context: dict[str, Any],
        base_id: str,
        *,
        search: str = "",
    ) -> list[dict[str, Any]]:
        documents: list[dict[str, Any]] = []
        page = 1
        while page <= 100:
            current, page_info = self._knowledge_hub_documents_from_context(
                context, base_id, page=page, page_size=200, search=search
            )
            documents.extend(current)
            total = self._ai_workbench_integer(page_info.get("total"), len(documents))
            if not current or len(documents) >= total:
                return documents
            page += 1
        raise ChaoxingAPIError("knowledge-hub document list exceeded 100 pages")

    @staticmethod
    def _resolve_knowledge_hub_document(
        documents: list[dict[str, Any]], query: str
    ) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("knowledge-hub document name or ID is required")
        exact = [
            item
            for item in documents
            if normalized
            in {
                str(item.get("document_id") or "").lower(),
                str(item.get("file_key") or "").lower(),
                str(item.get("object_id") or "").lower(),
                str(item.get("name") or "").strip().lower(),
            }
        ]
        if len(exact) == 1:
            return exact[0]
        if len(exact) > 1:
            options = ", ".join(f"{item['name']} ({item['file_key']})" for item in exact[:10])
            raise ChaoxingAPIError(f"multiple knowledge-hub documents match: {options}")
        partial = [item for item in documents if normalized in str(item.get("name") or "").lower()]
        if len(partial) == 1:
            return partial[0]
        if not partial:
            raise ChaoxingAPIError(f"knowledge-hub document not found: {query}")
        options = ", ".join(f"{item['name']} ({item['file_key']})" for item in partial[:10])
        raise ChaoxingAPIError(f"multiple knowledge-hub documents match: {options}")

    def list_knowledge_hub_documents(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        base: str,
        *,
        page: int = 1,
        page_size: int = 100,
        state: str = "",
        source: str = "",
        search: str = "",
        classify_id: str = "",
        file_type: str = "",
        begin_time: str = "",
        end_time: str = "",
        order: str = "",
    ) -> dict[str, Any]:
        context = self._knowledge_hub_context(course, clazz)
        selected = self._knowledge_hub_resolve_from_context(context, base)
        documents, page_info = self._knowledge_hub_documents_from_context(
            context,
            selected["base_id"],
            page=page,
            page_size=page_size,
            state=state,
            source=source,
            search=search,
            classify_id=classify_id,
            file_type=file_type,
            begin_time=begin_time,
            end_time=end_time,
            order=order,
        )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "base": selected,
            "count": len(documents),
            "page": page_info,
            "documents": documents,
            "verification": "knowledge-hub document page read through authenticated HTTP",
        }

    def download_knowledge_hub_document(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        base: str,
        document: str,
        output_path: str | Path,
        *,
        overwrite: bool = False,
    ) -> dict[str, Any]:
        context = self._knowledge_hub_context(course, clazz)
        selected_base = self._knowledge_hub_resolve_from_context(context, base)
        documents = self._knowledge_hub_all_documents(context, selected_base["base_id"])
        selected = self._resolve_knowledge_hub_document(documents, document)
        if not selected["file_key"]:
            raise ChaoxingAPIError("knowledge-hub document omitted its download file key")
        requested = Path(output_path).expanduser()
        if requested.exists() and requested.is_dir():
            destination = requested / (Path(selected["name"]).name or "knowledge-document.bin")
        elif str(output_path).endswith(("/", "\\")):
            requested.mkdir(parents=True, exist_ok=True)
            destination = requested / (Path(selected["name"]).name or "knowledge-document.bin")
        else:
            destination = requested
        destination = destination.resolve()
        if destination.exists() and not overwrite:
            raise ChaoxingAPIError(f"output file already exists: {destination}")
        destination.parent.mkdir(parents=True, exist_ok=True)
        response = self._knowledge_hub_response(
            context,
            "/v1/manage/document/"
            f"{quote(selected_base['base_id'], safe='')}/"
            f"{quote(selected['file_key'], safe='')}/download",
            "knowledge-hub document download",
            stream=True,
        )
        temporary = destination.with_name(f".{destination.name}.{uuid4().hex}.part")
        written = 0
        try:
            with temporary.open("wb") as handle:
                for chunk in response.iter_content(chunk_size=1024 * 1024):
                    if chunk:
                        handle.write(chunk)
                        written += len(chunk)
            if written == 0:
                raise ChaoxingAPIError("knowledge-hub document download returned an empty file")
            temporary.replace(destination)
        except OSError as exc:
            raise ChaoxingAPIError(f"cannot save knowledge-hub document: {exc}") from exc
        finally:
            temporary.unlink(missing_ok=True)
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "base": selected_base,
            "document": selected,
            "output_path": str(destination),
            "bytes_written": written,
            "verification": "download completed and a non-empty local file was written",
        }

    @staticmethod
    def _knowledge_hub_find_value(value: Any, keys: set[str]) -> Any:
        if isinstance(value, dict):
            for key, item in value.items():
                if str(key).lower() in keys and item is not None and item != "":
                    return item
            for item in value.values():
                found = ChaoxingAPI._knowledge_hub_find_value(item, keys)
                if found is not None and found != "":
                    return found
        elif isinstance(value, list):
            for item in value:
                found = ChaoxingAPI._knowledge_hub_find_value(item, keys)
                if found is not None and found != "":
                    return found
        return None

    def _knowledge_hub_default_classify_id(self, context: dict[str, Any]) -> str:
        payload = self._knowledge_hub_json_request(
            context,
            "/v1/manage/question/classify/list",
            "knowledge-hub document classifications read",
            params={"type": "DOC", "checkMultiRobot": "false"},
        )
        data = self._knowledge_hub_payload_data(payload)
        records = data if isinstance(data, list) else []
        if isinstance(data, dict):
            records = data.get("records") or data.get("list") or data.get("items") or []
        for raw in records:
            if isinstance(raw, dict):
                value = raw.get("id") or raw.get("classifyId")
                if value not in {None, ""}:
                    return str(value)
        return "2"

    def upload_knowledge_hub_document(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        base: str,
        file: str | Path,
        *,
        classify_id: str = "",
        split_rule: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        source = Path(file).expanduser().resolve()
        if not source.is_file():
            raise ChaoxingAPIError(f"knowledge-hub upload file not found: {source}")
        suffix = source.suffix.lower()
        if suffix not in KNOWLEDGE_HUB_UPLOAD_EXTENSIONS:
            allowed = ", ".join(sorted(KNOWLEDGE_HUB_UPLOAD_EXTENSIONS))
            raise ChaoxingAPIError(f"unsupported knowledge-hub upload type; allowed: {allowed}")
        if suffix in {".jpg", ".jpeg", ".png", ".gif", ".webp", ".bmp"}:
            if source.stat().st_size > 20 * 1024 * 1024:
                raise ChaoxingAPIError("knowledge-hub image upload must not exceed 20 MB")
        context = self._knowledge_hub_context(course, clazz)
        selected_base = self._knowledge_hub_resolve_from_context(context, base)
        before = self._knowledge_hub_all_documents(context, selected_base["base_id"])
        before_keys = {
            item["file_key"] or item["document_id"] or item["object_id"] for item in before
        }
        token_payload = self._knowledge_hub_json_request(
            context,
            "/v1/manage/multi/knowledge/upload/token",
            "knowledge-hub upload authorization",
        )
        token_data = self._knowledge_hub_payload_data(token_payload)
        upload_url = str(self._knowledge_hub_find_value(token_data, {"uploadurl"}) or "").strip()
        puid = str(self._knowledge_hub_find_value(token_data, {"puid"}) or "").strip()
        client_ip = str(self._knowledge_hub_find_value(token_data, {"clientip"}) or "").strip()
        token = str(self._knowledge_hub_find_value(token_data, {"token"}) or "").strip()
        parsed_upload = urlparse(upload_url)
        upload_host = str(parsed_upload.hostname or "").lower()
        if (
            not upload_url
            or not token
            or not puid
            or not (upload_host == "chaoxing.com" or upload_host.endswith(".chaoxing.com"))
        ):
            raise ChaoxingAPIError("knowledge-hub upload authorization was incomplete")
        mime = mimetypes.guess_type(source.name)[0] or "application/octet-stream"
        try:
            with source.open("rb") as handle:
                upload_response = context["session"].post(
                    upload_url,
                    data={
                        "puid": puid,
                        "clientip": client_ip,
                        "_token": token,
                        "uploadtype": "normal",
                    },
                    files={"file": (source.name, handle, mime)},
                    timeout=max(self.timeout, 120.0),
                )
                upload_response.raise_for_status()
        except (OSError, requests.RequestException) as exc:
            raise ChaoxingAPIError(
                f"knowledge-hub file transfer failed ({type(exc).__name__})"
            ) from exc
        try:
            upload_payload = json.loads(self._decode(upload_response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("knowledge-hub file transfer returned invalid JSON") from exc
        object_id = str(self._knowledge_hub_find_value(upload_payload, {"objectid"}) or "").strip()
        if not object_id:
            raise ChaoxingAPIError("knowledge-hub file transfer returned no object ID")
        selected_classify_id = str(
            classify_id or ""
        ).strip() or self._knowledge_hub_default_classify_id(context)
        self._knowledge_hub_json_request(
            context,
            "/v1/manage/multi/knowledge/file/multi/upload",
            "knowledge-hub document registration",
            method="POST",
            params={"baseId": selected_base["base_id"]},
            json_body={
                "classifyId": selected_classify_id,
                "splitRule": json.dumps(
                    self._knowledge_hub_rule(split_rule), ensure_ascii=False, separators=(",", ":")
                ),
                "fileList": [{"fileName": source.name, "objectId": object_id}],
            },
        )
        created: dict[str, Any] | None = None
        for attempt in range(60):
            after = self._knowledge_hub_all_documents(context, selected_base["base_id"])
            candidates = [
                item
                for item in after
                if item["name"] == source.name
                and (item["file_key"] or item["document_id"] or item["object_id"])
                not in before_keys
            ]
            if len(candidates) == 1:
                created = candidates[0]
                break
            if attempt < 59:
                sleep(0.5)
        if created is None:
            raise ChaoxingAPIError(
                "knowledge-hub document registration was acknowledged but the new document "
                "was not visible after 30 seconds"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "base": selected_base,
            "document": created,
            "verification": "new knowledge-hub document appeared in the refreshed document list",
        }

    def delete_knowledge_hub_document(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        base: str,
        document: str,
    ) -> dict[str, Any]:
        context = self._knowledge_hub_context(course, clazz)
        selected_base = self._knowledge_hub_resolve_from_context(context, base)
        documents = self._knowledge_hub_all_documents(context, selected_base["base_id"])
        selected = self._resolve_knowledge_hub_document(documents, document)
        if not selected["file_key"]:
            raise ChaoxingAPIError("knowledge-hub document omitted its deletion file key")
        self._knowledge_hub_json_request(
            context,
            "/v1/manage/document/remove",
            "knowledge-hub document deletion",
            method="POST",
            params={
                "fileKey": selected["file_key"],
                "baseId": selected_base["base_id"],
            },
        )
        for attempt in range(20):
            remaining = self._knowledge_hub_all_documents(context, selected_base["base_id"])
            if not any(item["file_key"] == selected["file_key"] for item in remaining):
                break
            if attempt < 19:
                sleep(0.25)
        else:
            raise ChaoxingAPIError(
                "knowledge-hub document deletion was acknowledged but the document is still visible"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "base": selected_base,
            "deleted_document": selected,
            "verification": "deleted knowledge-hub document is absent from the refreshed list",
        }

    @staticmethod
    def _ai_workbench_integer(value: Any, default: int = 0) -> int:
        try:
            return int(value)
        except (TypeError, ValueError):
            return default

    @staticmethod
    def _ai_workbench_html_attributes(fragment: str) -> dict[str, str]:
        attributes: dict[str, str] = {}
        pattern = re.compile(
            r"([:\w-]+)\s*=\s*(?:\"([^\"]*)\"|'([^']*)'|([^\s\"'=<>`]+))",
            flags=re.I | re.S,
        )
        for match in pattern.finditer(fragment):
            value = next((item for item in match.groups()[1:] if item is not None), "")
            attributes[match.group(1).lower()] = unescape(value)
        return attributes

    @staticmethod
    def _ai_workbench_role_label(role_type: int) -> str:
        return {
            0: "teacher",
            1: "student",
            2: "teacher_and_student",
            3: "closed",
        }.get(role_type, "unknown")

    @staticmethod
    def _ai_workbench_validate_group_name(name: str) -> str:
        normalized = str(name or "").strip()
        if not 1 <= len(normalized) <= 128:
            raise ChaoxingAPIError("AI command group name must contain 1-128 characters")
        return normalized

    @staticmethod
    def _ai_workbench_validate_command_fields(
        *,
        name: str,
        content: str,
        explanation: str,
        prompt_words: str,
        role_type: int,
        classify_id: int,
        command_ability: int,
        ability_type: int,
    ) -> dict[str, Any]:
        normalized = {
            "name": str(name or "").strip(),
            "content": str(content or "").strip(),
            "explanation": str(explanation or "").strip(),
            "prompt_words": str(prompt_words or "").strip(),
        }
        limits = {"name": 128, "content": 512, "explanation": 512, "prompt_words": 2048}
        for key in ("name", "content", "explanation"):
            if not normalized[key]:
                raise ChaoxingAPIError(f"AI command {key} is required")
        for key, limit in limits.items():
            if len(normalized[key]) > limit:
                raise ChaoxingAPIError(f"AI command {key} must not exceed {limit} characters")
        if role_type not in {0, 1, 2, 3}:
            raise ChaoxingAPIError("role_type must be 0, 1, 2, or 3")
        if classify_id < 0:
            raise ChaoxingAPIError("classify_id must be non-negative")
        if command_ability not in {0, 1}:
            raise ChaoxingAPIError("command_ability must be 0 or 1")
        if ability_type < 0:
            raise ChaoxingAPIError("ability_type must be non-negative")
        return {
            **normalized,
            "role_type": role_type,
            "classify_id": classify_id,
            "command_ability": command_ability,
            "ability_type": ability_type,
        }

    def _ai_workbench_context(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> dict[str, Any]:
        session = self._session()
        course_context = self._course_context(session, course, clazz)
        module = resolve_module(course_context["modules"], "AI工作台")
        request_url = self._module_url(course_context, module, course, clazz)
        try:
            response = session.get(
                request_url,
                timeout=self.timeout,
                allow_redirects=True,
                headers={"Referer": str(course_context["final_url"])},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"AI workbench request failed: {exc}") from exc
        html = self._decode(response)
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError(f"AI workbench request was redirected to login: {response.url}")
        page_hidden = parse_hidden_inputs(html)
        course_hidden = (
            course_context["hidden"] if isinstance(course_context.get("hidden"), dict) else {}
        )
        query = parse_qs(urlparse(response.url).query)

        def first(*keys: str, fallback: Any = "") -> str:
            for key in keys:
                values = query.get(key)
                if values and str(values[0]).strip():
                    return str(values[0]).strip()
                for source in (page_hidden, course_hidden):
                    if str(source.get(key) or "").strip():
                        return str(source[key]).strip()
            return str(fallback or "").strip()

        common = {
            "clazzId": first("clazzId", "clazzid", fallback=clazz.get("clazz_id")),
            "courseId": first("courseId", "courseid", fallback=course.get("course_id")),
            "cpi": first("cpi", fallback=course.get("cpi")),
            "ut": first("ut", fallback="t") or "t",
        }
        if not all(common[key] for key in ("clazzId", "courseId", "cpi")):
            raise ChaoxingAPIError("AI workbench response omitted course context identifiers")
        return {
            "session": session,
            "root_url": response.url,
            "request_url": request_url,
            "course": course,
            "clazz": clazz,
            "common": common,
            "module": module,
        }

    def _ai_workbench_response(
        self,
        context: dict[str, Any],
        path: str,
        operation: str,
        *,
        method: str = "GET",
        params: dict[str, Any] | None = None,
        data: dict[str, Any] | None = None,
    ) -> requests.Response:
        url = urljoin(MOOC1_BASE_URL + "/", path.lstrip("/"))
        headers = {
            "Referer": str(context["root_url"]),
            "X-Requested-With": "XMLHttpRequest",
        }
        try:
            if method.upper() == "POST":
                response = context["session"].post(
                    url,
                    params=params,
                    data=data,
                    timeout=self.timeout,
                    headers=headers,
                )
            else:
                response = context["session"].get(
                    url,
                    params=params,
                    timeout=self.timeout,
                    headers=headers,
                )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"{operation} failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError(f"{operation} was redirected to login: {response.url}")
        return response

    def _ai_workbench_json_request(
        self,
        context: dict[str, Any],
        path: str,
        operation: str,
        *,
        method: str = "GET",
        params: dict[str, Any] | None = None,
        data: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        response = self._ai_workbench_response(
            context,
            path,
            operation,
            method=method,
            params=params,
            data=data,
        )
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError(f"{operation} returned invalid JSON") from exc
        if not isinstance(payload, dict):
            raise ChaoxingAPIError(f"{operation} returned invalid JSON")
        if payload.get("status") is False or payload.get("success") is False:
            raise ChaoxingAPIError(str(payload.get("msg") or f"{operation} was rejected"))
        if "code" in payload and self._ai_workbench_integer(payload.get("code"), -1) not in {0, 1}:
            raise ChaoxingAPIError(str(payload.get("msg") or f"{operation} was rejected"))
        return payload

    @staticmethod
    def _ai_workbench_ack(payload: dict[str, Any], operation: str) -> None:
        acknowledged = (
            payload.get("status") is True
            or payload.get("success") is True
            or payload.get("result") is True
            or payload.get("result") == 1
            or payload.get("code") == 0
        )
        if not acknowledged:
            raise ChaoxingAPIError(str(payload.get("msg") or f"{operation} was not acknowledged"))

    def _ai_workbench_groups_from_context(
        self,
        context: dict[str, Any],
    ) -> list[dict[str, Any]]:
        payload = self._ai_workbench_json_request(
            context,
            "/course-ans/ai/v3/get-command-group-data",
            "AI command group list",
            params={key: context["common"][key] for key in ("clazzId", "courseId", "cpi")},
        )
        data = payload.get("data") if isinstance(payload.get("data"), dict) else {}
        raw_groups = (
            data.get("aiCommandGroupList")
            if isinstance(data.get("aiCommandGroupList"), list)
            else []
        )
        groups: list[dict[str, Any]] = []
        for index, raw in enumerate(raw_groups, 1):
            if not isinstance(raw, dict):
                continue
            group_id = str(raw.get("id") if raw.get("id") is not None else "").strip()
            if not group_id:
                continue
            name = str(raw.get("groupName") or raw.get("name") or "").strip()
            groups.append(
                {
                    "index": index,
                    "group_id": group_id,
                    "name": name,
                    "course_id": str(raw.get("courseId") or context["common"]["courseId"]),
                    "is_system": group_id == "0",
                    "can_rename": group_id != "0",
                    "can_delete": group_id != "0",
                }
            )
        return groups

    @staticmethod
    def _resolve_ai_workbench_group(
        groups: list[dict[str, Any]],
        query: str,
    ) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("AI command group name or ID is required")
        for key in ("group_id", "name"):
            exact = [
                item for item in groups if str(item.get(key) or "").strip().lower() == normalized
            ]
            if len(exact) == 1:
                return exact[0]
            if len(exact) > 1:
                options = ", ".join(f"{item['name']} ({item['group_id']})" for item in exact)
                raise ChaoxingAPIError(f"multiple AI command groups match: {options}")
        partial = [item for item in groups if normalized in str(item.get("name") or "").lower()]
        if len(partial) == 1:
            return partial[0]
        if not partial:
            raise ChaoxingAPIError(f"AI command group not found: {query}")
        options = ", ".join(f"{item['name']} ({item['group_id']})" for item in partial[:10])
        raise ChaoxingAPIError(f"multiple AI command groups match: {options}")

    def list_ai_workbench_groups(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> dict[str, Any]:
        context = self._ai_workbench_context(course, clazz)
        groups = self._ai_workbench_groups_from_context(context)
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "count": len(groups),
            "groups": groups,
            "verification": "AI command groups read from the authenticated workbench API",
        }

    def create_ai_workbench_group(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        name: str,
    ) -> dict[str, Any]:
        normalized_name = self._ai_workbench_validate_group_name(name)
        context = self._ai_workbench_context(course, clazz)
        before = self._ai_workbench_groups_from_context(context)
        if len(before) >= 10:
            raise ChaoxingAPIError("AI workbench already has the maximum of 10 command groups")
        if any(item["name"] == normalized_name for item in before):
            raise ChaoxingAPIError(f"AI command group already exists: {normalized_name}")
        payload = self._ai_workbench_json_request(
            context,
            "/course-ans/ai/add-command-group",
            "AI command group creation",
            params={**context["common"], "groupName": normalized_name},
        )
        self._ai_workbench_ack(payload, "AI command group creation")
        after = self._ai_workbench_groups_from_context(context)
        before_ids = {item["group_id"] for item in before}
        created = [
            item
            for item in after
            if item["group_id"] not in before_ids and item["name"] == normalized_name
        ]
        if len(created) != 1:
            raise ChaoxingAPIError(
                "server acknowledged group creation, but it was not uniquely visible"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "group": created[0],
            "verification": "new group ID appeared in the refreshed workbench group list",
        }

    def rename_ai_workbench_group(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        group: str,
        name: str,
    ) -> dict[str, Any]:
        normalized_name = self._ai_workbench_validate_group_name(name)
        context = self._ai_workbench_context(course, clazz)
        groups = self._ai_workbench_groups_from_context(context)
        selected = self._resolve_ai_workbench_group(groups, group)
        if selected["is_system"]:
            raise ChaoxingAPIError("the system command group cannot be renamed")
        if any(
            item["group_id"] != selected["group_id"] and item["name"] == normalized_name
            for item in groups
        ):
            raise ChaoxingAPIError(f"AI command group already exists: {normalized_name}")
        payload = self._ai_workbench_json_request(
            context,
            "/course-ans/ai/update-command-group",
            "AI command group rename",
            params={
                **context["common"],
                "groupId": selected["group_id"],
                "groupName": normalized_name,
            },
        )
        self._ai_workbench_ack(payload, "AI command group rename")
        refreshed = self._resolve_ai_workbench_group(
            self._ai_workbench_groups_from_context(context), selected["group_id"]
        )
        if refreshed["name"] != normalized_name:
            raise ChaoxingAPIError("server acknowledged group rename, but the name did not change")
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "group": refreshed,
            "verification": "group name matched after a fresh API read",
        }

    def reorder_ai_workbench_groups(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        groups: list[str],
    ) -> dict[str, Any]:
        context = self._ai_workbench_context(course, clazz)
        current = self._ai_workbench_groups_from_context(context)
        resolved = [self._resolve_ai_workbench_group(current, query) for query in groups]
        requested_ids = [item["group_id"] for item in resolved]
        current_ids = [item["group_id"] for item in current]
        if len(set(requested_ids)) != len(requested_ids) or set(requested_ids) != set(current_ids):
            raise ChaoxingAPIError(
                "groups must contain every current AI command group exactly once, including group 0"
            )
        payload = self._ai_workbench_json_request(
            context,
            "/course-ans/ai/updateAiWorkBenchCommandGroupSort",
            "AI command group reorder",
            method="POST",
            data={
                **{key: context["common"][key] for key in ("clazzId", "courseId", "cpi")},
                "sortedIds": ",".join(requested_ids) + ",",
            },
        )
        self._ai_workbench_ack(payload, "AI command group reorder")
        refreshed = self._ai_workbench_groups_from_context(context)
        if [item["group_id"] for item in refreshed] != requested_ids:
            raise ChaoxingAPIError("server acknowledged group reorder, but refreshed order differs")
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "groups": refreshed,
            "verification": "refreshed group IDs match the complete requested order",
        }

    @classmethod
    def _parse_ai_workbench_commands(
        cls,
        html: str,
        group: dict[str, Any],
    ) -> list[dict[str, Any]]:
        openings: list[tuple[int, int, dict[str, str]]] = []
        for match in re.finditer(r"<li\b([^>]*)>", html, flags=re.I | re.S):
            attrs = cls._ai_workbench_html_attributes(match.group(1))
            classes = str(attrs.get("class") or "").split()
            if "commandInfo" in classes:
                openings.append((match.start(), match.end(), attrs))
        commands: list[dict[str, Any]] = []
        seen: set[str] = set()
        for index, (_start, end, attrs) in enumerate(openings):
            next_start = openings[index + 1][0] if index + 1 < len(openings) else len(html)
            body = html[end:next_start]
            identifier = str(attrs.get("id") or "")
            id_match = re.search(r"commandLiCls_([^\s\"']+)", identifier, flags=re.I)
            if not id_match:
                id_match = re.search(
                    r"(?:editCustomCommandPop|showMoveCommandToGroupPop|showDeleteCommandPop)"
                    r"\([^,)]*?['\"]?([0-9]+)",
                    body,
                    flags=re.I,
                )
            command_id = id_match.group(1) if id_match else ""
            if not command_id or command_id in seen:
                continue
            seen.add(command_id)
            role_type = cls._ai_workbench_integer(attrs.get("curroletype"), 3)
            publish_status = cls._ai_workbench_integer(attrs.get("publishstatus"), 0)
            mapping_id = cls._ai_workbench_integer(attrs.get("mapping"), 0)
            can_edit = "editCustomCommandPop" in body
            can_move = "showMoveCommandToGroupPop" in body
            can_delete = "showDeleteCommandPop" in body
            can_publish = "publishAiWork(" in body
            if mapping_id:
                command_kind = "mapped"
            elif can_edit or can_move or can_delete or can_publish:
                command_kind = "custom"
            else:
                command_kind = "system"
            commands.append(
                {
                    "index": len(commands) + 1,
                    "command_id": command_id,
                    "group_id": group["group_id"],
                    "group_name": group["name"],
                    "name": str(attrs.get("commandname") or "").strip(),
                    "content": str(attrs.get("commanddesc") or "").strip(),
                    "explanation": str(attrs.get("commandexplain") or "").strip(),
                    "prompt_words": str(attrs.get("promptwords") or "").strip(),
                    "classify_id": cls._ai_workbench_integer(attrs.get("classifyid"), 0),
                    "mapping_id": mapping_id,
                    "publish_status": publish_status,
                    "published": publish_status in {1, 3},
                    "role_type": role_type,
                    "role": cls._ai_workbench_role_label(role_type),
                    "command_ability": cls._ai_workbench_integer(attrs.get("commandability"), 0),
                    "ability_type": cls._ai_workbench_integer(attrs.get("abilitytype"), 0),
                    "kind": command_kind,
                    "can_edit": can_edit,
                    "can_move": can_move,
                    "can_delete": can_delete,
                    "can_publish": can_publish,
                    "can_reorder": "toolDrag" in body,
                }
            )
        return commands

    @staticmethod
    def _parse_ai_workbench_role_order(
        html: str,
        group_id: str,
        role_type: int,
    ) -> list[str]:
        role = "Tea" if role_type == 0 else "Stu"
        match = re.search(
            rf"<ul\b[^>]*\bid=[\"']zlSort{role}_{re.escape(group_id)}[\"'][^>]*>"
            r"(?P<body>.*?)</ul>",
            html,
            flags=re.I | re.S,
        )
        if not match:
            return []
        return list(
            dict.fromkeys(re.findall(r"commandLiCls_([^\s\"']+)", match.group("body"), flags=re.I))
        )

    def _ai_workbench_commands_for_group(
        self,
        context: dict[str, Any],
        group: dict[str, Any],
        *,
        search: str = "",
    ) -> dict[str, Any]:
        response = self._ai_workbench_response(
            context,
            "/course-ans/ai/loadCommandSubData",
            "AI command list",
            params={
                **context["common"],
                "groupId": group["group_id"],
                "kw": str(search or "").strip(),
            },
        )
        html = self._decode(response)
        return {
            "commands": self._parse_ai_workbench_commands(html, group),
            "role_orders": {
                "teacher": self._parse_ai_workbench_role_order(html, group["group_id"], 0),
                "student": self._parse_ai_workbench_role_order(html, group["group_id"], 1),
            },
        }

    @staticmethod
    def _resolve_ai_workbench_command(
        commands: list[dict[str, Any]],
        query: str,
    ) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("AI command name or ID is required")
        for key in ("command_id", "name"):
            exact = [
                item for item in commands if str(item.get(key) or "").strip().lower() == normalized
            ]
            if len(exact) == 1:
                return exact[0]
            if len(exact) > 1:
                options = ", ".join(
                    f"{item['name']} ({item['command_id']}, group {item['group_id']})"
                    for item in exact[:10]
                )
                raise ChaoxingAPIError(f"multiple AI commands match: {options}")
        partial = [item for item in commands if normalized in str(item.get("name") or "").lower()]
        if len(partial) == 1:
            return partial[0]
        if not partial:
            raise ChaoxingAPIError(f"AI command not found: {query}")
        options = ", ".join(
            f"{item['name']} ({item['command_id']}, group {item['group_id']})"
            for item in partial[:10]
        )
        raise ChaoxingAPIError(f"multiple AI commands match: {options}")

    def _ai_workbench_all_commands(
        self,
        context: dict[str, Any],
        *,
        group: str = "",
        search: str = "",
    ) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
        groups = self._ai_workbench_groups_from_context(context)
        selected_groups = (
            [self._resolve_ai_workbench_group(groups, group)]
            if str(group or "").strip()
            else groups
        )
        commands: list[dict[str, Any]] = []
        for selected in selected_groups:
            commands.extend(
                self._ai_workbench_commands_for_group(context, selected, search=search)["commands"]
            )
        return commands, selected_groups

    def list_ai_workbench_commands(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        group: str = "",
        search: str = "",
    ) -> dict[str, Any]:
        context = self._ai_workbench_context(course, clazz)
        commands, groups = self._ai_workbench_all_commands(context, group=group, search=search)
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "search": str(search or "").strip(),
            "groups": groups,
            "count": len(commands),
            "commands": commands,
            "verification": "AI commands parsed and deduplicated from authenticated workbench HTML",
        }

    def read_ai_workbench_command(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        command: str,
        *,
        group: str = "",
    ) -> dict[str, Any]:
        context = self._ai_workbench_context(course, clazz)
        commands, _ = self._ai_workbench_all_commands(context, group=group)
        selected = self._resolve_ai_workbench_command(commands, command)
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "command": selected,
            "verification": "command resolved by stable ID or unambiguous current name",
        }

    def create_ai_workbench_command(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        group: str,
        name: str,
        content: str,
        explanation: str,
        *,
        prompt_words: str = "",
        role_type: int = 0,
        classify_id: int = 1,
        command_ability: int = 0,
        ability_type: int = 0,
    ) -> dict[str, Any]:
        fields = self._ai_workbench_validate_command_fields(
            name=name,
            content=content,
            explanation=explanation,
            prompt_words=prompt_words,
            role_type=role_type,
            classify_id=classify_id,
            command_ability=command_ability,
            ability_type=ability_type,
        )
        context = self._ai_workbench_context(course, clazz)
        selected_group = self._resolve_ai_workbench_group(
            self._ai_workbench_groups_from_context(context), group
        )
        before = self._ai_workbench_commands_for_group(context, selected_group)["commands"]
        payload = self._ai_workbench_json_request(
            context,
            "/course-ans/ai/v3/addAiCommand",
            "AI command creation",
            method="POST",
            data={
                **context["common"],
                "groupId": selected_group["group_id"],
                "commandName": fields["name"],
                "commandDesc": fields["content"],
                "commandExplain": fields["explanation"],
                "promptWords": fields["prompt_words"],
                "roleType": fields["role_type"],
                "classifyId": fields["classify_id"],
                "commandAbility": fields["command_ability"],
                "abilityType": fields["ability_type"],
            },
        )
        self._ai_workbench_ack(payload, "AI command creation")
        after = self._ai_workbench_commands_for_group(context, selected_group)["commands"]
        before_ids = {item["command_id"] for item in before}
        created = [
            item
            for item in after
            if item["command_id"] not in before_ids and item["name"] == fields["name"]
        ]
        if len(created) != 1:
            raise ChaoxingAPIError(
                "server acknowledged command creation, but it was not uniquely visible"
            )
        command = created[0]
        expected = {
            "name": fields["name"],
            "content": fields["content"],
            "explanation": fields["explanation"],
            "prompt_words": fields["prompt_words"],
            "role_type": fields["role_type"],
            "classify_id": fields["classify_id"],
            "command_ability": fields["command_ability"],
            "ability_type": fields["ability_type"],
        }
        if any(command[key] != value for key, value in expected.items()):
            raise ChaoxingAPIError("created AI command differs from the submitted fields")
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "command": command,
            "verification": "new command ID and all submitted fields matched after refresh",
        }

    def update_ai_workbench_command(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        command: str,
        *,
        group: str = "",
        name: str | None = None,
        content: str | None = None,
        explanation: str | None = None,
        prompt_words: str | None = None,
        role_type: int | None = None,
        classify_id: int | None = None,
        command_ability: int | None = None,
        ability_type: int | None = None,
    ) -> dict[str, Any]:
        context = self._ai_workbench_context(course, clazz)
        commands, _ = self._ai_workbench_all_commands(context, group=group)
        selected = self._resolve_ai_workbench_command(commands, command)
        requested_content_changes = any(
            value is not None
            for value in (
                name,
                content,
                explanation,
                prompt_words,
                classify_id,
                command_ability,
                ability_type,
            )
        )
        if selected["kind"] == "mapped":
            if requested_content_changes or role_type is None:
                raise ChaoxingAPIError("a mapped recommendation only supports role_type changes")
            if role_type not in {0, 1, 2, 3}:
                raise ChaoxingAPIError("role_type must be 0, 1, 2, or 3")
            payload = self._ai_workbench_json_request(
                context,
                "/course-ans/ai/updateMappingCommandSwitch",
                "mapped AI command role update",
                params={
                    **context["common"],
                    "commandId": selected["command_id"],
                    "roleType": role_type,
                },
            )
            self._ai_workbench_ack(payload, "mapped AI command role update")
            expected: dict[str, Any] = {"role_type": role_type}
        else:
            if selected["kind"] != "custom" or not selected["can_edit"]:
                raise ChaoxingAPIError("the selected system command cannot be edited")
            if selected["published"]:
                raise ChaoxingAPIError("unpublish the AI command before editing it")
            fields = self._ai_workbench_validate_command_fields(
                name=selected["name"] if name is None else name,
                content=selected["content"] if content is None else content,
                explanation=(selected["explanation"] if explanation is None else explanation),
                prompt_words=(selected["prompt_words"] if prompt_words is None else prompt_words),
                role_type=selected["role_type"] if role_type is None else role_type,
                classify_id=selected["classify_id"] if classify_id is None else classify_id,
                command_ability=(
                    selected["command_ability"] if command_ability is None else command_ability
                ),
                ability_type=selected["ability_type"] if ability_type is None else ability_type,
            )
            payload = self._ai_workbench_json_request(
                context,
                "/course-ans/ai/v3/update-work-command",
                "AI command update",
                method="POST",
                data={
                    **context["common"],
                    "dataId": selected["command_id"],
                    "groupId": selected["group_id"],
                    "commandName": fields["name"],
                    "commandDesc": fields["content"],
                    "commandExplain": fields["explanation"],
                    "promptWords": fields["prompt_words"],
                    "classifyId": fields["classify_id"],
                    "publishStatus": selected["publish_status"],
                    "roleType": fields["role_type"],
                    "commandAbility": fields["command_ability"],
                    "abilityType": fields["ability_type"],
                },
            )
            self._ai_workbench_ack(payload, "AI command update")
            expected = {
                "name": fields["name"],
                "content": fields["content"],
                "explanation": fields["explanation"],
                "prompt_words": fields["prompt_words"],
                "role_type": fields["role_type"],
                "classify_id": fields["classify_id"],
                "command_ability": fields["command_ability"],
                "ability_type": fields["ability_type"],
            }
        refreshed_commands, _ = self._ai_workbench_all_commands(context)
        refreshed = self._resolve_ai_workbench_command(refreshed_commands, selected["command_id"])
        if any(refreshed[key] != value for key, value in expected.items()):
            raise ChaoxingAPIError(
                "server acknowledged command update, but refreshed fields differ"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "command": refreshed,
            "verification": "all requested command fields matched after refresh",
        }

    def move_ai_workbench_command(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        command: str,
        target_group: str,
        *,
        group: str = "",
    ) -> dict[str, Any]:
        context = self._ai_workbench_context(course, clazz)
        groups = self._ai_workbench_groups_from_context(context)
        target = self._resolve_ai_workbench_group(groups, target_group)
        commands, _ = self._ai_workbench_all_commands(context, group=group)
        selected = self._resolve_ai_workbench_command(commands, command)
        if not selected["can_move"]:
            raise ChaoxingAPIError("the selected system command cannot be moved")
        if selected["group_id"] != target["group_id"]:
            payload = self._ai_workbench_json_request(
                context,
                "/course-ans/ai/move-ai-command",
                "AI command move",
                params={
                    **context["common"],
                    "groupId": target["group_id"],
                    "dataId": selected["command_id"],
                },
            )
            self._ai_workbench_ack(payload, "AI command move")
        refreshed_commands, _ = self._ai_workbench_all_commands(context)
        refreshed = self._resolve_ai_workbench_command(refreshed_commands, selected["command_id"])
        if refreshed["group_id"] != target["group_id"]:
            raise ChaoxingAPIError("server acknowledged command move, but target group differs")
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "command": refreshed,
            "verification": "command ID appeared in the requested group after refresh",
        }

    def reorder_ai_workbench_commands(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        group: str,
        role_type: int,
        commands: list[str],
    ) -> dict[str, Any]:
        if role_type not in {0, 1}:
            raise ChaoxingAPIError(
                "role_type for command ordering must be 0 (teacher) or 1 (student)"
            )
        context = self._ai_workbench_context(course, clazz)
        selected_group = self._resolve_ai_workbench_group(
            self._ai_workbench_groups_from_context(context), group
        )
        listing = self._ai_workbench_commands_for_group(context, selected_group)
        role_key = "teacher" if role_type == 0 else "student"
        current_ids = listing["role_orders"][role_key]
        eligible = [item for item in listing["commands"] if item["command_id"] in current_ids]
        resolved = [self._resolve_ai_workbench_command(eligible, query) for query in commands]
        requested_ids = [item["command_id"] for item in resolved]
        if len(set(requested_ids)) != len(requested_ids) or set(requested_ids) != set(current_ids):
            raise ChaoxingAPIError(
                f"commands must contain every {role_key} command in the group exactly once"
            )
        payload = self._ai_workbench_json_request(
            context,
            "/course-ans/ai/updateAiWorkBenchCommandSort",
            "AI command reorder",
            method="POST",
            data={
                **{key: context["common"][key] for key in ("clazzId", "courseId", "cpi")},
                "sortedIds": ",".join(requested_ids) + ",",
                "roleType": role_type,
                "groupId": selected_group["group_id"],
            },
        )
        self._ai_workbench_ack(payload, "AI command reorder")
        refreshed = self._ai_workbench_commands_for_group(context, selected_group)
        if refreshed["role_orders"][role_key] != requested_ids:
            raise ChaoxingAPIError(
                "server acknowledged command reorder, but refreshed order differs"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "group": selected_group,
            "role_type": role_type,
            "role": role_key,
            "command_ids": requested_ids,
            "verification": "refreshed role-specific command IDs match the complete order",
        }

    def set_ai_workbench_command_publish_status(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        command: str,
        published: bool,
        *,
        group: str = "",
    ) -> dict[str, Any]:
        context = self._ai_workbench_context(course, clazz)
        commands, _ = self._ai_workbench_all_commands(context, group=group)
        selected = self._resolve_ai_workbench_command(commands, command)
        if selected["kind"] != "custom" or not selected["can_edit"]:
            raise ChaoxingAPIError("only an editable custom AI command can be published")
        if bool(selected["published"]) != bool(published):
            payload = self._ai_workbench_json_request(
                context,
                "/course-ans/ai/publishAiWork",
                "AI command publish-status update",
                params={
                    **context["common"],
                    "entityId": selected["command_id"],
                    "type": "command",
                    "publishStatus": 1 if published else 0,
                },
            )
            self._ai_workbench_ack(payload, "AI command publish-status update")
        refreshed_commands, _ = self._ai_workbench_all_commands(context)
        refreshed = self._resolve_ai_workbench_command(refreshed_commands, selected["command_id"])
        if bool(refreshed["published"]) is not bool(published):
            raise ChaoxingAPIError("publish status did not match after refreshing the command")
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "command": refreshed,
            "internet_visible": bool(published),
            "verification": "command publish status matched after refresh",
        }

    def delete_ai_workbench_command(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        command: str,
        *,
        group: str = "",
    ) -> dict[str, Any]:
        context = self._ai_workbench_context(course, clazz)
        commands, _ = self._ai_workbench_all_commands(context, group=group)
        selected = self._resolve_ai_workbench_command(commands, command)
        if not selected["can_delete"]:
            raise ChaoxingAPIError("the selected system command cannot be deleted")
        payload = self._ai_workbench_json_request(
            context,
            "/course-ans/ai/delete-work-command",
            "AI command deletion",
            params={**context["common"], "dataId": selected["command_id"]},
        )
        self._ai_workbench_ack(payload, "AI command deletion")
        refreshed, _ = self._ai_workbench_all_commands(context)
        if any(item["command_id"] == selected["command_id"] for item in refreshed):
            raise ChaoxingAPIError("server acknowledged command deletion, but it is still visible")
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "deleted": selected,
            "verification": "command ID was absent from every refreshed group",
        }

    def delete_ai_workbench_group(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        group: str,
        *,
        allow_nonempty: bool = False,
    ) -> dict[str, Any]:
        context = self._ai_workbench_context(course, clazz)
        groups = self._ai_workbench_groups_from_context(context)
        selected = self._resolve_ai_workbench_group(groups, group)
        if selected["is_system"]:
            raise ChaoxingAPIError("the system command group cannot be deleted")
        contents = self._ai_workbench_commands_for_group(context, selected)["commands"]
        if contents and not allow_nonempty:
            raise ChaoxingAPIError(
                "AI command group is not empty; delete or move its commands first, "
                "or explicitly set allow_nonempty"
            )
        payload = self._ai_workbench_json_request(
            context,
            "/course-ans/ai/delete-command-group",
            "AI command group deletion",
            params={**context["common"], "groupId": selected["group_id"]},
        )
        self._ai_workbench_ack(payload, "AI command group deletion")
        refreshed = self._ai_workbench_groups_from_context(context)
        if any(item["group_id"] == selected["group_id"] for item in refreshed):
            raise ChaoxingAPIError("server acknowledged group deletion, but it is still visible")
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "deleted": selected,
            "deleted_command_count": len(contents),
            "verification": "group ID was absent from the refreshed workbench group list",
        }

    @classmethod
    def _normalize_ai_workbench_recommendation(
        cls,
        raw: dict[str, Any],
        index: int,
    ) -> dict[str, Any]:
        role_type = cls._ai_workbench_integer(raw.get("roleType"), 3)
        return {
            "index": index,
            "recommendation_id": str(raw.get("id") or ""),
            "open_id": str(raw.get("openId") or ""),
            "name": str(raw.get("name") or "").strip(),
            "content": str(raw.get("commandDesc") or "").strip(),
            "explanation": str(raw.get("commandExplain") or "").strip(),
            "prompt_words": str(raw.get("promptWords") or "").strip(),
            "classify_id": cls._ai_workbench_integer(raw.get("classifyId"), 0),
            "publish_status": cls._ai_workbench_integer(raw.get("publishStatus"), 0),
            "role_type": role_type,
            "role": cls._ai_workbench_role_label(role_type),
            "command_ability": cls._ai_workbench_integer(raw.get("commandAbility"), 0),
            "ability_type": cls._ai_workbench_integer(raw.get("abilityType"), 0),
        }

    def _ai_workbench_recommendations_page(
        self,
        context: dict[str, Any],
        page: int,
    ) -> dict[str, Any]:
        if page < 1:
            raise ChaoxingAPIError("page must be at least 1")
        payload = self._ai_workbench_json_request(
            context,
            "/course-ans/ai/recommendCommand",
            "AI command recommendations",
            method="POST",
            data={
                "courseid": context["common"]["courseId"],
                "clazzid": context["common"]["clazzId"],
                "cpi": context["common"]["cpi"],
                "pageNo": page,
            },
        )
        data = payload.get("data") if isinstance(payload.get("data"), dict) else {}
        raw_items = data.get("commandList") if isinstance(data.get("commandList"), list) else []
        items = [
            self._normalize_ai_workbench_recommendation(raw, index)
            for index, raw in enumerate(raw_items, 1)
            if isinstance(raw, dict) and str(raw.get("openId") or "")
        ]
        return {
            "page": page,
            "total_pages": max(1, self._ai_workbench_integer(data.get("totalPages"), 1)),
            "items": items,
        }

    def list_ai_workbench_recommendations(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        page: int = 1,
    ) -> dict[str, Any]:
        context = self._ai_workbench_context(course, clazz)
        listing = self._ai_workbench_recommendations_page(context, page)
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "page": listing["page"],
            "total_pages": listing["total_pages"],
            "count": len(listing["items"]),
            "recommendations": listing["items"],
            "verification": "recommendations read from the authenticated workbench API",
        }

    @staticmethod
    def _resolve_ai_workbench_recommendation(
        items: list[dict[str, Any]],
        query: str,
    ) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("AI command recommendation name or ID is required")
        for key in ("open_id", "recommendation_id", "name"):
            exact = [
                item for item in items if str(item.get(key) or "").strip().lower() == normalized
            ]
            if len(exact) == 1:
                return exact[0]
            if len(exact) > 1:
                options = ", ".join(
                    f"{item['name']} (open {item['open_id']})" for item in exact[:10]
                )
                raise ChaoxingAPIError(f"multiple AI recommendations match: {options}")
        partial = [item for item in items if normalized in str(item.get("name") or "").lower()]
        if len(partial) == 1:
            return partial[0]
        if not partial:
            raise ChaoxingAPIError(f"AI command recommendation not found: {query}")
        options = ", ".join(f"{item['name']} (open {item['open_id']})" for item in partial[:10])
        raise ChaoxingAPIError(f"multiple AI recommendations match: {options}")

    def add_ai_workbench_recommendation(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        recommendation: str,
        group: str,
    ) -> dict[str, Any]:
        context = self._ai_workbench_context(course, clazz)
        selected_group = self._resolve_ai_workbench_group(
            self._ai_workbench_groups_from_context(context), group
        )
        first_page = self._ai_workbench_recommendations_page(context, 1)
        recommendations = list(first_page["items"])
        if first_page["total_pages"] > 50:
            raise ChaoxingAPIError("recommendation page count exceeded the 50-page safety limit")
        for page in range(2, first_page["total_pages"] + 1):
            recommendations.extend(self._ai_workbench_recommendations_page(context, page)["items"])
        selected = self._resolve_ai_workbench_recommendation(recommendations, recommendation)
        before = self._ai_workbench_commands_for_group(context, selected_group)["commands"]
        payload = self._ai_workbench_json_request(
            context,
            "/course-ans/aiOpen/mappingAiOpenTarget",
            "AI command recommendation add",
            params={
                "type": "command",
                "courseId": context["common"]["courseId"],
                "cpi": context["common"]["cpi"],
                "commandGroupId": selected_group["group_id"],
                "id": selected["open_id"],
            },
        )
        self._ai_workbench_ack(payload, "AI command recommendation add")
        after = self._ai_workbench_commands_for_group(context, selected_group)["commands"]
        before_ids = {item["command_id"] for item in before}
        added = [item for item in after if item["command_id"] not in before_ids]
        matched = [
            item
            for item in added
            if item["mapping_id"] == self._ai_workbench_integer(selected["recommendation_id"])
            or item["name"] == selected["name"]
        ]
        if len(matched) != 1:
            raise ChaoxingAPIError(
                "server acknowledged recommendation add, but it was not uniquely visible"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "recommendation": selected,
            "command": matched[0],
            "verification": "a new mapped command appeared in the requested group",
        }

    @staticmethod
    def _task_engine_js_value(html: str, name: str, fallback: Any = None) -> Any:
        pattern = re.compile(
            rf"\b(?:const|let|var)\s+{re.escape(name)}\s*=\s*"
            r"(?:\"([^\"]*)\"|'([^']*)'|([^;\r\n]+))",
            flags=re.I,
        )
        match = pattern.search(html)
        if not match:
            return fallback
        raw = next((item for item in match.groups() if item is not None), "").strip()
        if raw in {"null", "undefined"}:
            return None
        if raw == "true":
            return True
        if raw == "false":
            return False
        if re.fullmatch(r"-?\d+", raw):
            return int(raw)
        return raw

    def _task_engine_context(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> dict[str, Any]:
        session = self._session()
        course_context = self._course_context(session, course, clazz)
        module = resolve_module(course_context["modules"], "任务引擎")
        request_url = self._module_url(course_context, module, course, clazz)
        try:
            response = session.get(
                request_url,
                timeout=self.timeout,
                allow_redirects=True,
                headers={"Referer": str(course_context["final_url"])},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"task-engine request failed: {exc}") from exc
        html = self._decode(response)
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError(f"task-engine request was redirected to login: {response.url}")
        common = {
            "course_id": str(
                self._task_engine_js_value(html, "courseId", course.get("course_id")) or ""
            ),
            "task_type": str(self._task_engine_js_value(html, "type", "course") or "course"),
            "school_id": self._task_engine_js_value(html, "belongschoolid"),
            "business_code": self._task_engine_js_value(html, "businessCode"),
            "folder_id": self._task_engine_js_value(html, "folderId"),
            "flag": self._task_engine_js_value(html, "flag", True),
            "encrypted_course_id": str(
                self._task_engine_js_value(html, "encryptedCourseId", "") or ""
            ),
            "encrypted_type": str(self._task_engine_js_value(html, "encryptedType", "") or ""),
        }
        if not common["course_id"]:
            raise ChaoxingAPIError("task-engine page omitted the course ID")
        return {
            "session": session,
            "root_url": response.url,
            "request_url": request_url,
            "course": course,
            "clazz": clazz,
            "common": common,
            "module": module,
        }

    def _task_engine_response(
        self,
        context: dict[str, Any],
        path: str,
        operation: str,
        *,
        method: str = "GET",
        params: dict[str, Any] | None = None,
        data: Any = None,
    ) -> requests.Response:
        url = urljoin(TASK_ENGINE_BASE_URL + "/", path.lstrip("/"))
        headers = {
            "Referer": str(context["root_url"]),
            "X-Requested-With": "XMLHttpRequest",
            "Accept": "application/json, text/plain, */*",
        }
        try:
            response = context["session"].request(
                method.upper(),
                url,
                params=params,
                json=data if method.upper() == "POST" else None,
                timeout=self.timeout,
                headers=headers,
                allow_redirects=True,
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"{operation} failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError(f"{operation} was redirected to login: {response.url}")
        return response

    def _task_engine_json_request(
        self,
        context: dict[str, Any],
        path: str,
        operation: str,
        *,
        method: str = "GET",
        params: dict[str, Any] | None = None,
        data: Any = None,
    ) -> Any:
        response = self._task_engine_response(
            context,
            path,
            operation,
            method=method,
            params=params,
            data=data,
        )
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError(f"{operation} returned invalid JSON") from exc
        if isinstance(payload, dict):
            if payload.get("result") is False or payload.get("success") is False:
                raise ChaoxingAPIError(
                    str(payload.get("message") or payload.get("msg") or f"{operation} was rejected")
                )
            if "code" in payload and self._ai_workbench_integer(payload.get("code"), -1) != 200:
                raise ChaoxingAPIError(
                    str(payload.get("message") or payload.get("msg") or f"{operation} was rejected")
                )
        return payload

    @staticmethod
    def _task_engine_ack(payload: Any, operation: str) -> dict[str, Any]:
        if not isinstance(payload, dict):
            raise ChaoxingAPIError(f"{operation} returned invalid JSON")
        if payload.get("code") != 200 or payload.get("result") is False:
            raise ChaoxingAPIError(
                str(payload.get("message") or payload.get("msg") or f"{operation} was rejected")
            )
        return payload

    @staticmethod
    def _normalize_task_engine_folder(raw: dict[str, Any]) -> dict[str, Any]:
        return {
            "folder_id": str(raw.get("id") or ""),
            "name": str(raw.get("name") or "").strip(),
            "task_count": ChaoxingAPI._ai_workbench_integer(raw.get("count"), 0),
            "sort": ChaoxingAPI._ai_workbench_integer(raw.get("sort"), -1),
        }

    @staticmethod
    def _normalize_task_engine_task(
        raw: dict[str, Any],
        *,
        folder_id: str | None,
        recycled: bool,
    ) -> dict[str, Any]:
        labels = raw.get("labelList") if isinstance(raw.get("labelList"), list) else []
        return {
            "task_id": str(raw.get("taskId") or ""),
            "name": str(raw.get("name") or "").strip(),
            "introduce": str(raw.get("introduce") or ""),
            "introduce_rich_text": str(raw.get("introduceRichText") or ""),
            "cover": str(raw.get("cover") or ""),
            "type": str(raw.get("type") or ""),
            "course_id": str(raw.get("courseId") or ""),
            "folder_id": folder_id,
            "labels": [
                {
                    "label_id": str(item.get("id") or ""),
                    "name": str(item.get("name") or ""),
                }
                for item in labels
                if isinstance(item, dict)
            ],
            "is_creator": bool(raw.get("isCreator")),
            "audit_status": bool(raw.get("auditStatus")),
            "audit_status_label": str(raw.get("auditStatusStr") or ""),
            "publish_status": bool(raw.get("publishStatus")),
            "task_point_count": ChaoxingAPI._ai_workbench_integer(raw.get("taskPointsNumber"), 0),
            "student_count": ChaoxingAPI._ai_workbench_integer(raw.get("taskStudentsNumber"), 0),
            "sort": ChaoxingAPI._ai_workbench_integer(raw.get("sort"), -1),
            "updated_at": str(raw.get("taskUpdateTime") or ""),
            "finish_commit": bool(raw.get("isFinishCommit")),
            "recycled": recycled,
            "support_ai_check": bool(raw.get("supportChaoDunAICheck")),
            "support_form_audit": bool(raw.get("supportFormAuditCheck")),
        }

    def _task_engine_folders_from_context(self, context: dict[str, Any]) -> list[dict[str, Any]]:
        common = context["common"]
        payload = self._task_engine_json_request(
            context,
            "/task/findTaskFolders",
            "task-engine folder list",
            method="POST",
            data={
                "type": common["task_type"],
                "courseId": common["course_id"],
                "folderId": None,
                "businessCode": common["business_code"],
            },
        )
        self._task_engine_ack(payload, "task-engine folder list")
        rows = payload.get("data") if isinstance(payload.get("data"), list) else []
        return [
            self._normalize_task_engine_folder(item)
            for item in rows
            if isinstance(item, dict) and str(item.get("id") or "")
        ]

    def _task_engine_tasks_from_context(
        self,
        context: dict[str, Any],
        *,
        folder_id: str | None = None,
        search: str = "",
        recycled: bool = False,
        max_items: int = 1000,
    ) -> list[dict[str, Any]]:
        if max_items < 1 or max_items > 10_000:
            raise ChaoxingAPIError("max_items must be between 1 and 10000")
        common = context["common"]
        tasks: list[dict[str, Any]] = []
        page = 1
        page_size = min(100, max_items)
        while len(tasks) < max_items:
            payload = self._task_engine_json_request(
                context,
                "/task/getTaskDataLists",
                "task-engine task list",
                params={
                    "searchKey": str(search or "").strip(),
                    "flag": str(bool(common["flag"])).lower(),
                    "courseId": common["course_id"],
                    "isDel": 1 if recycled else 0,
                    "businessCode": common["business_code"],
                    "folderId": folder_id,
                    "page": page,
                    "pageSize": page_size,
                },
            )
            self._task_engine_ack(payload, "task-engine task list")
            rows = payload.get("data") if isinstance(payload.get("data"), list) else []
            tasks.extend(
                self._normalize_task_engine_task(
                    item,
                    folder_id=folder_id,
                    recycled=recycled,
                )
                for item in rows
                if isinstance(item, dict) and str(item.get("taskId") or "")
            )
            total = self._ai_workbench_integer(payload.get("total"), len(tasks))
            if not rows or len(tasks) >= total:
                break
            page += 1
            if page > 100:
                raise ChaoxingAPIError("task-engine task list exceeded 100 pages")
        return tasks[:max_items]

    @staticmethod
    def _resolve_task_engine_folder(folders: list[dict[str, Any]], query: str) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("task-engine folder name or ID is required")
        exact = [
            item
            for item in folders
            if str(item.get("folder_id") or "").lower() == normalized
            or str(item.get("name") or "").strip().lower() == normalized
        ]
        if len(exact) == 1:
            return exact[0]
        partial = [item for item in folders if normalized in str(item.get("name") or "").lower()]
        if len(partial) == 1:
            return partial[0]
        if not partial:
            raise ChaoxingAPIError(f"task-engine folder not found: {query}")
        options = ", ".join(f"{item['name']} ({item['folder_id']})" for item in partial[:10])
        raise ChaoxingAPIError(f"multiple task-engine folders match: {options}")

    @staticmethod
    def _resolve_task_engine_task(tasks: list[dict[str, Any]], query: str) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("task-engine task name or ID is required")
        exact = [
            item
            for item in tasks
            if str(item.get("task_id") or "").lower() == normalized
            or str(item.get("name") or "").strip().lower() == normalized
        ]
        if len(exact) == 1:
            return exact[0]
        if len(exact) > 1:
            options = ", ".join(f"{item['name']} ({item['task_id']})" for item in exact[:10])
            raise ChaoxingAPIError(f"multiple task-engine tasks match: {options}")
        partial = [item for item in tasks if normalized in str(item.get("name") or "").lower()]
        if len(partial) == 1:
            return partial[0]
        if not partial:
            raise ChaoxingAPIError(f"task-engine task not found: {query}")
        options = ", ".join(f"{item['name']} ({item['task_id']})" for item in partial[:10])
        raise ChaoxingAPIError(f"multiple task-engine tasks match: {options}")

    def _task_engine_all_tasks(
        self,
        context: dict[str, Any],
        *,
        search: str = "",
        max_items: int = 1000,
    ) -> list[dict[str, Any]]:
        folders = self._task_engine_folders_from_context(context)
        tasks = self._task_engine_tasks_from_context(
            context,
            search=search,
            max_items=max_items,
        )
        for folder in folders:
            if len(tasks) >= max_items:
                break
            tasks.extend(
                self._task_engine_tasks_from_context(
                    context,
                    folder_id=folder["folder_id"],
                    search=search,
                    max_items=max_items - len(tasks),
                )
            )
        return tasks[:max_items]

    def list_task_engine_folders(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> dict[str, Any]:
        context = self._task_engine_context(course, clazz)
        folders = self._task_engine_folders_from_context(context)
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "count": len(folders),
            "folders": folders,
            "verification": "folders read from the authenticated task-engine API",
        }

    def list_task_engine_tasks(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        folder: str = "",
        search: str = "",
        recycled: bool = False,
        max_items: int = 1000,
    ) -> dict[str, Any]:
        context = self._task_engine_context(course, clazz)
        selected_folder: dict[str, Any] | None = None
        folder_id: str | None = None
        if folder:
            selected_folder = self._resolve_task_engine_folder(
                self._task_engine_folders_from_context(context), folder
            )
            folder_id = selected_folder["folder_id"]
        tasks = self._task_engine_tasks_from_context(
            context,
            folder_id=folder_id,
            search=search,
            recycled=recycled,
            max_items=max_items,
        )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "folder": selected_folder,
            "recycled": recycled,
            "search": str(search or "").strip(),
            "count": len(tasks),
            "tasks": tasks,
            "verification": "tasks read from the authenticated task-engine API",
        }

    @staticmethod
    def _normalize_task_engine_point(raw: dict[str, Any]) -> dict[str, Any]:
        return {
            "point_id": str(raw.get("id") or ""),
            "encrypted_point_id": str(raw.get("encryPlanDataId") or ""),
            "type": ChaoxingAPI._ai_workbench_integer(raw.get("type"), -1),
            "type_label": str(raw.get("planTypeTitle") or raw.get("customTypeName") or ""),
            "name": str(raw.get("name") or ""),
            "description": str(raw.get("desc") or ""),
            "external_data_id": str(raw.get("externalDataId") or ""),
            "encrypted_external_data_id": str(raw.get("encryExternalDataId") or ""),
            "associated_external_data_id": str(raw.get("associatedExternalDataId") or ""),
            "image_url": str(raw.get("imageUrl") or ""),
            "sort": ChaoxingAPI._ai_workbench_integer(raw.get("sort"), -1),
            "start_date": raw.get("startDateStr") or raw.get("startDate"),
            "end_date": raw.get("endDateStr") or raw.get("endDate"),
            "locked": bool(raw.get("lock")),
            "lock_condition": str(raw.get("lockCondition") or ""),
            "previous_lock_condition": str(raw.get("lastLockCondition") or ""),
            "have_permission": bool(raw.get("haveTaskPermission")),
            "chapter_permission": bool(raw.get("chapterPermission")),
            "url": str(raw.get("url") or raw.get("formUrl") or ""),
            "labels": [str(item) for item in raw.get("planLabelNameList", [])],
        }

    def _task_engine_task_data(
        self,
        context: dict[str, Any],
        task_id: str,
    ) -> dict[str, Any]:
        payload = self._task_engine_json_request(
            context,
            "/task/onMountGetTaskData",
            "task-engine task read",
            params={"taskId": task_id},
        )
        self._task_engine_ack(payload, "task-engine task read")
        data = payload.get("data")
        if not isinstance(data, dict) or str(data.get("taskId") or "") != task_id:
            raise ChaoxingAPIError("task-engine task read omitted the requested task")
        if str(data.get("courseId") or "") != str(context["common"]["course_id"]):
            raise ChaoxingAPIError("task-engine task belongs to a different course")
        return data

    def read_task_engine_task(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        task: str,
    ) -> dict[str, Any]:
        context = self._task_engine_context(course, clazz)
        selected = self._resolve_task_engine_task(self._task_engine_all_tasks(context), task)
        data = self._task_engine_task_data(context, selected["task_id"])
        groups: list[dict[str, Any]] = []
        for raw_group in data.get("groups", []):
            if not isinstance(raw_group, dict):
                continue
            points = [
                self._normalize_task_engine_point(item)
                for item in raw_group.get("detail", [])
                if isinstance(item, dict)
            ]
            groups.append(
                {
                    "group_id": str(raw_group.get("id") or ""),
                    "encrypted_group_id": str(raw_group.get("encryGroupDataId") or ""),
                    "name": str(raw_group.get("name") or ""),
                    "description": str(raw_group.get("desc") or ""),
                    "sort": self._ai_workbench_integer(raw_group.get("sort"), -1),
                    "point_count": len(points),
                    "points": points,
                }
            )
        labels = data.get("taskLabelList") if isinstance(data.get("taskLabelList"), list) else []
        result = {
            **selected,
            "name": str(data.get("name") or ""),
            "introduce": str(data.get("introduce") or ""),
            "introduce_rich_text": str(data.get("introduceRichText") or ""),
            "cover": str(data.get("cover") or ""),
            "target": str(data.get("target") or ""),
            "start_date": data.get("startDateStr") or data.get("startDate"),
            "end_date": data.get("endDateStr") or data.get("endDate"),
            "mode": str(data.get("mode") or "list"),
            "mode_id": data.get("modeId"),
            "selected_modes": list(data.get("selectedModes") or ["list"]),
            "publish_status": bool(data.get("publishStatus")),
            "finish_commit": bool(data.get("finishCommit")),
            "task_commit_enabled": bool(data.get("taskCommitFlag")),
            "is_creator": bool(data.get("isCreator")),
            "is_together_user": bool(data.get("isTogetherUser")),
            "audit_status": bool(data.get("auditStatus")),
            "audit_status_label": str(data.get("auditStatusStr") or ""),
            "already_published": bool(data.get("alreadyPublished")),
            "task_point_count": self._ai_workbench_integer(data.get("taskPointsNumber"), 0),
            "labels": [
                {
                    "label_id": str(item.get("id") or ""),
                    "name": str(item.get("name") or ""),
                    "allow_delete": bool(item.get("allowDelete")),
                }
                for item in labels
                if isinstance(item, dict)
            ],
            "target_list": list(data.get("targetList") or []),
            "support": {
                "associated_target": bool(data.get("supportAssociatedTarget")),
                "ai_check": bool(data.get("supportChaoDunAICheck")),
                "form_audit": bool(data.get("supportFormAuditCheck")),
                "task_template": bool(data.get("supportTaskTemplate")),
                "new_offline_classroom": bool(data.get("supportNewOfflineClassRoom")),
                "class_schedule": bool(data.get("supportUseClassSchedule")),
                "select_course": bool(data.get("supportSelectCourse")),
            },
            "group_count": len(groups),
            "groups": groups,
        }
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "task": result,
            "verification": "task base information and points were refreshed from task engine",
        }

    @staticmethod
    def _validate_task_engine_name(name: str) -> str:
        normalized = str(name or "").strip()
        if not 1 <= len(normalized) <= 100:
            raise ChaoxingAPIError("task-engine task name must contain 1-100 characters")
        return normalized

    @staticmethod
    def _validate_task_engine_folder_name(name: str) -> str:
        normalized = str(name or "").strip()
        if not 1 <= len(normalized) <= 100:
            raise ChaoxingAPIError("task-engine folder name must contain 1-100 characters")
        return normalized

    @staticmethod
    def _task_engine_encode_rich_text(value: str) -> str:
        return quote(str(value or "").replace("%", "##PERCENT##"), safe="~()*!.'-")

    def _task_engine_commit_payload(self, data: dict[str, Any]) -> dict[str, Any]:
        fields = (
            "taskId",
            "coverStyleId",
            "cover",
            "target",
            "taskPointsNumber",
            "isTogetherUser",
            "mode",
            "modeId",
            "startDate",
            "endDate",
            "selectedModes",
            "type",
            "courseId",
            "schoolId",
            "publishStatus",
            "supportAssociatedTarget",
            "supportChaoDunAICheck",
            "supportFormAuditCheck",
            "supportTaskTemplate",
            "supportNewOfflineClassRoom",
            "supportUseClassSchedule",
            "supportSelectCourse",
            "classId",
            "auditStatus",
            "alreadyPublished",
            "isCreator",
            "auditStatusStr",
            "businessCode",
            "targetList",
            "templateTaskId",
            "syncTaskPointInfo",
            "studyModePreviewUrl",
            "studyModeObjectId",
            "mapFrameUrl",
            "mapKnowledgeUrl",
        )
        payload = {key: data.get(key) for key in fields}
        payload.update(
            {
                "name": self._validate_task_engine_name(str(data.get("name") or "")),
                "introduce": str(data.get("introduce") or ""),
                "introduceRichText": self._task_engine_encode_rich_text(
                    str(data.get("introduceRichText") or "")
                ),
                "descTextType": self._ai_workbench_integer(data.get("descTextType"), 0),
                "descTemplateId": self._ai_workbench_integer(data.get("descTemplateId"), 1),
                "targetTextType": self._ai_workbench_integer(data.get("targetTextType"), 0),
                "targetTemplateId": self._ai_workbench_integer(data.get("targetTemplateId"), 1),
                "delivery": bool(data.get("delivery")),
                "labelList": list(data.get("taskLabelList") or data.get("labelList") or []),
            }
        )
        selected_modes = [str(item) for item in payload.get("selectedModes") or ["list"]]
        if "list" not in selected_modes or any(
            item not in {"list", "frame", "knowledge"} for item in selected_modes
        ):
            raise ChaoxingAPIError(
                "selected_modes must contain list and may additionally contain frame or knowledge"
            )
        payload["selectedModes"] = list(dict.fromkeys(selected_modes))
        if len(payload["introduce"]) > 500:
            raise ChaoxingAPIError("task-engine introduction must not exceed 500 characters")
        return payload

    def _commit_task_engine_task(
        self,
        context: dict[str, Any],
        data: dict[str, Any],
        operation: str,
    ) -> str:
        payload = self._task_engine_json_request(
            context,
            "/task/taskCommit",
            operation,
            method="POST",
            data=self._task_engine_commit_payload(data),
        )
        self._task_engine_ack(payload, operation)
        task_id = str(payload.get("data") or data.get("taskId") or "")
        if not task_id:
            raise ChaoxingAPIError(f"{operation} omitted the task ID")
        return task_id

    def create_task_engine_folder(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        name: str,
    ) -> dict[str, Any]:
        normalized_name = self._validate_task_engine_folder_name(name)
        context = self._task_engine_context(course, clazz)
        before = self._task_engine_folders_from_context(context)
        if any(item["name"] == normalized_name for item in before):
            raise ChaoxingAPIError(f"task-engine folder already exists: {normalized_name}")
        common = context["common"]
        payload = self._task_engine_json_request(
            context,
            "/task/addNewFolder",
            "task-engine folder create",
            method="POST",
            data={
                "name": normalized_name,
                "type": common["task_type"],
                "courseId": common["course_id"],
                "businessCode": common["business_code"],
            },
        )
        self._task_engine_ack(payload, "task-engine folder create")
        folder_id = str((payload.get("data") or {}).get("id") or "")
        after = self._task_engine_folders_from_context(context)
        matches = [
            item
            for item in after
            if item["folder_id"] == folder_id and item["name"] == normalized_name
        ]
        if len(matches) != 1:
            raise ChaoxingAPIError(
                "server acknowledged folder creation, but the new folder was not uniquely visible"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "folder": matches[0],
            "verification": "the new folder appeared in the refreshed folder list",
        }

    def rename_task_engine_folder(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        folder: str,
        name: str,
    ) -> dict[str, Any]:
        normalized_name = self._validate_task_engine_folder_name(name)
        context = self._task_engine_context(course, clazz)
        folders = self._task_engine_folders_from_context(context)
        selected = self._resolve_task_engine_folder(folders, folder)
        duplicates = [
            item
            for item in folders
            if item["folder_id"] != selected["folder_id"] and item["name"] == normalized_name
        ]
        if duplicates:
            raise ChaoxingAPIError(f"task-engine folder already exists: {normalized_name}")
        common = context["common"]
        payload = self._task_engine_json_request(
            context,
            "/task/reNameFolderConfirm",
            "task-engine folder rename",
            method="POST",
            data={
                "name": normalized_name,
                "type": common["task_type"],
                "courseId": common["course_id"],
                "businessCode": common["business_code"],
                "folderId": selected["folder_id"],
            },
        )
        self._task_engine_ack(payload, "task-engine folder rename")
        updated = self._resolve_task_engine_folder(
            self._task_engine_folders_from_context(context), selected["folder_id"]
        )
        if updated["name"] != normalized_name:
            raise ChaoxingAPIError(
                "server acknowledged folder rename, but the refreshed name did not change"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "before": selected,
            "folder": updated,
            "verification": "the refreshed folder has the requested name",
        }

    def delete_task_engine_folder(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        folder: str,
        *,
        allow_nonempty: bool = False,
    ) -> dict[str, Any]:
        context = self._task_engine_context(course, clazz)
        selected = self._resolve_task_engine_folder(
            self._task_engine_folders_from_context(context), folder
        )
        contained = self._task_engine_tasks_from_context(context, folder_id=selected["folder_id"])
        if contained and not allow_nonempty:
            raise ChaoxingAPIError(
                "task-engine folder is not empty; set allow_nonempty=true to move its tasks to root"
            )
        payload = self._task_engine_json_request(
            context,
            "/task/removeFolderConfirm",
            "task-engine folder delete",
            method="POST",
            data={"folderId": selected["folder_id"]},
        )
        self._task_engine_ack(payload, "task-engine folder delete")
        folders_after = self._task_engine_folders_from_context(context)
        if any(item["folder_id"] == selected["folder_id"] for item in folders_after):
            raise ChaoxingAPIError(
                "server acknowledged folder deletion, but the folder is still visible"
            )
        root_after = self._task_engine_tasks_from_context(context)
        missing = [
            item["task_id"]
            for item in contained
            if not any(root["task_id"] == item["task_id"] for root in root_after)
        ]
        if missing:
            raise ChaoxingAPIError(
                "folder was deleted, but one or more contained tasks were not visible at root"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "deleted_folder": selected,
            "moved_task_count": len(contained),
            "moved_tasks": contained,
            "verification": "folder disappeared and all contained tasks are visible at root",
        }

    def create_task_engine_task(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        name: str,
        *,
        introduce: str = "",
        rich_text: str = "",
        cover: str = "",
        target: str = "",
        folder: str = "",
        selected_modes: list[str] | None = None,
    ) -> dict[str, Any]:
        normalized_name = self._validate_task_engine_name(name)
        if len(str(introduce or "")) > 500:
            raise ChaoxingAPIError("task-engine introduction must not exceed 500 characters")
        context = self._task_engine_context(course, clazz)
        common = context["common"]
        if not common["encrypted_course_id"] or not common["encrypted_type"]:
            raise ChaoxingAPIError("task-engine page omitted encrypted creation identifiers")
        folder_id: str | None = None
        selected_folder: dict[str, Any] | None = None
        if folder:
            selected_folder = self._resolve_task_engine_folder(
                self._task_engine_folders_from_context(context), folder
            )
            folder_id = selected_folder["folder_id"]
        payload = self._task_engine_json_request(
            context,
            "/task/createTask",
            "task-engine task allocate",
            params={
                "encryptedCourseId": common["encrypted_course_id"],
                "encryptedType": common["encrypted_type"],
                "businessCode": common["business_code"],
                "folderId": folder_id,
            },
        )
        self._task_engine_ack(payload, "task-engine task allocate")
        allocation = payload.get("data") if isinstance(payload.get("data"), dict) else {}
        task_id = str(allocation.get("encryTaskId") or "")
        if not task_id:
            raise ChaoxingAPIError("task-engine allocation omitted the task ID")
        data = self._task_engine_task_data(context, task_id)
        data.update(
            {
                "name": normalized_name,
                "introduce": str(introduce or ""),
                "introduceRichText": str(rich_text or "")
                or (f"<div>{escape(str(introduce or ''))}</div>" if introduce else ""),
                "cover": str(cover or data.get("cover") or ""),
                "target": str(target or ""),
                "selectedModes": selected_modes or ["list"],
            }
        )
        committed_id = self._commit_task_engine_task(context, data, "task-engine task create")
        tasks_after = self._task_engine_all_tasks(context)
        created = [item for item in tasks_after if item["task_id"] == committed_id]
        if len(created) != 1 or created[0]["name"] != normalized_name:
            raise ChaoxingAPIError(
                "server acknowledged task creation, but the task was not uniquely visible"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "folder": selected_folder,
            "task": created[0],
            "verification": "the committed task appeared in the refreshed task tree",
        }

    def update_task_engine_task(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        task: str,
        *,
        name: str | None = None,
        introduce: str | None = None,
        rich_text: str | None = None,
        cover: str | None = None,
        target: str | None = None,
        start_date: Any = None,
        end_date: Any = None,
        selected_modes: list[str] | None = None,
    ) -> dict[str, Any]:
        context = self._task_engine_context(course, clazz)
        selected = self._resolve_task_engine_task(self._task_engine_all_tasks(context), task)
        data = self._task_engine_task_data(context, selected["task_id"])
        if data.get("auditStatus") and str(data.get("auditStatusStr") or "") == "审核中":
            raise ChaoxingAPIError("task-engine task is under audit and cannot be edited")
        if name is not None:
            data["name"] = self._validate_task_engine_name(name)
        if introduce is not None:
            if len(str(introduce)) > 500:
                raise ChaoxingAPIError("task-engine introduction must not exceed 500 characters")
            data["introduce"] = str(introduce)
            if rich_text is None:
                data["introduceRichText"] = (
                    f"<div>{escape(str(introduce))}</div>" if introduce else ""
                )
        if rich_text is not None:
            data["introduceRichText"] = str(rich_text)
        if cover is not None:
            data["cover"] = str(cover)
        if target is not None:
            data["target"] = str(target)
        if start_date is not None:
            data["startDate"] = start_date
        if end_date is not None:
            data["endDate"] = end_date
        if selected_modes is not None:
            data["selectedModes"] = selected_modes
        task_id = self._commit_task_engine_task(context, data, "task-engine task update")
        refreshed = self._task_engine_task_data(context, task_id)
        checks = {
            "name": name,
            "introduce": introduce,
            "introduceRichText": rich_text,
            "cover": cover,
            "target": target,
        }
        for key, expected in checks.items():
            if expected is not None and str(refreshed.get(key) or "") != str(expected):
                raise ChaoxingAPIError(
                    f"server acknowledged task update, but refreshed {key} did not match"
                )
        if selected_modes is not None and list(refreshed.get("selectedModes") or []) != list(
            dict.fromkeys(selected_modes)
        ):
            raise ChaoxingAPIError(
                "server acknowledged task update, but refreshed selected modes did not match"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "task_id": task_id,
            "name": str(refreshed.get("name") or ""),
            "introduce": str(refreshed.get("introduce") or ""),
            "introduce_rich_text": str(refreshed.get("introduceRichText") or ""),
            "cover": str(refreshed.get("cover") or ""),
            "target": str(refreshed.get("target") or ""),
            "selected_modes": list(refreshed.get("selectedModes") or []),
            "verification": "requested fields match the refreshed task data",
        }

    def move_task_engine_task(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        task: str,
        *,
        folder: str = "",
    ) -> dict[str, Any]:
        context = self._task_engine_context(course, clazz)
        tasks = self._task_engine_all_tasks(context)
        selected = self._resolve_task_engine_task(tasks, task)
        target: dict[str, Any] | None = None
        target_id = "0"
        if folder and str(folder).strip().lower() not in {"0", "root", "根目录"}:
            target = self._resolve_task_engine_folder(
                self._task_engine_folders_from_context(context), folder
            )
            target_id = target["folder_id"]
        common = context["common"]
        payload = self._task_engine_json_request(
            context,
            "/task/taskMoveToFolder",
            "task-engine task move",
            method="POST",
            data={
                "type": common["task_type"],
                "courseId": common["course_id"],
                "encryptedTaskId": selected["task_id"],
                "folderId": target_id,
                "businessCode": common["business_code"],
            },
        )
        self._task_engine_ack(payload, "task-engine task move")
        destination = self._task_engine_tasks_from_context(
            context, folder_id=target["folder_id"] if target else None
        )
        matches = [item for item in destination if item["task_id"] == selected["task_id"]]
        if len(matches) != 1:
            raise ChaoxingAPIError(
                "server acknowledged task move, but the task is not visible at the destination"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "task": matches[0],
            "folder": target,
            "verification": "the task is visible in the refreshed destination",
        }

    def reorder_task_engine_items(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        task_order: list[str],
        folder_order: list[str] | None = None,
        folder: str = "",
    ) -> dict[str, Any]:
        context = self._task_engine_context(course, clazz)
        folders = self._task_engine_folders_from_context(context)
        selected_folder: dict[str, Any] | None = None
        folder_id: str | None = None
        if folder:
            selected_folder = self._resolve_task_engine_folder(folders, folder)
            folder_id = selected_folder["folder_id"]
        current_tasks = self._task_engine_tasks_from_context(context, folder_id=folder_id)
        resolved_tasks = [
            self._resolve_task_engine_task(current_tasks, item) for item in task_order
        ]
        if len({item["task_id"] for item in resolved_tasks}) != len(resolved_tasks):
            raise ChaoxingAPIError("task_order contains duplicate tasks")
        if {item["task_id"] for item in resolved_tasks} != {
            item["task_id"] for item in current_tasks
        }:
            raise ChaoxingAPIError("task_order must contain every task in the selected folder once")
        resolved_folders: list[dict[str, Any]] = []
        if selected_folder is not None:
            if folder_order:
                raise ChaoxingAPIError("folder_order is only valid at task-engine root")
        else:
            requested_folders = list(folder_order or [])
            resolved_folders = [
                self._resolve_task_engine_folder(folders, item) for item in requested_folders
            ]
            if len({item["folder_id"] for item in resolved_folders}) != len(resolved_folders):
                raise ChaoxingAPIError("folder_order contains duplicate folders")
            if {item["folder_id"] for item in resolved_folders} != {
                item["folder_id"] for item in folders
            }:
                raise ChaoxingAPIError("folder_order must contain every root folder once")
        order_payload = [
            {"encryptTaskId": item["folder_id"], "sort": index, "status": 1}
            for index, item in enumerate(resolved_folders)
        ] + [
            {"encryptTaskId": item["task_id"], "sort": index, "status": 2}
            for index, item in enumerate(resolved_tasks)
        ]
        common = context["common"]
        payload = self._task_engine_json_request(
            context,
            "/task/swapTaskOrder",
            "task-engine item reorder",
            method="POST",
            params={
                "folderId": folder_id or "0",
                "taskType": common["task_type"],
                "courseId": common["course_id"],
                "businessCode": common["business_code"],
            },
            data=order_payload,
        )
        self._task_engine_ack(payload, "task-engine item reorder")
        tasks_after = self._task_engine_tasks_from_context(context, folder_id=folder_id)
        folders_after = self._task_engine_folders_from_context(context) if folder_id is None else []
        expected_task_ids = [item["task_id"] for item in resolved_tasks]
        actual_task_ids = [item["task_id"] for item in tasks_after]
        expected_folder_ids = [item["folder_id"] for item in resolved_folders]
        actual_folder_ids = [item["folder_id"] for item in folders_after]
        if actual_task_ids != expected_task_ids or actual_folder_ids != expected_folder_ids:
            raise ChaoxingAPIError(
                "server acknowledged item reorder, but the refreshed order did not match"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "folder": selected_folder,
            "folder_order": folders_after,
            "task_order": tasks_after,
            "verification": "refreshed folder and task orders match the complete requested orders",
        }

    def copy_task_engine_task(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        task: str,
        *,
        name: str = "",
        folder: str = "",
    ) -> dict[str, Any]:
        if name:
            self._validate_task_engine_name(name)
        context = self._task_engine_context(course, clazz)
        before = self._task_engine_all_tasks(context)
        selected = self._resolve_task_engine_task(before, task)
        payload = self._task_engine_json_request(
            context,
            "/task/confirmCourseCopyTask",
            "task-engine task copy",
            params={"taskId": selected["task_id"]},
        )
        self._task_engine_ack(payload, "task-engine task copy")
        before_ids = {item["task_id"] for item in before}
        created: list[dict[str, Any]] = []
        for _ in range(5):
            after = self._task_engine_all_tasks(context)
            created = [item for item in after if item["task_id"] not in before_ids]
            if created:
                break
            sleep(0.25)
        if len(created) != 1:
            raise ChaoxingAPIError(
                "server acknowledged task copy, but one new copy was not uniquely visible"
            )
        copied = created[0]
        if name:
            self.update_task_engine_task(course, clazz, copied["task_id"], name=name)
        if folder:
            self.move_task_engine_task(course, clazz, copied["task_id"], folder=folder)
        refreshed = self._resolve_task_engine_task(
            self._task_engine_all_tasks(context), copied["task_id"]
        )
        if name and refreshed["name"] != name.strip():
            raise ChaoxingAPIError("copied task did not retain the requested name")
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "source": selected,
            "task": refreshed,
            "verification": "one new copied task is visible after optional rename and move",
        }

    def delete_task_engine_task(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        task: str,
    ) -> dict[str, Any]:
        context = self._task_engine_context(course, clazz)
        selected = self._resolve_task_engine_task(self._task_engine_all_tasks(context), task)
        permission = self._task_engine_json_request(
            context,
            "/task/removeTaskPermissionValidate",
            "task-engine task delete permission check",
            params={"encryptedId": selected["task_id"]},
        )
        self._task_engine_ack(permission, "task-engine task delete permission check")
        if not permission.get("data"):
            raise ChaoxingAPIError("current account is not allowed to delete this task-engine task")
        payload = self._task_engine_json_request(
            context,
            "/task/deleteTaskInfo",
            "task-engine task delete",
            params={"taskId": selected["task_id"]},
        )
        self._task_engine_ack(payload, "task-engine task delete")
        active_after: list[dict[str, Any]] = []
        matches: list[dict[str, Any]] = []
        for attempt in range(5):
            active_after = self._task_engine_all_tasks(context)
            recycle_after = self._task_engine_tasks_from_context(context, recycled=True)
            matches = [item for item in recycle_after if item["task_id"] == selected["task_id"]]
            if (
                not any(item["task_id"] == selected["task_id"] for item in active_after)
                and len(matches) == 1
            ):
                break
            if attempt < 4:
                sleep(0.2)
        if any(item["task_id"] == selected["task_id"] for item in active_after):
            raise ChaoxingAPIError(
                "server acknowledged task deletion, but the task is still active"
            )
        if len(matches) != 1:
            raise ChaoxingAPIError(
                "server acknowledged task deletion, but the task is not visible in recycle"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "task": matches[0],
            "verification": "task disappeared from active items and appeared in recycle",
        }

    def list_task_engine_recycle(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        search: str = "",
        max_items: int = 1000,
    ) -> dict[str, Any]:
        context = self._task_engine_context(course, clazz)
        tasks = self._task_engine_tasks_from_context(
            context,
            search=search,
            recycled=True,
            max_items=max_items,
        )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "search": str(search or "").strip(),
            "count": len(tasks),
            "tasks": tasks,
            "verification": "recycled tasks read from the authenticated task-engine API",
        }

    def restore_task_engine_task(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        task: str,
    ) -> dict[str, Any]:
        context = self._task_engine_context(course, clazz)
        recycled = self._task_engine_tasks_from_context(context, recycled=True)
        selected = self._resolve_task_engine_task(recycled, task)
        payload = self._task_engine_json_request(
            context,
            "/task/recoverTaskInfo",
            "task-engine task restore",
            params={"taskId": selected["task_id"]},
        )
        self._task_engine_ack(payload, "task-engine task restore")
        active_after = self._task_engine_all_tasks(context)
        recycle_after = self._task_engine_tasks_from_context(context, recycled=True)
        matches = [item for item in active_after if item["task_id"] == selected["task_id"]]
        if len(matches) != 1 or any(
            item["task_id"] == selected["task_id"] for item in recycle_after
        ):
            raise ChaoxingAPIError(
                "server acknowledged task restore, but active and recycle states did not refresh"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "task": matches[0],
            "verification": "task appeared in active items and disappeared from recycle",
        }

    @staticmethod
    def _normalize_task_engine_label(raw: dict[str, Any]) -> dict[str, Any]:
        return {
            "label_id": str(raw.get("id") or ""),
            "name": str(raw.get("name") or "").strip(),
            "operator_user_id": str(raw.get("operatorUserId") or ""),
            "allow_delete": bool(raw.get("allowDelete")),
            "selected": bool(raw.get("isChoose")),
            "created_at": str(raw.get("createDate") or ""),
            "updated_at": str(raw.get("updateDate") or ""),
        }

    def _task_engine_labels_from_context(
        self,
        context: dict[str, Any],
        task: dict[str, Any],
        *,
        search: str = "",
    ) -> list[dict[str, Any]]:
        payload = self._task_engine_json_request(
            context,
            "/tasklabel/getTaskLabelDatas",
            "task-engine label list",
            params={
                "encryptId": task["task_id"],
                "labelName": str(search or ""),
                "isWordQuery": str(bool(search)).lower(),
                "taskName": task["name"],
            },
        )
        if not isinstance(payload, list):
            raise ChaoxingAPIError("task-engine label list returned invalid JSON")
        labels = [
            self._normalize_task_engine_label(item)
            for item in payload
            if isinstance(item, dict) and str(item.get("id") or "")
        ]
        unique: dict[str, dict[str, Any]] = {}
        for item in labels:
            unique[item["label_id"]] = item
        return list(unique.values())

    def list_task_engine_labels(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        task: str = "",
        search: str = "",
    ) -> dict[str, Any]:
        context = self._task_engine_context(course, clazz)
        tasks = self._task_engine_all_tasks(context)
        if not tasks:
            raise ChaoxingAPIError("task-engine labels require at least one committed task")
        selected = self._resolve_task_engine_task(tasks, task) if task else tasks[0]
        labels = self._task_engine_labels_from_context(context, selected, search=search)
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "task": selected,
            "search": str(search or ""),
            "count": len(labels),
            "labels": labels,
            "verification": "labels read through the selected task's authenticated label API",
        }

    def create_task_engine_label(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        name: str,
        *,
        task: str = "",
    ) -> dict[str, Any]:
        normalized_name = str(name or "").strip()
        if not 1 <= len(normalized_name) <= 100:
            raise ChaoxingAPIError("task-engine label name must contain 1-100 characters")
        context = self._task_engine_context(course, clazz)
        tasks = self._task_engine_all_tasks(context)
        if not tasks:
            raise ChaoxingAPIError("task-engine labels require at least one committed task")
        selected_task = self._resolve_task_engine_task(tasks, task) if task else tasks[0]
        payload = self._task_engine_json_request(
            context,
            "/tasklabel/saveOrDeleteTaskLabelData",
            "task-engine label create",
            method="POST",
            data={"name": normalized_name, "isAdd": True},
        )
        self._task_engine_ack(payload, "task-engine label create")
        label_id = str((payload.get("data") or {}).get("id") or "")
        labels = self._task_engine_labels_from_context(
            context, selected_task, search=normalized_name
        )
        matches = [
            item
            for item in labels
            if item["label_id"] == label_id and item["name"] == normalized_name
        ]
        if len(matches) != 1:
            raise ChaoxingAPIError(
                "server acknowledged label creation, but the label was not uniquely visible"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "label": matches[0],
            "verification": "the new label appeared in a refreshed exact-name search",
        }

    def _resolve_task_engine_label(
        self,
        labels: list[dict[str, Any]],
        query: str,
    ) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("task-engine label name or ID is required")
        exact = [
            item
            for item in labels
            if item["label_id"].lower() == normalized or item["name"].lower() == normalized
        ]
        if len(exact) == 1:
            return exact[0]
        partial = [item for item in labels if normalized in item["name"].lower()]
        if len(partial) == 1:
            return partial[0]
        if not partial:
            raise ChaoxingAPIError(f"task-engine label not found: {query}")
        options = ", ".join(f"{item['name']} ({item['label_id']})" for item in partial[:10])
        raise ChaoxingAPIError(f"multiple task-engine labels match: {options}")

    def rename_task_engine_label(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        label: str,
        name: str,
        *,
        task: str = "",
    ) -> dict[str, Any]:
        normalized_name = str(name or "").strip()
        if not 1 <= len(normalized_name) <= 100:
            raise ChaoxingAPIError("task-engine label name must contain 1-100 characters")
        context = self._task_engine_context(course, clazz)
        tasks = self._task_engine_all_tasks(context)
        if not tasks:
            raise ChaoxingAPIError("task-engine labels require at least one committed task")
        selected_task = self._resolve_task_engine_task(tasks, task) if task else tasks[0]
        labels = self._task_engine_labels_from_context(
            context, selected_task, search=str(label or "")
        )
        selected = self._resolve_task_engine_label(labels, label)
        payload = self._task_engine_json_request(
            context,
            "/tasklabel/saveOrDeleteTaskLabelData",
            "task-engine label rename",
            method="POST",
            data={"name": normalized_name, "isAdd": True, "id": selected["label_id"]},
        )
        self._task_engine_ack(payload, "task-engine label rename")
        labels_after = self._task_engine_labels_from_context(
            context, selected_task, search=normalized_name
        )
        matches = [
            item
            for item in labels_after
            if item["label_id"] == selected["label_id"] and item["name"] == normalized_name
        ]
        if len(matches) != 1:
            raise ChaoxingAPIError(
                "server acknowledged label rename, but the refreshed label did not match"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "before": selected,
            "label": matches[0],
            "verification": "the refreshed label has the requested name",
        }

    def delete_task_engine_label(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        label: str,
        *,
        task: str = "",
    ) -> dict[str, Any]:
        context = self._task_engine_context(course, clazz)
        tasks = self._task_engine_all_tasks(context)
        if not tasks:
            raise ChaoxingAPIError("task-engine labels require at least one committed task")
        selected_task = self._resolve_task_engine_task(tasks, task) if task else tasks[0]
        selected = self._resolve_task_engine_label(
            self._task_engine_labels_from_context(context, selected_task, search=str(label or "")),
            label,
        )
        payload = self._task_engine_json_request(
            context,
            "/tasklabel/saveOrDeleteTaskLabelData",
            "task-engine label delete",
            method="POST",
            data={"name": "", "isAdd": False, "id": selected["label_id"]},
        )
        self._task_engine_ack(payload, "task-engine label delete")
        labels_after = self._task_engine_labels_from_context(
            context, selected_task, search=selected["name"]
        )
        if any(item["label_id"] == selected["label_id"] for item in labels_after):
            raise ChaoxingAPIError(
                "server acknowledged label deletion, but the label is still visible"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "deleted_label": selected,
            "verification": "the deleted label is absent from refreshed exact-name search",
        }

    def request_task_engine_export(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        tasks: list[str] | None = None,
        *,
        folder: str = "",
    ) -> dict[str, Any]:
        context = self._task_engine_context(course, clazz)
        folder_id: str | None = None
        if folder:
            folder_id = self._resolve_task_engine_folder(
                self._task_engine_folders_from_context(context), folder
            )["folder_id"]
        available = self._task_engine_tasks_from_context(context, folder_id=folder_id)
        selected = (
            [self._resolve_task_engine_task(available, item) for item in tasks]
            if tasks
            else available
        )
        unique = list(dict.fromkeys(item["task_id"] for item in selected))
        if not unique:
            raise ChaoxingAPIError("no task-engine tasks were selected for export")
        payload = self._task_engine_json_request(
            context,
            "/task/exportTask",
            "task-engine export request",
            method="POST",
            data=",".join(unique),
        )
        self._task_engine_ack(payload, "task-engine export request")
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "requested_count": len(unique),
            "tasks": selected,
            "server_message": str(payload.get("message") or ""),
            "verification": "Chaoxing accepted the asynchronous export request",
        }

    def set_task_engine_publish_status(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        task: str,
        *,
        publish: bool,
        course_publish_param: list[dict[str, Any]] | None = None,
        task_publish_param: list[dict[str, Any]] | None = None,
    ) -> dict[str, Any]:
        context = self._task_engine_context(course, clazz)
        selected = self._resolve_task_engine_task(self._task_engine_all_tasks(context), task)
        details = self._task_engine_task_data(context, selected["task_id"])
        if publish:
            if self._ai_workbench_integer(details.get("taskPointsNumber"), 0) < 1:
                raise ChaoxingAPIError("task-engine task must contain at least one task point")
            check = self._task_engine_json_request(
                context,
                "/peTaskPlan/taskPointCheckPublish",
                "task-engine publish readiness check",
                params={"encryptedTaskId": selected["task_id"]},
            )
            self._task_engine_ack(check, "task-engine publish readiness check")
            payload = self._task_engine_json_request(
                context,
                "/taskReference/taskPublish",
                "task-engine task publish",
                method="POST",
                data={
                    "encryTaskId": selected["task_id"],
                    "coursePublishParam": list(course_publish_param or []),
                    "taskPublishParam": task_publish_param,
                },
            )
            self._task_engine_ack(payload, "task-engine task publish")
        else:
            payload = self._task_engine_json_request(
                context,
                "/taskReference/taskCancelPublish",
                "task-engine task unpublish",
                params={"taskId": selected["task_id"]},
            )
            self._task_engine_ack(payload, "task-engine task unpublish")
        refreshed = self._task_engine_task_data(context, selected["task_id"])
        if bool(refreshed.get("publishStatus")) != bool(publish):
            raise ChaoxingAPIError(
                "server acknowledged publish-state change, but refreshed state did not match"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "task_id": selected["task_id"],
            "name": str(refreshed.get("name") or ""),
            "published": bool(refreshed.get("publishStatus")),
            "verification": "refreshed task publish state matches the requested state",
        }

    def _knowledge_graph_context(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> dict[str, Any]:
        course_id = str(course.get("course_id") or "").strip()
        clazz_id = str(clazz.get("clazz_id") or "").strip()
        cpi = str(course.get("cpi") or "").strip()
        if not all((course_id, clazz_id, cpi)):
            raise ChaoxingAPIError("course_id, clazz_id, and cpi are required")
        return {
            "session": self._session(),
            "common": {
                "courseid": course_id,
                "clazzid": clazz_id,
                "cpi": cpi,
                "ut": "t",
            },
            "referer": MOOC2_BASE_URL + "/topic-ans/knowgraph/index.html",
        }

    def _knowledge_graph_json_request(
        self,
        context: dict[str, Any],
        path: str,
        operation: str,
        *,
        method: str = "GET",
        params: dict[str, Any] | None = None,
        data: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        url = urljoin(MOOC2_BASE_URL + "/", path.lstrip("/"))
        headers = {
            "Referer": context["referer"],
            "X-Requested-With": "XMLHttpRequest",
        }
        try:
            if method.upper() == "POST":
                response = context["session"].post(
                    url,
                    params=params,
                    data=data,
                    headers=headers,
                    timeout=self.timeout,
                )
            else:
                response = context["session"].get(
                    url,
                    params=params,
                    headers=headers,
                    timeout=self.timeout,
                )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"{operation} request failed: {exc}") from exc
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError(f"{operation} returned invalid JSON") from exc
        if not isinstance(payload, dict):
            raise ChaoxingAPIError(f"{operation} returned an invalid payload")
        return payload

    @staticmethod
    def _knowledge_graph_ack(payload: dict[str, Any], operation: str) -> dict[str, Any]:
        if payload.get("status") is True:
            return payload
        message = (
            payload.get("msg") or payload.get("message") or f"{operation} was not acknowledged"
        )
        raise ChaoxingAPIError(str(message))

    def _knowledge_graph_config_data(self, context: dict[str, Any]) -> dict[str, Any]:
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/coursetopic/knowledgemapconfig",
            "knowledge-graph configuration read",
            params=dict(context["common"]),
        )
        return self._knowledge_graph_ack(payload, "knowledge-graph configuration read")

    def _knowledge_graph_raw_data(self, context: dict[str, Any]) -> dict[str, Any]:
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/coursetopic/knowledgemapdata",
            "knowledge-graph data read",
            params=dict(context["common"]),
        )
        return self._knowledge_graph_ack(payload, "knowledge-graph data read")

    @staticmethod
    def _normalize_knowledge_graph(payload: dict[str, Any]) -> dict[str, Any]:
        raw_nodes = payload.get("nodes") if isinstance(payload.get("nodes"), list) else []
        raw_links = payload.get("links") if isinstance(payload.get("links"), list) else []
        parent_by_id: dict[str, str] = {}
        children_by_id: dict[str, list[str]] = {}
        relations: list[dict[str, Any]] = []
        for index, raw in enumerate(raw_links, 1):
            if not isinstance(raw, dict):
                continue
            source_id = str(raw.get("source") or "").strip()
            target_id = str(raw.get("target") or "").strip()
            relation_type = _numeric_or_text(str(raw.get("type") or "0"))
            relation = {
                "index": index,
                "source_id": source_id,
                "target_id": target_id,
                "type": relation_type,
                "name": str(raw.get("relation") or ""),
                "arrow": _numeric_or_text(str(raw.get("arrow") or "")),
                "dasharray": _numeric_or_text(str(raw.get("dasharray") or "")),
                "raw": raw,
            }
            relations.append(relation)
            if relation_type == 1 and source_id and target_id:
                parent_by_id[target_id] = source_id
                children_by_id.setdefault(source_id, []).append(target_id)

        nodes: list[dict[str, Any]] = []
        for raw in raw_nodes:
            if not isinstance(raw, dict):
                continue
            node_id = str(raw.get("id") or raw.get("topicid") or "").strip()
            if not node_id:
                continue
            raw_topic_id = raw.get("topicid")
            topic_id = str(raw_topic_id if raw_topic_id not in (None, 0, "0") else "").strip()
            raw_tag = raw.get("tag")
            if isinstance(raw_tag, list):
                tags = [str(item).strip() for item in raw_tag if str(item).strip()]
            else:
                tags = [item.strip() for item in str(raw_tag or "").split(",") if item.strip()]
            nodes.append(
                {
                    "index": len(nodes) + 1,
                    "node_id": node_id,
                    "topic_id": topic_id,
                    "name": str(raw.get("name") or "").strip(),
                    "level": _numeric_or_text(str(raw.get("level") or "0")),
                    "parent_id": parent_by_id.get(node_id, ""),
                    "children_ids": list(children_by_id.get(node_id, [])),
                    "tags": tags,
                    "category": _numeric_or_text(str(raw.get("category") or "0")),
                    "dimension": _numeric_or_text(str(raw.get("dimension") or "0")),
                    "look_course_id": str(raw.get("lookcourseid") or ""),
                    "across_class": bool(raw.get("acrossClass")),
                    "pile": _numeric_or_text(str(raw.get("pile") or "0")),
                    "group": _numeric_or_text(str(raw.get("group") or "0")),
                    "mark": str(raw.get("mark") or ""),
                    "is_root": not topic_id or node_id.startswith("courseid-"),
                    "raw": raw,
                }
            )

        by_id = {item["node_id"]: item for item in nodes}

        def node_path(item: dict[str, Any]) -> str:
            names: list[str] = []
            current = item
            seen: set[str] = set()
            while current and current["node_id"] not in seen:
                seen.add(current["node_id"])
                if current["name"]:
                    names.append(current["name"])
                current = by_id.get(current["parent_id"])
            return " / ".join(reversed(names))

        for item in nodes:
            item["path"] = node_path(item)
        return {
            "nodes": nodes,
            "relations": relations,
            "lineament": payload.get("lineament")
            if isinstance(payload.get("lineament"), list)
            else [],
            "node_styles": payload.get("nodeStyle")
            if isinstance(payload.get("nodeStyle"), list)
            else [],
            "shadings": payload.get("shadings")
            if isinstance(payload.get("shadings"), list)
            else [],
            "show_settings": payload.get("showSetData")
            if isinstance(payload.get("showSetData"), dict)
            else {},
        }

    @staticmethod
    def _resolve_knowledge_graph_node(
        nodes: list[dict[str, Any]], query: str, *, allow_root: bool = False
    ) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("knowledge-graph node index, ID, name, or path is required")
        candidates = nodes if allow_root else [item for item in nodes if not item["is_root"]]
        for key in ("node_id", "topic_id", "index"):
            matches = [
                item
                for item in candidates
                if str(item.get(key) or "").strip().lower() == normalized
            ]
            if len(matches) == 1:
                return matches[0]
        exact = [
            item
            for item in candidates
            if normalized
            in {
                str(item.get("name") or "").strip().lower(),
                str(item.get("path") or "").strip().lower(),
            }
        ]
        if len(exact) == 1:
            return exact[0]
        partial = [
            item for item in candidates if normalized in str(item.get("path") or "").strip().lower()
        ]
        if len(partial) == 1:
            return partial[0]
        matches = exact or partial
        if not matches:
            raise ChaoxingAPIError(f"knowledge-graph node not found: {query}")
        labels = ", ".join(
            f"{item['index']}. {item['path']} ({item['node_id']})" for item in matches[:10]
        )
        raise ChaoxingAPIError(f"multiple knowledge-graph nodes match: {labels}")

    def list_knowledge_graph(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        search: str = "",
        level: int | None = None,
    ) -> dict[str, Any]:
        context = self._knowledge_graph_context(course, clazz)
        config = self._knowledge_graph_config_data(context)
        graph = self._normalize_knowledge_graph(self._knowledge_graph_raw_data(context))
        nodes = graph["nodes"]
        normalized_search = str(search or "").strip().lower()
        if normalized_search:
            nodes = [
                item
                for item in nodes
                if normalized_search in item["name"].lower()
                or normalized_search in item["path"].lower()
            ]
        if level is not None:
            nodes = [item for item in nodes if item["level"] == int(level)]
        data_json = config.get("dataJson") if isinstance(config.get("dataJson"), dict) else {}
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "allow_edit": bool(config.get("allowEditGraph")),
            "search": normalized_search,
            "level_filter": level,
            "count": len(nodes),
            "total_count": len(graph["nodes"]),
            "nodes": nodes,
            "relations": graph["relations"],
            "relation_types": data_json.get("relationTypeDesc", []),
            "topic_classifications": config.get("topicClassifyArray", []),
            "graph_labels": config.get("graphLabelShow", []),
            "show_settings": config.get("showSetData", {}),
            "advanced_settings": data_json.get("advancedSet", {}),
            "class_contexts": data_json.get("clazzdata", []),
            "export_token": str(data_json.get("exportCourseTopicEnc") or ""),
            "preview_mode": data_json.get("previewModel"),
            "new_topic_version": data_json.get("runNewVersionTopic"),
            "lineament": graph["lineament"],
            "node_styles": graph["node_styles"],
            "shadings": graph["shadings"],
            "verification": "configuration and graph data refreshed from authenticated HTTP APIs",
        }

    def read_knowledge_graph_node(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        node: str,
    ) -> dict[str, Any]:
        context = self._knowledge_graph_context(course, clazz)
        graph = self._normalize_knowledge_graph(self._knowledge_graph_raw_data(context))
        selected = self._resolve_knowledge_graph_node(graph["nodes"], node, allow_root=True)
        related = [
            relation
            for relation in graph["relations"]
            if selected["node_id"] in {relation["source_id"], relation["target_id"]}
        ]
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "node": selected,
            "relations": related,
            "verification": "node and all incident relations refreshed from the graph API",
        }

    def _knowledge_graph_topic_setting_data(self, context: dict[str, Any]) -> dict[str, Any]:
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/coursetopic/gettopicsetting",
            "knowledge-graph model setting read",
            params={**context["common"], "topicModelId": "", "previewMode": ""},
        )
        self._knowledge_graph_ack(payload, "knowledge-graph model setting read")
        data = payload.get("data")
        return data if isinstance(data, dict) else {}

    @staticmethod
    def _normalize_knowledge_graph_models(data: dict[str, Any]) -> list[dict[str, Any]]:
        raw_models = data.get("topicModelData")
        if not isinstance(raw_models, list):
            return []
        mode_names = {
            0: "自定义图谱",
            1: "知识图谱",
            2: "学习地图",
            3: "问题图谱",
            4: "目标图谱",
            5: "课程思政图谱",
            6: "知识列表",
            7: "岗位能力图谱",
        }
        models: list[dict[str, Any]] = []
        for raw in raw_models:
            if not isinstance(raw, dict):
                continue
            model_id = str(raw.get("id") or "").strip()
            if not model_id:
                continue
            mode_type = int(raw.get("modeType") or 0)
            hidden = bool(raw.get("hide"))
            models.append(
                {
                    "index": len(models) + 1,
                    "model_id": model_id,
                    "name": str(raw.get("name") or "").strip(),
                    "mode_type": mode_type,
                    "mode_name": mode_names.get(mode_type, f"模式 {mode_type}"),
                    "style": int(raw.get("style") or 0),
                    "type": int(raw.get("type") or 0),
                    "hidden": hidden,
                    "visible": not hidden,
                    "is_default": bool(raw.get("flagDefault")),
                    "raw": raw,
                }
            )
        return models

    @staticmethod
    def _resolve_knowledge_graph_model(models: list[dict[str, Any]], query: str) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("knowledge-graph model index, ID, or name is required")
        id_matches = [item for item in models if normalized == item["model_id"].lower()]
        if len(id_matches) == 1:
            return id_matches[0]
        exact = [
            item
            for item in models
            if normalized
            in {
                str(item["index"]),
                item["name"].lower(),
                item["mode_name"].lower(),
            }
        ]
        if len(exact) == 1:
            return exact[0]
        partial = [
            item
            for item in models
            if normalized in item["name"].lower() or normalized in item["mode_name"].lower()
        ]
        if len(partial) == 1:
            return partial[0]
        if not partial:
            raise ChaoxingAPIError(f"knowledge-graph model not found: {query}")
        labels = ", ".join(
            f"{item['index']}. {item['name'] or item['mode_name']} ({item['model_id']})"
            for item in partial[:20]
        )
        raise ChaoxingAPIError(f"multiple knowledge-graph models match: {labels}")

    def list_knowledge_graph_models(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        search: str = "",
    ) -> dict[str, Any]:
        context = self._knowledge_graph_context(course, clazz)
        data = self._knowledge_graph_topic_setting_data(context)
        models = self._normalize_knowledge_graph_models(data)
        normalized_search = str(search or "").strip().lower()
        filtered = [
            item
            for item in models
            if not normalized_search
            or normalized_search in item["name"].lower()
            or normalized_search in item["mode_name"].lower()
            or normalized_search in item["model_id"].lower()
        ]
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "count": len(filtered),
            "total_count": len(models),
            "models": filtered,
            "switch_status": data.get("switchStatusData", {}),
            "verification": "graph models refreshed from the authenticated model-setting API",
        }

    def create_knowledge_graph_model(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        name: str,
        *,
        style: int = 0,
    ) -> dict[str, Any]:
        normalized_name = self._validate_knowledge_graph_text(
            name, "knowledge-graph model name", 10
        )
        normalized_style = int(style)
        if not 0 <= normalized_style <= 9:
            raise ChaoxingAPIError("knowledge-graph model style must be between 0 and 9")
        context = self._knowledge_graph_context(course, clazz)
        before = self._normalize_knowledge_graph_models(
            self._knowledge_graph_topic_setting_data(context)
        )
        before_ids = {item["model_id"] for item in before}
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/coursetopic/addtopicmodel",
            "knowledge-graph model create",
            params={
                "courseid": course["course_id"],
                "cpi": course["cpi"],
                "name": normalized_name,
                "addTopicType": 0,
                "style": normalized_style,
            },
        )
        self._knowledge_graph_ack(payload, "knowledge-graph model create")
        returned_id = str(payload.get("coruseTopicModelId") or "").strip()
        models = self._normalize_knowledge_graph_models(
            self._knowledge_graph_topic_setting_data(context)
        )
        candidates = [
            item
            for item in models
            if item["model_id"] not in before_ids
            and (not returned_id or item["model_id"] == returned_id)
        ]
        if len(candidates) != 1:
            raise ChaoxingAPIError(
                "server acknowledged model creation, but one new stable model ID was not found"
            )
        created = candidates[0]
        if created["name"] != normalized_name or created["style"] != normalized_style:
            raise ChaoxingAPIError(
                "server acknowledged model creation, but refreshed fields differ"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "model": created,
            "verification": "new graph model refreshed by its server-assigned stable ID",
        }

    def update_knowledge_graph_model(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        model: str,
        name: str,
        *,
        style: int | None = None,
    ) -> dict[str, Any]:
        normalized_name = self._validate_knowledge_graph_text(
            name, "knowledge-graph model name", 10
        )
        context = self._knowledge_graph_context(course, clazz)
        selected = self._resolve_knowledge_graph_model(
            self._normalize_knowledge_graph_models(
                self._knowledge_graph_topic_setting_data(context)
            ),
            model,
        )
        normalized_style = selected["style"] if style is None else int(style)
        if not 0 <= normalized_style <= 9:
            raise ChaoxingAPIError("knowledge-graph model style must be between 0 and 9")
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/coursetopic/updatetopicmodel",
            "knowledge-graph model update",
            params={
                "courseid": course["course_id"],
                "cpi": course["cpi"],
                "name": normalized_name,
                "style": normalized_style if style is not None else -1,
                "topicModeoId": selected["model_id"],
                "modelType": selected["mode_type"],
            },
        )
        self._knowledge_graph_ack(payload, "knowledge-graph model update")
        refreshed = self._resolve_knowledge_graph_model(
            self._normalize_knowledge_graph_models(
                self._knowledge_graph_topic_setting_data(context)
            ),
            selected["model_id"],
        )
        if refreshed["name"] != normalized_name or refreshed["style"] != normalized_style:
            raise ChaoxingAPIError("server acknowledged model update, but refreshed fields differ")
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "before": selected,
            "model": refreshed,
            "verification": "graph model refreshed by stable ID and requested fields match",
        }

    def set_knowledge_graph_model_visibility(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        model: str,
        *,
        visible: bool,
    ) -> dict[str, Any]:
        context = self._knowledge_graph_context(course, clazz)
        selected = self._resolve_knowledge_graph_model(
            self._normalize_knowledge_graph_models(
                self._knowledge_graph_topic_setting_data(context)
            ),
            model,
        )
        special = {
            3: ("/mooc2-ans/questionBankTopic/updatequestionmap", "questionMap"),
            4: ("/mooc2-ans/questionBankTopic/updateabilitymap", "abilityMap"),
            5: ("/mooc2-ans/questionBankTopic/updateideologicalmap", "ideologicalMap"),
        }
        if selected["mode_type"] in special:
            path, field = special[selected["mode_type"]]
            params = {
                "courseId": course["course_id"],
                "clazzId": clazz["clazz_id"],
                "cpi": course["cpi"],
                "topicModelId": selected["model_id"],
                "ut": "t",
                field: int(bool(visible)),
            }
        else:
            path = "/mooc2-ans/coursetopic/updatetopicmodelhide"
            params = {
                "courseid": course["course_id"],
                "cpi": course["cpi"],
                "hide": int(not bool(visible)),
                "topicModeoId": selected["model_id"],
            }
        payload = self._knowledge_graph_json_request(
            context,
            path,
            "knowledge-graph model visibility update",
            params=params,
        )
        self._knowledge_graph_ack(payload, "knowledge-graph model visibility update")
        refreshed = self._resolve_knowledge_graph_model(
            self._normalize_knowledge_graph_models(
                self._knowledge_graph_topic_setting_data(context)
            ),
            selected["model_id"],
        )
        if refreshed["visible"] is not bool(visible):
            raise ChaoxingAPIError(
                "server acknowledged model visibility, but refreshed state differs"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "before": selected,
            "model": refreshed,
            "verification": "graph model visibility matches a fresh model-setting response",
        }

    def reorder_knowledge_graph_models(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        model_order: list[str],
    ) -> dict[str, Any]:
        context = self._knowledge_graph_context(course, clazz)
        models = self._normalize_knowledge_graph_models(
            self._knowledge_graph_topic_setting_data(context)
        )
        resolved = [self._resolve_knowledge_graph_model(models, item) for item in model_order]
        expected_ids = [item["model_id"] for item in resolved]
        current_ids = [item["model_id"] for item in models]
        if len(set(expected_ids)) != len(expected_ids) or set(expected_ids) != set(current_ids):
            raise ChaoxingAPIError("model_order must contain every graph model exactly once")
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/coursetopic/updatedmodelsort",
            "knowledge-graph model reorder",
            params={
                "courseid": course["course_id"],
                "cpi": course["cpi"],
                "topicModelIds": ",".join(expected_ids),
            },
        )
        self._knowledge_graph_ack(payload, "knowledge-graph model reorder")
        refreshed = self._normalize_knowledge_graph_models(
            self._knowledge_graph_topic_setting_data(context)
        )
        if [item["model_id"] for item in refreshed] != expected_ids:
            raise ChaoxingAPIError("server acknowledged model reorder, but refreshed order differs")
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "models": refreshed,
            "verification": "fresh model order exactly matches the complete requested order",
        }

    def delete_knowledge_graph_model(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        model: str,
    ) -> dict[str, Any]:
        context = self._knowledge_graph_context(course, clazz)
        selected = self._resolve_knowledge_graph_model(
            self._normalize_knowledge_graph_models(
                self._knowledge_graph_topic_setting_data(context)
            ),
            model,
        )
        if selected["is_default"]:
            raise ChaoxingAPIError("default knowledge-graph models cannot be deleted")
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/coursetopic/deletetopicmodel",
            "knowledge-graph model delete",
            params={
                "courseid": course["course_id"],
                "cpi": course["cpi"],
                "topicModelId": selected["model_id"],
            },
        )
        self._knowledge_graph_ack(payload, "knowledge-graph model delete")
        remaining = self._normalize_knowledge_graph_models(
            self._knowledge_graph_topic_setting_data(context)
        )
        if any(item["model_id"] == selected["model_id"] for item in remaining):
            raise ChaoxingAPIError(
                "server acknowledged model deletion, but the model remains visible"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "deleted_model": selected,
            "verification": "custom graph model is absent from a fresh model-setting response",
        }

    @staticmethod
    def _normalize_knowledge_graph_model_classes(payload: dict[str, Any]) -> list[dict[str, Any]]:
        raw_classes = payload.get("data") if isinstance(payload.get("data"), list) else []
        classes: list[dict[str, Any]] = []
        for raw in raw_classes:
            if not isinstance(raw, dict):
                continue
            clazz_id = str(raw.get("id") or "").strip()
            if not clazz_id:
                continue
            hidden = bool(raw.get("modelHide"))
            classes.append(
                {
                    "index": len(classes) + 1,
                    "clazz_id": clazz_id,
                    "clazz_name": str(raw.get("name") or "").strip(),
                    "hidden": hidden,
                    "visible": not hidden,
                }
            )
        return classes

    def _knowledge_graph_model_classes(
        self,
        context: dict[str, Any],
        model_id: str,
    ) -> list[dict[str, Any]]:
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/questionBankTopic/queryclazztopicmodel",
            "knowledge-graph model class visibility read",
            params={
                "courseId": context["common"]["courseid"],
                "cpi": context["common"]["cpi"],
                "modelId": model_id,
                "ut": "t",
            },
        )
        self._knowledge_graph_ack(payload, "knowledge-graph model class visibility read")
        return self._normalize_knowledge_graph_model_classes(payload)

    @staticmethod
    def _resolve_knowledge_graph_model_class(
        classes: list[dict[str, Any]], query: str
    ) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("knowledge-graph model class index, ID, or name is required")
        exact = [
            item
            for item in classes
            if normalized
            in {str(item["index"]), item["clazz_id"].lower(), item["clazz_name"].lower()}
        ]
        if len(exact) == 1:
            return exact[0]
        partial = [item for item in classes if normalized in item["clazz_name"].lower()]
        if len(partial) == 1:
            return partial[0]
        if not partial:
            raise ChaoxingAPIError(f"knowledge-graph model class not found: {query}")
        labels = ", ".join(
            f"{item['index']}. {item['clazz_name']} ({item['clazz_id']})" for item in partial[:20]
        )
        raise ChaoxingAPIError(f"multiple model classes match: {labels}")

    def list_knowledge_graph_model_classes(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        model: str,
    ) -> dict[str, Any]:
        context = self._knowledge_graph_context(course, clazz)
        selected = self._resolve_knowledge_graph_model(
            self._normalize_knowledge_graph_models(
                self._knowledge_graph_topic_setting_data(context)
            ),
            model,
        )
        classes = self._knowledge_graph_model_classes(context, selected["model_id"])
        return {
            "course_id": course["course_id"],
            "model": selected,
            "count": len(classes),
            "classes": classes,
            "verification": "model class visibility refreshed from the authenticated API",
        }

    def update_knowledge_graph_model_classes(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        model: str,
        visible_classes: list[str],
    ) -> dict[str, Any]:
        context = self._knowledge_graph_context(course, clazz)
        selected = self._resolve_knowledge_graph_model(
            self._normalize_knowledge_graph_models(
                self._knowledge_graph_topic_setting_data(context)
            ),
            model,
        )
        classes = self._knowledge_graph_model_classes(context, selected["model_id"])
        if len(visible_classes) == 1 and str(visible_classes[0]).strip().lower() in {
            "*",
            "all",
            "全部",
            "全部班级",
        }:
            resolved = classes
        else:
            resolved = [
                self._resolve_knowledge_graph_model_class(classes, item) for item in visible_classes
            ]
        visible_ids = [item["clazz_id"] for item in resolved]
        if len(set(visible_ids)) != len(visible_ids):
            raise ChaoxingAPIError("visible_classes contains duplicate classes")
        visible_set = set(visible_ids)
        hidden_ids = [item["clazz_id"] for item in classes if item["clazz_id"] not in visible_set]
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/questionBankTopic/saveclazztopicmodel",
            "knowledge-graph model class visibility update",
            method="POST",
            data={
                "courseId": course["course_id"],
                "cpi": course["cpi"],
                "modelId": selected["model_id"],
                "ut": "t",
                "clazzIds": ",".join(hidden_ids),
            },
        )
        self._knowledge_graph_ack(payload, "knowledge-graph model class visibility update")
        refreshed = self._knowledge_graph_model_classes(context, selected["model_id"])
        actual_visible = {item["clazz_id"] for item in refreshed if item["visible"]}
        if actual_visible != visible_set:
            raise ChaoxingAPIError(
                "server acknowledged class visibility, but refreshed classes differ"
            )
        return {
            "course_id": course["course_id"],
            "model": selected,
            "classes": refreshed,
            "verification": "fresh class visibility exactly matches the requested class set",
        }

    @staticmethod
    def _normalize_knowledge_graph_model_data(data: dict[str, Any]) -> dict[str, Any]:
        nodes: list[dict[str, Any]] = []

        def visit(raw: dict[str, Any], parent_id: str, level: int, path: list[str]) -> None:
            name = str(raw.get("name") or "").strip()
            node_id = str(raw.get("topicId") or raw.get("id") or "root").strip()
            current_path = [*path, name] if name else path
            children = raw.get("children") if isinstance(raw.get("children"), list) else []
            nodes.append(
                {
                    "index": len(nodes) + 1,
                    "node_id": node_id,
                    "parent_id": parent_id,
                    "name": name,
                    "level": level,
                    "path": " / ".join(current_path),
                    "child_count": len(children),
                    "raw": raw,
                }
            )
            for child in children:
                if isinstance(child, dict):
                    visit(child, node_id, level + 1, current_path)

        visit(data, "", 0, [])
        return {"count": len(nodes), "nodes": nodes, "raw": data}

    def read_knowledge_graph_model_data(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        model: str,
    ) -> dict[str, Any]:
        context = self._knowledge_graph_context(course, clazz)
        selected = self._resolve_knowledge_graph_model(
            self._normalize_knowledge_graph_models(
                self._knowledge_graph_topic_setting_data(context)
            ),
            model,
        )
        config = self._knowledge_graph_config_data(context)
        data_json = config.get("dataJson") if isinstance(config.get("dataJson"), dict) else {}
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/coursetopic/mapmodeldata",
            "knowledge-graph model data read",
            params={
                "courseid": course["course_id"],
                "cpi": course["cpi"],
                "clazzid": clazz["clazz_id"],
                "topicModelId": selected["model_id"],
                "view": "json",
                "enc": str(data_json.get("exportCourseTopicEnc") or ""),
            },
        )
        self._knowledge_graph_ack(payload, "knowledge-graph model data read")
        raw = payload.get("data") if isinstance(payload.get("data"), dict) else {}
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "model": selected,
            "data": self._normalize_knowledge_graph_model_data(raw),
            "verification": "model-specific graph data refreshed from the authenticated API",
        }

    @staticmethod
    def _normalize_knowledge_graph_relation_types(
        config: dict[str, Any],
    ) -> list[dict[str, Any]]:
        data_json = config.get("dataJson") if isinstance(config.get("dataJson"), dict) else {}
        raw_relations = (
            data_json.get("relationTypeDesc")
            if isinstance(data_json.get("relationTypeDesc"), list)
            else []
        )
        relations: list[dict[str, Any]] = []
        for raw in raw_relations:
            if not isinstance(raw, dict):
                continue
            relation_id = str(
                raw.get("relationDescId") if raw.get("relationDescId") is not None else ""
            ).strip()
            if not relation_id:
                continue
            relations.append(
                {
                    "index": len(relations) + 1,
                    "relation_id": relation_id,
                    "name": str(raw.get("relationDescName") or "").strip(),
                    "meaning": str(raw.get("relationDescMean") or ""),
                    "example_html": str(raw.get("relationDescExample") or ""),
                    "relation_type": _numeric_or_text(
                        str(
                            raw.get("relationDescType")
                            if raw.get("relationDescType") is not None
                            else ""
                        )
                    ),
                    "filter_type": _numeric_or_text(
                        str(
                            raw.get("relationDescFilterType")
                            if raw.get("relationDescFilterType") is not None
                            else ""
                        )
                    ),
                    "default_type": _numeric_or_text(
                        str(raw.get("defaultType") if raw.get("defaultType") is not None else "")
                    ),
                    "is_default": bool(raw.get("isDefault")),
                    "color": str(raw.get("color") or ""),
                    "arrow_size": _numeric_or_text(str(raw.get("arrowSize") or "")),
                    "line_thickness": _numeric_or_text(str(raw.get("lineThickness") or "")),
                    "raw": raw,
                }
            )
        return relations

    @staticmethod
    def _resolve_knowledge_graph_relation_type(
        relations: list[dict[str, Any]], query: str
    ) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("knowledge-graph relation index, ID, or name is required")
        for key in ("relation_id", "index"):
            matches = [
                item for item in relations if str(item.get(key) or "").strip().lower() == normalized
            ]
            if len(matches) == 1:
                return matches[0]
        exact = [item for item in relations if item["name"].lower() == normalized]
        partial = [item for item in relations if normalized in item["name"].lower()]
        matches = exact if exact else partial
        if len(matches) == 1:
            return matches[0]
        if not matches:
            raise ChaoxingAPIError(f"knowledge-graph relation type not found: {query}")
        labels = ", ".join(
            f"{item['index']}. {item['name']} ({item['relation_id']})" for item in matches[:10]
        )
        raise ChaoxingAPIError(f"multiple knowledge-graph relation types match: {labels}")

    def list_knowledge_graph_relation_types(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        search: str = "",
    ) -> dict[str, Any]:
        context = self._knowledge_graph_context(course, clazz)
        relations = self._normalize_knowledge_graph_relation_types(
            self._knowledge_graph_config_data(context)
        )
        normalized_search = str(search or "").strip().lower()
        if normalized_search:
            relations = [
                item
                for item in relations
                if normalized_search in item["name"].lower()
                or normalized_search in item["meaning"].lower()
            ]
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "search": normalized_search,
            "count": len(relations),
            "relations": relations,
            "verification": "relation definitions refreshed from the authenticated graph config",
        }

    @staticmethod
    def _knowledge_graph_relation_type_values(values: list[int] | None) -> list[int]:
        result: list[int] = []
        for value in values or [0]:
            normalized = int(value)
            if normalized not in {0, 1, 2}:
                raise ChaoxingAPIError("relation types must contain only 0, 1, or 2")
            if normalized not in result:
                result.append(normalized)
        if not result:
            raise ChaoxingAPIError("at least one relation type is required")
        return result

    @staticmethod
    def _knowledge_graph_relation_form(
        *,
        course_id: str,
        cpi: str,
        name: str,
        meaning: str,
        relation_types: list[int],
        example_html: str,
        color: str,
        default_type: int,
        relation_id: str = "",
        arrow_size: int = 6,
        line_thickness: int = 1,
    ) -> dict[str, Any]:
        data: dict[str, Any] = {
            "courseId": course_id,
            "cpi": cpi,
            "relationName": name,
            "relationMean": meaning,
            "relationExample": example_html,
            "color": color,
            "defaultType": default_type,
        }
        for index, relation_type in enumerate(relation_types):
            data[f"relationType[{index}]"] = relation_type
        if relation_id:
            data.update(
                {
                    "relationId": relation_id,
                    "arrowSize": arrow_size,
                    "lineThickness": line_thickness,
                }
            )
        return data

    def create_knowledge_graph_relation_type(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        name: str,
        *,
        meaning: str = "",
        relation_types: list[int] | None = None,
        example_html: str = "",
        color: str = "",
    ) -> dict[str, Any]:
        normalized_name = self._validate_knowledge_graph_text(
            name, "knowledge-graph relation name", 20
        )
        normalized_types = self._knowledge_graph_relation_type_values(relation_types)
        context = self._knowledge_graph_context(course, clazz)
        before = self._normalize_knowledge_graph_relation_types(
            self._knowledge_graph_config_data(context)
        )
        before_ids = {item["relation_id"] for item in before}
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/questionBankTopic/createselfdefinetopicrelation",
            "knowledge-graph relation create",
            method="POST",
            data=self._knowledge_graph_relation_form(
                course_id=course["course_id"],
                cpi=course["cpi"],
                name=normalized_name,
                meaning=str(meaning or ""),
                relation_types=normalized_types,
                example_html=str(example_html or ""),
                color=str(color or ""),
                default_type=-1,
            ),
        )
        self._knowledge_graph_ack(payload, "knowledge-graph relation create")
        returned_id = str(payload.get("saveTopicRelationDescId") or "").strip()
        relations = self._normalize_knowledge_graph_relation_types(
            self._knowledge_graph_config_data(context)
        )
        matches = [
            item
            for item in relations
            if item["relation_id"] not in before_ids
            and item["name"] == normalized_name
            and (not returned_id or item["relation_id"] == returned_id)
        ]
        if len(matches) != 1:
            raise ChaoxingAPIError(
                "server acknowledged relation creation, but the new definition was not "
                "uniquely visible"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "relation": matches[0],
            "requested_relation_types": normalized_types,
            "verification": "one new custom relation appeared with the returned ID",
        }

    def update_knowledge_graph_relation_type(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        relation: str,
        *,
        name: str | None = None,
        meaning: str | None = None,
        relation_types: list[int] | None = None,
        example_html: str | None = None,
        color: str | None = None,
        arrow_size: int | None = None,
        line_thickness: int | None = None,
    ) -> dict[str, Any]:
        context = self._knowledge_graph_context(course, clazz)
        selected = self._resolve_knowledge_graph_relation_type(
            self._normalize_knowledge_graph_relation_types(
                self._knowledge_graph_config_data(context)
            ),
            relation,
        )
        if selected["is_default"]:
            raise ChaoxingAPIError("default knowledge-graph relation types cannot be updated")
        normalized_name = (
            selected["name"]
            if name is None
            else self._validate_knowledge_graph_text(name, "knowledge-graph relation name", 20)
        )
        normalized_types = self._knowledge_graph_relation_type_values(
            relation_types if relation_types is not None else [int(selected["relation_type"])]
        )
        normalized_arrow = int(selected["arrow_size"] if arrow_size is None else arrow_size)
        normalized_line = int(
            selected["line_thickness"] if line_thickness is None else line_thickness
        )
        if not 1 <= normalized_arrow <= 20 or not 1 <= normalized_line <= 20:
            raise ChaoxingAPIError("arrow_size and line_thickness must be between 1 and 20")
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/questionBankTopic/updateselfdefinetopicrelation",
            "knowledge-graph relation update",
            method="POST",
            data=self._knowledge_graph_relation_form(
                course_id=course["course_id"],
                cpi=course["cpi"],
                relation_id=selected["relation_id"],
                name=normalized_name,
                meaning=selected["meaning"] if meaning is None else str(meaning),
                relation_types=normalized_types,
                example_html=(
                    selected["example_html"] if example_html is None else str(example_html)
                ),
                color=selected["color"] if color is None else str(color),
                default_type=int(selected["default_type"]),
                arrow_size=normalized_arrow,
                line_thickness=normalized_line,
            ),
        )
        self._knowledge_graph_ack(payload, "knowledge-graph relation update")
        refreshed = self._resolve_knowledge_graph_relation_type(
            self._normalize_knowledge_graph_relation_types(
                self._knowledge_graph_config_data(context)
            ),
            selected["relation_id"],
        )
        expected = {
            "name": normalized_name,
            "meaning": selected["meaning"] if meaning is None else str(meaning),
            "example_html": (
                selected["example_html"] if example_html is None else str(example_html)
            ),
            "color": selected["color"] if color is None else str(color),
            "arrow_size": normalized_arrow,
            "line_thickness": normalized_line,
        }
        mismatches = {
            key: {"expected": value, "actual": refreshed.get(key)}
            for key, value in expected.items()
            if refreshed.get(key) != value
        }
        if mismatches:
            raise ChaoxingAPIError(
                f"server acknowledged relation update, but refreshed fields differ: {mismatches}"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "before": selected,
            "relation": refreshed,
            "requested_relation_types": normalized_types,
            "verification": "the custom relation was refreshed by stable ID",
        }

    def delete_knowledge_graph_relation_type(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        relation: str,
    ) -> dict[str, Any]:
        context = self._knowledge_graph_context(course, clazz)
        selected = self._resolve_knowledge_graph_relation_type(
            self._normalize_knowledge_graph_relation_types(
                self._knowledge_graph_config_data(context)
            ),
            relation,
        )
        if selected["is_default"]:
            raise ChaoxingAPIError("default knowledge-graph relation types cannot be deleted")
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/questionBankTopic/deleteselfdefinetopicrelation",
            "knowledge-graph relation delete",
            method="POST",
            data={
                "courseId": course["course_id"],
                "cpi": course["cpi"],
                "relationTypeId": selected["relation_id"],
            },
        )
        self._knowledge_graph_ack(payload, "knowledge-graph relation delete")
        remaining = self._normalize_knowledge_graph_relation_types(
            self._knowledge_graph_config_data(context)
        )
        if any(item["relation_id"] == selected["relation_id"] for item in remaining):
            raise ChaoxingAPIError(
                "server acknowledged relation deletion, but the definition remains visible"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "deleted_relation": selected,
            "verification": "the custom relation is absent from a fresh graph configuration",
        }

    @staticmethod
    def _normalize_knowledge_graph_settings(config: dict[str, Any]) -> dict[str, Any]:
        show = config.get("showSetData") if isinstance(config.get("showSetData"), dict) else {}
        data_json = config.get("dataJson") if isinstance(config.get("dataJson"), dict) else {}
        advanced = (
            data_json.get("advancedSet") if isinstance(data_json.get("advancedSet"), dict) else {}
        )
        return {
            "show_all_relations": bool(show.get("showAllRelation")),
            "show_all_topic_names": bool(show.get("showAllTopicname")),
            "navigation_node_scale": bool(show.get("navNodeScale")),
            "graph_background_color": bool(show.get("graphBackgroundColor")),
            "raw_show_settings": show,
            "raw_advanced_settings": advanced,
        }

    def read_knowledge_graph_settings(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> dict[str, Any]:
        context = self._knowledge_graph_context(course, clazz)
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "settings": self._normalize_knowledge_graph_settings(
                self._knowledge_graph_config_data(context)
            ),
            "verification": "graph settings refreshed from the authenticated configuration API",
        }

    def _update_knowledge_graph_setting_field(
        self,
        context: dict[str, Any],
        server_field: str,
        value: bool,
    ) -> None:
        endpoints = {
            "showAllRelation": ("/mooc2-ans/coursetopic/updateshowallrelation", "GET"),
            "showAllTopicname": ("/mooc2-ans/coursetopic/updateshowalltopicname", "GET"),
            "navNodeScale": ("/mooc2-ans/coursetopic/updatenavnodescale", "POST"),
            "graphBackgroundColor": (
                "/mooc2-ans/questionBankTopic/updategraphshowsetting",
                "GET",
            ),
        }
        path, method = endpoints[server_field]
        values = {
            "courseid": context["common"]["courseid"],
            "cpi": context["common"]["cpi"],
            server_field: int(value),
        }
        payload = self._knowledge_graph_json_request(
            context,
            path,
            f"knowledge-graph setting {server_field} update",
            method=method,
            params=values if method == "GET" else None,
            data=values if method == "POST" else None,
        )
        self._knowledge_graph_ack(payload, f"knowledge-graph setting {server_field} update")

    def update_knowledge_graph_settings(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        show_all_relations: bool | None = None,
        show_all_topic_names: bool | None = None,
        navigation_node_scale: bool | None = None,
        graph_background_color: bool | None = None,
    ) -> dict[str, Any]:
        requested = {
            key: value
            for key, value in {
                "show_all_relations": show_all_relations,
                "show_all_topic_names": show_all_topic_names,
                "navigation_node_scale": navigation_node_scale,
                "graph_background_color": graph_background_color,
            }.items()
            if value is not None
        }
        if not requested:
            raise ChaoxingAPIError("at least one knowledge-graph setting is required")
        server_fields = {
            "show_all_relations": "showAllRelation",
            "show_all_topic_names": "showAllTopicname",
            "navigation_node_scale": "navNodeScale",
            "graph_background_color": "graphBackgroundColor",
        }
        context = self._knowledge_graph_context(course, clazz)
        before = self._normalize_knowledge_graph_settings(
            self._knowledge_graph_config_data(context)
        )
        changed = [key for key, value in requested.items() if before[key] != bool(value)]
        applied: list[str] = []
        try:
            for key in changed:
                self._update_knowledge_graph_setting_field(
                    context, server_fields[key], bool(requested[key])
                )
                applied.append(key)
        except ChaoxingAPIError as exc:
            rollback_errors: list[str] = []
            for key in reversed(applied):
                try:
                    self._update_knowledge_graph_setting_field(
                        context, server_fields[key], before[key]
                    )
                except ChaoxingAPIError as rollback_exc:
                    rollback_errors.append(f"{key}: {rollback_exc}")
            suffix = f"; rollback errors: {rollback_errors}" if rollback_errors else ""
            raise ChaoxingAPIError(
                f"knowledge-graph settings update failed: {exc}{suffix}"
            ) from exc
        refreshed = self._normalize_knowledge_graph_settings(
            self._knowledge_graph_config_data(context)
        )
        mismatches = {
            key: {"expected": bool(value), "actual": refreshed[key]}
            for key, value in requested.items()
            if refreshed[key] != bool(value)
        }
        if mismatches:
            rollback_errors: list[str] = []
            for key in reversed(changed):
                try:
                    self._update_knowledge_graph_setting_field(
                        context, server_fields[key], before[key]
                    )
                except ChaoxingAPIError as rollback_exc:
                    rollback_errors.append(f"{key}: {rollback_exc}")
            suffix = f"; rollback errors: {rollback_errors}" if rollback_errors else ""
            raise ChaoxingAPIError(
                "server acknowledged graph settings, but refreshed values differ: "
                f"{mismatches}{suffix}"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "before": before,
            "settings": refreshed,
            "changed_fields": changed,
            "verification": "all requested display settings match a fresh graph configuration",
        }

    @staticmethod
    def _normalize_knowledge_graph_advanced_settings(data: dict[str, Any]) -> dict[str, Any]:
        def enabled(value: Any) -> bool:
            if isinstance(value, str):
                return value.strip().lower() not in {"", "0", "false", "off", "no", "null"}
            return bool(value)

        switches = (
            data.get("switchStatusData") if isinstance(data.get("switchStatusData"), dict) else {}
        )
        return {
            "topic_card": enabled(data.get("topicCard")),
            "teach_target": enabled(data.get("teachTarget")),
            "study_hours_enabled": enabled(data.get("studyHoursEnabled")),
            "classify_relation_data": enabled(data.get("classifyRelationData")),
            "selftest_included": enabled(switches.get("selftestIncluded")),
            "micro_preview": enabled(data.get("microPreview")),
            "micro_scale_mode": enabled(data.get("microScaleMode")),
            "raw_switch_status": switches,
            "raw_micro_tabs": (
                data.get("showMicroTab") if isinstance(data.get("showMicroTab"), dict) else {}
            ),
        }

    def read_knowledge_graph_advanced_settings(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> dict[str, Any]:
        context = self._knowledge_graph_context(course, clazz)
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "settings": self._normalize_knowledge_graph_advanced_settings(
                self._knowledge_graph_topic_setting_data(context)
            ),
            "verification": "advanced graph settings refreshed from the authenticated API",
        }

    def _update_knowledge_graph_advanced_setting_group(
        self,
        context: dict[str, Any],
        group: str,
        values: dict[str, bool],
    ) -> None:
        common = {
            "courseid": context["common"]["courseid"],
            "cpi": context["common"]["cpi"],
        }
        endpoints = {
            "study_hours_enabled": (
                "/mooc2-ans/coursetopic/updateStudyHoursEnabled",
                "studyHoursEnabled",
            ),
            "classify_relation_data": (
                "/mooc2-ans/coursetopic/updateclassifyrelationdata",
                "classifyRelationData",
            ),
            "selftest_included": (
                "/mooc2-ans/coursetopic/updateselftestincluded",
                "selftestIncluded",
            ),
            "micro_preview": (
                "/mooc2-ans/coursetopic/update-micro-preview",
                "microPreview",
            ),
            "micro_scale_mode": (
                "/mooc2-ans/coursetopic/update-micro-scale-mode",
                "microScaleMode",
            ),
        }
        if group == "topic_pair":
            path = "/mooc2-ans/coursetopic/updatetopiccardstatus"
            params = {
                **common,
                "topicCard": int(values["topic_card"]),
                "teachTarget": int(values["teach_target"]),
            }
        else:
            path, server_field = endpoints[group]
            params = {**common, server_field: int(values[group])}
        payload = self._knowledge_graph_json_request(
            context,
            path,
            f"knowledge-graph advanced setting {group} update",
            params=params,
        )
        self._knowledge_graph_ack(payload, f"knowledge-graph advanced setting {group} update")

    def update_knowledge_graph_advanced_settings(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        topic_card: bool | None = None,
        teach_target: bool | None = None,
        study_hours_enabled: bool | None = None,
        classify_relation_data: bool | None = None,
        selftest_included: bool | None = None,
        micro_preview: bool | None = None,
        micro_scale_mode: bool | None = None,
    ) -> dict[str, Any]:
        requested = {
            key: value
            for key, value in {
                "topic_card": topic_card,
                "teach_target": teach_target,
                "study_hours_enabled": study_hours_enabled,
                "classify_relation_data": classify_relation_data,
                "selftest_included": selftest_included,
                "micro_preview": micro_preview,
                "micro_scale_mode": micro_scale_mode,
            }.items()
            if value is not None
        }
        if not requested:
            raise ChaoxingAPIError("at least one advanced knowledge-graph setting is required")
        context = self._knowledge_graph_context(course, clazz)
        before = self._normalize_knowledge_graph_advanced_settings(
            self._knowledge_graph_topic_setting_data(context)
        )
        desired = {
            key: bool(requested.get(key, before[key]))
            for key in (
                "topic_card",
                "teach_target",
                "study_hours_enabled",
                "classify_relation_data",
                "selftest_included",
                "micro_preview",
                "micro_scale_mode",
            )
        }
        groups: list[str] = []
        if any(
            key in requested and desired[key] != before[key]
            for key in ("topic_card", "teach_target")
        ):
            groups.append("topic_pair")
        groups.extend(
            key
            for key in (
                "study_hours_enabled",
                "classify_relation_data",
                "selftest_included",
                "micro_preview",
                "micro_scale_mode",
            )
            if key in requested and desired[key] != before[key]
        )
        applied: list[str] = []
        try:
            for group in groups:
                self._update_knowledge_graph_advanced_setting_group(context, group, desired)
                applied.append(group)
        except ChaoxingAPIError as exc:
            rollback_errors: list[str] = []
            for group in reversed(applied):
                try:
                    self._update_knowledge_graph_advanced_setting_group(context, group, before)
                except ChaoxingAPIError as rollback_exc:
                    rollback_errors.append(f"{group}: {rollback_exc}")
            suffix = f"; rollback errors: {rollback_errors}" if rollback_errors else ""
            raise ChaoxingAPIError(
                f"advanced knowledge-graph settings update failed: {exc}{suffix}"
            ) from exc
        refreshed = self._normalize_knowledge_graph_advanced_settings(
            self._knowledge_graph_topic_setting_data(context)
        )
        mismatches = {
            key: {"expected": bool(value), "actual": refreshed[key]}
            for key, value in requested.items()
            if refreshed[key] != bool(value)
        }
        if mismatches:
            rollback_errors: list[str] = []
            for group in reversed(groups):
                try:
                    self._update_knowledge_graph_advanced_setting_group(context, group, before)
                except ChaoxingAPIError as rollback_exc:
                    rollback_errors.append(f"{group}: {rollback_exc}")
            suffix = f"; rollback errors: {rollback_errors}" if rollback_errors else ""
            raise ChaoxingAPIError(
                "server acknowledged advanced graph settings, but refreshed values differ: "
                f"{mismatches}{suffix}"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "before": before,
            "settings": refreshed,
            "changed_groups": groups,
            "verification": "all requested advanced settings match a fresh graph response",
        }

    @staticmethod
    def _validate_knowledge_graph_text(value: str, label: str, maximum: int = 200) -> str:
        normalized = str(value or "").strip()
        if not 1 <= len(normalized) <= maximum:
            raise ChaoxingAPIError(f"{label} must contain 1-{maximum} characters")
        return normalized

    @staticmethod
    def _knowledge_graph_node_type(value: str) -> tuple[str, int, int]:
        normalized = str(value or "knowledge").strip().lower().replace("-", "_")
        aliases = {
            "knowledge": ("knowledge", 0, 0),
            "knowledge_point": ("knowledge", 0, 0),
            "point": ("knowledge", 0, 0),
            "知识点": ("knowledge", 0, 0),
            "category": ("category", 1, 0),
            "classification": ("category", 1, 0),
            "分类": ("category", 1, 0),
            "分类节点": ("category", 1, 0),
            "ability": ("ability", 0, 1),
            "skill": ("ability", 0, 1),
            "ability_point": ("ability", 0, 1),
            "技能点": ("ability", 0, 1),
            "能力点": ("ability", 0, 1),
        }
        result = aliases.get(normalized)
        if result is None:
            raise ChaoxingAPIError(
                "knowledge-graph node_type must be knowledge, category, or ability"
            )
        return result

    def _knowledge_graph_default_model(
        self,
        context: dict[str, Any],
        query: str = "",
    ) -> dict[str, Any]:
        models = self._normalize_knowledge_graph_models(
            self._knowledge_graph_topic_setting_data(context)
        )
        if query:
            return self._resolve_knowledge_graph_model(models, query)
        candidates = [item for item in models if item["mode_type"] == 1]
        selected = next((item for item in candidates if item["is_default"]), None)
        selected = selected or (candidates[0] if candidates else None)
        if selected is None:
            raise ChaoxingAPIError("the course exposes no knowledge-graph model")
        return selected

    def create_knowledge_graph_node(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        name: str,
        *,
        node_type: str = "knowledge",
        parent: str = "",
        description: str = "",
        model: str = "",
    ) -> dict[str, Any]:
        normalized_name = self._validate_knowledge_graph_text(name, "knowledge-graph node name")
        normalized_description = str(description or "").strip()
        kind, add_node_type, is_ability_point = self._knowledge_graph_node_type(node_type)
        context = self._knowledge_graph_context(course, clazz)
        selected_model = self._knowledge_graph_default_model(context, str(model or "").strip())
        before_graph = self._normalize_knowledge_graph(self._knowledge_graph_raw_data(context))
        roots = [item for item in before_graph["nodes"] if item["is_root"]]
        if len(roots) != 1:
            raise ChaoxingAPIError("the course graph did not expose one unambiguous root node")
        parent_node = (
            self._resolve_knowledge_graph_node(before_graph["nodes"], str(parent), allow_root=True)
            if str(parent or "").strip()
            else roots[0]
        )
        before_ids = {item["node_id"] for item in before_graph["nodes"]}
        returned_id = ""
        created: dict[str, Any] | None = None
        try:
            payload = self._knowledge_graph_json_request(
                context,
                "/mooc2-ans/questionBankTopic/addtopic",
                "knowledge-graph node create",
                method="POST",
                data={
                    "courseid": course["course_id"],
                    "cpi": course["cpi"],
                    "clazzId": clazz["clazz_id"],
                    "topic": normalized_name,
                    "addTopicType": 1,
                    "curOperateTopicId": parent_node["topic_id"] or 0,
                    "addNodeType": add_node_type,
                    "topicModelId": selected_model["model_id"],
                    "citeTopicId": "",
                    "isAbilityPoint": is_ability_point,
                },
            )
            self._knowledge_graph_ack(payload, "knowledge-graph node create")
            returned_id = str(payload.get("topicId") or payload.get("realtTopicId") or "").strip()

            for _ in range(8):
                nodes = self._normalize_knowledge_graph(self._knowledge_graph_raw_data(context))[
                    "nodes"
                ]

                def type_matches(item: dict[str, Any]) -> bool:
                    is_category = int(item.get("pile") or 0) == 1
                    if kind == "category":
                        return is_category
                    if kind == "ability":
                        return not is_category and bool(item.get("tags"))
                    return not is_category

                matches = [
                    item
                    for item in nodes
                    if not item["is_root"]
                    and item["node_id"] not in before_ids
                    and item["name"] == normalized_name
                    and item["parent_id"] == parent_node["node_id"]
                    and type_matches(item)
                    and (not returned_id or returned_id in {item["node_id"], item["topic_id"]})
                ]
                if len(matches) == 1:
                    created = matches[0]
                    break
                sleep(0.25)
            if created is None:
                raise ChaoxingAPIError(
                    "server acknowledged node creation, but one new node with the requested "
                    "name, type, parent, and returned ID was not visible"
                )

            if normalized_description:
                description_payload = self._knowledge_graph_json_request(
                    context,
                    "/mooc2-ans/questionBankTopic/updatenameanddesc",
                    "knowledge-graph node description update",
                    method="POST",
                    data={
                        "courseid": course["course_id"],
                        "cpi": course["cpi"],
                        "scenarioType": 1,
                        "topicId": created["topic_id"],
                        "topicName": normalized_name,
                        "topicDesc": normalized_description,
                    },
                )
                self._knowledge_graph_ack(
                    description_payload, "knowledge-graph node description update"
                )
        except ChaoxingAPIError as exc:
            cleanup_id = (created or {}).get("topic_id") or returned_id
            cleanup_note = ""
            if cleanup_id:
                try:
                    cleanup_payload = self._knowledge_graph_json_request(
                        context,
                        "/mooc2-ans/questionBankTopic/deleteTopic",
                        "knowledge-graph node create cleanup",
                        params={
                            **context["common"],
                            "scenarioType": 1,
                            "topicId": cleanup_id,
                        },
                    )
                    self._knowledge_graph_ack(
                        cleanup_payload, "knowledge-graph node create cleanup"
                    )
                    cleanup_note = "; the partially created node was deleted"
                except ChaoxingAPIError as cleanup_exc:
                    cleanup_note = f"; automatic cleanup failed: {cleanup_exc}"
            raise ChaoxingAPIError(
                f"knowledge-graph node creation failed: {exc}{cleanup_note}"
            ) from exc

        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "node": created,
            "node_type": kind,
            "parent": parent_node,
            "model": selected_model,
            "description": normalized_description,
            "verification": (
                "a fresh graph exposed exactly one new node with the requested stable ID, "
                "name, server type marker, and parent"
            ),
            "description_verification": (
                "the description endpoint acknowledged the value"
                if normalized_description
                else "no description was requested"
            ),
        }

    def update_knowledge_graph_node(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        node: str,
        name: str,
        *,
        description: str = "",
    ) -> dict[str, Any]:
        normalized_name = self._validate_knowledge_graph_text(name, "knowledge-graph node name")
        normalized_description = str(description or "").strip()
        context = self._knowledge_graph_context(course, clazz)
        graph = self._normalize_knowledge_graph(self._knowledge_graph_raw_data(context))
        selected = self._resolve_knowledge_graph_node(graph["nodes"], node)
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/questionBankTopic/updatenameanddesc",
            "knowledge-graph node update",
            method="POST",
            data={
                "courseid": course["course_id"],
                "cpi": course["cpi"],
                "scenarioType": 1,
                "topicId": selected["topic_id"],
                "topicName": normalized_name,
                "topicDesc": normalized_description,
            },
        )
        self._knowledge_graph_ack(payload, "knowledge-graph node update")
        refreshed = self._resolve_knowledge_graph_node(
            self._normalize_knowledge_graph(self._knowledge_graph_raw_data(context))["nodes"],
            selected["node_id"],
        )
        if refreshed["name"] != normalized_name:
            raise ChaoxingAPIError(
                "server acknowledged node update, but the refreshed name did not match"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "before": selected,
            "node": refreshed,
            "description": normalized_description,
            "verification": "the node name was refreshed by stable node ID",
            "description_verification": "the description endpoint acknowledged the value",
        }

    def _knowledge_graph_relation_html(
        self,
        context: dict[str, Any],
        topic_id: str,
    ) -> str:
        url = MOOC2_BASE_URL + "/mooc2-ans/questionBankTopic/relatedtopicrelationlist"
        try:
            response = context["session"].get(
                url,
                params={
                    "courseid": context["common"]["courseid"],
                    "cpi": context["common"]["cpi"],
                    "topicId": topic_id,
                },
                headers={
                    "Referer": context["referer"],
                    "X-Requested-With": "XMLHttpRequest",
                },
                timeout=self.timeout,
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(
                f"knowledge-graph node relation read request failed: {exc}"
            ) from exc
        if "passport" in str(response.url or "").lower():
            raise ChaoxingAPIError("knowledge-graph node relation read requires a valid session")
        return self._decode(response)

    @staticmethod
    def _knowledge_graph_relation_kind(relation_id: str) -> str:
        return {
            "0": "association",
            "1": "predecessor",
            "2": "successor",
        }.get(str(relation_id), "custom")

    def _knowledge_graph_node_relation_state(
        self,
        context: dict[str, Any],
        graph: dict[str, Any],
        node: dict[str, Any],
    ) -> dict[str, Any]:
        parsed = parse_knowledge_graph_relation_html(
            self._knowledge_graph_relation_html(context, node["topic_id"])
        )
        definitions = self._normalize_knowledge_graph_relation_types(
            self._knowledge_graph_config_data(context)
        )
        definitions_by_id = {item["relation_id"]: item for item in definitions}
        nodes_by_topic = {item["topic_id"]: item for item in graph["nodes"] if item.get("topic_id")}
        default_names = {
            "0": "关联关系",
            "1": "前置关系",
            "2": "后置关系",
        }
        ordered_ids: list[str] = []
        for relation_id in ("1", "2", "0"):
            if relation_id not in ordered_ids:
                ordered_ids.append(relation_id)
        for relation in definitions:
            if relation["relation_id"] not in ordered_ids:
                ordered_ids.append(relation["relation_id"])
        for relation_id in parsed:
            if relation_id not in ordered_ids:
                ordered_ids.append(relation_id)

        groups: dict[str, list[dict[str, Any]]] = {}
        relation_groups: list[dict[str, Any]] = []
        for relation_id in ordered_ids:
            items: list[dict[str, Any]] = []
            for raw in parsed.get(relation_id, []):
                target = nodes_by_topic.get(raw["topic_id"])
                items.append(
                    {
                        "topic_id": raw["topic_id"],
                        "name": raw["name"] or (target or {}).get("name", ""),
                        "description": raw["description"],
                        "target_node_id": (target or {}).get("node_id", raw["topic_id"]),
                        "target_path": (target or {}).get("path", ""),
                    }
                )
            groups[relation_id] = items
            definition = definitions_by_id.get(relation_id)
            relation_groups.append(
                {
                    "relation_id": relation_id,
                    "name": (definition or {}).get("name")
                    or default_names.get(relation_id, f"自定义关系 {relation_id}"),
                    "kind": self._knowledge_graph_relation_kind(relation_id),
                    "count": len(items),
                    "relations": items,
                }
            )
        return {
            "node": node,
            "groups": groups,
            "relation_groups": relation_groups,
            "relation_count": sum(len(items) for items in groups.values()),
            "relation_types": definitions,
        }

    def read_knowledge_graph_node_relations(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        node: str,
    ) -> dict[str, Any]:
        context = self._knowledge_graph_context(course, clazz)
        graph = self._normalize_knowledge_graph(self._knowledge_graph_raw_data(context))
        selected = self._resolve_knowledge_graph_node(graph["nodes"], node)
        state = self._knowledge_graph_node_relation_state(context, graph, selected)
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "node": selected,
            "relation_count": state["relation_count"],
            "relation_groups": state["relation_groups"],
            "relation_types": state["relation_types"],
            "verification": "node relations refreshed from the authenticated outline editor API",
        }

    def _resolve_knowledge_graph_node_relation_type(
        self,
        definitions: list[dict[str, Any]],
        query: str,
    ) -> dict[str, Any]:
        normalized = str(query or "").strip().lower().replace("_", " ")
        aliases = {
            "0": "0",
            "association": "0",
            "related": "0",
            "关联": "0",
            "关联关系": "0",
            "1": "1",
            "predecessor": "1",
            "previous": "1",
            "前置": "1",
            "前置关系": "1",
            "2": "2",
            "successor": "2",
            "following": "2",
            "后置": "2",
            "后置关系": "2",
        }
        relation_id = aliases.get(normalized)
        if relation_id is not None:
            existing = next(
                (item for item in definitions if item["relation_id"] == relation_id), None
            )
            return existing or {
                "relation_id": relation_id,
                "name": {"0": "关联关系", "1": "前置关系", "2": "后置关系"}[relation_id],
                "is_default": True,
            }
        return self._resolve_knowledge_graph_relation_type(definitions, query)

    @staticmethod
    def _knowledge_graph_relation_signature(
        groups: dict[str, list[dict[str, Any]]],
    ) -> dict[str, tuple[tuple[str, str], ...]]:
        return {
            str(relation_id): tuple(
                sorted(
                    (
                        str(item.get("topic_id") or ""),
                        str(item.get("description") or "") if str(relation_id) == "0" else "",
                    )
                    for item in items
                )
            )
            for relation_id, items in groups.items()
            if items
        }

    def _send_knowledge_graph_node_relations(
        self,
        context: dict[str, Any],
        node: dict[str, Any],
        groups: dict[str, list[dict[str, Any]]],
        operation: str,
    ) -> None:
        def comma_values(values: list[str]) -> str:
            return ",".join(values) + ("," if values else "")

        association = groups.get("0", [])
        custom = {
            str(relation_id): [str(item.get("topic_id") or "") for item in items]
            for relation_id, items in groups.items()
            if str(relation_id) not in {"0", "1", "2"}
        }
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/questionBankTopic/updatetopicrelation",
            operation,
            params={
                "courseid": context["common"]["courseid"],
                "cpi": context["common"]["cpi"],
                "topicId": node["topic_id"],
                "relationTopicIds": comma_values(
                    [str(item.get("topic_id") or "") for item in association]
                ),
                "relationTopicPrevIds": comma_values(
                    [str(item.get("topic_id") or "") for item in groups.get("1", [])]
                ),
                "relationTopicNextIds": comma_values(
                    [str(item.get("topic_id") or "") for item in groups.get("2", [])]
                ),
                "relationDesc": ",".join(
                    str(item.get("description") or "") for item in association
                ),
                "selfDefineTopicsMap": json.dumps(
                    custom, ensure_ascii=False, separators=(",", ":")
                ),
            },
        )
        self._knowledge_graph_ack(payload, operation)

    def _replace_knowledge_graph_node_relations(
        self,
        context: dict[str, Any],
        graph: dict[str, Any],
        node: dict[str, Any],
        desired_groups: dict[str, list[dict[str, Any]]],
        original_groups: dict[str, list[dict[str, Any]]],
    ) -> dict[str, Any]:
        self._send_knowledge_graph_node_relations(
            context,
            node,
            desired_groups,
            "knowledge-graph node relation update",
        )
        refreshed = self._knowledge_graph_node_relation_state(context, graph, node)
        expected_signature = self._knowledge_graph_relation_signature(desired_groups)
        actual_signature = self._knowledge_graph_relation_signature(refreshed["groups"])
        if actual_signature != expected_signature:
            rollback_note = ""
            try:
                self._send_knowledge_graph_node_relations(
                    context,
                    node,
                    original_groups,
                    "knowledge-graph node relation rollback",
                )
                rolled_back = self._knowledge_graph_node_relation_state(context, graph, node)
                if self._knowledge_graph_relation_signature(
                    rolled_back["groups"]
                ) != self._knowledge_graph_relation_signature(original_groups):
                    rollback_note = (
                        "; rollback was acknowledged but did not restore the original set"
                    )
                else:
                    rollback_note = "; the original relation set was restored"
            except ChaoxingAPIError as rollback_exc:
                rollback_note = f"; rollback failed: {rollback_exc}"
            raise ChaoxingAPIError(
                "server acknowledged node relations, but the refreshed relation set differed"
                f"{rollback_note}"
            )
        return refreshed

    @staticmethod
    def _copy_knowledge_graph_relation_groups(
        groups: dict[str, list[dict[str, Any]]],
    ) -> dict[str, list[dict[str, Any]]]:
        return {
            str(relation_id): [dict(item) for item in items]
            for relation_id, items in groups.items()
        }

    def add_knowledge_graph_node_relation(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        node: str,
        relation: str,
        target: str,
        *,
        description: str = "",
    ) -> dict[str, Any]:
        context = self._knowledge_graph_context(course, clazz)
        graph = self._normalize_knowledge_graph(self._knowledge_graph_raw_data(context))
        selected = self._resolve_knowledge_graph_node(graph["nodes"], node)
        target_node = self._resolve_knowledge_graph_node(graph["nodes"], target)
        if selected["topic_id"] == target_node["topic_id"]:
            raise ChaoxingAPIError("a knowledge-graph node cannot relate to itself")
        before = self._knowledge_graph_node_relation_state(context, graph, selected)
        relation_type = self._resolve_knowledge_graph_node_relation_type(
            before["relation_types"], relation
        )
        relation_id = str(relation_type["relation_id"])
        normalized_description = str(description or "").strip()
        if normalized_description and relation_id != "0":
            raise ChaoxingAPIError(
                "relation descriptions are supported only for association relations"
            )
        if len(normalized_description) > 20:
            raise ChaoxingAPIError("association relation description must not exceed 20 characters")
        if "," in normalized_description:
            raise ChaoxingAPIError("association relation description must not contain a comma")

        locations = [
            relation_key
            for relation_key, items in before["groups"].items()
            if any(item["topic_id"] == target_node["topic_id"] for item in items)
        ]
        if locations and any(item != relation_id for item in locations):
            raise ChaoxingAPIError(
                "the target node already uses a different relation with this source: "
                + ", ".join(locations)
            )
        existing = next(
            (
                item
                for item in before["groups"].get(relation_id, [])
                if item["topic_id"] == target_node["topic_id"]
            ),
            None,
        )
        if existing and (
            relation_id != "0"
            or not normalized_description
            or existing.get("description") == normalized_description
        ):
            return {
                "course_id": course["course_id"],
                "clazz_id": clazz["clazz_id"],
                "node": selected,
                "relation_type": relation_type,
                "target": target_node,
                "changed": False,
                "relation_count": before["relation_count"],
                "relation_groups": before["relation_groups"],
                "verification": "the requested relation already existed in a fresh response",
            }

        desired = self._copy_knowledge_graph_relation_groups(before["groups"])
        desired.setdefault(relation_id, [])
        if existing:
            for item in desired[relation_id]:
                if item["topic_id"] == target_node["topic_id"]:
                    item["description"] = normalized_description
        else:
            desired[relation_id].append(
                {
                    "topic_id": target_node["topic_id"],
                    "name": target_node["name"],
                    "description": normalized_description,
                    "target_node_id": target_node["node_id"],
                    "target_path": target_node["path"],
                }
            )
        refreshed = self._replace_knowledge_graph_node_relations(
            context,
            graph,
            selected,
            desired,
            self._copy_knowledge_graph_relation_groups(before["groups"]),
        )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "node": selected,
            "relation_type": relation_type,
            "target": target_node,
            "description": normalized_description,
            "changed": True,
            "relation_count": refreshed["relation_count"],
            "relation_groups": refreshed["relation_groups"],
            "verification": (
                "the exact relation set and association description matched a fresh response"
            ),
        }

    def remove_knowledge_graph_node_relation(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        node: str,
        relation: str,
        target: str,
    ) -> dict[str, Any]:
        context = self._knowledge_graph_context(course, clazz)
        graph = self._normalize_knowledge_graph(self._knowledge_graph_raw_data(context))
        selected = self._resolve_knowledge_graph_node(graph["nodes"], node)
        target_node = self._resolve_knowledge_graph_node(graph["nodes"], target)
        before = self._knowledge_graph_node_relation_state(context, graph, selected)
        relation_type = self._resolve_knowledge_graph_node_relation_type(
            before["relation_types"], relation
        )
        relation_id = str(relation_type["relation_id"])
        found = any(
            item["topic_id"] == target_node["topic_id"]
            for item in before["groups"].get(relation_id, [])
        )
        if not found:
            return {
                "course_id": course["course_id"],
                "clazz_id": clazz["clazz_id"],
                "node": selected,
                "relation_type": relation_type,
                "target": target_node,
                "changed": False,
                "relation_count": before["relation_count"],
                "relation_groups": before["relation_groups"],
                "verification": "the requested relation was already absent from a fresh response",
            }
        desired = self._copy_knowledge_graph_relation_groups(before["groups"])
        desired[relation_id] = [
            item
            for item in desired.get(relation_id, [])
            if item["topic_id"] != target_node["topic_id"]
        ]
        refreshed = self._replace_knowledge_graph_node_relations(
            context,
            graph,
            selected,
            desired,
            self._copy_knowledge_graph_relation_groups(before["groups"]),
        )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "node": selected,
            "relation_type": relation_type,
            "target": target_node,
            "changed": True,
            "relation_count": refreshed["relation_count"],
            "relation_groups": refreshed["relation_groups"],
            "verification": "the exact relation set was absent in a fresh response",
        }

    def create_knowledge_graph_category(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        name: str,
        *,
        description: str = "",
    ) -> dict[str, Any]:
        normalized_name = self._validate_knowledge_graph_text(name, "knowledge-graph category name")
        normalized_description = str(description or "").strip()
        context = self._knowledge_graph_context(course, clazz)
        before = self._normalize_knowledge_graph(self._knowledge_graph_raw_data(context))["nodes"]
        before_ids = {item["node_id"] for item in before}
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/questionBankTopic/addtopicwithexpand",
            "knowledge-graph category create",
            method="POST",
            data={
                "courseId": course["course_id"],
                "cpi": course["cpi"],
                "scenarioType": 1,
                "addTopicType": 1,
                "curOperateTopicId": 0,
                "addNodeType": 1,
                "topicModelId": 0,
                "topicName": normalized_name,
                "topicDesc": normalized_description,
            },
        )
        self._knowledge_graph_ack(payload, "knowledge-graph category create")
        returned_id = str(payload.get("topicId") or payload.get("realtTopicId") or "").strip()
        created: dict[str, Any] | None = None
        for _ in range(8):
            nodes = self._normalize_knowledge_graph(self._knowledge_graph_raw_data(context))[
                "nodes"
            ]
            matches = [
                item
                for item in nodes
                if not item["is_root"]
                and item["node_id"] not in before_ids
                and item["name"] == normalized_name
                and (not returned_id or returned_id in {item["node_id"], item["topic_id"]})
            ]
            if len(matches) == 1:
                created = matches[0]
                break
            sleep(0.25)
        if created is None:
            raise ChaoxingAPIError(
                "server acknowledged category creation, but the new node was not uniquely visible"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "category": created,
            "description": normalized_description,
            "verification": "a fresh graph exposed one new category with the returned ID and name",
        }

    def update_knowledge_graph_category(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        node: str,
        name: str,
        *,
        description: str = "",
    ) -> dict[str, Any]:
        normalized_name = self._validate_knowledge_graph_text(name, "knowledge-graph category name")
        normalized_description = str(description or "").strip()
        context = self._knowledge_graph_context(course, clazz)
        graph = self._normalize_knowledge_graph(self._knowledge_graph_raw_data(context))
        selected = self._resolve_knowledge_graph_node(graph["nodes"], node)
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/questionBankTopic/updatenameanddesc",
            "knowledge-graph category update",
            method="POST",
            data={
                "courseid": course["course_id"],
                "cpi": course["cpi"],
                "scenarioType": 1,
                "topicId": selected["topic_id"],
                "topicName": normalized_name,
                "topicDesc": normalized_description,
            },
        )
        self._knowledge_graph_ack(payload, "knowledge-graph category update")
        refreshed = self._resolve_knowledge_graph_node(
            self._normalize_knowledge_graph(self._knowledge_graph_raw_data(context))["nodes"],
            selected["node_id"],
        )
        if refreshed["name"] != normalized_name:
            raise ChaoxingAPIError(
                "server acknowledged category update, but the refreshed name did not match"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "before": selected,
            "category": refreshed,
            "description": normalized_description,
            "verification": "the category name was refreshed by stable node ID",
        }

    def delete_knowledge_graph_node(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        node: str,
    ) -> dict[str, Any]:
        context = self._knowledge_graph_context(course, clazz)
        graph = self._normalize_knowledge_graph(self._knowledge_graph_raw_data(context))
        selected = self._resolve_knowledge_graph_node(graph["nodes"], node)
        descendants: list[dict[str, Any]] = []
        pending = list(selected["children_ids"])
        by_id = {item["node_id"]: item for item in graph["nodes"]}
        seen: set[str] = set()
        while pending:
            child_id = pending.pop(0)
            if child_id in seen:
                continue
            seen.add(child_id)
            child = by_id.get(child_id)
            if child:
                descendants.append(child)
                pending.extend(child["children_ids"])
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/questionBankTopic/deleteTopic",
            "knowledge-graph node delete",
            params={**context["common"], "scenarioType": 1, "topicId": selected["topic_id"]},
        )
        self._knowledge_graph_ack(payload, "knowledge-graph node delete")
        remaining = self._normalize_knowledge_graph(self._knowledge_graph_raw_data(context))[
            "nodes"
        ]
        deleted_ids = {selected["node_id"], *(item["node_id"] for item in descendants)}
        if any(item["node_id"] in deleted_ids for item in remaining):
            raise ChaoxingAPIError(
                "server acknowledged node deletion, but the node or a descendant remains visible"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "deleted_node": selected,
            "deleted_descendant_count": len(descendants),
            "deleted_descendants": descendants,
            "verification": "the node and all graph descendants are absent from a fresh graph",
        }

    @staticmethod
    def _normalize_knowledge_graph_label_groups(payload: dict[str, Any]) -> list[dict[str, Any]]:
        data = payload.get("data") if isinstance(payload.get("data"), dict) else {}
        raw_groups = (
            data.get("topicLabelGroupArray")
            if isinstance(data.get("topicLabelGroupArray"), list)
            else []
        )
        groups: list[dict[str, Any]] = []
        for raw in raw_groups:
            if not isinstance(raw, dict):
                continue
            group_id = str(raw.get("labelGroupId") or "").strip()
            if not group_id:
                continue
            raw_labels = (
                raw.get("topicLabelArray") if isinstance(raw.get("topicLabelArray"), list) else []
            )
            labels: list[dict[str, Any]] = []
            for label_raw in raw_labels:
                if not isinstance(label_raw, dict):
                    continue
                label_id = str(label_raw.get("id") or "").strip()
                if not label_id:
                    continue
                labels.append(
                    {
                        "index": len(labels) + 1,
                        "label_id": label_id,
                        "group_id": group_id,
                        "name": str(label_raw.get("name") or "").strip(),
                        "precast": bool(label_raw.get("precastLabel")),
                        "course_id": str(label_raw.get("courseId") or ""),
                        "raw": label_raw,
                    }
                )
            groups.append(
                {
                    "index": len(groups) + 1,
                    "group_id": group_id,
                    "name": str(raw.get("labelGroupName") or "").strip(),
                    "is_default": bool(raw.get("isDefault")),
                    "group_type": _numeric_or_text(str(raw.get("labelgrouptype") or "0")),
                    "label_use_group_id": str(raw.get("labelUseGroupId") or ""),
                    "label_count": len(labels),
                    "labels": labels,
                    "raw": raw,
                }
            )
        return groups

    def _knowledge_graph_label_groups(self, context: dict[str, Any]) -> list[dict[str, Any]]:
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/coursetopic/getlabelandgroupdata",
            "knowledge-graph label read",
            params=dict(context["common"]),
        )
        self._knowledge_graph_ack(payload, "knowledge-graph label read")
        return self._normalize_knowledge_graph_label_groups(payload)

    @staticmethod
    def _resolve_knowledge_graph_label_group(
        groups: list[dict[str, Any]], query: str
    ) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("knowledge-graph label-group index, ID, or name is required")
        for key in ("group_id", "index"):
            matches = [
                item for item in groups if str(item.get(key) or "").strip().lower() == normalized
            ]
            if len(matches) == 1:
                return matches[0]
        exact = [item for item in groups if item["name"].lower() == normalized]
        partial = [item for item in groups if normalized in item["name"].lower()]
        matches = exact if len(exact) != 0 else partial
        if len(matches) == 1:
            return matches[0]
        if not matches:
            raise ChaoxingAPIError(f"knowledge-graph label group not found: {query}")
        labels = ", ".join(
            f"{item['index']}. {item['name']} ({item['group_id']})" for item in matches[:10]
        )
        raise ChaoxingAPIError(f"multiple knowledge-graph label groups match: {labels}")

    @staticmethod
    def _resolve_knowledge_graph_label(
        groups: list[dict[str, Any]], query: str, *, group_id: str = ""
    ) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("knowledge-graph label index, ID, or name is required")
        labels = [
            label
            for group in groups
            if not group_id or group["group_id"] == group_id
            for label in group["labels"]
        ]
        for key in ("label_id", "index"):
            matches = [
                item for item in labels if str(item.get(key) or "").strip().lower() == normalized
            ]
            if len(matches) == 1:
                return matches[0]
        exact = [item for item in labels if item["name"].lower() == normalized]
        partial = [item for item in labels if normalized in item["name"].lower()]
        matches = exact if len(exact) != 0 else partial
        if len(matches) == 1:
            return matches[0]
        if not matches:
            raise ChaoxingAPIError(f"knowledge-graph label not found: {query}")
        labels_text = ", ".join(f"{item['name']} ({item['label_id']})" for item in matches[:10])
        raise ChaoxingAPIError(f"multiple knowledge-graph labels match: {labels_text}")

    def list_knowledge_graph_labels(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        search: str = "",
    ) -> dict[str, Any]:
        groups = self._knowledge_graph_label_groups(self._knowledge_graph_context(course, clazz))
        normalized_search = str(search or "").strip().lower()
        if normalized_search:
            filtered: list[dict[str, Any]] = []
            for group in groups:
                matching_labels = [
                    label for label in group["labels"] if normalized_search in label["name"].lower()
                ]
                if normalized_search in group["name"].lower() or matching_labels:
                    filtered.append(
                        {**group, "labels": matching_labels, "label_count": len(matching_labels)}
                    )
            groups = filtered
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "search": normalized_search,
            "count": len(groups),
            "label_count": sum(len(group["labels"]) for group in groups),
            "groups": groups,
            "verification": "label groups and labels refreshed from the authenticated graph API",
        }

    @staticmethod
    def _validate_knowledge_graph_label_name(name: str, label: str) -> str:
        return ChaoxingAPI._validate_knowledge_graph_text(name, label, 10)

    def create_knowledge_graph_label_group(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        name: str,
        *,
        group_type: int = 0,
    ) -> dict[str, Any]:
        normalized_name = self._validate_knowledge_graph_label_name(
            name, "knowledge-graph label-group name"
        )
        if int(group_type) not in {0, 1, 2}:
            raise ChaoxingAPIError("knowledge-graph label-group type must be 0, 1, or 2")
        context = self._knowledge_graph_context(course, clazz)
        before = self._knowledge_graph_label_groups(context)
        before_ids = {item["group_id"] for item in before}
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/coursetopic/createlabelgroup",
            "knowledge-graph label-group create",
            params={
                **context["common"],
                "name": normalized_name,
                "labelgrouptype": int(group_type),
            },
        )
        self._knowledge_graph_ack(payload, "knowledge-graph label-group create")
        matches = [
            item
            for item in self._knowledge_graph_label_groups(context)
            if item["group_id"] not in before_ids and item["name"] == normalized_name
        ]
        if len(matches) != 1:
            raise ChaoxingAPIError(
                "server acknowledged label-group creation, but the new group was not "
                "uniquely visible"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "group": matches[0],
            "verification": "one new label group appeared in a fresh listing",
        }

    def rename_knowledge_graph_label_group(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        group: str,
        name: str,
    ) -> dict[str, Any]:
        normalized_name = self._validate_knowledge_graph_label_name(
            name, "knowledge-graph label-group name"
        )
        context = self._knowledge_graph_context(course, clazz)
        selected = self._resolve_knowledge_graph_label_group(
            self._knowledge_graph_label_groups(context), group
        )
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/coursetopic/updatelabelgroupname",
            "knowledge-graph label-group rename",
            params={
                **context["common"],
                "name": normalized_name,
                "labelgroupid": selected["group_id"],
            },
        )
        self._knowledge_graph_ack(payload, "knowledge-graph label-group rename")
        refreshed = self._resolve_knowledge_graph_label_group(
            self._knowledge_graph_label_groups(context), selected["group_id"]
        )
        if refreshed["name"] != normalized_name:
            raise ChaoxingAPIError(
                "server acknowledged label-group rename, but the refreshed name did not match"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "before": selected,
            "group": refreshed,
            "verification": "the refreshed label group has the requested name",
        }

    def delete_knowledge_graph_label_group(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        group: str,
    ) -> dict[str, Any]:
        context = self._knowledge_graph_context(course, clazz)
        selected = self._resolve_knowledge_graph_label_group(
            self._knowledge_graph_label_groups(context), group
        )
        if selected["is_default"]:
            raise ChaoxingAPIError("the default knowledge-graph label group cannot be deleted")
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/coursetopic/deletelabelgroup",
            "knowledge-graph label-group delete",
            params={**context["common"], "labelgroupid": selected["group_id"]},
        )
        self._knowledge_graph_ack(payload, "knowledge-graph label-group delete")
        if any(
            item["group_id"] == selected["group_id"]
            for item in self._knowledge_graph_label_groups(context)
        ):
            raise ChaoxingAPIError(
                "server acknowledged label-group deletion, but the group remains visible"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "deleted_group": selected,
            "deleted_label_count": selected["label_count"],
            "verification": (
                "the label group and its contained labels are absent from a fresh listing"
            ),
        }

    def reorder_knowledge_graph_label_groups(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        group_order: list[str],
    ) -> dict[str, Any]:
        context = self._knowledge_graph_context(course, clazz)
        groups = self._knowledge_graph_label_groups(context)
        resolved = [self._resolve_knowledge_graph_label_group(groups, item) for item in group_order]
        if len({item["group_id"] for item in resolved}) != len(resolved):
            raise ChaoxingAPIError("group_order contains duplicate label groups")
        if {item["group_id"] for item in resolved} != {item["group_id"] for item in groups}:
            raise ChaoxingAPIError("group_order must contain every label group once")
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/coursetopic/updatelabelgroupsort",
            "knowledge-graph label-group reorder",
            params={
                **context["common"],
                "labelGroupIds": ",".join(item["group_id"] for item in resolved),
            },
        )
        self._knowledge_graph_ack(payload, "knowledge-graph label-group reorder")
        refreshed = self._knowledge_graph_label_groups(context)
        if [item["group_id"] for item in refreshed] != [item["group_id"] for item in resolved]:
            raise ChaoxingAPIError(
                "server acknowledged label-group reorder, but the refreshed order did not match"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "groups": refreshed,
            "verification": "the refreshed label-group order matches the complete request",
        }

    def create_knowledge_graph_label(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        group: str,
        name: str,
    ) -> dict[str, Any]:
        normalized_name = self._validate_knowledge_graph_label_name(
            name, "knowledge-graph label name"
        )
        context = self._knowledge_graph_context(course, clazz)
        groups = self._knowledge_graph_label_groups(context)
        selected_group = self._resolve_knowledge_graph_label_group(groups, group)
        before_ids = {label["label_id"] for item in groups for label in item["labels"]}
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/questionBankTopic/addtopiclable",
            "knowledge-graph label create",
            params={
                **context["common"],
                "courseId": course["course_id"],
                "name": normalized_name,
                "labelGroupId": selected_group["group_id"],
            },
        )
        self._knowledge_graph_ack(payload, "knowledge-graph label create")
        returned_id = str(payload.get("saveTopiclabelId") or "").strip()
        refreshed_groups = self._knowledge_graph_label_groups(context)
        matches = [
            label
            for item in refreshed_groups
            if item["group_id"] == selected_group["group_id"]
            for label in item["labels"]
            if label["label_id"] not in before_ids
            and label["name"] == normalized_name
            and (not returned_id or label["label_id"] == returned_id)
        ]
        if len(matches) != 1:
            raise ChaoxingAPIError(
                "server acknowledged label creation, but the new label was not uniquely visible"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "group": self._resolve_knowledge_graph_label_group(
                refreshed_groups, selected_group["group_id"]
            ),
            "label": matches[0],
            "verification": "one new label appeared in the requested group",
        }

    def rename_knowledge_graph_label(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        label: str,
        name: str,
    ) -> dict[str, Any]:
        normalized_name = self._validate_knowledge_graph_label_name(
            name, "knowledge-graph label name"
        )
        context = self._knowledge_graph_context(course, clazz)
        selected = self._resolve_knowledge_graph_label(
            self._knowledge_graph_label_groups(context), label
        )
        if selected["precast"]:
            raise ChaoxingAPIError("preset knowledge-graph labels cannot be renamed")
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/questionBankTopic/updatetopiclabel",
            "knowledge-graph label rename",
            params={
                **context["common"],
                "courseId": course["course_id"],
                "name": normalized_name,
                "topicLabelId": selected["label_id"],
            },
        )
        self._knowledge_graph_ack(payload, "knowledge-graph label rename")
        refreshed = self._resolve_knowledge_graph_label(
            self._knowledge_graph_label_groups(context), selected["label_id"]
        )
        if refreshed["name"] != normalized_name:
            raise ChaoxingAPIError(
                "server acknowledged label rename, but the refreshed name did not match"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "before": selected,
            "label": refreshed,
            "verification": "the refreshed label has the requested name",
        }

    def move_knowledge_graph_label(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        label: str,
        group: str,
    ) -> dict[str, Any]:
        context = self._knowledge_graph_context(course, clazz)
        groups = self._knowledge_graph_label_groups(context)
        selected = self._resolve_knowledge_graph_label(groups, label)
        target = self._resolve_knowledge_graph_label_group(groups, group)
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/coursetopic/updatelabelbelonggroup",
            "knowledge-graph label move",
            params={
                **context["common"],
                "labelid": selected["label_id"],
                "labelgroupid": target["group_id"],
            },
        )
        self._knowledge_graph_ack(payload, "knowledge-graph label move")
        refreshed = self._resolve_knowledge_graph_label(
            self._knowledge_graph_label_groups(context), selected["label_id"]
        )
        if refreshed["group_id"] != target["group_id"]:
            raise ChaoxingAPIError(
                "server acknowledged label move, but the refreshed group did not match"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "label": refreshed,
            "group": target,
            "verification": "the refreshed label belongs to the requested group",
        }

    def reorder_knowledge_graph_labels(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        group: str,
        label_order: list[str],
    ) -> dict[str, Any]:
        context = self._knowledge_graph_context(course, clazz)
        groups = self._knowledge_graph_label_groups(context)
        selected_group = self._resolve_knowledge_graph_label_group(groups, group)
        resolved = [
            self._resolve_knowledge_graph_label(groups, item, group_id=selected_group["group_id"])
            for item in label_order
        ]
        if len({item["label_id"] for item in resolved}) != len(resolved):
            raise ChaoxingAPIError("label_order contains duplicate labels")
        if {item["label_id"] for item in resolved} != {
            item["label_id"] for item in selected_group["labels"]
        }:
            raise ChaoxingAPIError("label_order must contain every label in the group once")
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/coursetopic/updatelabelsort",
            "knowledge-graph label reorder",
            params={
                **context["common"],
                "labelGroupId": selected_group["group_id"],
                "labelIds": ",".join(item["label_id"] for item in resolved),
            },
        )
        self._knowledge_graph_ack(payload, "knowledge-graph label reorder")
        refreshed_group = self._resolve_knowledge_graph_label_group(
            self._knowledge_graph_label_groups(context), selected_group["group_id"]
        )
        if [item["label_id"] for item in refreshed_group["labels"]] != [
            item["label_id"] for item in resolved
        ]:
            raise ChaoxingAPIError(
                "server acknowledged label reorder, but the refreshed order did not match"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "group": refreshed_group,
            "verification": "the refreshed label order matches the complete request",
        }

    def delete_knowledge_graph_label(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        label: str,
    ) -> dict[str, Any]:
        context = self._knowledge_graph_context(course, clazz)
        selected = self._resolve_knowledge_graph_label(
            self._knowledge_graph_label_groups(context), label
        )
        if selected["precast"]:
            raise ChaoxingAPIError("preset knowledge-graph labels cannot be deleted")
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/questionBankTopic/deletetopiclabel",
            "knowledge-graph label delete",
            params={
                **context["common"],
                "courseId": course["course_id"],
                "topicLabelId": selected["label_id"],
            },
        )
        self._knowledge_graph_ack(payload, "knowledge-graph label delete")
        groups = self._knowledge_graph_label_groups(context)
        if any(
            item["label_id"] == selected["label_id"] for group in groups for item in group["labels"]
        ):
            raise ChaoxingAPIError(
                "server acknowledged label deletion, but the label remains visible"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "deleted_label": selected,
            "verification": "the label is absent from a fresh listing",
        }

    @staticmethod
    def _normalize_knowledge_graph_events(payload: dict[str, Any]) -> list[dict[str, Any]]:
        def integer(value: Any, default: int = 0) -> int:
            try:
                return int(float(str(value).strip()))
            except (TypeError, ValueError):
                return default

        data = payload.get("data") if isinstance(payload.get("data"), dict) else {}
        raw_events = data.get("eventData") if isinstance(data.get("eventData"), list) else []
        topic_condition_names = {
            0: "knowledge_point_mastery_rate",
            1: "knowledge_point_completion_rate",
        }
        set_condition_names = {
            0: "equal",
            1: "greater_than",
            2: "less_than",
            3: "greater_than_or_equal",
            4: "less_than_or_equal",
            5: "empty",
            6: "not_empty",
            7: "between",
        }
        module_names = {0: "learning_path", 1: "microcourse_resources"}
        target_names = {0: "knowledge_point", 1: "resource"}
        events: list[dict[str, Any]] = []
        for raw in raw_events:
            if not isinstance(raw, dict):
                continue
            event_id = str(raw.get("id") or raw.get("eventId") or "").strip()
            if not event_id:
                continue
            topic_condition = integer(raw.get("topicCondition"), default=0)
            set_condition = integer(raw.get("setCondition"), default=0)
            raw_executions = (
                raw.get("exechteData") if isinstance(raw.get("exechteData"), list) else []
            )
            executions: list[dict[str, Any]] = []
            for execution in raw_executions:
                if not isinstance(execution, dict):
                    continue
                execute_module = integer(execution.get("executeModule"), default=0)
                tag_content = integer(execution.get("tagContent"), default=execute_module)
                executions.append(
                    {
                        "index": len(executions) + 1,
                        "label_id": str(execution.get("labelId") or "").strip(),
                        "label_name": str(execution.get("labelName") or "").strip(),
                        "execute_module": execute_module,
                        "execute_module_name": module_names.get(
                            execute_module, str(execute_module)
                        ),
                        "tag_content": tag_content,
                        "tag_content_name": target_names.get(tag_content, str(tag_content)),
                        "raw": execution,
                    }
                )
            events.append(
                {
                    "index": len(events) + 1,
                    "event_id": event_id,
                    "name": str(raw.get("name") or "").strip(),
                    "topic_condition": topic_condition,
                    "topic_condition_name": topic_condition_names.get(
                        topic_condition, str(topic_condition)
                    ),
                    "set_condition": set_condition,
                    "set_condition_name": set_condition_names.get(
                        set_condition, str(set_condition)
                    ),
                    "percent1": integer(raw.get("percent1"), default=0),
                    "percent2": integer(raw.get("percent2"), default=0),
                    "execution_count": len(executions),
                    "executions": executions,
                    "raw": raw,
                }
            )
        return events

    def _knowledge_graph_events(self, context: dict[str, Any]) -> list[dict[str, Any]]:
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/coursetopic/getalltopicevent",
            "knowledge-graph event read",
            params={
                "courseid": context["common"]["courseid"],
                "cpi": context["common"]["cpi"],
            },
        )
        self._knowledge_graph_ack(payload, "knowledge-graph event read")
        return self._normalize_knowledge_graph_events(payload)

    @staticmethod
    def _resolve_knowledge_graph_event(events: list[dict[str, Any]], query: str) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("knowledge-graph event index, ID, or name is required")
        for key in ("event_id", "index"):
            matches = [
                item for item in events if str(item.get(key) or "").strip().lower() == normalized
            ]
            if len(matches) == 1:
                return matches[0]
        exact = [item for item in events if item["name"].lower() == normalized]
        partial = [item for item in events if normalized in item["name"].lower()]
        matches = exact if exact else partial
        if len(matches) == 1:
            return matches[0]
        if not matches:
            raise ChaoxingAPIError(f"knowledge-graph event not found: {query}")
        labels = ", ".join(
            f"{item['index']}. {item['name']} ({item['event_id']})" for item in matches[:10]
        )
        raise ChaoxingAPIError(f"multiple knowledge-graph events match: {labels}")

    @staticmethod
    def _knowledge_graph_event_condition_value(value: Any, label: str) -> int:
        aliases = {
            "knowledge_point_mastery_rate": 0,
            "mastery": 0,
            "掌握率": 0,
            "知识点掌握率": 0,
            "knowledge_point_completion_rate": 1,
            "completion": 1,
            "完成率": 1,
            "知识点完成率": 1,
            "equal": 0,
            "等于": 0,
            "greater_than": 1,
            "大于": 1,
            "less_than": 2,
            "小于": 2,
            "greater_than_or_equal": 3,
            "大于等于": 3,
            "less_than_or_equal": 4,
            "小于等于": 4,
            "between": 7,
            "区间": 7,
            "为区间": 7,
        }
        normalized = str(value).strip().lower()
        if normalized in aliases:
            return aliases[normalized]
        try:
            return int(value)
        except (TypeError, ValueError) as exc:
            raise ChaoxingAPIError(f"invalid knowledge-graph event {label}: {value}") from exc

    def _knowledge_graph_event_executions(
        self,
        context: dict[str, Any],
        executions: list[dict[str, Any]],
    ) -> list[dict[str, Any]]:
        if not isinstance(executions, list) or not 1 <= len(executions) <= 3:
            raise ChaoxingAPIError("knowledge-graph event executions must contain 1-3 items")
        groups = self._knowledge_graph_label_groups(context)
        module_aliases = {
            "0": 0,
            "learning_path": 0,
            "学习路径": 0,
            "1": 1,
            "microcourse_resources": 1,
            "microcourse": 1,
            "微课资料": 1,
        }
        resolved: list[dict[str, Any]] = []
        for index, item in enumerate(executions, 1):
            if not isinstance(item, dict):
                raise ChaoxingAPIError(f"knowledge-graph event execution {index} must be an object")
            label_query = str(item.get("label") or item.get("label_id") or "").strip()
            label = self._resolve_knowledge_graph_label(groups, label_query)
            raw_module = item.get("execute_module", item.get("module", 0))
            module_key = str(raw_module).strip().lower()
            if module_key not in module_aliases:
                raise ChaoxingAPIError(
                    "knowledge-graph event execute_module must be learning_path/0 "
                    "or microcourse_resources/1"
                )
            execute_module = module_aliases[module_key]
            resolved.append(
                {
                    "executeModule": execute_module,
                    "labelId": label["label_id"],
                    "labelName": label["name"],
                    "tagContent": execute_module,
                }
            )
        return resolved

    def _knowledge_graph_event_form(
        self,
        context: dict[str, Any],
        *,
        name: str,
        topic_condition: Any,
        set_condition: Any,
        percent1: Any,
        percent2: Any,
        executions: list[dict[str, Any]],
    ) -> dict[str, Any]:
        normalized_name = self._validate_knowledge_graph_text(
            name, "knowledge-graph event name", 100
        )
        topic_value = self._knowledge_graph_event_condition_value(
            topic_condition, "topic_condition"
        )
        if topic_value not in {0, 1}:
            raise ChaoxingAPIError("knowledge-graph event topic_condition must be 0 or 1")
        set_value = self._knowledge_graph_event_condition_value(set_condition, "set_condition")
        if set_value not in {0, 1, 2, 3, 4, 7}:
            raise ChaoxingAPIError(
                "knowledge-graph event set_condition must be 0, 1, 2, 3, 4, or 7"
            )
        try:
            first = int(round(float(percent1)))
            second = int(round(float(percent2)))
        except (TypeError, ValueError) as exc:
            raise ChaoxingAPIError("knowledge-graph event percentages must be numbers") from exc
        if not 0 <= first <= 100 or not 0 <= second <= 100:
            raise ChaoxingAPIError("knowledge-graph event percentages must be between 0 and 100")
        if set_value == 7 and first > second:
            raise ChaoxingAPIError("knowledge-graph event range start cannot exceed range end")
        normalized_executions = self._knowledge_graph_event_executions(context, executions)
        return {
            "courseid": context["common"]["courseid"],
            "cpi": context["common"]["cpi"],
            "name": normalized_name,
            "topicCondition": topic_value,
            "setCondition": set_value,
            "percent1": str(first),
            "percent2": str(second),
            "executiveModuleParam": json.dumps(
                normalized_executions, ensure_ascii=False, separators=(",", ":")
            ),
        }

    def list_knowledge_graph_events(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        search: str = "",
    ) -> dict[str, Any]:
        events = self._knowledge_graph_events(self._knowledge_graph_context(course, clazz))
        normalized_search = str(search or "").strip().lower()
        if normalized_search:
            events = [item for item in events if normalized_search in item["name"].lower()]
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "search": normalized_search,
            "count": len(events),
            "events": events,
            "verification": "graph task events refreshed from the authenticated HTTP API",
        }

    def create_knowledge_graph_event(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        name: str,
        *,
        topic_condition: Any,
        set_condition: Any,
        percent1: Any,
        percent2: Any = 100,
        executions: list[dict[str, Any]],
    ) -> dict[str, Any]:
        context = self._knowledge_graph_context(course, clazz)
        before = self._knowledge_graph_events(context)
        before_ids = {item["event_id"] for item in before}
        form = self._knowledge_graph_event_form(
            context,
            name=name,
            topic_condition=topic_condition,
            set_condition=set_condition,
            percent1=percent1,
            percent2=percent2,
            executions=executions,
        )
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/coursetopic/addtopicevent",
            "knowledge-graph event create",
            method="POST",
            data=form,
        )
        self._knowledge_graph_ack(payload, "knowledge-graph event create")
        matches = [
            item
            for item in self._knowledge_graph_events(context)
            if item["event_id"] not in before_ids and item["name"] == form["name"]
        ]
        if len(matches) != 1:
            raise ChaoxingAPIError(
                "server acknowledged event creation, but the new event was not uniquely visible"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "event": matches[0],
            "verification": "one new graph task event is visible in a fresh listing",
        }

    def update_knowledge_graph_event(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        event: str,
        *,
        name: str | None = None,
        topic_condition: Any | None = None,
        set_condition: Any | None = None,
        percent1: Any | None = None,
        percent2: Any | None = None,
        executions: list[dict[str, Any]] | None = None,
    ) -> dict[str, Any]:
        context = self._knowledge_graph_context(course, clazz)
        selected = self._resolve_knowledge_graph_event(self._knowledge_graph_events(context), event)
        if all(
            value is None
            for value in (
                name,
                topic_condition,
                set_condition,
                percent1,
                percent2,
                executions,
            )
        ):
            raise ChaoxingAPIError("at least one knowledge-graph event field is required")
        current_executions = [
            {
                "label": item["label_id"],
                "execute_module": item["execute_module"],
            }
            for item in selected["executions"]
        ]
        form = self._knowledge_graph_event_form(
            context,
            name=selected["name"] if name is None else name,
            topic_condition=(
                selected["topic_condition"] if topic_condition is None else topic_condition
            ),
            set_condition=selected["set_condition"] if set_condition is None else set_condition,
            percent1=selected["percent1"] if percent1 is None else percent1,
            percent2=selected["percent2"] if percent2 is None else percent2,
            executions=current_executions if executions is None else executions,
        )
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/coursetopic/updatetopicevent",
            "knowledge-graph event update",
            method="POST",
            data={**form, "eventId": selected["event_id"]},
        )
        self._knowledge_graph_ack(payload, "knowledge-graph event update")
        refreshed = self._resolve_knowledge_graph_event(
            self._knowledge_graph_events(context), selected["event_id"]
        )
        expected = {
            "name": form["name"],
            "topic_condition": form["topicCondition"],
            "set_condition": form["setCondition"],
            "percent1": int(form["percent1"]),
            "percent2": int(form["percent2"]),
        }
        mismatches = {
            key: {"expected": value, "actual": refreshed[key]}
            for key, value in expected.items()
            if refreshed[key] != value
        }
        if mismatches:
            raise ChaoxingAPIError(
                f"server acknowledged event update, but refreshed values differ: {mismatches}"
            )
        expected_executions = json.loads(form["executiveModuleParam"])
        refreshed_keys = [
            (item["label_id"], item["execute_module"]) for item in refreshed["executions"]
        ]
        expected_keys = [
            (str(item["labelId"]), int(item["executeModule"])) for item in expected_executions
        ]
        if refreshed_keys != expected_keys:
            raise ChaoxingAPIError(
                "server acknowledged event update, but refreshed executions differ"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "before": selected,
            "event": refreshed,
            "verification": "all graph task event fields match a fresh listing",
        }

    def delete_knowledge_graph_event(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        event: str,
    ) -> dict[str, Any]:
        context = self._knowledge_graph_context(course, clazz)
        selected = self._resolve_knowledge_graph_event(self._knowledge_graph_events(context), event)
        payload = self._knowledge_graph_json_request(
            context,
            "/mooc2-ans/coursetopic/deletetopicevent",
            "knowledge-graph event delete",
            method="POST",
            data={
                "courseid": context["common"]["courseid"],
                "cpi": context["common"]["cpi"],
                "eventId": selected["event_id"],
            },
        )
        self._knowledge_graph_ack(payload, "knowledge-graph event delete")
        if any(
            item["event_id"] == selected["event_id"]
            for item in self._knowledge_graph_events(context)
        ):
            raise ChaoxingAPIError(
                "server acknowledged event deletion, but the event remains visible"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "deleted_event": selected,
            "verification": "the graph task event is absent from a fresh listing",
        }

    def download_knowledge_graph_export(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        export_format: str,
        output_path: str | Path,
        *,
        model: str = "",
        overwrite: bool = False,
    ) -> dict[str, Any]:
        aliases = {
            "xmind": "xmind",
            "excel": "excel",
            "xlsx": "excel",
            "csv": "csv",
            "psg": "psg",
            "json": "psg",
            "pdf": "pdf",
            "rdf": "rdf",
        }
        normalized_format = aliases.get(str(export_format or "").strip().lower())
        if normalized_format is None:
            raise ChaoxingAPIError(
                "knowledge-graph export format must be xmind, excel/xlsx, csv, psg/json, "
                "pdf, or rdf"
            )
        context = self._knowledge_graph_context(course, clazz)
        models = self._normalize_knowledge_graph_models(
            self._knowledge_graph_topic_setting_data(context)
        )
        if model:
            selected_model = self._resolve_knowledge_graph_model(models, model)
        else:
            selected_model = next(
                (item for item in models if item["mode_type"] == 1),
                models[0] if models else None,
            )
        if selected_model is None:
            raise ChaoxingAPIError("the course exposes no knowledge-graph model to export")
        config = self._knowledge_graph_config_data(context)
        data_json = config.get("dataJson") if isinstance(config.get("dataJson"), dict) else {}
        export_token = str(data_json.get("exportCourseTopicEnc") or "").strip()
        if not export_token:
            raise ChaoxingAPIError("knowledge-graph configuration exposed no export token")
        params: dict[str, Any] = {
            "courseId": course["course_id"],
            "cpi": course["cpi"],
            "topicModelId": selected_model["model_id"],
            "enc": export_token,
        }
        if normalized_format == "xmind":
            endpoint = "/mooc2-ans/questionBankTopic/exportcoursetopicxmind"
        else:
            endpoint = "/mooc2-ans/questionBankTopic/export-knowledge-points"
            params["clazzId"] = clazz["clazz_id"]
            export_types = {"csv": 1, "psg": 2, "pdf": 3, "rdf": 4}
            if normalized_format in export_types:
                params["exportType"] = export_types[normalized_format]
        payload = self._knowledge_graph_json_request(
            context,
            endpoint,
            f"knowledge-graph {normalized_format} export link",
            params=params,
        )
        self._knowledge_graph_ack(payload, f"knowledge-graph {normalized_format} export link")
        download_url = validated_chaoxing_url(
            str(payload.get("data") or ""), "knowledge-graph export URL"
        )
        try:
            response = context["session"].get(
                download_url,
                headers={"Referer": context["referer"]},
                timeout=max(self.timeout, 300),
                stream=True,
                allow_redirects=True,
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"knowledge-graph export download failed: {exc}") from exc
        validated_chaoxing_url(response.url, "knowledge-graph export final URL")
        content_type = str(response.headers.get("Content-Type") or "").lower()
        if "text/html" in content_type:
            message = html_text(self._decode(response), 240)
            raise ChaoxingAPIError(
                "knowledge-graph export returned text instead of a file"
                + (f": {message}" if message else "")
            )
        extensions = {
            "xmind": ".xmind",
            "excel": ".xlsx",
            "csv": ".csv",
            "psg": ".json",
            "pdf": ".pdf",
            "rdf": ".rdf",
        }
        server_name = content_disposition_filename(
            str(response.headers.get("Content-Disposition") or "")
        )
        fallback_name = (
            self._resource_archive_segment(
                f"{course.get('course_name') or course['course_id']}-课程知识点",
                f"course-{course['course_id']}-knowledge-graph",
            )
            + extensions[normalized_format]
        )
        target = self._resource_download_target(
            output_path,
            suggested_name=server_name or fallback_name,
            overwrite=overwrite,
        )
        temporary = target.with_name(target.name + ".part")
        if temporary.exists():
            raise ChaoxingAPIError(f"temporary download target already exists: {temporary}")
        size = 0
        prefix = b""
        try:
            with temporary.open("wb") as stream:
                for chunk in response.iter_content(chunk_size=1024 * 256):
                    if not chunk:
                        continue
                    if len(prefix) < 16:
                        prefix += chunk[: 16 - len(prefix)]
                    stream.write(chunk)
                    size += len(chunk)
            if size <= 0:
                raise ChaoxingAPIError("knowledge-graph export download was empty")
            signatures = {
                "xmind": lambda value: value.startswith(b"PK"),
                "excel": lambda value: value.startswith(b"PK"),
                "csv": lambda value: not value.lstrip().startswith(b"<"),
                "psg": lambda value: value.lstrip().startswith((b"{", b"[")),
                "pdf": lambda value: value.startswith(b"%PDF"),
                "rdf": lambda value: value.lstrip().startswith((b"<rdf:RDF", b"<?xml")),
            }
            if not signatures[normalized_format](prefix):
                raise ChaoxingAPIError(
                    f"downloaded content did not match {normalized_format} file signature"
                )
            temporary.replace(target)
        except (OSError, ChaoxingAPIError) as exc:
            temporary.unlink(missing_ok=True)
            if isinstance(exc, ChaoxingAPIError):
                raise
            raise ChaoxingAPIError(f"cannot save knowledge-graph export: {exc}") from exc
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "model": selected_model,
            "format": normalized_format,
            "output_path": str(target),
            "file_name": target.name,
            "byte_count": size,
            "content_type": content_type,
            "verification": (
                "the authenticated export was saved atomically and its file signature matched"
            ),
        }

    def _class_activity_context(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> dict[str, Any]:
        session = self._session()
        course_context = self._course_context(session, course, clazz)
        module = resolve_module(course_context["modules"], "班级活动")
        request_url = self._module_url(course_context, module, course, clazz)
        try:
            response = session.get(
                request_url,
                timeout=self.timeout,
                allow_redirects=True,
                headers={"Referer": str(course_context["final_url"])},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"class-activity page request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError(
                f"class-activity page request was redirected to login: {response.url}"
            )
        html = self._decode(response)
        page_hidden = parse_hidden_inputs(html)
        course_hidden = (
            course_context["hidden"] if isinstance(course_context.get("hidden"), dict) else {}
        )
        query = parse_qs(urlparse(response.url).query)

        def first(*keys: str, fallback: Any = "") -> str:
            for key in keys:
                values = query.get(key)
                if values and str(values[0]).strip():
                    return str(values[0]).strip()
                for source in (page_hidden, course_hidden):
                    if str(source.get(key) or "").strip():
                        return str(source[key]).strip()
            return str(fallback or "").strip()

        common = {
            "fid": first("fid"),
            "course_id": first("courseId", "courseid", fallback=course.get("course_id")),
            "clazz_id": first("classId", "clazzId", "clazzid", fallback=clazz.get("clazz_id")),
            "cpi": first("cpi", fallback=course.get("cpi")),
        }
        if not common["fid"]:
            fid_match = re.search(r"\bvar\s+fid\s*=\s*['\"]([^'\"]+)", html)
            common["fid"] = fid_match.group(1).strip() if fid_match else ""
        if not all(common[key] for key in ("course_id", "clazz_id")):
            raise ChaoxingAPIError("class-activity page omitted course or class identifiers")
        return {
            "session": session,
            "root_url": response.url,
            "course": course,
            "clazz": clazz,
            "common": common,
        }

    def _class_activity_json_request(
        self,
        context: dict[str, Any],
        path: str,
        operation: str,
        *,
        method: str = "GET",
        params: dict[str, Any] | None = None,
        data: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        url = urljoin(MOBILELEARN_BASE_URL + "/", path.lstrip("/"))
        headers = {
            "Referer": str(context["root_url"]),
            "X-Requested-With": "XMLHttpRequest",
            "Accept": "application/json, text/plain, */*",
        }
        try:
            response = context["session"].request(
                method.upper(),
                url,
                params=params if method.upper() == "GET" else None,
                data=data if method.upper() == "POST" else None,
                timeout=self.timeout,
                headers=headers,
                allow_redirects=True,
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"{operation} failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError(f"{operation} was redirected to login: {response.url}")
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError(f"{operation} returned invalid JSON") from exc
        if not isinstance(payload, dict):
            raise ChaoxingAPIError(f"{operation} returned invalid JSON")
        return payload

    @staticmethod
    def _class_activity_ack(payload: dict[str, Any], operation: str) -> dict[str, Any]:
        result = payload.get("result")
        status = payload.get("status")
        success = str(result).strip().lower() in {"1", "true"} or str(status).strip().lower() in {
            "1",
            "true",
        }
        if not success:
            raise ChaoxingAPIError(
                str(
                    payload.get("errorMsg")
                    or payload.get("messages")
                    or payload.get("message")
                    or payload.get("msg")
                    or f"{operation} was rejected"
                )
            )
        return payload

    @staticmethod
    def _normalize_class_activity_group(raw: dict[str, Any]) -> dict[str, Any]:
        class_id = raw.get("classId")
        return {
            "group_id": str(raw.get("id") or ""),
            "name": str(raw.get("name") or "").strip(),
            "course_id": str(raw.get("courseId") or ""),
            "clazz_id": str(class_id) if class_id not in (None, "") else None,
            "creator_uid": str(raw.get("uid") or ""),
            "type": ChaoxingAPI._ai_workbench_integer(raw.get("type"), -1),
            "sort": ChaoxingAPI._ai_workbench_integer(raw.get("sort"), -1),
            "deleted": bool(raw.get("isdelete")),
            "is_default": class_id in (None, "")
            and ChaoxingAPI._ai_workbench_integer(raw.get("sort"), -1) == 0,
            "created_at": raw.get("createtime"),
            "updated_at": raw.get("updatetime"),
        }

    @staticmethod
    def _class_activity_status_label(status: Any) -> str:
        return {0: "not_started", 1: "ongoing", 2: "ended"}.get(
            ChaoxingAPI._ai_workbench_integer(status, -1), "unknown"
        )

    @staticmethod
    def _normalize_class_activity(raw: dict[str, Any]) -> dict[str, Any]:
        content = raw.get("content")
        decoded_content: Any = None
        if isinstance(content, str) and content.strip():
            try:
                decoded_content = json.loads(content)
            except json.JSONDecodeError:
                decoded_content = None
        active_type = ChaoxingAPI._ai_workbench_integer(raw.get("activeType"), -1)
        return {
            "activity_id": str(raw.get("activeId") or raw.get("id") or ""),
            "name": str(raw.get("typeTitle") or raw.get("title") or "").strip(),
            "category_label": str(raw.get("title") or "").strip(),
            "activity_type": active_type,
            "clazz_id": str(raw.get("classId") or ""),
            "group_id": str(raw.get("planId") or ""),
            "group_name": str(raw.get("groupName") or "").strip(),
            "creator_uid": str(raw.get("activeCreateUid") or raw.get("createUid") or ""),
            "other_id": str(raw.get("otherId") or ""),
            "status": ChaoxingAPI._ai_workbench_integer(raw.get("status"), -1),
            "status_label": ChaoxingAPI._class_activity_status_label(raw.get("status")),
            "allow_start_end_from_list": bool(
                ChaoxingAPI._ai_workbench_integer(raw.get("allowBeginEndFromList"), 0)
            ),
            "content": content,
            "content_json": decoded_content,
            "created_at": raw.get("createTime") or raw.get("createtime"),
            "start_time": raw.get("startTime"),
            "end_time": raw.get("endTime"),
            "sort": ChaoxingAPI._ai_workbench_integer(raw.get("activeSort"), -1),
            "group_sort": ChaoxingAPI._ai_workbench_integer(raw.get("groupSort"), -1),
            "logo": str(raw.get("logo") or ""),
        }

    def _class_activity_listing(self, context: dict[str, Any]) -> dict[str, Any]:
        common = context["common"]
        payload = self._class_activity_json_request(
            context,
            "/v2/apis/active/pcActivelist",
            "class-activity list",
            params={
                "fid": common["fid"],
                "courseId": common["course_id"],
                "classId": common["clazz_id"],
                "types": "",
                "userid": "",
                "groupId": -1,
            },
        )
        self._class_activity_ack(payload, "class-activity list")
        data = payload.get("data") if isinstance(payload.get("data"), dict) else {}
        groups = [
            self._normalize_class_activity_group(item)
            for item in data.get("groupList", [])
            if isinstance(item, dict) and str(item.get("id") or "")
        ]
        activities = [
            self._normalize_class_activity(item)
            for item in data.get("activeList", [])
            if isinstance(item, dict) and str(item.get("activeId") or "")
        ]
        return {
            "archived": bool(data.get("archived")),
            "managed_group_ids": [
                item for item in str(data.get("beManagedPlanIds") or "").split(",") if item.strip()
            ],
            "groups": groups,
            "activities": activities,
        }

    @staticmethod
    def _resolve_class_activity_group(groups: list[dict[str, Any]], query: str) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("class-activity group name or ID is required")
        exact = [
            item
            for item in groups
            if item["group_id"].lower() == normalized or item["name"].lower() == normalized
        ]
        if len(exact) == 1:
            return exact[0]
        partial = [item for item in groups if normalized in item["name"].lower()]
        if len(partial) == 1:
            return partial[0]
        candidates = exact or partial
        if not candidates:
            raise ChaoxingAPIError(f"class-activity group not found: {query}")
        options = ", ".join(f"{item['name']} ({item['group_id']})" for item in candidates[:10])
        raise ChaoxingAPIError(f"multiple class-activity groups match: {options}")

    @staticmethod
    def _resolve_class_activity(activities: list[dict[str, Any]], query: str) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if not normalized:
            raise ChaoxingAPIError("class activity name or ID is required")
        exact = [
            item
            for item in activities
            if item["activity_id"].lower() == normalized or item["name"].lower() == normalized
        ]
        if len(exact) == 1:
            return exact[0]
        partial = [item for item in activities if normalized in item["name"].lower()]
        if len(partial) == 1:
            return partial[0]
        candidates = exact or partial
        if not candidates:
            raise ChaoxingAPIError(f"class activity not found: {query}")
        options = ", ".join(f"{item['name']} ({item['activity_id']})" for item in candidates[:10])
        raise ChaoxingAPIError(f"multiple class activities match: {options}")

    def list_class_activity_types(
        self, course: dict[str, Any], clazz: dict[str, Any]
    ) -> dict[str, Any]:
        context = self._class_activity_context(course, clazz)
        payload = self._class_activity_json_request(
            context,
            "/v2/apis/class/getActiveArray",
            "class-activity type list",
            params={
                "courseId": course["course_id"],
                "DB_STRATEGY": "COURSEID",
                "STRATEGY_PARA": "courseId",
            },
        )
        self._class_activity_ack(payload, "class-activity type list")
        data = payload.get("data") if isinstance(payload.get("data"), dict) else {}
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "active_types": [
                self._ai_workbench_integer(item, -1) for item in data.get("activeArray", [])
            ],
            "single_types": [
                self._ai_workbench_integer(item, -1) for item in data.get("singleActiveArray", [])
            ],
            "other_types": [
                self._ai_workbench_integer(item, -1) for item in data.get("otherActiveArray", [])
            ],
            "verification": "activity-type arrays read from the authenticated class API",
        }

    def list_class_activity_groups(
        self, course: dict[str, Any], clazz: dict[str, Any]
    ) -> dict[str, Any]:
        listing = self._class_activity_listing(self._class_activity_context(course, clazz))
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "count": len(listing["groups"]),
            "groups": listing["groups"],
            "managed_group_ids": listing["managed_group_ids"],
            "verification": "activity groups refreshed from the authenticated class list",
        }

    @staticmethod
    def _validate_class_activity_name(name: str, label: str) -> str:
        normalized = str(name or "").strip()
        if not 1 <= len(normalized) <= 200:
            raise ChaoxingAPIError(f"{label} must contain 1-200 characters")
        return normalized

    def create_class_activity_group(
        self, course: dict[str, Any], clazz: dict[str, Any], name: str
    ) -> dict[str, Any]:
        normalized_name = self._validate_class_activity_name(name, "class-activity group name")
        context = self._class_activity_context(course, clazz)
        before = self._class_activity_listing(context)["groups"]
        if any(item["name"] == normalized_name for item in before):
            raise ChaoxingAPIError(f"class-activity group already exists: {normalized_name}")
        payload = self._class_activity_json_request(
            context,
            "/v2/apis/active/group/add",
            "class-activity group create",
            method="POST",
            data={
                "courseId": course["course_id"],
                "classId": clazz["clazz_id"],
                "name": normalized_name,
            },
        )
        self._class_activity_ack(payload, "class-activity group create")
        created_data = payload.get("data")
        group_id = str(
            (created_data.get("id") or created_data.get("groupId") or "")
            if isinstance(created_data, dict)
            else (created_data or "")
        )
        after = self._class_activity_listing(context)["groups"]
        matches = [
            item
            for item in after
            if item["group_id"] == group_id and item["name"] == normalized_name
        ]
        if len(matches) != 1:
            raise ChaoxingAPIError(
                "server acknowledged activity-group creation, but it was not uniquely visible"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "group": matches[0],
            "verification": "the new activity group appeared with the returned ID",
        }

    def rename_class_activity_group(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        group: str,
        name: str,
    ) -> dict[str, Any]:
        normalized_name = self._validate_class_activity_name(name, "class-activity group name")
        context = self._class_activity_context(course, clazz)
        groups = self._class_activity_listing(context)["groups"]
        selected = self._resolve_class_activity_group(groups, group)
        if selected["is_default"]:
            raise ChaoxingAPIError("the default class-activity group cannot be renamed")
        if any(
            item["group_id"] != selected["group_id"] and item["name"] == normalized_name
            for item in groups
        ):
            raise ChaoxingAPIError(f"class-activity group already exists: {normalized_name}")
        payload = self._class_activity_json_request(
            context,
            "/ppt/taskAPI/updatetp",
            "class-activity group rename",
            method="POST",
            data={"id": selected["group_id"], "name": normalized_name},
        )
        self._class_activity_ack(payload, "class-activity group rename")
        refreshed = self._resolve_class_activity_group(
            self._class_activity_listing(context)["groups"], selected["group_id"]
        )
        if refreshed["name"] != normalized_name:
            raise ChaoxingAPIError(
                "server acknowledged activity-group rename, but the refreshed name did not match"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "before": selected,
            "group": refreshed,
            "verification": "the refreshed activity group has the requested name",
        }

    def delete_class_activity_group(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        group: str,
        *,
        allow_nonempty: bool = False,
    ) -> dict[str, Any]:
        context = self._class_activity_context(course, clazz)
        listing = self._class_activity_listing(context)
        selected = self._resolve_class_activity_group(listing["groups"], group)
        if selected["is_default"]:
            raise ChaoxingAPIError("the default class-activity group cannot be deleted")
        contained = [
            item for item in listing["activities"] if item["group_id"] == selected["group_id"]
        ]
        if contained and not allow_nonempty:
            raise ChaoxingAPIError(
                "class-activity group is not empty; set allow_nonempty=true to move its activities"
            )
        payload = self._class_activity_json_request(
            context,
            "/ppt/taskAPI/deltp",
            "class-activity group delete",
            method="POST",
            data={"id": selected["group_id"]},
        )
        self._class_activity_ack(payload, "class-activity group delete")
        after = self._class_activity_listing(context)
        if any(item["group_id"] == selected["group_id"] for item in after["groups"]):
            raise ChaoxingAPIError(
                "server acknowledged activity-group deletion, but it is still visible"
            )
        moved = [
            item
            for item in after["activities"]
            if any(old["activity_id"] == item["activity_id"] for old in contained)
        ]
        if len(moved) != len(contained) or any(
            item["group_id"] == selected["group_id"] for item in moved
        ):
            raise ChaoxingAPIError(
                "activity group was deleted, but its activities were not all visible elsewhere"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "deleted_group": selected,
            "moved_activity_count": len(moved),
            "moved_activities": moved,
            "verification": "the group disappeared and its activities remain outside it",
        }

    def reorder_class_activity_groups(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        group_order: list[str],
    ) -> dict[str, Any]:
        context = self._class_activity_context(course, clazz)
        groups = self._class_activity_listing(context)["groups"]
        custom = [item for item in groups if not item["is_default"]]
        resolved = [self._resolve_class_activity_group(custom, item) for item in group_order]
        if len({item["group_id"] for item in resolved}) != len(resolved):
            raise ChaoxingAPIError("group_order contains duplicate class-activity groups")
        if {item["group_id"] for item in resolved} != {item["group_id"] for item in custom}:
            raise ChaoxingAPIError("group_order must contain every custom activity group once")
        payload = self._class_activity_json_request(
            context,
            "/ppt/taskAPI/movetp",
            "class-activity group reorder",
            method="POST",
            data={
                "data": json.dumps(
                    {"data": [{"id": item["group_id"]} for item in resolved]},
                    separators=(",", ":"),
                ),
                "courseId": course["course_id"],
            },
        )
        self._class_activity_ack(payload, "class-activity group reorder")
        refreshed = [
            item
            for item in self._class_activity_listing(context)["groups"]
            if not item["is_default"]
        ]
        if [item["group_id"] for item in refreshed] != [item["group_id"] for item in resolved]:
            raise ChaoxingAPIError(
                "server acknowledged activity-group reorder, but the refreshed order did not match"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "groups": refreshed,
            "verification": "the refreshed custom-group order matches the complete request",
        }

    def list_class_activities(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        group: str = "",
        search: str = "",
        status: str = "",
        activity_type: int | None = None,
    ) -> dict[str, Any]:
        listing = self._class_activity_listing(self._class_activity_context(course, clazz))
        selected_group: dict[str, Any] | None = None
        activities = listing["activities"]
        if group:
            selected_group = self._resolve_class_activity_group(listing["groups"], group)
            activities = [
                item for item in activities if item["group_id"] == selected_group["group_id"]
            ]
        normalized_search = str(search or "").strip().lower()
        if normalized_search:
            activities = [
                item
                for item in activities
                if normalized_search in item["name"].lower()
                or normalized_search in item["category_label"].lower()
            ]
        normalized_status = str(status or "").strip().lower().replace("-", "_")
        status_aliases = {
            "0": 0,
            "not_started": 0,
            "未开始": 0,
            "1": 1,
            "ongoing": 1,
            "进行中": 1,
            "2": 2,
            "ended": 2,
            "已结束": 2,
        }
        if normalized_status:
            if normalized_status not in status_aliases:
                raise ChaoxingAPIError(
                    "class-activity status must be not_started, ongoing, ended, 0, 1, or 2"
                )
            activities = [
                item for item in activities if item["status"] == status_aliases[normalized_status]
            ]
        if activity_type is not None:
            activities = [
                item for item in activities if item["activity_type"] == int(activity_type)
            ]
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "archived": listing["archived"],
            "group": selected_group,
            "search": normalized_search,
            "status_filter": normalized_status,
            "activity_type_filter": activity_type,
            "count": len(activities),
            "activities": activities,
            "verification": "activities refreshed from the authenticated class API",
        }

    def read_class_activity(
        self, course: dict[str, Any], clazz: dict[str, Any], activity: str
    ) -> dict[str, Any]:
        context = self._class_activity_context(course, clazz)
        selected = self._resolve_class_activity(
            self._class_activity_listing(context)["activities"], activity
        )
        payload = self._class_activity_json_request(
            context,
            "/v2/apis/active/info",
            "class-activity read",
            params={
                "id": selected["activity_id"],
                "courseId": course["course_id"],
                "classId": clazz["clazz_id"],
                "fid": context["common"]["fid"],
            },
        )
        self._class_activity_ack(payload, "class-activity read")
        raw = payload.get("data")
        if not isinstance(raw, dict):
            raise ChaoxingAPIError("class-activity read omitted activity data")
        refreshed = {**selected, **self._normalize_class_activity(raw)}
        source_fields = {
            "activity_id": ("activeId", "id"),
            "name": ("typeTitle", "title"),
            "category_label": ("title",),
            "activity_type": ("activeType",),
            "clazz_id": ("classId",),
            "group_id": ("planId",),
            "group_name": ("groupName",),
            "creator_uid": ("activeCreateUid", "createUid"),
            "other_id": ("otherId",),
            "status": ("status",),
            "status_label": ("status",),
            "allow_start_end_from_list": ("allowBeginEndFromList",),
            "content": ("content",),
            "content_json": ("content",),
            "created_at": ("createTime", "createtime"),
            "start_time": ("startTime",),
            "end_time": ("endTime",),
            "sort": ("activeSort",),
            "group_sort": ("groupSort",),
            "logo": ("logo",),
        }
        for field, keys in source_fields.items():
            if not any(key in raw for key in keys):
                refreshed[field] = selected.get(field)
        if refreshed["activity_id"] != selected["activity_id"]:
            raise ChaoxingAPIError("class-activity read returned a different activity")
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "activity": refreshed,
            "verification": "activity metadata refreshed from the authenticated info API",
        }

    def rename_class_activity(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        activity: str,
        name: str,
    ) -> dict[str, Any]:
        normalized_name = self._validate_class_activity_name(name, "class activity name")
        context = self._class_activity_context(course, clazz)
        selected = self._resolve_class_activity(
            self._class_activity_listing(context)["activities"], activity
        )
        if selected["activity_type"] == 77:
            raise ChaoxingAPIError("AI-experiment activities cannot be renamed from this surface")
        payload = self._class_activity_json_request(
            context,
            "/v2/apis/active/reNameById?DB_STRATEGY=PRIMARY_KEY&STRATEGY_PARA=activeId",
            "class-activity rename",
            params={"activeId": selected["activity_id"], "newName": normalized_name},
        )
        self._class_activity_ack(payload, "class-activity rename")
        refreshed = self._resolve_class_activity(
            self._class_activity_listing(context)["activities"], selected["activity_id"]
        )
        if refreshed["name"] != normalized_name:
            raise ChaoxingAPIError(
                "server acknowledged class-activity rename, but the refreshed name did not match"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "before": selected,
            "activity": refreshed,
            "verification": "the refreshed activity has the requested name",
        }

    def move_class_activity(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        activity: str,
        group: str,
    ) -> dict[str, Any]:
        context = self._class_activity_context(course, clazz)
        listing = self._class_activity_listing(context)
        selected = self._resolve_class_activity(listing["activities"], activity)
        target = self._resolve_class_activity_group(listing["groups"], group)
        payload = self._class_activity_json_request(
            context,
            "/v2/apis/active/group/move",
            "class-activity move",
            params={
                "courseId": course["course_id"],
                "classId": clazz["clazz_id"],
                "activeId": selected["activity_id"],
                "groupId": target["group_id"],
                "idMaxSort": "true",
            },
        )
        self._class_activity_ack(payload, "class-activity move")
        refreshed = self._resolve_class_activity(
            self._class_activity_listing(context)["activities"], selected["activity_id"]
        )
        if refreshed["group_id"] != target["group_id"]:
            raise ChaoxingAPIError(
                "server acknowledged class-activity move, but the destination did not match"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "activity": refreshed,
            "group": target,
            "verification": "the refreshed activity is in the requested group",
        }

    def reorder_class_activities(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        group: str,
        activity_order: list[str],
    ) -> dict[str, Any]:
        context = self._class_activity_context(course, clazz)
        listing = self._class_activity_listing(context)
        selected_group = self._resolve_class_activity_group(listing["groups"], group)
        current = [
            item for item in listing["activities"] if item["group_id"] == selected_group["group_id"]
        ]
        resolved = [self._resolve_class_activity(current, item) for item in activity_order]
        if len({item["activity_id"] for item in resolved}) != len(resolved):
            raise ChaoxingAPIError("activity_order contains duplicate activities")
        if {item["activity_id"] for item in resolved} != {item["activity_id"] for item in current}:
            raise ChaoxingAPIError("activity_order must contain every activity in the group once")
        payload = self._class_activity_json_request(
            context,
            "/v2/apis/active/group/sort",
            "class-activity reorder",
            method="POST",
            data={
                "activeIdArray": ",".join(item["activity_id"] for item in reversed(resolved)),
                "groupId": selected_group["group_id"],
                "courseId": course["course_id"],
                "classId": clazz["clazz_id"],
            },
        )
        self._class_activity_ack(payload, "class-activity reorder")
        refreshed = [
            item
            for item in self._class_activity_listing(context)["activities"]
            if item["group_id"] == selected_group["group_id"]
        ]
        if [item["activity_id"] for item in refreshed] != [
            item["activity_id"] for item in resolved
        ]:
            raise ChaoxingAPIError(
                "server acknowledged class-activity reorder, but the refreshed order did not match"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "group": selected_group,
            "activities": refreshed,
            "verification": "the refreshed activity order matches the complete request",
        }

    def set_class_activity_status(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        activity: str,
        *,
        started: bool,
    ) -> dict[str, Any]:
        context = self._class_activity_context(course, clazz)
        selected = self._resolve_class_activity(
            self._class_activity_listing(context)["activities"], activity
        )
        if not selected["allow_start_end_from_list"]:
            raise ChaoxingAPIError(
                "this activity type cannot be started or ended from the class-activity list"
            )
        if started and selected["status"] != 0:
            raise ChaoxingAPIError("only a not-started class activity can be started")
        if not started and selected["status"] != 1:
            raise ChaoxingAPIError("only an ongoing class activity can be ended")
        if started:
            path = "/v2/apis/active/startActive"
            params = {
                "activeId": selected["activity_id"],
                "courseId": course["course_id"],
                "classId": clazz["clazz_id"],
                "activeType": selected["activity_type"],
                "fyktBigClassChatId": "",
            }
            operation = "class-activity start"
        elif selected["activity_type"] == 46:
            path = "/widget/CWareDataController/overFeedback"
            params = {
                "activeId": selected["activity_id"],
                "courseId": course["course_id"],
                "classId": clazz["clazz_id"],
            }
            operation = "class-activity feedback end"
        else:
            path = "/widget/active/endActive"
            params = {
                "activeId": selected["activity_id"],
                "activeType": selected["activity_type"],
                "isLockTopic": 1 if selected["activity_type"] == 5 else 0,
            }
            operation = "class-activity end"
        payload = self._class_activity_json_request(context, path, operation, params=params)
        self._class_activity_ack(payload, operation)
        expected_status = 1 if started else 2
        refreshed = self._resolve_class_activity(
            self._class_activity_listing(context)["activities"], selected["activity_id"]
        )
        if refreshed["status"] != expected_status:
            raise ChaoxingAPIError(
                "server acknowledged class-activity state change, but refreshed state did not match"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "activity": refreshed,
            "started": started,
            "verification": "the refreshed activity state matches the requested state",
        }

    def _class_activity_recycle_items(
        self,
        context: dict[str, Any],
        *,
        search: str = "",
        max_items: int = 1000,
    ) -> list[dict[str, Any]]:
        if max_items < 1 or max_items > 10_000:
            raise ChaoxingAPIError("max_items must be between 1 and 10000")
        common = context["common"]
        path = (
            "/v2/apis/recycleActive/searchRecycleActivesbyKeyword"
            if str(search or "").strip()
            else "/v2/apis/recycleActive/getRecycleActives"
        )
        items: list[dict[str, Any]] = []
        page = 1
        page_size = min(100, max_items)
        while len(items) < max_items:
            params: dict[str, Any] = {
                "DB_STRATEGY": "COURSEID",
                "STRATEGY_PARA": "courseId",
                "classId": common["clazz_id"],
                "courseId": common["course_id"],
                "page": page,
                "pageSize": page_size,
            }
            if search:
                params["keyWord"] = str(search).strip()
            payload = self._class_activity_json_request(
                context, path, "class-activity recycle list", params=params
            )
            if (
                str(payload.get("result")).strip() in {"0", "False", "false"}
                and str(payload.get("errorMsg") or "").strip().lower() == "no data"
            ):
                break
            self._class_activity_ack(payload, "class-activity recycle list")
            data = payload.get("data") if isinstance(payload.get("data"), dict) else {}
            rows = data.get("list") if isinstance(data.get("list"), list) else []
            for raw in rows:
                if not isinstance(raw, dict) or not str(raw.get("activeId") or ""):
                    continue
                item = self._normalize_class_activity(raw)
                item["recycled"] = True
                item["restore_supported"] = not (
                    item["activity_type"] == 77 and not bool(raw.get("isRestore"))
                )
                items.append(item)
            total_pages = self._ai_workbench_integer(data.get("totalPage"), page)
            total = self._ai_workbench_integer(data.get("allCount"), len(items))
            if not rows or page >= total_pages or len(items) >= total:
                break
            page += 1
            if page > 100:
                raise ChaoxingAPIError("class-activity recycle list exceeded 100 pages")
        return items[:max_items]

    def delete_class_activity(
        self, course: dict[str, Any], clazz: dict[str, Any], activity: str
    ) -> dict[str, Any]:
        context = self._class_activity_context(course, clazz)
        selected = self._resolve_class_activity(
            self._class_activity_listing(context)["activities"], activity
        )
        payload = self._class_activity_json_request(
            context,
            "/ppt/taskAPI/setdel",
            "class-activity delete",
            params={"aid": selected["activity_id"], "status": 1},
        )
        self._class_activity_ack(payload, "class-activity delete")
        recycled: list[dict[str, Any]] = []
        active_after: list[dict[str, Any]] = []
        for attempt in range(5):
            active_after = self._class_activity_listing(context)["activities"]
            recycled = [
                item
                for item in self._class_activity_recycle_items(context)
                if item["activity_id"] == selected["activity_id"]
            ]
            if (
                not any(item["activity_id"] == selected["activity_id"] for item in active_after)
                and len(recycled) == 1
            ):
                break
            if attempt < 4:
                sleep(0.2)
        if any(item["activity_id"] == selected["activity_id"] for item in active_after):
            raise ChaoxingAPIError(
                "server acknowledged class-activity deletion, but it is still active"
            )
        if len(recycled) != 1:
            raise ChaoxingAPIError(
                "server acknowledged class-activity deletion, but it is not visible in recycle"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "activity": recycled[0],
            "verification": "the activity disappeared from the active list and entered recycle",
        }

    def list_class_activity_recycle(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        search: str = "",
        max_items: int = 1000,
    ) -> dict[str, Any]:
        items = self._class_activity_recycle_items(
            self._class_activity_context(course, clazz),
            search=search,
            max_items=max_items,
        )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "search": str(search or "").strip(),
            "count": len(items),
            "activities": items,
            "verification": "recycled activities read from the authenticated recycle API",
        }

    def restore_class_activity(
        self, course: dict[str, Any], clazz: dict[str, Any], activity: str
    ) -> dict[str, Any]:
        context = self._class_activity_context(course, clazz)
        selected = self._resolve_class_activity(
            self._class_activity_recycle_items(context), activity
        )
        if not selected.get("restore_supported", True):
            raise ChaoxingAPIError("this recycled activity type does not support restoration")
        payload = self._class_activity_json_request(
            context,
            "/v2/apis/recycleActive/recycleActive",
            "class-activity restore",
            params={
                "DB_STRATEGY": "COURSEID",
                "STRATEGY_PARA": "courseId",
                "activeIds": selected["activity_id"],
                "classId": clazz["clazz_id"],
                "courseId": course["course_id"],
            },
        )
        self._class_activity_ack(payload, "class-activity restore")
        active_after = self._class_activity_listing(context)["activities"]
        recycle_after = self._class_activity_recycle_items(context)
        matches = [item for item in active_after if item["activity_id"] == selected["activity_id"]]
        if len(matches) != 1 or any(
            item["activity_id"] == selected["activity_id"] for item in recycle_after
        ):
            raise ChaoxingAPIError(
                "server acknowledged class-activity restore, but refreshed states did not match"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "activity": matches[0],
            "verification": "the activity returned to the active list and left recycle",
        }

    def permanently_delete_class_activities(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        activities: list[str],
    ) -> dict[str, Any]:
        if not activities:
            raise ChaoxingAPIError("at least one recycled class activity is required")
        context = self._class_activity_context(course, clazz)
        recycle = self._class_activity_recycle_items(context)
        selected = [self._resolve_class_activity(recycle, item) for item in activities]
        ids = list(dict.fromkeys(item["activity_id"] for item in selected))
        if len(ids) != len(selected):
            raise ChaoxingAPIError("activities contains duplicate recycled items")
        payload = self._class_activity_json_request(
            context,
            "/v2/apis/recycleActive/deleteCompletely",
            "class-activity permanent delete",
            params={
                "DB_STRATEGY": "COURSEID",
                "STRATEGY_PARA": "courseId",
                "activeIds": ",".join(ids),
                "classId": clazz["clazz_id"],
                "courseId": course["course_id"],
            },
        )
        self._class_activity_ack(payload, "class-activity permanent delete")
        remaining = self._class_activity_recycle_items(context)
        remaining_ids = {item["activity_id"] for item in remaining}
        if any(item in remaining_ids for item in ids):
            raise ChaoxingAPIError(
                "server acknowledged permanent activity deletion, but items remain visible"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "deleted_count": len(selected),
            "deleted_activities": selected,
            "verification": "all selected activities are absent from the refreshed recycle bin",
        }

    @staticmethod
    def _course_asset_kind(kind: str) -> tuple[str, dict[str, str]]:
        normalized = str(kind or "").strip().lower().replace("-", "_")
        aliases = {
            "courseware": "courseware",
            "course_ware": "courseware",
            "课件": "courseware",
            "teaching_plan": "teaching_plan",
            "teachingplan": "teaching_plan",
            "教案": "teaching_plan",
        }
        key = aliases.get(normalized)
        if key is None:
            raise ChaoxingAPIError("kind must be courseware or teaching_plan")
        return key, COURSE_ASSET_KINDS[key]

    def _course_asset_context(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        kind: str,
    ) -> dict[str, Any]:
        kind_key, config = self._course_asset_kind(kind)
        session = self._session()
        course_context = self._course_context(session, course, clazz)
        module = resolve_module(course_context["modules"], config["module"])
        return {
            "session": session,
            "kind": kind_key,
            "config": config,
            "root_url": self._module_url(course_context, module, course, clazz),
        }

    def _course_asset_json_request(
        self,
        context: dict[str, Any],
        path: str,
        operation: str,
        *,
        method: str = "GET",
        params: dict[str, Any] | None = None,
        data: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        url = urljoin(MOBILELEARN_BASE_URL + "/", path.lstrip("/"))
        headers = {
            "Referer": context["root_url"],
            "X-Requested-With": "XMLHttpRequest",
        }
        try:
            if method.upper() == "POST":
                response = context["session"].post(
                    url,
                    params=params,
                    data=data,
                    timeout=max(self.timeout, 60),
                    headers=headers,
                )
            else:
                response = context["session"].get(
                    url,
                    params=params,
                    timeout=max(self.timeout, 60),
                    headers=headers,
                )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"{operation} failed: {exc}") from exc
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError(f"{operation} returned invalid JSON") from exc
        if not isinstance(payload, dict):
            raise ChaoxingAPIError(f"{operation} returned invalid JSON")
        result = payload.get("result")
        if result is not None and str(result).strip().lower() not in {"1", "true"}:
            raise ChaoxingAPIError(
                str(payload.get("errorMsg") or payload.get("msg") or f"{operation} was rejected")
            )
        return payload

    @staticmethod
    def _normalize_course_asset(
        raw: dict[str, Any],
        index: int,
        *,
        kind: str,
        parent_id: str,
        parent_name: str,
        parent_path: str,
        depth: int,
        recycled: bool = False,
    ) -> dict[str, Any]:
        asset_id = str(raw.get("aid") or raw.get("id") or raw.get("activeId") or "")
        name = str(raw.get("title") or raw.get("name") or "").strip()
        try:
            type_code = int(raw.get("type"))
        except (TypeError, ValueError):
            type_code = 0
        suffix = str(raw.get("suffix") or "").strip().lstrip(".")
        type_labels = {
            1: "presentation",
            4: "folder",
            5: "teaching_plan",
            6: "teaching_plan_v2",
            7: "folder",
            8: "pdf",
            9: "word",
        }
        path = "/".join(part for part in (parent_path, name) if part)
        edit_ids = [
            item.strip() for item in str(raw.get("pptEditUidList") or "").split(",") if item.strip()
        ]

        def integer(value: Any) -> int:
            try:
                return int(value or 0)
            except (TypeError, ValueError):
                return 0

        return {
            "index": index,
            "asset_id": asset_id,
            "name": name,
            "title": name,
            "kind": kind,
            "type_code": type_code,
            "asset_type": type_labels.get(type_code, str(raw.get("typeTitle") or "unknown")),
            "is_folder": type_code == (7 if kind == "teaching_plan" else 4),
            "parent_id": parent_id,
            "parent_name": parent_name,
            "path": path,
            "depth": depth,
            "object_id": str(raw.get("pptObjectId") or raw.get("objectId") or ""),
            "suffix": suffix,
            "size": raw.get("size") or "",
            "creator_id": str(raw.get("createUid") or ""),
            "creator_name": str(raw.get("createName") or ""),
            "created_at": str(raw.get("createTime") or ""),
            "updated_at": str(raw.get("pptUpdateTime") or raw.get("updateTime") or ""),
            "sort": raw.get("sort"),
            "is_top": str(raw.get("topsign") or "0") == "1",
            "share_type": raw.get("shareType"),
            "folder_view_permissions_type": raw.get("folderViewPermissionsType"),
            "teacher_edit_ids": edit_ids,
            "child_count": integer(raw.get("childFileNum")),
            "activity_count": integer(raw.get("pptChildActiveNum")),
            "is_ai_generated": str(raw.get("isAIGenerate") or "0") == "1",
            "recycled": recycled,
        }

    def _course_asset_page(
        self,
        context: dict[str, Any],
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        folder_id: str = "0",
        folder_name: str = "根目录",
        folder_path: str = "",
        depth: int = 1,
        search: str = "",
        page: int = 1,
        page_size: int = 1000,
        recycled: bool = False,
    ) -> dict[str, Any]:
        if page < 1:
            raise ChaoxingAPIError("page must be at least 1")
        if not 1 <= page_size <= 1000:
            raise ChaoxingAPIError("page_size must be between 1 and 1000")
        path = (
            context["config"]["recycle_list_path"] if recycled else context["config"]["list_path"]
        )
        params: dict[str, Any] = {
            "DB_STRATEGY": "COURSEID",
            "STRATEGY_PARA": "courseId",
            "classId": clazz["clazz_id"],
            "courseId": course["course_id"],
            "page": page,
            "pageSize": page_size,
            "parentFolderId": folder_id,
            "keyWord": str(search or "").strip(),
        }
        if not recycled:
            params.update(
                {
                    "search": 1 if str(search or "").strip() else 0,
                    "createUid": "",
                    "orderByCreateTime": -1,
                }
            )
        payload = self._course_asset_json_request(
            context,
            path,
            f"{context['kind']} {'recycle ' if recycled else ''}list",
            params=params,
        )
        data = payload.get("data") if isinstance(payload.get("data"), dict) else {}
        raw_items = data.get("list") if isinstance(data.get("list"), list) else []
        items = [
            self._normalize_course_asset(
                raw,
                index,
                kind=context["kind"],
                parent_id=folder_id,
                parent_name=folder_name,
                parent_path=folder_path,
                depth=depth,
                recycled=recycled,
            )
            for index, raw in enumerate(raw_items, 1)
            if isinstance(raw, dict)
            and str(raw.get("aid") or raw.get("id") or raw.get("activeId") or "")
        ]

        def integer(key: str, fallback: int) -> int:
            try:
                return int(data.get(key))
            except (TypeError, ValueError):
                return fallback

        return {
            "page": integer("page", page),
            "page_size": integer("pageSize", page_size),
            "total_pages": integer("totalPage", 0),
            "total_count": integer("totalCount", len(items)),
            "all_count": integer("allCount", len(items)),
            "archived": str(data.get("archived") or "0") == "1",
            "has_manage_permission": str(data.get("hasManagePermission") or "1") != "0",
            "items": items,
        }

    def _course_asset_tree_from_context(
        self,
        context: dict[str, Any],
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        recycled: bool = False,
        max_nodes: int = 10000,
    ) -> list[dict[str, Any]]:
        tree: list[dict[str, Any]] = []
        queue: list[tuple[str, str, str, int]] = [("0", "根目录", "", 1)]
        visited: set[str] = set()
        seen_asset_ids: set[str] = set()
        while queue:
            folder_id, folder_name, folder_path, depth = queue.pop(0)
            if folder_id in visited:
                continue
            visited.add(folder_id)
            page = 1
            while True:
                listing = self._course_asset_page(
                    context,
                    course,
                    clazz,
                    folder_id=folder_id,
                    folder_name=folder_name,
                    folder_path=folder_path,
                    depth=depth,
                    page=page,
                    recycled=recycled,
                )
                for item in listing["items"]:
                    if item["asset_id"] in seen_asset_ids:
                        continue
                    seen_asset_ids.add(item["asset_id"])
                    item["index"] = len(tree) + 1
                    tree.append(item)
                    if len(tree) > max_nodes:
                        raise ChaoxingAPIError(
                            f"{context['kind']} tree exceeded the {max_nodes}-item safety limit"
                        )
                    if item["is_folder"]:
                        queue.append(
                            (
                                item["asset_id"],
                                item["name"],
                                item["path"],
                                depth + 1,
                            )
                        )
                total_pages = max(1, int(listing["total_pages"] or 0))
                if page >= total_pages:
                    break
                page += 1
        return tree

    @staticmethod
    def _resolve_course_asset(
        items: list[dict[str, Any]],
        query: str,
        *,
        require_folder: bool | None = None,
    ) -> dict[str, Any]:
        normalized = str(query or "").strip().lower().replace("\\", "/").strip("/")
        if not normalized:
            raise ChaoxingAPIError("course asset title, path, or ID is required")
        candidates = [
            item
            for item in items
            if require_folder is None or bool(item["is_folder"]) is require_folder
        ]
        for key in ("asset_id", "path", "name"):
            exact = [
                item
                for item in candidates
                if str(item.get(key) or "").strip().lower().replace("\\", "/").strip("/")
                == normalized
            ]
            if len(exact) == 1:
                return exact[0]
            if len(exact) > 1:
                options = ", ".join(f"{item['path']} ({item['asset_id']})" for item in exact[:10])
                raise ChaoxingAPIError(f"multiple course assets match: {options}")
        partial = [
            item
            for item in candidates
            if normalized in str(item.get("path") or item.get("name") or "").lower()
        ]
        if len(partial) == 1:
            return partial[0]
        if not partial:
            raise ChaoxingAPIError(f"course asset not found: {query}")
        options = ", ".join(f"{item['path']} ({item['asset_id']})" for item in partial[:10])
        raise ChaoxingAPIError(f"multiple course assets match: {options}")

    def list_course_assets(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        kind: str,
        *,
        folder: str = "",
        search: str = "",
        page: int = 1,
        page_size: int = 1000,
    ) -> dict[str, Any]:
        context = self._course_asset_context(course, clazz, kind)
        parent = {
            "asset_id": "0",
            "name": "根目录",
            "path": "",
            "is_folder": True,
        }
        if str(folder or "").strip():
            tree = self._course_asset_tree_from_context(context, course, clazz)
            parent = self._resolve_course_asset(tree, folder, require_folder=True)
        listing = self._course_asset_page(
            context,
            course,
            clazz,
            folder_id=parent["asset_id"],
            folder_name=parent["name"],
            folder_path=parent["path"],
            depth=int(parent.get("depth") or 0) + 1,
            search=search,
            page=page,
            page_size=page_size,
        )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "kind": context["kind"],
            "kind_label": context["config"]["label"],
            "parent": parent,
            "search": search,
            **listing,
            "verification": (f"read {len(listing['items'])} {context['kind']} items through HTTP"),
        }

    def list_course_asset_tree(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        kind: str,
        *,
        search: str = "",
    ) -> dict[str, Any]:
        context = self._course_asset_context(course, clazz, kind)
        tree = self._course_asset_tree_from_context(context, course, clazz)
        normalized_search = str(search or "").strip().lower()
        items = (
            [
                item
                for item in tree
                if normalized_search in str(item.get("path") or item["name"]).lower()
            ]
            if normalized_search
            else tree
        )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "kind": context["kind"],
            "kind_label": context["config"]["label"],
            "search": search,
            "count": len(items),
            "items": items,
            "verification": f"traversed {len(tree)} {context['kind']} items through HTTP",
        }

    @staticmethod
    def _validate_course_asset_name(name: str) -> str:
        normalized = str(name or "").strip()
        if not normalized or len(normalized) > 200:
            raise ChaoxingAPIError("course asset name must contain 1-200 characters")
        if re.search(r"[<>\x00-\x1f]", normalized):
            raise ChaoxingAPIError("course asset name contains an unsupported character")
        return normalized

    def _course_asset_direct_items(
        self,
        context: dict[str, Any],
        course: dict[str, Any],
        clazz: dict[str, Any],
        parent: dict[str, Any],
        *,
        recycled: bool = False,
    ) -> list[dict[str, Any]]:
        items: list[dict[str, Any]] = []
        page = 1
        while True:
            listing = self._course_asset_page(
                context,
                course,
                clazz,
                folder_id=str(parent["asset_id"]),
                folder_name=str(parent["name"]),
                folder_path=str(parent.get("path") or ""),
                depth=int(parent.get("depth") or 0) + 1,
                page=page,
                recycled=recycled,
            )
            items.extend(listing["items"])
            if page >= max(1, int(listing["total_pages"] or 0)):
                return items
            page += 1

    def create_course_asset_folder(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        kind: str,
        name: str,
        *,
        parent: str = "",
    ) -> dict[str, Any]:
        folder_name = self._validate_course_asset_name(name)
        context = self._course_asset_context(course, clazz, kind)
        destination: dict[str, Any] = {
            "asset_id": "0",
            "name": "根目录",
            "path": "",
            "depth": 0,
            "is_folder": True,
        }
        if str(parent or "").strip():
            tree = self._course_asset_tree_from_context(context, course, clazz)
            destination = self._resolve_course_asset(tree, parent, require_folder=True)
        before = self._course_asset_direct_items(context, course, clazz, destination)
        before_ids = {item["asset_id"] for item in before}
        data: dict[str, Any] = {
            "courseId": course["course_id"],
            "parentFolderId": destination["asset_id"],
            "name": folder_name,
            "shareType": 0,
            "folderViewPermissionsType": 1,
            "viewUidList": "",
            "editUidList": "",
        }
        if context["kind"] == "courseware":
            data["viewClassIdList"] = ""
        else:
            data.update({"DB_STRATEGY": "COURSEID", "STRATEGY_PARA": "courseId"})
        payload = self._course_asset_json_request(
            context,
            context["config"]["folder_create_path"],
            f"{context['kind']} folder creation",
            method="POST",
            data=data,
        )
        created: list[dict[str, Any]] = []
        for attempt in range(5):
            after = self._course_asset_direct_items(context, course, clazz, destination)
            created = [
                item
                for item in after
                if item["asset_id"] not in before_ids
                and item["is_folder"]
                and item["name"] == folder_name
            ]
            if len(created) == 1:
                break
            if attempt < 4:
                sleep(0.5)
        if len(created) != 1:
            raise ChaoxingAPIError(
                "server accepted course asset folder creation, but one new folder was not found"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "kind": context["kind"],
            "parent": destination,
            "folder": created[0],
            "server_data": payload.get("data"),
            "verification": (
                f"created {context['kind']} folder and re-read ID {created[0]['asset_id']}"
            ),
        }

    def import_cloud_files_to_course_assets(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        kind: str,
        resources: list[str],
        *,
        destination: str = "",
    ) -> dict[str, Any]:
        if not resources:
            raise ChaoxingAPIError("at least one cloud-disk file is required")
        if len(resources) > 100:
            raise ChaoxingAPIError("at most 100 cloud-disk files can be imported per request")
        context = self._course_asset_context(course, clazz, kind)
        tree = self._course_asset_tree_from_context(context, course, clazz)
        target: dict[str, Any] = {
            "asset_id": "0",
            "name": "根目录",
            "path": "",
            "depth": 0,
            "is_folder": True,
        }
        if str(destination or "").strip():
            target = self._resolve_course_asset(tree, destination, require_folder=True)

        cloud_context = self._cloud_disk_context(context["session"])
        selected: list[dict[str, Any]] = []
        for query in resources:
            item = self._resolve_active_cloud_disk_item(cloud_context, query)
            if not item["is_file"]:
                raise ChaoxingAPIError(f"cloud-disk item is not a file: {query}")
            if not item["object_id"]:
                raise ChaoxingAPIError(f"cloud-disk file exposes no object ID: {query}")
            if all(existing["resource_id"] != item["resource_id"] for existing in selected):
                selected.append(item)

        before = self._course_asset_direct_items(context, course, clazz, target)
        before_ids = {item["asset_id"] for item in before}
        ppt_data = [
            {
                "suffix": str(item.get("suffix") or "").lstrip("."),
                "objectId": item["object_id"],
                "name": item["name"],
                "size": item["byte_count"],
            }
            for item in selected
        ]
        params = (
            {"DB_STRATEGY": "COURSEID", "STRATEGY_PARA": "courseId"}
            if context["kind"] == "teaching_plan"
            else None
        )
        payload = self._course_asset_json_request(
            context,
            context["config"]["cloud_import_path"],
            f"{context['kind']} cloud-file import",
            method="POST",
            params=params,
            data={
                "courseId": course["course_id"],
                "parentFolderId": target["asset_id"],
                "pptData": json.dumps(ppt_data, ensure_ascii=False, separators=(",", ":")),
            },
        )

        imported: list[dict[str, Any]] = []
        selected_object_ids = {item["object_id"] for item in selected}
        selected_names = {str(item["name"]).strip().lower() for item in selected}
        for attempt in range(7):
            after = self._course_asset_direct_items(context, course, clazz, target)
            new_items = [item for item in after if item["asset_id"] not in before_ids]
            imported = [
                item
                for item in new_items
                if item["object_id"] in selected_object_ids
                or str(item["name"]).strip().lower() in selected_names
            ]
            matched_object_ids = {item["object_id"] for item in imported if item.get("object_id")}
            matched_names = {str(item["name"]).strip().lower() for item in imported}
            if selected_object_ids.issubset(matched_object_ids) or selected_names.issubset(
                matched_names
            ):
                break
            if attempt < 6:
                sleep(0.5)
        matched_object_ids = {item["object_id"] for item in imported if item.get("object_id")}
        matched_names = {str(item["name"]).strip().lower() for item in imported}
        if not (
            selected_object_ids.issubset(matched_object_ids)
            or selected_names.issubset(matched_names)
        ):
            raise ChaoxingAPIError(
                "server accepted the cloud-file import, but not every selected file appeared"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "kind": context["kind"],
            "destination": target,
            "selected": [self._public_cloud_disk_item(item) for item in selected],
            "imported": imported,
            "server_data": payload.get("data"),
            "verification": (
                f"imported and re-read {len(selected)} cloud files in {context['kind']}"
            ),
        }

    def rename_course_asset(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        kind: str,
        asset: str,
        name: str,
    ) -> dict[str, Any]:
        next_name = self._validate_course_asset_name(name)
        context = self._course_asset_context(course, clazz, kind)
        tree = self._course_asset_tree_from_context(context, course, clazz)
        selected = self._resolve_course_asset(tree, asset)
        self._course_asset_json_request(
            context,
            "/widget/coursewareActive/changeActiveName",
            f"{context['kind']} rename",
            method="POST",
            data={"activeId": selected["asset_id"], "newName": next_name},
        )
        refreshed = self._course_asset_tree_from_context(context, course, clazz)
        updated = self._resolve_course_asset(refreshed, selected["asset_id"])
        if updated["name"] != next_name:
            raise ChaoxingAPIError("course asset name did not match after refresh")
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "kind": context["kind"],
            "before": selected,
            "asset": updated,
            "verification": f"renamed {context['kind']} asset {updated['asset_id']} and re-read it",
        }

    def set_course_asset_top_status(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        kind: str,
        asset: str,
        *,
        top: bool,
    ) -> dict[str, Any]:
        context = self._course_asset_context(course, clazz, kind)
        tree = self._course_asset_tree_from_context(context, course, clazz)
        selected = self._resolve_course_asset(tree, asset)
        self._course_asset_json_request(
            context,
            "/widget/teachingPlan/fileSetTop",
            f"{context['kind']} top-status update",
            params={
                "activeId": selected["asset_id"],
                "courseId": course["course_id"],
                "parentFolderId": selected["parent_id"],
                "topsign": 1 if top else 0,
            },
        )
        refreshed = self._course_asset_tree_from_context(context, course, clazz)
        updated = self._resolve_course_asset(refreshed, selected["asset_id"])
        if bool(updated["is_top"]) is not bool(top):
            raise ChaoxingAPIError("course asset top status did not match after refresh")
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "kind": context["kind"],
            "before": selected,
            "asset": updated,
            "verification": f"updated and re-read top status for {updated['asset_id']}",
        }

    def move_course_assets(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        kind: str,
        assets: list[str],
        *,
        destination: str = "",
    ) -> dict[str, Any]:
        if not assets:
            raise ChaoxingAPIError("at least one course asset is required")
        context = self._course_asset_context(course, clazz, kind)
        tree = self._course_asset_tree_from_context(context, course, clazz)
        selected: list[dict[str, Any]] = []
        for query in assets:
            item = self._resolve_course_asset(tree, query)
            if all(existing["asset_id"] != item["asset_id"] for existing in selected):
                selected.append(item)
        target: dict[str, Any] = {
            "asset_id": "0",
            "name": "根目录",
            "path": "",
            "depth": 0,
            "is_folder": True,
        }
        if str(destination or "").strip():
            target = self._resolve_course_asset(tree, destination, require_folder=True)
        for item in selected:
            if item["asset_id"] == target["asset_id"]:
                raise ChaoxingAPIError("a course asset folder cannot be moved into itself")
            if item["is_folder"] and str(target["path"]).startswith(str(item["path"]) + "/"):
                raise ChaoxingAPIError("a course asset folder cannot be moved into a descendant")
            if item["parent_id"] == target["asset_id"]:
                raise ChaoxingAPIError(
                    f"course asset is already in the destination: {item['name']}"
                )
        self._course_asset_json_request(
            context,
            "/widget/teachingPlan/moveTeachPlanFiles",
            f"{context['kind']} move",
            params={
                "DB_STRATEGY": "COURSEID",
                "STRATEGY_PARA": "courseId",
                "activeIds": ",".join(item["asset_id"] for item in selected) + ",",
                "toFileId": target["asset_id"],
                "courseId": course["course_id"],
            },
        )
        refreshed = self._course_asset_tree_from_context(context, course, clazz)
        moved = [self._resolve_course_asset(refreshed, item["asset_id"]) for item in selected]
        if any(item["parent_id"] != target["asset_id"] for item in moved):
            raise ChaoxingAPIError(
                "one or more course assets have a different parent after refresh"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "kind": context["kind"],
            "destination": target,
            "assets": moved,
            "verification": f"moved and re-read {len(moved)} {context['kind']} assets",
        }

    def copy_course_asset(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        kind: str,
        asset: str,
    ) -> dict[str, Any]:
        context = self._course_asset_context(course, clazz, kind)
        tree = self._course_asset_tree_from_context(context, course, clazz)
        selected = self._resolve_course_asset(tree, asset, require_folder=False)
        parent = {
            "asset_id": selected["parent_id"],
            "name": selected["parent_name"],
            "path": "/".join(selected["path"].split("/")[:-1]),
            "depth": selected["depth"] - 1,
        }
        before = self._course_asset_direct_items(context, course, clazz, parent)
        before_ids = {item["asset_id"] for item in before}
        self._course_asset_json_request(
            context,
            context["config"]["copy_path"],
            f"{context['kind']} copy",
            method="POST",
            params={"DB_STRATEGY": "COURSEID", "STRATEGY_PARA": "courseId"},
            data={
                "teachPlanId": selected["asset_id"],
                "paid": selected["parent_id"],
                "courseId": course["course_id"],
            },
        )
        copies: list[dict[str, Any]] = []
        for attempt in range(5):
            after = self._course_asset_direct_items(context, course, clazz, parent)
            copies = [item for item in after if item["asset_id"] not in before_ids]
            if len(copies) == 1:
                break
            if attempt < 4:
                sleep(0.5)
        if len(copies) != 1:
            raise ChaoxingAPIError("server accepted course asset copy, but one copy was not found")
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "kind": context["kind"],
            "source": selected,
            "asset": copies[0],
            "verification": f"copied {selected['asset_id']} to new ID {copies[0]['asset_id']}",
        }

    def delete_course_assets(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        kind: str,
        assets: list[str],
    ) -> dict[str, Any]:
        if not assets:
            raise ChaoxingAPIError("at least one course asset is required")
        context = self._course_asset_context(course, clazz, kind)
        tree = self._course_asset_tree_from_context(context, course, clazz)
        selected: list[dict[str, Any]] = []
        for query in assets:
            item = self._resolve_course_asset(tree, query)
            if all(existing["asset_id"] != item["asset_id"] for existing in selected):
                selected.append(item)
        selected_ids = {item["asset_id"] for item in selected}
        selected = [
            item
            for item in selected
            if not any(
                ancestor["asset_id"] in selected_ids
                and str(item["path"]).startswith(str(ancestor["path"]) + "/")
                for ancestor in selected
                if ancestor["is_folder"] and ancestor["asset_id"] != item["asset_id"]
            )
        ]
        self._course_asset_json_request(
            context,
            "/widget/CWareDataController/deleteCPlansById",
            f"{context['kind']} deletion",
            params={"cPlanIds": ",".join(item["asset_id"] for item in selected)},
        )
        refreshed = self._course_asset_tree_from_context(context, course, clazz)
        remaining_ids = {item["asset_id"] for item in refreshed}
        if any(item["asset_id"] in remaining_ids for item in selected):
            raise ChaoxingAPIError("one or more deleted course assets remain in the active tree")
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "kind": context["kind"],
            "deleted": selected,
            "recoverable": True,
            "verification": (
                f"removed {len(selected)} assets from the active {context['kind']} tree"
            ),
        }

    def download_course_asset(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        kind: str,
        asset: str,
        output_path: str | Path,
        *,
        overwrite: bool = False,
    ) -> dict[str, Any]:
        context = self._course_asset_context(course, clazz, kind)
        tree = self._course_asset_tree_from_context(context, course, clazz)
        selected = self._resolve_course_asset(tree, asset, require_folder=False)
        payload = self._course_asset_json_request(
            context,
            "/v2/apis/ppt/getPptInfo",
            f"{context['kind']} download metadata",
            params={"activeId": selected["asset_id"]},
        )
        metadata = payload.get("data") if isinstance(payload.get("data"), dict) else {}
        file_name = str(metadata.get("name") or selected["name"]).strip()
        suffix = str(metadata.get("suffix") or selected["suffix"]).strip().lstrip(".")
        if suffix and not file_name.lower().endswith("." + suffix.lower()):
            file_name += "." + suffix
        object_id = str(metadata.get("objectId") or selected.get("object_id") or "").strip()
        if not object_id:
            raise ChaoxingAPIError("course asset metadata returned no object ID")
        download_url = append_query_params(
            MOBILELEARN_BASE_URL + "/widget/yunpan/proxyDownload",
            {
                "DB_STRATEGY": "RANDOM",
                "objectid": object_id,
                "name": file_name,
            },
        )
        parsed = urlparse(download_url)
        if parsed.scheme not in {"http", "https"} or not parsed.hostname:
            raise ChaoxingAPIError("course asset metadata returned no safe download target")
        try:
            response = context["session"].get(
                download_url,
                timeout=max(self.timeout, 300),
                stream=True,
                allow_redirects=True,
                headers={"Referer": context["root_url"]},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"course asset download failed: {exc}") from exc
        content_type = str(response.headers.get("Content-Type") or "").lower()
        if "text/html" in content_type:
            raise ChaoxingAPIError("course asset download returned HTML instead of a file")
        server_name = content_disposition_filename(
            str(response.headers.get("Content-Disposition") or "")
        )
        target = self._resource_download_target(
            output_path,
            suggested_name=server_name or file_name,
            overwrite=overwrite,
        )
        temporary = target.with_name(target.name + ".part")
        if temporary.exists():
            raise ChaoxingAPIError(f"temporary download target already exists: {temporary}")
        byte_count = 0
        try:
            with temporary.open("wb") as stream:
                for chunk in response.iter_content(chunk_size=1024 * 256):
                    if chunk:
                        stream.write(chunk)
                        byte_count += len(chunk)
            temporary.replace(target)
        except OSError as exc:
            temporary.unlink(missing_ok=True)
            raise ChaoxingAPIError(f"could not save course asset download: {exc}") from exc
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "kind": context["kind"],
            "asset": selected,
            "output_path": str(target),
            "file_name": target.name,
            "byte_count": byte_count,
            "content_type": content_type,
            "verification": "saved the authenticated course asset response as a local file",
        }

    def list_course_asset_recycle(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        kind: str,
        *,
        search: str = "",
    ) -> dict[str, Any]:
        context = self._course_asset_context(course, clazz, kind)
        tree = self._course_asset_tree_from_context(
            context,
            course,
            clazz,
            recycled=True,
        )
        normalized_search = str(search or "").strip().lower()
        items = (
            [item for item in tree if normalized_search in item["path"].lower()]
            if normalized_search
            else tree
        )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "kind": context["kind"],
            "search": search,
            "count": len(items),
            "items": items,
            "verification": f"traversed {len(tree)} recycled {context['kind']} items",
        }

    def restore_course_asset_recycle_items(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        kind: str,
        assets: list[str],
    ) -> dict[str, Any]:
        if not assets:
            raise ChaoxingAPIError("at least one recycled course asset is required")
        context = self._course_asset_context(course, clazz, kind)
        recycle_tree = self._course_asset_tree_from_context(context, course, clazz, recycled=True)
        selected: list[dict[str, Any]] = []
        for query in assets:
            item = self._resolve_course_asset(recycle_tree, query)
            if all(existing["asset_id"] != item["asset_id"] for existing in selected):
                selected.append(item)
        self._course_asset_json_request(
            context,
            "/v2/apis/recycleBinPpt/recyclePptById",
            f"{context['kind']} recycle restore",
            params={
                "DB_STRATEGY": "PRIMARY_KEY",
                "STRATEGY_PARA": "primaryKey",
                "cPlanIds": ",".join(item["asset_id"] for item in selected),
                "primaryKey": selected[0]["asset_id"],
                "courseId": course["course_id"],
            },
        )
        refreshed_recycle = self._course_asset_tree_from_context(
            context, course, clazz, recycled=True
        )
        recycled_ids = {item["asset_id"] for item in refreshed_recycle}
        if any(item["asset_id"] in recycled_ids for item in selected):
            raise ChaoxingAPIError("one or more restored course assets remain in recycle")
        active_tree = self._course_asset_tree_from_context(context, course, clazz)
        active_ids = {item["asset_id"] for item in active_tree}
        if any(item["asset_id"] not in active_ids for item in selected):
            raise ChaoxingAPIError(
                "one or more restored course assets are absent from active items"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "kind": context["kind"],
            "restored": selected,
            "verification": f"restored and re-read {len(selected)} {context['kind']} assets",
        }

    def permanently_delete_course_asset_recycle_items(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        kind: str,
        assets: list[str],
    ) -> dict[str, Any]:
        if not assets:
            raise ChaoxingAPIError("at least one recycled course asset is required")
        context = self._course_asset_context(course, clazz, kind)
        recycle_tree = self._course_asset_tree_from_context(context, course, clazz, recycled=True)
        selected: list[dict[str, Any]] = []
        for query in assets:
            item = self._resolve_course_asset(recycle_tree, query)
            if all(existing["asset_id"] != item["asset_id"] for existing in selected):
                selected.append(item)
        self._course_asset_json_request(
            context,
            "/v2/apis/recycleBinPpt/deleteCompletely",
            f"{context['kind']} permanent deletion",
            params={
                "DB_STRATEGY": "COURSEID",
                "STRATEGY_PARA": "courseId",
                "cPlanIds": ",".join(item["asset_id"] for item in selected),
                "classId": clazz["clazz_id"],
                "courseId": course["course_id"],
            },
        )
        refreshed = self._course_asset_tree_from_context(context, course, clazz, recycled=True)
        remaining_ids = {item["asset_id"] for item in refreshed}
        if any(item["asset_id"] in remaining_ids for item in selected):
            raise ChaoxingAPIError("one or more permanently deleted assets remain in recycle")
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "kind": context["kind"],
            "deleted": selected,
            "verification": (
                f"permanently deleted {len(selected)} recycled {context['kind']} assets"
            ),
        }

    def _chapter_editor_context(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        session: requests.Session | None = None,
    ) -> dict[str, Any]:
        active_session = session or self._session()
        endpoint = f"{MOOC1_BASE_URL}/edit/chapters/{course['course_id']}/0"
        try:
            response = active_session.get(
                endpoint,
                params={
                    "classId": clazz["clazz_id"],
                    "cpi": course["cpi"],
                    "newMooc": "true",
                    "mooc2": "1",
                },
                timeout=self.timeout,
                allow_redirects=True,
                headers={"Referer": build_teacher_entry_url(course, clazz)},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"chapter editor request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError("chapter editor request was redirected to login")
        html = self._decode(response)
        parsed = parse_chapter_editor_tree(html)
        return {
            **parsed,
            "session": active_session,
            "editor_url": str(response.url),
            "editor_html": html,
        }

    def _chapter_editor_post(
        self,
        context: dict[str, Any],
        path: str,
        data: dict[str, Any],
        operation: str,
        *,
        allow_non_json: bool = False,
    ) -> dict[str, Any]:
        try:
            response = context["session"].post(
                MOOC1_BASE_URL + path,
                data=data,
                timeout=max(self.timeout, 60),
                headers={
                    "Origin": MOOC1_BASE_URL,
                    "Referer": context["editor_url"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"{operation} failed: {exc}") from exc
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            if allow_non_json:
                return {"http_status": response.status_code}
            raise ChaoxingAPIError(f"{operation} returned invalid JSON") from exc
        if not isinstance(payload, dict):
            raise ChaoxingAPIError(f"{operation} returned invalid JSON")
        failed = payload.get("status") is False or payload.get("success") is False
        if "result" in payload and str(payload.get("result")) == "0":
            failed = True
        if failed:
            raise ChaoxingAPIError(str(payload.get("msg") or f"{operation} was rejected"))
        return payload

    @staticmethod
    def _chapter_descendant_ids(item: dict[str, Any]) -> list[str]:
        ids = [str(item.get("chapter_id") or "")]
        for child in item.get("children") or []:
            if isinstance(child, dict):
                ids.extend(ChaoxingAPI._chapter_descendant_ids(child))
        return [chapter_id for chapter_id in ids if chapter_id]

    def list_chapter_tree(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> dict[str, Any]:
        context = self._chapter_editor_context(course, clazz)
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "chapter_count": context["chapter_count"],
            "max_depth": context["max_depth"],
            "chapters": context["chapters"],
            "verification": (
                f"parsed {context['chapter_count']} nodes from the authenticated chapter editor"
            ),
        }

    def create_chapter(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        title: str,
        *,
        parent: str = "",
        before: str = "",
    ) -> dict[str, Any]:
        normalized_title = title.strip()
        if not normalized_title:
            raise ChaoxingAPIError("chapter title is required")
        context = self._chapter_editor_context(course, clazz)
        parent_id = "0"
        depth = 1
        parent_item: dict[str, Any] | None = None
        if parent.strip() and parent.strip().lower() not in {"0", "root", "顶层", "根目录"}:
            parent_item = resolve_chapter_editor_item(context["flat_chapters"], parent)
            parent_id = parent_item["chapter_id"]
            depth = int(parent_item["depth"]) + 1
        if depth > 7:
            raise ChaoxingAPIError("Chaoxing chapter hierarchy supports at most 7 levels")
        form: dict[str, Any] = {
            "name": normalized_title,
            "courseid": course["course_id"],
            "parentid": parent_id,
            "layer": str(depth),
            "mooc2": "1",
        }
        before_item: dict[str, Any] | None = None
        if before.strip():
            before_item = resolve_chapter_editor_item(context["flat_chapters"], before)
            if before_item["parent_id"] != parent_id:
                raise ChaoxingAPIError("before chapter must have the requested parent")
            form["siblingid"] = before_item["chapter_id"]
        payload = self._chapter_editor_post(
            context,
            "/edit/createchapter",
            form,
            "chapter creation",
        )
        created_id = str(payload.get("id") or "")
        refreshed = self._chapter_editor_context(course, clazz, session=context["session"])
        if created_id:
            created = resolve_chapter_editor_item(refreshed["flat_chapters"], created_id)
        else:
            before_ids = {item["chapter_id"] for item in context["flat_chapters"]}
            additions = [
                item
                for item in refreshed["flat_chapters"]
                if item["chapter_id"] not in before_ids
                and item["title"] == normalized_title
                and item["parent_id"] == parent_id
            ]
            if len(additions) != 1:
                raise ChaoxingAPIError("created chapter could not be identified after refresh")
            created = additions[0]
        if created["title"] != normalized_title or created["parent_id"] != parent_id:
            raise ChaoxingAPIError("created chapter did not match the requested title and parent")
        if before_item:
            siblings = [
                item for item in refreshed["flat_chapters"] if item["parent_id"] == parent_id
            ]
            positions = {item["chapter_id"]: item["position"] for item in siblings}
            if positions[created["chapter_id"]] >= positions[before_item["chapter_id"]]:
                raise ChaoxingAPIError(
                    "created chapter was not placed before the requested sibling"
                )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "chapter": created,
            "server_message": str(payload.get("msg") or ""),
            "verification": f"created and re-read chapter {created['chapter_id']} through HTTP",
        }

    def rename_chapter(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        chapter_query: str,
        title: str,
    ) -> dict[str, Any]:
        normalized_title = title.strip()
        if not normalized_title:
            raise ChaoxingAPIError("chapter title is required")
        context = self._chapter_editor_context(course, clazz)
        selected = resolve_chapter_editor_item(context["flat_chapters"], chapter_query)
        payload = self._chapter_editor_post(
            context,
            "/edit/changename",
            {
                "courseid": course["course_id"],
                "nodeid": selected["chapter_id"],
                "name": normalized_title,
            },
            "chapter rename",
        )
        refreshed = self._chapter_editor_context(course, clazz, session=context["session"])
        renamed = resolve_chapter_editor_item(refreshed["flat_chapters"], selected["chapter_id"])
        if renamed["title"] != normalized_title:
            raise ChaoxingAPIError("renamed chapter title did not match after refresh")
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "before": selected,
            "chapter": renamed,
            "server_message": str(payload.get("msg") or ""),
            "verification": f"renamed and re-read chapter {renamed['chapter_id']} through HTTP",
        }

    def move_chapter(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        chapter_query: str,
        *,
        parent: str = "",
        relative_to: str = "",
        position: str = "after",
    ) -> dict[str, Any]:
        if bool(parent.strip()) == bool(relative_to.strip()):
            raise ChaoxingAPIError("provide exactly one of parent or relative_to")
        normalized_position = position.strip().lower()
        if normalized_position not in {"before", "after"}:
            raise ChaoxingAPIError("chapter position must be before or after")
        context = self._chapter_editor_context(course, clazz)
        selected = resolve_chapter_editor_item(context["flat_chapters"], chapter_query)
        selected_ids = set(self._chapter_descendant_ids(selected))
        if parent.strip():
            if parent.strip().lower() in {"0", "root", "顶层", "根目录"}:
                parent_id = "0"
            else:
                parent_item = resolve_chapter_editor_item(context["flat_chapters"], parent)
                parent_id = parent_item["chapter_id"]
                if parent_id in selected_ids:
                    raise ChaoxingAPIError(
                        "a chapter cannot be moved into itself or its descendant"
                    )
                if int(parent_item["depth"]) + 1 > 7:
                    raise ChaoxingAPIError("Chaoxing chapter hierarchy supports at most 7 levels")
            payload = self._chapter_editor_post(
                context,
                "/edit/chaptermove",
                {
                    "courseid": course["course_id"],
                    "nodeid": selected["chapter_id"],
                    "pnodeid": parent_id,
                },
                "chapter move",
            )
            expected_parent_id = parent_id
            relative_item = None
        else:
            relative_item = resolve_chapter_editor_item(context["flat_chapters"], relative_to)
            if relative_item["chapter_id"] in selected_ids:
                raise ChaoxingAPIError("a chapter cannot be positioned relative to itself")
            payload = self._chapter_editor_post(
                context,
                "/edit/movechapter",
                {
                    "courseid": course["course_id"],
                    "nodeid": selected["chapter_id"],
                    "destid": relative_item["chapter_id"],
                    "position": normalized_position,
                },
                "chapter reorder",
            )
            expected_parent_id = relative_item["parent_id"]
        refreshed = self._chapter_editor_context(course, clazz, session=context["session"])
        moved = resolve_chapter_editor_item(refreshed["flat_chapters"], selected["chapter_id"])
        if moved["parent_id"] != expected_parent_id:
            raise ChaoxingAPIError("moved chapter parent did not match after refresh")
        if relative_item:
            relative_after = resolve_chapter_editor_item(
                refreshed["flat_chapters"], relative_item["chapter_id"]
            )
            correct_order = (
                moved["position"] < relative_after["position"]
                if normalized_position == "before"
                else moved["position"] > relative_after["position"]
            )
            if not correct_order:
                raise ChaoxingAPIError("chapter order did not match after refresh")
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "before": selected,
            "chapter": moved,
            "server_message": str(payload.get("msg") or ""),
            "verification": f"moved and re-read chapter {moved['chapter_id']} through HTTP",
        }

    def import_chapter_outline(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        outline: str,
    ) -> dict[str, Any]:
        normalized_outline = outline.strip("\r\n")
        if not normalized_outline.strip():
            raise ChaoxingAPIError("chapter outline text is required")
        context = self._chapter_editor_context(course, clazz)
        before_ids = {item["chapter_id"] for item in context["flat_chapters"]}
        payload = self._chapter_editor_post(
            context,
            "/edit/importdirForText",
            {"courseId": course["course_id"], "text": normalized_outline},
            "chapter outline import",
            allow_non_json=True,
        )
        refreshed = self._chapter_editor_context(course, clazz, session=context["session"])
        created = [
            item for item in refreshed["flat_chapters"] if item["chapter_id"] not in before_ids
        ]
        if not created:
            raise ChaoxingAPIError("chapter outline import created no verifiable chapter nodes")
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "created_count": len(created),
            "created_chapters": created,
            "server_message": str(payload.get("msg") or ""),
            "verification": f"imported and re-read {len(created)} new chapter nodes through HTTP",
        }

    def delete_chapters(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        chapter_queries: list[str],
    ) -> dict[str, Any]:
        if not chapter_queries:
            raise ChaoxingAPIError("at least one chapter is required")
        context = self._chapter_editor_context(course, clazz)
        selected = [
            resolve_chapter_editor_item(context["flat_chapters"], query)
            for query in chapter_queries
        ]
        selected_ids: list[str] = []
        for item in selected:
            for chapter_id in self._chapter_descendant_ids(item):
                if chapter_id not in selected_ids:
                    selected_ids.append(chapter_id)
        if len(selected_ids) > 200:
            raise ChaoxingAPIError("Chaoxing batch deletion accepts at most 200 chapter nodes")
        try:
            response = context["session"].post(
                f"{MOOC2_BASE_URL}/mooc2-ans/mycourse/batchdeletechapters",
                data={
                    "courseid": course["course_id"],
                    "knowledgeids": ",".join(selected_ids),
                    "cpi": course["cpi"],
                },
                timeout=max(self.timeout, 60),
                headers={"Referer": build_teacher_entry_url(course, clazz)},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"chapter deletion failed: {exc}") from exc
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("chapter deletion returned invalid JSON") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "chapter deletion was rejected"))
        refreshed = self._chapter_editor_context(course, clazz, session=context["session"])
        remaining_ids = {item["chapter_id"] for item in refreshed["flat_chapters"]}
        not_deleted = [chapter_id for chapter_id in selected_ids if chapter_id in remaining_ids]
        if not_deleted:
            raise ChaoxingAPIError(
                "deleted chapters were still present after refresh: " + ", ".join(not_deleted)
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "deleted_count": len(selected_ids),
            "deleted_chapters": selected,
            "deleted_ids": selected_ids,
            "server_message": str(payload.get("msg") or ""),
            "verification": f"deleted {len(selected_ids)} nodes and confirmed their absence",
        }

    def set_chapter_open_status(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        chapter_queries: list[str],
        status: str,
        *,
        target_classes: list[dict[str, Any]] | None = None,
        begin: str = "",
        end: str = "",
        time_end_review: bool = False,
    ) -> dict[str, Any]:
        aliases = {
            "open": "open",
            "开放": "open",
            "task": "task",
            "闯关": "task",
            "闯关模式": "task",
            "time": "time",
            "定时": "time",
            "定时开放": "time",
            "close": "close",
            "closed": "close",
            "关闭": "close",
            "review": "review",
            "复习": "review",
            "复习模式": "review",
        }
        normalized_status = aliases.get(status.strip().lower())
        if not normalized_status:
            raise ChaoxingAPIError("chapter status must be open, task, time, close, or review")
        if normalized_status == "time" and (not begin.strip() or not end.strip()):
            raise ChaoxingAPIError("begin and end are required for timed chapter opening")
        if normalized_status != "time" and bool(begin.strip()) != bool(end.strip()):
            raise ChaoxingAPIError("begin and end must either both be set or both be empty")
        if not chapter_queries:
            raise ChaoxingAPIError("at least one chapter is required")
        context = self._chapter_editor_context(course, clazz)
        selected = [
            resolve_chapter_editor_item(context["flat_chapters"], query)
            for query in chapter_queries
        ]
        chapter_ids: list[str] = []
        verifiable_ids: list[str] = []
        for item in selected:
            descendants = self._chapter_descendant_ids(item)
            for chapter_id in descendants:
                if chapter_id not in chapter_ids:
                    chapter_ids.append(chapter_id)
            leaves = [
                candidate["chapter_id"]
                for candidate in context["flat_chapters"]
                if candidate["chapter_id"] in descendants and not candidate["has_children"]
            ]
            for chapter_id in leaves:
                if chapter_id not in verifiable_ids:
                    verifiable_ids.append(chapter_id)
        if not verifiable_ids:
            raise ChaoxingAPIError("selected chapters contain no learnable leaf node")
        classes = target_classes or [clazz]
        class_ids = [str(item.get("clazz_id") or "") for item in classes]
        if not all(class_ids):
            raise ChaoxingAPIError("target classes require clazz_id values")
        form = {
            "clazzids": ",".join(class_ids),
            "courseid": course["course_id"],
            "chapterids": ",".join(chapter_ids),
            "status": normalized_status,
            "beginTime": begin.strip(),
            "endTime": end.strip(),
            "clazzid": clazz["clazz_id"],
            "timeEndReview": "1" if time_end_review else "0",
            "cpi": course["cpi"],
            "setPrivilege": "false",
            "viewType": "-1",
            "editType": "-1",
            "viewTchList": "",
            "editTchList": "",
        }
        try:
            response = context["session"].post(
                f"{MOOC2_BASE_URL}/mooc2-ans/mycourse/changestatus",
                data=form,
                timeout=max(self.timeout, 60),
                headers={"Referer": build_teacher_entry_url(course, clazz)},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"chapter status update failed: {exc}") from exc
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("chapter status update returned invalid JSON") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "chapter status update was rejected"))
        verification_by_class: list[dict[str, Any]] = []
        for target_class in classes:
            refreshed = self.list_chapters(course, target_class)
            leaf_items = [
                child
                for parent_item in refreshed["chapters"]
                for child in parent_item.get("children", [])
            ]
            by_id = {item["chapter_id"]: item for item in leaf_items}
            mismatches = [
                chapter_id
                for chapter_id in verifiable_ids
                if by_id.get(chapter_id, {}).get("configured_open_status") != normalized_status
            ]
            if mismatches:
                raise ChaoxingAPIError(
                    "chapter status did not match after refresh for class "
                    f"{target_class.get('clazz_name') or target_class.get('clazz_id')}: "
                    + ", ".join(mismatches)
                )
            verification_by_class.append(
                {
                    "clazz_id": target_class["clazz_id"],
                    "clazz_name": target_class.get("clazz_name", ""),
                    "verified_leaf_ids": verifiable_ids,
                }
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "status": normalized_status,
            "begin": begin.strip(),
            "end": end.strip(),
            "time_end_review": time_end_review,
            "chapter_ids": chapter_ids,
            "target_classes": verification_by_class,
            "server_message": str(payload.get("msg") or ""),
            "verification": (
                f"updated {len(verifiable_ids)} learnable nodes across {len(classes)} class(es) "
                "and re-read their configured status"
            ),
        }

    def _chapter_cards_request(
        self,
        context: dict[str, Any],
        course: dict[str, Any],
        chapter: dict[str, Any],
    ) -> list[dict[str, Any]]:
        try:
            response = context["session"].get(
                f"{MOOC1_BASE_URL}/edit/getcard",
                params={
                    "cardid": "0",
                    "nodeid": chapter["chapter_id"],
                    "courseid": course["course_id"],
                    "cpi": course["cpi"],
                    "microTopicId": "0",
                },
                timeout=self.timeout,
                headers={"Referer": context["editor_url"]},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"chapter card list request failed: {exc}") from exc
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("chapter card list returned invalid JSON") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "chapter card list was rejected"))
        return parse_chapter_cards(payload)

    def list_chapter_cards(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        chapter_query: str,
    ) -> dict[str, Any]:
        context = self._chapter_editor_context(course, clazz)
        chapter = resolve_chapter_editor_item(context["flat_chapters"], chapter_query)
        cards = self._chapter_cards_request(context, course, chapter)
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "chapter": chapter,
            "card_count": len(cards),
            "cards": cards,
            "verification": f"read {len(cards)} chapter cards through authenticated HTTP",
        }

    def _save_chapter_card(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        chapter_query: str,
        *,
        card_query: str = "",
        title: str | None = None,
        content: str | None = None,
        content_format: str = "plain",
        attachments: list[dict[str, Any]] | None = None,
    ) -> dict[str, Any]:
        creating = not card_query.strip()
        if creating and title is None:
            raise ChaoxingAPIError("chapter card title is required")
        if not creating and title is None and content is None and attachments is None:
            raise ChaoxingAPIError("title, content, or attachments is required for card update")
        context = self._chapter_editor_context(course, clazz)
        chapter = resolve_chapter_editor_item(context["flat_chapters"], chapter_query)
        cards = self._chapter_cards_request(context, course, chapter)
        if creating and len(cards) >= 20:
            raise ChaoxingAPIError("Chaoxing permits at most 20 pages in one chapter")
        selected: dict[str, Any] | None = None
        if not creating:
            selected = resolve_chapter_card(cards, card_query)
        next_title = str(title if title is not None else selected["title"]).strip()
        if not next_title:
            raise ChaoxingAPIError("chapter card title is required")
        if content is None:
            next_html = str(selected["content_html"] if selected else "")
        else:
            next_html = self._question_rich_text(
                content,
                content_format,
                "chapter card content",
                allow_empty=True,
            )
        if attachments is None:
            manifest = list(selected.get("attachment_manifest") or []) if selected else []
        else:
            if not isinstance(attachments, list) or not all(
                isinstance(item, dict) for item in attachments
            ):
                raise ChaoxingAPIError("chapter card attachments must be a list of objects")
            manifest = attachments
        form: dict[str, Any] = {
            "title": next_title,
            "attachments": json.dumps(
                manifest,
                ensure_ascii=False,
                separators=(",", ":"),
            ),
            "description": next_html,
            "nodeid": chapter["chapter_id"],
            "courseId": course["course_id"],
            "recordJson": "",
            "aiJsonArray": "",
            "docPageInfo": "",
        }
        if selected:
            form["id"] = selected["card_id"]
        payload = self._chapter_editor_post(
            context,
            "/edit/savecard",
            form,
            "chapter card creation" if creating else "chapter card update",
        )
        saved_id = str(payload.get("id") or (selected or {}).get("card_id") or "")
        if not saved_id:
            raise ChaoxingAPIError("saved chapter card response exposed no card ID")
        refreshed = self._chapter_cards_request(context, course, chapter)
        saved = resolve_chapter_card(refreshed, saved_id)
        if saved["title"] != next_title:
            raise ChaoxingAPIError("saved chapter card title did not match after refresh")
        if saved["content"] != html_text(next_html):
            raise ChaoxingAPIError("saved chapter card content did not match after refresh")
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "chapter": chapter,
            "before": selected,
            "card": saved,
            "server_message": str(payload.get("msg") or ""),
            "verification": (
                f"{'created' if creating else 'updated'} and re-read chapter card {saved_id} "
                "through HTTP"
            ),
        }

    def create_chapter_card(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        chapter_query: str,
        title: str,
        *,
        content: str = "",
        content_format: str = "plain",
        attachments: list[dict[str, Any]] | None = None,
    ) -> dict[str, Any]:
        return self._save_chapter_card(
            course,
            clazz,
            chapter_query,
            title=title,
            content=content,
            content_format=content_format,
            attachments=attachments,
        )

    def update_chapter_card(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        chapter_query: str,
        card_query: str,
        *,
        title: str | None = None,
        content: str | None = None,
        content_format: str = "plain",
        attachments: list[dict[str, Any]] | None = None,
    ) -> dict[str, Any]:
        return self._save_chapter_card(
            course,
            clazz,
            chapter_query,
            card_query=card_query,
            title=title,
            content=content,
            content_format=content_format,
            attachments=attachments,
        )

    def move_chapter_card(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        chapter_query: str,
        card_query: str,
        target_position: int,
    ) -> dict[str, Any]:
        context = self._chapter_editor_context(course, clazz)
        chapter = resolve_chapter_editor_item(context["flat_chapters"], chapter_query)
        cards = self._chapter_cards_request(context, course, chapter)
        selected = resolve_chapter_card(cards, card_query)
        if not 1 <= target_position <= len(cards):
            raise ChaoxingAPIError(f"target_position must be between 1 and {len(cards)}")
        if selected["index"] == target_position:
            return {
                "course_id": course["course_id"],
                "course_name": course["course_name"],
                "clazz_id": clazz["clazz_id"],
                "clazz_name": clazz["clazz_name"],
                "chapter": chapter,
                "card": selected,
                "changed": False,
                "verification": "chapter card was already at the requested position",
            }
        anchor = cards[target_position - 1]
        payload = self._chapter_editor_post(
            context,
            "/edit/movecard",
            {
                "nodeid": chapter["chapter_id"],
                "selid": selected["card_id"],
                "othid": anchor["card_id"],
                "courseId": course["course_id"],
            },
            "chapter card move",
        )
        refreshed = self._chapter_cards_request(context, course, chapter)
        moved = resolve_chapter_card(refreshed, selected["card_id"])
        if moved["index"] != target_position:
            raise ChaoxingAPIError("chapter card position did not match after refresh")
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "chapter": chapter,
            "before": selected,
            "card": moved,
            "changed": True,
            "server_message": str(payload.get("msg") or ""),
            "verification": f"moved and re-read chapter card {moved['card_id']} through HTTP",
        }

    def delete_chapter_card(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        chapter_query: str,
        card_query: str,
    ) -> dict[str, Any]:
        context = self._chapter_editor_context(course, clazz)
        chapter = resolve_chapter_editor_item(context["flat_chapters"], chapter_query)
        cards = self._chapter_cards_request(context, course, chapter)
        selected = resolve_chapter_card(cards, card_query)
        payload = self._chapter_editor_post(
            context,
            "/edit/deletecard",
            {"id": selected["card_id"], "courseId": course["course_id"]},
            "chapter card deletion",
        )
        refreshed = self._chapter_cards_request(context, course, chapter)
        if any(item["card_id"] == selected["card_id"] for item in refreshed):
            raise ChaoxingAPIError("deleted chapter card was still present after refresh")
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "chapter": chapter,
            "deleted_card": selected,
            "remaining_card_count": len(refreshed),
            "server_message": str(payload.get("msg") or ""),
            "verification": (
                f"deleted chapter card {selected['card_id']} and confirmed its absence"
            ),
        }

    def list_chapters(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        search: str = "",
    ) -> dict[str, Any]:
        session = self._session()
        context = self._course_context(session, course, clazz)
        endpoint = f"{MOOC2_BASE_URL}/mooc2-ans/mycourse/tchcourselist"
        try:
            response = session.get(
                endpoint,
                params={
                    "courseid": course["course_id"],
                    "clazzid": clazz["clazz_id"],
                    "cpi": course["cpi"],
                    "searchChapterListByName": search,
                    "flag": "0",
                },
                timeout=self.timeout,
                headers={"Referer": str(context["final_url"])},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"chapter list request failed: {exc}") from exc
        html = self._decode(response)
        chapters = parse_chapter_items(html)
        item_count = len(chapters) + sum(len(item["children"]) for item in chapters)
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "search": search,
            "top_level_count": len(chapters),
            "chapter_count": item_count,
            "chapters": chapters,
            "verification": f"parsed {item_count} chapter nodes through HTTP",
        }

    def _resource_context(
        self,
        session: requests.Session,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> dict[str, Any]:
        course_context = self._course_context(session, course, clazz)
        module = resolve_module(course_context["modules"], "资料")
        root_url = self._module_url(course_context, module, course, clazz)
        try:
            response = session.get(
                root_url,
                timeout=self.timeout,
                headers={"Referer": str(course_context["final_url"])},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"resource context request failed: {exc}") from exc
        html = self._decode(response)
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError("Chaoxing login has expired")
        return {
            "session": session,
            "course_context": course_context,
            "root_url": response.url,
            "root_html": html,
            "hidden": parse_hidden_inputs(html),
        }

    def _resource_folder_items(
        self,
        context: dict[str, Any],
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        folder_id: str = "0",
        folder_name: str = "",
    ) -> list[dict[str, Any]]:
        session = context["session"]
        normalized_folder_id = str(folder_id or "0")
        endpoint = f"{MOOC2_BASE_URL}/mooc2-ans/coursedata"
        items: list[dict[str, Any]] = []
        page = 1
        total_pages = 1
        while page <= min(total_pages, 100):
            if normalized_folder_id != "0":
                params = {
                    "courseid": course["course_id"],
                    "clazzid": clazz["clazz_id"],
                    "dataName": folder_name,
                    "dataId": normalized_folder_id,
                    "type": "1",
                    "parent": "",
                    "flag": "0",
                    "enc": context["hidden"].get("enc", ""),
                    "ut": "t",
                    "cpi": course["cpi"],
                    "t": context["hidden"].get("t", ""),
                    "pages": str(page),
                }
                request_url = endpoint
            else:
                params = {"pages": str(page)}
                request_url = context["root_url"]
            try:
                response = session.get(
                    request_url,
                    params=params,
                    timeout=self.timeout,
                    headers={"Referer": context["root_url"]},
                )
                response.raise_for_status()
            except requests.RequestException as exc:
                raise ChaoxingAPIError(f"resource page request failed: {exc}") from exc
            html = self._decode(response)
            if page == 1:
                hidden = parse_hidden_inputs(html)
                try:
                    total_pages = max(1, int(hidden.get("totalPage") or "1"))
                except (TypeError, ValueError):
                    total_pages = 1
            items.extend(parse_course_data_items(html))
            page += 1
        for index, item in enumerate(items, 1):
            item["index"] = index
            item["parent_id"] = normalized_folder_id
            item["parent_name"] = folder_name or "根目录"
        return items

    def _resource_tree_from_context(
        self,
        context: dict[str, Any],
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        max_nodes: int = 2000,
    ) -> list[dict[str, Any]]:
        roots = self._resource_folder_items(context, course, clazz)
        flattened: list[dict[str, Any]] = []
        queue: list[dict[str, Any]] = []
        seen_folders: set[str] = set()
        for item in roots:
            enriched = {**item, "parent_id": "0", "depth": 1, "path": item["name"]}
            flattened.append(enriched)
            if enriched["is_folder"]:
                queue.append(enriched)
        while queue:
            parent = queue.pop(0)
            parent_id = str(parent["data_id"])
            if parent_id in seen_folders:
                continue
            seen_folders.add(parent_id)
            if int(parent["depth"]) >= 10:
                continue
            children = self._resource_folder_items(
                context,
                course,
                clazz,
                folder_id=parent_id,
                folder_name=str(parent["name"]),
            )
            for child in children:
                enriched = {
                    **child,
                    "parent_id": parent_id,
                    "depth": int(parent["depth"]) + 1,
                    "path": f"{parent['path']}/{child['name']}",
                }
                flattened.append(enriched)
                if len(flattened) > max_nodes:
                    raise ChaoxingAPIError(
                        f"resource tree exceeds the safety limit of {max_nodes} nodes"
                    )
                if enriched["is_folder"]:
                    queue.append(enriched)
        for index, item in enumerate(flattened, 1):
            item["index"] = index
        return flattened

    @staticmethod
    def _resource_json(response: requests.Response, operation: str) -> dict[str, Any]:
        text = ChaoxingAPI._decode(response).strip()
        try:
            payload: Any = json.loads(text)
            if isinstance(payload, str):
                payload = json.loads(payload)
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError(f"{operation} returned invalid JSON") from exc
        if not isinstance(payload, dict):
            raise ChaoxingAPIError(f"{operation} returned an unexpected response")
        return payload

    @staticmethod
    def _validate_resource_name(name: str, *, label: str = "resource name") -> str:
        normalized = str(name or "").strip()
        if len(normalized) < 2 or len(normalized) > 100:
            raise ChaoxingAPIError(f"{label} must contain 2-100 characters")
        if re.search(r"[`~!@#$%^&*+<>?:\"{},\\/;\[\]|]", normalized):
            raise ChaoxingAPIError(f"{label} contains a character rejected by Chaoxing")
        return normalized

    def _resolve_resource_from_context(
        self,
        context: dict[str, Any],
        course: dict[str, Any],
        clazz: dict[str, Any],
        query: str,
        *,
        require_folder: bool | None = None,
    ) -> dict[str, Any]:
        normalized = str(query or "").strip()
        if not normalized:
            return resolve_resource_item([], normalized, require_folder=require_folder)
        if "/" in normalized.replace("\\", "/"):
            segments = [value.strip() for value in normalized.replace("\\", "/").split("/")]
            segments = [value for value in segments if value]
            parent_id = "0"
            parent_name = "根目录"
            parent_path = ""
            selected: dict[str, Any] | None = None
            for index, segment in enumerate(segments):
                children = self._resource_folder_items(
                    context,
                    course,
                    clazz,
                    folder_id=parent_id,
                    folder_name=parent_name,
                )
                selected = resolve_resource_item(
                    children,
                    segment,
                    require_folder=True if index < len(segments) - 1 else require_folder,
                )
                selected = {
                    **selected,
                    "path": f"{parent_path}/{selected['name']}".lstrip("/"),
                    "depth": index + 1,
                }
                parent_id = str(selected["data_id"])
                parent_name = str(selected["name"])
                parent_path = str(selected["path"])
            if selected is not None:
                return selected
        if normalized.isdigit():
            roots = self._resource_folder_items(context, course, clazz)
            queue: list[dict[str, Any]] = []
            for item in roots:
                enriched = {**item, "path": item["name"], "depth": 1}
                if str(enriched["data_id"]) == normalized and (
                    require_folder is None or bool(enriched["is_folder"]) is require_folder
                ):
                    return enriched
                if enriched["is_folder"]:
                    queue.append(enriched)
            seen: set[str] = set()
            while queue:
                parent = queue.pop(0)
                parent_id = str(parent["data_id"])
                if parent_id in seen or int(parent["depth"]) >= 10:
                    continue
                seen.add(parent_id)
                children = self._resource_folder_items(
                    context,
                    course,
                    clazz,
                    folder_id=parent_id,
                    folder_name=str(parent["name"]),
                )
                for item in children:
                    enriched = {
                        **item,
                        "path": f"{parent['path']}/{item['name']}",
                        "depth": int(parent["depth"]) + 1,
                    }
                    if str(enriched["data_id"]) == normalized and (
                        require_folder is None or bool(enriched["is_folder"]) is require_folder
                    ):
                        return enriched
                    if enriched["is_folder"]:
                        queue.append(enriched)
            kind = "resource folder" if require_folder else "resource"
            raise ChaoxingAPIError(f"{kind} not found: {query}")
        return resolve_resource_item(
            self._resource_tree_from_context(context, course, clazz),
            normalized,
            require_folder=require_folder,
        )

    def _resolve_resource_parent(
        self,
        context: dict[str, Any],
        course: dict[str, Any],
        clazz: dict[str, Any],
        query: str,
    ) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if normalized in {"", "0", "root", "根目录", "资料根目录"}:
            return {
                "data_id": "0",
                "name": "根目录",
                "path": "根目录",
                "depth": 0,
                "is_folder": True,
            }
        return self._resolve_resource_from_context(
            context,
            course,
            clazz,
            query,
            require_folder=True,
        )

    def list_resources(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        folder: str = "",
        search: str = "",
    ) -> dict[str, Any]:
        session = self._session()
        context = self._resource_context(session, course, clazz)
        parent = self._resolve_resource_parent(context, course, clazz, folder)
        items = self._resource_folder_items(
            context,
            course,
            clazz,
            folder_id=str(parent["data_id"]),
            folder_name=str(parent["name"]),
        )
        parent_path = "" if str(parent["data_id"]) == "0" else str(parent.get("path") or "")
        for item in items:
            item["path"] = f"{parent_path}/{item['name']}".lstrip("/")
            item["depth"] = int(parent.get("depth") or 0) + 1
        if search:
            normalized_search = search.strip().lower()
            items = [item for item in items if normalized_search in str(item["name"]).lower()]
        for index, item in enumerate(items, 1):
            item["index"] = index
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "folder_id": str(parent["data_id"]),
            "folder_name": str(parent["name"]),
            "folder_path": str(parent.get("path") or "根目录"),
            "search": search,
            "count": len(items),
            "folder_count": sum(1 for item in items if item["is_folder"]),
            "file_count": sum(1 for item in items if not item["is_folder"]),
            "items": items,
            "verification": f"parsed {len(items)} course resources through HTTP",
        }

    def list_resource_tree(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        search: str = "",
    ) -> dict[str, Any]:
        session = self._session()
        context = self._resource_context(session, course, clazz)
        items = self._resource_tree_from_context(context, course, clazz)
        if search:
            normalized = search.strip().lower()
            items = [
                item
                for item in items
                if normalized in str(item.get("name") or "").lower()
                or normalized in str(item.get("path") or "").lower()
            ]
            for index, item in enumerate(items, 1):
                item["index"] = index
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "search": search,
            "count": len(items),
            "folder_count": sum(1 for item in items if item["is_folder"]),
            "file_count": sum(1 for item in items if not item["is_folder"]),
            "max_depth": max((int(item["depth"]) for item in items), default=0),
            "items": items,
            "verification": f"parsed the complete {len(items)}-node resource tree through HTTP",
        }

    def _course_cloud_source_page(
        self,
        context: dict[str, Any],
        *,
        path: str = "",
        search: str = "",
        page: int = 1,
        page_size: int = 1000,
        share_id: str = "0",
    ) -> dict[str, Any]:
        if page < 1 or page_size < 1 or page_size > 1000:
            raise ChaoxingAPIError("page must be positive and page_size must be 1-1000")
        try:
            response = context["session"].get(
                f"{MOOC2_BASE_URL}/mooc2-ans/coursedata/file-list",
                params={
                    "f": "all_type",
                    "d": str(path or ""),
                    "page": str(page),
                    "size": str(page_size),
                    "kw": str(search or ""),
                    "shareId": str(share_id or "0"),
                },
                timeout=self.timeout,
                headers={"Referer": context["root_url"]},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"course cloud-source list failed: {exc}") from exc
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("course cloud-source list returned invalid JSON") from exc
        if not isinstance(payload, list):
            raise ChaoxingAPIError("course cloud-source list returned an unexpected response")
        parent_path = ""
        items: list[dict[str, Any]] = []
        for raw in payload:
            if not isinstance(raw, dict):
                continue
            item_type = str(raw.get("xtype") or "").lower()
            if item_type == "back":
                parent_path = str(raw.get("path") or "")
                continue
            resource_id = str(raw.get("resid") or raw.get("id") or "")
            item_path = str(raw.get("path") or "")
            if not resource_id and item_path:
                resource_id = item_path.rstrip("/").split("/")[-1]
            if not resource_id:
                continue
            is_folder = item_type == "dir"
            items.append(
                {
                    "index": len(items) + 1,
                    "resource_id": resource_id,
                    "name": str(raw.get("name") or ""),
                    "title": str(raw.get("name") or ""),
                    "path": item_path,
                    "is_file": item_type == "file",
                    "is_folder": is_folder,
                    "suffix": str(raw.get("suffix") or ""),
                    "byte_count": int(raw.get("size") or 0),
                    "object_id": str(raw.get("objectid") or raw.get("objectId") or ""),
                    "upload_time": raw.get("uploadDate"),
                    "catalog_id": raw.get("cataId"),
                    "file_path": str(raw.get("filepath") or ""),
                    "extra_info": raw.get("extinfo"),
                    "share_id": str(raw.get("shareId") or share_id or "0"),
                }
            )
        return {
            "path": str(path or ""),
            "parent_path": parent_path,
            "search": str(search or ""),
            "page": page,
            "page_size": page_size,
            "share_id": str(share_id or "0"),
            "count": len(items),
            "items": items,
        }

    def list_course_cloud_sources(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        path: str = "",
        search: str = "",
        page: int = 1,
        page_size: int = 1000,
        share_id: str = "0",
    ) -> dict[str, Any]:
        session = self._session()
        context = self._resource_context(session, course, clazz)
        listing = self._course_cloud_source_page(
            context,
            path=path,
            search=search,
            page=page,
            page_size=page_size,
            share_id=share_id,
        )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            **listing,
            "verification": (
                f"read {listing['count']} cloud-source items from the course HTTP interface"
            ),
        }

    def _resource_labels_from_context(
        self,
        context: dict[str, Any],
        course: dict[str, Any],
        selected: dict[str, Any],
        *,
        search: str = "",
    ) -> list[dict[str, Any]]:
        try:
            response = context["session"].get(
                f"{MOOC2_BASE_URL}/mooc2-ans/coursedata/getCourseDataLabelList",
                params={
                    "courseId": course["course_id"],
                    "dataId": selected["data_id"],
                    "query": str(search or ""),
                },
                timeout=self.timeout,
                headers={"Referer": context["root_url"]},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"resource label list failed: {exc}") from exc
        return parse_resource_labels(self._decode(response))

    @staticmethod
    def _resolve_resource_label(
        labels: list[dict[str, Any]],
        query: str,
    ) -> dict[str, Any]:
        return _resolve_titled_item(labels, query, id_key="label_id", label="resource label")

    @staticmethod
    def _validate_resource_label_name(name: str) -> str:
        normalized = str(name or "").strip()
        if not normalized or len(normalized) > 50:
            raise ChaoxingAPIError("resource label name must contain 1-50 characters")
        if re.search(r"[<>\x00-\x1f]", normalized):
            raise ChaoxingAPIError("resource label name contains an unsupported character")
        return normalized

    def list_resource_labels(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        resource: str,
        *,
        search: str = "",
    ) -> dict[str, Any]:
        session = self._session()
        context = self._resource_context(session, course, clazz)
        selected = self._resolve_resource_from_context(context, course, clazz, resource)
        labels = self._resource_labels_from_context(
            context,
            course,
            selected,
            search=search,
        )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "resource": selected,
            "search": search,
            "count": len(labels),
            "assigned_count": sum(1 for label in labels if label["assigned"]),
            "labels": labels,
            "verification": f"parsed {len(labels)} resource labels through HTTP",
        }

    def create_resource_label(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        resource: str,
        name: str,
    ) -> dict[str, Any]:
        normalized_name = self._validate_resource_label_name(name)
        session = self._session()
        context = self._resource_context(session, course, clazz)
        selected = self._resolve_resource_from_context(context, course, clazz, resource)
        try:
            response = session.get(
                f"{MOOC2_BASE_URL}/mooc2-ans/questionBankTopic/addtopiclable",
                params={
                    "cpi": course["cpi"],
                    "courseId": course["course_id"],
                    "name": normalized_name,
                },
                timeout=self.timeout,
                headers={"Referer": context["root_url"]},
            )
            response.raise_for_status()
            payload = self._resource_json(response, "resource label creation")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"resource label creation failed: {exc}") from exc
        if not payload.get("status"):
            raise ChaoxingAPIError(
                str(payload.get("msg") or "Chaoxing rejected resource label creation")
            )
        label_id = str(payload.get("saveTopiclabelId") or "")
        labels = self._resource_labels_from_context(context, course, selected)
        created = next(
            (
                label
                for label in labels
                if str(label["label_id"]) == label_id and label["name"] == normalized_name
            ),
            None,
        )
        if created is None:
            raise ChaoxingAPIError(
                "server accepted resource label creation, but the new label was not found"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "resource": selected,
            "label": created,
            "verification": f"created resource label {label_id} and found it after refresh",
        }

    def rename_resource_label(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        resource: str,
        label: str,
        name: str,
    ) -> dict[str, Any]:
        normalized_name = self._validate_resource_label_name(name)
        session = self._session()
        context = self._resource_context(session, course, clazz)
        selected = self._resolve_resource_from_context(context, course, clazz, resource)
        labels = self._resource_labels_from_context(context, course, selected)
        current = self._resolve_resource_label(labels, label)
        if not current["editable"]:
            raise ChaoxingAPIError("the selected resource label is not editable")
        try:
            response = session.get(
                f"{MOOC2_BASE_URL}/mooc2-ans/questionBankTopic/updatetopiclabel",
                params={
                    "cpi": course["cpi"],
                    "courseId": course["course_id"],
                    "name": normalized_name,
                    "topicLabelId": current["label_id"],
                },
                timeout=self.timeout,
                headers={"Referer": context["root_url"]},
            )
            response.raise_for_status()
            payload = self._resource_json(response, "resource label rename")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"resource label rename failed: {exc}") from exc
        if not payload.get("status"):
            raise ChaoxingAPIError(str(payload.get("msg") or "Chaoxing rejected label rename"))
        refreshed = self._resource_labels_from_context(context, course, selected)
        updated = self._resolve_resource_label(refreshed, str(current["label_id"]))
        if updated["name"] != normalized_name:
            raise ChaoxingAPIError("server accepted label rename, but the refreshed name differs")
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "resource": selected,
            "before": current,
            "label": updated,
            "verification": f"renamed resource label {updated['label_id']} and re-read its name",
        }

    def delete_resource_label(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        resource: str,
        label: str,
    ) -> dict[str, Any]:
        session = self._session()
        context = self._resource_context(session, course, clazz)
        selected = self._resolve_resource_from_context(context, course, clazz, resource)
        labels = self._resource_labels_from_context(context, course, selected)
        current = self._resolve_resource_label(labels, label)
        if not current["deletable"]:
            raise ChaoxingAPIError("the selected resource label is not deletable")
        try:
            response = session.get(
                f"{MOOC2_BASE_URL}/mooc2-ans/questionBankTopic/deletetopiclabel",
                params={
                    "cpi": course["cpi"],
                    "courseId": course["course_id"],
                    "topicLabelId": current["label_id"],
                },
                timeout=self.timeout,
                headers={"Referer": context["root_url"]},
            )
            response.raise_for_status()
            payload = self._resource_json(response, "resource label deletion")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"resource label deletion failed: {exc}") from exc
        if not payload.get("status"):
            raise ChaoxingAPIError(str(payload.get("msg") or "Chaoxing rejected label deletion"))
        refreshed = self._resource_labels_from_context(context, course, selected)
        if any(str(item["label_id"]) == str(current["label_id"]) for item in refreshed):
            raise ChaoxingAPIError("server accepted label deletion, but the label remains")
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "resource": selected,
            "label": current,
            "verification": f"deleted resource label {current['label_id']} and confirmed absence",
        }

    def update_resource_labels(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        resources: list[str],
        labels: list[str],
    ) -> dict[str, Any]:
        if not resources:
            raise ChaoxingAPIError("at least one resource is required")
        if len(resources) > 100:
            raise ChaoxingAPIError("no more than 100 resources may be labeled at once")
        session = self._session()
        context = self._resource_context(session, course, clazz)
        tree = self._resource_tree_from_context(context, course, clazz)
        selected_resources: list[dict[str, Any]] = []
        for query in resources:
            item = resolve_resource_item(tree, query)
            if all(
                str(existing["data_id"]) != str(item["data_id"]) for existing in selected_resources
            ):
                selected_resources.append(item)
        catalog = self._resource_labels_from_context(context, course, selected_resources[0])
        selected_labels: list[dict[str, Any]] = []
        for query in labels:
            item = self._resolve_resource_label(catalog, query)
            if all(
                str(existing["label_id"]) != str(item["label_id"]) for existing in selected_labels
            ):
                selected_labels.append(item)
        data_ids = ",".join(str(item["data_id"]) for item in selected_resources)
        label_ids = ",".join(str(item["label_id"]) for item in selected_labels)
        if label_ids:
            label_ids += ","
        try:
            response = session.post(
                f"{MOOC2_BASE_URL}/mooc2-ans/coursedata/saveCourseDataLabelRelation",
                data={
                    "courseid": course["course_id"],
                    "cpi": course["cpi"],
                    "dataIds": data_ids,
                    "labelIds": label_ids,
                },
                timeout=self.timeout,
                headers={"Referer": context["root_url"]},
            )
            response.raise_for_status()
            payload = self._resource_json(response, "resource label relation update")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"resource label relation update failed: {exc}") from exc
        if not payload.get("status"):
            raise ChaoxingAPIError(
                str(payload.get("msg") or "Chaoxing rejected resource label update")
            )
        expected_ids = {str(item["label_id"]) for item in selected_labels}
        verified: list[dict[str, Any]] = []
        for resource_item in selected_resources:
            refreshed = self._resource_labels_from_context(context, course, resource_item)
            assigned_ids = {str(item["label_id"]) for item in refreshed if bool(item["assigned"])}
            if assigned_ids != expected_ids:
                raise ChaoxingAPIError(
                    f"resource {resource_item['data_id']} refreshed with different label IDs"
                )
            verified.append(
                {
                    "resource": resource_item,
                    "assigned_label_ids": sorted(assigned_ids),
                }
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "resources": selected_resources,
            "labels": selected_labels,
            "verified": verified,
            "verification": (
                f"replaced labels on {len(selected_resources)} resources and re-read every relation"
            ),
        }

    @staticmethod
    def _human_file_size(byte_count: int) -> str:
        value = float(max(0, byte_count))
        units = ("B", "KB", "MB", "GB", "TB")
        unit = units[0]
        for unit in units:
            if value < 1024 or unit == units[-1]:
                break
            value /= 1024
        return f"{value:.2f}".rstrip("0").rstrip(".") + f" {unit}"

    def import_cloud_files_to_resources(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        resources: list[str],
        *,
        source_path: str = "",
        destination: str = "",
        share_id: str = "0",
    ) -> dict[str, Any]:
        if not resources:
            raise ChaoxingAPIError("at least one cloud source is required")
        if len(resources) > 50:
            raise ChaoxingAPIError("no more than 50 cloud sources may be imported at once")
        session = self._session()
        context = self._resource_context(session, course, clazz)
        destination_folder = self._resolve_resource_parent(
            context,
            course,
            clazz,
            destination,
        )
        source_listing = self._course_cloud_source_page(
            context,
            path=source_path,
            page_size=1000,
            share_id=share_id,
        )["items"]
        cloud_context: dict[str, Any] | None = None
        selected: list[dict[str, Any]] = []
        for query in resources:
            normalized = str(query or "").strip()
            exact = [
                item
                for item in source_listing
                if normalized
                in {
                    str(item["resource_id"]),
                    str(item["path"]),
                    str(item["name"]),
                }
            ]
            partial = [
                item for item in source_listing if normalized.lower() in str(item["name"]).lower()
            ]
            matches = exact or partial
            if len(matches) == 1:
                item = matches[0]
            elif len(matches) > 1:
                choices = ", ".join(
                    f"{candidate['name']} ({candidate['resource_id']})"
                    for candidate in matches[:20]
                )
                raise ChaoxingAPIError(f"multiple cloud sources match: {choices}")
            else:
                if cloud_context is None:
                    cloud_context = self._cloud_disk_context(session)
                active = self._resolve_active_cloud_disk_item(cloud_context, normalized)
                item = {
                    "resource_id": active["resource_id"],
                    "name": active["name"],
                    "title": active["name"],
                    "path": "",
                    "is_file": active["is_file"],
                    "is_folder": active["is_folder"],
                    "suffix": active["suffix"],
                    "byte_count": active["byte_count"],
                    "object_id": active["object_id"],
                    "upload_time": active["upload_time"],
                    "catalog_id": None,
                    "file_path": "",
                    "extra_info": None,
                    "share_id": "0",
                }
            if not item["is_file"]:
                raise ChaoxingAPIError(
                    f"cloud source {item['name']} is a folder; use the cloud-folder import action"
                )
            if all(
                str(existing["resource_id"]) != str(item["resource_id"]) for existing in selected
            ):
                selected.append(item)
        records: list[dict[str, Any]] = []
        for item in selected:
            catalog_id = item.get("catalog_id")
            if catalog_id not in (None, ""):
                if str(catalog_id) == "1":
                    records.append(
                        {
                            "cataId": catalog_id,
                            "name": item["name"],
                            "filepath": item["file_path"],
                        }
                    )
                else:
                    records.append(
                        {
                            "cataId": catalog_id,
                            "extinfo": item.get("extra_info"),
                        }
                    )
                continue
            if not item.get("object_id"):
                raise ChaoxingAPIError(f"cloud source {item['name']} exposed no object ID")
            byte_count = int(item.get("byte_count") or 0)
            suffix = str(item.get("suffix") or "").lstrip(".")
            records.append(
                {
                    "objectid": item["object_id"],
                    "name": item["name"],
                    "size": byte_count,
                    "hsize": self._human_file_size(byte_count),
                    "type": "." + suffix if suffix else "",
                }
            )
        before = self._resource_folder_items(
            context,
            course,
            clazz,
            folder_id=str(destination_folder["data_id"]),
            folder_name=str(destination_folder["name"]),
        )
        before_ids = {str(item["data_id"]) for item in before}
        try:
            response = session.post(
                f"{MOOC2_BASE_URL}/mooc2-ans/coursedata/addYunPan",
                data={
                    "courseId": course["course_id"],
                    "dataId": destination_folder["data_id"],
                    "f": json.dumps(records, ensure_ascii=False, separators=(",", ":")),
                    "cpi": course["cpi"],
                    "microTopicId": context["hidden"].get("microTopicId", "0"),
                },
                timeout=self.timeout,
                headers={"Referer": context["root_url"]},
            )
            response.raise_for_status()
            payload = self._resource_json(response, "cloud-file import")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"cloud-file import failed: {exc}") from exc
        if not payload.get("result"):
            raise ChaoxingAPIError(str(payload.get("msg") or "Chaoxing rejected cloud-file import"))
        if payload.get("exist"):
            raise ChaoxingAPIError(
                str(payload.get("msg") or "one or more cloud files already exist in the folder")
            )
        refreshed = self._resource_folder_items(
            context,
            course,
            clazz,
            folder_id=str(destination_folder["data_id"]),
            folder_name=str(destination_folder["name"]),
        )
        imported = [item for item in refreshed if str(item["data_id"]) not in before_ids]
        selected_names = sorted(str(item["name"]) for item in selected)
        imported_names = sorted(str(item["name"]) for item in imported)
        if len(imported) != len(selected) or imported_names != selected_names:
            raise ChaoxingAPIError(
                "server accepted cloud-file import, but refreshed resource names or count differ"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "source_path": source_path,
            "destination": destination_folder,
            "sources": selected,
            "resources": imported,
            "verification": (
                f"imported {len(imported)} cloud files and found every new course resource ID"
            ),
        }

    def import_cloud_folder_to_resources(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        resource: str,
        *,
        source_path: str = "",
        destination: str = "",
        share_id: str = "0",
    ) -> dict[str, Any]:
        session = self._session()
        context = self._resource_context(session, course, clazz)
        destination_folder = self._resolve_resource_parent(
            context,
            course,
            clazz,
            destination,
        )
        source_listing = self._course_cloud_source_page(
            context,
            path=source_path,
            page_size=1000,
            share_id=share_id,
        )["items"]
        normalized = str(resource or "").strip()
        exact = [
            item
            for item in source_listing
            if normalized
            in {
                str(item["resource_id"]),
                str(item["path"]),
                str(item["name"]),
            }
            and item["is_folder"]
        ]
        partial = [
            item
            for item in source_listing
            if item["is_folder"] and normalized.lower() in str(item["name"]).lower()
        ]
        matches = exact or partial
        cloud_context: dict[str, Any] | None = None
        if len(matches) == 1:
            source_folder = matches[0]
        elif len(matches) > 1:
            choices = ", ".join(
                f"{candidate['name']} ({candidate['resource_id']})" for candidate in matches[:20]
            )
            raise ChaoxingAPIError(f"multiple cloud folders match: {choices}")
        else:
            cloud_context = self._cloud_disk_context(session)
            active = self._resolve_cloud_disk_folder(cloud_context, normalized)
            source_folder = {
                "resource_id": active["resource_id"],
                "name": active["name"],
                "title": active["name"],
                "path": "",
                "is_file": False,
                "is_folder": True,
                "suffix": "",
                "byte_count": 0,
                "object_id": "",
                "upload_time": active.get("upload_time"),
                "catalog_id": None,
                "file_path": "",
                "extra_info": None,
                "share_id": "0",
            }
        if source_folder.get("path"):
            source_children = self._course_cloud_source_page(
                context,
                path=str(source_folder["path"]),
                page_size=1000,
                share_id=str(source_folder.get("share_id") or share_id or "0"),
            )["items"]
        else:
            if cloud_context is None:
                cloud_context = self._cloud_disk_context(session)
            source_children = self._cloud_disk_listing(
                cloud_context,
                parent_id=str(source_folder["resource_id"]),
                page_size=1000,
            )["items"]
        before = self._resource_folder_items(
            context,
            course,
            clazz,
            folder_id=str(destination_folder["data_id"]),
            folder_name=str(destination_folder["name"]),
        )
        before_ids = {str(item["data_id"]) for item in before}
        try:
            response = session.post(
                f"{MOOC2_BASE_URL}/mooc2-ans/coursedata/addYunPanFolder",
                data={
                    "courseId": course["course_id"],
                    "yunPanFolderId": source_folder["resource_id"],
                    "rootId": destination_folder["data_id"],
                    "folderName": source_folder["name"],
                    "cpi": course["cpi"],
                    "microTopicId": context["hidden"].get("microTopicId", "0"),
                },
                timeout=self.timeout,
                headers={"Referer": context["root_url"]},
            )
            response.raise_for_status()
            payload = self._resource_json(response, "cloud-folder import")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"cloud-folder import failed: {exc}") from exc
        if not payload.get("result"):
            raise ChaoxingAPIError(
                str(payload.get("msg") or "Chaoxing rejected cloud-folder import")
            )
        if payload.get("exist"):
            raise ChaoxingAPIError(
                str(payload.get("msg") or "the cloud folder already exists in the destination")
            )
        refreshed = self._resource_folder_items(
            context,
            course,
            clazz,
            folder_id=str(destination_folder["data_id"]),
            folder_name=str(destination_folder["name"]),
        )
        imported = [
            item
            for item in refreshed
            if str(item["data_id"]) not in before_ids
            and item["is_folder"]
            and str(item["name"]) == str(source_folder["name"])
        ]
        if len(imported) != 1:
            raise ChaoxingAPIError(
                "server accepted cloud-folder import, but exactly one new matching folder "
                "was not found"
            )
        imported_children = self._resource_folder_items(
            context,
            course,
            clazz,
            folder_id=str(imported[0]["data_id"]),
            folder_name=str(imported[0]["name"]),
        )
        source_names = sorted(str(item["name"]) for item in source_children)
        imported_names = sorted(str(item["name"]) for item in imported_children)
        if source_names != imported_names:
            raise ChaoxingAPIError(
                "server created the imported cloud folder, but its direct-child names differ"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "source": source_folder,
            "source_path": source_path,
            "destination": destination_folder,
            "folder": imported[0],
            "direct_child_count": len(imported_children),
            "verification": (
                f"imported cloud folder {source_folder['resource_id']} as course folder "
                f"{imported[0]['data_id']} and matched {len(imported_children)} direct children"
            ),
        }

    def create_resource_folder(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        name: str,
        *,
        parent: str = "",
    ) -> dict[str, Any]:
        normalized_name = self._validate_resource_name(name, label="folder name")
        session = self._session()
        context = self._resource_context(session, course, clazz)
        destination = self._resolve_resource_parent(context, course, clazz, parent)
        before = self._resource_folder_items(
            context,
            course,
            clazz,
            folder_id=str(destination["data_id"]),
            folder_name=str(destination["name"]),
        )
        before_ids = {str(item["data_id"]) for item in before}
        endpoint = f"{MOOC2_BASE_URL}/mooc2-ans/coursedata/add-folder"
        try:
            response = session.post(
                endpoint,
                data={
                    "dataName": normalized_name,
                    "courseId": course["course_id"],
                    "classId": clazz["clazz_id"],
                    "courseName": course["course_name"],
                    "rootId": destination["data_id"],
                    "dataType": "afolder",
                    "source": context["hidden"].get("source", "1"),
                    "parent": "",
                    "cpi": course["cpi"],
                    "isOpen": context["hidden"].get("isOpen", "0"),
                    "shared": "false",
                    "classIds": "",
                    "personIds": "",
                    "openTeacherTeamAll": "true",
                    "deletePersonIds": "",
                },
                timeout=self.timeout,
                headers={"Referer": context["root_url"]},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"resource folder creation failed: {exc}") from exc
        response_text = self._decode(response).strip().strip('"')
        if response_text == "-1":
            raise ChaoxingAPIError(
                "Chaoxing rejected the folder because the depth limit was reached"
            )
        refreshed = self._resource_folder_items(
            context,
            course,
            clazz,
            folder_id=str(destination["data_id"]),
            folder_name=str(destination["name"]),
        )
        created = [
            item
            for item in refreshed
            if str(item["data_id"]) not in before_ids
            and item["is_folder"]
            and str(item["name"]) == normalized_name
        ]
        if len(created) != 1:
            raise ChaoxingAPIError(
                "server accepted folder creation, but exactly one new matching folder was not found"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "parent": destination,
            "folder": created[0],
            "verification": f"created folder {created[0]['data_id']} and found it after refresh",
        }

    def rename_resource(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        resource: str,
        name: str,
    ) -> dict[str, Any]:
        normalized_name = self._validate_resource_name(name)
        session = self._session()
        context = self._resource_context(session, course, clazz)
        tree = self._resource_tree_from_context(context, course, clazz)
        selected = resolve_resource_item(tree, resource)
        try:
            response = session.post(
                f"{MOOC2_BASE_URL}/mooc2-ans/coursedata/update",
                data={
                    "courseId": course["course_id"],
                    "rootId": selected["parent_id"],
                    "dataId": selected["data_id"],
                    "dataName": normalized_name,
                    "cpi": course["cpi"],
                },
                timeout=self.timeout,
                headers={"Referer": context["root_url"]},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"resource rename failed: {exc}") from exc
        if self._decode(response).strip().strip('"').lower() == "rename":
            raise ChaoxingAPIError("a sibling resource already uses that name")
        refreshed = self._resource_tree_from_context(context, course, clazz)
        renamed = resolve_resource_item(refreshed, str(selected["data_id"]))
        if renamed["name"] != normalized_name:
            raise ChaoxingAPIError("server accepted the rename, but the refreshed name differs")
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "before": selected,
            "resource": renamed,
            "verification": f"renamed resource {renamed['data_id']} and confirmed the new name",
        }

    def move_resources(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        resources: list[str],
        *,
        destination: str = "",
    ) -> dict[str, Any]:
        if not resources:
            raise ChaoxingAPIError("at least one resource is required")
        session = self._session()
        context = self._resource_context(session, course, clazz)
        tree = self._resource_tree_from_context(context, course, clazz)
        selected: list[dict[str, Any]] = []
        for query in resources:
            item = resolve_resource_item(tree, query)
            if all(str(existing["data_id"]) != str(item["data_id"]) for existing in selected):
                selected.append(item)
        target = self._resolve_resource_parent(context, course, clazz, destination)
        selected_ids = {str(item["data_id"]) for item in selected}
        if str(target["data_id"]) in selected_ids:
            raise ChaoxingAPIError("a resource folder cannot be moved into itself")
        for item in selected:
            if item["is_folder"] and str(target.get("path") or "").startswith(
                str(item.get("path") or "") + "/"
            ):
                raise ChaoxingAPIError("a resource folder cannot be moved into its descendant")
        encoded_ids = "".join(f"{item['data_id']}--" for item in selected)
        try:
            response = session.post(
                f"{MOOC2_BASE_URL}/mooc2-ans/coursedata/move",
                data={
                    "dataId": encoded_ids,
                    "folderId": target["data_id"],
                    "courseid": course["course_id"],
                    "cpi": course["cpi"],
                },
                timeout=self.timeout,
                headers={"Referer": context["root_url"]},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"resource move failed: {exc}") from exc
        refreshed = self._resource_tree_from_context(context, course, clazz)
        moved = [resolve_resource_item(refreshed, item_id) for item_id in selected_ids]
        if any(str(item["parent_id"]) != str(target["data_id"]) for item in moved):
            raise ChaoxingAPIError(
                "server accepted the move, but one or more resources have a different parent"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "destination": target,
            "moved": moved,
            "verification": f"moved {len(moved)} resources and confirmed every parent ID",
        }

    def reorder_resources(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        ordered_resources: list[str],
        *,
        folder: str = "",
    ) -> dict[str, Any]:
        session = self._session()
        context = self._resource_context(session, course, clazz)
        parent = self._resolve_resource_parent(context, course, clazz, folder)
        siblings = self._resource_folder_items(
            context,
            course,
            clazz,
            folder_id=str(parent["data_id"]),
            folder_name=str(parent["name"]),
        )
        ordered = [resolve_resource_item(siblings, query) for query in ordered_resources]
        ordered_ids = [str(item["data_id"]) for item in ordered]
        sibling_ids = [str(item["data_id"]) for item in siblings]
        if len(set(ordered_ids)) != len(ordered_ids):
            raise ChaoxingAPIError("ordered_resources contains the same resource more than once")
        if set(ordered_ids) != set(sibling_ids):
            raise ChaoxingAPIError(
                "ordered_resources must contain every direct child of the folder exactly once"
            )
        try:
            response = session.get(
                f"{MOOC2_BASE_URL}/mooc2-ans/coursedata/sort",
                params={
                    "dataId": ",".join(ordered_ids),
                    "cpi": course["cpi"],
                    "courseid": course["course_id"],
                },
                timeout=self.timeout,
                headers={"Referer": context["root_url"]},
            )
            response.raise_for_status()
            payload = self._resource_json(response, "resource reorder")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"resource reorder failed: {exc}") from exc
        if payload.get("result") is not True:
            raise ChaoxingAPIError(
                str(payload.get("msg") or "Chaoxing rejected the resource order")
            )
        refreshed = self._resource_folder_items(
            context,
            course,
            clazz,
            folder_id=str(parent["data_id"]),
            folder_name=str(parent["name"]),
        )
        refreshed_ids = [str(item["data_id"]) for item in refreshed]
        if refreshed_ids != ordered_ids:
            raise ChaoxingAPIError("resource order response was successful, but refresh differs")
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "folder": parent,
            "items": refreshed,
            "verification": f"saved and re-read the order of {len(refreshed)} resources",
        }

    def set_resource_top_status(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        resource: str,
        *,
        top: bool,
    ) -> dict[str, Any]:
        session = self._session()
        context = self._resource_context(session, course, clazz)
        selected = self._resolve_resource_from_context(context, course, clazz, resource)
        parent_id = str(selected.get("parent_id") or selected.get("root_id") or "0")
        parent_name = str(selected.get("parent_name") or "")
        endpoint = (
            f"{MOOC2_BASE_URL}/mooc2-ans/coursedata/set-top"
            if top
            else f"{MOOC2_BASE_URL}/mooc2-ans/coursedata/cancel-set-top"
        )
        data = (
            {
                "courseId": course["course_id"],
                "dataId": selected["data_id"],
                "type": selected["data_type"],
                "rootId": parent_id,
                "cpi": course["cpi"],
            }
            if top
            else {
                "dataId": selected["data_id"],
                "courseid": course["course_id"],
                "cpi": course["cpi"],
            }
        )
        try:
            response = session.post(
                endpoint,
                data=data,
                timeout=self.timeout,
                headers={"Referer": context["root_url"]},
            )
            response.raise_for_status()
            payload = self._resource_json(response, "resource top-status update")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"resource top-status update failed: {exc}") from exc
        if not payload.get("status"):
            raise ChaoxingAPIError(
                str(payload.get("msg") or "Chaoxing rejected the resource top status")
            )
        siblings = self._resource_folder_items(
            context,
            course,
            clazz,
            folder_id=parent_id,
            folder_name=parent_name,
        )
        updated = resolve_resource_item(siblings, str(selected["data_id"]))
        if bool(updated["is_top"]) is not top:
            raise ChaoxingAPIError(
                "server accepted the resource top status, but the refreshed state differs"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "before": selected,
            "resource": updated,
            "top": top,
            "verification": f"set top={top} and confirmed it in the affected resource folder",
        }

    def copy_resource(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        resource: str,
    ) -> dict[str, Any]:
        session = self._session()
        context = self._resource_context(session, course, clazz)
        selected = self._resolve_resource_from_context(context, course, clazz, resource)
        parent_id = str(selected.get("parent_id") or "0")
        parent_name = str(selected.get("parent_name") or "")
        before = self._resource_folder_items(
            context,
            course,
            clazz,
            folder_id=parent_id,
            folder_name=parent_name,
        )
        before_ids = {str(item["data_id"]) for item in before}
        try:
            response = session.get(
                f"{MOOC2_BASE_URL}/mooc2-ans/coursedata/copyCourseDataByResId",
                params={
                    "dataId": selected["data_id"],
                    "cpi": course["cpi"],
                    "courseId": course["course_id"],
                },
                timeout=self.timeout,
                headers={"Referer": context["root_url"]},
            )
            response.raise_for_status()
            payload = self._resource_json(response, "resource copy")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"resource copy failed: {exc}") from exc
        if not payload.get("status"):
            raise ChaoxingAPIError(str(payload.get("msg") or "Chaoxing rejected the resource copy"))
        refreshed = self._resource_folder_items(
            context,
            course,
            clazz,
            folder_id=parent_id,
            folder_name=parent_name,
        )
        copied = [item for item in refreshed if str(item["data_id"]) not in before_ids]
        if len(copied) != 1:
            raise ChaoxingAPIError(
                "server accepted the resource copy, but exactly one new sibling was not found"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "source": selected,
            "resource": copied[0],
            "verification": (
                f"copied resource {selected['data_id']} and found new sibling "
                f"{copied[0]['data_id']} after refresh"
            ),
        }

    def copy_resource_to_cloud_disk(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        resource: str,
        *,
        destination: str = "",
    ) -> dict[str, Any]:
        session = self._session()
        context = self._resource_context(session, course, clazz)
        selected = self._resolve_resource_from_context(
            context,
            course,
            clazz,
            resource,
            require_folder=False,
        )
        if not selected.get("object_id"):
            raise ChaoxingAPIError(
                "only course files with a cloud object ID can be copied to the personal cloud disk"
            )
        cloud_context = self._cloud_disk_context(session)
        cloud_destination = self._resolve_cloud_disk_folder(cloud_context, destination)
        before = self._cloud_disk_listing(
            cloud_context,
            parent_id=str(cloud_destination["resource_id"]),
            page_size=1000,
        )["items"]
        before_ids = {str(item["resource_id"]) for item in before}
        try:
            response = session.post(
                f"{MOOC2_BASE_URL}/mooc2-ans/coursedata/copy-to-cloud-disk",
                data={
                    "name": selected["name"],
                    "objectid": selected["object_id"],
                    "dataId": selected["data_id"],
                    "dataType": selected["data_type"],
                    "fldid": cloud_destination["resource_id"],
                    "courseid": course["course_id"],
                    "cpi": course["cpi"],
                    "ut": "t",
                },
                timeout=self.timeout,
                headers={"Referer": context["root_url"]},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"resource copy to cloud disk failed: {exc}") from exc
        if self._decode(response).strip().strip('"').lower() != "true":
            raise ChaoxingAPIError(
                "Chaoxing rejected copying the course resource to the personal cloud disk"
            )
        refreshed = self._cloud_disk_listing(
            cloud_context,
            parent_id=str(cloud_destination["resource_id"]),
            page_size=1000,
        )["items"]
        created = [item for item in refreshed if str(item["resource_id"]) not in before_ids]
        matching = [
            item
            for item in created
            if str(item.get("object_id") or "") == str(selected["object_id"])
            or str(item.get("name") or "") == str(selected["name"])
        ]
        if len(matching) != 1:
            raise ChaoxingAPIError(
                "server accepted the cloud-disk copy, but exactly one new matching item "
                "was not found"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "source": selected,
            "destination": self._public_cloud_disk_item(cloud_destination),
            "cloud_item": self._public_cloud_disk_item(matching[0]),
            "verification": (
                f"copied course resource {selected['data_id']} to cloud item "
                f"{matching[0]['resource_id']} and found it after refresh"
            ),
        }

    def delete_resources(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        resources: list[str],
    ) -> dict[str, Any]:
        if not resources:
            raise ChaoxingAPIError("at least one resource is required")
        if len(resources) > 100:
            raise ChaoxingAPIError("no more than 100 resources may be deleted at once")
        session = self._session()
        context = self._resource_context(session, course, clazz)
        selected: list[dict[str, Any]] = []
        normalized_queries = [str(query or "").strip() for query in resources]
        direct_queries = all(
            query.isdigit() or "/" in query.replace("\\", "/") for query in normalized_queries
        )
        tree = None
        if not direct_queries:
            tree = self._resource_tree_from_context(context, course, clazz)
        for query in normalized_queries:
            item = (
                self._resolve_resource_from_context(context, course, clazz, query)
                if tree is None
                else resolve_resource_item(tree, query)
            )
            if all(str(existing["data_id"]) != str(item["data_id"]) for existing in selected):
                selected.append(item)
        selected_ids = [str(item["data_id"]) for item in selected]
        try:
            response = session.post(
                f"{MOOC2_BASE_URL}/mooc2-ans/coursedata/batchDelete",
                params={"dataId": ",".join(selected_ids), "courseId": course["course_id"]},
                timeout=self.timeout,
                headers={"Referer": context["root_url"]},
            )
            response.raise_for_status()
            payload = self._resource_json(response, "resource deletion")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"resource deletion failed: {exc}") from exc
        if payload.get("status") is False:
            raise ChaoxingAPIError(str(payload.get("msg") or "Chaoxing rejected resource deletion"))
        effective_selected = [
            item
            for item in selected
            if not any(
                other["is_folder"]
                and str(other["data_id"]) != str(item["data_id"])
                and str(item.get("path") or "").startswith(str(other.get("path") or "") + "/")
                for other in selected
            )
        ]
        refreshed_by_parent: dict[str, list[dict[str, Any]]] = {}
        for item in effective_selected:
            parent_id = str(item.get("parent_id") or "0")
            if parent_id not in refreshed_by_parent:
                refreshed_by_parent[parent_id] = self._resource_folder_items(
                    context,
                    course,
                    clazz,
                    folder_id=parent_id,
                    folder_name=str(item.get("parent_name") or ""),
                )
        remaining_ids = {
            str(item["data_id"]) for siblings in refreshed_by_parent.values() for item in siblings
        }
        present = [
            str(item["data_id"])
            for item in effective_selected
            if str(item["data_id"]) in remaining_ids
        ]
        if present:
            raise ChaoxingAPIError(
                "server accepted resource deletion, but these IDs remain: " + ", ".join(present)
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "deleted": selected,
            "affected_parent_remaining_count": sum(
                len(items) for items in refreshed_by_parent.values()
            ),
            "verification": (
                f"deleted {len(selected)} resources and confirmed their absence "
                f"in {len(refreshed_by_parent)} affected parent folders"
            ),
        }

    def _add_resource_record(
        self,
        context: dict[str, Any],
        course: dict[str, Any],
        clazz: dict[str, Any],
        record: dict[str, Any],
    ) -> dict[str, Any]:
        try:
            response = context["session"].post(
                f"{MOOC2_BASE_URL}/mooc2-ans/coursedata/adddata",
                data={
                    "jsonData": json.dumps([record], ensure_ascii=False, separators=(",", ":")),
                    "courseid": course["course_id"],
                    "cpi": course["cpi"],
                    "microTopicId": context["hidden"].get("microTopicId", "0"),
                },
                timeout=self.timeout,
                headers={"Referer": context["root_url"]},
            )
            response.raise_for_status()
            payload = self._resource_json(response, "resource registration")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"resource registration failed: {exc}") from exc
        if payload.get("status") is False:
            raise ChaoxingAPIError(str(payload.get("msg") or "Chaoxing rejected the resource"))
        return payload

    def create_resource_link(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        name: str,
        url: str,
        *,
        parent: str = "",
    ) -> dict[str, Any]:
        normalized_name = self._validate_resource_name(name)
        normalized_url = str(url or "").strip()
        if not re.match(r"^https?://", normalized_url, flags=re.IGNORECASE):
            normalized_url = "https://" + normalized_url
        parsed = urlparse(normalized_url)
        if parsed.scheme not in {"http", "https"} or not parsed.hostname:
            raise ChaoxingAPIError("resource URL must be a valid HTTP or HTTPS URL")
        if len(normalized_url) > 1024:
            raise ChaoxingAPIError("resource URL cannot exceed 1024 characters")
        session = self._session()
        context = self._resource_context(session, course, clazz)
        destination = self._resolve_resource_parent(context, course, clazz, parent)
        before = self._resource_folder_items(
            context,
            course,
            clazz,
            folder_id=str(destination["data_id"]),
            folder_name=str(destination["name"]),
        )
        before_ids = {str(item["data_id"]) for item in before}
        payload = self._add_resource_record(
            context,
            course,
            clazz,
            {
                "courseId": course["course_id"],
                "rootId": destination["data_id"],
                "dataName": normalized_name,
                "url": normalized_url,
                "dataType": "url",
                "courseName": course["course_name"],
                "isOpen": context["hidden"].get("isOpen", "0"),
            },
        )
        refreshed = self._resource_folder_items(
            context,
            course,
            clazz,
            folder_id=str(destination["data_id"]),
            folder_name=str(destination["name"]),
        )
        created = [
            item
            for item in refreshed
            if str(item["data_id"]) not in before_ids
            and item["name"] == normalized_name
            and item["data_type"].lower() == "url"
        ]
        if len(created) != 1:
            raise ChaoxingAPIError(
                "server accepted the link, but exactly one new matching resource was not found"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "parent": destination,
            "resource": created[0],
            "server_key": str(payload.get("key") or ""),
            "verification": (
                f"created link resource {created[0]['data_id']} and found it after refresh"
            ),
        }

    def upload_resource_file(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        file_path: str | Path,
        *,
        parent: str = "",
        name: str = "",
    ) -> dict[str, Any]:
        path = Path(file_path).expanduser().resolve()
        if not path.exists() or not path.is_file():
            raise ChaoxingAPIError(f"upload file does not exist: {path}")
        if not path.suffix:
            raise ChaoxingAPIError("Chaoxing requires an uploaded file to have an extension")
        if path.stat().st_size > 1024 * 1024 * 1024:
            raise ChaoxingAPIError("Chaoxing limits each ordinary resource upload to 1 GB")
        resource_name = self._validate_resource_name(name or path.name)
        session = self._session()
        context = self._resource_context(session, course, clazz)
        destination = self._resolve_resource_parent(context, course, clazz, parent)
        before = self._resource_folder_items(
            context,
            course,
            clazz,
            folder_id=str(destination["data_id"]),
            folder_name=str(destination["name"]),
        )
        before_ids = {str(item["data_id"]) for item in before}
        upload_match = re.search(
            r"var\s+commonUploadUrl\s*=\s*ServerHost\.uploadDomain\s*\+\s*['\"]([^'\"]+)",
            context["root_html"],
            flags=re.IGNORECASE,
        )
        if not upload_match:
            raise ChaoxingAPIError(
                "resource page did not expose the current upload authorization URL"
            )
        upload_path = unescape(upload_match.group(1))
        upload_url = UPLOAD_BASE_URL.rstrip("/") + "/" + upload_path.lstrip("/")
        parsed_upload = urlparse(upload_url)
        if (
            parsed_upload.scheme != "https"
            or parsed_upload.hostname != "mooc1.chaoxing.com"
            or not parsed_upload.path.startswith("/upload-ans/upload/uploadNew")
        ):
            raise ChaoxingAPIError("resource page exposed an unexpected upload endpoint")
        content_type = mimetypes.guess_type(path.name)[0] or "application/octet-stream"
        try:
            with path.open("rb") as stream:
                upload_response = session.post(
                    upload_url,
                    data={"source": "1"},
                    files={"file": (path.name, stream, content_type)},
                    timeout=max(self.timeout, 300),
                    headers={"Referer": context["root_url"]},
                )
            upload_response.raise_for_status()
            uploaded = self._resource_json(upload_response, "resource file upload")
        except (OSError, requests.RequestException) as exc:
            raise ChaoxingAPIError(f"resource file upload failed: {exc}") from exc
        if str(uploaded.get("state") or "").upper() != "SUCCESS":
            raise ChaoxingAPIError(str(uploaded.get("state") or "Chaoxing rejected the upload"))
        object_id = str(uploaded.get("url") or uploaded.get("objectId") or "")
        if not object_id:
            raise ChaoxingAPIError("upload succeeded but did not return a resource object ID")
        registration = self._add_resource_record(
            context,
            course,
            clazz,
            {
                "courseId": course["course_id"],
                "rootId": destination["data_id"],
                "dataName": resource_name,
                "source": "1",
                "dataSize": uploaded.get("fileSize", path.stat().st_size),
                "dataType": uploaded.get("fileType", path.suffix.lstrip(".")),
                "objectId": object_id,
                "courseName": course["course_name"],
                "isOpen": "0",
                "dataRealType": uploaded.get("fileRealType", ""),
            },
        )
        refreshed = self._resource_folder_items(
            context,
            course,
            clazz,
            folder_id=str(destination["data_id"]),
            folder_name=str(destination["name"]),
        )
        created = [
            item
            for item in refreshed
            if str(item["data_id"]) not in before_ids
            and item["name"] == resource_name
            and (not item["object_id"] or item["object_id"] == object_id)
        ]
        if len(created) != 1:
            raise ChaoxingAPIError(
                "file bytes were uploaded, but exactly one registered course resource was not found"
            )
        cloud_resource: dict[str, Any] | None = None
        cloud_warning = ""
        try:
            cloud_resource = self._find_active_cloud_disk_item_by_object_id(
                session,
                object_id=object_id,
                name=resource_name,
            )
        except ChaoxingAPIError as exc:
            cloud_warning = str(exc)
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "parent": destination,
            "resource": created[0],
            "local_file": str(path),
            "byte_count": path.stat().st_size,
            "server_key": str(registration.get("key") or ""),
            "cloud_resource": cloud_resource,
            "cloud_side_effect": (
                "Chaoxing also stored the uploaded bytes in the account cloud disk"
            ),
            "cloud_warning": cloud_warning,
            "verification": (
                f"uploaded and registered resource {created[0]['data_id']}, "
                "then found it after refresh; the associated cloud object was also queried"
            ),
        }

    @staticmethod
    def _resource_download_target(
        output_path: str | Path,
        *,
        suggested_name: str,
        overwrite: bool,
    ) -> Path:
        target = Path(output_path).expanduser()
        if target.exists() and target.is_dir():
            target = target / suggested_name
        elif not target.name:
            raise ChaoxingAPIError("output_path must name a file or an existing directory")
        if target.exists() and not overwrite:
            raise ChaoxingAPIError(f"download target already exists: {target}")
        target.parent.mkdir(parents=True, exist_ok=True)
        return target.resolve()

    def _resource_file_response(
        self,
        context: dict[str, Any],
        course: dict[str, Any],
        clazz: dict[str, Any],
        selected: dict[str, Any],
    ) -> tuple[requests.Response, str]:
        download_url = str(selected.get("download_url") or "")
        if not download_url:
            domain = str(context["hidden"].get("downloadDomain") or MOOC1_BASE_URL)
            download_url = append_query_params(
                domain.rstrip("/") + "/coursedata/downloadData",
                {
                    "dataId": selected["data_id"],
                    "classId": clazz["clazz_id"],
                    "cpi": course["cpi"],
                    "courseId": course["course_id"],
                    "ut": "t",
                },
            )
        parsed = urlparse(download_url)
        if parsed.scheme not in {"http", "https"} or not parsed.hostname:
            raise ChaoxingAPIError("resource page returned an unsafe download URL")
        try:
            response = context["session"].get(
                download_url,
                timeout=max(self.timeout, 300),
                stream=True,
                allow_redirects=True,
                headers={"Referer": context["root_url"]},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"resource download failed: {exc}") from exc
        content_type = str(response.headers.get("Content-Type") or "").lower()
        if "text/html" in content_type:
            raise ChaoxingAPIError(
                "resource download returned HTML instead of a file: "
                + html_text(self._decode(response), 240)
            )
        return response, content_type

    def download_resource_file(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        resource: str,
        output_path: str | Path,
        *,
        overwrite: bool = False,
    ) -> dict[str, Any]:
        session = self._session()
        context = self._resource_context(session, course, clazz)
        selected = self._resolve_resource_from_context(
            context,
            course,
            clazz,
            resource,
            require_folder=False,
        )
        response, content_type = self._resource_file_response(
            context,
            course,
            clazz,
            selected,
        )
        server_name = content_disposition_filename(
            str(response.headers.get("Content-Disposition") or "")
        )
        target = self._resource_download_target(
            output_path,
            suggested_name=server_name or str(selected["name"]),
            overwrite=overwrite,
        )
        temporary = target.with_name(target.name + ".part")
        if temporary.exists():
            raise ChaoxingAPIError(f"temporary download target already exists: {temporary}")
        size = 0
        try:
            with temporary.open("wb") as stream:
                for chunk in response.iter_content(chunk_size=1024 * 256):
                    if chunk:
                        stream.write(chunk)
                        size += len(chunk)
            temporary.replace(target)
        except OSError as exc:
            temporary.unlink(missing_ok=True)
            raise ChaoxingAPIError(f"could not save resource download: {exc}") from exc
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "resource": selected,
            "output_path": str(target),
            "file_name": target.name,
            "byte_count": size,
            "content_type": content_type,
            "verification": "saved the authenticated response as a non-HTML local file",
        }

    @staticmethod
    def _resource_archive_segment(name: str, fallback: str) -> str:
        normalized = re.sub(r"[\\/:*?\"<>|\x00-\x1f]", "_", str(name or "").strip())
        normalized = normalized.strip(". ")
        return normalized or fallback

    def download_resource_items(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        resources: list[str],
        output_path: str | Path,
        *,
        overwrite: bool = False,
        max_nodes: int = 5000,
    ) -> dict[str, Any]:
        if not resources:
            raise ChaoxingAPIError("at least one resource is required")
        session = self._session()
        context = self._resource_context(session, course, clazz)
        tree = self._resource_tree_from_context(
            context,
            course,
            clazz,
            max_nodes=max_nodes,
        )
        selected: list[dict[str, Any]] = []
        for query in resources:
            item = resolve_resource_item(tree, query)
            if all(str(existing["data_id"]) != str(item["data_id"]) for existing in selected):
                selected.append(item)
        selected = [
            item
            for item in selected
            if not any(
                ancestor["is_folder"]
                and str(item.get("path") or "").startswith(
                    str(ancestor.get("path") or "").rstrip("/") + "/"
                )
                for ancestor in selected
                if str(ancestor["data_id"]) != str(item["data_id"])
            )
        ]
        if (
            len(selected) == 1
            and not selected[0]["is_folder"]
            and not selected[0].get("source_url")
        ):
            response, content_type = self._resource_file_response(
                context,
                course,
                clazz,
                selected[0],
            )
            server_name = content_disposition_filename(
                str(response.headers.get("Content-Disposition") or "")
            )
            target = self._resource_download_target(
                output_path,
                suggested_name=server_name or str(selected[0]["name"]),
                overwrite=overwrite,
            )
            temporary = target.with_name(target.name + ".part")
            if temporary.exists():
                raise ChaoxingAPIError(f"temporary download target already exists: {temporary}")
            size = 0
            try:
                with temporary.open("wb") as stream:
                    for chunk in response.iter_content(chunk_size=1024 * 256):
                        if chunk:
                            stream.write(chunk)
                            size += len(chunk)
                temporary.replace(target)
            except OSError as exc:
                temporary.unlink(missing_ok=True)
                raise ChaoxingAPIError(f"could not save resource download: {exc}") from exc
            return {
                "course_id": course["course_id"],
                "clazz_id": clazz["clazz_id"],
                "resources": selected,
                "output_path": str(target),
                "file_name": target.name,
                "file_count": 1,
                "byte_count": size,
                "content_type": content_type,
                "archive": False,
                "verification": "saved one authenticated course resource through HTTP",
            }

        children_by_parent: dict[str, list[dict[str, Any]]] = {}
        for item in tree:
            children_by_parent.setdefault(str(item.get("parent_id") or "0"), []).append(item)
        binary_files: list[tuple[dict[str, Any], str]] = []
        link_files: list[tuple[str, str]] = []
        empty_folders: list[str] = []
        used_roots: set[str] = set()
        node_count = 0

        def add_item(item: dict[str, Any], archive_path: str) -> None:
            nonlocal node_count
            node_count += 1
            if node_count > max_nodes:
                raise ChaoxingAPIError(
                    f"resource download exceeds the safety limit of {max_nodes} nodes"
                )
            if item["is_folder"]:
                children = children_by_parent.get(str(item["data_id"]), [])
                if not children:
                    empty_folders.append(archive_path.rstrip("/") + "/")
                    return
                child_names: set[str] = set()
                for child in children:
                    segment = self._resource_archive_segment(
                        str(child["name"]), f"resource-{child['data_id']}"
                    )
                    if segment.lower() in child_names:
                        segment = f"{segment}-{child['data_id']}"
                    child_names.add(segment.lower())
                    add_item(child, f"{archive_path.rstrip('/')}/{segment}")
                return
            source_url = str(item.get("source_url") or "").strip()
            if source_url:
                link_path = archive_path
                if not link_path.lower().endswith(".url"):
                    link_path += ".url"
                link_files.append((link_path, f"[InternetShortcut]\r\nURL={source_url}\r\n"))
            else:
                binary_files.append((item, archive_path))

        for item in selected:
            base = self._resource_archive_segment(str(item["name"]), f"resource-{item['data_id']}")
            if base.lower() in used_roots:
                base = f"{base}-{item['data_id']}"
            used_roots.add(base.lower())
            add_item(item, base)

        if len(selected) == 1:
            archive_name = self._resource_archive_segment(
                str(selected[0]["name"]), f"resource-{selected[0]['data_id']}"
            )
        else:
            archive_name = self._resource_archive_segment(
                str(course.get("course_name") or "course-resources"),
                "course-resources",
            )
        target = self._resource_download_target(
            output_path,
            suggested_name=archive_name + ".zip",
            overwrite=overwrite,
        )
        temporary = target.with_name(target.name + ".part")
        if temporary.exists():
            raise ChaoxingAPIError(f"temporary download target already exists: {temporary}")
        downloaded_bytes = 0
        try:
            with zipfile.ZipFile(
                temporary,
                mode="w",
                compression=zipfile.ZIP_DEFLATED,
                allowZip64=True,
            ) as archive:
                for folder_path in empty_folders:
                    archive.writestr(folder_path, b"")
                for link_path, content in link_files:
                    encoded = content.encode("utf-8")
                    archive.writestr(link_path, encoded)
                    downloaded_bytes += len(encoded)
                for item, archive_path in binary_files:
                    response, _content_type = self._resource_file_response(
                        context,
                        course,
                        clazz,
                        item,
                    )
                    with archive.open(archive_path, mode="w", force_zip64=True) as output:
                        for chunk in response.iter_content(chunk_size=1024 * 256):
                            if chunk:
                                output.write(chunk)
                                downloaded_bytes += len(chunk)
            temporary.replace(target)
        except ChaoxingAPIError:
            temporary.unlink(missing_ok=True)
            raise
        except (OSError, zipfile.BadZipFile) as exc:
            temporary.unlink(missing_ok=True)
            raise ChaoxingAPIError(f"could not save resource archive: {exc}") from exc
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "resources": selected,
            "output_path": str(target),
            "file_name": target.name,
            "file_count": len(binary_files),
            "link_count": len(link_files),
            "empty_folder_count": len(empty_folders),
            "source_byte_count": downloaded_bytes,
            "byte_count": target.stat().st_size,
            "content_type": "application/zip",
            "archive": True,
            "verification": (
                f"downloaded {len(binary_files)} course files through HTTP, preserved "
                f"{len(link_files)} links, and assembled a local ZIP without the client"
            ),
        }

    def set_resource_download_permission(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        resources: list[str],
        *,
        allow_download: bool,
    ) -> dict[str, Any]:
        if not resources:
            raise ChaoxingAPIError("at least one resource is required")
        session = self._session()
        context = self._resource_context(session, course, clazz)
        tree = self._resource_tree_from_context(context, course, clazz)
        selected = [resolve_resource_item(tree, query) for query in resources]
        selected_ids = list(dict.fromkeys(str(item["data_id"]) for item in selected))
        try:
            response = session.post(
                f"{MOOC2_BASE_URL}/mooc2-ans/coursedata/batch-set-download",
                data={
                    "courseId": course["course_id"],
                    "dataIds": ",".join(selected_ids),
                    "isDownload": "1" if allow_download else "0",
                    "cpi": course["cpi"],
                },
                timeout=self.timeout,
                headers={"Referer": context["root_url"]},
            )
            response.raise_for_status()
            payload = self._resource_json(response, "resource download-permission update")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"resource download-permission update failed: {exc}") from exc
        if not payload.get("status"):
            raise ChaoxingAPIError(str(payload.get("msg") or "Chaoxing rejected the permission"))
        refreshed = self._resource_tree_from_context(context, course, clazz)
        updated = [resolve_resource_item(refreshed, item_id) for item_id in selected_ids]
        if any(bool(item["can_download"]) is not allow_download for item in updated):
            raise ChaoxingAPIError(
                "permission response was successful, but one or more refreshed values differ"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "allow_download": allow_download,
            "resources": updated,
            "verification": f"updated and re-read {len(updated)} download-permission values",
        }

    def read_resource_folder_visibility(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        folder: str,
        *,
        context: dict[str, Any] | None = None,
        selected: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        local_context = context or self._resource_context(self._session(), course, clazz)
        target = selected or self._resolve_resource_from_context(
            local_context,
            course,
            clazz,
            folder,
            require_folder=True,
        )
        try:
            response = local_context["session"].post(
                f"{MOOC2_BASE_URL}/mooc2-ans/coursedata/getallclass",
                data={
                    "courseId": course["course_id"],
                    "dataId": target["data_id"],
                    "cpi": course["cpi"],
                    "getFolderCreFlag": "1",
                },
                timeout=self.timeout,
                headers={"Referer": local_context["root_url"]},
            )
            response.raise_for_status()
            payload = self._resource_json(response, "resource folder visibility")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"resource folder visibility request failed: {exc}") from exc
        if payload.get("status") is False:
            raise ChaoxingAPIError(str(payload.get("msg") or "could not read folder visibility"))
        class_ids = [
            value
            for value in re.split(r"[,;\s]+", str(payload.get("openPartClassIds") or ""))
            if value
        ]
        open_part = int(payload.get("openPartClass") or 0)
        mode = (
            "all_classes" if open_part == 0 else ("selected_classes" if class_ids else "no_classes")
        )
        all_classes = payload.get("data") if isinstance(payload.get("data"), list) else []
        all_teachers = (
            payload.get("allTeacherTeamArr")
            if isinstance(payload.get("allTeacherTeamArr"), list)
            else []
        )
        authorized_teacher_ids = [
            str(value)
            for value in (
                payload.get("haveAuthTeacherTeamArrIds")
                if isinstance(payload.get("haveAuthTeacherTeamArrIds"), list)
                else []
            )
        ]
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "folder": target,
            "mode": mode,
            "class_ids": class_ids,
            "classes": all_classes,
            "no_authority_classes": (
                payload.get("noAuthClazzIds")
                if isinstance(payload.get("noAuthClazzIds"), list)
                else []
            ),
            "all_teachers": all_teachers,
            "authorized_teacher_ids": authorized_teacher_ids,
            "all_teachers_authorized": bool(payload.get("openPartTeacherTeamFlag")),
            "creator_ids": (
                payload.get("dataCreatorId")
                if isinstance(payload.get("dataCreatorId"), list)
                else []
            ),
            "verification": "read the folder's current class and teacher-team visibility",
        }

    def update_resource_folder_visibility(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        folder: str,
        *,
        mode: str,
        classes: list[str] | None = None,
        teacher_ids: list[str] | None = None,
        all_teachers: bool | None = None,
    ) -> dict[str, Any]:
        aliases = {
            "all": "all_classes",
            "all_classes": "all_classes",
            "全部班级": "all_classes",
            "selected": "selected_classes",
            "selected_classes": "selected_classes",
            "指定班级": "selected_classes",
            "none": "no_classes",
            "no_classes": "no_classes",
            "不对班级开放": "no_classes",
        }
        normalized_mode = aliases.get(str(mode or "").strip().lower())
        if not normalized_mode:
            raise ChaoxingAPIError("mode must be all_classes, selected_classes, or no_classes")
        session = self._session()
        context = self._resource_context(session, course, clazz)
        selected = self._resolve_resource_from_context(
            context,
            course,
            clazz,
            folder,
            require_folder=True,
        )
        before = self.read_resource_folder_visibility(
            course, clazz, folder, context=context, selected=selected
        )
        class_ids: list[str] = []
        if normalized_mode == "selected_classes":
            if not classes:
                raise ChaoxingAPIError("selected_classes mode requires at least one class")
            class_ids = [str(resolve_class(course, query)["clazz_id"]) for query in classes]
            class_ids = list(dict.fromkeys(class_ids))
        effective_teacher_ids = (
            list(dict.fromkeys(str(value) for value in teacher_ids))
            if teacher_ids is not None
            else list(before["authorized_teacher_ids"])
        )
        effective_all_teachers = (
            bool(all_teachers)
            if all_teachers is not None
            else bool(before["all_teachers_authorized"])
        )
        all_teacher_ids = {
            str(item.get("id") or "")
            for item in before["all_teachers"]
            if isinstance(item, dict) and item.get("id")
        }
        delete_teacher_ids = sorted(all_teacher_ids - set(effective_teacher_ids))
        shared = normalized_mode != "all_classes"
        try:
            response = session.post(
                f"{MOOC2_BASE_URL}/mooc2-ans/coursedata/dataReNameNew",
                data={
                    "dataId": selected["data_id"],
                    "dataName": selected["name"],
                    "isOpen": "0",
                    "shared": "true" if shared else "false",
                    "classIds": ",".join(class_ids),
                    "cpi": course["cpi"],
                    "courseid": course["course_id"],
                    "personIds": ",".join(effective_teacher_ids),
                    "openTeacherTeamAll": "true" if effective_all_teachers else "false",
                    "deletePersonIds": ",".join(delete_teacher_ids),
                },
                timeout=self.timeout,
                headers={"Referer": context["root_url"]},
            )
            response.raise_for_status()
            payload = self._resource_json(response, "resource folder visibility update")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"resource folder visibility update failed: {exc}") from exc
        if int(payload.get("result") or 0) != 1:
            raise ChaoxingAPIError(str(payload.get("msg") or "Chaoxing rejected folder visibility"))
        refreshed = self.read_resource_folder_visibility(
            course, clazz, folder, context=context, selected=selected
        )
        if refreshed["mode"] != normalized_mode or set(refreshed["class_ids"]) != set(class_ids):
            raise ChaoxingAPIError("folder visibility response was successful, but refresh differs")
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "before": before,
            "visibility": refreshed,
            "verification": "updated folder visibility and re-read class and teacher-team access",
        }

    def list_resource_readers(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        resource: str,
        *,
        reader_class: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        session = self._session()
        context = self._resource_context(session, course, clazz)
        selected = self._resolve_resource_from_context(context, course, clazz, resource)
        target_class = reader_class or clazz
        read_people: list[dict[str, Any]] = []
        unread_people: list[dict[str, Any]] = []
        class_options: list[dict[str, Any]] = []
        last_person_id = 0
        seen_cursors: set[int] = set()
        for _ in range(100):
            try:
                response = session.get(
                    f"{MOOC2_BASE_URL}/mooc2-ans/coursedata/data-reader-list",
                    params={
                        "courseid": course["course_id"],
                        "clazzid": target_class["clazz_id"],
                        "dataId": selected["data_id"],
                        "cpi": course["cpi"],
                        "lastPersonId": last_person_id,
                    },
                    timeout=self.timeout,
                    headers={
                        "Referer": context["root_url"],
                        "X-Requested-With": "XMLHttpRequest",
                    },
                )
                response.raise_for_status()
                payload = self._resource_json(response, "resource reader list")
            except requests.RequestException as exc:
                raise ChaoxingAPIError(f"resource reader list failed: {exc}") from exc
            if not payload.get("status"):
                raise ChaoxingAPIError(str(payload.get("msg") or "could not read resource readers"))
            if not class_options and isinstance(payload.get("clazzList"), list):
                class_options = payload["clazzList"]
            page_read = payload.get("readPersonList")
            if isinstance(page_read, list):
                read_people.extend(item for item in page_read if isinstance(item, dict))
            if not unread_people and isinstance(payload.get("unReadPersonList"), list):
                unread_people = [
                    item for item in payload["unReadPersonList"] if isinstance(item, dict)
                ]
            try:
                next_cursor = int(payload.get("lastPersonId") or 0)
            except (TypeError, ValueError):
                next_cursor = 0
            if next_cursor <= 0 or next_cursor in seen_cursors:
                break
            seen_cursors.add(next_cursor)
            last_person_id = next_cursor
        return {
            "course_id": course["course_id"],
            "clazz_id": target_class["clazz_id"],
            "clazz_name": target_class["clazz_name"],
            "resource": selected,
            "read_count": len(read_people),
            "unread_count": len(unread_people),
            "readers": read_people,
            "non_readers": unread_people,
            "class_options": class_options,
            "verification": "read the complete reader and non-reader lists through HTTP",
        }

    def list_resource_downloaders(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        resource: str,
    ) -> dict[str, Any]:
        session = self._session()
        context = self._resource_context(session, course, clazz)
        selected = self._resolve_resource_from_context(context, course, clazz, resource)
        try:
            response = session.get(
                f"{MOOC2_BASE_URL}/mooc2-ans/coursedata/query/downloaders",
                params={"dataId": selected["data_id"], "courseId": course["course_id"]},
                timeout=self.timeout,
                headers={"Referer": context["root_url"]},
            )
            response.raise_for_status()
            payload = self._resource_json(response, "resource downloader list")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"resource downloader list failed: {exc}") from exc
        if not payload.get("status"):
            raise ChaoxingAPIError(str(payload.get("msg") or "could not read resource downloaders"))
        people = payload.get("array") if isinstance(payload.get("array"), list) else []
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "resource": selected,
            "count": len(people),
            "downloaders": [item for item in people if isinstance(item, dict)],
            "server_count": payload.get("size"),
            "verification": f"read {len(people)} resource downloader records through HTTP",
        }

    def list_resource_import_courses(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        search: str = "",
    ) -> dict[str, Any]:
        session = self._session()
        context = self._resource_context(session, course, clazz)
        try:
            response = session.get(
                f"{MOOC2_BASE_URL}/mooc2-ans/course/getimportlist",
                params={
                    "courseId": course["course_id"],
                    "cpi": course["cpi"],
                    "viewType": "2",
                    "require": search,
                },
                timeout=self.timeout,
                headers={"Referer": context["root_url"]},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"resource import-course list failed: {exc}") from exc
        courses = parse_resource_import_courses(self._decode(response))
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "search": search,
            "count": len(courses),
            "courses": courses,
            "verification": f"parsed {len(courses)} source courses available for resource import",
        }

    def list_resource_import_items(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        source_course: str,
        *,
        folder_id: str = "",
        search: str = "",
        page: int = 1,
        page_size: int = 100,
    ) -> dict[str, Any]:
        if page < 1 or page_size < 1 or page_size > 100:
            raise ChaoxingAPIError("page must be positive and page_size must be 1-100")
        sources = self.list_resource_import_courses(course, clazz)
        selected_source = _resolve_titled_item(
            sources["courses"],
            source_course,
            id_key="course_id",
            label="resource import source course",
        )
        session = self._session()
        context = self._resource_context(session, course, clazz)
        try:
            response = session.get(
                f"{MOOC2_BASE_URL}/mooc2-ans/coursedata/get-course-data-list",
                params={
                    "pageNum": page,
                    "pageSize": page_size,
                    "dataId": folder_id,
                    "targetCourseId": selected_source["course_id"],
                    "dataName": search,
                },
                timeout=self.timeout,
                headers={"Referer": context["root_url"]},
            )
            response.raise_for_status()
            payload = self._resource_json(response, "resource import item list")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"resource import item list failed: {exc}") from exc
        if not payload.get("status"):
            raise ChaoxingAPIError(str(payload.get("msg") or "could not list source resources"))
        parsed = parse_resource_import_items(payload)
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "source_course": selected_source,
            "folder_id": folder_id,
            "search": search,
            "page": page,
            "page_size": page_size,
            "total_pages": parsed["total_pages"],
            "server_page_size": parsed["server_page_size"],
            "count": len(parsed["items"]),
            "items": parsed["items"],
            "verification": f"read {len(parsed['items'])} source resources through HTTP",
        }

    def import_resources_from_course(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        source_course: str,
        resources: list[str],
        *,
        source_folder_id: str = "",
        destination: str = "",
    ) -> dict[str, Any]:
        if not resources:
            raise ChaoxingAPIError("at least one source resource is required")
        if len(resources) > 100:
            raise ChaoxingAPIError("Chaoxing imports at most 100 resources per request")
        source_listing = self.list_resource_import_items(
            course,
            clazz,
            source_course,
            folder_id=source_folder_id,
            page_size=100,
        )
        selected: list[dict[str, Any]] = []
        for query in resources:
            item = resolve_resource_item(source_listing["items"], query)
            if all(str(existing["data_id"]) != str(item["data_id"]) for existing in selected):
                selected.append(item)
        session = self._session()
        context = self._resource_context(session, course, clazz)
        target = self._resolve_resource_parent(context, course, clazz, destination)
        before = self._resource_folder_items(
            context,
            course,
            clazz,
            folder_id=str(target["data_id"]),
            folder_name=str(target["name"]),
        )
        before_ids = {str(item["data_id"]) for item in before}
        try:
            response = session.post(
                f"{MOOC2_BASE_URL}/mooc2-ans/coursedata/import-course-data-list",
                data={
                    "targetCourseId": course["course_id"],
                    "srcCourseId": source_listing["source_course"]["course_id"],
                    "dataIds": ",".join(str(item["data_id"]) for item in selected),
                    "parentId": target["data_id"],
                },
                timeout=max(self.timeout, 120),
                headers={"Referer": context["root_url"]},
            )
            response.raise_for_status()
            payload = self._resource_json(response, "resource import")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"resource import failed: {exc}") from exc
        if not payload.get("status"):
            raise ChaoxingAPIError(str(payload.get("msg") or "Chaoxing rejected resource import"))
        refreshed = self._resource_folder_items(
            context,
            course,
            clazz,
            folder_id=str(target["data_id"]),
            folder_name=str(target["name"]),
        )
        new_items = [item for item in refreshed if str(item["data_id"]) not in before_ids]
        selected_names = {str(item["name"]) for item in selected}
        if not selected_names.issubset({str(item["name"]) for item in new_items}):
            raise ChaoxingAPIError(
                "resource import response was successful, but not every selected name appeared"
            )
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "source_course": source_listing["source_course"],
            "destination": target,
            "selected": selected,
            "imported": new_items,
            "server_message": str(payload.get("msg") or ""),
            "verification": (
                f"imported {len(selected)} resources and found every name after refresh"
            ),
        }

    def create_resource_share_link(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        resource: str,
    ) -> dict[str, Any]:
        session = self._session()
        context = self._resource_context(session, course, clazz)
        selected = self._resolve_resource_from_context(context, course, clazz, resource)
        try:
            response = session.get(
                f"{MOOC2_BASE_URL}/mooc2-ans/coursedata/sharedResource/generateKey",
                params={
                    "id": selected["data_id"],
                    "courseId": course["course_id"],
                    "cpi": course["cpi"],
                },
                timeout=self.timeout,
                headers={"Referer": context["root_url"]},
            )
            response.raise_for_status()
            payload = self._resource_json(response, "resource share-link creation")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"resource share-link creation failed: {exc}") from exc
        key = str(payload.get("key") or "")
        if not key:
            raise ChaoxingAPIError(str(payload.get("msg") or "Chaoxing did not return a share key"))
        return {
            "course_id": course["course_id"],
            "clazz_id": clazz["clazz_id"],
            "resource": selected,
            "share_url": append_query_params(
                f"{MOOC1_BASE_URL}/coursedata/sharedResource", {"key": key}
            ),
            "verification": "Chaoxing returned a non-empty share key and HTTP share URL",
        }

    def _cloud_disk_json(self, response: requests.Response, operation: str) -> Any:
        try:
            return json.loads(self._decode(response))
        except (json.JSONDecodeError, ValueError) as exc:
            raise ChaoxingAPIError(f"{operation} returned invalid JSON") from exc

    def _cloud_disk_context(
        self,
        session: requests.Session | None = None,
    ) -> dict[str, Any]:
        active_session = session or self._session()
        endpoint = CLOUD_DISK_BASE_URL + "/pcuserpan/index"
        try:
            response = active_session.get(endpoint, timeout=self.timeout, allow_redirects=True)
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"cloud-disk context request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError("Chaoxing cloud-disk login has expired")
        html = self._decode(response)

        def javascript_value(name: str, *, required: bool = True) -> str:
            assignment = (
                rf"(?<![A-Za-z0-9_$])(?:var\s+)?{re.escape(name)}"
                r"(?![A-Za-z0-9_$])\s*="
            )
            literals = [
                value.strip()
                for _quote, value in re.findall(
                    assignment + r"\s*(['\"])(.*?)\1",
                    html,
                    flags=re.DOTALL,
                )
                if value.strip()
            ]
            if literals:
                value = max(literals, key=len)
            else:
                match = re.search(assignment + r"\s*([^;\s]+)", html)
                value = match.group(1).strip() if match else ""
                if any(character in value for character in "()'\""):
                    value = ""
            if required and not value:
                raise ChaoxingAPIError(f"cloud-disk page exposed no {name}")
            return value

        return {
            "session": active_session,
            "root_url": response.url,
            "current_puid": javascript_value("currentPuid"),
            "root_id": javascript_value("rootdir"),
            "enc": javascript_value("encstr"),
            "auth_header": javascript_value("p_auth_token", required=False),
            "request_token": javascript_value("_token", required=False),
            "client_token": javascript_value("cx_p_token", required=False),
        }

    @staticmethod
    def _normalize_cloud_disk_item(raw: dict[str, Any], index: int = 0) -> dict[str, Any]:
        resource_id = str(raw.get("id") or raw.get("resid") or raw.get("residstr") or "")
        name = str(raw.get("name") or "")
        is_file_value = raw.get("isfile")
        is_file = (
            is_file_value is True
            or str(is_file_value or "").strip().lower() in {"1", "true", "yes"}
            or str(raw.get("xtype") or "").strip().lower() == "file"
        )
        size_value = raw.get("filesize")
        if size_value is None:
            size_value = raw.get("size")
        try:
            byte_count: int | str = int(size_value or 0)
        except (TypeError, ValueError):
            byte_count = str(size_value or "")
        return {
            "index": index,
            "resource_id": resource_id,
            "name": name,
            "title": name,
            "is_file": is_file,
            "is_folder": bool(resource_id) and not is_file,
            "suffix": str(raw.get("suffix") or ""),
            "resource_type": raw.get("type"),
            "byte_count": byte_count,
            "object_id": str(raw.get("objectId") or raw.get("objectid") or ""),
            "owner_puid": str(raw.get("puid") or raw.get("creator") or ""),
            "parent_id": str(raw.get("parentFolderId") or ""),
            "parent_name": str(raw.get("parentFolderName") or ""),
            "path": str(raw.get("path") or ""),
            "upload_time": raw.get("uploadDate"),
            "modified_time": raw.get("modifyDate"),
            "deleted_time": raw.get("deleteDate") or raw.get("deleteTime"),
            "expires_time": raw.get("validDate") or raw.get("validTime"),
            "is_top": int(raw.get("topsort") or 0) > 0,
            "is_shared": bool(raw.get("isshare")),
            "shared_to_me": bool(raw.get("istome")),
            "operations_disabled": bool(raw.get("disableOpt")),
            "_encrypted_id": str(raw.get("encryptedId") or ""),
        }

    @staticmethod
    def _public_cloud_disk_item(item: dict[str, Any]) -> dict[str, Any]:
        return {key: value for key, value in item.items() if not key.startswith("_")}

    def _cloud_disk_listing(
        self,
        context: dict[str, Any],
        *,
        parent_id: str,
        search: str = "",
        page: int = 1,
        page_size: int = 100,
    ) -> dict[str, Any]:
        if page < 1 or page_size < 1 or page_size > 1000:
            raise ChaoxingAPIError("page must be positive and page_size must be 1-1000")
        session = context["session"]
        try:
            response = session.get(
                CLOUD_DISK_BASE_URL + "/opt/listres",
                params={
                    "puid": context["current_puid"],
                    "shareid": "0",
                    "parentId": parent_id,
                    "page": str(page),
                    "size": str(page_size),
                    "enc": context["enc"],
                    "filterType": "",
                    "orderField": "",
                    "orderType": "",
                    "searchValue": search,
                },
                timeout=self.timeout,
                headers={
                    "Referer": context["root_url"],
                    "p-auth-token": context["auth_header"],
                },
            )
            response.raise_for_status()
            payload = self._cloud_disk_json(response, "cloud-disk item list")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"cloud-disk item list failed: {exc}") from exc
        if not isinstance(payload, dict) or not isinstance(payload.get("list"), list):
            raise ChaoxingAPIError("cloud-disk item list returned an unexpected response")
        items = [
            self._normalize_cloud_disk_item(raw, index)
            for index, raw in enumerate(payload["list"], 1)
            if isinstance(raw, dict) and str(raw.get("id") or raw.get("resid") or "")
        ]
        return {
            "parent_id": parent_id,
            "search": search,
            "page": page,
            "page_size": page_size,
            "total_count": int(payload.get("totalCount") or len(items)),
            "items": items,
        }

    def list_cloud_disk_items(
        self,
        *,
        parent: str = "",
        search: str = "",
        page: int = 1,
        page_size: int = 100,
    ) -> dict[str, Any]:
        context = self._cloud_disk_context()
        normalized_parent = str(parent or "").strip().lower()
        parent_id = (
            context["root_id"]
            if normalized_parent in {"", "0", "root", "根目录", "云盘根目录"}
            else str(parent).strip()
        )
        listing = self._cloud_disk_listing(
            context,
            parent_id=parent_id,
            search=search.strip(),
            page=page,
            page_size=page_size,
        )
        return {
            "root_id": context["root_id"],
            **{key: value for key, value in listing.items() if key != "items"},
            "count": len(listing["items"]),
            "items": [self._public_cloud_disk_item(item) for item in listing["items"]],
            "verification": f"read {len(listing['items'])} active cloud-disk items through HTTP",
        }

    def _cloud_disk_file_info(
        self,
        context: dict[str, Any],
        resource_id: str,
    ) -> dict[str, Any]:
        session = context["session"]
        try:
            response = session.get(
                CLOUD_DISK_BASE_URL + "/pcuserpan/operation/fileinfo",
                params={
                    "resid": resource_id,
                    "puid": context["current_puid"],
                    "_token": "",
                    "showShareInfo": "true",
                },
                timeout=self.timeout,
                headers={
                    "Referer": context["root_url"],
                    "p-auth-token": context["auth_header"],
                },
            )
            response.raise_for_status()
            payload = self._cloud_disk_json(response, "cloud-disk item detail")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"cloud-disk item detail failed: {exc}") from exc
        data = payload.get("data") if isinstance(payload, dict) else None
        if not isinstance(data, list) or not data or not isinstance(data[0], dict):
            raise ChaoxingAPIError(f"active cloud-disk item not found: {resource_id}")
        return self._normalize_cloud_disk_item(data[0], 1)

    def _resolve_active_cloud_disk_item(
        self,
        context: dict[str, Any],
        query: str,
    ) -> dict[str, Any]:
        normalized = str(query or "").strip()
        if not normalized:
            raise ChaoxingAPIError("cloud-disk item ID or name is required")
        if normalized.isdigit():
            detail = self._cloud_disk_file_info(context, normalized)
            active = self._cloud_disk_listing(
                context,
                parent_id=context["root_id"],
                search=str(detail["name"]),
                page_size=1000,
            )["items"]
            match = next(
                (item for item in active if str(item["resource_id"]) == normalized),
                None,
            )
            if match is None:
                raise ChaoxingAPIError(f"active cloud-disk item not found: {query}")
            return match
        candidates = self._cloud_disk_listing(
            context,
            parent_id=context["root_id"],
            search=normalized,
            page_size=1000,
        )["items"]
        exact = [
            item for item in candidates if str(item["name"]).strip().lower() == normalized.lower()
        ]
        partial = [item for item in candidates if normalized.lower() in str(item["name"]).lower()]
        matches = exact or partial
        if len(matches) == 1:
            return matches[0]
        if not matches:
            raise ChaoxingAPIError(f"active cloud-disk item not found: {query}")
        choices = ", ".join(f"{item['name']} ({item['resource_id']})" for item in matches[:20])
        raise ChaoxingAPIError(f"multiple active cloud-disk items match: {choices}")

    def read_cloud_disk_item(self, resource: str) -> dict[str, Any]:
        context = self._cloud_disk_context()
        item = self._resolve_active_cloud_disk_item(context, resource)
        return {
            "item": self._public_cloud_disk_item(item),
            "verification": f"resolved active cloud-disk item {item['resource_id']} through HTTP",
        }

    @staticmethod
    def _validate_cloud_disk_name(name: str) -> str:
        normalized = str(name or "").strip()
        if not normalized or len(normalized) > 255:
            raise ChaoxingAPIError("cloud-disk name must contain 1-255 characters")
        if any(character in normalized for character in ("/", "\\", "\0")):
            raise ChaoxingAPIError("cloud-disk name cannot contain a slash, backslash, or NUL")
        return normalized

    def _resolve_cloud_disk_folder(
        self,
        context: dict[str, Any],
        query: str,
    ) -> dict[str, Any]:
        normalized = str(query or "").strip().lower()
        if normalized in {"", "0", "root", "根目录", "云盘根目录"}:
            return {
                "resource_id": context["root_id"],
                "name": "根目录",
                "is_file": False,
                "is_folder": True,
                "owner_puid": context["current_puid"],
                "parent_id": "",
            }
        folder = self._resolve_active_cloud_disk_item(context, query)
        if not folder["is_folder"]:
            raise ChaoxingAPIError(f"cloud-disk destination is not a folder: {query}")
        if folder["operations_disabled"]:
            raise ChaoxingAPIError(f"cloud-disk destination does not permit operations: {query}")
        return folder

    def create_cloud_disk_folder(
        self,
        name: str,
        *,
        parent: str = "",
        shared: bool = False,
    ) -> dict[str, Any]:
        normalized_name = self._validate_cloud_disk_name(name)
        context = self._cloud_disk_context()
        destination = self._resolve_cloud_disk_folder(context, parent)
        before = self._cloud_disk_listing(
            context,
            parent_id=str(destination["resource_id"]),
            page_size=1000,
        )["items"]
        before_ids = {str(item["resource_id"]) for item in before}
        if not context["client_token"]:
            raise ChaoxingAPIError("cloud-disk page exposed no current folder-operation token")
        try:
            response = context["session"].post(
                CLOUD_DISK_BASE_URL + "/opt/newRootfolder",
                data={
                    "parentId": destination["resource_id"],
                    "name": normalized_name,
                    "selectDlid": "allperson" if shared else "onlyme",
                    "newfileid": "0",
                    "cx_p_token": context["client_token"],
                },
                timeout=self.timeout,
                headers={
                    "Referer": context["root_url"],
                    "p-auth-token": context["auth_header"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
            payload = self._cloud_disk_json(response, "cloud-disk folder creation")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"cloud-disk folder creation failed: {exc}") from exc
        if not isinstance(payload, dict) or not (
            payload.get("success") or payload.get("result") is True
        ):
            raise ChaoxingAPIError(
                str(payload.get("msg") if isinstance(payload, dict) else "")
                or "Chaoxing rejected cloud-disk folder creation"
            )
        refreshed = self._cloud_disk_listing(
            context,
            parent_id=str(destination["resource_id"]),
            page_size=1000,
        )["items"]
        created = [
            item
            for item in refreshed
            if str(item["resource_id"]) not in before_ids
            and item["is_folder"]
            and str(item["name"]) == normalized_name
        ]
        if len(created) != 1:
            raise ChaoxingAPIError(
                "server accepted cloud-disk folder creation, but exactly one new "
                "folder was not found"
            )
        return {
            "parent": self._public_cloud_disk_item(destination),
            "folder": self._public_cloud_disk_item(created[0]),
            "shared": shared,
            "verification": (
                f"created cloud-disk folder {created[0]['resource_id']} and found it after refresh"
            ),
        }

    def rename_cloud_disk_item(self, resource: str, name: str) -> dict[str, Any]:
        normalized_name = self._validate_cloud_disk_name(name)
        context = self._cloud_disk_context()
        selected = self._resolve_active_cloud_disk_item(context, resource)
        if selected["owner_puid"] != context["current_puid"] or selected["operations_disabled"]:
            raise ChaoxingAPIError("the selected cloud-disk item cannot be renamed by this account")
        suffix = str(selected["suffix"] or "").lstrip(".")
        if (
            selected["is_file"]
            and suffix
            and not normalized_name.lower().endswith("." + suffix.lower())
        ):
            normalized_name += "." + suffix
        try:
            response = context["session"].post(
                CLOUD_DISK_BASE_URL + "/opt/rename",
                data={
                    "name": normalized_name,
                    "resid": selected["resource_id"],
                    "encryptedId": selected["_encrypted_id"],
                    "puid": context["current_puid"],
                },
                timeout=self.timeout,
                headers={
                    "Referer": context["root_url"],
                    "p-auth-token": context["auth_header"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
            payload = self._cloud_disk_json(response, "cloud-disk rename")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"cloud-disk rename failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("success"):
            raise ChaoxingAPIError(
                str(payload.get("msg") if isinstance(payload, dict) else "")
                or "Chaoxing rejected the cloud-disk rename"
            )
        updated = self._resolve_active_cloud_disk_item(context, str(selected["resource_id"]))
        if str(updated["name"]) != normalized_name:
            raise ChaoxingAPIError(
                "server accepted cloud-disk rename, but the refreshed name differs"
            )
        return {
            "before": self._public_cloud_disk_item(selected),
            "item": self._public_cloud_disk_item(updated),
            "verification": (
                f"renamed cloud-disk item {updated['resource_id']} and re-read its name"
            ),
        }

    def move_cloud_disk_items(
        self,
        resources: list[str],
        *,
        destination: str = "",
    ) -> dict[str, Any]:
        if not resources:
            raise ChaoxingAPIError("at least one cloud-disk item is required")
        if len(resources) > 100:
            raise ChaoxingAPIError("no more than 100 cloud-disk items may be moved at once")
        context = self._cloud_disk_context()
        selected: list[dict[str, Any]] = []
        for query in resources:
            item = self._resolve_active_cloud_disk_item(context, query)
            if all(existing["resource_id"] != item["resource_id"] for existing in selected):
                selected.append(item)
        target = self._resolve_cloud_disk_folder(context, destination)
        selected_ids = {str(item["resource_id"]) for item in selected}
        if str(target["resource_id"]) in selected_ids:
            raise ChaoxingAPIError("a cloud-disk folder cannot be moved into itself")
        if any(
            item["owner_puid"] != context["current_puid"] or item["operations_disabled"]
            for item in selected
        ):
            raise ChaoxingAPIError("one or more selected cloud-disk items cannot be moved")
        try:
            response = context["session"].post(
                CLOUD_DISK_BASE_URL + "/opt/moveres",
                data={
                    "folderid": f"{target['resource_id']}_{context['current_puid']}",
                    "resids": ",".join(item["resource_id"] for item in selected),
                },
                timeout=self.timeout,
                headers={
                    "Referer": context["root_url"],
                    "p-auth-token": context["auth_header"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
            payload = self._cloud_disk_json(response, "cloud-disk move")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"cloud-disk move failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("success"):
            raise ChaoxingAPIError(
                str(payload.get("msg") if isinstance(payload, dict) else "")
                or "Chaoxing rejected the cloud-disk move"
            )
        moved = [
            self._resolve_active_cloud_disk_item(context, str(item["resource_id"]))
            for item in selected
        ]
        if any(str(item["parent_id"]) != str(target["resource_id"]) for item in moved):
            raise ChaoxingAPIError(
                "server accepted the cloud-disk move, but one or more parent IDs differ"
            )
        return {
            "destination": self._public_cloud_disk_item(target),
            "moved": [self._public_cloud_disk_item(item) for item in moved],
            "verification": f"moved {len(moved)} cloud-disk items and confirmed every parent ID",
        }

    def set_cloud_disk_top_status(self, resource: str, *, top: bool) -> dict[str, Any]:
        context = self._cloud_disk_context()
        selected = self._resolve_active_cloud_disk_item(context, resource)
        if selected["owner_puid"] != context["current_puid"] or selected["operations_disabled"]:
            raise ChaoxingAPIError("the selected cloud-disk item cannot change top status")
        parent_id = str(selected["parent_id"] or context["root_id"])
        endpoint = "/opt/setupTop" if top else "/opt/cancalTop"
        try:
            response = context["session"].post(
                CLOUD_DISK_BASE_URL + endpoint,
                params={"parentId": parent_id, "fileinfoId": selected["resource_id"]},
                timeout=self.timeout,
                headers={
                    "Referer": context["root_url"],
                    "p-auth-token": context["auth_header"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
            payload = self._cloud_disk_json(response, "cloud-disk top-status update")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"cloud-disk top-status update failed: {exc}") from exc
        if not isinstance(payload, dict) or not (
            payload.get("success") or payload.get("result") is True
        ):
            raise ChaoxingAPIError(
                str(payload.get("msg") if isinstance(payload, dict) else "")
                or "Chaoxing rejected the cloud-disk top status"
            )
        siblings = self._cloud_disk_listing(
            context,
            parent_id=parent_id,
            page_size=1000,
        )["items"]
        updated = next(
            (item for item in siblings if str(item["resource_id"]) == str(selected["resource_id"])),
            None,
        )
        if updated is None or bool(updated["is_top"]) is not top:
            raise ChaoxingAPIError(
                "server accepted the cloud-disk top status, but the refreshed state differs"
            )
        return {
            "before": self._public_cloud_disk_item(selected),
            "item": self._public_cloud_disk_item(updated),
            "top": top,
            "verification": f"set cloud-disk top={top} and confirmed it after refresh",
        }

    def _cloud_disk_file_response(
        self,
        context: dict[str, Any],
        selected: dict[str, Any],
    ) -> tuple[requests.Response, str]:
        try:
            response = context["session"].get(
                CLOUD_DISK_BASE_URL + "/download/downloadFileV2",
                params={
                    "fleid": selected["resource_id"],
                    "puid": selected["owner_puid"],
                    "currentFolderId": selected["parent_id"] or context["root_id"],
                    "p_auth_token": context["auth_header"],
                    "encryptedId": selected["_encrypted_id"],
                    "auditRecordIdEnc": "",
                },
                timeout=max(self.timeout, 300),
                stream=True,
                allow_redirects=True,
                headers={
                    "Referer": context["root_url"],
                    "p-auth-token": context["auth_header"],
                },
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"cloud-disk download failed: {exc}") from exc
        content_type = str(response.headers.get("Content-Type") or "").lower()
        if "text/html" in content_type:
            raise ChaoxingAPIError(
                "cloud-disk download returned HTML instead of a file: "
                + html_text(self._decode(response), 240)
            )
        return response, content_type

    def download_cloud_disk_item(
        self,
        resource: str,
        output_path: str | Path,
        *,
        overwrite: bool = False,
    ) -> dict[str, Any]:
        context = self._cloud_disk_context()
        selected = self._resolve_active_cloud_disk_item(context, resource)
        if not selected["is_file"]:
            raise ChaoxingAPIError("single cloud-disk download requires a file, not a folder")
        response, content_type = self._cloud_disk_file_response(context, selected)
        server_name = content_disposition_filename(
            str(response.headers.get("Content-Disposition") or "")
        )
        target = self._resource_download_target(
            output_path,
            suggested_name=server_name or str(selected["name"]),
            overwrite=overwrite,
        )
        temporary = target.with_name(target.name + ".part")
        if temporary.exists():
            raise ChaoxingAPIError(f"temporary download target already exists: {temporary}")
        size = 0
        try:
            with temporary.open("wb") as stream:
                for chunk in response.iter_content(chunk_size=1024 * 256):
                    if chunk:
                        stream.write(chunk)
                        size += len(chunk)
            temporary.replace(target)
        except OSError as exc:
            temporary.unlink(missing_ok=True)
            raise ChaoxingAPIError(f"could not save cloud-disk download: {exc}") from exc
        return {
            "item": self._public_cloud_disk_item(selected),
            "output_path": str(target),
            "file_name": target.name,
            "byte_count": size,
            "content_type": content_type,
            "verification": "saved the authenticated cloud-disk response as a non-HTML local file",
        }

    @staticmethod
    def _cloud_disk_archive_segment(name: str, fallback: str) -> str:
        normalized = re.sub(r"[\\/:*?\"<>|\x00-\x1f]", "_", str(name or "").strip())
        normalized = normalized.strip(". ")
        return normalized or fallback

    def _cloud_disk_archive_entries(
        self,
        context: dict[str, Any],
        selected: list[dict[str, Any]],
        *,
        max_nodes: int = 5000,
    ) -> tuple[list[tuple[dict[str, Any], str]], list[str]]:
        files: list[tuple[dict[str, Any], str]] = []
        empty_folders: list[str] = []
        queue: list[tuple[dict[str, Any], str]] = []
        used_roots: set[str] = set()
        for item in selected:
            base = self._cloud_disk_archive_segment(
                str(item["name"]), f"item-{item['resource_id']}"
            )
            if base.lower() in used_roots:
                base = f"{base}-{item['resource_id']}"
            used_roots.add(base.lower())
            if item["is_file"]:
                files.append((item, base))
            else:
                queue.append((item, base))
        seen_folders: set[str] = set()
        node_count = len(selected)
        while queue:
            folder, prefix = queue.pop(0)
            folder_id = str(folder["resource_id"])
            if folder_id in seen_folders:
                continue
            seen_folders.add(folder_id)
            children = self._cloud_disk_listing(
                context,
                parent_id=folder_id,
                page_size=1000,
            )["items"]
            if not children:
                empty_folders.append(prefix.rstrip("/") + "/")
                continue
            child_names: set[str] = set()
            for child in children:
                node_count += 1
                if node_count > max_nodes:
                    raise ChaoxingAPIError(
                        f"cloud-disk download exceeds the safety limit of {max_nodes} nodes"
                    )
                segment = self._cloud_disk_archive_segment(
                    str(child["name"]), f"item-{child['resource_id']}"
                )
                if segment.lower() in child_names:
                    segment = f"{segment}-{child['resource_id']}"
                child_names.add(segment.lower())
                archive_path = f"{prefix.rstrip('/')}/{segment}"
                if child["is_file"]:
                    files.append((child, archive_path))
                else:
                    queue.append((child, archive_path))
        return files, empty_folders

    def download_cloud_disk_items(
        self,
        resources: list[str],
        output_path: str | Path,
        *,
        overwrite: bool = False,
    ) -> dict[str, Any]:
        if not resources:
            raise ChaoxingAPIError("at least one cloud-disk item is required")
        context = self._cloud_disk_context()
        selected: list[dict[str, Any]] = []
        for query in resources:
            item = self._resolve_active_cloud_disk_item(context, query)
            if all(existing["resource_id"] != item["resource_id"] for existing in selected):
                selected.append(item)
        if len(selected) == 1 and selected[0]["is_file"]:
            item = selected[0]
            response, content_type = self._cloud_disk_file_response(context, item)
            server_name = content_disposition_filename(
                str(response.headers.get("Content-Disposition") or "")
            )
            target = self._resource_download_target(
                output_path,
                suggested_name=server_name or str(item["name"]),
                overwrite=overwrite,
            )
            temporary = target.with_name(target.name + ".part")
            if temporary.exists():
                raise ChaoxingAPIError(f"temporary download target already exists: {temporary}")
            size = 0
            try:
                with temporary.open("wb") as stream:
                    for chunk in response.iter_content(chunk_size=1024 * 256):
                        if chunk:
                            stream.write(chunk)
                            size += len(chunk)
                temporary.replace(target)
            except OSError as exc:
                temporary.unlink(missing_ok=True)
                raise ChaoxingAPIError(f"could not save cloud-disk download: {exc}") from exc
            return {
                "items": [self._public_cloud_disk_item(item)],
                "output_path": str(target),
                "file_name": target.name,
                "file_count": 1,
                "byte_count": size,
                "content_type": content_type,
                "archive": False,
                "verification": "saved one authenticated cloud-disk file through HTTP",
            }
        files, empty_folders = self._cloud_disk_archive_entries(context, selected)
        suggested_name = (
            self._cloud_disk_archive_segment(
                str(selected[0]["name"]), f"cloud-disk-{selected[0]['resource_id']}"
            )
            + ".zip"
            if len(selected) == 1
            else "cloud-disk-download.zip"
        )
        target = self._resource_download_target(
            output_path,
            suggested_name=suggested_name,
            overwrite=overwrite,
        )
        temporary = target.with_name(target.name + ".part")
        if temporary.exists():
            raise ChaoxingAPIError(f"temporary download target already exists: {temporary}")
        downloaded_bytes = 0
        try:
            with zipfile.ZipFile(
                temporary,
                mode="w",
                compression=zipfile.ZIP_DEFLATED,
                allowZip64=True,
            ) as archive:
                for folder_path in empty_folders:
                    archive.writestr(folder_path, b"")
                for item, archive_path in files:
                    response, _content_type = self._cloud_disk_file_response(context, item)
                    with archive.open(archive_path, mode="w", force_zip64=True) as output:
                        for chunk in response.iter_content(chunk_size=1024 * 256):
                            if chunk:
                                output.write(chunk)
                                downloaded_bytes += len(chunk)
            temporary.replace(target)
        except ChaoxingAPIError:
            temporary.unlink(missing_ok=True)
            raise
        except (OSError, zipfile.BadZipFile) as exc:
            temporary.unlink(missing_ok=True)
            raise ChaoxingAPIError(f"could not save cloud-disk archive: {exc}") from exc
        return {
            "items": [self._public_cloud_disk_item(item) for item in selected],
            "output_path": str(target),
            "file_name": target.name,
            "file_count": len(files),
            "empty_folder_count": len(empty_folders),
            "source_byte_count": downloaded_bytes,
            "byte_count": target.stat().st_size,
            "content_type": "application/zip",
            "archive": True,
            "verification": (
                f"downloaded {len(files)} cloud-disk files individually through HTTP "
                "and assembled a local ZIP without the Chaoxing client"
            ),
        }

    def _find_active_cloud_disk_item_by_object_id(
        self,
        session: requests.Session,
        *,
        object_id: str,
        name: str,
    ) -> dict[str, Any] | None:
        context = self._cloud_disk_context(session)
        items = self._cloud_disk_listing(
            context,
            parent_id=context["root_id"],
            search=name,
            page_size=1000,
        )["items"]
        matches = [item for item in items if str(item["object_id"]) == object_id]
        if not matches:
            return None
        selected = max(
            matches,
            key=lambda item: (
                int(item["upload_time"] or 0) if str(item["upload_time"] or "").isdigit() else 0,
                int(item["resource_id"]) if str(item["resource_id"]).isdigit() else 0,
            ),
        )
        return self._public_cloud_disk_item(selected)

    def delete_cloud_disk_items(self, resources: list[str]) -> dict[str, Any]:
        if not resources:
            raise ChaoxingAPIError("at least one cloud-disk item is required")
        context = self._cloud_disk_context()
        selected: list[dict[str, Any]] = []
        for query in resources:
            item = self._resolve_active_cloud_disk_item(context, query)
            if all(existing["resource_id"] != item["resource_id"] for existing in selected):
                selected.append(item)
        if any(item["owner_puid"] != context["current_puid"] for item in selected):
            raise ChaoxingAPIError("shared cloud-disk items cannot be deleted as owned items")
        if any(not item["_encrypted_id"] for item in selected):
            raise ChaoxingAPIError("a selected cloud-disk item exposed no deletion identifier")
        session = context["session"]
        try:
            response = session.post(
                CLOUD_DISK_BASE_URL + "/opt/delres",
                data={
                    "resids": ",".join(item["resource_id"] for item in selected),
                    "resourcetype": ",".join("0" for _ in selected),
                    "puids": ",".join(item["owner_puid"] for item in selected),
                    "encryptedids": ",".join(item["_encrypted_id"] for item in selected),
                },
                timeout=self.timeout,
                headers={
                    "Referer": context["root_url"],
                    "p-auth-token": context["auth_header"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
            payload = self._cloud_disk_json(response, "cloud-disk deletion")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"cloud-disk deletion failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("success"):
            raise ChaoxingAPIError(
                str(payload.get("msg") if isinstance(payload, dict) else "")
                or "Chaoxing rejected cloud-disk deletion"
            )
        for item in selected:
            active = self._cloud_disk_listing(
                context,
                parent_id=context["root_id"],
                search=str(item["name"]),
                page_size=1000,
            )["items"]
            if any(candidate["resource_id"] == item["resource_id"] for candidate in active):
                raise ChaoxingAPIError(
                    f"cloud-disk item {item['resource_id']} remained in the active list"
                )
        return {
            "deleted": [self._public_cloud_disk_item(item) for item in selected],
            "count": len(selected),
            "verification": "every deleted item is absent from fresh active cloud-disk searches",
        }

    def _cloud_disk_recycle_listing(
        self,
        context: dict[str, Any],
        *,
        page: int = 1,
        page_size: int = 100,
    ) -> dict[str, Any]:
        if page < 1 or page_size < 1 or page_size > 1000:
            raise ChaoxingAPIError("page must be positive and page_size must be 1-1000")
        try:
            response = context["session"].post(
                CLOUD_DISK_BASE_URL + "/recycle",
                params={"page": str(page), "size": str(page_size)},
                timeout=self.timeout,
                headers={
                    "Referer": CLOUD_DISK_BASE_URL + "/pcuserpan/recycle",
                    "p-auth-token": context["auth_header"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
            payload = self._cloud_disk_json(response, "cloud-disk recycle list")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"cloud-disk recycle list failed: {exc}") from exc
        raw_items = payload.get("data") if isinstance(payload, dict) else None
        if not isinstance(raw_items, list):
            raise ChaoxingAPIError("cloud-disk recycle list returned an unexpected response")
        items: list[dict[str, Any]] = []
        for index, raw in enumerate(raw_items, 1):
            if not isinstance(raw, dict):
                continue
            item = self._normalize_cloud_disk_item(raw, index)
            if not item["resource_id"]:
                continue
            item["deleted_time"] = (
                raw.get("deleteDate")
                or raw.get("deleteTime")
                or raw.get("modifyDate")
                or raw.get("uploadDate")
            )
            item["expires_time"] = (
                raw.get("validDate") or raw.get("validTime") or raw.get("validtimestr")
            )
            items.append(item)
        return {
            "page": page,
            "page_size": page_size,
            "total_count": int(payload.get("totalCount") or len(items)),
            "items": items,
        }

    def _all_cloud_disk_recycle_items(
        self,
        context: dict[str, Any],
        *,
        max_items: int = 5000,
    ) -> list[dict[str, Any]]:
        first = self._cloud_disk_recycle_listing(context, page=1, page_size=1000)
        items = list(first["items"])
        total_count = int(first["total_count"])
        total_pages = max(1, (total_count + 999) // 1000)
        for page in range(2, total_pages + 1):
            items.extend(
                self._cloud_disk_recycle_listing(context, page=page, page_size=1000)["items"]
            )
            if len(items) > max_items:
                raise ChaoxingAPIError(
                    f"cloud-disk recycle list exceeds the safety limit of {max_items} items"
                )
        for index, item in enumerate(items, 1):
            item["index"] = index
        return items

    def list_cloud_disk_recycle_items(
        self,
        *,
        page: int = 1,
        page_size: int = 100,
    ) -> dict[str, Any]:
        context = self._cloud_disk_context()
        listing = self._cloud_disk_recycle_listing(
            context,
            page=page,
            page_size=page_size,
        )
        return {
            **{key: value for key, value in listing.items() if key != "items"},
            "count": len(listing["items"]),
            "items": [self._public_cloud_disk_item(item) for item in listing["items"]],
            "verification": (
                f"read {len(listing['items'])} personal cloud-disk recycle items through HTTP"
            ),
        }

    @staticmethod
    def _resolve_cloud_disk_recycle_item(
        items: list[dict[str, Any]],
        query: str,
    ) -> dict[str, Any]:
        return _resolve_titled_item(
            items,
            query,
            id_key="resource_id",
            label="cloud-disk recycle item",
        )

    def restore_cloud_disk_recycle_items(
        self,
        resources: list[str],
        *,
        conflict_policy: str = "keep_both",
    ) -> dict[str, Any]:
        if not resources:
            raise ChaoxingAPIError("at least one cloud-disk recycle item is required")
        if len(resources) > 100:
            raise ChaoxingAPIError("no more than 100 cloud-disk items may be restored at once")
        normalized_policy = str(conflict_policy or "").strip().lower().replace("-", "_")
        policy_map = {
            "keep_both": "1",
            "keep": "1",
            "保留两个": "1",
            "replace": "2",
            "overwrite": "2",
            "替换": "2",
        }
        if normalized_policy not in policy_map:
            raise ChaoxingAPIError("conflict_policy must be keep_both or replace")
        context = self._cloud_disk_context()
        before = self._all_cloud_disk_recycle_items(context)
        selected: list[dict[str, Any]] = []
        for query in resources:
            item = self._resolve_cloud_disk_recycle_item(before, query)
            if all(existing["resource_id"] != item["resource_id"] for existing in selected):
                selected.append(item)
        selected_ids = [str(item["resource_id"]) for item in selected]
        try:
            response = context["session"].post(
                CLOUD_DISK_BASE_URL + "/recycle/recover",
                data={"resids": ",".join(selected_ids), "t": "0"},
                timeout=self.timeout,
                headers={
                    "Referer": CLOUD_DISK_BASE_URL + "/pcuserpan/recycle",
                    "p-auth-token": context["auth_header"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
            payload = self._cloud_disk_json(response, "cloud-disk recycle restore")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"cloud-disk recycle restore failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("result"):
            raise ChaoxingAPIError(
                str(payload.get("msg") if isinstance(payload, dict) else "")
                or "Chaoxing rejected cloud-disk recycle restore"
            )
        results = payload.get("data")
        if not isinstance(results, list):
            results = []
        conflicts = [
            result
            for result in results
            if isinstance(result, dict) and str(result.get("code") or "") == "-2"
        ]
        failed = [
            result
            for result in results
            if isinstance(result, dict)
            and not result.get("success")
            and str(result.get("code") or "") not in {"-2"}
        ]
        if failed:
            messages = ", ".join(str(item.get("msg") or item.get("code")) for item in failed)
            raise ChaoxingAPIError(
                "cloud-disk restore partially failed after the server processed it: " + messages
            )
        if conflicts:
            conflict_ids = [str(item.get("resid") or "") for item in conflicts]
            conflict_ids = [item_id for item_id in conflict_ids if item_id]
            try:
                response = context["session"].post(
                    CLOUD_DISK_BASE_URL + "/recycle/recover",
                    data={
                        "resids": ",".join(conflict_ids),
                        "t": policy_map[normalized_policy],
                    },
                    timeout=self.timeout,
                    headers={
                        "Referer": CLOUD_DISK_BASE_URL + "/pcuserpan/recycle",
                        "p-auth-token": context["auth_header"],
                        "X-Requested-With": "XMLHttpRequest",
                    },
                )
                response.raise_for_status()
                conflict_payload = self._cloud_disk_json(
                    response, "cloud-disk recycle conflict resolution"
                )
            except requests.RequestException as exc:
                raise ChaoxingAPIError(
                    f"cloud-disk recycle conflict resolution failed: {exc}"
                ) from exc
            if isinstance(conflict_payload, dict) and (
                conflict_payload.get("result") is False or conflict_payload.get("success") is False
            ):
                raise ChaoxingAPIError(
                    str(conflict_payload.get("msg") or "Chaoxing rejected restore conflicts")
                )
        remaining = self._all_cloud_disk_recycle_items(context)
        remaining_ids = {str(item["resource_id"]) for item in remaining}
        not_restored = [item_id for item_id in selected_ids if item_id in remaining_ids]
        if not_restored:
            raise ChaoxingAPIError(
                "server accepted cloud-disk restore, but these recycle IDs remain: "
                + ", ".join(not_restored)
            )
        active: list[dict[str, Any]] = []
        for item in selected:
            candidates = self._cloud_disk_listing(
                context,
                parent_id=context["root_id"],
                search=str(item["name"]),
                page_size=1000,
            )["items"]
            active.extend(
                self._public_cloud_disk_item(candidate)
                for candidate in candidates
                if str(candidate["name"]).lower() == str(item["name"]).lower()
            )
        return {
            "restored": [self._public_cloud_disk_item(item) for item in selected],
            "active_matches": active,
            "conflict_policy": normalized_policy,
            "conflict_count": len(conflicts),
            "verification": (
                "every selected ID is absent from the recycle bin after restore, and active "
                "items with matching names were queried"
            ),
        }

    def permanently_delete_cloud_disk_recycle_items(
        self,
        resources: list[str],
    ) -> dict[str, Any]:
        if not resources:
            raise ChaoxingAPIError("at least one cloud-disk recycle item is required")
        if len(resources) > 100:
            raise ChaoxingAPIError(
                "no more than 100 cloud-disk recycle items may be permanently deleted at once"
            )
        context = self._cloud_disk_context()
        before = self._all_cloud_disk_recycle_items(context)
        selected: list[dict[str, Any]] = []
        for query in resources:
            item = self._resolve_cloud_disk_recycle_item(before, query)
            if all(existing["resource_id"] != item["resource_id"] for existing in selected):
                selected.append(item)
        selected_ids = [str(item["resource_id"]) for item in selected]
        try:
            response = context["session"].post(
                CLOUD_DISK_BASE_URL + "/recycle/delres",
                data={"resids": ",".join(selected_ids)},
                timeout=self.timeout,
                headers={
                    "Referer": CLOUD_DISK_BASE_URL + "/pcuserpan/recycle",
                    "p-auth-token": context["auth_header"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
            payload = self._cloud_disk_json(response, "cloud-disk permanent deletion")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"cloud-disk permanent deletion failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("success"):
            raise ChaoxingAPIError(
                str(payload.get("msg") if isinstance(payload, dict) else "")
                or "Chaoxing rejected cloud-disk permanent deletion"
            )
        remaining_ids = {
            str(item["resource_id"]) for item in self._all_cloud_disk_recycle_items(context)
        }
        present = [item_id for item_id in selected_ids if item_id in remaining_ids]
        if present:
            raise ChaoxingAPIError(
                "server accepted permanent deletion, but these recycle IDs remain: "
                + ", ".join(present)
            )
        return {
            "permanently_deleted": [self._public_cloud_disk_item(item) for item in selected],
            "count": len(selected),
            "verification": "every permanently deleted ID is absent from the recycle bin",
        }

    def empty_cloud_disk_recycle(self) -> dict[str, Any]:
        context = self._cloud_disk_context()
        before = self._cloud_disk_recycle_listing(context, page=1, page_size=1)
        try:
            response = context["session"].post(
                CLOUD_DISK_BASE_URL + "/recycle/empty",
                timeout=self.timeout,
                headers={
                    "Referer": CLOUD_DISK_BASE_URL + "/pcuserpan/recycle",
                    "p-auth-token": context["auth_header"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
            payload = self._cloud_disk_json(response, "cloud-disk recycle empty")
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"cloud-disk recycle empty failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("success"):
            raise ChaoxingAPIError(
                str(payload.get("msg") if isinstance(payload, dict) else "")
                or "Chaoxing rejected emptying the cloud-disk recycle bin"
            )
        after = self._cloud_disk_recycle_listing(context, page=1, page_size=1)
        if int(after["total_count"]) != 0:
            raise ChaoxingAPIError("server accepted recycle empty, but items still remain")
        return {
            "previous_count": int(before["total_count"]),
            "remaining_count": 0,
            "verification": "emptied the cloud-disk recycle bin and confirmed total_count=0",
        }

    def list_homeworks(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        only_ungraded: bool = False,
    ) -> dict[str, Any]:
        session = self._session()
        context = self._course_context(session, course, clazz)
        module = resolve_module(context["modules"], "作业")
        base_url = self._module_url(context, module, course, clazz)

        all_items: list[dict[str, Any]] = []
        total_pages = 1
        final_url = ""
        page = 1
        while page <= total_pages:
            page_url = append_query_params(
                base_url,
                {"pages": str(page), "pageSize": "12", "status": "-1"},
            )
            try:
                response = session.get(
                    page_url,
                    timeout=self.timeout,
                    allow_redirects=True,
                    headers={"Referer": str(context["final_url"])},
                )
                response.raise_for_status()
            except requests.RequestException as exc:
                raise ChaoxingAPIError(f"homework list request failed: {exc}") from exc
            if "passport2.chaoxing.com/login" in response.url.lower():
                raise ChaoxingAPIError(
                    f"homework list request was redirected to login: {response.url}"
                )
            html = self._decode(response)
            if page == 1:
                hidden = parse_hidden_inputs(html)
                try:
                    total_pages = max(1, int(hidden.get("pageNum") or "1"))
                except ValueError:
                    total_pages = 1
            all_items.extend(parse_homework_items(html, response.url, clazz))
            final_url = response.url
            page += 1

        for index, item in enumerate(all_items, 1):
            item["index"] = index
        all_count = len(all_items)
        pending_submission_count = sum(int(item.get("pending_count") or 0) for item in all_items)
        if only_ungraded:
            all_items = [item for item in all_items if int(item.get("pending_count") or 0) > 0]
            for index, item in enumerate(all_items, 1):
                item["index"] = index

        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "only_ungraded": only_ungraded,
            "total_homework_count": all_count,
            "pending_submission_count": pending_submission_count,
            "count": len(all_items),
            "homeworks": all_items,
            "final_url": final_url,
            "verification": (
                f"parsed {all_count} homework records across {total_pages} HTTP page(s)"
            ),
        }

    def list_homework_library(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        directory_id: str = "0",
        search: str = "",
    ) -> dict[str, Any]:
        directory_id = str(directory_id or "0").strip()
        search = search.strip()
        session = self._session()
        endpoint = MOOC2_BASE_URL + "/mooc2-ans/work/library"
        items: list[dict[str, Any]] = []
        total_pages = 1
        server_total: int | None = None
        page_size = 12
        page = 1
        while page <= total_pages:
            params = {
                "courseid": course["course_id"],
                "clazzid": clazz["clazz_id"],
                "directoryid": directory_id,
                "cpi": course["cpi"],
                "search": search,
                "topicid": "0",
                "from": "",
            }
            if page > 1:
                params.update(
                    {
                        "status": "0",
                        "isfirst": "false",
                        "pages": str(page),
                        "size": str(page_size),
                    }
                )
            try:
                response = session.get(
                    endpoint,
                    params=params,
                    timeout=self.timeout,
                    allow_redirects=True,
                )
                response.raise_for_status()
            except requests.RequestException as exc:
                raise ChaoxingAPIError(f"homework-library request failed: {exc}") from exc
            if "passport2.chaoxing.com/login" in response.url.lower():
                raise ChaoxingAPIError(
                    f"homework-library request was redirected to login: {response.url}"
                )
            html = self._decode(response)
            if page == 1:
                hidden = parse_hidden_inputs(html)
                try:
                    total_pages = max(1, int(hidden.get("totalPage") or "1"))
                except ValueError:
                    total_pages = 1
                try:
                    page_size = max(1, int(hidden.get("pageSize") or "12"))
                except ValueError:
                    page_size = 12
                total_match = re.search(r"共\s*(\d+)\s*份", html_text(html))
                server_total = int(total_match.group(1)) if total_match else None
            items.extend(parse_homework_library_items(html))
            page += 1

        unique: dict[tuple[str, str], dict[str, Any]] = {}
        for item in items:
            unique[(str(item["item_id"]), str(item["item_type"]))] = item
        items = list(unique.values())
        if search:
            normalized = search.lower()
            items = [item for item in items if normalized in str(item["title"]).lower()]
        for index, item in enumerate(items, 1):
            item["index"] = index
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "directory_id": directory_id,
            "search": search,
            "server_total": server_total,
            "count": len(items),
            "folder_count": sum(1 for item in items if item["is_folder"]),
            "homework_count": sum(1 for item in items if not item["is_folder"]),
            "items": items,
            "verification": (
                f"parsed {len(items)} homework-library items across {total_pages} HTTP page(s)"
            ),
        }

    def list_homework_drafts(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        search: str = "",
    ) -> dict[str, Any]:
        search = search.strip()
        session = self._session()
        endpoint = MOOC2_BASE_URL + "/mooc2-ans/work/library/drafts"
        drafts: list[dict[str, Any]] = []
        total_pages = 1
        server_total: int | None = None
        page = 1
        while page <= total_pages:
            params = {
                "courseid": course["course_id"],
                "clazzid": clazz["clazz_id"],
                "cpi": course["cpi"],
                "from": "",
            }
            if page > 1:
                params.update({"isfirst": "false", "pages": str(page)})
            try:
                response = session.get(
                    endpoint,
                    params=params,
                    timeout=self.timeout,
                    allow_redirects=True,
                )
                response.raise_for_status()
            except requests.RequestException as exc:
                raise ChaoxingAPIError(f"homework-draft request failed: {exc}") from exc
            if "passport2.chaoxing.com/login" in response.url.lower():
                raise ChaoxingAPIError(
                    f"homework-draft request was redirected to login: {response.url}"
                )
            html = self._decode(response)
            if page == 1:
                page_match = re.search(
                    r"pageNum\s*:\s*parseInt\(['\"](\d+)['\"]\)",
                    html,
                    flags=re.IGNORECASE,
                )
                total_pages = max(1, int(page_match.group(1))) if page_match else 1
                total_match = re.search(r"共\s*(\d+)\s*份", html_text(html))
                server_total = int(total_match.group(1)) if total_match else None
            drafts.extend(parse_homework_drafts(html))
            page += 1

        unique = {str(draft["work_id"]): draft for draft in drafts}
        drafts = list(unique.values())
        if search:
            normalized = search.lower()
            drafts = [draft for draft in drafts if normalized in str(draft["title"]).lower()]
        for index, draft in enumerate(drafts, 1):
            draft["index"] = index
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "search": search,
            "server_total": server_total,
            "count": len(drafts),
            "drafts": drafts,
            "verification": (
                f"parsed {len(drafts)} homework drafts across {total_pages} HTTP page(s)"
            ),
        }

    @staticmethod
    def _validate_homework_title(title: str) -> str:
        title = title.strip()
        if not title:
            raise ChaoxingAPIError("homework title is required")
        if len(title) > 50:
            raise ChaoxingAPIError("homework title cannot exceed 50 characters")
        if any(ord(character) > 0xFFFF for character in title):
            raise ChaoxingAPIError("homework title contains an unsupported character")
        return title

    def _homework_editor_context(
        self,
        session: requests.Session,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        work_id: str = "",
        directory_id: str = "0",
    ) -> dict[str, Any]:
        try:
            response = session.get(
                MOOC2_BASE_URL + "/mooc2-ans/work/goToWorkEditor",
                params={
                    "courseid": course["course_id"],
                    "clazzid": clazz["clazz_id"],
                    "cpi": course["cpi"],
                    "directoryid": directory_id,
                    "mooc": "1",
                    "workid": work_id,
                    "built": "1",
                    "from": "",
                },
                timeout=self.timeout,
                allow_redirects=True,
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"homework editor request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError(
                f"homework editor request was redirected to login: {response.url}"
            )
        html = self._decode(response)
        hidden = parse_hidden_inputs(html)
        if hidden.get("courseid") != str(course["course_id"]):
            raise ChaoxingAPIError("homework editor did not return the selected course context")
        return {
            "hidden": hidden,
            "referer": response.url,
            "html": html,
            "outline": parse_homework_editor_outline(html),
            "form_controls": _html_form_controls(_form_fragment(html, "workForm")),
        }

    def _save_homework_draft_request(
        self,
        session: requests.Session,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        title: str,
        work_id: str,
        directory_id: str,
        hidden: dict[str, str],
        referer: str,
    ) -> dict[str, Any]:
        try:
            response = session.get(
                MOOC2_BASE_URL + "/mooc2-ans/work/save-work",
                params={
                    "courseid": course["course_id"],
                    "clazzid": clazz["clazz_id"],
                    "cpi": course["cpi"],
                    "workid": work_id,
                    "title": title,
                    "grading": hidden.get("grading", "0"),
                    "directoryid": hidden.get("directoryid", directory_id) or directory_id,
                    "workStatus": "-1",
                    "questionGroup": hidden.get("questionGroup", "0"),
                },
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"homework draft save failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "homework draft save was not acknowledged"))
        return payload

    def create_homework_draft(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        title: str,
        *,
        directory: str = "0",
    ) -> dict[str, Any]:
        title = self._validate_homework_title(title)
        directory_id = str(directory or "0").strip()
        if directory_id != "0" and not directory_id.isdigit():
            library = self.list_homework_library(course, clazz)
            folder = resolve_homework_library_item(library["items"], directory_id)
            if not folder["is_folder"]:
                raise ChaoxingAPIError(f"homework-library item is not a folder: {directory}")
            directory_id = str(folder["item_id"])
        before = self.list_homework_drafts(course, clazz)
        before_ids = {str(draft["work_id"]) for draft in before["drafts"]}
        session = self._session()
        editor = self._homework_editor_context(
            session,
            course,
            clazz,
            directory_id=directory_id,
        )
        payload = self._save_homework_draft_request(
            session,
            course,
            clazz,
            title=title,
            work_id="",
            directory_id=directory_id,
            hidden=editor["hidden"],
            referer=editor["referer"],
        )
        after = self.list_homework_drafts(course, clazz)
        created = [
            draft
            for draft in after["drafts"]
            if str(draft["work_id"]) not in before_ids and draft["title"] == title
        ]
        if len(created) != 1:
            raise ChaoxingAPIError(
                "server acknowledged homework draft creation, but one new matching draft "
                "could not be verified"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "directory_id": directory_id,
            "draft": created[0],
            "server_message": str(payload.get("msg") or ""),
            "verification": "one new draft with the requested title appeared in a fresh HTTP read",
        }

    def update_homework_draft(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        draft_query: str,
        title: str,
    ) -> dict[str, Any]:
        title = self._validate_homework_title(title)
        before = self.list_homework_drafts(course, clazz)
        draft = resolve_homework_draft(before["drafts"], draft_query)
        session = self._session()
        editor = self._homework_editor_context(
            session,
            course,
            clazz,
            work_id=str(draft["work_id"]),
        )
        payload = self._save_homework_draft_request(
            session,
            course,
            clazz,
            title=title,
            work_id=str(draft["work_id"]),
            directory_id=str(editor["hidden"].get("directoryid") or "0"),
            hidden=editor["hidden"],
            referer=editor["referer"],
        )
        after = self.list_homework_drafts(course, clazz)
        updated = resolve_homework_draft(after["drafts"], str(draft["work_id"]))
        if updated["title"] != title:
            raise ChaoxingAPIError(
                "server acknowledged homework draft update, but the refreshed title differs"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "before": draft,
            "after": updated,
            "server_message": str(payload.get("msg") or ""),
            "verification": "the selected draft now has the requested title in a fresh HTTP read",
        }

    def delete_homework_draft(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        draft_query: str,
    ) -> dict[str, Any]:
        before = self.list_homework_drafts(course, clazz)
        draft = resolve_homework_draft(before["drafts"], draft_query)
        session = self._session()
        try:
            response = session.get(
                MOOC2_BASE_URL + "/mooc2-ans/work/library/work-update",
                params={
                    "courseid": course["course_id"],
                    "workid": draft["work_id"],
                    "cpi": course["cpi"],
                    "status": "1",
                },
                timeout=self.timeout,
                headers={"Referer": draft["edit_url"], "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"homework draft deletion failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "homework draft deletion was not acknowledged"))
        after = self.list_homework_drafts(course, clazz)
        if any(str(item["work_id"]) == str(draft["work_id"]) for item in after["drafts"]):
            raise ChaoxingAPIError(
                "server acknowledged homework draft deletion, but the draft is still listed"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "deleted": draft,
            "server_message": str(payload.get("msg") or ""),
            "verification": "the deleted draft is absent from a fresh HTTP draft listing",
        }

    def _resolve_editable_homework(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        query: str,
    ) -> dict[str, Any]:
        library = self.list_homework_library(course, clazz)
        drafts = self.list_homework_drafts(course, clazz)
        return resolve_homework_editor_target(library["items"], drafts["drafts"], query)

    def _homework_question_detail_html(
        self,
        session: requests.Session,
        course: dict[str, Any],
        clazz: dict[str, Any],
        question: dict[str, Any],
        *,
        grading: str = "0",
        referer: str = "",
        new_create: bool = False,
    ) -> str:
        params = {
            "courseid": course["course_id"],
            "clazzid": clazz["clazz_id"],
            "cpi": course["cpi"],
            "questionid": question["question_id"],
            "type": question["question_type_code"],
            "grading": grading,
            "courseQuestionTypeId": question.get("course_question_type_id", "0"),
        }
        if new_create:
            params["newCreate"] = "1"
        try:
            response = session.get(
                MOOC2_BASE_URL + "/mooc2-ans/work/viewLibraryRelationQuestionDetail",
                params=params,
                timeout=self.timeout,
                headers={"Referer": referer} if referer else None,
                allow_redirects=True,
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"homework question detail request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError(
                f"homework question detail request was redirected to login: {response.url}"
            )
        html = self._decode(response)
        if not _control_values(_html_form_controls(html), "content"):
            raise ChaoxingAPIError("homework question detail did not expose an editable stem")
        return html

    def _read_homework_question_from_editor(
        self,
        session: requests.Session,
        course: dict[str, Any],
        clazz: dict[str, Any],
        work_id: str,
        question_query: str,
    ) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
        editor = self._homework_editor_context(
            session,
            course,
            clazz,
            work_id=work_id,
        )
        metadata = resolve_homework_question(editor["outline"]["questions"], question_query)
        detail_html = self._homework_question_detail_html(
            session,
            course,
            clazz,
            metadata,
            grading=str(editor["hidden"].get("grading") or "0"),
            referer=editor["referer"],
        )
        detail = parse_homework_question_detail(
            detail_html,
            question_id=str(metadata["question_id"]),
            question_type_code=str(metadata["question_type_code"]),
            relation_id=str(metadata["relation_id"]),
            index=int(metadata["index"]),
        )
        detail["course_question_type_id"] = metadata.get("course_question_type_id", "")
        detail["preview"] = metadata.get("preview", "")
        return editor, metadata, detail

    def read_homework_library_item(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        homework_query: str,
        *,
        question: str = "",
    ) -> dict[str, Any]:
        target = self._resolve_editable_homework(course, clazz, homework_query)
        session = self._session()
        editor = self._homework_editor_context(
            session,
            course,
            clazz,
            work_id=str(target["work_id"]),
        )
        outline = editor["outline"]
        metadata_rows = list(outline["questions"])
        selected_metadata: list[dict[str, Any]] = metadata_rows
        if question:
            try:
                selected_metadata = [resolve_homework_question(metadata_rows, question)]
            except ChaoxingAPIError:
                selected_metadata = metadata_rows

        details: list[dict[str, Any]] = []
        for metadata in selected_metadata:
            detail_html = self._homework_question_detail_html(
                session,
                course,
                clazz,
                metadata,
                grading=str(editor["hidden"].get("grading") or "0"),
                referer=editor["referer"],
            )
            detail = parse_homework_question_detail(
                detail_html,
                question_id=str(metadata["question_id"]),
                question_type_code=str(metadata["question_type_code"]),
                relation_id=str(metadata["relation_id"]),
                index=int(metadata["index"]),
            )
            detail["course_question_type_id"] = metadata.get("course_question_type_id", "")
            detail["preview"] = metadata.get("preview", "")
            details.append(detail)
        if question:
            details = [resolve_homework_question(details, question)]
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "homework": {
                "work_id": target["work_id"],
                "title": outline.get("title") or target.get("title", ""),
                "source": target["source"],
                "directory_id": outline.get("directory_id", ""),
                "work_used": outline.get("work_used", False),
            },
            "question_query": question,
            "question_count": outline["question_count"],
            "returned_question_count": len(details),
            "groups": outline["groups"],
            "questions": details,
            "verification": (
                f"parsed the editor outline and {len(details)} authenticated question-detail "
                "HTTP response(s)"
            ),
        }

    @staticmethod
    def _question_rich_text(
        value: str,
        content_format: str,
        label: str,
        *,
        allow_empty: bool = False,
    ) -> str:
        value = str(value or "").strip()
        normalized_format = str(content_format or "plain").strip().lower()
        if normalized_format not in {"plain", "html"}:
            raise ChaoxingAPIError("content_format must be plain or html")
        if not value:
            if allow_empty:
                return ""
            raise ChaoxingAPIError(f"{label} cannot be empty")
        if normalized_format == "html":
            if not html_text(value) and not parse_content_images(value):
                raise ChaoxingAPIError(f"{label} HTML has no visible content")
            return value
        lines = value.replace("\r\n", "\n").replace("\r", "\n").split("\n")
        return "".join(f"<p>{escape(line) if line else '<br>'}</p>" for line in lines)

    @staticmethod
    def _question_score(value: Any) -> int | float:
        try:
            number = float(value)
        except (TypeError, ValueError) as exc:
            raise ChaoxingAPIError("question score must be numeric") from exc
        if not 0 < number <= 1000:
            raise ChaoxingAPIError("question score must be greater than 0 and at most 1000")
        return int(number) if number.is_integer() else number

    @staticmethod
    def _question_difficulty(value: Any) -> float:
        try:
            number = float(value)
        except (TypeError, ValueError) as exc:
            raise ChaoxingAPIError("question difficulty must be numeric") from exc
        if not 0.1 <= number <= 1.0:
            raise ChaoxingAPIError("question difficulty must be between 0.1 and 1.0")
        if abs(number * 10 - round(number * 10)) > 1e-9:
            raise ChaoxingAPIError("question difficulty must use increments of 0.1")
        return number

    @staticmethod
    def _question_boolean_answer(value: Any) -> bool:
        if isinstance(value, bool):
            return value
        normalized = str(value or "").strip().lower()
        if normalized in {"true", "t", "1", "yes", "正确", "对", "是"}:
            return True
        if normalized in {"false", "f", "0", "no", "错误", "错", "否"}:
            return False
        raise ChaoxingAPIError("true/false answer must be true/false, 对/错, or 正确/错误")

    @staticmethod
    def _question_choice_options(options: Any) -> dict[str, str]:
        if isinstance(options, dict):
            normalized = {
                str(label).strip().upper(): str(value or "").strip()
                for label, value in options.items()
            }
        elif isinstance(options, list):
            normalized = {
                chr(ord("A") + index): str(value or "").strip()
                for index, value in enumerate(options)
            }
        else:
            raise ChaoxingAPIError("choice options must be a JSON object or list")
        if not 2 <= len(normalized) <= 26:
            raise ChaoxingAPIError("choice questions require 2 to 26 options")
        expected = [chr(ord("A") + index) for index in range(len(normalized))]
        if list(normalized) != expected:
            raise ChaoxingAPIError("choice option labels must be contiguous from A")
        if any(not value for value in normalized.values()):
            raise ChaoxingAPIError("choice options cannot be empty")
        if len({value.casefold() for value in normalized.values()}) != len(normalized):
            raise ChaoxingAPIError("choice options cannot contain duplicate text")
        return normalized

    @staticmethod
    def _question_choice_answers(value: Any) -> list[str]:
        if isinstance(value, list):
            raw = value
        else:
            raw = re.split(r"[,，、;；\s]+", str(value or "").strip())
        answers: list[str] = []
        for item in raw:
            label = str(item or "").strip().upper()
            if label and label not in answers:
                answers.append(label)
        if not answers or any(not re.fullmatch(r"[A-Z]", item) for item in answers):
            raise ChaoxingAPIError("correct_answer must contain option labels such as A or A,C")
        return answers

    def _compose_homework_question_form(
        self,
        editor: dict[str, Any],
        detail_html: str,
        question: dict[str, Any],
        *,
        stem: str | None = None,
        score: Any = None,
        options: Any = None,
        correct_answer: Any = None,
        answers: list[str] | None = None,
        answer: Any = None,
        analysis: str | None = None,
        difficulty: Any = None,
        content_format: str = "plain",
        creating: bool = False,
    ) -> tuple[list[tuple[str, str]], dict[str, Any]]:
        base_names = {
            "queNumMaxSize",
            "courseid",
            "clazzid",
            "chapterId",
            "fromChapter",
            "workid",
            "directoryid",
            "cpi",
            "enc",
            "grading",
            "questionGroup",
            "mooc",
            "questionid",
            "workLibraryRelationid",
            "type",
            "typeName",
            "courseQuestionTypeId",
            "wrapAnswer",
            "answerForTF",
            "title",
        }
        controls = [(key, value) for key, value in editor["form_controls"] if key in base_names]
        detail_controls = _html_form_controls(detail_html)
        controls.extend((key, value) for key, value in detail_controls if key not in base_names)
        type_code = str(question["question_type_code"])
        type_info = HOMEWORK_QUESTION_TYPES[type_code]
        _set_form_control(controls, "workid", str(question["work_id"]))
        _set_form_control(controls, "questionid", str(question["question_id"]))
        _set_form_control(controls, "workLibraryRelationid", str(question["relation_id"]))
        _set_form_control(controls, "type", type_code)
        _set_form_control(controls, "typeName", type_info["label"])
        _set_form_control(
            controls,
            "courseQuestionTypeId",
            str(question.get("course_question_type_id") or type_code),
        )
        _set_form_control(controls, "updateSignal", "false")

        expected: dict[str, Any] = {"question_type": type_info["key"]}
        current = parse_homework_question_detail(
            detail_html,
            question_id=str(question["question_id"]),
            question_type_code=type_code,
            relation_id=str(question["relation_id"]),
        )
        if stem is not None:
            stem_html = self._question_rich_text(stem, content_format, "question stem")
            _set_form_control(controls, "content", stem_html)
            expected["stem"] = html_text(stem_html)
        elif creating:
            raise ChaoxingAPIError("question stem is required")

        if score is not None:
            normalized_score = self._question_score(score)
            _set_form_control(controls, "score", normalized_score)
            expected["score"] = normalized_score
        elif creating:
            _set_form_control(controls, "score", 5)
            expected["score"] = 5

        if analysis is not None:
            analysis_html = self._question_rich_text(
                analysis,
                content_format,
                "answer analysis",
                allow_empty=True,
            )
            _set_form_control(controls, "answerAnalysis", analysis_html)
            expected["answer_analysis"] = html_text(analysis_html)
        elif creating:
            _set_form_control(controls, "answerAnalysis", "")

        if difficulty is not None:
            normalized_difficulty = self._question_difficulty(difficulty)
            _set_form_control(controls, "difficulty", normalized_difficulty)
            expected["difficulty"] = normalized_difficulty
        elif creating:
            _set_form_control(controls, "difficulty", 0.8)
            expected["difficulty"] = 0.8

        if type_code in {"0", "1"}:
            if options is not None:
                normalized_options = self._question_choice_options(options)
                controls[:] = [
                    (key, value) for key, value in controls if not re.fullmatch(r"[A-Z]", key)
                ]
                converted_options: dict[str, str] = {}
                for label, value in normalized_options.items():
                    option_html = self._question_rich_text(
                        value,
                        content_format,
                        f"option {label}",
                    )
                    controls.append((label, option_html))
                    converted_options[label] = html_text(option_html)
                expected["options"] = [
                    {"label": label, "text": value} for label, value in converted_options.items()
                ]
            elif creating:
                raise ChaoxingAPIError("choice options are required")
            else:
                normalized_options = {
                    str(item["label"]): str(item["text"]) for item in current["options"]
                }
            if correct_answer is not None:
                normalized_answers = self._question_choice_answers(correct_answer)
                if any(label not in normalized_options for label in normalized_answers):
                    raise ChaoxingAPIError("correct_answer refers to a missing option")
                if type_code == "0" and len(normalized_answers) != 1:
                    raise ChaoxingAPIError("single-choice questions require exactly one answer")
                _set_form_control(controls, "defAnswer", normalized_answers)
                expected["answer"] = (
                    normalized_answers[0] if type_code == "0" else normalized_answers
                )
            elif creating:
                raise ChaoxingAPIError("correct_answer is required for a choice question")
        elif type_code == "2":
            if answers is not None:
                if not isinstance(answers, list) or not answers:
                    raise ChaoxingAPIError("fill-blank answers must be a non-empty list")
                answer_html = [
                    self._question_rich_text(
                        item,
                        content_format,
                        f"answer {index}",
                    )
                    for index, item in enumerate(answers, 1)
                ]
                controls[:] = [(key, value) for key, value in controls if not key.isdigit()]
                controls.extend((str(index), item) for index, item in enumerate(answer_html, 1))
                _set_form_control(controls, "wrapAnswer", "★".join(answer_html))
                expected["answer"] = [
                    {"blank": index, "text": html_text(item)}
                    for index, item in enumerate(answer_html, 1)
                ]
            elif creating:
                raise ChaoxingAPIError("fill-blank answers are required")
            else:
                current_answer_html = [
                    str(item.get("html") or "") for item in current.get("answer", [])
                ]
                _set_form_control(controls, "wrapAnswer", "★".join(current_answer_html))
        elif type_code == "3":
            if answer is not None:
                boolean_answer = self._question_boolean_answer(answer)
                _set_form_control(controls, "answerForTF", str(boolean_answer).lower())
                expected["answer"] = boolean_answer
            elif creating:
                raise ChaoxingAPIError("true/false answer is required")
            elif current.get("answer") is not None:
                _set_form_control(
                    controls,
                    "answerForTF",
                    str(bool(current["answer"])).lower(),
                )
        elif type_code == "4":
            if answer is not None:
                answer_html = self._question_rich_text(
                    str(answer),
                    content_format,
                    "reference answer",
                    allow_empty=True,
                )
                _set_form_control(controls, "answer", answer_html)
                expected["answer"] = html_text(answer_html)
            elif creating:
                _set_form_control(controls, "answer", "")
        return controls, expected

    @staticmethod
    def _verify_homework_question_fields(
        actual: dict[str, Any],
        expected: dict[str, Any],
    ) -> None:
        for key, expected_value in expected.items():
            actual_value = actual.get(key)
            if key == "options":
                actual_value = [
                    {"label": item["label"], "text": item["text"]}
                    for item in actual.get("options", [])
                ]
            elif key == "answer" and isinstance(expected_value, list):
                if expected_value and isinstance(expected_value[0], dict):
                    actual_value = [
                        {"blank": item["blank"], "text": item["text"]}
                        for item in actual.get("answer", [])
                    ]
            if actual_value != expected_value:
                raise ChaoxingAPIError(
                    f"homework question read-back mismatch for {key}: "
                    f"expected {expected_value!r}, got {actual_value!r}"
                )

    def _delete_homework_question_request(
        self,
        session: requests.Session,
        course: dict[str, Any],
        clazz: dict[str, Any],
        work_id: str,
        question_id: str,
        *,
        referer: str,
    ) -> dict[str, Any]:
        try:
            response = session.post(
                MOOC2_BASE_URL + "/mooc2-ans/work/deleteDataFromFukWork",
                data={
                    "courseId": course["course_id"],
                    "classId": clazz["clazz_id"],
                    "cpi": course["cpi"],
                    "workLibraryId": work_id,
                    "delParam": question_id,
                    "isWorkLibraryRelation": "false",
                    "extraParam": "",
                },
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"homework question deletion failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("success"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(
                str(message or "homework question deletion was not acknowledged")
            )
        return payload

    def add_homework_question(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        homework_query: str,
        question_type: str,
        stem: str,
        *,
        score: Any = 5,
        options: Any = None,
        correct_answer: Any = None,
        answers: list[str] | None = None,
        answer: Any = None,
        analysis: str = "",
        difficulty: Any = 0.8,
        content_format: str = "plain",
    ) -> dict[str, Any]:
        type_code = normalize_homework_question_type(question_type)
        target = self._resolve_editable_homework(course, clazz, homework_query)
        session = self._session()
        editor = self._homework_editor_context(
            session,
            course,
            clazz,
            work_id=str(target["work_id"]),
        )
        relation_id = next(
            (
                str(group["relation_id"])
                for group in editor["outline"]["groups"]
                if str(group["question_type_code"]) == type_code
            ),
            "0",
        )
        try:
            response = session.post(
                MOOC2_BASE_URL + "/mooc2-ans/work/questionInit",
                data={
                    "courseid": course["course_id"],
                    "clazzid": clazz["clazz_id"],
                    "cpi": course["cpi"],
                    "workid": target["work_id"],
                    "relationid": relation_id,
                    "title": editor["outline"].get("title") or target.get("title", ""),
                    "directoryid": editor["hidden"].get("directoryid", "0"),
                    "grading": editor["hidden"].get("grading", "0"),
                    "questionGroup": editor["hidden"].get("questionGroup", "0"),
                    "originType": type_code,
                    "courseQuestionTypeId": type_code,
                },
                timeout=self.timeout,
                headers={
                    "Referer": editor["referer"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
            init_payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"homework question initialization failed: {exc}") from exc
        if not isinstance(init_payload, dict) or not init_payload.get("status"):
            message = init_payload.get("msg") if isinstance(init_payload, dict) else ""
            raise ChaoxingAPIError(str(message or "homework question initialization failed"))
        initialized = {
            "work_id": str(init_payload.get("workid") or target["work_id"]),
            "question_id": str(init_payload.get("questionid") or ""),
            "relation_id": str(init_payload.get("relationid") or relation_id),
            "question_type_code": type_code,
            "course_question_type_id": type_code,
        }
        if not initialized["question_id"]:
            raise ChaoxingAPIError("question initialization did not return questionid")

        try:
            detail_html = self._homework_question_detail_html(
                session,
                course,
                clazz,
                initialized,
                grading=str(editor["hidden"].get("grading") or "0"),
                referer=editor["referer"],
                new_create=True,
            )
            form, expected = self._compose_homework_question_form(
                editor,
                detail_html,
                initialized,
                stem=stem,
                score=score,
                options=options,
                correct_answer=correct_answer,
                answers=answers,
                answer=answer,
                analysis=analysis,
                difficulty=difficulty,
                content_format=content_format,
                creating=True,
            )
        except Exception as exc:
            try:
                self._delete_homework_question_request(
                    session,
                    course,
                    clazz,
                    initialized["work_id"],
                    initialized["question_id"],
                    referer=editor["referer"],
                )
            except ChaoxingAPIError as rollback_exc:
                raise ChaoxingAPIError(
                    f"{exc}; initialized placeholder rollback also failed: {rollback_exc}"
                ) from exc
            raise

        try:
            save_response = session.post(
                MOOC2_BASE_URL + "/mooc2-ans/work/toEditWorkQuestion",
                data=form,
                timeout=self.timeout,
                headers={
                    "Referer": editor["referer"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            save_response.raise_for_status()
            save_payload = json.loads(self._decode(save_response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            try:
                _, _, actual = self._read_homework_question_from_editor(
                    session,
                    course,
                    clazz,
                    initialized["work_id"],
                    initialized["question_id"],
                )
                self._verify_homework_question_fields(actual, expected)
            except ChaoxingAPIError:
                self._delete_homework_question_request(
                    session,
                    course,
                    clazz,
                    initialized["work_id"],
                    initialized["question_id"],
                    referer=editor["referer"],
                )
                raise ChaoxingAPIError(f"homework question save failed: {exc}") from exc
            save_payload = {"success": True, "msg": "verified after uncertain response"}
        if not isinstance(save_payload, dict) or not save_payload.get("success"):
            message = save_payload.get("msg") if isinstance(save_payload, dict) else ""
            self._delete_homework_question_request(
                session,
                course,
                clazz,
                initialized["work_id"],
                initialized["question_id"],
                referer=editor["referer"],
            )
            raise ChaoxingAPIError(str(message or "homework question save was not acknowledged"))
        _, _, actual = self._read_homework_question_from_editor(
            session,
            course,
            clazz,
            initialized["work_id"],
            initialized["question_id"],
        )
        self._verify_homework_question_fields(actual, expected)
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "homework": {
                "work_id": initialized["work_id"],
                "title": target.get("title", ""),
                "source": target["source"],
            },
            "question": actual,
            "server_message": str(save_payload.get("msg") or ""),
            "verification": "the new question and requested fields were read back over HTTP",
        }

    def update_homework_question(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        homework_query: str,
        question_query: str,
        *,
        stem: str | None = None,
        score: Any = None,
        options: Any = None,
        correct_answer: Any = None,
        answers: list[str] | None = None,
        answer: Any = None,
        analysis: str | None = None,
        difficulty: Any = None,
        content_format: str = "plain",
    ) -> dict[str, Any]:
        if all(
            value is None
            for value in (
                stem,
                score,
                options,
                correct_answer,
                answers,
                answer,
                analysis,
                difficulty,
            )
        ):
            raise ChaoxingAPIError("at least one question field must be updated")
        target = self._resolve_editable_homework(course, clazz, homework_query)
        session = self._session()
        editor, metadata, before = self._read_homework_question_from_editor(
            session,
            course,
            clazz,
            str(target["work_id"]),
            question_query,
        )
        detail_html = self._homework_question_detail_html(
            session,
            course,
            clazz,
            metadata,
            grading=str(editor["hidden"].get("grading") or "0"),
            referer=editor["referer"],
        )
        question_context = {
            **metadata,
            "work_id": target["work_id"],
        }
        form, expected = self._compose_homework_question_form(
            editor,
            detail_html,
            question_context,
            stem=stem,
            score=score,
            options=options,
            correct_answer=correct_answer,
            answers=answers,
            answer=answer,
            analysis=analysis,
            difficulty=difficulty,
            content_format=content_format,
            creating=False,
        )
        try:
            response = session.post(
                MOOC2_BASE_URL + "/mooc2-ans/work/toEditWorkQuestion",
                data=form,
                timeout=self.timeout,
                headers={
                    "Referer": editor["referer"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"homework question update failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("success"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "homework question update was not acknowledged"))
        _, _, after = self._read_homework_question_from_editor(
            session,
            course,
            clazz,
            str(target["work_id"]),
            str(metadata["question_id"]),
        )
        self._verify_homework_question_fields(after, expected)
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "homework": {
                "work_id": target["work_id"],
                "title": target.get("title", ""),
                "source": target["source"],
            },
            "before": before,
            "after": after,
            "server_message": str(payload.get("msg") or ""),
            "verification": "the updated question fields were read back over HTTP",
        }

    def delete_homework_question(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        homework_query: str,
        question_query: str,
    ) -> dict[str, Any]:
        target = self._resolve_editable_homework(course, clazz, homework_query)
        session = self._session()
        editor, metadata, before = self._read_homework_question_from_editor(
            session,
            course,
            clazz,
            str(target["work_id"]),
            question_query,
        )
        payload = self._delete_homework_question_request(
            session,
            course,
            clazz,
            str(target["work_id"]),
            str(metadata["question_id"]),
            referer=editor["referer"],
        )
        refreshed = self._homework_editor_context(
            session,
            course,
            clazz,
            work_id=str(target["work_id"]),
        )
        if any(
            str(question["question_id"]) == str(metadata["question_id"])
            for question in refreshed["outline"]["questions"]
        ):
            raise ChaoxingAPIError(
                "server acknowledged homework question deletion, but the question is still listed"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "homework": {
                "work_id": target["work_id"],
                "title": target.get("title", ""),
                "source": target["source"],
            },
            "deleted": before,
            "server_message": str(payload.get("msg") or ""),
            "verification": "the deleted question is absent from a fresh editor outline",
        }

    def publish_homework_from_library(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        homework_query: str,
        *,
        target_classes: list[str] | None = None,
        start_time: str = "now",
        end_time: str = "",
        allow_late_submission: bool = False,
        late_deadline: str = "",
        passing_score: int | float = 0,
        redo_times: int = 0,
        allow_paste: bool = True,
        show_score: bool = True,
        show_correctness: bool = True,
        randomize_questions: bool = False,
        randomize_options: bool = False,
    ) -> dict[str, Any]:
        library = self.list_homework_library(course, clazz, search=homework_query)
        homework = resolve_homework_library_item(library["items"], homework_query)
        if homework["is_folder"]:
            raise ChaoxingAPIError(f"homework-library item is a folder: {homework_query}")
        if int(homework.get("work_type") or 0) != 0:
            raise ChaoxingAPIError("group homework publishing requires the group-work action")
        try:
            passing_score_value = float(passing_score)
        except (TypeError, ValueError) as exc:
            raise ChaoxingAPIError("passing_score must be numeric") from exc
        if not 0 <= passing_score_value <= 100:
            raise ChaoxingAPIError("passing_score must be between 0 and 100")
        if not 0 <= redo_times <= 100:
            raise ChaoxingAPIError("redo_times must be between 0 and 100")

        selected_classes: list[dict[str, Any]] = []
        for selector in target_classes or [str(clazz["clazz_id"])]:
            selected = resolve_class(course, selector)
            if selected["clazz_id"] not in {item["clazz_id"] for item in selected_classes}:
                selected_classes.append(selected)
        if not selected_classes:
            raise ChaoxingAPIError("at least one target class is required")

        session = self._session()
        setting_url = MOOC2_BASE_URL + "/mooc2-ans/work/library/setting"
        try:
            setting_response = session.get(
                setting_url,
                params={
                    "courseid": course["course_id"],
                    "cpi": course["cpi"],
                    "workLibraryId": homework["item_id"],
                    "from": "",
                },
                timeout=self.timeout,
                allow_redirects=True,
            )
            setting_response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"homework publish settings request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in setting_response.url.lower():
            raise ChaoxingAPIError(
                f"homework publish settings redirected to login: {setting_response.url}"
            )
        hidden = parse_hidden_inputs(self._decode(setting_response))
        if hidden.get("workLibraryid") != str(homework["item_id"]):
            raise ChaoxingAPIError("homework publish settings did not return the selected work")
        server_now = str(hidden.get("curDate") or "").strip()

        def normalized_datetime(value: str, label: str, *, allow_empty: bool = False) -> str:
            value = str(value or "").strip()
            if value.lower() == "now":
                value = server_now
            if not value and allow_empty:
                return ""
            if not value:
                raise ChaoxingAPIError(f"{label} is required")
            for pattern in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M"):
                try:
                    parsed = datetime.strptime(value, pattern)
                    return parsed.strftime("%Y-%m-%d %H:%M:%S")
                except ValueError:
                    continue
            raise ChaoxingAPIError(f"{label} must use YYYY-MM-DD HH:MM[:SS]")

        normalized_start = normalized_datetime(start_time, "start_time")
        normalized_end = normalized_datetime(end_time, "end_time", allow_empty=True)
        normalized_deadline = normalized_datetime(
            late_deadline,
            "late_deadline",
            allow_empty=True,
        )
        start_dt = datetime.strptime(normalized_start, "%Y-%m-%d %H:%M:%S")
        if server_now:
            server_now_dt = datetime.strptime(server_now, "%Y-%m-%d %H:%M:%S")
            if start_dt < server_now_dt:
                raise ChaoxingAPIError("start_time cannot be earlier than the server time")
        if normalized_end:
            end_dt = datetime.strptime(normalized_end, "%Y-%m-%d %H:%M:%S")
            if end_dt <= start_dt:
                raise ChaoxingAPIError("end_time must be later than start_time")
        else:
            end_dt = None
        if allow_late_submission and not normalized_end:
            raise ChaoxingAPIError("end_time is required when late submission is enabled")
        if normalized_deadline:
            if end_dt is None:
                raise ChaoxingAPIError("end_time is required when late_deadline is set")
            deadline_dt = datetime.strptime(normalized_deadline, "%Y-%m-%d %H:%M:%S")
            if deadline_dt < end_dt:
                raise ChaoxingAPIError("late_deadline cannot be earlier than end_time")

        try:
            check_response = session.get(
                MOOC2_BASE_URL + "/mooc2-ans/work/check/question",
                params={
                    "courseid": course["course_id"],
                    "clazzid": selected_classes[0]["clazz_id"],
                    "cpi": course["cpi"],
                    "workid": homework["item_id"],
                },
                timeout=self.timeout,
                headers={"Referer": setting_response.url},
            )
            check_response.raise_for_status()
            check_payload = json.loads(self._decode(check_response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"homework question validation failed: {exc}") from exc
        if not isinstance(check_payload, dict) or check_payload.get("status") != 1:
            message = check_payload.get("msg") if isinstance(check_payload, dict) else ""
            raise ChaoxingAPIError(str(message or "homework cannot be published"))

        before_ids: dict[str, set[str]] = {}
        for selected in selected_classes:
            listing = self.list_homeworks(course, selected)
            before_ids[selected["clazz_id"]] = {
                str(item["work_id"])
                for item in listing["homeworks"]
                if item["title"] == homework["title"]
            }

        publish_objects = [
            {"classid": int(selected["clazz_id"]), "publishType": 0}
            for selected in selected_classes
        ]
        form: dict[str, Any] = {
            "courseid": course["course_id"],
            "workLibraryId": homework["item_id"],
            "cpi": course["cpi"],
            "publishObj": json.dumps(publish_objects, ensure_ascii=False, separators=(",", ":")),
            "startTime": normalized_start,
            "endTime": normalized_end,
            "answerAfterEnd": int(allow_late_submission),
            "passingStandard": passing_score_value,
            "redoTimes": redo_times,
            "redoHighestScore": 0,
            "allowAnswer": 1,
            "allowScore": int(show_score),
            "viewTypeScore": 0,
            "allowPaste": int(allow_paste),
            "knowTrueFalse": int(show_correctness),
            "randomSort": int(randomize_questions),
            "randomOptions": int(randomize_options),
            "redoDifferQuestion": 0,
            "endNoticeTime": 24 if normalized_end else 0,
            "intervalNotice": 0,
            "finishStandard": 0,
            "blankobj": 1,
            "completionIngoreCase": 1,
            "multiHalfScore": 1,
            "answerEmptyIsObj": 0,
            "blankIgnoreComma": 1,
            "evaluation": 0,
            "evaluationStandard": "",
            "evaluationNum": 0,
            "evaluationStartTime": "",
            "evaluationEndTime": "",
            "anonymousMarking": 0,
            "anonymousMarkingResult": 0,
            "teacherMarkScore": 0,
            "studentMarkScore": 0,
            "evalPartakeScore": 0,
            "stuMarkNum": 0,
            "teachPlan": 0,
            "sortAvgScore": 0,
            "randomNum": 0,
            "randomType": 0,
            "randomTypeSet": "",
            "randomCustomScore": 0,
            "setMarkScore": 0,
            "markScoreMin": 0,
            "markScoreMax": 0,
            "notShowLastAnswer": 0,
            "allowDownloadAttachment": 1,
            "redoDifferLibrary": 0,
            "saveAsTemplate": 0,
            "selfMark": 0,
            "aiReview": 0,
            "aiAutoMarkScore": 0,
            "answerAfterEndDeadline": normalized_deadline,
            "prohibitViewWork": 0,
            "notShowTeacherComment": 0,
            "limitReviewer": 0,
            "limitReviewerObj": "[]",
            "removeMaxMinScore": 0,
        }
        try:
            response = session.post(
                MOOC2_BASE_URL + "/mooc2-ans/work/library/publish",
                data=form,
                timeout=self.timeout,
                headers={
                    "Referer": setting_response.url,
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"homework publication failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "homework publication was not acknowledged"))

        published: list[dict[str, Any]] = []
        for selected in selected_classes:
            listing = self.list_homeworks(course, selected)
            matches = [
                item
                for item in listing["homeworks"]
                if item["title"] == homework["title"]
                and str(item["work_id"]) not in before_ids[selected["clazz_id"]]
            ]
            if len(matches) != 1:
                raise ChaoxingAPIError(
                    "server acknowledged homework publication, but one new matching class "
                    f"assignment could not be verified for {selected['clazz_name']}"
                )
            published.append({"clazz": selected, "homework": matches[0]})
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "library_homework": homework,
            "settings": {
                "target_class_ids": [item["clazz_id"] for item in selected_classes],
                "start_time": normalized_start,
                "end_time": normalized_end,
                "allow_late_submission": allow_late_submission,
                "late_deadline": normalized_deadline,
                "passing_score": passing_score_value,
                "redo_times": redo_times,
                "allow_paste": allow_paste,
                "show_score": show_score,
                "show_correctness": show_correctness,
                "randomize_questions": randomize_questions,
                "randomize_options": randomize_options,
            },
            "published": published,
            "server_message": str(payload.get("msg") or ""),
            "verification": "one new class assignment was read back for every target class",
        }

    def list_homework_submissions(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        homework_query: str,
        *,
        status: int = 0,
    ) -> dict[str, Any]:
        if status not in {0, 3, 4}:
            raise ChaoxingAPIError("submission status must be 0 (all), 3 (pending), or 4 (graded)")
        homework_result = self.list_homeworks(course, clazz)
        homework = resolve_homework(homework_result["homeworks"], homework_query)
        work_id = str(homework["work_id"])
        session = self._session()

        try:
            info_response = session.get(
                MOOC2_BASE_URL + "/mooc2-ans/work/workinfo",
                params={
                    "courseid": course["course_id"],
                    "clazzid": clazz["clazz_id"],
                    "workid": work_id,
                    "cpi": course["cpi"],
                },
                timeout=self.timeout,
            )
            info_response.raise_for_status()
            info_payload = info_response.json()
        except (requests.RequestException, ValueError) as exc:
            raise ChaoxingAPIError(f"homework info request failed: {exc}") from exc
        if not isinstance(info_payload, dict) or not info_payload.get("status"):
            message = info_payload.get("msg") if isinstance(info_payload, dict) else ""
            raise ChaoxingAPIError(str(message or "failed to fetch homework info"))
        work_info = info_payload.get("data")
        if not isinstance(work_info, dict):
            work_info = {}

        submissions: list[dict[str, Any]] = []
        total_pages = 1
        page = 1
        while page <= total_pages:
            try:
                response = session.get(
                    MOOC2_BASE_URL + "/mooc2-ans/work/mark-list",
                    params={
                        "courseid": course["course_id"],
                        "clazzid": clazz["clazz_id"],
                        "workid": work_id,
                        "submit": "true",
                        "status": str(status),
                        "groupId": "0",
                        "cpi": course["cpi"],
                        "evaluation": "0",
                        "sort": "0",
                        "order": "0",
                        "unEval": "false",
                        "search": "",
                        "from": "",
                        "topicid": "0",
                        "pages": str(page),
                        "size": "100",
                    },
                    timeout=self.timeout,
                    allow_redirects=True,
                )
                response.raise_for_status()
            except requests.RequestException as exc:
                raise ChaoxingAPIError(f"submission list request failed: {exc}") from exc
            if "passport2.chaoxing.com/login" in response.url.lower():
                raise ChaoxingAPIError(
                    f"submission list request was redirected to login: {response.url}"
                )
            page_rows, detected_pages = parse_submission_rows(self._decode(response))
            if page == 1:
                total_pages = detected_pages
            submissions.extend(page_rows)
            page += 1

        for index, row in enumerate(submissions, 1):
            row["index"] = index
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "homework": homework,
            "work_info": work_info,
            "status_filter": status,
            "count": len(submissions),
            "submissions": submissions,
            "verification": (
                f"parsed {len(submissions)} submission records across {total_pages} HTTP page(s)"
            ),
        }

    def read_homework_submission(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        homework_query: str,
        submission_query: str,
        *,
        max_chars: int = 4000,
    ) -> dict[str, Any]:
        if not 1 <= max_chars <= 20_000:
            raise ChaoxingAPIError("max_chars must be between 1 and 20000")
        listing = self.list_homework_submissions(course, clazz, homework_query, status=0)
        submission = resolve_submission(listing["submissions"], submission_query)
        review_url = str(submission.get("review_url") or "")
        if not review_url:
            raise ChaoxingAPIError(f"submission has no review URL: {submission.get('answer_id')}")
        try:
            response = self._session().get(review_url, timeout=self.timeout, allow_redirects=True)
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"submission review request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError(
                f"submission review request was redirected to login: {response.url}"
            )
        review = parse_review_summary(self._decode(response), max_chars=max_chars)
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "homework": listing["homework"],
            "submission": submission,
            "review": review,
            "review_url": response.url,
            "http_status": response.status_code,
            "verification": (
                "authenticated review HTML parsed through HTTP for answer_id "
                f"{submission.get('answer_id')}"
            ),
        }

    def set_homework_score(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        homework_query: str,
        submission_query: str,
        score: str | int | float,
    ) -> dict[str, Any]:
        score_text = str(score).strip()
        if not re.fullmatch(r"\d+(?:\.\d)?", score_text):
            raise ChaoxingAPIError("score must be non-negative with at most one decimal place")
        score_value = float(score_text)

        before_listing = self.list_homework_submissions(course, clazz, homework_query, status=0)
        homework = before_listing["homework"]
        submission = resolve_submission(before_listing["submissions"], submission_query)
        try:
            full_score = float(before_listing["work_info"].get("score"))
        except (TypeError, ValueError) as exc:
            raise ChaoxingAPIError("homework full score was unavailable") from exc
        if score_value > full_score:
            raise ChaoxingAPIError(f"score {score_text} exceeds homework full score {full_score:g}")

        answer_id = str(submission["answer_id"])
        work_id = str(homework["work_id"])
        try:
            response = self._session().post(
                MOOC2_BASE_URL
                + "/mooc2-ans/work/markscore?"
                + urlencode(
                    {
                        "markScore": score_text,
                        "markAnswerIds": answer_id,
                        "markType": "0",
                    }
                ),
                data={
                    "courseid": course["course_id"],
                    "clazzid": clazz["clazz_id"],
                    "cpi": course["cpi"],
                    "workid": work_id,
                    "answerIds": answer_id,
                    "type": "0",
                    "score": score_text,
                },
                timeout=self.timeout,
            )
            response.raise_for_status()
            api_result = response.json()
        except (requests.RequestException, ValueError) as exc:
            raise ChaoxingAPIError(f"score submission failed: {exc}") from exc

        after_listing = self.list_homework_submissions(course, clazz, homework_query, status=0)
        after = resolve_submission(after_listing["submissions"], answer_id)
        try:
            verified = abs(float(str(after.get("score") or "nan")) - score_value) < 1e-9
        except ValueError:
            verified = False
        if not verified:
            raise ChaoxingAPIError(
                "score endpoint returned but the submission list did not show the requested score"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "homework": homework,
            "submission": {
                "answer_id": answer_id,
                "student_name": submission.get("student_name"),
                "student_no": submission.get("student_no"),
            },
            "previous_score": submission.get("score"),
            "score": after.get("score"),
            "api_result": api_result,
            "verification": "requested score matched a fresh HTTP submission-list read",
        }

    def _notice_page_context(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> dict[str, Any]:
        session = self._session()
        context = self._course_context(session, course, clazz)
        module = resolve_module(context["modules"], "tz")
        page_url = self._module_url(context, module, course, clazz)
        try:
            response = session.get(
                page_url,
                timeout=self.timeout,
                allow_redirects=True,
                headers={"Referer": str(context["final_url"])},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"notice page request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError(f"notice page was redirected to login: {response.url}")
        return {"session": session, "page_url": response.url}

    def _notice_editor_context(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        notice_id: str = "",
    ) -> dict[str, Any]:
        context = self._notice_page_context(course, clazz)
        editor_params: dict[str, Any] = {
            "courseId": course["course_id"],
            "classId": clazz["clazz_id"],
        }
        if notice_id:
            editor_params = {"type": "edit", "noticeId": notice_id}
        try:
            response = context["session"].get(
                "https://notice.chaoxing.com/pc/course/notice/richtextNotice",
                params=editor_params,
                timeout=self.timeout,
                allow_redirects=True,
                headers={"Referer": context["page_url"]},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"notice editor request failed: {exc}") from exc
        html = self._decode(response)
        uuid_match = re.search(r"uuidTemp\s*=\s*['\"]([^'\"]+)", html)
        return {
            **context,
            "editor_url": response.url,
            "uuid": uuid_match.group(1) if uuid_match else f"$CACG${uuid4()}",
        }

    @staticmethod
    def _notice_rtf(content: str) -> str:
        return "<p>" + escape(content).replace("\r\n", "<br>").replace("\n", "<br>") + "</p>"

    def list_notice_drafts(
        self,
        course: dict[str, Any],
        *,
        search: str = "",
        page_size: int = 100,
    ) -> dict[str, Any]:
        if not 1 <= page_size <= 1000:
            raise ChaoxingAPIError("notice draft page_size must be between 1 and 1000")
        session = self._session()
        referer = "https://notice.chaoxing.com/pc/draft/notice/noticeDraftBox?" + urlencode(
            {"courseId": course["course_id"]}
        )
        drafts: list[dict[str, Any]] = []
        seen: set[str] = set()
        offset = ""
        pages = 0
        while pages < 100:
            try:
                response = session.post(
                    NOTICE_DRAFT_LIST_URL,
                    data={
                        "offsetValue": offset,
                        "pageSize": page_size,
                        "kw": search,
                        "courseId": course["course_id"],
                    },
                    timeout=self.timeout,
                    headers={
                        "Referer": referer,
                        "X-Requested-With": "XMLHttpRequest",
                    },
                )
                response.raise_for_status()
            except requests.RequestException as exc:
                raise ChaoxingAPIError(f"notice draft list request failed: {exc}") from exc
            try:
                payload = json.loads(self._decode(response))
            except json.JSONDecodeError as exc:
                raise ChaoxingAPIError("notice draft list response was not JSON") from exc
            if not isinstance(payload, dict) or payload.get("status") is not True:
                message = payload.get("msg") if isinstance(payload, dict) else ""
                raise ChaoxingAPIError(str(message or "failed to fetch notice drafts"))
            page_items, next_offset, last_page = parse_notice_draft_payload(payload)
            pages += 1
            for item in page_items:
                key = item["draft_id"] or item["draft_uuid"]
                if key in seen:
                    continue
                seen.add(key)
                drafts.append(item)
            if last_page or not next_offset or next_offset == offset:
                break
            offset = next_offset
        for index, item in enumerate(drafts, 1):
            item["index"] = index
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "search": search,
            "count": len(drafts),
            "drafts": drafts,
            "verification": f"parsed {len(drafts)} notice drafts from {pages} HTTP page(s)",
        }

    def save_notice_draft(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        title: str,
        content: str,
        *,
        recipient_classes: list[str] | None = None,
        draft_query: str = "",
        scheduled_send_time: Any = None,
        clear_schedule: bool = False,
        allow_comments: bool = True,
        show_comments: bool = False,
        hide_read_status: bool = False,
    ) -> dict[str, Any]:
        title = title.strip()
        content = content.strip()
        if not title or not content:
            raise ChaoxingAPIError("notice draft title and content are required")

        before: dict[str, Any] | None = None
        if draft_query:
            before = resolve_notice_draft(
                self.list_notice_drafts(course)["drafts"],
                draft_query,
            )

        selectors = recipient_classes
        if selectors is None and before:
            selectors = [
                str(item.get("clazzId"))
                for item in before.get("recipients", [])
                if isinstance(item, dict) and item.get("type") == 4 and item.get("clazzId")
            ]
        if not selectors:
            selectors = [clazz["clazz_id"]]
        recipients: list[dict[str, Any]] = []
        for selector in selectors:
            resolved = resolve_class(course, str(selector))
            if resolved["clazz_id"] not in {item["clazz_id"] for item in recipients}:
                recipients.append(resolved)

        editor = self._notice_editor_context(course, clazz)
        if clear_schedule:
            send_time: int | str = ""
        elif scheduled_send_time is not None:
            send_time = parse_notice_send_time(scheduled_send_time)
        elif before and before.get("send_time"):
            send_time = int(before["send_time"])
        else:
            send_time = ""

        recipient_ids = [item["clazz_id"] for item in recipients]
        receiver_data = [
            {"type": 4, "clazzId": item["clazz_id"], "name": item["clazz_name"]}
            for item in recipients
        ]
        orderly_receive = [
            {
                "name": item["clazz_name"],
                "opt": 0,
                "clazzId": item["clazz_id"],
                "type": 4,
            }
            for item in recipients
        ]
        attachments = before.get("attachments", []) if before else []
        images = before.get("images", []) if before else []
        notice_uuid = str(before.get("notice_uuid") or "") if before else ""
        payload = {
            "draft_uuid": str(before.get("draft_uuid") or "") if before else "",
            "noticeId": str(before.get("notice_id") or "") if before else "",
            "draft_version": str(before.get("version") or "0") if before else "0",
            "source_type": str(before.get("source_type") or "14") if before else "14",
            "title": title,
            "content": content,
            "puids": json.dumps(receiver_data, ensure_ascii=False, separators=(",", ":")),
            "tocc": "",
            "issuingPuid": "",
            "attr_file": (
                json.dumps(attachments, ensure_ascii=False, separators=(",", ":"))
                if attachments
                else ""
            ),
            "imgs": (
                json.dumps(images, ensure_ascii=False, separators=(",", ":")) if images else ""
            ),
            "isRtf": 1,
            "rtf_content": self._notice_rtf(content),
            "operType": str(before.get("operation") or "add") if before else "add",
            "tag": "courseId" + course["course_id"],
            "noticeTarget": json.dumps(
                [{"classId": clazz_id} for clazz_id in recipient_ids],
                ensure_ascii=False,
                separators=(",", ":"),
            ),
            "uuid": notice_uuid or editor["uuid"],
            "uuidEnc": "",
            "oEnc": "",
            "pcode": "",
            "signId": "",
            "orderlyReceive": json.dumps(
                orderly_receive,
                ensure_ascii=False,
                separators=(",", ":"),
            ),
            "receiveUnreadReminds": "{}",
            "sendUnreadReminds": "{}",
            "allow_comments": "0" if allow_comments else "1",
            "showRead": "2" if hide_read_status else "0",
            "showComments": "1" if show_comments else "0",
            "sendTime": str(send_time),
            "sendType": 0,
        }
        try:
            response = editor["session"].post(
                NOTICE_DRAFT_SAVE_URL,
                data=payload,
                timeout=self.timeout,
                headers={
                    "Referer": editor["editor_url"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"notice draft save request failed: {exc}") from exc
        try:
            result = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("notice draft save response was not JSON") from exc
        if not isinstance(result, dict) or result.get("status") is not True:
            message = result.get("msg") if isinstance(result, dict) else ""
            raise ChaoxingAPIError(str(message or "notice draft save was not acknowledged"))

        message = result.get("msg")
        message = message if isinstance(message, dict) else {}
        returned_id = str(message.get("id") or "")
        listing = self.list_notice_drafts(course, search=title)
        after = resolve_notice_draft(listing["drafts"], returned_id or title)
        if after["title"] != title or after["content"] != content:
            raise ChaoxingAPIError(
                "notice draft was acknowledged, but refreshed title or content differs"
            )
        expected_send_time = int(send_time) if send_time != "" else None
        if after.get("send_time") != expected_send_time:
            if clear_schedule and before and before.get("send_time") and after.get("send_time"):
                replacement = self.save_notice_draft(
                    course,
                    clazz,
                    title,
                    content,
                    recipient_classes=recipient_ids,
                    allow_comments=allow_comments,
                    show_comments=show_comments,
                    hide_read_status=hide_read_status,
                )
                self.delete_notice_draft(course, before["draft_id"])
                replacement["before"] = before
                replacement["replaced_scheduled_draft_id"] = before["draft_id"]
                replacement["verification"] = (
                    "Chaoxing preserves a timed draft's schedule when sendTime is blank; "
                    "created an unscheduled replacement, deleted the timed draft, and verified "
                    "both states through fresh HTTP draft-list reads"
                )
                return replacement
            raise ChaoxingAPIError("notice draft was acknowledged, but refreshed schedule differs")
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "recipient_classes": [
                {"clazz_id": item["clazz_id"], "clazz_name": item["clazz_name"]}
                for item in recipients
            ],
            "before": before,
            "draft": after,
            "scheduled": expected_send_time is not None,
            "verification": (
                "saved title, content, recipients, and scheduled-send timestamp matched a fresh "
                "HTTP draft-list read"
            ),
        }

    def delete_notice_draft(
        self,
        course: dict[str, Any],
        draft_query: str,
    ) -> dict[str, Any]:
        before = resolve_notice_draft(
            self.list_notice_drafts(course)["drafts"],
            draft_query,
        )
        session = self._session()
        referer = "https://notice.chaoxing.com/pc/draft/notice/noticeDraftBox?" + urlencode(
            {"courseId": course["course_id"]}
        )
        try:
            response = session.post(
                NOTICE_DRAFT_DELETE_URL,
                data={"ids": before["draft_id"]},
                timeout=self.timeout,
                headers={
                    "Referer": referer,
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"notice draft delete request failed: {exc}") from exc
        try:
            result = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("notice draft delete response was not JSON") from exc
        if not isinstance(result, dict) or result.get("status") is not True:
            message = result.get("msg") if isinstance(result, dict) else ""
            raise ChaoxingAPIError(str(message or "notice draft delete was not acknowledged"))
        after = self.list_notice_drafts(course, search=before["title"])
        if any(item["draft_id"] == before["draft_id"] for item in after["drafts"]):
            raise ChaoxingAPIError(
                "notice draft delete was acknowledged, but the draft is still listed"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "deleted_draft": before,
            "verification": "deleted draft ID is absent from a refreshed HTTP draft-list read",
        }

    def send_notice(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        title: str,
        content: str,
        *,
        recipient_classes: list[str] | None = None,
        allow_comments: bool = True,
        show_comments: bool = False,
        hide_read_status: bool = False,
    ) -> dict[str, Any]:
        title = title.strip()
        content = content.strip()
        if not title or not content:
            raise ChaoxingAPIError("notice title and content are required")
        selectors = recipient_classes if recipient_classes is not None else [clazz["clazz_id"]]
        if not selectors:
            raise ChaoxingAPIError("at least one recipient class is required")
        recipients: list[dict[str, Any]] = []
        for selector in selectors:
            resolved = resolve_class(course, str(selector))
            if resolved["clazz_id"] not in {item["clazz_id"] for item in recipients}:
                recipients.append(resolved)
        recipient_ids = [item["clazz_id"] for item in recipients]
        editor = self._notice_editor_context(course, clazz)
        try:
            response = editor["session"].post(
                "https://notice.chaoxing.com/pc/course/notice/addNotice",
                data={
                    "uuid": editor["uuid"],
                    "courseId": course["course_id"],
                    "noticeTarget": json.dumps(
                        [{"classId": clazz_id} for clazz_id in recipient_ids]
                    ),
                    "title": title,
                    "content": content,
                    "puids": "",
                    "clazzs": ",".join(recipient_ids),
                    "tocc": "",
                    "attr_file": "[]",
                    "imgs": "[]",
                    "isRtf": 1,
                    "rtf_content": self._notice_rtf(content),
                    "pcode": "",
                    "receiveUnreadReminds": "{}",
                    "sendUnreadReminds": "{}",
                    "allow_comments": "0" if allow_comments else "1",
                    "showRead": "2" if hide_read_status else "0",
                    "showComments": "1" if show_comments else "0",
                },
                timeout=self.timeout,
                headers={
                    "Referer": editor["editor_url"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"notice send request failed: {exc}") from exc
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("notice send response was not JSON") from exc
        if not isinstance(payload, dict) or payload.get("status") is not True:
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "notice send was not acknowledged"))
        message = payload.get("msg")
        message = message if isinstance(message, dict) else {}
        notice_id = str(message.get("idCode") or "")
        notice_uuid = str(message.get("uuid") or "")
        after = self.list_notices(course, recipients[0], search=title)
        published = resolve_notice(after["notices"], notice_id or notice_uuid or title)
        if published["title"] != title or published["content"] != content:
            raise ChaoxingAPIError("notice was acknowledged, but refreshed content does not match")
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "recipient_classes": [
                {"clazz_id": item["clazz_id"], "clazz_name": item["clazz_name"]}
                for item in recipients
            ],
            "notice": published,
            "verification": "new notice ID, title, and content matched a refreshed notice list",
        }

    def edit_notice(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        notice_query: str,
        title: str,
        content: str,
    ) -> dict[str, Any]:
        title = title.strip()
        content = content.strip()
        if not title or not content:
            raise ChaoxingAPIError("notice title and content are required")
        before = resolve_notice(self.list_notices(course, clazz)["notices"], notice_query)
        editor = self._notice_editor_context(
            course,
            clazz,
            notice_id=before["notice_id"],
        )
        try:
            response = editor["session"].post(
                "https://notice.chaoxing.com/pc/course/notice/updateNotice",
                data={
                    "noticeIdCode": before["notice_id"],
                    "title": title,
                    "content": content,
                    "attr_file": json.dumps(before["attachments"], ensure_ascii=False),
                    "imgs": json.dumps(before["images"], ensure_ascii=False),
                    "isRtf": 1,
                    "rtf_content": self._notice_rtf(content),
                    "allow_comments": before["allow_comments"]
                    if before["allow_comments"] is not None
                    else "0",
                    "showComments": before["show_comments"] or "0",
                    "receiveUnreadReminds": "{}",
                    "sendUnreadReminds": "{}",
                    "showRead": before["show_read"] or "0",
                },
                timeout=self.timeout,
                headers={
                    "Referer": editor["editor_url"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"notice edit request failed: {exc}") from exc
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("notice edit response was not JSON") from exc
        if not isinstance(payload, dict) or payload.get("status") is not True:
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "notice edit was not acknowledged"))
        after = resolve_notice(self.list_notices(course, clazz)["notices"], before["notice_id"])
        if after["title"] != title or after["content"] != content:
            raise ChaoxingAPIError("notice edit was acknowledged, but refreshed content differs")
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "before": {"title": before["title"], "content": before["content"]},
            "after": after,
            "verification": "edited notice title and content matched a refreshed notice list",
        }

    def set_notice_top(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        notice_query: str,
        top: bool,
    ) -> dict[str, Any]:
        before = resolve_notice(self.list_notices(course, clazz)["notices"], notice_query)
        page = self._notice_page_context(course, clazz)
        try:
            response = page["session"].post(
                f"https://notice.chaoxing.com/pc/course/notice/{before['notice_id']}/topNotice",
                data={"top": 1 if top else 0},
                timeout=self.timeout,
                headers={
                    "Referer": page["page_url"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"notice top-status request failed: {exc}") from exc
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("notice top-status response was not JSON") from exc
        if not isinstance(payload, dict) or payload.get("status") is not True:
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "notice top-status was not acknowledged"))
        after = resolve_notice(self.list_notices(course, clazz)["notices"], before["notice_id"])
