    def delete_notice(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        notice_query: str,
    ) -> dict[str, Any]:
        notice = resolve_notice(self.list_notices(course, clazz)["notices"], notice_query)
        page = self._notice_page_context(course, clazz)
        try:
            response = page["session"].post(
                "https://notice.chaoxing.com/pc/course/notice/delNoitce",
                data={"noticeId": notice["notice_id"], "sendTag": notice["send_tag"] or ""},
                timeout=self.timeout,
                headers={
                    "Referer": page["page_url"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"notice delete request failed: {exc}") from exc
        try:
            payload = json.loads(self._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("notice delete response was not JSON") from exc
        if not isinstance(payload, dict) or payload.get("status") is not True:
            message = payload.get("msg") if isinstance(payload, dict) else ""
