    def move_exam_paper_library_item(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        item_query: str,
        target_directory_id: str,
        *,
        source_directory_id: str = "0",
        target_parent_directory_id: str = "0",
        is_folder: bool = False,
    ) -> dict[str, Any]:
        source_directory_id = str(source_directory_id or "0").strip()
        target_directory_query = str(target_directory_id or "0").strip()
        target_parent_directory_id = str(target_parent_directory_id or "0").strip()
        if not source_directory_id.isdigit() or not target_parent_directory_id.isdigit():
            raise ChaoxingAPIError(
                "source and target-parent paper-library directory IDs must be numeric"
            )
        if target_directory_query.isdigit():
            target_directory_id = target_directory_query
        else:
            target_parent = self.list_exam_paper_library(
                course, clazz, directory_id=target_parent_directory_id
            )
            target_folder = resolve_exam_paper_library_item(
                target_parent["items"], target_directory_query, folders=True
            )
            target_directory_id = str(target_folder["folder_id"])
        if source_directory_id == target_directory_id:
            raise ChaoxingAPIError("source and target paper-library directories are identical")
        source = self.list_exam_paper_library(course, clazz, directory_id=source_directory_id)
        item = resolve_exam_paper_library_item(source["items"], item_query, folders=is_folder)
        if is_folder and str(item["folder_id"]) == target_directory_id:
            raise ChaoxingAPIError("a paper-library folder cannot be moved into itself")
        session = self._session()
        try:
            response = session.get(
                MOOC2_BASE_URL + "/mooc2-ans/exam/updatepid",
                params={
                    **self._exam_library_request_data(course, clazz),
                    "pid": target_directory_id,
                    "type": "0" if is_folder else "1",
                    "ids": item["item_id"],
                },
                timeout=self.timeout,
                headers={
                    "Referer": str(source.get("source_url") or ""),
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"exam paper-library move failed: {exc}") from exc
        self._exam_library_json(response, "exam paper-library move")
        refreshed_source = self.list_exam_paper_library(
            course, clazz, directory_id=source_directory_id
        )
        refreshed_target = self.list_exam_paper_library(
            course, clazz, directory_id=target_directory_id
        )
        item_id = str(item["item_id"])
        remains_in_source = any(
            str(candidate["item_id"]) == item_id for candidate in refreshed_source["items"]
        )
        target_matches = [
            candidate
            for candidate in refreshed_target["items"]
            if str(candidate["item_id"]) == item_id and bool(candidate["is_folder"]) is is_folder
        ]
        if remains_in_source or len(target_matches) != 1:
            raise ChaoxingAPIError(
                "exam paper-library move was acknowledged but source/target read-back differs"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "source_directory_id": source_directory_id,
            "target_directory_id": target_directory_id,
            "item": target_matches[0],
            "verification": "item is absent from the source and present in the target library",
        }

    def list_exams(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        status: int = -1,
        search: str = "",
    ) -> dict[str, Any]:
        if status not in {-1, 0, 1, 2}:
            raise ChaoxingAPIError(
                "exam status must be -1 (all), 0 (not started), 1 (active), or 2 (ended)"
            )
        session = self._session()
        context = self._course_context(session, course, clazz)
        module = resolve_module(context["modules"], "考试")
        base_url = self._module_url(context, module, course, clazz)

        exams: list[dict[str, Any]] = []
        total_pages = 1
        page = 1
        while page <= total_pages:
            page_url = append_query_params(
                base_url,
                {
                    "pageNum": str(page),
                    "size": "12",
                    "status": str(status),
                    "sw": search,
                    "recyle": "0",
                    "topicid": "0",
                    "perspectiveType": "0",
                },
            )
            try:
                response = session.get(
                    page_url,
                    timeout=self.timeout,
                    allow_redirects=True,
                    headers={"Referer": str(context["final_url"])},
                )
                response.raise_for_status()
            except requests.RequestException as exc:
                raise ChaoxingAPIError(f"exam list request failed: {exc}") from exc
            if "passport2.chaoxing.com/login" in response.url.lower():
                raise ChaoxingAPIError(f"exam list request was redirected to login: {response.url}")
            html = self._decode(response)
            if page == 1:
                hidden = parse_hidden_inputs(html)
                try:
                    total_pages = max(1, int(hidden.get("totalPage") or "1"))
                except ValueError:
                    total_pages = 1
            exams.extend(parse_exam_items(html, response.url))
            page += 1

        for index, item in enumerate(exams, 1):
            item["index"] = index
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "status_filter": status,
            "search": search,
            "count": len(exams),
            "exams": exams,
            "verification": (f"parsed {len(exams)} exam records across {total_pages} HTTP page(s)"),
        }

    def list_exam_submissions(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        exam_query: str,
        *,
        state: int = 1,
        status: int = -1,
        search: str = "",
    ) -> dict[str, Any]:
        if state not in {0, 1}:
            raise ChaoxingAPIError("exam submission state must be 0 (unsubmitted) or 1 (submitted)")
        exam_result = self.list_exams(course, clazz, status=-1)
        exam = resolve_exam(exam_result["exams"], exam_query)
        mark_url = str(exam.get("mark_url") or "")
        if not mark_url:
            mark_url = append_query_params(
                f"{MOOC2_BASE_URL}/mooc2-ans/exam/test/marklist",
                {
                    "courseid": course["course_id"],
                    "clazzid": clazz["clazz_id"],
                    "cpi": course["cpi"],
                    "id": exam["exam_id"],
                    "paperId": exam.get("paper_id", ""),
                },
            )

        session = self._session()
        try:
            landing = session.get(mark_url, timeout=self.timeout, allow_redirects=True)
            landing.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"exam submission page request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in landing.url.lower():
            raise ChaoxingAPIError(
                f"exam submission request was redirected to login: {landing.url}"
            )
        landing_hidden = parse_hidden_inputs(self._decode(landing))

        submissions: list[dict[str, Any]] = []
        seen: set[str] = set()
        total_pages = 1
        server_total: int | None = None
        class_size: int | None = None
        page = 1
        endpoint = f"{MOOC2_BASE_URL}/mooc2-ans/exam/test/markresult-new"
        while page <= total_pages and page <= 100:
            request_data = {
                "courseid": course["course_id"],
                "clazzid": clazz["clazz_id"],
                "cpi": course["cpi"],
                "ut": "",
                "id": exam["exam_id"],
                "sw": search,
                "schoolId": landing_hidden.get("schoolId") or "-1",
                "schoolName": landing_hidden.get("schoolName") or "",
                "sort": "",
                "sorttype": "",
                "state": str(state),
                "status": str(status),
                "groupIds": "",
                "groupid": "-1",
                "collegeId": "-1",
                "majorId": "-1",
                "clazzId": "-1",
                "reviewMarkLabel": "0",
                "markType": "0",
                "hideInvigilation": "0",
                "hideRetest": "false",
                "updateScore": "1",
                "allowAnnotationRedoDownload": "1",
                "pages": str(page),
                "size": "100",
            }
            try:
                response = session.post(
                    endpoint,
                    data=request_data,
                    timeout=self.timeout,
                    allow_redirects=True,
                    headers={"Referer": landing.url},
                )
                response.raise_for_status()
            except requests.RequestException as exc:
                raise ChaoxingAPIError(f"exam submission list request failed: {exc}") from exc
            try:
                payload = json.loads(self._decode(response))
            except json.JSONDecodeError as exc:
                raise ChaoxingAPIError("exam submission list response was not JSON") from exc
            if not isinstance(payload, dict) or not isinstance(payload.get("data"), list):
                message = payload.get("msg") if isinstance(payload, dict) else ""
                raise ChaoxingAPIError(str(message or "failed to fetch exam submissions"))
            if page == 1:
                try:
                    total_pages = max(1, int(payload.get("totalPage") or "1"))
                except (TypeError, ValueError):
                    total_pages = 1
                try:
                    server_total = int(payload.get("total"))
                except (TypeError, ValueError):
                    server_total = None
                try:
                    class_size = int(payload.get("classSize"))
                except (TypeError, ValueError):
                    class_size = None
            for row in parse_exam_submission_payload(payload):
                identity = (
                    str(row.get("answer_id") or "")
                    or str(row.get("student_no") or "")
                    or f"{row.get('person_id')}|{row.get('student_name')}"
                )
                if identity in seen:
                    continue
                seen.add(identity)
                submissions.append(row)
            page += 1

        for index, row in enumerate(submissions, 1):
            row["index"] = index
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "exam": exam,
            "state_filter": state,
            "status_filter": status,
            "search": search,
            "server_total": server_total,
            "class_size": class_size,
            "count": len(submissions),
            "submissions": submissions,
            "verification": (
                f"parsed {len(submissions)} exam submission records across "
                f"{total_pages} HTTP page(s)"
            ),
        }

    def read_exam_submission(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        exam_query: str,
        submission_query: str,
    ) -> dict[str, Any]:
        listing = self.list_exam_submissions(
            course,
            clazz,
            exam_query,
            state=1,
            status=-1,
        )
        submission = resolve_exam_submission(listing["submissions"], submission_query)
        review_url = str(submission.get("review_url") or "")
        if not review_url:
            raise ChaoxingAPIError("selected exam submission has no review URL")
        session = self._session()
        try:
            response = session.get(
                review_url,
                timeout=self.timeout,
                allow_redirects=True,
                headers={"Referer": str(listing["exam"].get("mark_url") or "")},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"exam answer request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError(f"exam answer request was redirected to login: {response.url}")
        answer_sheet = parse_exam_answer_sheet(self._decode(response))
        if not answer_sheet["questions"]:
            raise ChaoxingAPIError("exam answer page exposed no questions")
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "exam": listing["exam"],
            "submission": submission,
            "answer_sheet": answer_sheet,
            "source_url": response.url,
            "verification": (
                f"parsed {answer_sheet['question_count']} questions from the authenticated "
                "exam answer page through HTTP"
            ),
        }

    def _question_bank_landing_context(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        session: requests.Session | None = None,
    ) -> dict[str, Any]:
        session = session or self._session()
        context = self._course_context(session, course, clazz)
        module = resolve_module(context["modules"], "题库")
        qbank_url = self._module_url(context, module, course, clazz)
        try:
            response = session.get(
                qbank_url,
                timeout=self.timeout,
                allow_redirects=True,
                headers={"Referer": str(context["final_url"])},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"question bank request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError(f"question bank request was redirected to login: {response.url}")
        return {
            "session": session,
            "course_context": context,
            "landing_url": response.url,
            "landing_html": self._decode(response),
        }

    def _question_bank_directory_tree(
        self,
        session: requests.Session,
        course: dict[str, Any],
        *,
        referer: str,
    ) -> list[dict[str, Any]]:
        try:
            response = session.post(
                MOOC2_BASE_URL + "/mooc2-ans/qbank/directory-relation",
                data={"courseid": course["course_id"], "cpi": course["cpi"]},
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"question-bank directory request failed: {exc}") from exc
        if not isinstance(payload, dict):
            raise ChaoxingAPIError("question-bank directory request returned an invalid response")
        return parse_question_bank_directory_tree(payload)

    def _question_bank_mutation_request(
        self,
        session: requests.Session,
        path: str,
        data: dict[str, Any],
        *,
        referer: str,
        operation: str,
    ) -> dict[str, Any]:
        try:
            response = session.post(
                MOOC2_BASE_URL + path,
                data=data,
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"{operation} failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or f"{operation} was not acknowledged"))
        return payload

    def list_question_bank_directories(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> dict[str, Any]:
        landing = self._question_bank_landing_context(course, clazz)
        directories = self._question_bank_directory_tree(
            landing["session"],
            course,
            referer=landing["landing_url"],
        )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "count": len(directories),
            "directories": directories,
            "verification": "parsed the complete authenticated question-bank directory tree",
        }

    @staticmethod
    def _question_bank_share_scope_code(value: Any) -> str:
        normalized = str(value or "").strip().lower().replace("-", "_")
        aliases = {
            "0": "0",
            "all": "0",
            "all_team": "0",
            "public": "0",
            "open": "0",
            "公开": "0",
            "全部": "0",
            "全体教师": "0",
            "所有教学团队成员": "0",
            "1": "1",
            "private": "1",
            "self": "1",
            "私有": "1",
            "仅自己": "1",
            "2": "2",
            "selected": "2",
            "selected_team": "2",
            "selected_teachers": "2",
            "specified": "2",
            "指定": "2",
            "指定教师": "2",
            "指定教学团队成员": "2",
        }
        if normalized not in aliases:
            raise ChaoxingAPIError(
                "question-bank share scope must be all_team, private, or selected_teachers"
            )
        return aliases[normalized]

    @staticmethod
    def _question_bank_permission_state(
        directory: dict[str, Any],
        permission_payload: dict[str, Any],
        teacher_candidates: list[dict[str, Any]],
    ) -> dict[str, Any]:
        raw_open = str(directory.get("is_open") if directory.get("is_open") is not None else "0")
        raw_scope = str(
            directory.get("share_state") if directory.get("share_state") is not None else "0"
        )
        scope_names = {
            "0": "all_team",
            "1": "private",
            "2": "selected_teachers",
        }
        scope_labels = {
            "0": "全部教学团队成员",
            "1": "仅自己",
            "2": "指定教学团队成员",
        }
        selected_ids = list(permission_payload.get("selected_person_ids") or [])
        candidates_by_id = {
            str(item.get("person_id") or ""): item
            for item in teacher_candidates
            if str(item.get("person_id") or "")
        }
        selected_teachers = [
            candidates_by_id.get(person_id, {"person_id": person_id, "teacher_name": ""})
            for person_id in selected_ids
        ]
        return {
            "student_self_practice_allowed": raw_open != "-1",
            "self_practice_raw": raw_open,
            "share_scope": scope_names.get(raw_scope, f"unknown:{raw_scope}"),
            "share_scope_label": scope_labels.get(raw_scope, f"未知值 {raw_scope}"),
            "share_scope_raw": raw_scope,
            "selected_person_ids": selected_ids if permission_payload.get("accessible") else None,
            "selected_teachers": (
                selected_teachers if permission_payload.get("accessible") else None
            ),
            "permission_details_accessible": bool(permission_payload.get("accessible")),
            "permission_message": str(permission_payload.get("message") or ""),
        }

    def _question_bank_directory_permission_payload(
        self,
        session: requests.Session,
        course: dict[str, Any],
        directory: dict[str, Any],
        *,
        referer: str,
    ) -> dict[str, Any]:
        try:
            response = session.get(
                MOOC2_BASE_URL + "/mooc2-ans/dir-permission/list",
                params={
                    "courseid": directory.get("course_id") or course["course_id"],
                    "dirId": directory["directory_id"],
                },
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(
                f"question-bank directory permission request failed: {exc}"
            ) from exc
        if not isinstance(payload, dict):
            raise ChaoxingAPIError(
                "question-bank directory permission request returned an invalid response"
            )
        accessible = payload.get("status") is True or str(payload.get("status")).lower() == "true"
        permission_items = payload.get("permissionList")
        if not isinstance(permission_items, list):
            permission_items = []
        selected_ids: list[str] = []
        for item in permission_items:
            if not isinstance(item, dict):
                continue
            person_id = str(item.get("personId") or item.get("person_id") or "").strip()
            if person_id and person_id not in selected_ids:
                selected_ids.append(person_id)
        return {
            "accessible": accessible,
            "selected_person_ids": selected_ids,
            "message": str(payload.get("msg") or ""),
        }

    def read_question_bank_directory_permissions(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        directory_query: str,
    ) -> dict[str, Any]:
        landing = self._question_bank_landing_context(course, clazz)
        session = landing["session"]
        tree = self._question_bank_directory_tree(
            session,
            course,
            referer=landing["landing_url"],
        )
        directory = resolve_question_bank_directory(tree, directory_query)
        permission_payload = self._question_bank_directory_permission_payload(
            session,
            course,
            directory,
            referer=landing["landing_url"],
        )
        candidates = parse_question_bank_permission_teachers(landing["landing_html"])
        permissions = self._question_bank_permission_state(
            directory,
            permission_payload,
            candidates,
        )
        verification = (
            "read the directory state and selected-teacher permission list through HTTP"
            if permission_payload["accessible"]
            else (
                "read the directory state through HTTP; Chaoxing denied the selected-teacher "
                "detail request for this directory"
            )
        )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "directory": directory,
            "permissions": permissions,
            "available_share_teachers": candidates,
            "verification": verification,
        }

    def update_question_bank_directory_permissions(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        directory_query: str,
        *,
        allow_student_self_practice: bool | None = None,
        share_scope: str | None = None,
        selected_teachers: list[str] | str | None = None,
    ) -> dict[str, Any]:
        if (
            allow_student_self_practice is None
            and share_scope is None
            and selected_teachers is None
        ):
            raise ChaoxingAPIError("at least one question-bank permission change is required")
        if allow_student_self_practice is not None and not isinstance(
            allow_student_self_practice, bool
        ):
            raise ChaoxingAPIError("allow_student_self_practice must be a boolean")

        landing = self._question_bank_landing_context(course, clazz)
        session = landing["session"]
        before_tree = self._question_bank_directory_tree(
            session,
            course,
            referer=landing["landing_url"],
        )
        before_directory = resolve_question_bank_directory(before_tree, directory_query)
        before_payload = self._question_bank_directory_permission_payload(
            session,
            course,
            before_directory,
            referer=landing["landing_url"],
        )
        if not before_payload["accessible"]:
            raise ChaoxingAPIError(
                before_payload["message"]
                or "Chaoxing did not permit this account to manage the directory permissions"
            )
        candidates = parse_question_bank_permission_teachers(landing["landing_html"])
        before_state = self._question_bank_permission_state(
            before_directory,
            before_payload,
            candidates,
        )

        explicit_selected = selected_teachers is not None
        if isinstance(selected_teachers, str):
            teacher_queries = [
                item.strip() for item in re.split(r"[,，]", selected_teachers) if item.strip()
            ]
        elif selected_teachers is None:
            teacher_queries = []
        elif isinstance(selected_teachers, (list, tuple, set)):
            teacher_queries = [str(item).strip() for item in selected_teachers if str(item).strip()]
        else:
            raise ChaoxingAPIError("selected_teachers must be a list of teacher references")

        target_scope = (
            self._question_bank_share_scope_code(share_scope)
            if share_scope is not None
            else ("2" if explicit_selected else str(before_directory.get("share_state") or "0"))
        )
        if explicit_selected and share_scope is not None and target_scope != "2":
            raise ChaoxingAPIError(
                "selected_teachers can only be used with the selected_teachers share scope"
            )
        selected_records: list[dict[str, Any]] = []
        for query in teacher_queries:
            teacher = resolve_course_teacher(candidates, query)
            if not teacher.get("person_id"):
                raise ChaoxingAPIError(f"selected teacher has no usable person ID: {query}")
            if all(existing["person_id"] != teacher["person_id"] for existing in selected_records):
                selected_records.append(teacher)
        if target_scope == "2":
            target_selected_ids = (
                [str(item["person_id"]) for item in selected_records]
                if explicit_selected
                else list(before_payload["selected_person_ids"])
            )
            if not target_selected_ids:
                raise ChaoxingAPIError(
                    "selected_teachers share scope requires at least one teaching-team member"
                )
        else:
            target_selected_ids = []

        target_self_practice = (
            allow_student_self_practice
            if allow_student_self_practice is not None
            else bool(before_state["student_self_practice_allowed"])
        )
        semantic_change = any(
            (
                target_self_practice != before_state["student_self_practice_allowed"],
                target_scope != before_state["share_scope_raw"],
                target_scope == "2"
                and set(target_selected_ids) != set(before_payload["selected_person_ids"]),
            )
        )
        if not semantic_change:
            return {
                "course_id": course["course_id"],
                "course_name": course["course_name"],
                "clazz_id": clazz["clazz_id"],
                "clazz_name": clazz["clazz_name"],
                "directory": before_directory,
                "before": before_state,
                "after": before_state,
                "changed": False,
                "verification": "the requested directory permissions were already present",
            }

        selected_field = ",".join(target_selected_ids) + "," if target_selected_ids else ""
        payload = self._question_bank_mutation_request(
            session,
            "/mooc2-ans/qbank/update-permission",
            {
                "courseid": before_directory.get("course_id") or course["course_id"],
                "dirid": before_directory["directory_id"],
                "isopen": "1" if target_self_practice else "-1",
                "isShare": target_scope,
                "personIdArr": selected_field,
            },
            referer=landing["landing_url"],
            operation="question-bank directory permission update",
        )
        after_tree = self._question_bank_directory_tree(
            session,
            course,
            referer=landing["landing_url"],
        )
        after_directory = resolve_question_bank_directory(
            after_tree,
            before_directory["directory_id"],
        )
        after_payload = self._question_bank_directory_permission_payload(
            session,
            course,
            after_directory,
            referer=landing["landing_url"],
        )
        if not after_payload["accessible"]:
            raise ChaoxingAPIError(
                "directory permission update was acknowledged but read-back was denied"
            )
        after_state = self._question_bank_permission_state(
            after_directory,
            after_payload,
            candidates,
        )
        mismatches: list[str] = []
        if after_state["student_self_practice_allowed"] != target_self_practice:
            mismatches.append("student self-practice")
        if after_state["share_scope_raw"] != target_scope:
            mismatches.append("share scope")
        if target_scope == "2" and set(after_payload["selected_person_ids"]) != set(
            target_selected_ids
        ):
            mismatches.append("selected teachers")
        if mismatches:
            raise ChaoxingAPIError(
                "directory permission update was acknowledged but read-back differs: "
                + ", ".join(mismatches)
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "directory": after_directory,
            "before": before_state,
            "after": after_state,
            "changed": True,
            "server_message": str(payload.get("msg") or ""),
            "private_scope_effect": (
                "Chaoxing moves questions created by other people from this directory to the "
                "question-bank root when the directory becomes private."
                if target_scope == "1"
                else ""
            ),
            "verification": (
                "share scope, selected teachers, and self-practice state match fresh HTTP reads"
            ),
        }

    def _question_bank_question_types(
        self,
        session: requests.Session,
        course: dict[str, Any],
        *,
        referer: str,
    ) -> list[dict[str, Any]]:
        try:
            response = session.get(
                MOOC2_BASE_URL + "/mooc2-ans/qbank/get-qtype",
                params={"courseid": course["course_id"], "cpi": course["cpi"]},
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"question-bank question-type request failed: {exc}") from exc
        return parse_question_bank_question_types(self._decode(response))

    def _question_bank_qtype_json_request(
        self,
        session: requests.Session,
        path: str,
        params: dict[str, Any],
        *,
        referer: str,
        operation: str,
    ) -> dict[str, Any]:
        try:
            response = session.get(
                MOOC2_BASE_URL + path,
                params=params,
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"{operation} failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or f"{operation} was not acknowledged"))
        return payload

    @staticmethod
    def _question_bank_question_type_name(name: str, *, max_length: int = 100) -> str:
        normalized = re.sub(r"['\"]", "", str(name or "")).strip()
        if not normalized:
            raise ChaoxingAPIError("question-bank question-type name is required")
        if len(normalized) > max_length:
            raise ChaoxingAPIError(
                f"question-bank question-type name cannot exceed {max_length} characters"
            )
        return normalized

    @staticmethod
    def _question_bank_base_type_code(value: str) -> str:
        normalized = str(value or "").strip().lower().replace("-", "_")
        aliases = {
            str(alias).lower(): code for alias, code in QUESTION_BANK_BASE_TYPE_ALIASES.items()
        }
        if normalized not in aliases:
            available = ", ".join(
                f"{code}={item['key']}" for code, item in QUESTION_BANK_CREATABLE_BASE_TYPES.items()
            )
            raise ChaoxingAPIError(f"unsupported question-bank base type; available: {available}")
        return aliases[normalized]

    @staticmethod
    def _question_bank_qtype_p_message(landing_html: str) -> str:
        return (
            "true"
            if parse_hidden_inputs(landing_html).get("qtypeManagePMessage", "").lower() == "true"
            else "false"
        )

    def list_question_bank_question_types(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> dict[str, Any]:
        landing = self._question_bank_landing_context(course, clazz)
        question_types = self._question_bank_question_types(
            landing["session"],
            course,
            referer=landing["landing_url"],
        )
        hidden = parse_hidden_inputs(landing["landing_html"])
        try:
            max_name_length = int(hidden.get("typeNameMaxLength") or 100)
        except (TypeError, ValueError):
            max_name_length = 100
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "count": len(question_types),
            "question_types": question_types,
            "creatable_base_types": [
                {"code": code, **item} for code, item in QUESTION_BANK_CREATABLE_BASE_TYPES.items()
            ],
            "max_name_length": max_name_length,
            "verification": "parsed the current question-type management list through HTTP",
        }

    def add_question_bank_question_type(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        name: str,
        base_type: str,
    ) -> dict[str, Any]:
        landing = self._question_bank_landing_context(course, clazz)
        hidden = parse_hidden_inputs(landing["landing_html"])
        try:
            max_length = int(hidden.get("typeNameMaxLength") or 100)
        except (TypeError, ValueError):
            max_length = 100
        name = self._question_bank_question_type_name(name, max_length=max_length)
        origin_type = self._question_bank_base_type_code(base_type)
        session = landing["session"]
        before = self._question_bank_question_types(
            session,
            course,
            referer=landing["landing_url"],
        )
        before_ids = {item["type_id"] for item in before}
        payload = self._question_bank_qtype_json_request(
            session,
            "/mooc2-ans/qbank/add-qtype",
            {
                "courseid": course["course_id"],
                "cpi": course["cpi"],
                "typename": name,
                "originType": origin_type,
                "pMessage": self._question_bank_qtype_p_message(landing["landing_html"]),
            },
            referer=landing["landing_url"],
            operation="question-bank question-type creation",
        )
        refreshed = self._question_bank_question_types(
            session,
            course,
            referer=landing["landing_url"],
        )
        created = [
            item
            for item in refreshed
            if item["type_id"] not in before_ids
            and item["name"] == name
            and item["origin_type"] == origin_type
        ]
        returned_id = str(payload.get("courseQtypeId") or "").strip()
        if returned_id:
            created = [item for item in created if item["type_id"] == returned_id]
        if len(created) != 1:
            raise ChaoxingAPIError(
                "question-type creation was acknowledged but exactly one matching new type "
                "was not found"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "question_type": created[0],
            "server_message": str(payload.get("msg") or ""),
            "verification": "the new question-type ID, name, and base type match a fresh read",
        }

    def rename_question_bank_question_type(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        question_type_query: str,
        name: str,
    ) -> dict[str, Any]:
        landing = self._question_bank_landing_context(course, clazz)
        hidden = parse_hidden_inputs(landing["landing_html"])
        try:
            max_length = int(hidden.get("typeNameMaxLength") or 100)
        except (TypeError, ValueError):
            max_length = 100
        name = self._question_bank_question_type_name(name, max_length=max_length)
        session = landing["session"]
        before_types = self._question_bank_question_types(
            session,
            course,
            referer=landing["landing_url"],
        )
        before = resolve_question_bank_question_type(before_types, question_type_query)
        if not before["can_rename"]:
            raise ChaoxingAPIError("the current question-type interface does not allow renaming")
        if before["name"] == name:
            return {
                "course_id": course["course_id"],
                "course_name": course["course_name"],
                "clazz_id": clazz["clazz_id"],
                "clazz_name": clazz["clazz_name"],
                "before": before,
                "after": before,
                "changed": False,
                "verification": "the requested question-type name was already present",
            }
        payload = self._question_bank_qtype_json_request(
            session,
            "/mooc2-ans/qbank/update-qtype",
            {
                "courseid": course["course_id"],
                "cpi": course["cpi"],
                "typeid": before["type_id"],
                "typename": name,
                "pMessage": self._question_bank_qtype_p_message(landing["landing_html"]),
            },
            referer=landing["landing_url"],
            operation="question-bank question-type rename",
        )
        refreshed = self._question_bank_question_types(
            session,
            course,
            referer=landing["landing_url"],
        )
        after = resolve_question_bank_question_type(refreshed, before["type_id"])
        if after["name"] != name:
            raise ChaoxingAPIError(
                "question-type rename was acknowledged but the refreshed name differs"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "before": before,
            "after": after,
            "changed": True,
            "server_message": str(payload.get("msg") or ""),
            "verification": "the question-type name matches a fresh management-list read",
        }

    def move_question_bank_question_type(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        question_type_query: str,
        target_position: int,
    ) -> dict[str, Any]:
        landing = self._question_bank_landing_context(course, clazz)
        session = landing["session"]
        before_types = self._question_bank_question_types(
            session,
            course,
            referer=landing["landing_url"],
        )
        target = resolve_question_bank_question_type(before_types, question_type_query)
        before_order = [item["type_id"] for item in before_types]
        target_order = reposition_identifier(
            before_order,
            target["type_id"],
            target_position,
        )
        if target_order == before_order:
            return {
                "course_id": course["course_id"],
                "course_name": course["course_name"],
                "clazz_id": clazz["clazz_id"],
                "clazz_name": clazz["clazz_name"],
                "question_type": target,
                "before_order": before_order,
                "after_order": before_order,
                "changed": False,
                "verification": "the question type was already at the requested position",
            }
        payload = self._question_bank_qtype_json_request(
            session,
            "/mooc2-ans/qbank/update-qtype-sort",
            {
                "courseid": course["course_id"],
                "cpi": course["cpi"],
                "typeIds": ",".join(target_order) + ",",
            },
            referer=landing["landing_url"],
            operation="question-bank question-type reorder",
        )
        refreshed = self._question_bank_question_types(
            session,
            course,
            referer=landing["landing_url"],
        )
        after_order = [item["type_id"] for item in refreshed]
        if after_order != target_order:
            raise ChaoxingAPIError(
                "question-type reorder was acknowledged but the refreshed order differs"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "question_type": resolve_question_bank_question_type(
                refreshed,
                target["type_id"],
            ),
            "before_order": before_order,
            "after_order": after_order,
            "changed": True,
            "server_message": str(payload.get("msg") or ""),
            "verification": "the complete question-type order matches a fresh read",
        }

    def delete_question_bank_question_type(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        question_type_query: str,
    ) -> dict[str, Any]:
        landing = self._question_bank_landing_context(course, clazz)
        session = landing["session"]
        before_types = self._question_bank_question_types(
            session,
            course,
            referer=landing["landing_url"],
        )
        before = resolve_question_bank_question_type(before_types, question_type_query)
        if not before["can_delete"]:
            raise ChaoxingAPIError("the current question-type interface does not allow deletion")
        payload = self._question_bank_qtype_json_request(
            session,
            "/mooc2-ans/qbank/delete-qtype",
            {
                "courseid": course["course_id"],
                "cpi": course["cpi"],
                "typeid": before["type_id"],
                "pMessage": self._question_bank_qtype_p_message(landing["landing_html"]),
            },
            referer=landing["landing_url"],
            operation="question-bank question-type deletion",
        )
        refreshed = self._question_bank_question_types(
            session,
            course,
            referer=landing["landing_url"],
        )
        if any(item["type_id"] == before["type_id"] for item in refreshed):
            raise ChaoxingAPIError(
                "question-type deletion was acknowledged but it remains in the management list"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "deleted_question_type": before,
            "server_message": str(payload.get("msg") or ""),
            "verification": "the deleted question-type ID is absent from a fresh management list",
        }

    def _question_bank_label_listing(
        self,
        session: requests.Session,
        course: dict[str, Any],
        *,
        referer: str,
        question_id: str = "",
    ) -> dict[str, Any]:
        try:
            response = session.post(
                MOOC2_BASE_URL + "/mooc2-ans/question-label/list",
                data={
                    "courseid": course["course_id"],
                    "cpi": course["cpi"],
                    "qid": str(question_id),
                },
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"question-bank label request failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(
                str(message or "question-bank label request was not acknowledged")
            )
        labels = parse_question_bank_label_tree(payload)
        checked_raw = payload.get("checkedIds")
        checked_ids: list[str] = []
        if isinstance(checked_raw, list):
            for value in checked_raw:
                label_id = str(value).strip()
                if label_id and label_id not in checked_ids:
                    checked_ids.append(label_id)
        return {
            "labels": labels,
            "checked_ids": checked_ids,
            "message": str(payload.get("msg") or ""),
        }

    @staticmethod
    def _question_bank_label_name(name: str) -> str:
        normalized = str(name or "").strip()
        if not normalized:
            raise ChaoxingAPIError("question-bank label name is required")
        return normalized

    def list_question_bank_labels(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        question_query: str = "",
        directory_id: str = "0",
    ) -> dict[str, Any]:
        landing = self._question_bank_landing_context(course, clazz)
        question: dict[str, Any] | None = None
        if question_query.strip():
            items = self._list_all_question_bank_items(
                course,
                clazz,
                directory_id=str(directory_id or "0"),
            )
            question = resolve_question_bank_question(items["questions"], question_query)
        listing = self._question_bank_label_listing(
            landing["session"],
            course,
            referer=landing["landing_url"],
            question_id=str(question.get("question_id") or "") if question else "",
        )
        checked = set(listing["checked_ids"])
        for label in listing["labels"]:
            label["selected"] = label["label_id"] in checked if question else None
        hidden = parse_hidden_inputs(landing["landing_html"])
        try:
            max_level = int(hidden.get("qbankLabelMaxLevel") or 7)
        except (TypeError, ValueError):
            max_level = 7
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "directory_id": str(directory_id or "0"),
            "question": question,
            "count": len(listing["labels"]),
            "labels": listing["labels"],
            "selected_label_ids": listing["checked_ids"] if question else None,
            "max_level": max_level,
            "verification": "parsed the label tree and current question selections through HTTP",
        }

    def create_question_bank_label(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        name: str,
        *,
        parent_label: str = "0",
    ) -> dict[str, Any]:
        name = self._question_bank_label_name(name)
        landing = self._question_bank_landing_context(course, clazz)
        session = landing["session"]
        before = self._question_bank_label_listing(
            session,
            course,
            referer=landing["landing_url"],
        )
        parent = resolve_question_bank_label(
            before["labels"],
            parent_label,
            allow_root=True,
        )
        hidden = parse_hidden_inputs(landing["landing_html"])
        try:
            max_level = int(hidden.get("qbankLabelMaxLevel") or 7)
        except (TypeError, ValueError):
            max_level = 7
        if int(parent.get("level") or 0) >= max_level:
            raise ChaoxingAPIError(f"question-bank labels cannot exceed {max_level} levels")
        before_ids = {item["label_id"] for item in before["labels"]}
        payload = self._question_bank_mutation_request(
            session,
            "/mooc2-ans/question-label/add",
            {
                "courseid": course["course_id"],
                "cpi": course["cpi"],
                "parentId": parent["label_id"],
                "labelname": name,
            },
            referer=landing["landing_url"],
            operation="question-bank label creation",
        )
        refreshed = self._question_bank_label_listing(
            session,
            course,
            referer=landing["landing_url"],
        )
        created = [
            item
            for item in refreshed["labels"]
            if item["label_id"] not in before_ids
            and item["parent_id"] == parent["label_id"]
            and item["name"] == name
        ]
        returned_id = str(payload.get("labelId") or "").strip()
        if returned_id:
            created = [item for item in created if item["label_id"] == returned_id]
        if len(created) != 1:
            raise ChaoxingAPIError(
                "label creation was acknowledged but exactly one matching label was not found"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "parent": parent,
            "label": created[0],
            "server_message": str(payload.get("msg") or ""),
            "verification": "the new label ID, parent, and name match a fresh label-tree read",
        }

    def rename_question_bank_label(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        label_query: str,
        name: str,
    ) -> dict[str, Any]:
        name = self._question_bank_label_name(name)
        landing = self._question_bank_landing_context(course, clazz)
        session = landing["session"]
        before_listing = self._question_bank_label_listing(
            session,
            course,
            referer=landing["landing_url"],
        )
        before = resolve_question_bank_label(before_listing["labels"], label_query)
        if before["name"] == name:
            return {
                "course_id": course["course_id"],
                "course_name": course["course_name"],
                "clazz_id": clazz["clazz_id"],
                "clazz_name": clazz["clazz_name"],
                "before": before,
                "after": before,
                "changed": False,
                "verification": "the requested label name was already present",
            }
        payload = self._question_bank_mutation_request(
            session,
            "/mooc2-ans/question-label/edit",
            {
                "courseid": course["course_id"],
                "cpi": course["cpi"],
                "labelid": before["label_id"],
                "labelname": name,
            },
            referer=landing["landing_url"],
            operation="question-bank label rename",
        )
        refreshed = self._question_bank_label_listing(
            session,
            course,
            referer=landing["landing_url"],
        )
        after = resolve_question_bank_label(refreshed["labels"], before["label_id"])
        if after["name"] != name:
            raise ChaoxingAPIError("label rename was acknowledged but read-back differs")
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "before": before,
            "after": after,
            "changed": True,
            "server_message": str(payload.get("msg") or ""),
            "verification": "the label name matches a fresh label-tree read",
        }

    def delete_question_bank_label(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        label_query: str,
    ) -> dict[str, Any]:
        landing = self._question_bank_landing_context(course, clazz)
        session = landing["session"]
        before_listing = self._question_bank_label_listing(
            session,
            course,
            referer=landing["landing_url"],
        )
        before = resolve_question_bank_label(before_listing["labels"], label_query)
        removed_ids = {before["label_id"]}
        changed = True
        while changed:
            changed = False
            for item in before_listing["labels"]:
                if item["parent_id"] in removed_ids and item["label_id"] not in removed_ids:
                    removed_ids.add(item["label_id"])
                    changed = True
        payload = self._question_bank_qtype_json_request(
            session,
            "/mooc2-ans/question-label/delete",
            {
                "courseid": course["course_id"],
                "cpi": course["cpi"],
                "labelid": before["label_id"],
            },
            referer=landing["landing_url"],
            operation="question-bank label deletion",
        )
        refreshed = self._question_bank_label_listing(
            session,
            course,
            referer=landing["landing_url"],
        )
        remaining_ids = {item["label_id"] for item in refreshed["labels"]}
        if removed_ids & remaining_ids:
            raise ChaoxingAPIError(
                "label deletion was acknowledged but the label or a descendant remains"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "deleted_label": before,
            "deleted_label_ids": sorted(removed_ids),
            "server_message": str(payload.get("msg") or ""),
            "verification": "the label and all descendants are absent from a fresh tree read",
        }

    def _question_bank_label_assignment_request(
        self,
        session: requests.Session,
        course: dict[str, Any],
        question_id: str,
        label_ids: list[str],
        *,
        sync_references: bool,
        referer: str,
    ) -> dict[str, Any]:
        label_field = ",".join(label_ids) + "," if label_ids else ""
        try:
            response = session.post(
                MOOC2_BASE_URL + "/mooc2-ans/qbank/update-label",
                params={
                    "courseid": course["course_id"],
                    "cpi": course["cpi"],
                    "labelIds": label_field,
                    "updateExamWord": "true" if sync_references else "false",
                },
                data={"qids": question_id},
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"question-bank label assignment failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "label assignment was not acknowledged"))
        return payload

    def set_question_bank_question_labels(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        questions: list[str] | str,
        labels: list[str] | str | None,
        *,
        directory_id: str = "0",
        mode: str = "replace",
        sync_references: bool = False,
    ) -> dict[str, Any]:
        question_queries = (
            [questions] if isinstance(questions, str) else [str(item) for item in questions]
        )
        question_queries = [item.strip() for item in question_queries if item.strip()]
        if not question_queries:
            raise ChaoxingAPIError("at least one question-bank question is required")
        if labels is None:
            label_queries: list[str] = []
        elif isinstance(labels, str):
            label_queries = [labels.strip()] if labels.strip() else []
        else:
            label_queries = [str(item).strip() for item in labels if str(item).strip()]
        normalized_mode = str(mode or "replace").strip().lower()
        if normalized_mode not in {"replace", "add", "remove"}:
            raise ChaoxingAPIError("label assignment mode must be replace, add, or remove")
        if normalized_mode in {"add", "remove"} and not label_queries:
            raise ChaoxingAPIError(f"label assignment mode {normalized_mode} requires labels")

        directory_id = str(directory_id or "0")
        items = self._list_all_question_bank_items(
            course,
            clazz,
            directory_id=directory_id,
        )
        resolved_questions: list[dict[str, Any]] = []
        for query in question_queries:
            question = resolve_question_bank_question(items["questions"], query)
            if all(
                existing["question_id"] != question["question_id"]
                for existing in resolved_questions
            ):
                resolved_questions.append(question)
        landing = self._question_bank_landing_context(course, clazz)
        session = landing["session"]
        label_listing = self._question_bank_label_listing(
            session,
            course,
            referer=landing["landing_url"],
        )
        resolved_labels: list[dict[str, Any]] = []
        for query in label_queries:
            label = resolve_question_bank_label(label_listing["labels"], query)
            if all(existing["label_id"] != label["label_id"] for existing in resolved_labels):
                resolved_labels.append(label)
        requested_ids = [item["label_id"] for item in resolved_labels]
        canonical_order = [item["label_id"] for item in label_listing["labels"]]
        changes: list[dict[str, Any]] = []
        messages: list[str] = []
        requests_sent = 0
        for question in resolved_questions:
            before = self._question_bank_label_listing(
                session,
                course,
                referer=landing["landing_url"],
                question_id=question["question_id"],
            )
            current = list(before["checked_ids"])
            if normalized_mode == "replace":
                target_set = set(requested_ids)
            elif normalized_mode == "add":
                target_set = set(current) | set(requested_ids)
            else:
                target_set = set(current) - set(requested_ids)
            target = [label_id for label_id in canonical_order if label_id in target_set]
            source_changed = set(current) != set(target)
            if not source_changed and not sync_references:
                changes.append(
                    {
                        "question": question,
                        "before_label_ids": current,
                        "after_label_ids": current,
                        "changed": False,
                        "sync_requested": False,
                    }
                )
                continue
            payload = self._question_bank_label_assignment_request(
                session,
                course,
                question["question_id"],
                target,
                sync_references=sync_references,
                referer=landing["landing_url"],
            )
            requests_sent += 1
            after = self._question_bank_label_listing(
                session,
                course,
                referer=landing["landing_url"],
                question_id=question["question_id"],
            )
            if set(after["checked_ids"]) != set(target):
                raise ChaoxingAPIError(
                    f"label assignment for question {question['question_id']} was acknowledged "
                    "but read-back differs"
                )
            messages.append(str(payload.get("msg") or ""))
            changes.append(
                {
                    "question": question,
                    "before_label_ids": current,
                    "after_label_ids": after["checked_ids"],
                    "changed": source_changed,
                    "sync_requested": sync_references,
                }
            )
        labels_by_id = {item["label_id"]: item for item in label_listing["labels"]}
        for change in changes:
            change["before_labels"] = [
                labels_by_id[label_id]
                for label_id in change["before_label_ids"]
                if label_id in labels_by_id
            ]
            change["after_labels"] = [
                labels_by_id[label_id]
                for label_id in change["after_label_ids"]
                if label_id in labels_by_id
            ]
        verification = "every source question's selected label IDs match fresh HTTP reads"
        if sync_references:
            verification += (
                "; Chaoxing acknowledged downstream homework/exam synchronization, "
                "which was not individually audited"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "directory_id": directory_id,
            "mode": normalized_mode,
            "sync_references": sync_references,
            "requested_labels": resolved_labels,
            "question_count": len(changes),
            "changed_count": sum(1 for item in changes if item["changed"]),
            "requests_sent": requests_sent,
            "changes": changes,
            "server_messages": messages,
            "verification": verification,
        }

    def _question_bank_topic_listing(
        self,
        session: requests.Session,
        course: dict[str, Any],
        *,
        referer: str,
        question_id: str = "",
        query: str = "",
    ) -> dict[str, Any]:
        try:
            response = session.get(
                MOOC2_BASE_URL + "/mooc2-ans/question-topic/course",
                params={
                    "courseid": course["course_id"],
                    "cpi": course["cpi"],
                    "qid": str(question_id),
                    "workId": "",
                    "paperId": "",
                    "query": str(query),
                    "clazzid": "0",
                    "aiPracticeAssistant": "false",
                },
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"question-bank topic request failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(
                str(message or "question-bank topic request was not acknowledged")
            )
        topics, selected_ids = parse_question_bank_topic_tree(payload)
        return {
            "topics": topics,
            "selected_ids": selected_ids,
            "message": str(payload.get("msg") or ""),
        }

    @staticmethod
    def _question_bank_topic_name(name: str) -> str:
        normalized = str(name or "").strip()
        if not normalized:
            raise ChaoxingAPIError("question-bank topic name is required")
        return normalized

    @staticmethod
    def _question_bank_topic_kind(kind: str) -> tuple[str, str]:
        normalized = str(kind or "knowledge_point").strip().lower().replace("-", "_")
        aliases = {
            "0": ("0", "knowledge_point"),
            "point": ("0", "knowledge_point"),
            "topic": ("0", "knowledge_point"),
            "knowledge_point": ("0", "knowledge_point"),
            "知识点": ("0", "knowledge_point"),
            "1": ("1", "category"),
            "category": ("1", "category"),
            "classification": ("1", "category"),
            "folder": ("1", "category"),
            "分类": ("1", "category"),
        }
        if normalized not in aliases:
            raise ChaoxingAPIError("question-bank topic kind must be knowledge_point or category")
        return aliases[normalized]

    @staticmethod
    def _question_bank_topic_limits(landing_html: str) -> tuple[int, int]:
        hidden = parse_hidden_inputs(landing_html)
        try:
            max_level = int(hidden.get("topicLevels") or 7)
        except (TypeError, ValueError):
            max_level = 7
        try:
            max_relations = int(hidden.get("topicRelationMaxNum") or 50)
        except (TypeError, ValueError):
            max_relations = 50
        return max_level, max_relations

    @staticmethod
    def _ensure_question_bank_topic_editable(landing_html: str) -> dict[str, str]:
        hidden = parse_hidden_inputs(landing_html)
        if str(hidden.get("allowEditGraph") or "true").strip().lower() == "false":
            raise ChaoxingAPIError("this course does not allow editing its knowledge graph")
        if str(hidden.get("hideTopicEditFlag") or "false").strip().lower() == "true":
            raise ChaoxingAPIError("this course hides knowledge-point editing")
        return hidden

    def list_question_bank_topics(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        question_query: str = "",
        directory_id: str = "0",
        search: str = "",
    ) -> dict[str, Any]:
        landing = self._question_bank_landing_context(course, clazz)
        question: dict[str, Any] | None = None
        if question_query.strip():
            items = self._list_all_question_bank_items(
                course,
                clazz,
                directory_id=str(directory_id or "0"),
            )
            question = resolve_question_bank_question(items["questions"], question_query)
        listing = self._question_bank_topic_listing(
            landing["session"],
            course,
            referer=landing["landing_url"],
            question_id=str(question.get("question_id") or "") if question else "",
            query=search,
        )
        max_level, max_relations = self._question_bank_topic_limits(landing["landing_html"])
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "directory_id": str(directory_id or "0"),
            "question": question,
            "search": str(search),
            "count": len(listing["topics"]),
            "topics": listing["topics"],
            "selected_topic_ids": listing["selected_ids"] if question else None,
            "max_level": max_level,
            "max_topics_per_question": max_relations,
            "verification": "parsed the current knowledge-point tree through authenticated HTTP",
        }

    def create_question_bank_topic(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        name: str,
        *,
        kind: str = "knowledge_point",
        parent_topic: str | None = None,
        after_topic: str = "",
    ) -> dict[str, Any]:
        name = self._question_bank_topic_name(name)
        node_type, normalized_kind = self._question_bank_topic_kind(kind)
        landing = self._question_bank_landing_context(course, clazz)
        hidden = self._ensure_question_bank_topic_editable(landing["landing_html"])
        session = landing["session"]
        before_listing = self._question_bank_topic_listing(
            session,
            course,
            referer=landing["landing_url"],
        )
        after: dict[str, Any] | None = None
        if str(after_topic or "").strip():
            after = resolve_question_bank_topic(before_listing["topics"], after_topic)
            inferred_parent = resolve_question_bank_topic(
                before_listing["topics"],
                str(after["parent_id"] or "0"),
                allow_root=True,
            )
        else:
            inferred_parent = resolve_question_bank_topic(
                before_listing["topics"],
                str(parent_topic or "0"),
                allow_root=True,
            )
        if parent_topic is not None and str(parent_topic).strip():
            explicit_parent = resolve_question_bank_topic(
                before_listing["topics"],
                str(parent_topic),
                allow_root=True,
            )
            if after and explicit_parent["topic_id"] != inferred_parent["topic_id"]:
                raise ChaoxingAPIError("after_topic is not a child of parent_topic")
            parent = explicit_parent
        else:
            parent = inferred_parent
        if parent["topic_id"] != "0" and parent.get("kind") != "category":
            raise ChaoxingAPIError("knowledge points can only be created below a category")
        max_level, _ = self._question_bank_topic_limits(landing["landing_html"])
        if int(parent.get("level") or 0) >= max_level:
            raise ChaoxingAPIError(f"question-bank topics cannot exceed {max_level} levels")

        before_ids = {item["topic_id"] for item in before_listing["topics"]}
        payload = self._question_bank_mutation_request(
            session,
            "/mooc2-ans/questionBankTopic/addtopic",
            {
                "cpi": course["cpi"],
                "ut": str(hidden.get("ut") or "t"),
                "courseid": course["course_id"],
                "topic": name,
                "parentId": parent["topic_id"],
                "curOperateTopicId": after["topic_id"] if after else "0",
                "addTopicType": "0" if after else "-1",
                "addNodeType": node_type,
            },
            referer=landing["landing_url"],
            operation="question-bank topic creation",
        )
        refreshed = self._question_bank_topic_listing(
            session,
            course,
            referer=landing["landing_url"],
        )
        returned_id = str(payload.get("topicId") or "").strip()
        created = [
            item
            for item in refreshed["topics"]
            if item["topic_id"] not in before_ids
            and item["parent_id"] == parent["topic_id"]
            and item["name"] == name
            and item["node_type"] == node_type
        ]
        if returned_id:
            created = [item for item in created if item["topic_id"] == returned_id]
        if len(created) != 1:
            raise ChaoxingAPIError(
                "topic creation was acknowledged but exactly one matching node was not found"
            )
        if after:
            sibling_ids = [
                item["topic_id"]
                for item in refreshed["topics"]
                if item["parent_id"] == parent["topic_id"]
            ]
            if (
                sibling_ids.index(created[0]["topic_id"])
                != sibling_ids.index(after["topic_id"]) + 1
            ):
                raise ChaoxingAPIError("the new topic was not inserted after the requested sibling")
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "parent": parent,
            "after_topic": after,
            "topic": created[0],
            "kind": normalized_kind,
            "server_message": str(payload.get("msg") or ""),
            "verification": "the new topic ID, parent, kind, and name match a fresh tree read",
        }

    def rename_question_bank_topic(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        topic_query: str,
        name: str,
    ) -> dict[str, Any]:
        name = self._question_bank_topic_name(name)
        landing = self._question_bank_landing_context(course, clazz)
        self._ensure_question_bank_topic_editable(landing["landing_html"])
        session = landing["session"]
        before_listing = self._question_bank_topic_listing(
            session,
            course,
            referer=landing["landing_url"],
        )
        before = resolve_question_bank_topic(before_listing["topics"], topic_query)
        if before["name"] == name:
            return {
                "course_id": course["course_id"],
                "course_name": course["course_name"],
                "clazz_id": clazz["clazz_id"],
                "clazz_name": clazz["clazz_name"],
                "before": before,
                "after": before,
                "changed": False,
                "verification": "the requested topic name was already present",
            }
        payload = self._question_bank_mutation_request(
            session,
            "/mooc2-ans/questionBankTopic/editTopic",
            {
                "courseid": course["course_id"],
                "topicId": before["topic_id"],
                "topic": name,
            },
            referer=landing["landing_url"],
            operation="question-bank topic rename",
        )
        refreshed = self._question_bank_topic_listing(
            session,
            course,
            referer=landing["landing_url"],
        )
        after = resolve_question_bank_topic(refreshed["topics"], before["topic_id"])
        if after["name"] != name:
            raise ChaoxingAPIError("topic rename was acknowledged but read-back differs")
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "before": before,
            "after": after,
            "changed": True,
            "server_message": str(payload.get("msg") or ""),
            "verification": "the topic name matches a fresh knowledge-point tree read",
        }

    def delete_question_bank_topic(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        topic_query: str,
    ) -> dict[str, Any]:
        landing = self._question_bank_landing_context(course, clazz)
        self._ensure_question_bank_topic_editable(landing["landing_html"])
        session = landing["session"]
        before_listing = self._question_bank_topic_listing(
            session,
            course,
            referer=landing["landing_url"],
        )
        before = resolve_question_bank_topic(before_listing["topics"], topic_query)
        removed_ids = {before["topic_id"]}
        changed = True
        while changed:
            changed = False
            for item in before_listing["topics"]:
                if item["parent_id"] in removed_ids and item["topic_id"] not in removed_ids:
                    removed_ids.add(item["topic_id"])
                    changed = True
        payload = self._question_bank_mutation_request(
            session,
            "/mooc2-ans/questionBankTopic/deleteTopic",
            {"courseid": course["course_id"], "topicId": before["topic_id"]},
            referer=landing["landing_url"],
            operation="question-bank topic deletion",
        )
        refreshed = self._question_bank_topic_listing(
            session,
            course,
            referer=landing["landing_url"],
        )
        remaining_ids = {item["topic_id"] for item in refreshed["topics"]}
        if removed_ids & remaining_ids:
            raise ChaoxingAPIError(
                "topic deletion was acknowledged but the topic or a descendant remains"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "deleted_topic": before,
            "deleted_topic_ids": sorted(removed_ids),
            "server_message": str(payload.get("msg") or ""),
            "verification": "the topic and all descendants are absent from a fresh tree read",
        }

    def _question_bank_topic_assignment_request(
        self,
        session: requests.Session,
        course: dict[str, Any],
        question_id: str,
        topic_ids: list[str],
        *,
        sync_references: bool,
        referer: str,
    ) -> dict[str, Any]:
        topic_field = ",".join(topic_ids) + "," if topic_ids else ""
        try:
            response = session.post(
                MOOC2_BASE_URL + "/mooc2-ans/qbank/update-topic",
                params={
                    "courseid": course["course_id"],
                    "cpi": course["cpi"],
                    "topicIds": topic_field,
                },
                data={
                    "qids": question_id,
                    "updateExamWord": "true" if sync_references else "false",
                    "retainOldTopicRelation": "false",
                },
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"question-bank topic assignment failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "topic assignment was not acknowledged"))
        return payload

    def set_question_bank_question_topics(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        questions: list[str] | str,
        topics: list[str] | str | None,
        *,
        directory_id: str = "0",
        mode: str = "replace",
        sync_references: bool = False,
    ) -> dict[str, Any]:
        question_queries = (
            [questions] if isinstance(questions, str) else [str(item) for item in questions]
        )
        question_queries = [item.strip() for item in question_queries if item.strip()]
        if not question_queries:
            raise ChaoxingAPIError("at least one question-bank question is required")
        if topics is None:
            topic_queries: list[str] = []
        elif isinstance(topics, str):
            topic_queries = [topics.strip()] if topics.strip() else []
        else:
            topic_queries = [str(item).strip() for item in topics if str(item).strip()]
        normalized_mode = str(mode or "replace").strip().lower()
        if normalized_mode not in {"replace", "add", "remove"}:
            raise ChaoxingAPIError("topic assignment mode must be replace, add, or remove")
        if normalized_mode in {"add", "remove"} and not topic_queries:
            raise ChaoxingAPIError(f"topic assignment mode {normalized_mode} requires topics")

        directory_id = str(directory_id or "0")
        items = self._list_all_question_bank_items(course, clazz, directory_id=directory_id)
        resolved_questions: list[dict[str, Any]] = []
        for query in question_queries:
            question = resolve_question_bank_question(items["questions"], query)
            if all(
                existing["question_id"] != question["question_id"]
                for existing in resolved_questions
            ):
                resolved_questions.append(question)
        landing = self._question_bank_landing_context(course, clazz)
        session = landing["session"]
        base_listing = self._question_bank_topic_listing(
            session,
            course,
            referer=landing["landing_url"],
        )
        resolved_topics: list[dict[str, Any]] = []
        for query in topic_queries:
            topic = resolve_question_bank_topic(base_listing["topics"], query)
            if all(existing["topic_id"] != topic["topic_id"] for existing in resolved_topics):
                resolved_topics.append(topic)
        requested_ids = [item["topic_id"] for item in resolved_topics]
        canonical_order = [item["topic_id"] for item in base_listing["topics"]]
        _, max_relations = self._question_bank_topic_limits(landing["landing_html"])
        changes: list[dict[str, Any]] = []
        messages: list[str] = []
        requests_sent = 0
        for question in resolved_questions:
            before = self._question_bank_topic_listing(
                session,
                course,
                referer=landing["landing_url"],
                question_id=question["question_id"],
            )
            current = list(before["selected_ids"])
            if normalized_mode == "replace":
                target_set = set(requested_ids)
            elif normalized_mode == "add":
                target_set = set(current) | set(requested_ids)
            else:
                target_set = set(current) - set(requested_ids)
            target = [topic_id for topic_id in canonical_order if topic_id in target_set]
            target.extend(
                topic_id
                for topic_id in current
                if topic_id in target_set and topic_id not in target
            )
            if max_relations > 0 and len(target) > max_relations:
                raise ChaoxingAPIError(
                    f"a question can be associated with at most {max_relations} topics"
                )
            source_changed = set(current) != set(target)
            if source_changed or sync_references:
                payload = self._question_bank_topic_assignment_request(
                    session,
                    course,
                    question["question_id"],
                    target,
                    sync_references=sync_references,
                    referer=landing["landing_url"],
                )
                requests_sent += 1
                messages.append(str(payload.get("msg") or ""))
                after = self._question_bank_topic_listing(
                    session,
                    course,
                    referer=landing["landing_url"],
                    question_id=question["question_id"],
                )
                if set(after["selected_ids"]) != set(target):
                    raise ChaoxingAPIError(
                        f"topic assignment for question {question['question_id']} was acknowledged "
                        "but read-back differs"
                    )
                after_ids = after["selected_ids"]
            else:
                after_ids = current
            changes.append(
                {
                    "question": question,
                    "before_topic_ids": current,
                    "after_topic_ids": after_ids,
                    "changed": source_changed,
                    "sync_requested": sync_references,
                }
            )
        topics_by_id = {item["topic_id"]: item for item in base_listing["topics"]}

        def describe(topic_id: str) -> dict[str, Any]:
            return topics_by_id.get(
                topic_id,
                {"topic_id": topic_id, "missing_from_current_tree": True},
            )

        for change in changes:
            change["before_topics"] = [
                describe(topic_id) for topic_id in change["before_topic_ids"]
            ]
            change["after_topics"] = [describe(topic_id) for topic_id in change["after_topic_ids"]]
        verification = "every source question's selected topic IDs match fresh HTTP reads"
        if sync_references:
            verification += (
                "; Chaoxing acknowledged downstream homework/exam synchronization, "
                "which was not individually audited"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "directory_id": directory_id,
            "mode": normalized_mode,
            "sync_references": sync_references,
            "requested_topics": resolved_topics,
            "question_count": len(changes),
            "changed_count": sum(1 for item in changes if item["changed"]),
            "requests_sent": requests_sent,
            "changes": changes,
            "server_messages": messages,
            "verification": verification,
        }

    def _question_bank_inactive_page(
        self,
        session: requests.Session,
        course: dict[str, Any],
        *,
        referer: str,
        state: str,
        page: int = 1,
        page_size: int = 0,
        search: str = "",
        directory_id: str = "",
        directory_path_ids: list[str] | str | None = None,
        order: str = "desc",
        lock_time_filters: list[str] | str | None = None,
    ) -> dict[str, Any]:
        normalized_state = str(state or "").strip().lower()
        if normalized_state not in {"recycle", "locked"}:
            raise ChaoxingAPIError("inactive question-bank state must be recycle or locked")
        if page < 1:
            raise ChaoxingAPIError("page must be at least 1")
        if page_size < 0:
            raise ChaoxingAPIError("page_size cannot be negative")
        normalized_order = str(order or "desc").strip().lower()
        if normalized_order not in {"asc", "desc"}:
            raise ChaoxingAPIError("order must be asc or desc")

        def comma_field(value: list[str] | str | None, *, trailing: bool = False) -> str:
            if value is None:
                return ""
            if isinstance(value, str):
                parts = [part.strip() for part in value.split(",") if part.strip()]
            else:
                parts = [str(part).strip() for part in value if str(part).strip()]
            joined = ",".join(parts)
            return joined + "," if joined and trailing else joined

        endpoint = "recycle-search" if normalized_state == "recycle" else "lock-search"
        status = "2" if normalized_state == "recycle" else "3"
        try:
            response = session.post(
                MOOC2_BASE_URL + f"/mooc2-ans/qbank/{endpoint}",
                data={
                    "courseid": course["course_id"],
                    "cpi": course["cpi"],
                    "dirId": str(directory_id or ""),
                    "courseIds": "",
                    "sw": str(search or ""),
                    "pageNum": "" if page == 1 else str(page),
                    "orderType": normalized_order,
                    "pageSize": str(page_size) if page_size else "",
                    "status": status,
                    "dirPathIds": comma_field(directory_path_ids, trailing=True),
                    "lockTimeArr": comma_field(lock_time_filters),
                },
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(
                f"question-bank {normalized_state} listing failed: {exc}"
            ) from exc
        if not isinstance(payload, dict):
            raise ChaoxingAPIError(
                f"question-bank {normalized_state} listing returned an invalid response"
            )
        parsed = parse_question_bank_inactive_items(
            payload,
            state=normalized_state,
            index_offset=max(page - 1, 0) * (page_size or 10),
        )
        parsed.update(
            {
                "state": normalized_state,
                "page": page,
                "requested_page_size": page_size or None,
                "search": str(search or ""),
                "directory_id": str(directory_id or ""),
                "order": normalized_order,
            }
        )
        return parsed

    def list_question_bank_inactive_items(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        state: str,
        page: int = 1,
        page_size: int = 0,
        search: str = "",
        directory_id: str = "",
        directory_path_ids: list[str] | str | None = None,
        order: str = "desc",
        lock_time_filters: list[str] | str | None = None,
    ) -> dict[str, Any]:
        landing = self._question_bank_landing_context(course, clazz)
        listing = self._question_bank_inactive_page(
            landing["session"],
            course,
            referer=landing["landing_url"],
            state=state,
            page=page,
            page_size=page_size,
            search=search,
            directory_id=directory_id,
            directory_path_ids=directory_path_ids,
            order=order,
            lock_time_filters=lock_time_filters,
        )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            **listing,
            "count": len(listing["items"]),
            "verification": f"read the current question-bank {listing['state']} page through HTTP",
        }

    def _resolve_question_bank_inactive_items(
        self,
        session: requests.Session,
        course: dict[str, Any],
        queries: list[str] | str,
        *,
        state: str,
        referer: str,
        directory_id: str = "",
        directory_path_ids: list[str] | str | None = None,
    ) -> list[dict[str, Any]]:
        query_list = [queries] if isinstance(queries, str) else [str(item) for item in queries]
        query_list = [item.strip() for item in query_list if item.strip()]
        if not query_list:
            raise ChaoxingAPIError("at least one inactive question-bank item is required")
        base = self._question_bank_inactive_page(
            session,
            course,
            referer=referer,
            state=state,
            directory_id=directory_id,
            directory_path_ids=directory_path_ids,
        )
        candidates = list(base["items"])
        total_pages = 1
        try:
            total_pages = max(int(base["page_info"].get("totalPage") or 1), 1)
        except (TypeError, ValueError):
            total_pages = 1
        for page in range(2, min(total_pages, 100) + 1):
            page_data = self._question_bank_inactive_page(
                session,
                course,
                referer=referer,
                state=state,
                page=page,
                directory_id=directory_id,
                directory_path_ids=directory_path_ids,
            )
            candidates.extend(page_data["items"])
        unique = {item["item_id"]: item for item in candidates}
        resolved: list[dict[str, Any]] = []
        for query in query_list:
            try:
                item = resolve_question_bank_inactive_item(list(unique.values()), query)
            except ChaoxingAPIError as initial_error:
                searched = self._question_bank_inactive_page(
                    session,
                    course,
                    referer=referer,
                    state=state,
                    search=query,
                    directory_id=directory_id,
                    directory_path_ids=directory_path_ids,
                )
                for found in searched["items"]:
                    unique[found["item_id"]] = found
                try:
                    item = resolve_question_bank_inactive_item(list(unique.values()), query)
                except ChaoxingAPIError:
                    raise initial_error from None
            if all(existing["item_id"] != item["item_id"] for existing in resolved):
                resolved.append(item)
        return resolved

    def _question_bank_batch_status_request(
        self,
        session: requests.Session,
        course: dict[str, Any],
        *,
        question_ids: list[str],
        directory_ids: list[str],
        status: str,
        referer: str,
        lock_from_active: bool = False,
    ) -> dict[str, Any]:
        if not question_ids and not directory_ids:
            raise ChaoxingAPIError("at least one question or directory is required")
        data: dict[str, Any] = {
            "courseid": course["course_id"],
            "questionIds": ",".join(question_ids),
            "dirIds": ",".join(directory_ids),
            "status": str(status),
        }
        method = "get"
        if lock_from_active:
            method = "post"
            data["cpi"] = course["cpi"]
            data["curStatus"] = "0"
        try:
            response = getattr(session, method)(
                MOOC2_BASE_URL + "/mooc2-ans/qbank/batch-updatestatus",
                **({"data": data} if method == "post" else {"params": data}),
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"question-bank status update failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(
                str(message or "question-bank status update was not acknowledged")
            )
        return payload

    def lock_question_bank_items(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        questions: list[str] | str | None = None,
        directories: list[str] | str | None = None,
        directory_id: str = "0",
    ) -> dict[str, Any]:
        question_queries = (
            []
            if questions is None
            else [questions]
            if isinstance(questions, str)
            else [str(item) for item in questions]
        )
        directory_queries = (
            []
            if directories is None
            else [directories]
            if isinstance(directories, str)
            else [str(item) for item in directories]
        )
        question_queries = [item.strip() for item in question_queries if item.strip()]
        directory_queries = [item.strip() for item in directory_queries if item.strip()]
        if not question_queries and not directory_queries:
            raise ChaoxingAPIError("at least one active question or directory is required")
        directory_id = str(directory_id or "0")
        active_items = self._list_all_question_bank_items(
            course,
            clazz,
            directory_id=directory_id,
        )
        resolved_questions: list[dict[str, Any]] = []
        for query in question_queries:
            question = resolve_question_bank_question(active_items["questions"], query)
            if str(question.get("origin_type") or "") not in QUESTION_BANK_LOCKABLE_ORIGIN_TYPES:
                raise ChaoxingAPIError(
                    f"question type {question.get('origin_type')} cannot be locked "
                    "in the current UI"
                )
            if all(
                existing["question_id"] != question["question_id"]
                for existing in resolved_questions
            ):
                resolved_questions.append(question)
        landing = self._question_bank_landing_context(course, clazz)
        tree = self._question_bank_directory_tree(
            landing["session"],
            course,
            referer=landing["landing_url"],
        )
        resolved_directories: list[dict[str, Any]] = []
        for query in directory_queries:
            directory = resolve_question_bank_directory(tree, query)
            if all(
                existing["directory_id"] != directory["directory_id"]
                for existing in resolved_directories
            ):
                resolved_directories.append(directory)
        payload = self._question_bank_batch_status_request(
            landing["session"],
            course,
            question_ids=[item["question_id"] for item in resolved_questions],
            directory_ids=[item["directory_id"] for item in resolved_directories],
            status="3",
            referer=landing["landing_url"],
            lock_from_active=True,
        )
        refreshed_questions = self._list_all_question_bank_items(
            course,
            clazz,
            directory_id=directory_id,
        )["questions"]
        remaining_question_ids = {item["question_id"] for item in refreshed_questions}
        refreshed_tree = self._question_bank_directory_tree(
            landing["session"],
            course,
            referer=landing["landing_url"],
        )
        remaining_directory_ids = {item["directory_id"] for item in refreshed_tree}
        requested_question_ids = {item["question_id"] for item in resolved_questions}
        requested_directory_ids = {item["directory_id"] for item in resolved_directories}
        if requested_question_ids & remaining_question_ids:
            raise ChaoxingAPIError("locking was acknowledged but a question remains active")
        if requested_directory_ids & remaining_directory_ids:
            raise ChaoxingAPIError("locking was acknowledged but a directory remains active")
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "directory_id": directory_id,
            "questions": resolved_questions,
            "directories": resolved_directories,
            "server_message": str(payload.get("msg") or ""),
            "verification": (
                "all requested IDs are absent from fresh active question/directory reads"
            ),
        }

    def transition_question_bank_inactive_items(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        items: list[str] | str,
        *,
        source_state: str,
        operation: str,
        directory_id: str = "",
        directory_path_ids: list[str] | str | None = None,
    ) -> dict[str, Any]:
        normalized_source = str(source_state or "").strip().lower()
        normalized_operation = str(operation or "").strip().lower()
        expected = {
            ("recycle", "restore"): "0",
            ("recycle", "delete"): "1",
            ("locked", "unlock"): "0",
        }
        status = expected.get((normalized_source, normalized_operation))
        if status is None:
            raise ChaoxingAPIError("unsupported inactive question-bank transition")
        landing = self._question_bank_landing_context(course, clazz)
        resolved = self._resolve_question_bank_inactive_items(
            landing["session"],
            course,
            items,
            state=normalized_source,
            referer=landing["landing_url"],
            directory_id=directory_id,
            directory_path_ids=directory_path_ids,
        )
        payload = self._question_bank_batch_status_request(
            landing["session"],
            course,
            question_ids=[item["item_id"] for item in resolved if item["item_type"] == "question"],
            directory_ids=[
                item["item_id"] for item in resolved if item["item_type"] == "directory"
            ],
            status=status,
            referer=landing["landing_url"],
        )
        remaining_ids: set[str] = set()
        for item in resolved:
            refreshed = self._question_bank_inactive_page(
                landing["session"],
                course,
                referer=landing["landing_url"],
                state=normalized_source,
                search=item["name"],
                directory_id=directory_id,
                directory_path_ids=directory_path_ids,
            )
            remaining_ids.update(found["item_id"] for found in refreshed["items"])
        requested_ids = {item["item_id"] for item in resolved}
        if requested_ids & remaining_ids:
            raise ChaoxingAPIError(
                f"question-bank {normalized_operation} was acknowledged but an item remains"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "source_state": normalized_source,
            "operation": normalized_operation,
            "items": resolved,
            "server_message": str(payload.get("msg") or ""),
            "verification": f"all requested IDs are absent from fresh {normalized_source} reads",
        }

    def empty_question_bank_recycle_bin(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> dict[str, Any]:
        landing = self._question_bank_landing_context(course, clazz)
        before = self._question_bank_inactive_page(
            landing["session"],
            course,
            referer=landing["landing_url"],
            state="recycle",
        )
        try:
            response = landing["session"].get(
                MOOC2_BASE_URL + "/mooc2-ans/qbank/empty-recycle",
                params={"courseid": course["course_id"], "cpi": course["cpi"]},
                timeout=self.timeout,
                headers={
                    "Referer": landing["landing_url"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"emptying the question-bank recycle bin failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "empty recycle-bin request was not acknowledged"))
        after = self._question_bank_inactive_page(
            landing["session"],
            course,
            referer=landing["landing_url"],
            state="recycle",
        )
        if after["items"]:
            raise ChaoxingAPIError("empty recycle-bin request succeeded but root items remain")
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "root_item_count_before": len(before["items"]),
            "root_item_count_after": len(after["items"]),
            "server_message": str(payload.get("msg") or ""),
            "verification": "a fresh recycle-bin root read contains no items",
        }

    @staticmethod
    def _question_bank_directory_name(name: str) -> str:
        normalized = str(name or "").strip()
        if not normalized:
            raise ChaoxingAPIError("question-bank directory name is required")
        return normalized

    def create_question_bank_directory(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        name: str,
        *,
        parent_directory: str = "0",
    ) -> dict[str, Any]:
        name = self._question_bank_directory_name(name)
        landing = self._question_bank_landing_context(course, clazz)
        session = landing["session"]
        before = self._question_bank_directory_tree(
            session,
            course,
            referer=landing["landing_url"],
        )
        parent = resolve_question_bank_directory(before, parent_directory, allow_root=True)
        before_ids = {item["directory_id"] for item in before}
        payload = self._question_bank_mutation_request(
            session,
            "/mooc2-ans/qbank/insertdir",
            {
                "dirName": name,
                "courseid": course["course_id"],
                "pid": parent["directory_id"],
                "cpi": course["cpi"],
            },
            referer=landing["landing_url"],
            operation="question-bank directory creation",
        )
        refreshed = self._question_bank_directory_tree(
            session,
            course,
            referer=landing["landing_url"],
        )
        created = [
            item
            for item in refreshed
            if item["directory_id"] not in before_ids
            and item["parent_id"] == parent["directory_id"]
            and item["name"] == name
        ]
        returned_id = str(payload.get("id") or payload.get("dirId") or "").strip()
        if returned_id:
            created = [item for item in created if item["directory_id"] == returned_id]
        if len(created) != 1:
            raise ChaoxingAPIError(
                "directory creation was acknowledged but exactly one new matching directory "
                "was not found"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "parent": parent,
            "directory": created[0],
            "server_message": str(payload.get("msg") or ""),
            "verification": "the new directory ID, parent, and name match the refreshed tree",
        }

    def rename_question_bank_directory(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        directory_query: str,
        name: str,
    ) -> dict[str, Any]:
        name = self._question_bank_directory_name(name)
        landing = self._question_bank_landing_context(course, clazz)
        session = landing["session"]
        before_tree = self._question_bank_directory_tree(
            session,
            course,
            referer=landing["landing_url"],
        )
        before = resolve_question_bank_directory(before_tree, directory_query)
        payload = self._question_bank_mutation_request(
            session,
            "/mooc2-ans/qbank/update-dirname",
            {
                "dirName": name,
                "courseid": course["course_id"],
                "pid": before["parent_id"],
                "cpi": course["cpi"],
                "id": before["directory_id"],
            },
            referer=landing["landing_url"],
            operation="question-bank directory rename",
        )
        refreshed = self._question_bank_directory_tree(
            session,
            course,
            referer=landing["landing_url"],
        )
        after = resolve_question_bank_directory(refreshed, before["directory_id"])
        if after["name"] != name:
            raise ChaoxingAPIError(
                "directory rename was acknowledged but the refreshed name differs"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "before": before,
            "after": after,
            "server_message": str(payload.get("msg") or ""),
            "verification": "the directory name matches the refreshed tree",
        }

    def move_question_bank_directory(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        directory_query: str,
        target_directory_query: str,
    ) -> dict[str, Any]:
        landing = self._question_bank_landing_context(course, clazz)
        session = landing["session"]
        before_tree = self._question_bank_directory_tree(
            session,
            course,
            referer=landing["landing_url"],
        )
        source = resolve_question_bank_directory(before_tree, directory_query)
        target = resolve_question_bank_directory(
            before_tree, target_directory_query, allow_root=True
        )
        if source["directory_id"] == target["directory_id"]:
            raise ChaoxingAPIError("a question-bank directory cannot be moved into itself")
        parent_by_id = {item["directory_id"]: item["parent_id"] for item in before_tree}
        ancestor_id = target["directory_id"]
        while ancestor_id != "0" and ancestor_id in parent_by_id:
            if ancestor_id == source["directory_id"]:
                raise ChaoxingAPIError(
                    "a question-bank directory cannot be moved into one of its descendants"
                )
            ancestor_id = parent_by_id[ancestor_id]
        if source["parent_id"] == target["directory_id"]:
            return {
                "course_id": course["course_id"],
                "course_name": course["course_name"],
                "clazz_id": clazz["clazz_id"],
                "clazz_name": clazz["clazz_name"],
                "directory": source,
                "target": target,
                "changed": False,
                "verification": "the directory is already in the requested parent",
            }
        payload = self._question_bank_mutation_request(
            session,
            "/mooc2-ans/qbank/update-pid",
            {
                "courseid": course["course_id"],
                "cpi": course["cpi"],
                "operateId": source["directory_id"],
                "operateCourseId": source.get("course_id") or course["course_id"],
                "type": "0",
                "newPid": target["directory_id"],
            },
            referer=landing["landing_url"],
            operation="question-bank directory move",
        )
        refreshed = self._question_bank_directory_tree(
            session,
            course,
            referer=landing["landing_url"],
        )
        after = resolve_question_bank_directory(refreshed, source["directory_id"])
        if after["parent_id"] != target["directory_id"]:
            raise ChaoxingAPIError(
                "directory move was acknowledged but the refreshed parent differs"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "before": source,
            "target": target,
            "after": after,
            "changed": True,
            "server_message": str(payload.get("msg") or ""),
            "verification": "the directory parent matches the refreshed tree",
        }

    def set_question_bank_directory_top(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        directory_query: str,
        top: bool,
    ) -> dict[str, Any]:
        landing = self._question_bank_landing_context(course, clazz)
        session = landing["session"]
        before_tree = self._question_bank_directory_tree(
            session,
            course,
            referer=landing["landing_url"],
        )
        before = resolve_question_bank_directory(before_tree, directory_query)
        if bool(before.get("is_top")) == top:
            return {
                "course_id": course["course_id"],
                "course_name": course["course_name"],
                "clazz_id": clazz["clazz_id"],
                "clazz_name": clazz["clazz_name"],
                "before": before,
                "after": before,
                "changed": False,
                "verification": "the requested top status was already present",
            }
        payload = self._question_bank_mutation_request(
            session,
            "/mooc2-ans/qbank/update-top",
            {
                "courseid": course["course_id"],
                "cpi": course["cpi"],
                "dirId": before["directory_id"],
                "top": "1" if top else "0",
            },
            referer=landing["landing_url"],
            operation="question-bank directory top-status update",
        )
        refreshed = self._question_bank_directory_tree(
            session,
            course,
            referer=landing["landing_url"],
        )
        after = resolve_question_bank_directory(refreshed, before["directory_id"])
        if bool(after.get("is_top")) != top:
            raise ChaoxingAPIError(
                "directory top-status update was acknowledged but read-back differs"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "before": before,
            "after": after,
            "changed": True,
            "server_message": str(payload.get("msg") or ""),
            "verification": "the directory top status matches the refreshed tree",
        }

    def delete_question_bank_directory(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        directory_query: str,
    ) -> dict[str, Any]:
        landing = self._question_bank_landing_context(course, clazz)
        session = landing["session"]
        before_tree = self._question_bank_directory_tree(
            session,
            course,
            referer=landing["landing_url"],
        )
        before = resolve_question_bank_directory(before_tree, directory_query)
        payload = self._question_bank_mutation_request(
            session,
            "/mooc2-ans/qbank/deal-recycle",
            {
                "courseid": course["course_id"],
                "id": before["directory_id"],
                "status": "2",
                "cpi": course["cpi"],
                "type": "0",
            },
            referer=landing["landing_url"],
            operation="question-bank directory recycle",
        )
        refreshed = self._question_bank_directory_tree(
            session,
            course,
            referer=landing["landing_url"],
        )
        if any(item["directory_id"] == before["directory_id"] for item in refreshed):
            raise ChaoxingAPIError(
                "directory recycle was acknowledged but it remains in the active tree"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "deleted": before,
            "server_message": str(payload.get("msg") or ""),
            "verification": "the directory is absent from the refreshed active tree",
        }

    def list_question_bank(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        page: int = 1,
        page_size: int = 30,
        search: str = "",
        directory_id: str = "0",
    ) -> dict[str, Any]:
        if page < 1:
            raise ChaoxingAPIError("page must be at least 1")
        if not 1 <= page_size <= 100:
            raise ChaoxingAPIError("page_size must be between 1 and 100")
        session = self._session()
        context = self._course_context(session, course, clazz)
        module = resolve_module(context["modules"], "题库")
        qbank_url = self._module_url(context, module, course, clazz)
        try:
            landing = session.get(
                qbank_url,
                timeout=self.timeout,
                allow_redirects=True,
                headers={"Referer": str(context["final_url"])},
            )
            landing.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"question bank request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in landing.url.lower():
            raise ChaoxingAPIError(f"question bank request was redirected to login: {landing.url}")

        data = {
            "courseid": course["course_id"],
            "microTopicId": "0",
            "cpi": course["cpi"],
            "dirId": directory_id,
            "courseIds": course["course_id"],
            "qTypes": "",
            "eTypes": "",
            "difficulty": "",
            "sw": search,
            "pageNum": str(page),
            "pageSize": str(page_size),
            "fromEdit": "false",
            "topicIds": "",
            "courseTargetIds": "",
            "labelIds": "",
            "createrId": "",
            "needHtml": "true",
            "hideEditBtn": "false",
            "qbanksystem": "0",
            "hideLockDir": "false",
            "dirCourseId": course["course_id"],
            "topicIdStatus": "-1",
            "rightPercentFrom": "",
            "rightPercentTo": "",
            "orderType": "",
            "orderByType": "",
            "orderByRight": "",
            "orderByName": "",
        }
        try:
            response = session.post(
                QBANK_SEARCH_URL,
                data=data,
                timeout=self.timeout,
                allow_redirects=True,
                headers={"Referer": landing.url},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"question bank search failed: {exc}") from exc
        html = self._decode(response)
        directories, questions = parse_question_bank_items(html)
        hidden = parse_hidden_inputs(html)

        def hidden_int(name: str, default: int) -> int:
            try:
                return int(hidden.get(name) or default)
            except (TypeError, ValueError):
                return default

        total_questions_match = re.search(r"id=['\"]sumNum['\"][^>]*>\s*共\s*(\d+)\s*题", html)
        total_questions = int(total_questions_match.group(1)) if total_questions_match else None
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "directory_id": directory_id,
            "search": search,
            "page": hidden_int("currentPageNo", page),
            "page_size": page_size,
            "page_count": hidden_int("totalPage", 1),
            "total_result_count": hidden_int("totalResult", len(directories) + len(questions)),
            "total_question_count": total_questions,
            "allow_sort": str(hidden.get("allowSort") or "").lower() == "true",
            "directory_count": len(directories),
            "question_count": len(questions),
            "directories": directories,
            "questions": questions,
            "verification": (
                f"parsed {len(directories)} directories and {len(questions)} questions "
                f"from HTTP page {page}"
            ),
        }

    def read_question_bank_question(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        question_query: str,
        *,
        directory_id: str = "0",
    ) -> dict[str, Any]:
        searched = self.list_question_bank(
            course,
            clazz,
            page=1,
            page_size=100,
            search=question_query,
            directory_id=directory_id,
        )
        pages_read = 1
        questions = list(searched["questions"])
        if questions:
            question = resolve_question_bank_question(questions, question_query)
        else:
            first = self.list_question_bank(
                course,
                clazz,
                page=1,
                page_size=100,
                directory_id=directory_id,
            )
            pages_read += 1
            questions = list(first["questions"])
            page_count = min(int(first["page_count"]), 100)
            for page in range(2, page_count + 1):
                current = self.list_question_bank(
                    course,
                    clazz,
                    page=page,
                    page_size=100,
                    directory_id=directory_id,
                )
                questions.extend(current["questions"])
                pages_read += 1
            question = resolve_question_bank_question(questions, question_query)
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "directory_id": directory_id,
            "question": question,
            "verification": (
                "resolved and parsed the complete question, answer, and assets from "
                f"{pages_read} authenticated question-bank HTTP response(s)"
            ),
        }

    def _question_bank_question_shell(
        self,
        session: requests.Session,
        course: dict[str, Any],
        *,
        directory_id: str,
        referer: str,
        question: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        editing = question is not None
        path = "/mooc2-ans/qbank/edit-question" if editing else "/mooc2-ans/qbank/create-question"
        params = {
            "courseid": course["course_id"],
            "cpi": course["cpi"],
            "dirId": str(directory_id),
            "pageNum": "1",
            "curCourseId": (
                str(question.get("course_id") or course["course_id"])
                if question
                else str(course["course_id"])
            ),
            "qbanksystem": "0",
            "microTopicId": "0",
        }
        if question:
            params.update(
                {
                    "questionBankId": str(question["question_id"]),
                    "indexNum": str(max(0, int(question.get("index") or 1) - 1)),
                }
            )
        try:
            response = session.get(
                MOOC2_BASE_URL + path,
                params=params,
                timeout=self.timeout,
                allow_redirects=True,
                headers={"Referer": referer},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"question-bank editor request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError(
                f"question-bank editor request was redirected to login: {response.url}"
            )
        html = self._decode(response)
        hidden = parse_hidden_inputs(html)
        if str(hidden.get("courseid") or "") != str(course["course_id"]):
            raise ChaoxingAPIError("question-bank editor returned a different course context")
        if question and str(hidden.get("questionBankId") or "") != str(question["question_id"]):
            raise ChaoxingAPIError("question-bank editor returned a different question ID")
        return {
            "html": html,
            "hidden": hidden,
            "referer": response.url,
            "editing": editing,
        }

    def _question_bank_question_detail_html(
        self,
        session: requests.Session,
        course: dict[str, Any],
        shell: dict[str, Any],
        question_type_code: str,
        *,
        course_question_type_id: str = "0",
    ) -> str:
        hidden = shell["hidden"]
        try:
            response = session.get(
                MOOC2_BASE_URL + "/mooc2-ans/qbank/editdetails",
                params={
                    "isNewVersionTopic": str(hidden.get("isNewVersionTopic") or ""),
                    "cpi": course["cpi"],
                    "courseQuestionTypeId": str(course_question_type_id or "0"),
                    "originType": str(question_type_code),
                    "questionBankId": str(hidden.get("questionBankId") or ""),
                    "courseid": course["course_id"],
                    "curCourseId": str(hidden.get("curCourseId") or course["course_id"]),
                    "qbankScoreEdit": str(hidden.get("qbankScoreEdit") or "false"),
                },
                timeout=self.timeout,
                allow_redirects=True,
                headers={"Referer": shell["referer"]},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"question-bank question-detail request failed: {exc}") from exc
        html = self._decode(response)
        if not _control_values(_html_form_controls(html), "content"):
            raise ChaoxingAPIError("question-bank question detail did not expose an editable stem")
        return html

    def _compose_question_bank_question_form(
        self,
        shell: dict[str, Any],
        detail_html: str,
        question_type_code: str,
        *,
        stem: str | None = None,
        options: Any = None,
        correct_answer: Any = None,
        answers: list[str] | None = None,
        answer: Any = None,
        analysis: str | None = None,
        difficulty: Any = None,
        content_format: str = "plain",
        creating: bool = False,
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        type_code = str(question_type_code)
        if type_code not in EXAM_CORE_QUESTION_TYPES:
            raise ChaoxingAPIError(
                f"question-bank type {type_code} is not supported by the core editor"
            )
        current = parse_exam_question_detail(
            detail_html,
            question_id=str(shell["hidden"].get("questionBankId") or ""),
            question_type_code=type_code,
        )
        form: dict[str, Any] = {
            name: value
            for name, value in (
                _html_form_controls(shell["html"]) + _html_form_controls(detail_html)
            )
        }
        form["originType"] = type_code
        form["qType"] = type_code

        if stem is not None:
            stem_html = self._question_rich_text(stem, content_format, "question stem")
        elif creating:
            raise ChaoxingAPIError("question stem is required")
        else:
            stem_html = str(current.get("stem_html") or "")
        if not html_text(stem_html) and not parse_content_images(stem_html):
            raise ChaoxingAPIError("question stem cannot be empty")
        form["content"] = stem_html

        if analysis is not None:
            analysis_html = self._question_rich_text(
                analysis,
                content_format,
                "answer analysis",
                allow_empty=True,
            )
        elif creating:
            analysis_html = ""
        else:
            analysis_html = str(current.get("answer_analysis_html") or "")
        form["answerAnalysis"] = analysis_html

        if difficulty is not None:
            normalized_difficulty = self._question_difficulty(difficulty)
        elif creating:
            normalized_difficulty = 0.8
        else:
            normalized_difficulty = self._question_difficulty(current.get("difficulty"))
        form["difficulty"] = str(normalized_difficulty)

        expected: dict[str, Any] = {
            "question_type": EXAM_CORE_QUESTION_TYPES[type_code]["key"],
            "stem": html_text(stem_html),
            "answer_analysis": html_text(analysis_html),
            "difficulty": normalized_difficulty,
        }

        if type_code in {"0", "1"}:
            if options is not None:
                normalized_options = self._question_choice_options(options)
                option_html = {
                    label: self._question_rich_text(
                        value,
                        content_format,
                        f"option {label}",
                    )
                    for label, value in normalized_options.items()
                }
            elif creating:
                raise ChaoxingAPIError("choice options are required")
            else:
                option_html = {
                    str(item["label"]): str(item.get("html") or "")
                    for item in current.get("options", [])
                }
                normalized_options = {
                    label: html_text(value) for label, value in option_html.items()
                }
            if correct_answer is not None:
                normalized_answers = self._question_choice_answers(correct_answer)
            elif creating:
                raise ChaoxingAPIError("correct_answer is required for a choice question")
            else:
                current_answer = current.get("answer")
                normalized_answers = (
                    [str(current_answer)]
                    if type_code == "0"
                    else [str(item) for item in current_answer or []]
                )
            if any(label not in normalized_options for label in normalized_answers):
                raise ChaoxingAPIError("correct_answer refers to a missing option")
            if type_code == "0" and len(normalized_answers) != 1:
                raise ChaoxingAPIError("single-choice questions require exactly one answer")
            for key in [key for key in form if re.fullmatch(r"[A-Z]", key)]:
                form.pop(key)
            form.update(option_html)
            form["defAnswer"] = normalized_answers[0] if type_code == "0" else normalized_answers
            expected["options"] = [
                {"label": label, "text": html_text(value)} for label, value in option_html.items()
            ]
            expected["answer"] = normalized_answers[0] if type_code == "0" else normalized_answers
        elif type_code == "2":
            if answers is not None:
                if not isinstance(answers, list) or not answers:
                    raise ChaoxingAPIError("fill-blank answers must be a non-empty list")
                answer_html = [
                    self._question_rich_text(item, content_format, f"answer {index}")
                    for index, item in enumerate(answers, 1)
                ]
            elif creating:
                raise ChaoxingAPIError("fill-blank answers are required")
            else:
                answer_html = [str(item.get("html") or "") for item in current.get("answer", [])]
            if not answer_html:
                raise ChaoxingAPIError("fill-blank answers cannot be empty")
            for key in [key for key in form if key.isdigit()]:
                form.pop(key)
            for index, value in enumerate(answer_html, 1):
                form[str(index)] = value
            form["answer"] = "★".join(answer_html)
            form["isMutex"] = str(current.get("is_mutex") or "")
            form["blankSubject"] = "1" if current.get("blank_subject") else "0"
            expected["answer"] = [
                {"blank": index, "text": html_text(value)}
                for index, value in enumerate(answer_html, 1)
            ]
        elif type_code == "3":
            if answer is not None:
                boolean_answer = self._question_boolean_answer(answer)
            elif creating:
                raise ChaoxingAPIError("true/false answer is required")
            elif current.get("answer") is None:
                raise ChaoxingAPIError("current true/false answer could not be read")
            else:
                boolean_answer = bool(current["answer"])
            form["answerForTF"] = str(boolean_answer).lower()
            expected["answer"] = boolean_answer
        else:
            if answer is not None:
                answer_html = self._question_rich_text(
                    str(answer),
                    content_format,
                    "reference answer",
                    allow_empty=True,
                )
            elif creating:
                answer_html = ""
            else:
                answer_html = str(current.get("answer_html") or "")
            form["answer"] = answer_html
            form["wordMinNum"] = str(current.get("word_min") or "0")
            form["wordnum"] = str(current.get("word_max") or "0")
            form["saveScorePoints"] = str(current.get("score_points") or "")
            expected["answer"] = html_text(answer_html)
        return form, expected

    def _save_question_bank_question(
        self,
        session: requests.Session,
        course: dict[str, Any],
        shell: dict[str, Any],
        form: dict[str, Any],
    ) -> dict[str, Any]:
        question_id = str(shell["hidden"].get("questionBankId") or "")
        try:
            response = session.post(
                MOOC2_BASE_URL + "/mooc2-ans/qbank/add_question",
                params={
                    "questionBankId": question_id,
                    "courseid": course["course_id"],
                    "microTopicId": str(shell["hidden"].get("microTopicId") or "0"),
                    "saveAsNew": "false",
                    "promptId": str(form.get("promptId") or "-1"),
                    "useAi": str(form.get("useAi") or "0"),
                    "autoScore": str(form.get("autoScore") or "0"),
                    "aiOptimized": str(form.get("aiOptimized") or ""),
                },
                data=form,
                timeout=self.timeout,
                headers={
                    "Referer": shell["referer"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"question-bank question save failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(
                str(message or "question-bank question save was not acknowledged")
            )
        returned_id = str(payload.get("qid") or question_id).strip()
        if not returned_id:
            raise ChaoxingAPIError("question-bank question save returned no question ID")
        if question_id and returned_id != question_id:
            raise ChaoxingAPIError("question-bank update returned a different question ID")
        payload["resolved_question_id"] = returned_id
        return payload

    def _read_question_bank_question_from_editor(
        self,
        session: requests.Session,
        course: dict[str, Any],
        question: dict[str, Any],
        *,
        directory_id: str,
        referer: str,
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        shell = self._question_bank_question_shell(
            session,
            course,
            directory_id=directory_id,
            referer=referer,
            question=question,
        )
        type_code = str(shell["hidden"].get("originType") or question.get("origin_type") or "")
        course_type_id = str(
            shell["hidden"].get("courseQuestionTypeId")
            or question.get("course_question_type_id")
            or "0"
        )
        detail_html = self._question_bank_question_detail_html(
            session,
            course,
            shell,
            type_code,
            course_question_type_id=course_type_id,
        )
        detail = parse_exam_question_detail(
            detail_html,
            question_id=str(question["question_id"]),
            question_type_code=type_code,
        )
        detail["directory_id"] = str(directory_id)
        detail["course_question_type_id"] = course_type_id
        return shell, detail

    def add_question_bank_question(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        question_type: str,
        stem: str,
        *,
        directory: str = "0",
        options: Any = None,
        correct_answer: Any = None,
        answers: list[str] | None = None,
        answer: Any = None,
        analysis: str = "",
        difficulty: Any = 0.8,
        content_format: str = "plain",
    ) -> dict[str, Any]:
        type_code = normalize_exam_question_type(question_type)
        landing = self._question_bank_landing_context(course, clazz)
        session = landing["session"]
        tree = self._question_bank_directory_tree(
            session,
            course,
            referer=landing["landing_url"],
        )
        target = resolve_question_bank_directory(tree, directory, allow_root=True)
        shell = self._question_bank_question_shell(
            session,
            course,
            directory_id=target["directory_id"],
            referer=landing["landing_url"],
        )
        detail_html = self._question_bank_question_detail_html(
            session,
            course,
            shell,
            type_code,
        )
        form, expected = self._compose_question_bank_question_form(
            shell,
            detail_html,
            type_code,
            stem=stem,
            options=options,
            correct_answer=correct_answer,
            answers=answers,
            answer=answer,
            analysis=analysis,
            difficulty=difficulty,
            content_format=content_format,
            creating=True,
        )
        payload = self._save_question_bank_question(session, course, shell, form)
        question_id = str(payload["resolved_question_id"])
        question_metadata = {
            "question_id": question_id,
            "course_id": str(course["course_id"]),
            "origin_type": type_code,
            "course_question_type_id": "0",
            "index": 1,
        }
        _saved_shell, actual = self._read_question_bank_question_from_editor(
            session,
            course,
            question_metadata,
            directory_id=target["directory_id"],
            referer=landing["landing_url"],
        )
        self._verify_exam_question_fields(actual, expected)
        directory_items = self._list_all_question_bank_items(
            course,
            clazz,
            directory_id=target["directory_id"],
        )
        if not any(item["question_id"] == question_id for item in directory_items["questions"]):
            raise ChaoxingAPIError(
                "question save was verified in the editor but is absent from the target directory"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "directory": target,
            "question": actual,
            "server_message": str(payload.get("msg") or ""),
            "verification": (
                "the new question fields match the editor read-back and its ID is present in "
                "the target directory"
            ),
        }

    def update_question_bank_question(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        question_query: str,
        *,
        directory_id: str = "0",
        stem: str | None = None,
        options: Any = None,
        correct_answer: Any = None,
        answers: list[str] | None = None,
        answer: Any = None,
        analysis: str | None = None,
        difficulty: Any = None,
        content_format: str = "plain",
    ) -> dict[str, Any]:
        if all(
            value is None
            for value in (
                stem,
                options,
                correct_answer,
                answers,
                answer,
                analysis,
                difficulty,
            )
        ):
            raise ChaoxingAPIError("at least one question-bank field must be updated")
        directory_id = str(directory_id or "0")
        items = self._list_all_question_bank_items(
            course,
            clazz,
            directory_id=directory_id,
        )
        question = resolve_question_bank_question(items["questions"], question_query)
        landing = self._question_bank_landing_context(course, clazz)
        session = landing["session"]
        shell, before = self._read_question_bank_question_from_editor(
            session,
            course,
            question,
            directory_id=directory_id,
            referer=landing["landing_url"],
        )
        type_code = str(shell["hidden"].get("originType") or question.get("origin_type") or "")
        detail_html = self._question_bank_question_detail_html(
            session,
            course,
            shell,
            type_code,
            course_question_type_id=str(shell["hidden"].get("courseQuestionTypeId") or "0"),
        )
        form, expected = self._compose_question_bank_question_form(
            shell,
            detail_html,
            type_code,
            stem=stem,
            options=options,
            correct_answer=correct_answer,
            answers=answers,
            answer=answer,
            analysis=analysis,
            difficulty=difficulty,
            content_format=content_format,
            creating=False,
        )
        payload = self._save_question_bank_question(session, course, shell, form)
        _fresh_shell, after = self._read_question_bank_question_from_editor(
            session,
            course,
            question,
            directory_id=directory_id,
            referer=landing["landing_url"],
        )
        self._verify_exam_question_fields(after, expected)
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "directory_id": directory_id,
            "before": before,
            "after": after,
            "server_message": str(payload.get("msg") or ""),
            "verification": "every requested question-bank field matches a fresh editor read",
        }

    def _list_all_question_bank_items(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        directory_id: str,
        search: str = "",
    ) -> dict[str, Any]:
        first = self.list_question_bank(
            course,
            clazz,
            page=1,
            page_size=100,
            search=search,
            directory_id=directory_id,
        )
        directories = list(first["directories"])
        questions = list(first["questions"])
        page_count = min(int(first.get("page_count") or 1), 100)
        for page in range(2, page_count + 1):
            current = self.list_question_bank(
                course,
                clazz,
                page=page,
                page_size=100,
                search=search,
                directory_id=directory_id,
            )
            directories.extend(current["directories"])
            questions.extend(current["questions"])
        for index, item in enumerate(directories, 1):
            item["index"] = index
        for index, item in enumerate(questions, 1):
            item["index"] = index
        return {
            "directory_id": str(directory_id),
            "search": search,
            "page_count": page_count,
            "allow_sort": bool(first.get("allow_sort")),
            "directories": directories,
            "questions": questions,
        }

    def reorder_question_bank_directory(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        directory_query: str,
        target_position: int,
    ) -> dict[str, Any]:
        landing = self._question_bank_landing_context(course, clazz)
        session = landing["session"]
        tree = self._question_bank_directory_tree(
            session,
            course,
            referer=landing["landing_url"],
        )
        source = resolve_question_bank_directory(tree, directory_query)
        if source.get("is_top"):
            raise ChaoxingAPIError(
                "a topped question-bank directory must be un-topped before manual reordering"
            )
        parent_id = str(source.get("parent_id") or "0")
        before_items = self._list_all_question_bank_items(
            course,
            clazz,
            directory_id=parent_id,
        )
        tree_by_id = {item["directory_id"]: item for item in tree}
        before_order = [
            item["directory_id"]
            for item in before_items["directories"]
            if item["directory_id"] in tree_by_id
            and str(tree_by_id[item["directory_id"]].get("parent_id") or "0") == parent_id
            and not tree_by_id[item["directory_id"]].get("is_top")
        ]
        expected_ids = {
            item["directory_id"]
            for item in tree
            if str(item.get("parent_id") or "0") == parent_id and not item.get("is_top")
        }
        if set(before_order) != expected_ids:
            raise ChaoxingAPIError(
                "the current directory listing did not expose every reorderable sibling"
            )
        target_order = reposition_identifier(
            before_order,
            source["directory_id"],
            target_position,
        )
        if target_order == before_order:
            return {
                "course_id": course["course_id"],
                "course_name": course["course_name"],
                "clazz_id": clazz["clazz_id"],
                "clazz_name": clazz["clazz_name"],
                "directory": source,
                "parent_id": parent_id,
                "before_order": before_order,
                "after_order": before_order,
                "changed": False,
                "verification": "the directory was already at the requested sibling position",
            }
        payload = self._question_bank_mutation_request(
            session,
            "/mooc2-ans/qbank/batchUpdateSort",
            {
                "courseid": course["course_id"],
                "cpi": course["cpi"],
                "idStr": ",".join(target_order),
                "type": "0",
            },
            referer=landing["landing_url"],
            operation="question-bank directory reorder",
        )
        refreshed = self._list_all_question_bank_items(
            course,
            clazz,
            directory_id=parent_id,
        )
        after_order = [
            item["directory_id"]
            for item in refreshed["directories"]
            if item["directory_id"] in expected_ids
        ]
        if after_order != target_order:
            raise ChaoxingAPIError(
                "directory reorder was acknowledged but the refreshed sibling order differs"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "directory": source,
            "parent_id": parent_id,
            "before_order": before_order,
            "after_order": after_order,
            "changed": True,
            "server_message": str(payload.get("msg") or ""),
            "verification": "the complete non-topped sibling order matches a fresh HTTP read",
        }

    def reorder_question_bank_question(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        question_query: str,
        target_position: int,
        *,
        directory_id: str = "0",
    ) -> dict[str, Any]:
        directory_id = str(directory_id or "0")
        before_items = self._list_all_question_bank_items(
            course,
            clazz,
            directory_id=directory_id,
        )
        if not before_items["allow_sort"]:
            raise ChaoxingAPIError(
                "the current question-bank directory does not enable manual question sorting"
            )
        question = resolve_question_bank_question(before_items["questions"], question_query)
        before_order = [item["question_id"] for item in before_items["questions"]]
        target_order = reposition_identifier(
            before_order,
            question["question_id"],
            target_position,
        )
        if target_order == before_order:
            return {
                "course_id": course["course_id"],
                "course_name": course["course_name"],
                "clazz_id": clazz["clazz_id"],
                "clazz_name": clazz["clazz_name"],
                "directory_id": directory_id,
                "question": question,
                "before_order": before_order,
                "after_order": before_order,
                "changed": False,
                "verification": "the question was already at the requested position",
            }
        landing = self._question_bank_landing_context(course, clazz)
        payload = self._question_bank_mutation_request(
            landing["session"],
            "/mooc2-ans/qbank/batchUpdateSort",
            {
                "courseid": course["course_id"],
                "cpi": course["cpi"],
                "idStr": ",".join(target_order),
                "type": "1",
            },
            referer=landing["landing_url"],
            operation="question-bank question reorder",
        )
        refreshed = self._list_all_question_bank_items(
            course,
            clazz,
            directory_id=directory_id,
        )
        after_order = [item["question_id"] for item in refreshed["questions"]]
        if after_order != target_order:
            raise ChaoxingAPIError(
                "question reorder was acknowledged but the refreshed question order differs"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "directory_id": directory_id,
            "question": resolve_question_bank_question(
                refreshed["questions"], question["question_id"]
            ),
            "before_order": before_order,
            "after_order": after_order,
            "changed": True,
            "server_message": str(payload.get("msg") or ""),
            "verification": "the complete question order matches a fresh HTTP read",
        }

    def move_question_bank_question(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        question_query: str,
        target_directory_query: str,
        *,
        source_directory_id: str = "0",
    ) -> dict[str, Any]:
        source_directory_id = str(source_directory_id or "0")
        before_items = self._list_all_question_bank_items(
            course,
            clazz,
            directory_id=source_directory_id,
        )
        question = resolve_question_bank_question(before_items["questions"], question_query)
        landing = self._question_bank_landing_context(course, clazz)
        session = landing["session"]
        tree = self._question_bank_directory_tree(
            session,
            course,
            referer=landing["landing_url"],
        )
        target = resolve_question_bank_directory(tree, target_directory_query, allow_root=True)
        if source_directory_id == target["directory_id"]:
            return {
                "course_id": course["course_id"],
                "course_name": course["course_name"],
                "clazz_id": clazz["clazz_id"],
                "clazz_name": clazz["clazz_name"],
                "question": question,
                "source_directory_id": source_directory_id,
                "target": target,
                "changed": False,
                "verification": "the question is already in the requested directory",
            }
        payload = self._question_bank_mutation_request(
            session,
            "/mooc2-ans/qbank/update-pid",
            {
                "courseid": course["course_id"],
                "cpi": course["cpi"],
                "operateId": question["question_id"],
                "operateCourseId": question.get("course_id") or course["course_id"],
                "type": "1",
                "newPid": target["directory_id"],
            },
            referer=landing["landing_url"],
            operation="question-bank question move",
        )
        source_after = self._list_all_question_bank_items(
            course,
            clazz,
            directory_id=source_directory_id,
        )
        target_after = self._list_all_question_bank_items(
            course,
            clazz,
            directory_id=target["directory_id"],
        )
        in_source = any(
            item["question_id"] == question["question_id"] for item in source_after["questions"]
        )
        target_matches = [
            item
            for item in target_after["questions"]
            if item["question_id"] == question["question_id"]
        ]
        if in_source or len(target_matches) != 1:
            raise ChaoxingAPIError(
                "question move was acknowledged but source/target read-back differs"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "source_directory_id": source_directory_id,
            "target": target,
            "question": target_matches[0],
            "changed": True,
            "server_message": str(payload.get("msg") or ""),
            "verification": "the question is absent from the source and present in the target",
        }

    def delete_question_bank_question(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        question_query: str,
        *,
        directory_id: str = "0",
    ) -> dict[str, Any]:
        directory_id = str(directory_id or "0")
        before_items = self._list_all_question_bank_items(
            course,
            clazz,
            directory_id=directory_id,
        )
        question = resolve_question_bank_question(before_items["questions"], question_query)
        landing = self._question_bank_landing_context(course, clazz)
        payload = self._question_bank_mutation_request(
            landing["session"],
            "/mooc2-ans/qbank/deal-recycle",
            {
                "courseid": course["course_id"],
                "id": question["question_id"],
                "status": "2",
                "cpi": course["cpi"],
                "type": "1",
            },
            referer=landing["landing_url"],
            operation="question-bank question recycle",
        )
        refreshed = self._list_all_question_bank_items(
            course,
            clazz,
            directory_id=directory_id,
        )
        if any(item["question_id"] == question["question_id"] for item in refreshed["questions"]):
            raise ChaoxingAPIError(
                "question recycle was acknowledged but it remains in the active directory"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "directory_id": directory_id,
            "deleted": question,
            "server_message": str(payload.get("msg") or ""),
            "verification": "the question is absent from the refreshed active directory",
        }

    def update_question_bank_question_difficulty(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        question_query: str,
        difficulty: Any,
        *,
        directory_id: str = "0",
    ) -> dict[str, Any]:
        directory_id = str(directory_id or "0")
        normalized_difficulty = self._question_difficulty(difficulty)
        before_items = self._list_all_question_bank_items(
            course,
            clazz,
            directory_id=directory_id,
        )
        question = resolve_question_bank_question(before_items["questions"], question_query)
        landing = self._question_bank_landing_context(course, clazz)
        hidden = parse_hidden_inputs(landing["landing_html"])
        open_difficulty = str(hidden.get("openDifficulty") or "").lower() == "true"
        if not open_difficulty:
            raise ChaoxingAPIError(
                "this question bank currently uses categorical difficulty; numeric update is "
                "not available through the active editor mode"
            )
        payload = self._question_bank_mutation_request(
            landing["session"],
            "/mooc2-ans/qbank/update-difficulty",
            {
                "courseid": course["course_id"],
                "cpi": course["cpi"],
                "qids": question["question_id"],
                "difficulty": normalized_difficulty,
            },
            referer=landing["landing_url"],
            operation="question-bank difficulty update",
        )
        refreshed = self._list_all_question_bank_items(
            course,
            clazz,
            directory_id=directory_id,
        )
        after = resolve_question_bank_question(refreshed["questions"], question["question_id"])
        difficulty_match = re.search(r"\d+(?:\.\d+)?", str(after.get("difficulty") or ""))
        actual = float(difficulty_match.group(0)) if difficulty_match else None
        if actual is None or abs(actual - normalized_difficulty) >= 1e-9:
            raise ChaoxingAPIError(
                "difficulty update was acknowledged but the refreshed value differs"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "directory_id": directory_id,
            "before": question,
            "after": after,
            "server_message": str(payload.get("msg") or ""),
            "verification": "the numeric difficulty matches the refreshed question list",
        }

    def update_question_bank_questions_difficulty(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        questions: list[str] | str,
        difficulty: Any,
        *,
        directory_id: str = "0",
    ) -> dict[str, Any]:
        queries = [questions] if isinstance(questions, str) else [str(item) for item in questions]
        queries = [item.strip() for item in queries if item.strip()]
        if not queries:
            raise ChaoxingAPIError("at least one question-bank question is required")
        directory_id = str(directory_id or "0")
        before_items = self._list_all_question_bank_items(
            course,
            clazz,
            directory_id=directory_id,
        )
        resolved: list[dict[str, Any]] = []
        for query in queries:
            question = resolve_question_bank_question(before_items["questions"], query)
            if all(item["question_id"] != question["question_id"] for item in resolved):
                resolved.append(question)
        landing = self._question_bank_landing_context(course, clazz)
        hidden = parse_hidden_inputs(landing["landing_html"])
        numeric_mode = str(hidden.get("openDifficulty") or "").lower() == "true"
        if numeric_mode:
            normalized_value: str | float = self._question_difficulty(difficulty)
            expected_label = ""
        else:
            aliases = {
                "0": "0",
                "easy": "0",
                "易": "0",
                "1": "1",
                "medium": "1",
                "中": "1",
                "2": "2",
                "hard": "2",
                "难": "2",
            }
            key = str(difficulty or "").strip().lower()
            if key not in aliases:
                raise ChaoxingAPIError("categorical difficulty must be easy, medium, or hard")
            normalized_value = aliases[key]
            expected_label = {"0": "易", "1": "中", "2": "难"}[str(normalized_value)]
        qids = ",".join(item["question_id"] for item in resolved)
        if len(resolved) > 1:
            qids += ","
        payload = self._question_bank_mutation_request(
            landing["session"],
            "/mooc2-ans/qbank/update-easy",
            {
                "courseid": course["course_id"],
                "cpi": course["cpi"],
                "qids": qids,
                "easy": normalized_value,
            },
            referer=landing["landing_url"],
            operation="question-bank batch difficulty update",
        )
        refreshed = self._list_all_question_bank_items(
            course,
            clazz,
            directory_id=directory_id,
        )
        changes: list[dict[str, Any]] = []
        for before in resolved:
            after = resolve_question_bank_question(refreshed["questions"], before["question_id"])
            actual_text = str(after.get("difficulty") or "")
            if numeric_mode:
                match = re.search(r"\d+(?:\.\d+)?", actual_text)
                actual = float(match.group(0)) if match else None
                if actual is None or abs(actual - float(normalized_value)) >= 1e-9:
                    raise ChaoxingAPIError(
                        f"difficulty update for question {before['question_id']} was acknowledged "
                        "but read-back differs"
                    )
            elif expected_label not in actual_text:
                raise ChaoxingAPIError(
                    f"difficulty update for question {before['question_id']} was acknowledged "
                    "but read-back differs"
                )
            changes.append({"before": before, "after": after})
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "directory_id": directory_id,
            "difficulty_mode": "numeric" if numeric_mode else "categorical",
            "difficulty": normalized_value,
            "question_count": len(changes),
            "changes": changes,
            "server_message": str(payload.get("msg") or ""),
            "verification": (
                "every requested question shows the target difficulty in a fresh list read"
            ),
        }

    def update_question_bank_questions_type(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        questions: list[str] | str,
        question_type_query: str,
        *,
        directory_id: str = "0",
    ) -> dict[str, Any]:
        question_queries = (
            [questions] if isinstance(questions, str) else [str(item) for item in questions]
        )
        question_queries = [item.strip() for item in question_queries if item.strip()]
        if not question_queries:
            raise ChaoxingAPIError("at least one question-bank question is required")
        directory_id = str(directory_id or "0")
        before_items = self._list_all_question_bank_items(
            course,
            clazz,
            directory_id=directory_id,
        )
        resolved_questions: list[dict[str, Any]] = []
        for query in question_queries:
            question = resolve_question_bank_question(before_items["questions"], query)
            if all(
                existing["question_id"] != question["question_id"]
                for existing in resolved_questions
            ):
                resolved_questions.append(question)
        landing = self._question_bank_landing_context(course, clazz)
        question_types = self._question_bank_question_types(
            landing["session"],
            course,
            referer=landing["landing_url"],
        )
        target = resolve_question_bank_question_type(question_types, question_type_query)
        target_type_id = "0" if target["system_type"] == "1" else target["type_id"]
        try:
            response = landing["session"].post(
                MOOC2_BASE_URL + "/mooc2-ans/qbank/update-que-type",
                params={
                    "courseid": course["course_id"],
                    "cpi": course["cpi"],
                    "newQtype": target["origin_type"],
                    "typeId": target_type_id,
                },
                data={"qids": ",".join(item["question_id"] for item in resolved_questions)},
                timeout=self.timeout,
                headers={
                    "Referer": landing["landing_url"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"question-bank type update failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "question-bank type update was not acknowledged"))
        refreshed = self._list_all_question_bank_items(
            course,
            clazz,
            directory_id=directory_id,
        )
        changes: list[dict[str, Any]] = []
        for before in resolved_questions:
            after = resolve_question_bank_question(refreshed["questions"], before["question_id"])
            if (
                str(after.get("origin_type") or "") != target["origin_type"]
                or str(after.get("question_type") or "").strip() != target["name"]
            ):
                raise ChaoxingAPIError(
                    f"type update for question {before['question_id']} was acknowledged "
                    "but read-back differs"
                )
            changes.append({"before": before, "after": after})
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "directory_id": directory_id,
            "target_question_type": target,
            "question_count": len(changes),
            "changes": changes,
            "server_message": str(payload.get("msg") or ""),
            "verification": "every requested question has the target type in a fresh list read",
        }

    def copy_question_bank_items(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        questions: list[str] | str | None = None,
        directories: list[str] | str | None = None,
        source_directory_id: str = "0",
        target_directory: str = "0",
    ) -> dict[str, Any]:
        question_queries = (
            []
            if questions is None
            else [questions]
            if isinstance(questions, str)
            else [str(item) for item in questions]
        )
        directory_queries = (
            []
            if directories is None
            else [directories]
            if isinstance(directories, str)
            else [str(item) for item in directories]
        )
        question_queries = [item.strip() for item in question_queries if item.strip()]
        directory_queries = [item.strip() for item in directory_queries if item.strip()]
        if not question_queries and not directory_queries:
            raise ChaoxingAPIError("at least one question or directory is required for copying")
        source_directory_id = str(source_directory_id or "0")
        source_items = self._list_all_question_bank_items(
            course,
            clazz,
            directory_id=source_directory_id,
        )
        resolved_questions: list[dict[str, Any]] = []
        for query in question_queries:
            question = resolve_question_bank_question(source_items["questions"], query)
            if all(
                existing["question_id"] != question["question_id"]
                for existing in resolved_questions
            ):
                resolved_questions.append(question)
        landing = self._question_bank_landing_context(course, clazz)
        before_tree = self._question_bank_directory_tree(
            landing["session"],
            course,
            referer=landing["landing_url"],
        )
        target = resolve_question_bank_directory(
            before_tree,
            target_directory,
            allow_root=True,
        )
        resolved_directories: list[dict[str, Any]] = []
        for query in directory_queries:
            directory = resolve_question_bank_directory(before_tree, query)
            if target["directory_id"] == directory["directory_id"] or str(
                target.get("path") or ""
            ).startswith(str(directory.get("path") or "") + " / "):
                raise ChaoxingAPIError("a directory cannot be copied into itself or a descendant")
            if all(
                existing["directory_id"] != directory["directory_id"]
                for existing in resolved_directories
            ):
                resolved_directories.append(directory)
        before_target = self._list_all_question_bank_items(
            course,
            clazz,
            directory_id=target["directory_id"],
        )
        before_question_ids = {item["question_id"] for item in before_target["questions"]}
        before_directory_ids = {item["directory_id"] for item in before_tree}
        try:
            response = landing["session"].post(
                MOOC2_BASE_URL + "/mooc2-ans/qbank/questionCopy",
                params={
                    "courseid": course["course_id"],
                    "cpi": course["cpi"],
                    "newPid": target["directory_id"],
                    "pids": (
                        ",".join(item["directory_id"] for item in resolved_directories) + ","
                        if resolved_directories
                        else ""
                    ),
                },
                data={
                    "qids": (
                        ",".join(item["question_id"] for item in resolved_questions) + ","
                        if resolved_questions
                        else ""
                    )
                },
                timeout=self.timeout,
                headers={
                    "Referer": landing["landing_url"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"question-bank copy failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "question-bank copy was not acknowledged"))
        after_tree = self._question_bank_directory_tree(
            landing["session"],
            course,
            referer=landing["landing_url"],
        )
        copied_directories = [
            item
            for item in after_tree
            if item["directory_id"] not in before_directory_ids
            and item["parent_id"] == target["directory_id"]
            and any(item["name"] == source["name"] for source in resolved_directories)
        ]
        if len(copied_directories) != len(resolved_directories):
            raise ChaoxingAPIError(
                "copy was acknowledged but the expected new directories were not all found"
            )
        after_target = self._list_all_question_bank_items(
            course,
            clazz,
            directory_id=target["directory_id"],
        )
        copied_questions = [
            item
            for item in after_target["questions"]
            if item["question_id"] not in before_question_ids
            and any(
                item.get("stem") == source.get("stem")
                and item.get("origin_type") == source.get("origin_type")
                for source in resolved_questions
            )
        ]
        if len(copied_questions) != len(resolved_questions):
            raise ChaoxingAPIError(
                "copy was acknowledged but the expected new questions were not all found"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "source_directory_id": source_directory_id,
            "target_directory": target,
            "source_questions": resolved_questions,
            "source_directories": resolved_directories,
            "copied_questions": copied_questions,
            "copied_directories": copied_directories,
            "server_message": str(payload.get("msg") or ""),
            "verification": "fresh target reads expose one new matching item per source item",
        }

    def _question_bank_smart_import_context(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> dict[str, Any]:
        landing = self._question_bank_landing_context(course, clazz)
        session = landing["session"]
        smart_import_url = MOOC2_BASE_URL + "/mooc2-ans/qbank/smartimport"
        try:
            response = session.get(
                smart_import_url,
                params={
                    "courseid": course["course_id"],
                    "cpi": course["cpi"],
                    "qbanksystem": "0",
                    "microTopicId": "0",
                },
                timeout=self.timeout,
                allow_redirects=True,
                headers={"Referer": landing["landing_url"]},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(
                f"question-bank smart-import page request failed: {exc}"
            ) from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError(
                f"question-bank smart-import request was redirected to login: {response.url}"
            )
        context = parse_question_bank_smart_import_context(self._decode(response))
        context.update(
            {
                "session": session,
                "landing_url": landing["landing_url"],
                "smart_import_url": response.url,
            }
        )
        return context

    @staticmethod
    def _question_bank_smart_import_response(
        response: requests.Response,
        operation: str,
    ) -> dict[str, Any]:
        try:
            response.raise_for_status()
            payload = json.loads(ChaoxingAPI._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"question-bank smart-import {operation} failed: {exc}") from exc
        if not isinstance(payload, dict):
            raise ChaoxingAPIError(
                f"question-bank smart-import {operation} returned an invalid response"
            )
        if payload.get("status") is False:
            raise ChaoxingAPIError(
                str(payload.get("msg") or f"question-bank smart-import {operation} was rejected")
            )
        return payload

    def _parse_question_bank_smart_import_file(
        self,
        session: requests.Session,
        smart_import_url: str,
        file_path: str | Path,
        *,
        parse_latex_code: bool,
        parse_latex_formula: bool,
    ) -> tuple[list[Any], dict[str, Any]]:
        path = Path(file_path).expanduser().resolve()
        if not path.is_file():
            raise ChaoxingAPIError(f"smart-import source file not found: {path}")
        file_size = path.stat().st_size
        if file_size <= 0:
            raise ChaoxingAPIError("smart-import source file is empty")
        if file_size > 20 * 1024 * 1024:
            raise ChaoxingAPIError("smart-import source file cannot exceed 20 MB")
        suffix = path.suffix.lower()
        allowed_suffixes = {".doc", ".docx", ".pdf", ".png", ".jpg", ".jpeg"}
        if suffix not in allowed_suffixes:
            raise ChaoxingAPIError("smart import supports Word, PDF, PNG, and JPEG source files")
        content_type = mimetypes.guess_type(path.name)[0] or "application/octet-stream"
        form = {
            "isParseLatexFormula": str(parse_latex_formula).lower(),
            "isFormulaImageOcr": "false",
        }
        try:
            with path.open("rb") as source:
                response = session.post(
                    MOOC2_BASE_URL + "/sqp/api/upload",
                    data=form,
                    files={"file": (path.name, source, content_type)},
                    timeout=max(self.timeout, 60),
                    headers={
                        "Referer": smart_import_url,
                        "X-Requested-With": "XMLHttpRequest",
                    },
                )
        except (OSError, requests.RequestException) as exc:
            raise ChaoxingAPIError(f"question-bank smart-import upload failed: {exc}") from exc
        upload = self._question_bank_smart_import_response(response, "upload")
        object_id = str(upload.get("crc") or "").strip()
        if not object_id:
            raise ChaoxingAPIError("question-bank smart-import upload exposed no file identifier")

        parse_info = upload.get("parseInfo") if isinstance(upload.get("parseInfo"), dict) else {}
        if (
            suffix in {".pdf", ".png", ".jpg", ".jpeg"}
            and str(parse_info.get("status") or "").lower() != "completed"
        ):
            pdf_id = str(parse_info.get("pdfId") or "").strip()
            if not pdf_id:
                raise ChaoxingAPIError(
                    "question-bank smart-import conversion exposed no PDF/image task identifier"
                )
            converted = False
            for attempt in range(8):
                if attempt:
                    sleep(5)
                try:
                    response = session.get(
                        MOOC2_BASE_URL + "/sqp/api/pdf2html",
                        params={"file": object_id, "pdfId": pdf_id},
                        timeout=max(self.timeout, 30),
                        headers={
                            "Referer": smart_import_url,
                            "X-Requested-With": "XMLHttpRequest",
                        },
                    )
                except requests.RequestException as exc:
                    raise ChaoxingAPIError(
                        f"question-bank smart-import conversion failed: {exc}"
                    ) from exc
                conversion = self._question_bank_smart_import_response(response, "conversion")
                conversion_info = (
                    conversion.get("parseInfo")
                    if isinstance(conversion.get("parseInfo"), dict)
                    else {}
                )
                if str(conversion_info.get("status") or "").lower() == "completed":
                    converted = True
                    break
            if not converted:
                raise ChaoxingAPIError("question-bank smart-import conversion did not finish")

        try:
            response = session.get(
                MOOC2_BASE_URL + "/sqp/api/parse",
                params={
                    "file": object_id,
                    "isParseLatexCode": str(parse_latex_code).lower(),
                    "isParseLatexFormula": str(parse_latex_formula).lower(),
                },
                timeout=max(self.timeout, 60),
                headers={
                    "Referer": smart_import_url,
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"question-bank smart-import parsing failed: {exc}") from exc
        parsed = self._question_bank_smart_import_response(response, "parsing")
        paper = parsed.get("paper")
        if not isinstance(paper, list):
            raise ChaoxingAPIError("question-bank smart-import parser exposed no paper list")
        return paper, {"mode": "file", "file_name": path.name, "file_size": file_size}

    def _parse_question_bank_smart_import_source(
        self,
        session: requests.Session,
        smart_import_url: str,
        *,
        source_text: str | None,
        file_path: str | Path | None,
        content_format: str,
        parse_latex_code: bool,
        parse_latex_formula: bool,
    ) -> dict[str, Any]:
        source_count = int(source_text is not None) + int(file_path is not None)
        if source_count != 1:
            raise ChaoxingAPIError(
                "provide exactly one smart-import source: source_text or file_path"
            )
        if file_path is not None:
            paper, source = self._parse_question_bank_smart_import_file(
                session,
                smart_import_url,
                file_path,
                parse_latex_code=parse_latex_code,
                parse_latex_formula=parse_latex_formula,
            )
        else:
            text = str(source_text or "")
            if not text.strip():
                raise ChaoxingAPIError("smart-import source text cannot be empty")
            normalized_format = content_format.strip().lower()
            if normalized_format not in {"plain", "html"}:
                raise ChaoxingAPIError("content_format must be plain or html")
            if normalized_format == "plain":
                html = "".join(
                    f"<p>{escape(line) if line else '<br>'}</p>" for line in text.splitlines()
                )
            else:
                html = text
            try:
                response = session.post(
                    MOOC2_BASE_URL + "/sqp/api/parse",
                    data={
                        "html": html,
                        "isParseLatexCode": str(parse_latex_code).lower(),
                        "isParseLatexFormula": str(parse_latex_formula).lower(),
                    },
                    timeout=max(self.timeout, 60),
                    headers={
                        "Referer": smart_import_url,
                        "X-Requested-With": "XMLHttpRequest",
                    },
                )
            except requests.RequestException as exc:
                raise ChaoxingAPIError(
                    f"question-bank smart-import text parsing failed: {exc}"
                ) from exc
            parsed = self._question_bank_smart_import_response(response, "text parsing")
            paper = parsed.get("paper")
            if not isinstance(paper, list):
                raise ChaoxingAPIError("question-bank smart-import parser exposed no paper list")
            source = {
                "mode": "text",
                "content_format": normalized_format,
                "character_count": len(text),
            }
        normalized = normalize_question_bank_smart_import_paper(paper)
        return {**normalized, "source": source}

    def preview_question_bank_smart_import(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        source_text: str | None = None,
        file_path: str | Path | None = None,
        content_format: str = "plain",
        parse_latex_code: bool = False,
        parse_latex_formula: bool = False,
    ) -> dict[str, Any]:
        context = self._question_bank_smart_import_context(course, clazz)
        parsed = self._parse_question_bank_smart_import_source(
            context["session"],
            context["smart_import_url"],
            source_text=source_text,
            file_path=file_path,
            content_format=content_format,
            parse_latex_code=parse_latex_code,
            parse_latex_formula=parse_latex_formula,
        )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            **parsed,
            "course_question_count": context["course_question_count"],
            "course_question_limit": context["course_question_limit"],
            "allow_import_topics": context["allow_import_topics"],
            "source_url": context["smart_import_url"],
            "verification": (
                "the authenticated Chaoxing smart-import parser returned these normalized "
                "questions through HTTP; nothing was added to the question bank"
            ),
        }

    @staticmethod
    def _validate_question_bank_import_questions(
        questions: Any,
    ) -> list[dict[str, Any]]:
        if not isinstance(questions, list) or not questions:
            raise ChaoxingAPIError("at least one normalized smart-import question is required")
        if len(questions) > 1000:
            raise ChaoxingAPIError("one smart import cannot contain more than 1000 questions")
        supported_types = {
            definition[0] for definition in QUESTION_BANK_SMART_IMPORT_TYPES.values()
        }
        supported_types.update({5, 6, 7, 9})
        normalized: list[dict[str, Any]] = []
        for index, raw in enumerate(questions, 1):
            if not isinstance(raw, dict):
                raise ChaoxingAPIError(f"smart-import question {index} must be an object")
            question = json.loads(json.dumps(raw, ensure_ascii=False))
            try:
                question_type = int(question.get("type"))
            except (TypeError, ValueError) as exc:
                raise ChaoxingAPIError(
                    f"smart-import question {index} has no numeric type"
                ) from exc
            if question_type not in supported_types:
                raise ChaoxingAPIError(
                    f"smart-import question {index} has unsupported type {question_type}"
                )
            if not html_text(str(question.get("content") or "")):
                raise ChaoxingAPIError(f"smart-import question {index} has an empty stem")
            answers = question.get("answer")
            if question_type in {0, 1} and not any(
                isinstance(item, dict) and item.get("isanswer") for item in answers or []
            ):
                raise ChaoxingAPIError(
                    f"smart-import objective question {index} has no correct answer"
                )
            if question_type == 2 and not any(
                isinstance(item, dict) and str(item.get("content") or "").strip()
                for item in answers or []
            ):
                raise ChaoxingAPIError(f"smart-import fill-blank question {index} has no answer")
            if question_type == 3 and not (
                isinstance(answers, list)
                and answers
                and isinstance(answers[0], dict)
                and isinstance(answers[0].get("answer"), bool)
            ):
                raise ChaoxingAPIError(f"smart-import true-false question {index} has no answer")
            question["id"] = index - 1
            normalized.append(question)
        return normalized

    def import_question_bank_smart(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        target_directory: str = "0",
        source_text: str | None = None,
        file_path: str | Path | None = None,
        questions: list[dict[str, Any]] | None = None,
        content_format: str = "plain",
        parse_latex_code: bool = False,
        parse_latex_formula: bool = False,
        allow_parser_warnings: bool = False,
    ) -> dict[str, Any]:
        source_count = (
            int(source_text is not None) + int(file_path is not None) + int(questions is not None)
        )
        if source_count != 1:
            raise ChaoxingAPIError(
                "provide exactly one smart-import source: source_text, file_path, or questions"
            )
        context = self._question_bank_smart_import_context(course, clazz)
        session = context["session"]
        source: dict[str, Any]
        parser_warnings: list[dict[str, Any]] = []
        if questions is not None:
            import_questions = self._validate_question_bank_import_questions(questions)
            source = {"mode": "normalized_questions"}
        else:
            parsed = self._parse_question_bank_smart_import_source(
                session,
                context["smart_import_url"],
                source_text=source_text,
                file_path=file_path,
                content_format=content_format,
                parse_latex_code=parse_latex_code,
                parse_latex_formula=parse_latex_formula,
            )
            parser_warnings = parsed["warnings"]
            if parser_warnings and not allow_parser_warnings:
                raise ChaoxingAPIError(
                    "smart-import preview contains parser warnings; review the preview or "
                    "set allow_parser_warnings=true"
                )
            import_questions = self._validate_question_bank_import_questions(parsed["questions"])
            source = parsed["source"]

        tree = self._question_bank_directory_tree(
            session,
            course,
            referer=context["smart_import_url"],
        )
        target = resolve_question_bank_directory(tree, target_directory, allow_root=True)
        before = self._list_all_question_bank_items(
            course,
            clazz,
            directory_id=target["directory_id"],
        )
        before_ids = {item["question_id"] for item in before["questions"]}
        type_list = [
            {"type": item["type"], "name": str(item.get("typeAlias") or item.get("name") or "")}
            for item in import_questions
        ]
        try:
            response = session.post(
                MOOC2_BASE_URL + "/mooc2-ans/qbank/check-qtype-create",
                data={
                    "courseid": course["course_id"],
                    "cpi": course["cpi"],
                    "data": json.dumps(type_list, ensure_ascii=False),
                },
                timeout=self.timeout,
                headers={
                    "Referer": context["smart_import_url"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"question-bank smart-import type check failed: {exc}") from exc
        type_check = self._question_bank_smart_import_response(response, "type check")
        import_fields = {
            "courseId": course["course_id"],
            "isMutex": "0",
            "pid": target["directory_id"],
            "cpi": course["cpi"],
            "enc": context["import_token"],
            "insertQuestion": "true",
            "paperLibraryId": context["paper_library_id"],
            "workLibraryId": context["work_library_id"],
            "needQid": str(context["need_question_ids"]).lower(),
            "uuid": str(uuid4()),
            "microTopicId": context["micro_topic_id"],
            "groupId": context["group_id"],
            "initStatus": context["initial_status"],
            "qjson": json.dumps(import_questions, ensure_ascii=False, separators=(",", ":")),
        }
        try:
            response = session.post(
                context["import_endpoint"],
                data=import_fields,
                timeout=max(self.timeout, 60),
                headers={
                    "Origin": MOOC2_BASE_URL,
                    "Referer": context["smart_import_url"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"question-bank smart import failed: {exc}") from exc
        imported = self._question_bank_smart_import_response(response, "question insertion")
        try:
            total_count = int(imported.get("totalNum") or len(import_questions))
            inserted_count = int(imported.get("insertSuccessNum") or 0)
            failed_count = int(imported.get("insertFailedNum") or 0)
            ignored_count = int(imported.get("ignoreNum") or 0)
        except (TypeError, ValueError) as exc:
            raise ChaoxingAPIError(
                "question-bank smart import returned invalid result counts"
            ) from exc
        after = self._list_all_question_bank_items(
            course,
            clazz,
            directory_id=target["directory_id"],
        )
        new_questions = [
            item for item in after["questions"] if item["question_id"] not in before_ids
        ]
        expected_signatures = {
            (html_text(str(item.get("content") or "")), str(item["type"]))
            for item in import_questions
        }
        matched_questions = [
            item
            for item in new_questions
            if (str(item.get("stem") or ""), str(item.get("origin_type") or ""))
            in expected_signatures
        ]
        if len(matched_questions) < inserted_count:
            raise ChaoxingAPIError(
                "smart import was acknowledged but not all inserted questions appeared in a fresh "
                "target-directory read"
            )
        if inserted_count == len(import_questions):
            outcome = "complete"
        elif inserted_count:
            outcome = "partial"
        else:
            outcome = "failed"
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "target_directory": target,
            "source": source,
            "parser_warnings": parser_warnings,
            "outcome": outcome,
            "total_count": total_count,
            "inserted_count": inserted_count,
            "failed_count": failed_count,
            "ignored_count": ignored_count,
            "question_types_were_created": bool(type_check.get("needCreate")),
            "new_questions": matched_questions,
            "failure_details": str(imported.get("insertFailedContent") or ""),
            "ignored_details": str(imported.get("ignoreContent") or ""),
            "same_choice_details": str(imported.get("sameChoiceNumContent") or ""),
            "verification": (
                f"Chaoxing reported {inserted_count} inserted questions; a fresh HTTP read found "
                f"{len(matched_questions)} new questions with matching stems and types in the "
                "target"
            ),
        }

    @staticmethod
    def _question_bank_export_type(value: str) -> str:
        normalized = str(value or "").strip().lower()
        aliases = {
            "ti": "ti",
            "word": "word",
            "doc": "word",
            "docx": "word",
            "excel": "excel",
            "xls": "excel",
            "xlsx": "excel",
            "pdf": "pdf",
        }
        if normalized not in aliases:
            raise ChaoxingAPIError("export_type must be ti, word, excel, or pdf")
        return aliases[normalized]

    def _question_bank_export_selection(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        questions: list[str] | str | None,
        directories: list[str] | str | None,
        source_directory_id: str,
        referer: str,
        session: requests.Session,
    ) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
        question_queries = (
            []
            if questions is None
            else ([questions] if isinstance(questions, str) else list(questions))
        )
        directory_queries = (
            []
            if directories is None
            else ([directories] if isinstance(directories, str) else list(directories))
        )
        question_queries = [str(item).strip() for item in question_queries if str(item).strip()]
        directory_queries = [str(item).strip() for item in directory_queries if str(item).strip()]
        resolved_questions: list[dict[str, Any]] = []
        if question_queries:
            listing = self._list_all_question_bank_items(
                course,
                clazz,
                directory_id=str(source_directory_id or "0"),
            )
            for query in question_queries:
                question = resolve_question_bank_question(listing["questions"], query)
                if all(
                    item["question_id"] != question["question_id"] for item in resolved_questions
                ):
                    resolved_questions.append(question)
        resolved_directories: list[dict[str, Any]] = []
        if directory_queries:
            tree = self._question_bank_directory_tree(
                session,
                course,
                referer=referer,
            )
            for query in directory_queries:
                directory = resolve_question_bank_directory(tree, query)
                if all(
                    item["directory_id"] != directory["directory_id"]
                    for item in resolved_directories
                ):
                    resolved_directories.append(directory)
        return resolved_questions, resolved_directories

    @staticmethod
    def _question_bank_download_target(
        output_path: str | Path,
        *,
        suggested_name: str,
        fallback_name: str,
        overwrite: bool,
    ) -> Path:
        target = Path(output_path).expanduser()
        if target.exists() and target.is_dir():
            target = target / (suggested_name or fallback_name)
        elif not target.name:
            raise ChaoxingAPIError("output_path must name a file or an existing directory")
        if target.exists() and not overwrite:
            raise ChaoxingAPIError(f"download target already exists: {target}")
        target.parent.mkdir(parents=True, exist_ok=True)
        return target.resolve()

    def _save_question_bank_download_response(
        self,
        response: requests.Response,
        output_path: str | Path,
        *,
        fallback_name: str,
        overwrite: bool,
    ) -> dict[str, Any]:
        content_type = str(response.headers.get("Content-Type") or "").lower()
        if "text/html" in content_type:
            excerpt = html_text(self._decode(response), 240)
            raise ChaoxingAPIError(
                f"question-bank download returned HTML instead of a file: {excerpt}"
            )
        suggested_name = content_disposition_filename(
            str(response.headers.get("Content-Disposition") or "")
        )
        target = self._question_bank_download_target(
            output_path,
            suggested_name=suggested_name,
            fallback_name=fallback_name,
            overwrite=overwrite,
        )
        temporary = target.with_name(target.name + ".part")
        if temporary.exists():
            raise ChaoxingAPIError(f"temporary download target already exists: {temporary}")
        size = 0
        try:
            with temporary.open("wb") as stream:
                for chunk in response.iter_content(chunk_size=1024 * 256):
                    if chunk:
                        stream.write(chunk)
                        size += len(chunk)
            temporary.replace(target)
        except OSError as exc:
            temporary.unlink(missing_ok=True)
            raise ChaoxingAPIError(f"could not save question-bank download: {exc}") from exc
        return {
            "output_path": str(target),
            "file_name": target.name,
            "byte_count": size,
            "content_type": content_type,
            "source_url": urlparse(str(response.url))._replace(query="", fragment="").geturl(),
        }

    def export_question_bank(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        export_type: str,
        questions: list[str] | str | None = None,
        directories: list[str] | str | None = None,
        export_all: bool = False,
        source_directory_id: str = "0",
        output_path: str | Path | None = None,
        include_answers: bool = True,
        include_analysis: bool = True,
        include_difficulty: bool = False,
        include_type_names: bool = False,
        include_topics: bool = False,
        include_targets: bool = False,
        include_correct_rate: bool = False,
        include_use_count: bool = False,
        excel_plain_text: bool = False,
        overwrite: bool = False,
    ) -> dict[str, Any]:
        normalized_type = self._question_bank_export_type(export_type)
        if not isinstance(export_all, bool):
            raise ChaoxingAPIError("export_all must be a boolean")
        landing = self._question_bank_landing_context(course, clazz)
        session = landing["session"]
        context = parse_question_bank_export_context(landing["landing_html"])
        selected_questions, selected_directories = self._question_bank_export_selection(
            course,
            clazz,
            questions=questions,
            directories=directories,
            source_directory_id=str(source_directory_id or "0"),
            referer=landing["landing_url"],
            session=session,
        )
        if export_all and (selected_questions or selected_directories):
            raise ChaoxingAPIError("export_all cannot be combined with selected items")
        if not export_all and not (selected_questions or selected_directories):
            raise ChaoxingAPIError("select at least one question or directory, or set export_all")
        asynchronous = export_all or (
            normalized_type in {"word", "pdf"}
            and (len(selected_questions) > 100 or bool(selected_directories))
        )
        if not asynchronous and output_path is None:
            raise ChaoxingAPIError("output_path is required for a synchronous export")
        params: dict[str, Any] = {
            "courseId": course["course_id"],
            "cpi": course["cpi"],
            "enc": context["export_token"],
            "exportType": normalized_type,
            "exportTypeName": str(include_type_names).lower(),
            "exportEasy": str(include_difficulty).lower(),
            "exportAnalyse": str(include_analysis).lower(),
            "exportAnswer": str(include_answers).lower(),
            "exportTopic": str(include_topics).lower(),
            "excelOnlyText": "1" if excel_plain_text else "0",
            "exportTarget": str(include_targets).lower(),
            "version": context["version"],
            "microTopicId": context["micro_topic_id"],
        }
        if include_correct_rate:
            params["exportRightPercent"] = "true"
        if include_use_count:
            params["exportUseNum"] = "true"
        if asynchronous:
            params.update(
                {
                    "exportAll": str(export_all).lower(),
                    "async": "true",
                }
            )
        else:
            params["saveAs"] = "true"
        form = {
            "questionIds": ",".join(item["question_id"] for item in selected_questions),
            "directoryids": ",".join(item["directory_id"] for item in selected_directories),
        }
        try:
            response = session.post(
                context["export_endpoint"],
                params=params,
                data=form,
                timeout=max(self.timeout, 120),
                stream=not asynchronous,
                headers={
                    "Origin": MOOC2_BASE_URL,
                    "Referer": landing["landing_url"],
                },
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"question-bank export failed: {exc}") from exc
        selection = {
            "export_all": export_all,
            "source_directory_id": str(source_directory_id or "0"),
            "questions": selected_questions,
            "directories": selected_directories,
        }
        if not asynchronous:
            content_type = str(response.headers.get("Content-Type") or "").lower()
            if "json" in content_type:
                try:
                    payload = response.json()
                except (requests.RequestException, ValueError) as exc:
                    raise ChaoxingAPIError("question-bank export returned invalid JSON") from exc
                if not isinstance(payload, dict) or not payload.get("status"):
                    message = payload.get("msg") if isinstance(payload, dict) else ""
                    raise ChaoxingAPIError(str(message or "question-bank export was rejected"))
                download_center = self.list_question_bank_download_center(
                    course,
                    clazz,
                    page=1,
                    order="down",
                )
                return {
                    "course_id": course["course_id"],
                    "course_name": course["course_name"],
                    "clazz_id": clazz["clazz_id"],
                    "clazz_name": clazz["clazz_name"],
                    "export_type": normalized_type,
                    "mode": "asynchronous",
                    "selection": selection,
                    "queued": True,
                    "server_message": str(payload.get("msg") or ""),
                    "download_center": download_center,
                    "verification": (
                        "Chaoxing converted the requested synchronous export into a server task "
                        "and the download center was refreshed through HTTP"
                    ),
                }
            fallback_extension = {"ti": "ti", "word": "docx", "excel": "xlsx", "pdf": "pdf"}
            saved = self._save_question_bank_download_response(
                response,
                output_path,
                fallback_name=(
                    f"{course['course_name']}_题库.{fallback_extension[normalized_type]}"
                ),
                overwrite=overwrite,
            )
            return {
                "course_id": course["course_id"],
                "course_name": course["course_name"],
                "clazz_id": clazz["clazz_id"],
                "clazz_name": clazz["clazz_name"],
                "export_type": normalized_type,
                "mode": "synchronous",
                "selection": selection,
                "file": saved,
                "verification": "the HTTP export response was saved as a non-HTML local file",
            }
        try:
            payload = response.json()
        except (requests.RequestException, ValueError) as exc:
            raise ChaoxingAPIError(
                "asynchronous question-bank export returned invalid JSON"
            ) from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "asynchronous question-bank export was rejected"))
        download_center = self.list_question_bank_download_center(
            course,
            clazz,
            page=1,
            order="down",
        )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "export_type": normalized_type,
            "mode": "asynchronous",
            "selection": selection,
            "queued": True,
            "server_message": str(payload.get("msg") or ""),
            "download_center": download_center,
            "verification": (
                "Chaoxing accepted the export task and the download center was refreshed through "
                "HTTP"
            ),
        }

    def list_question_bank_download_center(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        page: int = 1,
        order: str = "down",
    ) -> dict[str, Any]:
        if page < 1:
            raise ChaoxingAPIError("page must be at least 1")
        normalized_order = str(order or "down").strip().lower()
        normalized_order = {
            "desc": "down",
            "descending": "down",
            "1": "down",
            "asc": "up",
            "ascending": "up",
            "0": "up",
        }.get(normalized_order, normalized_order)
        if normalized_order not in {"down", "up"}:
            raise ChaoxingAPIError("download-center order must be down or up")
        landing = self._question_bank_landing_context(course, clazz)
        try:
            response = landing["session"].get(
                MOOC2_BASE_URL + "/mooc2-ans/tcm/downloadcenter",
                params={
                    "courseId": course["course_id"],
                    "pageNum": str(page),
                    "cpi": course["cpi"],
                    "order": normalized_order,
                },
                timeout=self.timeout,
                headers={"Referer": landing["landing_url"]},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"question-bank download-center request failed: {exc}") from exc
        listing = parse_question_bank_download_center(
            self._decode(response),
            index_offset=(page - 1) * 20,
        )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            **listing,
            "verification": "parsed the authenticated question-bank download center through HTTP",
        }

    def _all_question_bank_download_records(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> list[dict[str, Any]]:
        first = self.list_question_bank_download_center(course, clazz, page=1, order="down")
        records = list(first["records"])
        for page in range(2, min(int(first["page_count"]), 100) + 1):
            current = self.list_question_bank_download_center(
                course,
                clazz,
                page=page,
                order="down",
            )
            records.extend(current["records"])
        return records

    def get_question_bank_download(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        record_query: str,
        *,
        output_path: str | Path | None = None,
        password: str | None = None,
        overwrite: bool = False,
    ) -> dict[str, Any]:
        records = self._all_question_bank_download_records(course, clazz)
        record = resolve_question_bank_download_record(records, record_query)
        if record["status"] == "processing":
            return {
                "course_id": course["course_id"],
                "course_name": course["course_name"],
                "record": record,
                "ready": False,
                "verification": "the refreshed download-center record is still processing",
            }
        landing = self._question_bank_landing_context(course, clazz)
        session = landing["session"]
        download_url = str(record.get("direct_url") or "")
        check_response: requests.Response | None = None
        if not download_url:
            metadata = record.get("metadata") if isinstance(record.get("metadata"), dict) else {}
            try:
                check_response = session.get(
                    MOOC2_BASE_URL + "/mooc2-ans/tcm/check-download-record",
                    params={
                        "courseid": course["course_id"],
                        "recordId": record["record_id"],
                        "relationId": metadata.get("relationId") or record.get("relation_id") or "",
                        "clazzId": metadata.get("clazzId") or record.get("clazz_id") or "",
                        "paperid": metadata.get("libraryId") or record.get("library_id") or "",
                    },
                    timeout=self.timeout,
                    headers={"Referer": landing["landing_url"]},
                )
                check_response.raise_for_status()
            except requests.RequestException as exc:
                raise ChaoxingAPIError(
                    f"question-bank download authorization failed: {exc}"
                ) from exc

            def parse_download_check(response: requests.Response) -> tuple[str, str]:
                text = self._decode(response)
                try:
                    payload = json.loads(text)
                except json.JSONDecodeError:
                    payload = None
                if isinstance(payload, dict) and payload.get("downloadUrl"):
                    return str(payload["downloadUrl"]), ""
                hidden = parse_hidden_inputs(text)
                return "", str(hidden.get("paperid") or record.get("library_id") or "")

            download_url, protected_paper_id = parse_download_check(check_response)
            if not download_url and protected_paper_id and password is not None:
                try:
                    password_response = session.get(
                        MOOC2_BASE_URL + "/mooc2-ans/exam/keep/psafe",
                        params={
                            "courseid": course["course_id"],
                            "cpi": course["cpi"],
                            "paperid": protected_paper_id,
                            "pwd": password,
                        },
                        timeout=self.timeout,
                        headers={"Referer": landing["landing_url"]},
                    )
                    password_response.raise_for_status()
                    password_payload = json.loads(self._decode(password_response))
                except (requests.RequestException, json.JSONDecodeError) as exc:
                    raise ChaoxingAPIError(
                        f"question-bank download password check failed: {exc}"
                    ) from exc
                if not isinstance(password_payload, dict) or not password_payload.get("status"):
                    message = (
                        password_payload.get("msg") if isinstance(password_payload, dict) else ""
                    )
                    raise ChaoxingAPIError(str(message or "download password was rejected"))
                try:
                    check_response = session.get(
                        MOOC2_BASE_URL + "/mooc2-ans/tcm/check-download-record",
                        params={
                            "courseid": course["course_id"],
                            "recordId": record["record_id"],
                            "relationId": record.get("relation_id") or "",
                            "clazzId": record.get("clazz_id") or "",
                            "paperid": protected_paper_id,
                        },
                        timeout=self.timeout,
                        headers={"Referer": landing["landing_url"]},
                    )
                    check_response.raise_for_status()
                except requests.RequestException as exc:
                    raise ChaoxingAPIError(
                        f"question-bank download authorization failed after password: {exc}"
                    ) from exc
                download_url, _ = parse_download_check(check_response)
            if not download_url:
                return {
                    "course_id": course["course_id"],
                    "course_name": course["course_name"],
                    "record": record,
                    "ready": True,
                    "password_required": bool(protected_paper_id),
                    "paper_id": protected_paper_id,
                    "verification": (
                        "Chaoxing returned its password prompt; no file was downloaded"
                    ),
                }
        download_url = urljoin(MOOC2_BASE_URL, download_url)
        parsed_url = urlparse(download_url)
        if parsed_url.scheme not in {"http", "https"} or not parsed_url.hostname:
            raise ChaoxingAPIError("download center returned an unsafe file URL")
        result: dict[str, Any] = {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "record": record,
            "ready": True,
            "password_required": False,
            "download_url": download_url,
        }
        if output_path is None:
            result["verification"] = "Chaoxing returned a valid HTTP download URL"
            return result
        try:
            response = session.get(
                download_url,
                timeout=max(self.timeout, 120),
                stream=True,
                allow_redirects=True,
                headers={"Referer": landing["landing_url"]},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"question-bank file download failed: {exc}") from exc
        result["file"] = self._save_question_bank_download_response(
            response,
            output_path,
            fallback_name=str(record.get("file_name") or "chaoxing-question-bank-export"),
            overwrite=overwrite,
        )
        result["verification"] = "the authorized export was saved as a non-HTML local file"
        return result

    def rename_question_bank_download_record(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        record_query: str,
        name: str,
    ) -> dict[str, Any]:
        normalized_name = str(name or "").strip()
        if not normalized_name:
            raise ChaoxingAPIError("download record file name cannot be empty")
        records = self._all_question_bank_download_records(course, clazz)
        before = resolve_question_bank_download_record(records, record_query)
        landing = self._question_bank_landing_context(course, clazz)
        try:
            response = landing["session"].get(
                MOOC2_BASE_URL + "/mooc2-ans/tcm/downloadcenter/updateFileName",
                params={
                    "courseId": course["course_id"],
                    "cpi": course["cpi"],
                    "id": before["record_id"],
                    "fileName": normalized_name,
                },
                timeout=self.timeout,
                headers={"Referer": landing["landing_url"]},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"download-record rename failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "download-record rename was rejected"))
        after_records = self._all_question_bank_download_records(course, clazz)
        after = resolve_question_bank_download_record(after_records, before["record_id"])
        if str(after.get("file_name") or "") != normalized_name:
            raise ChaoxingAPIError(
                "download-record rename was acknowledged but the refreshed name differs"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "before": before,
            "after": after,
            "server_message": str(payload.get("msg") or ""),
            "verification": "the refreshed download-center record has the requested name",
        }

    def delete_question_bank_download_record(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        record_query: str,
    ) -> dict[str, Any]:
        records = self._all_question_bank_download_records(course, clazz)
        before = resolve_question_bank_download_record(records, record_query)
        landing = self._question_bank_landing_context(course, clazz)
        try:
            response = landing["session"].get(
                MOOC2_BASE_URL + "/mooc2-ans/tcm/deleteDownloadCenter",
                params={
                    "courseId": course["course_id"],
                    "id": before["record_id"],
                    "cpi": course["cpi"],
                },
                timeout=self.timeout,
                headers={"Referer": landing["landing_url"]},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"download-record deletion failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "download-record deletion was rejected"))
        after_records = self._all_question_bank_download_records(course, clazz)
        if any(item["record_id"] == before["record_id"] for item in after_records):
            raise ChaoxingAPIError(
                "download-record deletion was acknowledged but the record remains visible"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "deleted": before,
            "server_message": str(payload.get("msg") or ""),
            "verification": "the record is absent from the refreshed download center",
        }

    def _question_bank_source_context(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> dict[str, Any]:
        landing = self._question_bank_landing_context(course, clazz)
        session = landing["session"]
        fetch_url = MOOC2_BASE_URL + "/mooc2-ans/qbank/fetch-question-new"
        try:
            response = session.get(
                fetch_url,
                params={
                    "courseid": course["course_id"],
                    "cpi": course["cpi"],
                    "from": "qbankFetch",
                    "qbankbackurl": landing["landing_url"],
                },
                timeout=self.timeout,
                allow_redirects=True,
                headers={"Referer": landing["landing_url"]},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"question-bank source picker request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError(
                f"question-bank source picker was redirected to login: {response.url}"
            )
        picker_url = response.url
        try:
            response = session.post(
                MOOC2_BASE_URL + "/mooc2-ans/qbank/get-qbank-course",
                data={
                    "courseid": course["course_id"],
                    "cpi": course["cpi"],
                    "qbankType": "personalQbank",
                    "typeId": "",
                    "qbanksystem": "0",
                    "courseIdsStr": "",
                    "qbankFetch": "true",
                },
                timeout=self.timeout,
                headers={"Referer": picker_url, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"question-bank source-course request failed: {exc}") from exc
        courses = parse_question_bank_source_courses(self._decode(response))
        return {
            "session": session,
            "landing_url": landing["landing_url"],
            "picker_url": picker_url,
            "source_courses": courses,
        }

    def list_question_bank_source_courses(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> dict[str, Any]:
        context = self._question_bank_source_context(course, clazz)
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "source_type": "personalQbank",
            "count": len(context["source_courses"]),
            "source_courses": context["source_courses"],
            "source_url": context["picker_url"],
            "verification": "parsed the current personal source-course picker through HTTP",
        }

    def _question_bank_source_security_state(
        self,
        session: requests.Session,
        source_course: dict[str, Any],
        *,
        referer: str,
    ) -> dict[str, Any]:
        try:
            response = session.get(
                MOOC2_BASE_URL + "/mooc2-ans/qbank/qbanksafe",
                params={"courseid": source_course["course_id"]},
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"question-bank source security check failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "question-bank source security check failed"))
        if payload.get("isLock"):
            raise ChaoxingAPIError(
                f"source course {source_course['course_name']} has a question-bank safety password"
            )
        return payload

    def _question_bank_source_search(
        self,
        session: requests.Session,
        course: dict[str, Any],
        source_course: dict[str, Any],
        *,
        referer: str,
        page: int,
        page_size: int,
        search: str,
        directory_id: str,
        index_offset: int = 0,
    ) -> dict[str, Any]:
        if page < 1:
            raise ChaoxingAPIError("page must be at least 1")
        if page_size < 1 or page_size > 100:
            raise ChaoxingAPIError("page_size must be between 1 and 100")
        try:
            response = session.post(
                MOOC2_BASE_URL + "/mooc2-ans/qbank/search-new",
                data={
                    "courseid": source_course["course_id"],
                    "directoryid": str(directory_id or "0"),
                    "topicIdArr": "",
                    "typeArr": "",
                    "easyArr": "",
                    "targetIdArr": "",
                    "labelIdArr": "",
                    "createrIdArr": "",
                    "rightPercentFrom": "",
                    "rightPercentTo": "",
                    "orderByRight": "",
                    "orderByCreatetime": "",
                    "sw": search,
                    "pageSize": str(page_size),
                    "pageNum": str(page),
                    "oriCourseId": course["course_id"],
                    "qbankType": "personalQbank",
                    "cenc": source_course.get("course_token") or "",
                    "showChildDirQuestion": "true",
                },
                timeout=self.timeout,
                headers={"Referer": referer, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"question-bank source search failed: {exc}") from exc
        return parse_question_bank_source_questions(
            self._decode(response),
            index_offset=index_offset,
        )

    def list_question_bank_source_questions(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        source_course_query: str,
        *,
        page: int = 1,
        page_size: int = 30,
        search: str = "",
        directory_id: str = "0",
    ) -> dict[str, Any]:
        context = self._question_bank_source_context(course, clazz)
        source_course = resolve_question_bank_source_course(
            context["source_courses"], source_course_query
        )
        self._question_bank_source_security_state(
            context["session"], source_course, referer=context["picker_url"]
        )
        listing = self._question_bank_source_search(
            context["session"],
            course,
            source_course,
            referer=context["picker_url"],
            page=page,
            page_size=page_size,
            search=search.strip(),
            directory_id=str(directory_id or "0"),
            index_offset=(page - 1) * page_size,
        )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "source_course": source_course,
            "directory_id": str(directory_id or "0"),
            "search": search.strip(),
            **listing,
            "source_url": context["picker_url"],
            "verification": "parsed the authenticated cross-course question picker through HTTP",
        }

    def import_question_bank_questions_from_course(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        source_course_query: str,
        questions: list[str] | str,
        *,
        target_directory: str = "0",
        source_directory_id: str = "0",
    ) -> dict[str, Any]:
        queries = [questions] if isinstance(questions, str) else [str(item) for item in questions]
        queries = [item.strip() for item in queries if item.strip()]
        if not queries:
            raise ChaoxingAPIError("at least one source question is required")
        if len(queries) > 1000:
            raise ChaoxingAPIError("at most 1000 questions can be imported at once")
        context = self._question_bank_source_context(course, clazz)
        session = context["session"]
        source_course = resolve_question_bank_source_course(
            context["source_courses"], source_course_query
        )
        self._question_bank_source_security_state(
            session, source_course, referer=context["picker_url"]
        )
        first = self._question_bank_source_search(
            session,
            course,
            source_course,
            referer=context["picker_url"],
            page=1,
            page_size=100,
            search="",
            directory_id=str(source_directory_id or "0"),
        )
        source_questions = list(first["questions"])
        for page in range(2, min(first["page_count"], 100) + 1):
            current = self._question_bank_source_search(
                session,
                course,
                source_course,
                referer=context["picker_url"],
                page=page,
                page_size=100,
                search="",
                directory_id=str(source_directory_id or "0"),
                index_offset=(page - 1) * 100,
            )
            source_questions.extend(current["questions"])
        resolved: list[dict[str, Any]] = []
        for query in queries:
            question = resolve_question_bank_source_question(source_questions, query)
            if not question["selectable"]:
                raise ChaoxingAPIError(
                    f"source question is disabled in the current picker: {question['question_id']}"
                )
            if all(item["question_id"] != question["question_id"] for item in resolved):
                resolved.append(question)

        target_tree = self._question_bank_directory_tree(
            session,
            course,
            referer=context["picker_url"],
        )
        target = resolve_question_bank_directory(target_tree, target_directory, allow_root=True)
        before = self._list_all_question_bank_items(
            course,
            clazz,
            directory_id=target["directory_id"],
        )
        before_ids = {item["question_id"] for item in before["questions"]}
        grouped: dict[str, dict[str, Any]] = {}
        for question in resolved:
            key = question["origin_type"] + "--" + question["custom_type_id"]
            group = grouped.setdefault(
                key,
                {
                    "type": question["origin_type"],
                    "courseQuestionTypeId": question["custom_type_id"],
                    "qNum": 0,
                    "data": [],
                },
            )
            group["qNum"] += 1
            group["data"].append(
                {
                    "cid": source_course["course_id"],
                    "cenc": source_course.get("course_token") or "",
                    "qid": question["question_id"],
                    "qbankType": "personalQbank",
                }
            )
        try:
            response = session.post(
                MOOC2_BASE_URL + "/mooc2-ans/qbank/appendQuestionToQbank",
                data={
                    "courseid": course["course_id"],
                    "cpi": course["cpi"],
                    "dirId": target["directory_id"],
                    "questionBankParam": json.dumps(
                        grouped, ensure_ascii=False, separators=(",", ":")
                    ),
                },
                timeout=max(self.timeout, 60),
                headers={
                    "Referer": context["picker_url"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"cross-course question import failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(
                str(message or "cross-course question import was not acknowledged")
            )
        after = self._list_all_question_bank_items(
            course,
            clazz,
            directory_id=target["directory_id"],
        )
        expected_signatures = {
            (str(item.get("stem") or ""), str(item.get("origin_type") or "")) for item in resolved
        }
        imported_questions = [
            item
            for item in after["questions"]
            if item["question_id"] not in before_ids
            and (str(item.get("stem") or ""), str(item.get("origin_type") or ""))
            in expected_signatures
        ]
        if len(imported_questions) < len(resolved):
            raise ChaoxingAPIError(
                "cross-course import was acknowledged but the expected new questions were not all "
                "found in a fresh target read"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "source_course": source_course,
            "source_directory_id": str(source_directory_id or "0"),
            "target_directory": target,
            "source_questions": resolved,
            "imported_questions": imported_questions,
            "server_message": str(payload.get("msg") or ""),
            "verification": (
                "a fresh target-directory read exposes one new matching question per source "
                "question"
            ),
        }

    def _discussion_landing_context(
        self,
        session: requests.Session,
        course: dict[str, Any],
        clazz: dict[str, Any],
    ) -> dict[str, Any]:
        context = self._course_context(session, course, clazz)
        module = resolve_module(context["modules"], "讨论")
        landing_url = self._module_url(context, module, course, clazz)
        try:
            response = session.get(
                landing_url,
                timeout=self.timeout,
                allow_redirects=True,
                headers={"Referer": str(context["final_url"])},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"discussion landing-page request failed: {exc}") from exc
        if "passport2.chaoxing.com/login" in response.url.lower():
            raise ChaoxingAPIError(f"discussion request was redirected to login: {response.url}")
        html = self._decode(response)
        hidden = context.get("hidden") if isinstance(context.get("hidden"), dict) else {}
        bbs_id = str(hidden.get("bbsid") or query_value(response.url, "bbsid") or "")
        if not bbs_id:
            match = re.search(r'["\']bbsid["\']\s*:\s*["\']([^"\']+)', html)
            bbs_id = match.group(1) if match else ""
        token_match = re.search(r"\burlToken\s*:\s*(['\"])(.*?)\1", html, flags=re.S)
        url_token = token_match.group(2) if token_match else ""
        if not bbs_id:
            raise ChaoxingAPIError("discussion page did not expose bbsid")
        return {
            "session": session,
            "course_context": context,
            "landing_url": response.url,
            "landing_html": html,
            "bbs_id": bbs_id,
            "url_token": url_token,
        }

    def _discussion_topic_payload(
        self,
        session: requests.Session,
        topic_uuid: str,
        *,
        referer: str = "",
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        endpoint = f"{GROUPWEB_BASE_URL}/course/topic/{topic_uuid}/getTopic"
        try:
            response = session.get(
                endpoint,
                timeout=self.timeout,
                headers={"Referer": referer} if referer else None,
            )
            response.raise_for_status()
            payload = json.loads(self._decode(response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"discussion topic request failed: {exc}") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or "failed to fetch discussion topic"))
        raw = payload.get("datas")
        if not isinstance(raw, dict):
            raise ChaoxingAPIError("discussion topic response did not contain topic data")
        return raw, parse_discussion_topic(raw)

    @staticmethod
    def _discussion_json(response: requests.Response, operation: str) -> dict[str, Any]:
        try:
            payload = json.loads(ChaoxingAPI._decode(response))
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError(f"{operation} response was not JSON") from exc
        if not isinstance(payload, dict) or not payload.get("status"):
            message = payload.get("msg") if isinstance(payload, dict) else ""
            raise ChaoxingAPIError(str(message or f"{operation} was not acknowledged"))
        return payload

    @staticmethod
    def _discussion_class_tags(
        course: dict[str, Any], clazz: dict[str, Any], class_only: bool
    ) -> str:
        if class_only:
            return f"classId{clazz['clazz_id']}"
        classes = course.get("classes") if isinstance(course.get("classes"), list) else []
        class_ids = [str(item.get("clazz_id") or "") for item in classes if isinstance(item, dict)]
        class_ids = [class_id for class_id in class_ids if class_id]
        if not class_ids:
            class_ids = [str(clazz["clazz_id"])]
        return ",".join(f"classId{class_id}" for class_id in class_ids)

    def create_discussion_topic(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        title: str,
        content: str,
        *,
        class_only: bool = False,
        anonymous: bool = False,
    ) -> dict[str, Any]:
        title = title.strip()
        content = content.strip()
        if not title and not content:
            raise ChaoxingAPIError("discussion title and content cannot both be empty")
        if len(title) > 200:
            raise ChaoxingAPIError("discussion title cannot exceed 200 characters")
        session = self._session()
        context = self._discussion_landing_context(session, course, clazz)
        if not context["url_token"]:
            raise ChaoxingAPIError("discussion page did not expose urlToken")
        topic_uuid = uuid4().hex
        endpoint = f"{GROUPWEB_BASE_URL}/pc/topic/{context['bbs_id']}/addTopic"
        try:
            response = session.post(
                endpoint,
                params={"uuid": topic_uuid},
                data={
                    "topicTitle": quote(title, safe=""),
                    "topicContent": quote(content, safe=""),
                    "files_url": "",
                    "files_attr": "",
                    "bbsid": context["bbs_id"],
                    "courseId": course["course_id"],
                    "folder_uuid": "",
                    "anonymous": "1" if anonymous else "",
                    "label": "",
                    "tags": self._discussion_class_tags(course, clazz, class_only),
                    "urlToken": context["url_token"],
                },
                timeout=self.timeout,
                headers={
                    "Referer": context["landing_url"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"discussion topic creation failed: {exc}") from exc
        payload = self._discussion_json(response, "discussion topic creation")
        _raw, created = self._discussion_topic_payload(
            session, topic_uuid, referer=context["landing_url"]
        )
        if created["uuid"] != topic_uuid:
            raise ChaoxingAPIError("created discussion could not be verified by UUID")
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "scope": "selected_class" if class_only else "course_all_classes",
            "anonymous": anonymous,
            "topic": created,
            "server_message": str(payload.get("msg") or ""),
            "verification": f"created and re-read discussion topic {topic_uuid} through HTTP",
        }

    def _discussion_edit_page(
        self,
        session: requests.Session,
        course: dict[str, Any],
        clazz: dict[str, Any],
        bbs_id: str,
        topic_uuid: str,
        referer: str,
    ) -> tuple[str, dict[str, Any]]:
        endpoint = f"{GROUPWEB_BASE_URL}/course/topic/jumpToUpdateTopic"
        try:
            response = session.get(
                endpoint,
                params={
                    "bbsid": bbs_id,
                    "uuid": topic_uuid,
                    "courseId": course["course_id"],
                    "cpi": course["cpi"],
                    "classId": clazz["clazz_id"],
                },
                timeout=self.timeout,
                headers={"Referer": referer},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"discussion edit-page request failed: {exc}") from exc
        html = self._decode(response)
        marker = re.search(r"\btopic\s*:\s*", html)
        if not marker:
            raise ChaoxingAPIError("discussion topic is not editable by the current account")
        try:
            raw, _end = json.JSONDecoder().raw_decode(html[marker.end() :].lstrip())
        except json.JSONDecodeError as exc:
            raise ChaoxingAPIError("discussion edit page exposed invalid topic data") from exc
        if not isinstance(raw, dict):
            raise ChaoxingAPIError("discussion edit page exposed invalid topic data")
        return response.url, raw

    @staticmethod
    def _discussion_asset_fields(raw: dict[str, Any]) -> tuple[str, str]:
        images = raw.get("img_data") if isinstance(raw.get("img_data"), list) else []
        image_urls = [
            str(item.get("imgUrl") or item.get("url") or "")
            for item in images
            if isinstance(item, dict)
        ]
        files_url = ";".join(url for url in image_urls if url)
        attachments = raw.get("attachment")
        if not isinstance(attachments, list):
            attachments = []
        files_attr = ",".join(
            json.dumps(item, ensure_ascii=False, separators=(",", ":"))
            for item in attachments
            if isinstance(item, dict)
        )
        return files_url, files_attr

    def edit_discussion_topic(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        topic_query: str,
        *,
        title: str | None = None,
        content: str | None = None,
    ) -> dict[str, Any]:
        if title is None and content is None:
            raise ChaoxingAPIError("title or content is required for discussion editing")
        listing = self.list_discussions(course, clazz)
        selected = resolve_discussion_topic(listing["topics"], topic_query)
        session = self._session()
        context = self._discussion_landing_context(session, course, clazz)
        edit_url, editable = self._discussion_edit_page(
            session,
            course,
            clazz,
            listing["bbs_id"],
            selected["uuid"],
            context["landing_url"],
        )
        next_title = selected["title"] if title is None else title.strip()
        original_content = str(editable.get("content") or selected.get("content") or "")
        next_content = original_content if content is None else content.strip()
        if not next_title and not next_content:
            raise ChaoxingAPIError("discussion title and content cannot both be empty")
        if len(next_title) > 200:
            raise ChaoxingAPIError("discussion title cannot exceed 200 characters")
        files_url, files_attr = self._discussion_asset_fields(editable)
        is_rich = bool(editable.get("rtf_content")) or editable.get("topicType") == 10
        data: dict[str, Any] = {
            "edit_topicTitle": quote(next_title, safe=""),
            "edit_topicContent": quote(next_content, safe=""),
            "edit_files_url": files_url,
            "edit_files_attr": quote(files_attr, safe=""),
            "isRichText": "1" if is_rich else "0",
        }
        if is_rich:
            rtf_content = (
                str(editable.get("rtf_content") or "")
                if content is None
                else f"<p>{escape(next_content)}</p>"
            )
            data["rtf_content"] = quote(rtf_content, safe="")
        endpoint = (
            f"{GROUPWEB_BASE_URL}/course/topic/{listing['bbs_id']}/{selected['uuid']}/updateTopic"
        )
        try:
            response = session.post(
                endpoint,
                data=data,
                timeout=self.timeout,
                headers={"Referer": edit_url, "X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"discussion topic update failed: {exc}") from exc
        payload = self._discussion_json(response, "discussion topic update")
        _raw, updated = self._discussion_topic_payload(session, selected["uuid"], referer=edit_url)
        if updated["title"] != next_title or updated["content"] != next_content:
            raise ChaoxingAPIError(
                "server acknowledged the discussion update, but the refreshed topic differs"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "topic": updated,
            "server_message": str(payload.get("msg") or ""),
            "verification": f"updated and re-read discussion topic {selected['uuid']}",
        }

    def set_discussion_topic_top(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        topic_query: str,
        top: bool,
    ) -> dict[str, Any]:
        listing = self.list_discussions(course, clazz)
        selected = resolve_discussion_topic(listing["topics"], topic_query)
        session = self._session()
        operation = "set" if top else "cancel"
        endpoint = f"{GROUPWEB_BASE_URL}/pc/topic/{selected['uuid']}/{operation}/top"
        try:
            response = session.get(
                endpoint,
                timeout=self.timeout,
                headers={"X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"discussion top-status update failed: {exc}") from exc
        payload = self._discussion_json(response, "discussion top-status update")
        _raw, updated = self._discussion_topic_payload(session, selected["uuid"])
        if updated["is_top"] is not top:
            raise ChaoxingAPIError(
                "server acknowledged the top-status update, but refreshed state differs"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "topic": updated,
            "top": top,
            "server_message": str(payload.get("msg") or ""),
            "verification": f"refreshed topic {selected['uuid']} has top={top}",
        }

    def delete_discussion_topic(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        topic_query: str,
    ) -> dict[str, Any]:
        listing = self.list_discussions(course, clazz)
        selected = resolve_discussion_topic(listing["topics"], topic_query)
        session = self._session()
        endpoint = (
            f"{GROUPWEB_BASE_URL}/pc/topic/{listing['bbs_id']}/{selected['uuid']}/deleteTopic"
        )
        try:
            response = session.post(
                endpoint,
                timeout=self.timeout,
                headers={"X-Requested-With": "XMLHttpRequest"},
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"discussion topic deletion failed: {exc}") from exc
        payload = self._discussion_json(response, "discussion topic deletion")
        refreshed = self.list_discussions(course, clazz, search=selected["title"])
        if any(topic["uuid"] == selected["uuid"] for topic in refreshed["topics"]):
            raise ChaoxingAPIError(
                "server acknowledged the deletion, but the discussion is still visible"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "deleted_topic": selected,
            "deleted": True,
            "server_message": str(payload.get("msg") or ""),
            "verification": f"topic {selected['uuid']} is absent from the refreshed list",
        }

    def list_discussions(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        *,
        search: str = "",
        class_only: bool = False,
    ) -> dict[str, Any]:
        session = self._session()
        context = self._course_context(session, course, clazz)
        hidden = context.get("hidden") if isinstance(context.get("hidden"), dict) else {}
        bbs_id = str(hidden.get("bbsid") or "")
        if not bbs_id:
            raise ChaoxingAPIError("teacher course response did not expose bbsid")
        endpoint = f"{GROUPWEB_BASE_URL}/course/topic/{bbs_id}/getTopicList"

        topics: list[dict[str, Any]] = []
        folders: list[dict[str, Any]] = []
        permissions: dict[str, Any] = {}
        last_reply_time = ""
        last_aux_value = ""
        page = 1
        while page <= 100:
            params: dict[str, Any] = {
                "folder_uuid": "",
                "page": str(page),
                "pageSize": "20",
                "kw": search,
                "courseId": course["course_id"],
                "isSetTop": "",
                "selectedStartTime": "",
                "selectedEndTime": "",
                "selectedType": "",
                "learnSilverStartTime": "",
                "learnSilverEndTime": "",
                "lastAuxValue": last_aux_value,
            }
            if last_reply_time:
                params["last_reply_time"] = last_reply_time
            if class_only:
                params["searchType"] = "4"
                params["classid"] = clazz["clazz_id"]
            try:
                response = session.post(
                    endpoint,
                    params=params,
                    timeout=self.timeout,
                    allow_redirects=True,
                    headers={"Referer": str(context["final_url"])},
                )
                response.raise_for_status()
            except requests.RequestException as exc:
                raise ChaoxingAPIError(f"discussion list request failed: {exc}") from exc
            try:
                payload = json.loads(self._decode(response))
            except json.JSONDecodeError as exc:
                raise ChaoxingAPIError("discussion list response was not JSON") from exc
            if not isinstance(payload, dict) or not payload.get("status"):
                message = payload.get("msg") if isinstance(payload, dict) else ""
                raise ChaoxingAPIError(str(message or "failed to fetch discussions"))
            page_topics, page_folders = parse_discussion_payload(payload)
            topics.extend(page_topics)
            if page == 1:
                folders = page_folders
                user_auth = payload.get("userAuth")
                permissions = user_auth if isinstance(user_auth, dict) else {}
            poff = payload.get("poff") if isinstance(payload.get("poff"), dict) else {}
            if bool(poff.get("lastPage")) or not page_topics:
                break
            next_reply_time = str(poff.get("lastValue") or "")
            next_aux = str(poff.get("lastAuxValue") or "")
            if not next_reply_time or next_reply_time == last_reply_time:
                break
            last_reply_time = next_reply_time
            last_aux_value = next_aux
            page += 1

        for index, topic in enumerate(topics, 1):
            topic["index"] = index
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "scope": "selected_class" if class_only else "course_all_classes",
            "search": search,
            "bbs_id": bbs_id,
            "count": len(topics),
            "folder_count": len(folders),
            "topics": topics,
            "folders": folders,
            "permissions": permissions,
            "verification": f"parsed {len(topics)} discussion topics through HTTP",
        }

    def read_discussion_topic(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        topic_query: str,
        *,
        class_only: bool = False,
        order: int = 2,
        reply_search: str = "",
    ) -> dict[str, Any]:
        if order not in {1, 2}:
            raise ChaoxingAPIError("discussion reply order must be 1 (oldest) or 2 (newest)")
        listing = self.list_discussions(course, clazz, class_only=class_only)
        topic = resolve_discussion_topic(listing["topics"], topic_query)
        bbs_id = str(topic.get("bbs_id") or listing.get("bbs_id") or "")
        topic_uuid = str(topic.get("uuid") or "")
        if not bbs_id or not topic_uuid:
            raise ChaoxingAPIError("discussion topic did not expose bbsid and uuid")

        session = self._session()
        detail_url = f"{GROUPWEB_BASE_URL}/course/topic/{topic_uuid}/getTopic"
        try:
            detail_response = session.get(detail_url, timeout=self.timeout)
            detail_response.raise_for_status()
            detail_payload = json.loads(self._decode(detail_response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"discussion topic request failed: {exc}") from exc
        if not isinstance(detail_payload, dict) or not detail_payload.get("status"):
            message = detail_payload.get("msg") if isinstance(detail_payload, dict) else ""
            raise ChaoxingAPIError(str(message or "failed to fetch discussion topic"))
        raw_topic = detail_payload.get("datas")
        if not isinstance(raw_topic, dict):
            raise ChaoxingAPIError("discussion topic response did not contain topic data")
        topic = parse_discussion_topic(raw_topic)

        tag = f"classId{clazz['clazz_id']}" if class_only else ""
        common_params = {
            "bbsid": bbs_id,
            "uuid": topic_uuid,
            "tag": tag,
            "order": str(order),
        }
        top_endpoint = f"{GROUPWEB_BASE_URL}/pc/invitation/getTopReplyList"
        try:
            top_response = session.get(
                top_endpoint,
                params={**common_params, "kw": reply_search},
                timeout=self.timeout,
                headers={"Referer": detail_url},
            )
            top_response.raise_for_status()
            top_payload = json.loads(self._decode(top_response))
        except (requests.RequestException, json.JSONDecodeError) as exc:
            raise ChaoxingAPIError(f"top discussion replies request failed: {exc}") from exc
        if not isinstance(top_payload, dict) or not top_payload.get("status"):
            message = top_payload.get("msg") if isinstance(top_payload, dict) else ""
            raise ChaoxingAPIError(str(message or "failed to fetch top discussion replies"))

        replies = parse_discussion_replies(top_payload, is_top=True)
        reply_endpoint = f"{GROUPWEB_BASE_URL}/pc/invitation/getReplyList"
        last_value = ""
        last_aux_value = ""
        pages = 0
        while pages < 100:
            params = {
                **common_params,
                "lastValue": last_value,
                "lastAuxValue": last_aux_value,
            }
            try:
                response = session.get(
                    reply_endpoint,
                    params=params,
                    timeout=self.timeout,
                    headers={"Referer": detail_url},
                )
                response.raise_for_status()
                payload = json.loads(self._decode(response))
            except (requests.RequestException, json.JSONDecodeError) as exc:
                raise ChaoxingAPIError(f"discussion replies request failed: {exc}") from exc
            if not isinstance(payload, dict) or not payload.get("status"):
                message = payload.get("msg") if isinstance(payload, dict) else ""
                raise ChaoxingAPIError(str(message or "failed to fetch discussion replies"))
            page_replies = parse_discussion_replies(payload, is_top=False)
            replies.extend(page_replies)
            pages += 1
            poff = payload.get("poff") if isinstance(payload.get("poff"), dict) else {}
            if bool(poff.get("lastPage")) or not page_replies:
                break
            next_value = str(poff.get("lastValue") or "")
            next_aux_value = str(poff.get("lastAuxValue") or "")
            if not next_value or (next_value, next_aux_value) == (last_value, last_aux_value):
                break
            last_value = next_value
            last_aux_value = next_aux_value

        seen: set[str] = set()
        unique_replies: list[dict[str, Any]] = []
        for reply in replies:
            identity = str(reply.get("uuid") or reply.get("reply_id") or "")
            if identity and identity in seen:
                continue
            if identity:
                seen.add(identity)
            reply["index"] = len(unique_replies) + 1
            unique_replies.append(reply)
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "scope": "selected_class" if class_only else "course_all_classes",
            "reply_order": "oldest_first" if order == 1 else "newest_first",
            "reply_search": reply_search,
            "topic": topic,
            "reply_count": len(unique_replies),
            "replies": unique_replies,
            "verification": (
                f"fetched topic {topic_uuid} and {len(unique_replies)} replies through HTTP"
            ),
        }

    def _discussion_reply_context(
        self,
        session: requests.Session,
        course: dict[str, Any],
        clazz: dict[str, Any],
        bbs_id: str,
        topic_uuid: str,
    ) -> dict[str, str]:
        endpoint = f"{GROUPWEB_BASE_URL}/course/topic/v3/bbs/{bbs_id}/{topic_uuid}/replysList"
        try:
            response = session.get(
                endpoint,
                params={
                    "courseId": course["course_id"],
                    "classId": clazz["clazz_id"],
                    "cpi": course["cpi"],
                },
                timeout=self.timeout,
                allow_redirects=True,
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"discussion reply-page request failed: {exc}") from exc
        html = self._decode(response)
        token_match = re.search(r"\burlToken\s*:\s*(['\"])(.*?)\1", html, flags=re.S)
        url_token = token_match.group(2) if token_match else ""
        if not url_token:
            raise ChaoxingAPIError("discussion reply page did not expose urlToken")
        return {"detail_url": response.url, "url_token": url_token}

    def create_discussion_reply(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        topic_query: str,
        content: str,
        *,
        reply_to: str = "",
        anonymous: bool = False,
    ) -> dict[str, Any]:
        content = content.strip()
        if not content:
            raise ChaoxingAPIError("discussion reply content cannot be empty")
        listing = self.list_discussions(course, clazz)
        topic = resolve_discussion_topic(listing["topics"], topic_query)
        reply_id = "-1"
        parent: dict[str, Any] | None = None
        if reply_to:
            before = self.read_discussion_topic(course, clazz, topic["uuid"])
            parent = resolve_discussion_reply(before["replies"], reply_to)
            reply_id = parent["reply_id"]
        session = self._session()
        context = self._discussion_reply_context(
            session, course, clazz, listing["bbs_id"], topic["uuid"]
        )
        reply_uuid = uuid4().hex
        endpoint = f"{GROUPWEB_BASE_URL}/pc/invitation/{topic['uuid']}/addReplys"
        try:
            response = session.post(
                endpoint,
                data={
                    "courseId": course["course_id"],
                    "classId": clazz["clazz_id"],
                    "replyId": reply_id,
                    "uuid": reply_uuid,
                    "topic_content": quote(content, safe=""),
                    "files_url": "",
                    "files_attr": "",
                    "anonymous": "1" if anonymous else "",
                    "urlToken": context["url_token"],
                    "bbsid": listing["bbs_id"],
                },
                timeout=self.timeout,
                headers={
                    "Referer": context["detail_url"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"discussion reply creation failed: {exc}") from exc
        payload = self._discussion_json(response, "discussion reply creation")
        if not isinstance(payload.get("datas"), dict):
            return {
                "course_id": course["course_id"],
                "course_name": course["course_name"],
                "clazz_id": clazz["clazz_id"],
                "clazz_name": clazz["clazz_name"],
                "topic": topic,
                "reply_uuid": reply_uuid,
                "reply_to": parent,
                "anonymous": anonymous,
                "pending_review": True,
                "server_message": str(payload.get("msg") or ""),
                "verification": "server accepted the reply for moderation; it is not yet visible",
            }
        refreshed = self.read_discussion_topic(course, clazz, topic["uuid"])
        created = resolve_discussion_reply(refreshed["replies"], reply_uuid)
        if created["content"] != content:
            raise ChaoxingAPIError(
                "server acknowledged the reply, but the refreshed content differs"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "topic": topic,
            "reply": created,
            "reply_to": parent,
            "anonymous": anonymous,
            "pending_review": False,
            "server_message": str(payload.get("msg") or ""),
            "verification": f"created and re-read discussion reply {reply_uuid}",
        }

    def edit_discussion_reply(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        topic_query: str,
        reply_query: str,
        content: str,
    ) -> dict[str, Any]:
        content = content.strip()
        if not content:
            raise ChaoxingAPIError("discussion reply content cannot be empty")
        before = self.read_discussion_topic(course, clazz, topic_query)
        topic = before["topic"]
        reply = resolve_discussion_reply(before["replies"], reply_query)
        image_urls = [
            str(item.get("imgUrl") or item.get("url") or "")
            for item in reply.get("images", [])
            if isinstance(item, dict)
        ]
        files_url = ";".join(url for url in image_urls if url)
        files_attr = ",".join(
            json.dumps(item, ensure_ascii=False, separators=(",", ":"))
            for item in reply.get("attachments", [])
            if isinstance(item, dict)
        )
        session = self._session()
        context = self._discussion_reply_context(
            session, course, clazz, topic["bbs_id"], topic["uuid"]
        )
        endpoint = f"{GROUPWEB_BASE_URL}/pc/invitation/{topic['uuid']}/updateReply"
        try:
            response = session.post(
                endpoint,
                data={
                    "uuid": reply["uuid"],
                    "reply_content": quote(content, safe=""),
                    "reply_files_url": quote(files_url, safe=""),
                    "reply_files_attr": quote(files_attr, safe=""),
                },
                timeout=self.timeout,
                headers={
                    "Referer": context["detail_url"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"discussion reply update failed: {exc}") from exc
        payload = self._discussion_json(response, "discussion reply update")
        refreshed = self.read_discussion_topic(course, clazz, topic["uuid"])
        updated = resolve_discussion_reply(refreshed["replies"], reply["uuid"])
        if updated["content"] != content:
            raise ChaoxingAPIError(
                "server acknowledged the reply update, but refreshed content differs"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "topic": topic,
            "reply": updated,
            "server_message": str(payload.get("msg") or ""),
            "verification": f"updated and re-read discussion reply {reply['uuid']}",
        }

    def delete_discussion_reply(
        self,
        course: dict[str, Any],
        clazz: dict[str, Any],
        topic_query: str,
        reply_query: str,
    ) -> dict[str, Any]:
        before = self.read_discussion_topic(course, clazz, topic_query)
        topic = before["topic"]
        reply = resolve_discussion_reply(before["replies"], reply_query)
        session = self._session()
        context = self._discussion_reply_context(
            session, course, clazz, topic["bbs_id"], topic["uuid"]
        )
        endpoint = f"{GROUPWEB_BASE_URL}/pc/invitation/{topic['uuid']}/deleteReply"
        try:
            response = session.post(
                endpoint,
                params={"uuid": reply["uuid"]},
                timeout=self.timeout,
                headers={
                    "Referer": context["detail_url"],
                    "X-Requested-With": "XMLHttpRequest",
                },
            )
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ChaoxingAPIError(f"discussion reply deletion failed: {exc}") from exc
        payload = self._discussion_json(response, "discussion reply deletion")
        refreshed = self.read_discussion_topic(course, clazz, topic["uuid"])
        try:
            resolve_discussion_reply(refreshed["replies"], reply["uuid"])
        except ChaoxingAPIError as exc:
            if "not found" not in str(exc):
                raise
        else:
            raise ChaoxingAPIError(
                "server acknowledged the deletion, but the reply is still visible"
            )
        return {
            "course_id": course["course_id"],
            "course_name": course["course_name"],
            "clazz_id": clazz["clazz_id"],
            "clazz_name": clazz["clazz_name"],
            "topic": topic,
            "deleted_reply": reply,
            "deleted": True,
            "server_message": str(payload.get("msg") or ""),
            "verification": f"reply {reply['uuid']} is absent from the refreshed topic",
        }
